//================================================================================================
//外部参照関数
//================================================================================================
Bool PnlComIsEnableAllShortCutKey()
{
	return True;
}
//================================================================================================
//クラス  ：PLBC_StaticList : リストクラス
//概要    ：初期設定
//================================================================================================
template < class TYPE > void PLBC_StaticList< TYPE >::init( TYPE* pc_Buffer, ushort us_MaxSize )
{
	if( ( NULL == pc_Buffer ) || ( 0 == us_MaxSize ) ) {
		PnlComPutDebugLog( True, UC_PNL_LOGPATTERN_1, "PLBC_StaticList< TYPE >::init", UC_PNL_ERROR_PARAMETER );
		return;
	}
	pc_MmbBuffer = pc_Buffer;
	us_MmbMaxSize = us_MaxSize;
	us_MmbNowSize = 0;
}
//================================================================================================
//クラス  ：PLBC_StaticList : リストクラス
//概要    ：要素のリセット
//================================================================================================
template < class TYPE > void PLBC_StaticList< TYPE >::resetAllNode()
{
	if( ( NULL == pc_MmbBuffer ) || ( 0 == us_MmbMaxSize ) ) {
		PnlComPutDebugLog( True, UC_PNL_LOGPATTERN_1, "PLBC_StaticList< TYPE >::resetNode", UC_PNL_ERROR_SETLEAK );
		return;
	}
	us_MmbNowSize = 0;
}
//================================================================================================
//クラス  ：PLBC_StaticList : リストクラス
//概要    ：要素の追加（リストの末尾に追加）
//================================================================================================
template < class TYPE > void PLBC_StaticList< TYPE >::addNode( const TYPE c_Node )
{
	if( ( NULL == pc_MmbBuffer ) || ( 0 == us_MmbMaxSize ) ) {
		PnlComPutDebugLog( True, UC_PNL_LOGPATTERN_1, "PLBC_StaticList< TYPE >::addNode", UC_PNL_ERROR_SETLEAK );
		return;
	}
	if( us_MmbMaxSize < ( us_MmbNowSize + 1 ) ) {
		// 要素数の最大値を超えてしまう場合.
		PnlComPutDebugLog( True, UC_PNL_LOGPATTERN_1, "PLBC_StaticList< TYPE >::addNode", UC_PNL_ERROR_USE );
		return;
	}
	pc_MmbBuffer[ us_MmbNowSize ] = c_Node;
	++us_MmbNowSize;
}
//================================================================================================
//クラス  ：PLBC_StaticList : リストクラス
//概要    ：要素の挿入
//================================================================================================
template < class TYPE > void PLBC_StaticList< TYPE >::insertNode( TYPE c_Node, const ushort us_Index )
{
	if( ( NULL == pc_MmbBuffer ) || ( 0 == us_MmbMaxSize ) ) {
		PnlComPutDebugLog( True, UC_PNL_LOGPATTERN_1, "PLBC_StaticList< TYPE >::insertNode", UC_PNL_ERROR_SETLEAK );
		return;
	}
	if( ( 0 == us_Index ) || ( ( us_MmbNowSize + 1 ) < us_Index ) ) {
		// 引数が不正な場合.
		PnlComPutDebugLog( True, UC_PNL_LOGPATTERN_1, "PLBC_StaticList< TYPE >::insertNode", UC_PNL_ERROR_PARAMETER );
		return;
	}
	if( us_MmbMaxSize < ( us_MmbNowSize + 1 ) ) {
		// 要素数の最大値を超えてしまう場合.
		PnlComPutDebugLog( True, UC_PNL_LOGPATTERN_1, "PLBC_StaticList< TYPE >::insertNode", UC_PNL_ERROR_USE );
		return;
	}
	for( ushort i = us_MmbNowSize; us_Index <= i; --i ) {
		pc_MmbBuffer[ i ] = pc_MmbBuffer[ i - 1 ];
	}
	pc_MmbBuffer[ us_Index - 1 ] = c_Node;
	++us_MmbNowSize;
}
//================================================================================================
//クラス  ：PLBC_StaticList : リストクラス
//概要    ：要素の削除
//================================================================================================
template < class TYPE > void PLBC_StaticList< TYPE >::deleteNode( const ushort us_Index )
{
	if( ( NULL == pc_MmbBuffer ) || ( 0 == us_MmbMaxSize ) ) {
		PnlComPutDebugLog( True, UC_PNL_LOGPATTERN_1, "PLBC_StaticList< TYPE >::deleteNode", UC_PNL_ERROR_SETLEAK );
		return;
	}
	if( ( 0 == us_Index ) || ( us_MmbNowSize < us_Index ) ) {
		// 引数が不正な場合.
		PnlComPutDebugLog( True, UC_PNL_LOGPATTERN_1, "PLBC_StaticList< TYPE >::deleteNode", UC_PNL_ERROR_PARAMETER );
		return;
	}
	for( ushort i = us_Index; us_MmbNowSize > i; ++i ) {
		pc_MmbBuffer[ i - 1 ] = pc_MmbBuffer[ i ];
	}
	--us_MmbNowSize;
}
//================================================================================================
//クラス  ：PLBC_StaticList : リストクラス
//概要    ：要素の取得
//================================================================================================
template < class TYPE > void PLBC_StaticList< TYPE >::getNode( TYPE& c_Node, const ushort us_Index )
{
	if( ( NULL == pc_MmbBuffer ) || ( 0 == us_MmbMaxSize ) ) {
		PnlComPutDebugLog( True, UC_PNL_LOGPATTERN_1, "PLBC_StaticList< TYPE >::getNode", UC_PNL_ERROR_SETLEAK );
		return;
	}
	if( ( 0 == us_Index ) || ( us_MmbNowSize < us_Index ) ) {
		// 引数が不正な場合.
		PnlComPutDebugLog( True, UC_PNL_LOGPATTERN_1, "PLBC_StaticList< TYPE >::getNode", UC_PNL_ERROR_PARAMETER );
		return;
	}
	c_Node = pc_MmbBuffer[ us_Index - 1 ];
}
//================================================================================================
//クラス  ：PLBC_StaticList : リストクラス
//概要    ：現在の要素数の取得
//================================================================================================
template < class TYPE > ushort PLBC_StaticList< TYPE >::getNodeSize()
{
	if( ( NULL == pc_MmbBuffer ) || ( 0 == us_MmbMaxSize ) ) {
		PnlComPutDebugLog( True, UC_PNL_LOGPATTERN_1, "PLBC_StaticList< TYPE >::getNodeSize", UC_PNL_ERROR_SETLEAK );
		return 0;
	}
	// 現在の要素数を返す.
	return us_MmbNowSize;
}

//================================================================================================
//クラス  ：PLBC_StaticList : リストクラス
//概要    ：要素の更新.
//================================================================================================
template < class TYPE >
void PLBC_StaticList< TYPE >::updateNode( const TYPE c_Node, const ushort us_Index )
{
	if( us_Index <= getNodeSize() ) {
		// 指定インデックスが範囲内だった場合は更新する.
		pc_MmbBuffer[ us_Index - 1 ] = c_Node;
	}
}

//================================================================================================
//クラス  ：TYPC_RegAddress : 登録宛先管理クラス.
//概要    ：宛先登録時の元となる宛先を提供する.
//================================================================================================

Bool						TYPC_RegAddress::bl_NewAddressUse = False;
TYPS_AddressInfo			TYPC_RegAddress::s_NewAddressInfo;
TYPC_DirectMailAddress		TYPC_RegAddress::c_NewMailAddress;
TYPC_DirectFtpAddress 		TYPC_RegAddress::c_NewFtpAddress;
TYPC_DirectSmbAddress		TYPC_RegAddress::c_NewSmbAddress;
TYPC_DirectBoxAddress		TYPC_RegAddress::c_NewBoxAddress;
TYPC_DirectFaxAddress		TYPC_RegAddress::c_NewFaxAddress;
TYPC_DirectWebDavAddress	TYPC_RegAddress::c_NewWebDavAddress;

// ===============================================================================================.
// 概要    ：登録宛先情報の取得.
// ===============================================================================================.
Bool TYPC_RegAddress::getRegAddressInfo( TYPS_AddressInfo& s_RegAddressInfo, const short ss_RegIndex )
{
	if( True == bl_NewAddressUse ) {
		// 新規入力宛先を取得.
		memcpy( &s_RegAddressInfo, &s_NewAddressInfo, sizeof( TYPS_AddressInfo ) );
		return True;
	} else {
		// 直接入力宛先を取得.
		TYPC_BroadcastAddress*	pc_BroadcastAddress	= PnlComGetBroadcastAddressForSend();
		if( NULL == pc_BroadcastAddress ) { LOGF_debug_PutEventLog( LOGF_DEBUG_EVENT_KIND_ALL, 0, LOGD_DEBUG_LEVEL_UNKNOWN, "Assert Failed!" ); return False; }
		return ( pc_BroadcastAddress->getDirectAddressInfo( s_RegAddressInfo, ss_RegIndex ) );
	}
}
// ===============================================================================================.
// 概要    ：E-Mail／IFax／IPFaxの登録宛先取得.
// ===============================================================================================.
TYPC_DirectMailAddress* TYPC_RegAddress::getRegMailAddress( const short ss_RegAddressNo )
{
	if( True == bl_NewAddressUse ) {
		// 新規入力宛先を取得.
		return ( &c_NewMailAddress );
	} else {
		// 直接入力宛先を取得.
		APIC_Job* pc_ScanFaxJob = PnlComGetJobScanFax();
		if( NULL == pc_ScanFaxJob ) { LOGF_debug_PutEventLog( LOGF_DEBUG_EVENT_KIND_ALL, 0, LOGD_DEBUG_LEVEL_UNKNOWN, "Assert Failed!" ); return ( &c_NewMailAddress ); }
		TYPC_DirectAddressBook* pc_DirectAddressBook = &( pc_ScanFaxJob->getJobSpec()->pc_Send->c_ComSend.c_DirectAddressBook );
		if( NULL == pc_DirectAddressBook ) { LOGF_debug_PutEventLog( LOGF_DEBUG_EVENT_KIND_ALL, 0, LOGD_DEBUG_LEVEL_UNKNOWN, "Assert Failed!" ); return ( &c_NewMailAddress ); }
		return ( pc_DirectAddressBook->pageMailAddress( ss_RegAddressNo ) );
	}
}
