// ===============================================================================================.
//	概要     : 新規入力宛先の初期化登録処理.
// ===============================================================================================.
void TYPC_RegAddress::initNewAddress( TYPE_SendMode e_SetSendMode )
{
	APIC_Job* pc_ScanFaxJob = PnlComGetJobScanFax();
	if( NULL == pc_ScanFaxJob ) { LOGF_debug_PutEventLog( LOGF_DEBUG_EVENT_KIND_ALL, 0, LOGD_DEBUG_LEVEL_UNKNOWN, "Assert Failed!" ); return; }
	TYPC_DirectAddressBook* pc_DirectAddressBook = &( pc_ScanFaxJob->getJobSpec()->pc_Send->c_ComSend.c_DirectAddressBook );
	if( NULL == pc_DirectAddressBook ) { LOGF_debug_PutEventLog( LOGF_DEBUG_EVENT_KIND_ALL, 0, LOGD_DEBUG_LEVEL_UNKNOWN, "Assert Failed!" ); return; }

	// 宛先情報を初期化・登録.
	memset( &s_NewAddressInfo, 0x00, sizeof( s_NewAddressInfo ) );
	s_NewAddressInfo.b_Direct		= True;									// ダイレクトフラグ（True : ダイレクト宛先）.
	s_NewAddressInfo.e_SendMode		= e_SetSendMode;						// 送信種別.

	// 送信種別に応じて宛先を初期化・登録.
	switch( e_SetSendMode ) {
		case TYPE_SendModeFax:												//【ファクス】.
			memset( &c_NewFaxAddress, 0, sizeof( c_NewFaxAddress ) );
			c_NewFaxAddress.setOn( True );									// 登録有効化.
			break;

		case TYPE_SendModeEmail:											//【E-Mail】.
			memset( &c_NewMailAddress, 0, sizeof( c_NewMailAddress ) );
			c_NewMailAddress.setOn( True );									// 登録有効化.
			break;

		case TYPE_SendModeBox:												//【ボックス】.
		{
			memset( &c_NewBoxAddress, 0, sizeof( c_NewBoxAddress ) );
			TYPS_BoxAddress s_ClearBoxAddress;
			memset( &s_ClearBoxAddress, 0, sizeof( s_ClearBoxAddress ) );
			s_ClearBoxAddress.sl_BoxNo = DOCD_BoxIdDefault;				// ボックス番号.
			c_NewBoxAddress.setBoxAddress( s_ClearBoxAddress );
			c_NewBoxAddress.setOn( True );								// 登録有効化.
		}
		break;

		case TYPE_SendModeSmb:												//【ファイル送信(SMB)】.
		{
			memset( &c_NewSmbAddress, 0, sizeof( c_NewSmbAddress ) );
			TYPS_SmbAddress s_ClearSmbAddress;
			memset( &s_ClearSmbAddress, 0, sizeof( s_ClearSmbAddress ) );

			// ----------------------------------------.
			// デフォルトのログイン名／パスワード設定↓.
			// ----------------------------------------.
			int32_t i32_UserNo = 0; // 2013/11/01 【US-20U-PN3G】20万人対応.
			char sc_DomainName[PNLD_NetworkSetSSODomainNameSize + 1];
			memset( sc_DomainName, 0, sizeof( sc_DomainName ) );

			APIC_User* pC_User = PnlComGetUser();
			APIC_SmbSetting* pC_Setting = PnlComGetSMBSetting();
			if( NULL != pC_User && NULL != pC_Setting ) {
				if( True == pC_Setting->isEnableSMBClientSettingForSSO() ) {									// SMB送信用のSSO設定が完了状態.

					// ログインユーザーのユーザー名とドメイン名を取得.
					// getInputUserNameはICカードログインではカードIDをユーザー名と覚えてしまうので
					// getUserNameUTF8を使用する.
					pC_User->getUserNameUTF8( s_ClearSmbAddress.sc_LoginName );							// ログインユーザーの［ユーザー名］取得.
					i32_UserNo = pC_User->getUserNo();														// ログインユーザーの［ユーザー管理番号］取得.
					Bool b_Ret = pC_User->getDomainNameForLoginUser( i32_UserNo, sc_DomainName );			// ログインユーザーの［ドメイン名］取得.

					if( False == b_Ret ) {
						// ログインユーザーのドメイン名が取得できなかった場合はSMBデフォルトドメインを取得.
						APIC_UserAuthenticationSetting* pC_AuthSetting = PnlComGetUserAuthenticationSetting();
						if( NULL != pC_AuthSetting ) {
							TYPE_UserAuthentication e_UserAuthentication = PnlComGetUserAuthentication()->getUserAuthentication(PNLC_NetworkLan::getInstance()->getLine());
							if( ( TYPE_UserAuthenticationServer == e_UserAuthentication ) ||
							    ( TYPE_UserAuthenticationDeviceAndServer == e_UserAuthentication ) ) {
								// 認証方式が外部認証サーバー 又は 本体＋外部サーバー認証の時.
								APIC_AuthenticationSeverSetting* apicAuth = APIC_AuthenticationSeverSetting::newInstance();
								if( NULL == apicAuth ) { LOGF_debug_PutEventLog( LOGF_DEBUG_EVENT_KIND_ALL, 0, LOGD_DEBUG_LEVEL_UNKNOWN, "Assert Failed!" ); return; }
								char sc_ServerName[ APID_MaxLengthOfServerName + 1 ];
								pC_User->getServerName( sc_ServerName );									// 認証外部サーバー名取得.
								char sc_SrvIndex = APID_AuthenticationServerIndexNone;
								APIS_AuthenticationServerInfo	ps_AuthenticationServerInfo = {};			// サーバー情報.
								APIS_AuthServerGroupInfo		ps_AuthServerGroupInfo = {};				// サーバーグループ情報.
								if( False == apicAuth->checkServerGroup() ) {
									// サーバー名よりサーバーIndexを取得.
									sc_SrvIndex = apicAuth->getServerIndexFromName( sc_ServerName );
									// サーバーIndexよりサーバー情報を取得.
									apicAuth->getServerInfo( apicAuth->getServerIndexFromName( sc_ServerName ), &ps_AuthenticationServerInfo, PNLC_NetworkLan::getInstance()->getLine() );
								} else {
									// サーバー名よりサーバーグループIndexを取得.
									sc_SrvIndex = static_cast<APID_AuthenticationServerIndex>( apicAuth->getServerGroupIndexFromName( sc_ServerName , PNLC_NetworkLan::getInstance()->getLine() ) );
									// サーバー名より取得したサーバーグループIndexからサーバーグループ情報を取得.
									apicAuth->getAuthServerGroupInfo( static_cast<APID_AuthServerGroupIndex>( sc_SrvIndex ), &ps_AuthServerGroupInfo , PNLC_NetworkLan::getInstance()->getLine() );
									// サーバーグループ情報のサーバー登録１のサーバー情報を取得.
									apicAuth->getServerInfo( ps_AuthServerGroupInfo.sc_ServerIndex[0], &ps_AuthenticationServerInfo, PNLC_NetworkLan::getInstance()->getLine() );
								}
//Comment 2017/09/29 [HCL-Surya M] [IT5 4.2][RQ-686]Multiple Network support.
								TYPE_NetworkSpecific e_NetworkSpecific = PNLC_NetworkLan::getInstance()->getLine();
								switch( ps_AuthenticationServerInfo.e_ServerType ) {
									case TYPE_AuthenticationServerTypeSMB:
									case TYPE_AuthenticationServerTypeNTLMv2:
										// SMB 又は NTLMv2の時.
//Comment 2017/09/29 [HCL-Surya M] [IT5 4.2][RQ-686]Multiple Network support.
										//pC_AuthSetting->getSmbDefaultDomainName( sc_DomainName );				// SMBデフォルトドメインを取得.
										pC_AuthSetting->getSmbDefaultDomainName( sc_DomainName, e_NetworkSpecific );				// SMBデフォルトドメインを取得.
										break;
									default:
										break;
								}
							}
						}
					}
					// comment 2015/08/27 OPS1-川手 [特ROM対応][CQ517645] SMB、Kerveros認証の強化対応(PKIの場合以外、ドメインを付与しない).
					if( True == PLBC_FuncPKICheck::isPKI() ){ 		// PKI認証の場合のみ.
						if( sc_DomainName[0] != '\0' ){
							// ドメイン名がある場合は、［ユーザー名］＋［＠］＋［ドメイン名］をデフォルトログイン名とする.
							int32_t i32_loginNamelen = 0;
							i32_loginNamelen = PLBC_UTF8Library::getCharCount( (char *)s_ClearSmbAddress.sc_LoginName );
							if( ( i32_loginNamelen + strlen( sc_DomainName ) + 1 ) <= PCGD_SMB_InputStrName_MAX ){
								// ユーザー名領域に収まる場合、ドメイン名を加える.
								strncat(s_ClearSmbAddress.sc_LoginName, "@", 1);
								strncat(s_ClearSmbAddress.sc_LoginName, sc_DomainName, sizeof(sc_DomainName));
								onlyPanel.bl_deleteDomainName = False;											// 文字数オーバー警告フラグ設定.
							}else{
								// ユーザー名領域に収まらない場合、ドメイン名は加えない.
								onlyPanel.bl_deleteDomainName = True;											// 文字数オーバー警告フラグ設定.
							}
						}
					}

					// ログインユーザーのパスワードをデフォルトパスワードとする.
					pC_User->getInputUserPassword( s_ClearSmbAddress.sc_Password );
				}
			}
			// ----------------------------------------.
			// デフォルトのログイン名／パスワード設定↑.
			// ----------------------------------------.

			c_NewSmbAddress.setSmbAddress( s_ClearSmbAddress );
			c_NewSmbAddress.setOn( True );																	// 登録有効化.
		}
		break;

		case TYPE_SendModeFtp:												//【ファイル送信(FTP)】.
		{
			memset( &c_NewFtpAddress, 0, sizeof( c_NewFtpAddress ) );
			TYPS_FtpAddress s_ClearFtpAddress;
			memset( &s_ClearFtpAddress, 0, sizeof( s_ClearFtpAddress ) );
			s_ClearFtpAddress.us_PortNo = PCGD_PortNumDefault;			// ポート番号.
			c_NewFtpAddress.setFtpAddress( s_ClearFtpAddress );
			c_NewFtpAddress.setOn( True );								// 登録有効化.
		}
		break;

		case TYPE_SendModeIfax:												//【インターネットファクス】.
			memset( &c_NewMailAddress, 0, sizeof( c_NewMailAddress ) );
			c_NewMailAddress.setOn( True );									// 登録有効化.
			c_NewMailAddress.setIfaxSendInfo( c_JobControl.getDefaultIfaxPartnerReceptAbility() );	//相手機受信能力デフォルト値設定.
			break;

		case TYPE_SendModeIPAddressFax:										//【IPアドレスファクス.】
			memset( &c_NewMailAddress, 0, sizeof( c_NewMailAddress ) );
			c_NewMailAddress.setOn( True );									// 登録有効化.
			break;

		case TYPE_SendModeWebDav:											//【ファイル送信(WebDAV).】
		{
			memset( &c_NewWebDavAddress, 0, sizeof( c_NewWebDavAddress ) );
			TYPS_WebDavAddress s_ClearWebDavAddress;
			memset( &s_ClearWebDavAddress, 0, sizeof( s_ClearWebDavAddress ) );
			s_ClearWebDavAddress.us_PortNo = PCGD_WebDAVPortNumDefault;	// ポート番号.
			c_NewWebDavAddress.setWebDavAddressUTF8( s_ClearWebDavAddress );
			c_NewWebDavAddress.setOn( True );							// 登録有効化.
		}
		break;

		default:
			break;
	}
}

//================================================================================================
//クラス  ：TYPC_BroadcastAddress : 同報宛先管理クラス
//概要    ：短縮宛先の設定・解除
//================================================================================================
void TYPC_BroadcastAddress::setShorteningAddress( const short ss_AddressNo, const Bool b_On )
{
	// 同報宛先件数を取得.
	const ushort us_AddressCount = s_MmbBroadcastList.getNodeSize();
	ushort i;					// Qt4対応:VC固有スコープ処理を回避
	for( i = 1; us_AddressCount >= i; ++i )
	{
		// 選択されている宛先を順次取得.
		TYPS_AddressInfo s_AddressInfo;
		memset( &s_AddressInfo, 0x00, sizeof( s_AddressInfo ) );
		s_MmbBroadcastList.getNode( s_AddressInfo, i );
		// 指定した宛先と同一のものがある場合.
		if( ( ss_AddressNo == s_AddressInfo.ss_AddressNo ) && ( False == s_AddressInfo.b_Direct ) ) {
			break;
		}
	}
	// 解除指定で指定した宛先が選択されている場合.
	if( ( False == b_On ) && ( us_AddressCount >= i ) ) {
		// 最終選択同報宛先の削除.
		TYPS_AddressInfo s_AddressInfo;
		memset( &s_AddressInfo, 0x00, sizeof( s_AddressInfo ) );
		s_MmbBroadcastList.getNode( s_AddressInfo, i );
		// 宛先登録情報を操作ログとして残す(宛先解除).
		PNLC_OperationLog::newInstance()->setLogAddressInfo( &s_AddressInfo, OPLE_SubInfoAdrRelease );
		delLastSelectAddress( &s_AddressInfo );
		PNLC_BroadcastPadControlLib::newInstance()->deleteBroadcastList( (ushort)( i - 1 ) );
		// 指定した宛先を同報宛先リストから削除.
		s_MmbBroadcastList.deleteNode( i );
		bl_MmbAddressCount = False;	// カウンター更新フラグ.
		if( us_MmbSelectAddress == i ) {
			us_MmbSelectAddress = TYPD_NotSelectBroadcastAddress;
		}
		if(	( TYPD_BroadcastAddressEffectiveStart != us_MmbEffectivePosition )
		    && ( us_MmbEffectivePosition > s_MmbBroadcastList.getNodeSize() ) ) {
			us_MmbEffectivePosition = (ushort)( us_MmbEffectivePosition - us_MmbEffectiveRange );
		}
	} else if( ( True == b_On ) && ( us_AddressCount < i ) ) {
		// 選択指定で指定した宛先が選択されていない場合.
		// 指定した宛先を同報宛先リストに追加.
		TYPS_AddressInfo s_AddressInfo;
		memset( &s_AddressInfo, 0x00, sizeof( s_AddressInfo ) );
		s_AddressInfo.ss_AddressNo = ss_AddressNo;
		s_AddressInfo.b_Direct = False;
		s_AddressInfo.b_Select = False;
		APIC_ShorteningAddress* pc_ShorteningAddress = APIC_ShorteningAddress::newInstance( ss_AddressNo );
		if( NULL != pc_ShorteningAddress ) {
			s_AddressInfo.e_SendMode = pc_ShorteningAddress->getSendMode();
		}
		bl_MmbAddressCount = False;	// カウンター更新フラグ.
		s_MmbBroadcastList.addNode( s_AddressInfo );
		PNLC_BroadcastPadControlLib::newInstance()->addBroadcastList( s_AddressInfo );
		// 最終選択同報宛先の設定.
		setLastSelectAddress( &s_AddressInfo );
		// 宛先登録情報を操作ログとして残す(宛先選択).
		PNLC_OperationLog::newInstance()->setLogAddressInfo( &s_AddressInfo, OPLE_SubInfoAdrSelect );
	}
}
//================================================================================================
//クラス  ：TYPC_BroadcastAddress : 同報宛先管理クラス
//================================================================================================
void TYPC_BroadcastAddress::setDirectAddress( const short ss_AddressNo, const TYPE_SendMode e_SendMode, const Bool b_On )
{
	setDirectAddress( ss_AddressNo, e_SendMode, b_On, -1 );
}
//================================================================================================
//クラス  ：TYPC_BroadcastAddress : 同報宛先管理クラス
//================================================================================================
void TYPC_BroadcastAddress::setDirectAddress( const short ss_AddressNo, const TYPE_SendMode e_SendMode, const Bool b_On, const short ss_DigitalID )
{
	// 同報宛先件数を取得.
	const ushort us_AddressCount = s_MmbBroadcastList.getNodeSize();
	ushort i;					// Qt4対応:VC固有スコープ処理を回避
	for( i = 1; us_AddressCount >= i; ++i )
	{
		// 選択されている宛先を順次取得.
		TYPS_AddressInfo s_AddressInfo;
		s_MmbBroadcastList.getNode( s_AddressInfo, i );
		// 指定した宛先と同一のものがある場合.
		if(	( ss_AddressNo == s_AddressInfo.ss_AddressNo )
		    && ( e_SendMode == s_AddressInfo.e_SendMode )
		    && ( True == s_AddressInfo.b_Direct ) ) {
			break;
		}
	}
	// 解除指定で指定した宛先が選択されている場合.
	if( ( False == b_On ) && ( us_AddressCount >= i ) ) {
		// 証明書付宛先検索時は登録した証明書を削除する.
		if( True == onlyPanel.isSearchDigitalID() || onlyPanel.isEquivalentAddressOn() == True ) {
			TYPS_AddressInfo s_AddressInfo;
			memset( &s_AddressInfo, 0x00, sizeof( s_AddressInfo ) );
			s_MmbBroadcastList.getNode( s_AddressInfo, i );
			APIC_SmimeCertInfo* pc_SmimeCertInfo = APIC_SmimeCertInfo::newInstance();	// インスタンス取得.
			pc_SmimeCertInfo->DeleteSmimeCertInfo( s_AddressInfo.ss_DigitalID );
		}
		// 最終選択同報宛先の削除.
		TYPS_AddressInfo s_AddressInfo;
		s_MmbBroadcastList.getNode( s_AddressInfo, i );
		// 宛先登録情報を操作ログとして残す(宛先解除).
		PNLC_OperationLog::newInstance()->setLogAddressInfo( &s_AddressInfo, OPLE_SubInfoAdrRelease );
		delLastSelectAddress( &s_AddressInfo );
		PNLC_BroadcastPadControlLib::newInstance()->deleteBroadcastList( (ushort)( i - 1 ) );
		// 指定した宛先を同報宛先リストから削除.
		s_MmbBroadcastList.deleteNode( i );
		bl_MmbAddressCount = False;	// カウンター更新フラグ.
		if( us_MmbSelectAddress == i ) {
			us_MmbSelectAddress = TYPD_NotSelectBroadcastAddress;
		}
		if(	( TYPD_BroadcastAddressEffectiveStart != us_MmbEffectivePosition )
		    && ( us_MmbEffectivePosition > s_MmbBroadcastList.getNodeSize() ) ) {
			us_MmbEffectivePosition = (ushort)( us_MmbEffectivePosition - us_MmbEffectiveRange );
		}
		if( True == APIC_SoftDipSw::newInstance()->getSoftDipSwBitForPanelSpecNo( DEFSOFTWARESW214, 0 ) ) {	// LDAP検索実施時、認証ユーザーのE-mailアドレスをFROMアドレスに設定する機能の有効設定.
			if( 0 == s_MmbBroadcastList.getNodeSize() ) {		// 宛先選択総数が0.
				PnlComSetFromAddressAtNotSelectAddress( PnlComGetJobScanFax() );
			}
		}
	} else if( ( True == b_On ) && ( us_AddressCount < i ) ) {
		// 選択指定で指定した宛先が選択されていない場合.
		// 指定した宛先を同報宛先リストに追加.
		TYPS_AddressInfo s_AddressInfo;
		memset( &s_AddressInfo, 0x00, sizeof( s_AddressInfo ) );
		s_AddressInfo.ss_AddressNo = ss_AddressNo;
		s_AddressInfo.b_Direct = True;
		s_AddressInfo.e_SendMode = e_SendMode;
		if( ( True == onlyPanel.isSearchDigitalID() || onlyPanel.isEquivalentAddressOn() == True ) && ss_DigitalID >= 0 ) {	// 証明書付宛先検索時
			s_AddressInfo.ss_DigitalID = ss_DigitalID;		// デジタルIDセット.
		}
		s_AddressInfo.b_Select = False;
		bl_MmbAddressCount = False;	// カウンター更新フラグ.
		s_MmbBroadcastList.addNode( s_AddressInfo );
		PNLC_BroadcastPadControlLib::newInstance()->addBroadcastList( s_AddressInfo );
		// 最終選択同報宛先の設定.
		setLastSelectAddress( &s_AddressInfo );
		// 宛先登録情報を操作ログとして残す(宛先選択).
		// 「Ｇ３ＦＡＸ送信ダイレクト」の場合はこのタイミングでは行わない.
		PBasicMessageProc* pc_Gamen = PNLC_PopupListControl::newInstance()->getNowPopupNonPullDown();
		if( NULL == pc_Gamen ) {
			pc_Gamen = PBasicMessageProc::getNowGamen();	// ポップアップでない場合、ベース画面のインスタンスを取得.
		}
		if( ( TYPE_SendModeFax 		!= s_AddressInfo.e_SendMode ) ) {
			PNLC_OperationLog::newInstance()->setLogAddressInfo( &s_AddressInfo, OPLE_SubInfoAdrSelect );
		} else if( ( &gp_ScanFaxHistoryAddress == pc_Gamen			||
		             &gp_RedialSelectOffHook_scanfax == pc_Gamen	||
		             &gp_FromTxLog_box == pc_Gamen	||
		             &gp_PD_10H00480 == pc_Gamen			||
		             &gp_EnlScanFax_RedialSelectOffHook == pc_Gamen	||
		             &gp_PD_10H00550 == pc_Gamen ) ) {
			PNLC_OperationLog::newInstance()->setLogAddressInfo( &s_AddressInfo, OPLE_SubInfoAdrSelect );
		}

	}
}
// comment 2015/09/14 OPS1-Sky後藤 [MinervaSBK][CQ518343] UD評価指摘対応.
//関数--------------------------------------------------------------------------.
//概要    ：ダイレクト宛先更新.
//備考    ：.
//戻値    ：.
//作成者  ：OPS1 後藤.
//変更履歴：2015/09/14 新規作成.
//------------------------------------------------------------------------------.
void TYPC_BroadcastAddress::updateDirectAddress( TYPS_AddressInfo s_AddressInfo, ushort us_Index )
{
	ushort us_SearchIndex = 0;
	ushort us_SelectIndex = 0;
	
	const ushort us_AddressCount = s_MmbBroadcastList.getNodeSize();
	for ( ushort i = 1; us_AddressCount >= i; ++i ) {
		// 選択されている宛先を順次取得.
		TYPS_AddressInfo s_AddressInfoSearch;
		s_MmbBroadcastList.getNode( s_AddressInfoSearch, i );
		
		if( True == s_AddressInfoSearch.b_Direct ) {
			us_SearchIndex++;
		}
		
		if( us_Index == us_SearchIndex ) {
			us_SelectIndex = i;
			break;
		}
	}
	
	if( 0 < us_SelectIndex ) {
		s_MmbBroadcastList.updateNode( s_AddressInfo, us_SelectIndex );
	}
}

//================================================================================================
//クラス  ：TYPC_BroadcastAddress : 同報宛先管理クラス
//概要    ：同報宛先のリセット（同報宛先をクリアする）
//================================================================================================
void TYPC_BroadcastAddress::resetAllBroadcastAddress()
{
	PNLC_BroadcastPadControlLib::newInstance()->endBroadcastPad();
	// 同報宛先リストを空にする.
	s_MmbBroadcastList.resetAllNode();
	bl_MmbAddressCount = False;	// カウンター更新フラグ.

	// ダイレクト宛先E-Mail証明書情報格納用テーブル初期化.
	memset( s_smimeCertTable, '\0', sizeof( PLBS_SmimeCertTable ) );
	// 操作対象となるアドレス、選択中のアドレスを初期化.
	us_MmbEffectivePosition = TYPD_BroadcastAddressEffectiveStart;
	us_MmbSelectAddress = TYPD_NotSelectBroadcastAddress;

// comment Sky森本（弘） 2018/06/25 [Eagle][市場問題(FQ-OPSD-1700387-OFP195)] 短縮宛先が選択されているにも関わらず送信操作ログに全宛先解除が記録される．
	// 宛先登録情報を操作ログとして残す(全宛先解除).
//	PNLC_OperationLog::newInstance()->setLogAddressInfo( NULL, OPLE_SubInfoAdrClearAll );
// comment 2018/12/6 Sky雜賀 【Eagle】【1032676】.
//	if ( PnlComGetBroadcastAddressForSend( cp_scanfaxJob ) == this) {
	if ( ( PnlComGetBroadcastAddressForSend( cp_scanfaxJob ) == this) && ( NULL != cp_scanfaxJob ) ) {
		PNLC_OperationLog::newInstance()->setLogAddressInfo( NULL, OPLE_SubInfoAdrClearAll, NULL, NULL, OPLE_EvtStatAdrInfoClearScan );
// comment 2018/12/6 Sky雜賀 【Eagle】【1032676】.
//	} else if ( PnlComGetBroadcastAddressForSend( cp_jbscanfaxJob ) == this) {
	} else if ( ( PnlComGetBroadcastAddressForSend( cp_jbscanfaxJob ) == this) && ( NULL != cp_jbscanfaxJob ) ) {
		PNLC_OperationLog::newInstance()->setLogAddressInfo( NULL, OPLE_SubInfoAdrClearAll, NULL, NULL, OPLE_EvtStatAdrInfoClearBox );
// comment 2018/12/6 Sky雜賀 【Eagle】【1032676】.
//	} else if ( PnlComGetBroadcastAddressForSend( cp_faxJob ) == this) {
	} else if ( ( PnlComGetBroadcastAddressForSend( cp_faxJob ) == this) && ( NULL != cp_faxJob ) ) {
		PNLC_OperationLog::newInstance()->setLogAddressInfo( NULL, OPLE_SubInfoAdrClearAll, NULL, NULL, OPLE_EvtStatAdrInfoClearFax );
	}

	// 最終選択同報宛先のリセット.
	resetLastSelectAddress();
}
//================================================================================================
//クラス  ：TYPC_BroadcastAddress : 同報宛先管理クラス
//概要    ：デジタルID宛先のリセット（デジタルID宛先をクリアする）
//================================================================================================
void TYPC_BroadcastAddress::resetAllDigitalIDAddress()
{
	APIC_HddInfo* pc_HddInfo = APIC_HddInfo::newInstance();
	if( ( NULL != pc_HddInfo ) && ( True == pc_HddInfo->getHddExist() ) ) {	// ＨＤＤが有る時.
		// 同報宛先件数を取得.
		const ushort us_AddressCount = s_MmbBroadcastList.getNodeSize();
		APIC_SmimeCertInfo* pc_SmimeCertInfo = APIC_SmimeCertInfo::newInstance();	// インスタンス取得.
		TYPS_AddressInfo s_AddressInfo;
		memset( &s_AddressInfo, 0x00, sizeof( s_AddressInfo ) );
		// 登録されているデジタルIDより、関連する証明書を削除する
		for( ushort i = 1; us_AddressCount >= i; ++i ) {
			// 選択されている宛先を順次取得.
			s_MmbBroadcastList.getNode( s_AddressInfo, i );
			if( 0 < s_AddressInfo.ss_DigitalID ) {	// デジタルIDが登録されていない場合は削除しない .
				// HDDより証明書削除.
				pc_SmimeCertInfo->DeleteSmimeCertInfo( s_AddressInfo.ss_DigitalID );
			}
		}
	}
	resetAllBroadcastAddress();
}
//================================================================================================
//クラス  ：TYPC_BroadcastAddress : 同報宛先管理クラス
//概要    ：同報宛先のリセット（同報宛先をクリアしない）
//================================================================================================
void TYPC_BroadcastAddress::resetBroadcastAddress()
{
	// 操作対象となるアドレス、選択中のアドレスを初期化.
	us_MmbEffectivePosition = TYPD_BroadcastAddressEffectiveStart;
	us_MmbSelectAddress = TYPD_NotSelectBroadcastAddress;
	const ushort us_AddressCount = s_MmbBroadcastList.getNodeSize();
	for( ushort i = 1; us_AddressCount >= i; ++i ) {
		// 選択されている宛先を順次取得.
		TYPS_AddressInfo s_AddressInfo;
		s_MmbBroadcastList.getNode( s_AddressInfo, i );
		s_AddressInfo.b_Select = False;
		s_MmbBroadcastList.updateNode( s_AddressInfo, i );
	}
	bl_MmbAddressCount = False;	// カウンター更新フラグ.
}
//================================================================================================
//クラス  ：TYPC_BroadcastAddress : 同報宛先管理クラス
//概要    ：指定した宛先情報の取得
//================================================================================================
void TYPC_BroadcastAddress::getBroadcastAddressInfo( TYPS_AddressInfo& s_AddressInfo, const ushort us_EffectiveIndex )
{
	if( ( 0 == us_EffectiveIndex ) || ( us_MmbEffectiveRange < us_EffectiveIndex ) ) {
		// 引数が不正な場合.
		PnlComPutDebugLog( True, UC_PNL_LOGPATTERN_1, "TYPC_BroadcastAddress::getBroadcastAddressInfo", UC_PNL_ERROR_PARAMETER );
		return;
	}
	// 指定されたアドレスを算出.
	const ushort us_Index = ( ushort )( us_MmbEffectivePosition + ( us_EffectiveIndex - 1 ) );
	if( us_Index > s_MmbBroadcastList.getNodeSize() ) {
		PnlComPutDebugLog( True, UC_PNL_LOGPATTERN_1, "TYPC_BroadcastAddress::getBroadcastAddressInfo", UC_PNL_ERROR_IMPOSSIBLE );
		return;
	}
	// 指定した宛先情報を取得する.
	s_MmbBroadcastList.getNode( s_AddressInfo, us_Index );
}
//================================================================================================
//クラス  ：TYPC_BroadcastAddress : 同報宛先管理クラス
//概要    ：宛先情報の取得
//================================================================================================
void TYPC_BroadcastAddress::getUniqueBroadcastAddressInfo( TYPS_AddressInfo& s_AddressInfo, const ushort us_EffectiveIndex )
{
	if( ( 0 == us_EffectiveIndex ) || ( s_MmbBroadcastList.getNodeSize() < us_EffectiveIndex ) ) {
		// 引数が不正な場合.
		PnlComPutDebugLog( True, UC_PNL_LOGPATTERN_1, "TYPC_BroadcastAddress::getUniqueBroadcastAddressInfo", UC_PNL_ERROR_PARAMETER );
		return;
	}
	// 指定した宛先情報を取得する.
	s_MmbBroadcastList.getNode( s_AddressInfo, us_EffectiveIndex );
}

//================================================================================================
//クラス  :  TYPC_BroadcastAddress : 同報宛先管理クラス .
//概要    :  宛先情報のindexを取得 .
// 引数   :  TYPS_AddressInfo 宛先情報  .
// 戻り値  : ushort             インデックス 1始まり 0の場合は存在しない.
//================================================================================================
ushort TYPC_BroadcastAddress::getBroadcastAddressIndex( const TYPS_AddressInfo& st_AddressInfo )
{
	ushort us_result = 0;
	for( ushort us_count = 1 ; s_MmbBroadcastList.getNodeSize() >= us_count ; us_count++ ) {
		TYPS_AddressInfo st_checkAddressInfo;
		memset( &st_checkAddressInfo, 0x00, sizeof( st_checkAddressInfo ) );
		getUniqueBroadcastAddressInfo( st_checkAddressInfo , us_count );
		// 宛先情報を比較する(選択状態は宛先情報ではないので除外).
		if( st_AddressInfo.ss_AddressNo == st_checkAddressInfo.ss_AddressNo
		    && st_AddressInfo.b_Direct == st_checkAddressInfo.b_Direct
		    && st_AddressInfo.e_SendMode == st_checkAddressInfo.e_SendMode
		    && st_AddressInfo.ul_LeftRecodeId == st_checkAddressInfo.ul_LeftRecodeId
		    && st_AddressInfo.ss_DigitalID == st_checkAddressInfo.ss_DigitalID ) {
			us_result = us_count;
			break;
		}
	}
	return us_result;
}

//================================================================================================
//クラス  ：TYPC_BroadcastAddress : 同報宛先管理クラス
//概要    ：選択されている宛先情報の取得
//================================================================================================
Bool TYPC_BroadcastAddress::getSelectedBroadcastAddressInfo( TYPS_AddressInfo& s_AddressInfo )
{
	// 非選択状態の場合.
	if( TYPD_NotSelectBroadcastAddress == us_MmbSelectAddress ) {
		return False;
	}
	if( us_MmbSelectAddress > s_MmbBroadcastList.getNodeSize() ) {
		PnlComPutDebugLog( True, UC_PNL_LOGPATTERN_1, "TYPC_BroadcastAddress::getSelectedBroadcastAddressInfo", UC_PNL_ERROR_IMPOSSIBLE );
		return False;
	}
	// 指定した宛先情報を取得する.
	s_MmbBroadcastList.getNode( s_AddressInfo, us_MmbSelectAddress );
	return True;
}
//================================================================================================
//クラス  ：TYPC_BroadcastAddress : 同報宛先管理クラス
//概要    ：同報宛先件数の取得
//================================================================================================
ushort TYPC_BroadcastAddress::getBroadcastAddressCount()
{
	// 現在の同報宛先件数を返す.
	return s_MmbBroadcastList.getNodeSize();
}
//================================================================================================
//クラス  ：TYPC_BroadcastAddress : 同報宛先管理クラス
//概要    ：捜査対象となる宛先の開始インデックスの取得
//================================================================================================
ushort TYPC_BroadcastAddress::getEffectivePosition()
{
	// 捜査対象となる宛先の開始インデックスを返す.
	return us_MmbEffectivePosition;
}
//================================================================================================
//クラス  ：TYPC_BroadcastAddress : 同報宛先管理クラス
//概要    ：操作対象となる宛先の変更（前へ）
//================================================================================================
Bool TYPC_BroadcastAddress::moveBeforeEffectivePosition()
{
	Bool	b_Ret = False;
	if( us_MmbEffectiveRange < us_MmbEffectivePosition ) {
		us_MmbEffectivePosition = (ushort)( us_MmbEffectivePosition - us_MmbEffectiveRange );
		b_Ret = True;
	}
	return b_Ret;
}
//================================================================================================
//クラス  ：TYPC_BroadcastAddress : 同報宛先管理クラス
//概要    ：操作対象となる宛先の変更（次へ）
//================================================================================================
Bool TYPC_BroadcastAddress::moveNextEffectivePosition()
{
	Bool	b_Ret = False;
	// 現在の同報宛先件数を取得.
	const ushort us_MaxAddressCount = s_MmbBroadcastList.getNodeSize();
	if( us_MaxAddressCount >= ( us_MmbEffectivePosition + us_MmbEffectiveRange ) ) {
		us_MmbEffectivePosition = (ushort)( us_MmbEffectivePosition + us_MmbEffectiveRange );
		b_Ret = True;
	}
	return b_Ret;
}
//================================================================================================
//クラス  ：TYPC_BroadcastAddress : 同報宛先管理クラス
//概要    ：同報宛先の選択
//================================================================================================
void TYPC_BroadcastAddress::selectBroadcastAddress( const ushort us_EffectiveIndex )
{
	if( ( 0 == us_EffectiveIndex ) || ( us_MmbEffectiveRange < us_EffectiveIndex ) ) {
		// 引数が不正な場合.
		PnlComPutDebugLog( True, UC_PNL_LOGPATTERN_1, "TYPC_BroadcastAddress::selectBroadcastAddress", UC_PNL_ERROR_PARAMETER );
		return;
	}
	// 指定されたアドレスを算出.
	const ushort us_SelectAddress = ( ushort )( us_MmbEffectivePosition + ( us_EffectiveIndex - 1 ) );
	if( us_SelectAddress > s_MmbBroadcastList.getNodeSize() ) {
		PnlComPutDebugLog( True, UC_PNL_LOGPATTERN_1, "TYPC_BroadcastAddress::selectBroadcastAddress", UC_PNL_ERROR_IMPOSSIBLE );
		return;
	}
	// 選択中アドレスの更新.
	us_MmbSelectAddress = ( ( us_SelectAddress == us_MmbSelectAddress ) ? TYPD_NotSelectBroadcastAddress : us_SelectAddress );
}
//================================================================================================
//クラス  ：TYPC_BroadcastAddress : 同報宛先管理クラス
//概要    ：選択宛先のインデックスの取得（操作対象となっていない場合は未選択を返す）
//================================================================================================
ushort TYPC_BroadcastAddress::getSelectedEffectiveIndex()
{
	// 選択されていない場合はそのまま返す.
	if( TYPD_NotSelectBroadcastAddress == us_MmbSelectAddress ) {
		return us_MmbSelectAddress;
	}
	if(	( us_MmbEffectivePosition <= us_MmbSelectAddress )
	    && ( ( us_MmbEffectivePosition + us_MmbEffectiveRange ) > us_MmbSelectAddress ) ) {
		return ( ushort )( ( us_MmbSelectAddress - us_MmbEffectivePosition ) + 1 );
	}
	return TYPD_NotSelectBroadcastAddress;
}
//================================================================================================
//クラス  ：TYPC_BroadcastAddress : 同報宛先管理クラス
//概要    ：ジョブにデジタルIDをセットする.
//================================================================================================
void TYPC_BroadcastAddress::setDigitalIDToJob( APIC_Job* pc_Job )
{
	if( NULL == pc_Job ) { LOGF_debug_PutEventLog( LOGF_DEBUG_EVENT_KIND_ALL, 0, LOGD_DEBUG_LEVEL_UNKNOWN, "Assert Failed!" ); return;}
	TYPC_PdfEncryption* cp_PdfEncryption = &( pc_Job->getJobSpec()->pc_Send->c_PdfEncryption );
	short s_digitalId[TYPD_DIGITAL_ID_FOR_PDF_ENCRYPTION_MAX];
	TYPS_AddressInfo s_AddressInfo;
	memset( &s_AddressInfo, 0x00, sizeof( s_AddressInfo ) );
	if( ( cp_PdfEncryption->getPdfEncryption() == TYPE_PdfEncryptionNon )
	    || ( cp_PdfEncryption->getEncryptionType() != TYPD_PDF_ENCRYPTION_TYPE_DIGITAL_ID ) )	{	// 暗号化の種類がデジタルIDでない.
		return;
	}
	// 同報宛先件数を取得.
	const ushort us_AddressCount = s_MmbBroadcastList.getNodeSize();
	memset( s_digitalId, '\0', sizeof( s_digitalId ) );
	for( ushort i = 1; us_AddressCount >= i; ++i ) {
		// 選択されている宛先を順次取得.
		s_MmbBroadcastList.getNode( s_AddressInfo, i );
		s_digitalId[i-1] = s_AddressInfo.ss_DigitalID;		// デジタルIDの保存.
	}
	if( us_AddressCount != 0 ) {	// 選択宛先がある場合.
		// ジョブにデジタルIDをセットする.
		cp_PdfEncryption->setCertIds( s_digitalId, us_AddressCount );
	}
	// 送信時に使用した証明書をInitJobSettingで削除してしまわない為、 .
	// デジタルID用同報宛先情報をクリアする .
	resetAllBroadcastAddress();
}
//================================================================================================
//クラス  ：TYPC_BroadcastAddress : 同報宛先管理クラス
//概要    ：短縮宛先 宛先種別カウンター取得.
//================================================================================================
ushort TYPC_BroadcastAddress::getShorteningAddressCount( TYPE_SendMode e_SendMode )
{
	createAddressCount();
	return c_MmbShorteningAddressCount.getAddressCount( e_SendMode );
}

//================================================================================================
//クラス  ：TYPC_BroadcastAddress : 同報宛先管理クラス
//概要    ：直接入力 宛先種別カウンター取得.
//================================================================================================
ushort TYPC_BroadcastAddress::getDirectAddressCount( TYPE_SendMode e_SendMode )
{
	createAddressCount();
	return c_MmbDirectAddressCount.getAddressCount( e_SendMode );
}

//================================================================================================
//クラス  ：TYPC_BroadcastAddress : 同報宛先管理クラス
//概要    ：宛先種別カウンター作成.
//================================================================================================
void TYPC_BroadcastAddress::createAddressCount()
{
	TYPS_AddressInfo s_AddressInfo;
	memset( &s_AddressInfo,0x00,sizeof( s_AddressInfo ) );
	if( False == bl_MmbAddressCount ) {

		c_MmbDirectAddressCount.clearAddressCount();		// 直接入力 カウンタークリア.
		c_MmbShorteningAddressCount.clearAddressCount();	// 短縮宛先 カウンタークリア.

		const ushort us_AddressCount = s_MmbBroadcastList.getNodeSize();
		for( ushort i = 1; us_AddressCount >= i; ++i ) {
			s_MmbBroadcastList.getNode( s_AddressInfo, i );

			if( True == s_AddressInfo.b_Direct ) {	// 直接入力.
				c_MmbDirectAddressCount.countUpAddressCount( s_AddressInfo.e_SendMode );
			} else {								// 短縮宛先.
				c_MmbShorteningAddressCount.countUpAddressCount( s_AddressInfo.e_SendMode );
			}
		}
		bl_MmbAddressCount = True;
	}
}
//================================================================================================
//クラス  ：TYPC_BroadcastAddress : 同報宛先管理クラス
//概要    ：直接入力宛先のリスト作成.
//================================================================================================
void TYPC_BroadcastAddress::createDirectAddressList()
{
	c_DirectAddressList.delAll();
	const ushort us_AddressCount = s_MmbBroadcastList.getNodeSize();
	for( ushort i = 0; us_AddressCount > i; ++i ) {
		if( True == s_MmbBroadcastAddress[i].b_Direct ) {		// 直接入力.
			c_DirectAddressList.add( &( s_MmbBroadcastAddress[i] ) );
		}
	}
}
//================================================================================================
//クラス  ：TYPC_BroadcastAddress : 同報宛先管理クラス
//概要    ：直接入力アドレス数の取得.
//================================================================================================
short TYPC_BroadcastAddress::getDirectAddressNum()
{
	return c_DirectAddressList.getCount();
}
//================================================================================================
//クラス  ：TYPC_BroadcastAddress : 同報宛先管理クラス
//概要    ：直接入力アドレス情報の取得.
//================================================================================================
Bool TYPC_BroadcastAddress::getDirectAddressInfo( TYPS_AddressInfo& s_AddressInfo, const short ss_Index )
{
	TYPS_AddressInfo* ps_AddressInfo = c_DirectAddressList.findFirst();
	short ss_DirectAddressNum = getDirectAddressNum();

	if( ( 0 == ss_Index ) || NULL == ps_AddressInfo ) {
		PnlComPutDebugLog( True, UC_PNL_LOGPATTERN_1, "TYPC_BroadcastAddress::getUniqueBroadcastAddressInfo", UC_PNL_ERROR_PARAMETER );
		return False;
	}
	if( ss_DirectAddressNum < ss_Index ) {
		return False;
	}
	if( 1 == ss_Index ) {
		memcpy( &s_AddressInfo, ps_AddressInfo, sizeof( TYPS_AddressInfo ) );
	} else {
		for( short i = 0; ( ss_Index - 1 ) > i; i++ ) {
			ps_AddressInfo = c_DirectAddressList.findNext();
		}
		if( NULL != ps_AddressInfo ) {
			memcpy( &s_AddressInfo, ps_AddressInfo, sizeof( TYPS_AddressInfo ) );
		}
	}
	return True;
}

//================================================================================================
//クラス  ：TYPC_SelectDocument : 選択文書管理クラス
//概要    ：ボックス番号の設定
//================================================================================================
void TYPC_SelectDocument::setBoxNumber( const int32_t sl_BoxNumber )
{
	if( DOCD_BoxIdDefault == sl_BoxNumber ) {
		PnlComPutDebugLog( True, UC_PNL_LOGPATTERN_1, "TYPC_SelectDocument::setBoxNumber", UC_PNL_ERROR_PARAMETER );
		return;
	}
	// ボックス番号の設定.
	sl_MmbBoxNumber = sl_BoxNumber;
// comment 2016/28/21 HCLT-Archana [IT5_3.4] [AR1009642] Commenting resetting the node and adding it based on condition check.
//	// 選択文書リストを空にする.
//	c_MmbSelectDocList.resetAllNode();
	// 操作対象となる文書、選択中の文書を初期化.
	us_MmbEffectivePosition = TYPD_SelectDocumentEffectiveStart;
// comment 2016/28/21 HCLT-Archana [IT5_3.4] [AR1009642] Resetting the node and the index of the document selected document based on condition.
//	us_MmbSelectDocListNum = 0;
	if( 0 == c_MmbSelectDocList.getNodeSize() ) {
		c_MmbSelectDocList.resetAllNode();	// Empty the selected document list.
		us_MmbSelectDocListNum = 0;
	}
}
