//================================================================================================
//クラス  ：TYPC_SelectDocument : 選択文書管理クラス
//概要    ：1200dpi文書の有無取得.
//================================================================================================
Bool TYPC_SelectDocument::get1200DpiDocExist()
{
	TYPC_JobStatus c_JobStatus;
	TYPS_DocumentInfo s_DocumentInfo;
	memset( &s_DocumentInfo, 0x00, sizeof( s_DocumentInfo ) );
	int32_t i32_ret = APID_DocapiMethodOk;
// Commment 2017/09/22 HCL_Venkataramesh [IT5_4.2][RQ-686][WP689] setBoxId support for Network2 user.
//	cp_OneDoc->setBoxId( sl_MmbBoxNumber );
	PNLC_NetworkLan::getInstance()->setBoxIdPNL( cp_OneDoc, sl_MmbBoxNumber );
	for( ushort i = 1; i <=  getSelectDocumentCount(); i++ ) {
		c_MmbSelectDocList.getNode( s_DocumentInfo, i );
		cp_OneDoc->setDocId( s_DocumentInfo.sl_DocID );
// comment 2019/08/19 Sky東島 [EagleHigh][1TB対応].
//		i32_ret = cp_OneDoc->getJobStatus( &c_JobStatus );
		// LocalUIにて保持しているJobStatus情報から取得する(getJobStatusの処理に時間がかかるため).
		i32_ret = PNLC_DocInfoMng::newInstance()->getBackupDocJobStatus( s_DocumentInfo.sl_DocID , &c_JobStatus );
		if( APID_DocapiMethodOk == i32_ret ) {
			if( c_JobStatus.getBoxPrintWarning( TYPE_BoxNgSpec_1200dpiLimit ) ) {
				return True;
			}
		} else {
			LOGF_debug_PutEventLog( LOGF_DEBUG_EVENT_KIND_ALL, 0, LOGD_DEBUG_LEVEL_UNKNOWN, "Assert Failed!" );
		}
	}
	return False;
}

