{
	static TYPC_BroadcastAddress c_BroadcastAddressScanFax( TYPD_LeftSettingScanFaxListNum );
	static TYPC_BroadcastAddress c_BroadcastAddressBox( TYPD_LeftSettingScanFaxListNum );
// comment 2015/3/6 OPS1-Sky東島 [ZeusS][CQ510843].
	static TYPC_BroadcastAddress c_BroadcastAddressFax( TYPD_LeftSettingScanFaxListNum );
	if( NULL == cp_Job ) 	{
	} else {
		// ジョブ指定によるアドレス領域取得.
// comment 2015/3/6 OPS1-Sky東島 [ZeusS][CQ510843].
//		if ( cp_scanfaxJob == cp_Job || cp_faxJob == cp_Job ) {
		if ( cp_scanfaxJob == cp_Job ) {
			// スキャンファックスジョブ
			return &c_BroadcastAddressScanFax;
// comment 2015/3/6 OPS1-Sky東島 [ZeusS][CQ510843].
		} else if( cp_faxJob == cp_Job ) {
			// ファックスジョブ
			return &c_BroadcastAddressFax;
		} else if( cp_jbscanfaxJob == cp_Job ) {
			// ボックス/ジョブリストジョブ
			return &c_BroadcastAddressBox;
		}
		// 上記以外は自動判定を行う.
	}
// comment 2015/3/6 OPS1-Sky東島 [ZeusS][CQ510843].
	if( True == onlyPanel.getFaxAppMode() ){
		return &c_BroadcastAddressFax;
	}
	return ( ( PCGE_JobPutOther == sc_JobPutNo ) ? &c_BroadcastAddressScanFax : &c_BroadcastAddressBox );
}
