//================================================================================================
//グローバル関数
//概要    ：選択文書情報が有効か確認
//================================================================================================
Bool PnlComCheckSelectedDocument( Bool* pbl_EnableDocument, PCGS_CheckSelectedDocumentType* pst_ChkSlctDocType, const Bool bl_ColorCheck )
{
	TYPC_SelectDocument*	pc_SelectDocument	= PnlComGetSelectDocument();														// 選択文書情報の取得.
	Bool				bl_Ret				= True;

	if( ( NULL != pbl_EnableDocument ) && ( NULL != pc_SelectDocument ) && ( NULL != pst_ChkSlctDocType ) ) {
		TYPS_DocumentInfo	st_DocInfo;
		memset( &st_DocInfo, 0x00, sizeof( st_DocInfo ) );
		short				ss_selectNum;													// リスト選択数を取得.
		short				ss_docCount;
		TYPE_FuncLimit		e_accountStatus;

		*pbl_EnableDocument	= True;
		ss_selectNum		= pc_SelectDocument->getSelectDocumentCount();					// リスト選択数を取得.

		for( ss_docCount = 1; ss_selectNum >= ss_docCount; ss_docCount++ ) {
			pc_SelectDocument->getDocumentInfo( st_DocInfo, ss_docCount );					// 選択中のDocument取得.

			if( DOCD_DocFunc_Copy == st_DocInfo.sl_DocFunc ) {								// Copy機能制限.
				e_accountStatus = pst_ChkSlctDocType->e_statusCopy;
			} else if( DOCD_DocFunc_Print == st_DocInfo.sl_DocFunc ) {						// Print機能制限.
				e_accountStatus = pst_ChkSlctDocType->e_statusPrint;
			} else {																		// その他:蓄積文書送信機能制限.
				e_accountStatus = pst_ChkSlctDocType->e_statusBox;
			}

			if( TYPE_FuncLimit_Disable == e_accountStatus ) {								// 機能制限が禁止の場合は無効.
				*pbl_EnableDocument = False;
				break;
			} else if( ( True == bl_ColorCheck ) &&											// 機能制限のカラーチェックを行う場合かつ、.
			           ( TYPE_FuncLimit_OnlyBlack == e_accountStatus ) ) {						// 機能制限がBlackのみの場合は文書のカラーチェック.
				if( 1 != ss_selectNum && TYPE_ColorModeBlack != st_DocInfo.sc_DocColor ) {	// 選択文書数が１でないかつ文書がBlackでない場合.
					*pbl_EnableDocument = False;
					break;
				}
			}
		}
	} else {
		bl_Ret = False;
		LOGF_debug_PutEventLog( LOGF_DEBUG_EVENT_KIND_ALL, 0, LOGD_DEBUG_LEVEL_UNKNOWN, "Assert Failed!" );
	}

	return bl_Ret;
}
