//================================================================================================
//グローバル関数
//概要    :原稿サイズ選択関数 : 自動検出およびサイズ指定の選択、表示・遷移キー版.
//================================================================================================
void PnlComSelectOriginalSize( PSizeField* pc_SizeField, PSinglePartsText* pc_SinglePartsText, POnOffButtonAdd* pc_OnOffButtonAdd )
{
	if( ( NULL == pc_SizeField ) || ( NULL == pc_SinglePartsText ) || ( NULL == pc_OnOffButtonAdd ) ) {
		LOGF_debug_PutEventLog( LOGF_DEBUG_EVENT_KIND_ALL, 0, LOGD_DEBUG_LEVEL_UNKNOWN, "Assert Failed!" );
		return;
	}
	APIC_Job* pc_job = PnlComGetJobCopy();
	if( NULL == pc_job ) {
		LOGF_debug_PutEventLog( LOGF_DEBUG_EVENT_KIND_ALL, 0, LOGD_DEBUG_LEVEL_UNKNOWN, "Assert Failed!" );
		return;
	}
	TYPC_Scan* pc_Scan = pc_job->getJobSpec()->pc_Scan;
	// 原稿サイズの取得.
	TYPC_PaperSize c_PaperSize = pc_Scan->c_OriginalSize.getPaperSize();
	Bool b_Enable = False;
	// 自動検出モードの判定.
	if( pc_Scan->c_OriginalSize.getAutoSize() ) {
		APIC_Original* pc_Original = PnlComGetOriginal();
		// 原稿サイズが確定している場合.
		if( False != comPanelJob->isPlatenOriginalSizeFixed() ) {
			// 自動検出時原稿サイズありかどうかの判定.
			c_PaperSize = pc_Original->getPlatenOriginalSize();
			if( TYPE_SizeCodeUnknown != c_PaperSize.e_SizeCode ) {
				b_Enable = True;
				// 原稿サイズの設定.
				pc_OnOffButtonAdd->setSize( pc_SizeField, c_PaperSize, False, False );
			}
		}
	} else {
		b_Enable = True;
		// 原稿サイズの設定.
		pc_OnOffButtonAdd->setSize( pc_SizeField, c_PaperSize, False, False );
	}
	// 原稿サイズの表示・非表示設定.
	pc_OnOffButtonAdd->showEnableAdd( pc_SizeField, b_Enable );
	// 自動検出状態表示.
	pc_OnOffButtonAdd->showEnableAdd( pc_SinglePartsText, pc_Scan->c_OriginalSize.getAutoSize() );
	// 原稿サイズキーの選択状態表示.
	// 自動検出モードでなければ、選択状態とする.
	pc_OnOffButtonAdd->select( !( pc_Scan->c_OriginalSize.getAutoSize() ) );
}
