//================================================================================================
//グローバル関数
//概要    :ページ切換えキー表示判定関数 : 1/1ページの場合の、ページ切換えキー非表示処理.
//================================================================================================
void PnlComSetupPageKey( PButton* pc_PageUp, PButton* pc_PageDown, short ss_MaxPage )
{
	// 1/1ページの場合、上下キーを非表示にする.
	if( 1 == ss_MaxPage ) {
		pc_PageUp->showEnable( False );
		pc_PageDown->showEnable( False );
	} else if( 1 < ss_MaxPage ) {
		pc_PageUp->showEnable( True );
		pc_PageDown->showEnable( True );
	}
}
