//概要    :ヒントアイコンカウント初期化関数 : 電球アイコンの点滅処理用カウント初期化.
//================================================================================================
void PnlComSetupHintMessageIconInit()
{
	b_HintMessage = False;
	sc_HintMessageCnt = 0;
	// 表示位置を元に戻す
	if( True == b_changePositionMessage ) {
		if( ( ( onlyPanel.bl_isEnlargeDisplayMode == False ) &&																// 通常画面.
		      ( sp_MessageWarningTable[onlyPanel.us_NowMessageWarning].bl_isCombinationCheckError == False ) ) ||				// 組禁警告ではない.
		    ( ( onlyPanel.bl_isEnlargeDisplayMode == True ) &&																	// 拡大画面.
		      ( sp_MessageEnlWarningTable[onlyPanel.us_NowMessageWarning].bl_isCombination == False ) )							// 組禁警告ではない.
		  )	{
			Txt_Message1.changePosition( 168, 8 );
		}
		Txt_MessageAttention.changePosition( 168, 40 );
		Txt_IMDMessage.changePosition( 152, 8 );
		b_changePositionMessage = False;
	}
}
