//================================================================================================
//グローバル関数
//概要    :ヒントアイコン表示判定関数 : 電球アイコンの点滅処理.
//引数    : Bool b_WarningCheck  警告表示状態でヒントアイコンの点滅処理あり(False)／なし(True).
//================================================================================================
void PnlComSetupHintMessageIcon( PSinglePartsGraphic* pc_HintMessage, Bool b_WarningCheck )
{
	if( 0 != onlyPanel.us_NowMessageWarning && True == b_WarningCheck ) {
		sc_HintMessageCnt = 0;
		b_HintMessage = False;
		return;
	}
	pc_HintMessage->showEnable( b_HintMessage );
	if( ( 4 != sc_HintMessageCnt ) && ( True == b_HintMessage ) ) {
		b_HintMessage = False;
		sc_HintMessageCnt++;
	} else {
		b_HintMessage = True;
	}
}
