Bool PCGC_ThumbnailPreviewControl::m_bl_Overlay = False;	// 対象文書にオーバレイ有無.
// 2016/06/21 CQ530867 データアクセスログ(サムネイル変換)追加 Sky大嶋 Start.
//==================================================================================================
// 概要     : ボックス文書のサムネイルデータアクセス時に監査ログを記録する.
// 引数     : int32_t		sl_DocID		：文書ID.
//          : int32_t		sl_BoxID		：ボックスID.
//          : TYPE_ThumbnailResult	e_Result	: サムネイル生成結果.
// 戻り値   : True	: 正常終了.
//            False	: 異常終了.
// 変更履歴 : 2016/05/11 Sky平田 新規作成 監査ログ ファイルアクセスログ対応.
//          : 2016/07/08 Sky大嶋 引数にサムネイル生成結果を追加.
//==================================================================================================
Bool PCGC_ThumbnailPreviewControl::addOpeLogThumbnailImage( int32_t sl_DocID, int32_t sl_BoxID, TYPE_ThumbnailResult e_Result )
{
	Bool bl_Ret = False;
	JLGS_OpeLogFileAccess s_OpeLogFileAccess;
	PNLC_InspectLog c_InspectLog;
	PNLS_InspectLogParam s_InspectLogParam;

	do{
		memset( &s_InspectLogParam, 0, sizeof(s_InspectLogParam) );
		s_InspectLogParam.b_BatchMode	= False;
		s_InspectLogParam.ul_OpeCode	= JLGE_InspectLogReadBoxDoc;
// 2016/07/08 CQ532138 画像アクセスログ対応 Sky大嶋.
		s_InspectLogParam.us_ResultCode	= (TYPE_ThumbnailResult_OK == e_Result) ? JLGE_InspectLogResultOK : JLGE_InspectLogResultNG;
		memset( &s_OpeLogFileAccess, 0, sizeof(s_OpeLogFileAccess) );
		s_OpeLogFileAccess.sl_DocNo		= sl_DocID;		//文書ID.
		s_OpeLogFileAccess.sl_BoxNo		= sl_BoxID;		//ボックスID.
// 2016/08/25 SCD2-Sky Kawanishi [SecV2] Warning除去.
		APIC_Doc::newInstance()->getDocName(sl_DocID, sl_BoxID, (char*)s_OpeLogFileAccess.uc_DocName, sizeof(s_OpeLogFileAccess.uc_DocName), LIBE_CharSetDefault);
		s_InspectLogParam.vp_ExData		= (void *)&s_OpeLogFileAccess;
		c_InspectLog.SetLog( PNLD_LogMember_PnlFileAccess, s_InspectLogParam, PNLD_InspectLogAddMode_FileAccess );
		bl_Ret = True;
	}while(0);

	return bl_Ret;
}

//概要    :サムネイル画像データ取得要求
//［引数］	uchar					uc_option			: サムネイル表示オプション
//			int32_t					sl_BoxID			: BOX番号
//			int32_t					sl_DocID			: ドキュメント番号
//			int32_t					sl_DocPageNum		: ページ番号
//			PActivatable*			pc_PartsPointer		: 取得画像表示パーツポインタ
void PCGC_ThumbnailPreviewControl::getThumbnailImgeData(
    uchar uc_option,
    int32_t sl_BoxID,
    int32_t sl_DocID,
    int32_t sl_DocPageNum,
    PActivatableAdd* pc_PartsPointer,
    PSinglePartsRawGraphic* pc_GraUserIcon,
    TYPE_ImageDir e_ImageDir,
    Bool bl_Req,
    PComponent* pc_Component,
    EP_ComponentAttribute e_ComponentAttr )
{
	m_pc_Component = pc_Component;
	m_e_ComponentAttr = e_ComponentAttr;

// comment 2018/09/27 SCD2-4G吉田 [EagleH][制御構成変更_No.53] サムネイルサイズ対応.
	APIC_PanelSetting* pc_ThumbnailSize = APIC_PanelSetting::newInstance();
	if( NULL == pc_ThumbnailSize ) {
		return;
	}
	short ss_ThumbnailDotImageSize = pc_ThumbnailSize->getThumbnailLength();
	uint32_t ul_ThumbnailImageSize = ( ss_ThumbnailDotImageSize * ss_ThumbnailDotImageSize * 3 + 6 );

	// サムネイル画像取得をキャンセル.
	cancelThumbnailImgeData( uc_option, sl_BoxID, sl_DocID, sl_DocPageNum, pc_PartsPointer, e_ImageDir, bl_Req );
	// サムネイル画像データ取得要求チェック.
	if( True == checkReqThumbnailControl( uc_option, sl_BoxID, sl_DocID, sl_DocPageNum, pc_PartsPointer, e_ImageDir ) ) {
		APIC_ThumbnailConverter* pc_ThumbnailConverter = APIC_ThumbnailConverter::newInstance();
		TYPS_ReqThumbnailPara s_ReqThumbnailPara;
		// サムネイル画像要求パラメータ設定.
		s_ReqThumbnailPara.sl_BoxID = sl_BoxID;
		s_ReqThumbnailPara.sl_DocID = sl_DocID;
		s_ReqThumbnailPara.sl_PageNum = sl_DocPageNum;
		s_ReqThumbnailPara.e_ImageDir = e_ImageDir;
		s_ReqThumbnailPara.e_ThumbnailFormat = TYPE_FileFormatRAW;
// comment 2018/09/27 SCD2-4G吉田 [EagleH][制御構成変更_No.53] サムネイルサイズ対応.
//		s_ReqThumbnailPara.ss_ReqImageDotSizeWidth = PCGD_ThumbnailDotImageSize;
//		s_ReqThumbnailPara.ss_ReqImageDotSizeHight = PCGD_ThumbnailDotImageSize;
		s_ReqThumbnailPara.ss_ReqImageDotSizeWidth = ss_ThumbnailDotImageSize;
		s_ReqThumbnailPara.ss_ReqImageDotSizeHight = ss_ThumbnailDotImageSize;
		s_ReqThumbnailPara.psc_ImageDataPointer = s_ThumbnailControl[uc_option].psc_ImageData + 5;
// Comment IT5_4.0 [AR1011815] A4 model specific is changed to common.
//#if defined( DEF_A4_Cus )			// Comment VenusMLK -> [CQ522607]★A3共通問題★.
// comment 2018/09/27 SCD2-4G吉田 [EagleH][制御構成変更_No.53] サムネイルサイズ対応.
//		s_ReqThumbnailPara.ul_ImageDataPointerSize = PCGD_ThumbnailImageSize - 6;
		s_ReqThumbnailPara.ul_ImageDataPointerSize = ul_ThumbnailImageSize - 6;
//#else // defined( DEF_A4_Cus ).		// Comment VenusMLK -- [CQ522607]★A3共通問題★.
//		s_ReqThumbnailPara.ul_ImageDataPointerSize = PCGD_ThumbnailImageSize;
//#endif // defined( DEF_A4_Cus ).	// Comment VenusMLK <- [CQ522607]★A3共通問題★.
		s_ReqThumbnailPara.e_Priority = TYPE_ThumbnailPriorityHigh;
		PnlComMakeWVEvent( PNLD_WVEVENT_THUMBNAIL_GETSTART, &sl_DocPageNum, sizeof( sl_DocPageNum ) );
		// サムネイル画像要求.
		PanelLog( PNLD_LogKind_Box, "req_getThumbnailData: P1[%p] P2[%s]", &s_ReqThumbnailPara, "ans_ThumbnailData", 0, 0, 0, 0 );
		uint32_t ui32_ReqNum = pc_ThumbnailConverter->req_getThumbnailData( s_ReqThumbnailPara, ans_ThumbnailData );
		// サムネイル画像管理情報設定.
		s_ThumbnailControl[uc_option].ul_reqSerialNo = ui32_ReqNum;
		s_ThumbnailControl[uc_option].e_ImageDataStatus = PCGE_ImageDataRequext;
		s_ThumbnailControl[uc_option].pc_PartsPointer = pc_PartsPointer;
		s_ThumbnailControl[uc_option].pc_PartsRawGraphic = pc_GraUserIcon;
		s_ThumbnailControl[uc_option].pc_PartsPointer->showEnableAdd( pc_GraUserIcon, False );
		s_ThumbnailControl[uc_option].sl_BoxID = sl_BoxID;
		s_ThumbnailControl[uc_option].sl_DocID = sl_DocID;
		s_ThumbnailControl[uc_option].sl_DocPageNum = sl_DocPageNum;
		s_ThumbnailControl[uc_option].e_ImageDir = e_ImageDir;
		s_ThumbnailControl[uc_option].e_GetKind = PCGE_GetPreviewKindNULL;
// comment 2023/07/04 Sky Nakamura [IT6_2.3][TAS000000013824]暗号化PDF設定時、プレビューを表示しない対応.
		s_ThumbnailControl[uc_option].bl_IsWaitForDocInfo = False;
		
// comment 2018/09/27 SCD2-4G吉田 [EagleH][制御構成変更_No.53] サムネイルサイズ対応.
#ifndef DEF_LCD_7INCH
		if( NULL != pc_PartsPointer ){
			pc_PartsPointer->setScalingNeed(False);
		}
#endif	// DEF_LCD_7INCH.
	} else {
		// 既に取得済みの場合、取得済みの画像をMTUI制御部に送る.
		if( PNLE_MTUIMODE_V0 <= PLBC_MultiTouchFunction::getMultiTouchMode() ) { //[MTUIv1-CHANGED] MR対応.
			// サムネイル画像がリクエストエラーでない.
			if( PCGE_GetPreviewKindNoMedia != s_ThumbnailControl[uc_option].e_GetKind ) {
				// サムネイル画像ヘッダーに格納されている画像サイズをチェック.
				if( ( ( s_ThumbnailControl[uc_option].ss_getImageXSize >> 8 )	!= ( short )s_ThumbnailControl[uc_option].psc_ImageData[0] ) ||	// 画像Xサイズ(上位8bit)チェック.
				    ( ( s_ThumbnailControl[uc_option].ss_getImageXSize & 0xff )	!= ( short )s_ThumbnailControl[uc_option].psc_ImageData[1] ) ||	// 画像Xサイズ(下位8bit)チェック.
				    ( ( s_ThumbnailControl[uc_option].ss_getImageYSize >> 8 )	!= ( short )s_ThumbnailControl[uc_option].psc_ImageData[2] ) ||	// 画像Yサイズ(上位8bit)チェック.
				    ( ( s_ThumbnailControl[uc_option].ss_getImageYSize & 0xff )	!= ( short )s_ThumbnailControl[uc_option].psc_ImageData[3] ) ) {	// 画像Yサイズ(下位8bit)チェック.
					// ヘッダーを再生成する.
					createHeaderData( s_ThumbnailControl[uc_option].psc_ImageData, s_ThumbnailControl[uc_option].e_getImageTone, s_ThumbnailControl[uc_option].ss_getImageXSize, s_ThumbnailControl[uc_option].ss_getImageYSize );
				}
			}
// comment 2023/07/04 Sky Nakamura [IT6_2.3][TAS000000013824]暗号化PDF設定時、プレビューを表示しない対応.
			if (True == APIC_SoftDipSw::newInstance()->getSoftDipSwBitForPanelSpecNo(DEFSOFTWARESW125, 2)) {
				TYPE_PdfEncryption e_enc = TYPE_PdfEncryptionNon;
				if (True == PNLC_DocInfoMng::newInstance()->getDocInfo_PdfEncryption(s_ThumbnailControl[uc_option].sl_BoxID, s_ThumbnailControl[uc_option].sl_DocID, &e_enc)) {
					if (TYPE_PdfEncryptionNon != e_enc && DOCE_DocDispTypeInfo_Print == PNLC_BoxDataLib::newInstance()->getDocListType()) {
						replaceThumbnailToEncPdfIconRawData(&(s_ThumbnailControl[uc_option]));
					}
					PnlComMtuiIf_BoxDocumentModel::instance()->setThumbnail( s_ThumbnailControl[uc_option].sl_DocID, ( uchar* )s_ThumbnailControl[uc_option].psc_ImageData );
					PnlComMtuiIf_BoxDocumentPageModel::instance()->setThumbnail( s_ThumbnailControl[uc_option].sl_DocPageNum, ( uchar* )s_ThumbnailControl[uc_option].psc_ImageData );
					s_ThumbnailControl[uc_option].bl_IsWaitForDocInfo = False;
				}
				else {
					s_ThumbnailControl[uc_option].bl_IsWaitForDocInfo = True;
				}
			}
			else {
				PnlComMtuiIf_BoxDocumentModel::instance()->setThumbnail( s_ThumbnailControl[uc_option].sl_DocID, ( uchar* )s_ThumbnailControl[uc_option].psc_ImageData );
				PnlComMtuiIf_BoxDocumentPageModel::instance()->setThumbnail( s_ThumbnailControl[uc_option].sl_DocPageNum, ( uchar* )s_ThumbnailControl[uc_option].psc_ImageData );
				s_ThumbnailControl[uc_option].bl_IsWaitForDocInfo = False; // 念のため.
			}
		}
	}
}
//概要    :プレビュー・左エリア画像データ取得要求
//［引数］	int32_t						sl_BoxID				: BOX番号
//			int32_t						sl_DocID				: ドキュメント番号
//			int32_t						sl_DocPageNum			: ページ番号
//			PActivatable*				pc_PartsPointer			: 取得画像表示パーツポインタ
//			PCGE_PreviewImageDataSize	e_PreviewImageDataSize	: 画像サイズ.
//			TYPE_ImageDir				e_ImageDir				: 画像回転角度
//			Bool						bl_Check				: 画像要求するか否かのチェック（True：チェックする、False：チェックしない）.
//          int32_t                        sl_DocPageNum           : 表示ページ番号.(デフォルト(0)の場合はページ番号と一緒.)
void PCGC_ThumbnailPreviewControl::getDocPreviewImgeData(
    int32_t sl_BoxID,
    int32_t sl_DocID,
    int32_t sl_DocPageNum,
    PActivatable* pc_PartsPointer,
    PCGE_PreviewImageDataSize e_PreviewImageDataSize,
    TYPE_ImageDir e_ImageDir,
    Bool bl_Check,
    int32_t sl_DispDocPageNum,
    Bool bl_isDummyActivateParts )
{
	m_bl_isActivatablePartsDummy = bl_isDummyActivateParts;
	// プレビュー画像取得をキャンセル.
	cancelPreviewImgeData( sl_BoxID, sl_DocID, sl_DocPageNum, pc_PartsPointer, e_PreviewImageDataSize, e_ImageDir );
	PreviewDispImgeData();
	// [MTUI]ボックスプレビューマルチページ対応.
	uchar uc_option = 1;
	if( PCGE_PreviewImageDataSizeLeftErea == e_PreviewImageDataSize ) {
		uc_option = 0;
	} else if( PCGE_PreviewImageDataSizePreviewRightSmall == e_PreviewImageDataSize ) {
		uc_option = 2;
	}
	uchar uc_PreviewScrollLevelX = 0;
	uchar uc_PreviewScrollLevelY = 0;
	getPreviewScrollLevel( &uc_PreviewScrollLevelX, &uc_PreviewScrollLevelY );
	Bool bl_CheckReqPreview = False;
	if( True == checkReqPreviewControl( sl_BoxID, sl_DocID, sl_DocPageNum, pc_PartsPointer, e_PreviewImageDataSize, e_ImageDir, bl_Check ) ) {
		APIC_PreviewConverter* pc_PreviewConverter = APIC_PreviewConverter::newInstance();
		TYPS_ReqPreviewPara s_ReqPreviewPara;
		// プレビュー画像要求パラメータ設定.
		s_ReqPreviewPara.sl_BoxID = sl_BoxID;
		s_ReqPreviewPara.sl_DocID = sl_DocID;
		s_ReqPreviewPara.sl_PageNum = sl_DocPageNum;
		s_ReqPreviewPara.e_PreviewFormat = TYPE_FileFormatRAW;		// add matsuda 出力プレビュー画像フォーマット
		s_ReqPreviewPara.e_ImageDir = e_ImageDir;
// comment 2015/12/10 【HCLT-Meenakshi】【ZeusSZX0】【CQ521750】Stop unnecessary scaling for preview image for 10.1inch.
// comment 2015/12/10 【HCLT-Meenakshi】 【ZeusSZX0】 【CQ521759】 Removing LCD Panel resolution check and added 10.1 inch compilation switch.
// comment 2015/10/07 [HCLT-Chandrasekar] [制御構成変更_No.74] [WP1724] Preview Image Resolution has been modified for 10.1 inch.
//		s_ReqPreviewPara.ss_ReqImageDotSizeWidth = getPreviewXYSize( e_PreviewImageDataSize, s_PreviewControl[uc_option].b_Splitdirection, True );
//		s_ReqPreviewPara.ss_ReqImageDotSizeHight = getPreviewXYSize( e_PreviewImageDataSize, s_PreviewControl[uc_option].b_Splitdirection, False );
//		if ( PNLD_PANELSIZE_10_1INCH == PLBC_PanelDeviceCheck::getInstance()->getPanelSize()  ) {
//#ifdef DEF_RES_WSVGA
//		s_ReqPreviewPara.ss_ReqImageDotSizeWidth = scalePreviewThumbnailWidth( getPreviewXYSize( e_PreviewImageDataSize, s_PreviewControl[uc_option].b_Splitdirection, True ) );
//		s_ReqPreviewPara.ss_ReqImageDotSizeHight = GFWC_System::getInstance()->convertScalingPartsY( getPreviewXYSize( e_PreviewImageDataSize, s_PreviewControl[uc_option].b_Splitdirection, False ) );
//			s_ReqPreviewPara.ul_ImageDataPointerSize = PCGD_PreviewImageSize_WSVGA;
//		} else  {
//#else
		s_ReqPreviewPara.ss_ReqImageDotSizeWidth = getPreviewXYSize( e_PreviewImageDataSize, s_PreviewControl[uc_option].b_Splitdirection, True );
		s_ReqPreviewPara.ss_ReqImageDotSizeHight = getPreviewXYSize( e_PreviewImageDataSize, s_PreviewControl[uc_option].b_Splitdirection, False );
//			s_ReqPreviewPara.ul_ImageDataPointerSize = PCGD_PreviewImageSize;
//		}
//#endif
		s_ReqPreviewPara.psc_ImageDataPointer = s_PreviewControl[uc_option].psc_ImageData + 5;
		s_ReqPreviewPara.ul_ImageDataPointerSize = PCGD_PreviewImageSize;
		PnlComMakeWVEvent( PNLD_WVEVENT_PREVIEW_GETSTART, &uc_option, sizeof( uc_option ) );
		PanelLog( PNLD_LogKind_Box, "req_getPreviewData: P1[%p] P2[%s]", &s_ReqPreviewPara, "ans_PreviewData", 0, 0, 0, 0 );
		uint32_t ui32_ReqNum = pc_PreviewConverter->req_getPreviewData( s_ReqPreviewPara, ans_PreviewData );
		bl_CheckReqPreview = True;
		// プレビュー画像管理情報設定.
		s_PreviewControl[uc_option].ul_reqSerialNo = ui32_ReqNum;
		s_PreviewControl[uc_option].e_ImageDataStatus = PCGE_ImageDataRequext;
		s_PreviewControl[uc_option].pc_PartsPointer = pc_PartsPointer;
		s_PreviewControl[uc_option].pc_PartsPointer->showEnableAdd( False );
		s_PreviewControl[uc_option].sl_BoxID = sl_BoxID;
		s_PreviewControl[uc_option].sl_DocID = sl_DocID;
		s_PreviewControl[uc_option].e_GetKind = PCGE_GetPreviewKindNULL;
		s_PreviewControl[uc_option].sl_DocPageNum = sl_DocPageNum;
		s_PreviewControl[uc_option].sl_DispDocPageNum = sl_DispDocPageNum;
		s_PreviewControl[uc_option].e_PreviewImageDataSize = e_PreviewImageDataSize;
		s_PreviewControl[uc_option].e_ImageDir = e_ImageDir;
		s_PreviewControl[uc_option].uc_PreviewScrollLevelX = 0;
		s_PreviewControl[uc_option].uc_PreviewScrollLevelY = 0;
		changePreviewScrollLevel( ( uchar )0, ( uchar )0 );
	}
	else if( ( uc_PreviewScrollLevelX != s_PreviewControl[uc_option].uc_PreviewScrollLevelX )
	         || ( uc_PreviewScrollLevelY != s_PreviewControl[uc_option].uc_PreviewScrollLevelY ) ) {
		s_PreviewControl[uc_option].uc_PreviewScrollLevelX = uc_PreviewScrollLevelX;
		s_PreviewControl[uc_option].uc_PreviewScrollLevelY = uc_PreviewScrollLevelY;
		if( PCGE_ImageDataDrawingEnd == s_PreviewControl[uc_option].e_ImageDataStatus ) {
			// 画像表示タイプを取得する.
			PCGE_ImageDisplayType e_ImageDisplayType = getPreviewImageDisplayType( e_PreviewImageDataSize );
			s_PreviewControl[uc_option].e_ImageDataStatus = PCGE_ImageDataComplete;
			showPreviewImage( e_ImageDisplayType );
		}
	}
	if( False == bl_CheckReqPreview ) {
		if( False == m_bl_isActivatablePartsDummy )
		{
			if( ( PNLE_MTUIMODE_V2 > PLBC_MultiTouchFunction::getMultiTouchMode()
			      ||   False == PLBC_FuncVersionCheck::isOK_MiZe_Type4() )
			    || ( False == m_bl_PreviewMtuiExt ) ) {                               	// 旧QtWidget or 旧UIのプレビュー処理を行わない.
				PnlComQtPreviewCancelReading();
			}
		} else {
			PNLC_DummyActivatable* p_dummyParts = ( PNLC_DummyActivatable* )pc_PartsPointer;
			p_dummyParts->cancelReadingImagerNoticed();
		}
	}
}

//概要    :プレビュー・スタンプ画像データ取得要求.
//［引数］	PActivatable*				pc_PartsPointer			: 取得画像表示パーツポインタ.
//			PCGE_GetPreviewKind			e_GetKind				: プレビュー画像取得種類.
//			uint32_t					sl_StampKind			: スタンプID.
//			PCGE_PreviewImageDataSize	e_PreviewImageDataSize	: 画像サイズ.
//			TYPE_ImageDir				e_ImageDir				: 画像回転角度.
//			Bool						bl_isGestureZoom		: check gesture zoom.
//
void PCGC_ThumbnailPreviewControl::getStampPreviewImgeData(
    PActivatable* pc_PartsPointer,
    PCGE_GetPreviewKind e_GetKind,
    uint32_t sl_StampKind,
    PCGE_PreviewImageDataSize e_PreviewImageDataSize,
    TYPE_ImageDir e_ImageDir,
    Bool bl_isDummyActivateParts,
	Bool bl_isGestureZoom ) //comment 2023/02/28 FPT-DuongDV11【IT6_2.3】【OP_BTS-39930】 登録したオーバーレイのプレビュー詳細画面で、ジェスチャーで拡大実施、プレビュー詳細画面は上下に移動できなくなる.
{
	m_bl_isActivatablePartsDummy = bl_isDummyActivateParts;
	uchar uc_option = getNumPreviewControl( e_GetKind );	// 対象プレビューからプレビュー管理情報の位置取得.
	// プレビュー画像取得をキャンセル.
	cancelStampPreviewImgeData( pc_PartsPointer, e_GetKind, sl_StampKind, uc_option, e_PreviewImageDataSize, e_ImageDir );
	//プレビュー表示非表示設定.
	PreviewDispImgeData();
	// プレビュー画像のスクロール位置を取得する.
	uchar uc_PreviewScrollLevelX = 0;
	uchar uc_PreviewScrollLevelY = 0;
	getPreviewScrollLevel( &uc_PreviewScrollLevelX, &uc_PreviewScrollLevelY );

// comment 2018/09/27 SCD2-4G吉田 [EagleH][制御構成変更_No.53] サムネイルサイズ対応.
	APIC_PanelSetting* pc_ThumbnailSize = APIC_PanelSetting::newInstance();
	if( NULL == pc_ThumbnailSize ) {
		return;
	}
	short ss_ThumbnailDotImageSize = pc_ThumbnailSize->getThumbnailLength();
	uint32_t ul_ThumbnailImageSize = ( ss_ThumbnailDotImageSize * ss_ThumbnailDotImageSize * 3 + 6 );

	// プレビュー画像データ取得要求チェック.
	//comment 2023/02/28 FPT-DuongDV11【IT6_2.3】【OP_BTS-39930】 登録したオーバーレイのプレビュー詳細画面で、ジェスチャーで拡大実施、プレビュー詳細画面は上下に移動できなくなる.
	if( True == checkReqStampPreviewControl( pc_PartsPointer, e_GetKind, sl_StampKind, uc_option, e_PreviewImageDataSize, e_ImageDir, bl_isGestureZoom ) ) {
		uint32_t ui32_ReqNum = 0;	// 受付番号.
		APIC_PreviewConverter* pc_PreviewConverter = APIC_PreviewConverter::newInstance();
		// プレビュー画像取得.
		switch( e_GetKind ) {
			case PCGE_GetPreviewKindOverlay1:		// オーバーレイ1.
			case PCGE_GetPreviewKindOverlay2:		// オーバーレイ2.
			case PCGE_GetPreviewKindOverlay3:		// オーバーレイ3.
			case PCGE_GetPreviewKindOverlay4:		// オーバーレイ4.
			case PCGE_GetPreviewKindOverlay5:		// オーバーレイ5.
			case PCGE_GetPreviewKindOverlay6:		// オーバーレイ6.
			{

				if( 0 > sl_StampKind ) {	// 範囲チェック.

					return;
				}
				TYPS_ReqThumbnailPara s_ReqThumbnailPara;
				// プレビュー画像要求パラメータ設定.
				s_ReqThumbnailPara.sl_BoxID= DOCD_OverLayBox;
				s_ReqThumbnailPara.sl_DocID = sl_StampKind;				// 【CQ.325539】256件以上登録した際に画像取得が行われない問題の対策 酒井健.
				s_ReqThumbnailPara.sl_PageNum = 1;
				s_ReqThumbnailPara.e_ThumbnailFormat = TYPE_FileFormatRAW;
// comment 2018/09/27 SCD2-4G吉田 [EagleH][制御構成変更_No.53] サムネイルサイズ対応.
//				s_ReqThumbnailPara.ss_ReqImageDotSizeWidth = PCGD_ThumbnailDotImageSize;
//				s_ReqThumbnailPara.ss_ReqImageDotSizeHight = PCGD_ThumbnailDotImageSize;
				s_ReqThumbnailPara.ss_ReqImageDotSizeWidth = ss_ThumbnailDotImageSize;
				s_ReqThumbnailPara.ss_ReqImageDotSizeHight = ss_ThumbnailDotImageSize;
				s_ReqThumbnailPara.e_ImagePlace = TYPE_ImagePlaceMemory;
				s_ReqThumbnailPara.psc_ImageDataPointer = s_ThumbnailControl[uc_option].psc_ImageData + 5;
// Comment IT5_4.0 [AR1011815] A4 model specific is changed to common.
//#if defined( DEF_A4_Cus )			// Comment VenusMLK -> [CQ522607]★A3共通問題★.
// comment 2018/09/27 SCD2-4G吉田 [EagleH][制御構成変更_No.53] サムネイルサイズ対応.
//				s_ReqThumbnailPara.ul_ImageDataPointerSize = PCGD_ThumbnailImageSize - 6;
				s_ReqThumbnailPara.ul_ImageDataPointerSize = ul_ThumbnailImageSize - 6;
//#else // defined( DEF_A4_Cus ).		// Comment VenusMLK -- [CQ522607]★A3共通問題★.
//				s_ReqThumbnailPara.ul_ImageDataPointerSize = PCGD_ThumbnailImageSize;
//#endif // defined( DEF_A4_Cus ).	// Comment VenusMLK <- [CQ522607]★A3共通問題★.
				// プレビュー画像要求.
				APIC_ThumbnailConverter* pc_ThumbnailConverter = APIC_ThumbnailConverter::newInstance();
				PanelLog( PNLD_LogKind_Box, "req_getThumbnailData: P1[%p] P2[%s]", &s_ReqThumbnailPara, "ans_OverlayData", 0, 0, 0, 0 );
				ui32_ReqNum = pc_ThumbnailConverter->req_getThumbnailData( s_ReqThumbnailPara, ans_OverlayData );
				s_ThumbnailControl[uc_option].uc_OverlayID = ( uchar )sl_StampKind;	// プレビュー画像情報保存.
// comment 2018/09/27 SCD2-4G吉田 [EagleH][制御構成変更_No.53] サムネイルサイズ対応.
#ifndef DEF_LCD_7INCH
				if( NULL != pc_PartsPointer ){
					pc_PartsPointer->setScalingNeed(False);
				}
#endif	// DEF_LCD_7INCH.
				break;
			}
			case PCGE_GetPreviewKindOverlayDetail:	// オーバーレイ詳細.
			{

				if( 0 > sl_StampKind ) {	// 範囲チェック.

					return;
				}
				TYPS_ReqPreviewPara s_ReqPreviewPara;
				// プレビュー画像要求パラメータ設定.
				s_ReqPreviewPara.sl_BoxID = DOCD_OverLayBox;
				s_ReqPreviewPara.sl_DocID = sl_StampKind;
				s_ReqPreviewPara.sl_PageNum = 1;
				s_ReqPreviewPara.e_PreviewFormat = TYPE_FileFormatRAW;		// add matsuda 出力プレビュー画像フォーマット
				s_ReqPreviewPara.e_ImageDir = e_ImageDir;
// comment 2015/12/10 【HCLT-Meenakshi】【ZeusSZX0】【CQ521750】Stop unnecessary scaling for preview image for 10.1inch.
// comment 2015/12/10 【HCLT-Meenakshi】 【ZeusSZX0】 【CQ521759】 Removing LCD Panel resolution check and added 10.1 inch compilation switch.
// comment 2015/10/07 [HCLT-Chandrasekar] [制御構成変更_No.74] [WP1724] Preview Image Resolution has been modified for 10.1 inch.
//				s_ReqPreviewPara.ss_ReqImageDotSizeWidth = getPreviewXYSize( e_PreviewImageDataSize, s_PreviewControl[uc_option].b_Splitdirection, True );
//				s_ReqPreviewPara.ss_ReqImageDotSizeHight = getPreviewXYSize( e_PreviewImageDataSize, s_PreviewControl[uc_option].b_Splitdirection, False );
				//Resolution modified for 10.1 inch. Vertical & Horizontal zoom ratio for Preview/Thumbnail is 1.25(1Pane) & 1.113(3Pane).
//				if ( PNLD_PANELSIZE_10_1INCH == PLBC_PanelDeviceCheck::getInstance()->getPanelSize()  ) {
//#ifdef DEF_RES_WSVGA
//				s_ReqPreviewPara.ss_ReqImageDotSizeWidth = scalePreviewThumbnailWidth(getPreviewXYSize( e_PreviewImageDataSize, s_PreviewControl[uc_option].b_Splitdirection, True ));
//				s_ReqPreviewPara.ss_ReqImageDotSizeHight = GFWC_System::getInstance()->convertScalingPartsY (getPreviewXYSize( e_PreviewImageDataSize, s_PreviewControl[uc_option].b_Splitdirection, False ));
//					s_ReqPreviewPara.ul_ImageDataPointerSize = PCGD_PreviewImageSize_WSVGA;
//				} else {
//#else
				s_ReqPreviewPara.ss_ReqImageDotSizeWidth = getPreviewXYSize( e_PreviewImageDataSize, s_PreviewControl[uc_option].b_Splitdirection, True );
				s_ReqPreviewPara.ss_ReqImageDotSizeHight = getPreviewXYSize( e_PreviewImageDataSize, s_PreviewControl[uc_option].b_Splitdirection, False );
//					s_ReqPreviewPara.ul_ImageDataPointerSize = PCGD_PreviewImageSize;
//				}
//#endif
				s_ReqPreviewPara.e_ImagePlace = TYPE_ImagePlaceMemory;
				s_ReqPreviewPara.psc_ImageDataPointer = s_PreviewControl[uc_option].psc_ImageData + 5;
				s_ReqPreviewPara.ul_ImageDataPointerSize = PCGD_PreviewImageSize;
				PnlComMakeWVEvent( PNLD_WVEVENT_PREVIEW_GETSTART, &uc_option, sizeof( uc_option ) );

				// Preview画像要求.
				PanelLog( PNLD_LogKind_Box, "req_getPreviewData: P1[%p] P2[%s]", &s_ReqPreviewPara, "ans_PreviewData", 0, 0, 0, 0 );
				ui32_ReqNum = pc_PreviewConverter->req_getPreviewData( s_ReqPreviewPara, ans_PreviewData );
				s_PreviewControl[uc_option].uc_OverlayID = ( uchar )sl_StampKind;	// プレビュー画像情報保存.
				break;
			}
			case PCGE_GetPreviewKindJobLog:			// ジョブ履歴.
			{
				if( 0 > sl_StampKind ) {	// 範囲チェック.
					return;
				}
				TYPS_ReqHistoryPara s_ReqHistoryPara;
				// プレビュー画像要求パラメータ設定.
				s_ReqHistoryPara.sl_JobID = ( int32_t )sl_StampKind;
				s_ReqHistoryPara.e_ThumbnailFormat = TYPE_FileFormatRAW;
				s_ReqHistoryPara.psc_ImageDataPointer = s_PreviewControl[uc_option].psc_ImageData + 5;
// comment 2018/09/27 SCD2-4G吉田 [EagleH][制御構成変更_No.53] サムネイルサイズ対応.
//				s_ReqHistoryPara.ss_ReqImageDotSizeWidth = PCGD_HistoryPreviewDotImageSize;
//				s_ReqHistoryPara.ss_ReqImageDotSizeHight = PCGD_HistoryPreviewDotImageSize;
//				s_ReqHistoryPara.ul_ImageDataPointerSize = PCGD_HistoryPreviewImageSize;
				s_ReqHistoryPara.ss_ReqImageDotSizeWidth = ss_ThumbnailDotImageSize;
				s_ReqHistoryPara.ss_ReqImageDotSizeHight = ss_ThumbnailDotImageSize;
				s_ReqHistoryPara.ul_ImageDataPointerSize = ul_ThumbnailImageSize;
				// プレビュー画像要求.
				APIC_ThumbnailConverter* pc_ThumbnailConverter = APIC_ThumbnailConverter::newInstance();
				PanelLog( PNLD_LogKind_Box, "req_getJobThumbnailData: P1[%p] P2[%s]", &s_ReqHistoryPara, "ans_JobLogData", 0, 0, 0, 0 );
				ui32_ReqNum = pc_ThumbnailConverter->req_getJobThumbnailData( s_ReqHistoryPara, ans_JobLogData );
				s_PreviewControl[uc_option].sl_JobID = ( int32_t )sl_StampKind;	// プレビュー画像情報保存.
// comment 2018/09/27 SCD2-4G吉田 [EagleH][制御構成変更_No.53] サムネイルサイズ対応.
#ifndef DEF_LCD_7INCH
				if( NULL != pc_PartsPointer ){
					pc_PartsPointer->setScalingNeed(False);
				}
#endif		// DEF_LCD_7INCH.
				break;
			}
			default:
				break;
		}

		switch( e_GetKind ) {
			case PCGE_GetPreviewKindOverlay1:		// オーバーレイ1.
			case PCGE_GetPreviewKindOverlay2:		// オーバーレイ2.
			case PCGE_GetPreviewKindOverlay3:		// オーバーレイ3.
			case PCGE_GetPreviewKindOverlay4:		// オーバーレイ4.
			case PCGE_GetPreviewKindOverlay5:		// オーバーレイ5.
			case PCGE_GetPreviewKindOverlay6:		// オーバーレイ6.
				// プレビュー画像管理情報設定.
				s_ThumbnailControl[uc_option].ul_reqSerialNo = ui32_ReqNum;
				s_ThumbnailControl[uc_option].sl_BoxID = 0;
				s_ThumbnailControl[uc_option].sl_DocID = 0;
				s_ThumbnailControl[uc_option].sl_DocPageNum = 0;
				s_ThumbnailControl[uc_option].e_ImageDataStatus = PCGE_ImageDataRequext;
				s_ThumbnailControl[uc_option].e_GetKind = e_GetKind;
				s_ThumbnailControl[uc_option].pc_PartsPointerOverlay = pc_PartsPointer;
				s_ThumbnailControl[uc_option].pc_PartsPointerOverlay->showEnableAdd( False );
				s_ThumbnailControl[uc_option].e_ImageDir = e_ImageDir;
				break;
			case PCGE_GetPreviewKindOverlayDetail:		// オーバーレイ詳細.
				s_PreviewControl[uc_option].ul_reqSerialNo = ui32_ReqNum;
				s_PreviewControl[uc_option].sl_BoxID = DOCD_OverLayBox;
				s_PreviewControl[uc_option].sl_DocID = sl_StampKind;
				s_PreviewControl[uc_option].sl_DocPageNum = 1;
				s_PreviewControl[uc_option].sl_DispDocPageNum = 0;
				s_PreviewControl[uc_option].e_ImageDataStatus = PCGE_ImageDataRequext;
				s_PreviewControl[uc_option].e_GetKind = e_GetKind;
				s_PreviewControl[uc_option].pc_PartsPointer = pc_PartsPointer;
				s_PreviewControl[uc_option].pc_PartsPointer->showEnableAdd( False );
				s_PreviewControl[uc_option].e_PreviewImageDataSize = e_PreviewImageDataSize;
				s_PreviewControl[uc_option].e_ImageDir = e_ImageDir;
				s_PreviewControl[uc_option].uc_PreviewScrollLevelX = 0;
				s_PreviewControl[uc_option].uc_PreviewScrollLevelY = 0;
				break;
			default:
				// プレビュー画像管理情報設定.
				s_PreviewControl[uc_option].ul_reqSerialNo = ui32_ReqNum;
				s_PreviewControl[uc_option].sl_BoxID = 0;
				s_PreviewControl[uc_option].sl_DocID = 0;
				s_PreviewControl[uc_option].sl_DocPageNum = 0;
				s_PreviewControl[uc_option].sl_DispDocPageNum = 0;
				s_PreviewControl[uc_option].e_ImageDataStatus = PCGE_ImageDataRequext;
				s_PreviewControl[uc_option].e_GetKind = e_GetKind;
				s_PreviewControl[uc_option].pc_PartsPointer = pc_PartsPointer;
				s_PreviewControl[uc_option].pc_PartsPointer->showEnableAdd( False );
				s_PreviewControl[uc_option].e_PreviewImageDataSize = e_PreviewImageDataSize;
				s_PreviewControl[uc_option].e_ImageDir = e_ImageDir;
				s_PreviewControl[uc_option].uc_PreviewScrollLevelX = 0;
				s_PreviewControl[uc_option].uc_PreviewScrollLevelY = 0;
				break;
		}
		// プレビュー画像のスクロール位置を初期化する.
		changePreviewScrollLevel( ( uchar )0, ( uchar )0 );
	}
	else if( ( PCGE_GetPreviewKindOverlayDetail == e_GetKind )		// オーバーレイ詳細.
	         &&( ( uc_PreviewScrollLevelX != s_PreviewControl[uc_option].uc_PreviewScrollLevelX )
	             ||( uc_PreviewScrollLevelY != s_PreviewControl[uc_option].uc_PreviewScrollLevelY ) ) ) {
		// プレビュー画像のスクロール位置を更新する.
		s_PreviewControl[uc_option].uc_PreviewScrollLevelX = uc_PreviewScrollLevelX;
		s_PreviewControl[uc_option].uc_PreviewScrollLevelY = uc_PreviewScrollLevelY;

		// プレビュー画像描画要求完了時の場合.
		if( PCGE_ImageDataDrawingEnd == s_PreviewControl[uc_option].e_ImageDataStatus ) {
			// 画像表示タイプを取得する.
			PCGE_ImageDisplayType e_ImageDisplayType = getPreviewImageDisplayType( e_PreviewImageDataSize );

			// プレビュー画像を表示する.
			s_PreviewControl[uc_option].e_ImageDataStatus = PCGE_ImageDataComplete;
			showPreviewImage( e_ImageDisplayType );
		}
	}
}

//概要    :メディアダイレクトサムネイル画像データ取得要求.
//［引数］	uchar*				uc_option		: サムネイル表示オプション.
//			POnOffButtonAdd*	pc_PartsPointer	: 取得画像表示パーツポインタ.
//			char*				sc_FilePath		: ファイルパス（フルパス）.
void PCGC_ThumbnailPreviewControl::getMediaDirectThumbnailImageData(
    uchar uc_option,
    char* sc_FilePath,
    PActivatableAdd* pc_PartsPointer,
    PSinglePartsRawGraphic* pc_GraUserIcon,
    PSelectButton* pc_NotThumbnail )
{
// Comment 2019/02/14【HCLT-Naveena】【OP_BTS-2893 】【ID: 190949】RNPD.DREF.
	if( NULL == pc_PartsPointer ){
		LOGF_debug_PutEventLog( LOGF_DEBUG_EVENT_KIND_ALL, 0, LOGD_DEBUG_LEVEL_UNKNOWN, "Assert Failed!" );
		return;
	}
	if( !sc_FilePath ) {	// NULLチェック.
		return;
	}
	// サムネイル画像取得をキャンセル.
	if( ( 0 != strcmp( sc_FilePath, s_ThumbnailControl[ uc_option ].sc_MediaDirectFilePath )
	      || s_ThumbnailControl[uc_option].pc_PartsPointer != pc_PartsPointer )
	    && s_ThumbnailControl[uc_option].e_ImageDataStatus == PCGE_ImageDataRequext ) {
		// サムネイル画像要求のキャンセル.
		APIC_ThumbnailConverter* pc_ThumbnailConverter = APIC_ThumbnailConverter::newInstance();
		PanelLog( PNLD_LogKind_Box, "req_cancel: P1[%u]", s_ThumbnailControl[uc_option].ul_reqSerialNo, 0, 0, 0, 0, 0 );
		pc_ThumbnailConverter->req_cancel( s_ThumbnailControl[uc_option].ul_reqSerialNo );
		// 画像データ取得ステータスを初期化.
		s_ThumbnailControl[uc_option].e_ImageDataStatus = PCGE_ImageDataNonComplete;
	}
	pc_PartsPointer->showEnable( False );
	if( 0 != pc_NotThumbnail ) {
		pc_NotThumbnail->showEnable( False );
	}
	// サムネイル画像データ取得要求チェック.
	if( ( 0 == strcmp( sc_FilePath, s_ThumbnailControl[ uc_option ].sc_MediaDirectFilePath ) )
	    && ( s_ThumbnailControl[uc_option].pc_PartsPointer == pc_PartsPointer )
	    && ( s_ThumbnailControl[uc_option].e_ImageDataStatus != PCGE_ImageDataNonComplete ) ) {
		// 既に画像データ取得済み、もしくは要求中.
		if( PCGE_GetPreviewKindNoMedia == s_ThumbnailControl[uc_option].e_GetKind ) {
			if( 0 != pc_NotThumbnail ) {
				pc_NotThumbnail->changeGraphic( PG_USBIcon_X104Y104 );		// サムネイルを定型アイコンにする.
				pc_NotThumbnail->showEnable( True );
			}
		} else {
			pc_PartsPointer->showEnable( True );
		}
		return;
	}
	TYPS_ReqMediaThumbnailPara s_ReqMediaThumbnailPara;
// comment 2018/09/27 SCD2-4G吉田 [EagleH][制御構成変更_No.53] サムネイルサイズ対応.
	APIC_PanelSetting* pc_ThumbnailSize = APIC_PanelSetting::newInstance();
	if( NULL == pc_ThumbnailSize ) {
		return;
	}
	short ss_ThumbnailDotImageSize = pc_ThumbnailSize->getThumbnailLength();
	uint32_t ul_ThumbnailImageSize = ( ss_ThumbnailDotImageSize * ss_ThumbnailDotImageSize * 3 + 6 );

	// サムネイル画像要求パラメータ設定.
	s_ReqMediaThumbnailPara.ps_InputFilePointer			= NULL;							// 入力ファイル（PDF)ポインター（パネルからは常にNULL）.
	s_ReqMediaThumbnailPara.e_InputFileFormat			= TYPE_FileFormatPdf;			// 入力ファイル画像フォーマット(PDFファイルのみ).
	s_ReqMediaThumbnailPara.sl_PageNum					= 1;							// ページ番号（現状固定「1」とする）.
	s_ReqMediaThumbnailPara.e_ThumbnailFormat			= TYPE_FileFormatRAW;			// 出力サムネイル画像フォーマット(RAW/JPEGのみ）.
// comment 2018/09/27 SCD2-4G吉田 [EagleH][制御構成変更_No.53] サムネイルサイズ対応.
//	s_ReqMediaThumbnailPara.ss_ReqImageDotMaxSizeWidth 	= PCGD_ThumbnailDotImageSize;	// 出力サムネイル画像ドット最大値(幅)(1～104).
//	s_ReqMediaThumbnailPara.ss_ReqImageDotMaxSizeHight 	= PCGD_ThumbnailDotImageSize;	// 出力サムネイル画像ドット最大値(高さ)(1～104).
	s_ReqMediaThumbnailPara.ss_ReqImageDotMaxSizeWidth 	= ss_ThumbnailDotImageSize;	// 出力サムネイル画像ドット最大値(幅)(1～104).
	s_ReqMediaThumbnailPara.ss_ReqImageDotMaxSizeHight 	= ss_ThumbnailDotImageSize;	// 出力サムネイル画像ドット最大値(高さ)(1～104).
	s_ReqMediaThumbnailPara.e_ImagePlace				= TYPE_ImagePlaceMemory;		// 出力サムネイル画像の保存場所.
	s_ReqMediaThumbnailPara.psc_ImageDataPointer 		= s_ThumbnailControl[uc_option].psc_ImageData + 5;	// 出力画像エリアの先頭アドレス.
// comment 2018/09/27 SCD2-4G吉田 [EagleH][制御構成変更_No.53] サムネイルサイズ対応.
//	s_ReqMediaThumbnailPara.ul_ImageDataPointerSize		= PCGD_ThumbnailImageSize;		// 出力画像エリアのメモリサイズ.
	s_ReqMediaThumbnailPara.ul_ImageDataPointerSize		= ul_ThumbnailImageSize;		// 出力画像エリアのメモリサイズ.

	// サムネイル画像要求.
	uint32_t ui32_ReqNum = 0;
	if( False != PLBC_FuncVersionCheck::isOK_Type3() ) {				// Donau拡張機能3、Amur機能拡張2以降.
	} else {
	}
	// サムネイル画像管理情報設定.
	memcpy( s_ThumbnailControl[uc_option].sc_MediaDirectFilePath, sc_FilePath, PNLD_PrintFileNameMax+1 );	// プレビュー画像情報保存.
	s_ThumbnailControl[uc_option].ul_reqSerialNo = ui32_ReqNum;
	s_ThumbnailControl[uc_option].e_ImageDataStatus = PCGE_ImageDataRequext;
	s_ThumbnailControl[uc_option].pc_PartsPointer = pc_PartsPointer;
	s_ThumbnailControl[uc_option].pc_PartsRawGraphic = pc_GraUserIcon;
	s_ThumbnailControl[uc_option].pc_PartsPointer->showEnableAdd( pc_GraUserIcon, False );
	s_ThumbnailControl[uc_option].e_GetKind = PCGE_GetPreviewKindNULL;
	s_ThumbnailControl[uc_option].pc_NotThumbnail = pc_NotThumbnail;
// comment 2018/09/27 SCD2-4G吉田 [EagleH][制御構成変更_No.53] サムネイルサイズ対応.
#ifndef DEF_LCD_7INCH
	if( NULL != pc_PartsPointer ){
		pc_PartsPointer->setScalingNeed(False);
	}
#endif		// DEF_LCD_7INCH.
}

// 概要    :対象プレビューからプレビュー管理情報の位置取得
//［引数］	PCGE_GetPreviewKind	e_GetKind	: プレビュー画像取得種類
//［戻値］	uchar	:要求結果
uchar PCGC_ThumbnailPreviewControl::getNumPreviewControl( PCGE_GetPreviewKind e_GetKind )
{
	switch( e_GetKind ) {
		case PCGE_GetPreviewKindStamp:					// スタンプ.
		case PCGE_GetPreviewKindWatermark:				// ウォーターマーク.
		case PCGE_GetPreviewKindOverlayDetail:			// オーバーレイ詳細.
		case PCGE_GetPreviewKindJobLog:		return 1;	// ジョブ履歴.
		case PCGE_GetPreviewKindOverlay1:	return 0;	// オーバーレイ1.
		case PCGE_GetPreviewKindOverlay2:	return 1;	// オーバーレイ2.
		case PCGE_GetPreviewKindOverlay3:	return 2;	// オーバーレイ3.
		case PCGE_GetPreviewKindOverlay4:	return 3;	// オーバーレイ4.
		case PCGE_GetPreviewKindOverlay5:	return 4;	// オーバーレイ5.
		case PCGE_GetPreviewKindOverlay6:	return 5;	// オーバーレイ6.
		default:	break;
	}
	return 1;
}

//概要    :プレビュー画像表示位置変更
//［引数］	PCGE_PreviewImageSplitPos	e_PreviewImageSplitPos	: プレビュー画像分割表示位置
//［戻値］	Bool	:要求結果
Bool PCGC_ThumbnailPreviewControl::changeDocPreviewDispPos( PCGE_PreviewImageSplitPos e_PreviewImageSplitPos )
{
	// 画像取得済みで無い、分割画像で無い場合は無視.
	if( s_PreviewControl[1].e_ImageDataStatus != PCGE_ImageDataComplete
	    || s_PreviewControl[1].e_PreviewImageDataSize == PCGE_PreviewImageDataSizePreview1Split ) {
		return False;
	}
	// 2分割時は対象外.
	else if( s_PreviewControl[1].e_PreviewImageDataSize == PCGE_PreviewImageDataSizePreview2Split
	         && e_PreviewImageSplitPos > PCGE_PreviewImageSplitPos2 ) {
		return False;
	}
	// 4分割時は対象外.
	else if( s_PreviewControl[1].e_PreviewImageDataSize == PCGE_PreviewImageDataSizePreview4Split
	         && e_PreviewImageSplitPos > PCGE_PreviewImageSplitPos4 ) {
		return False;
	}
	// 8分割時は対象外.
	else if( s_PreviewControl[1].e_PreviewImageDataSize == PCGE_PreviewImageDataSizePreview8Split
	         && e_PreviewImageSplitPos > PCGE_PreviewImageSplitPos8 ) {
		return False;
	} else {
		s_PreviewControl[1].pc_PartsPointer->showEnableAdd( False );
		s_PreviewControl[1].e_PreviewImageSplitPos = e_PreviewImageSplitPos;
		// 画像編集処理.
		short ss_EditXSize = 0;
		short ss_EditYSize = 0;
		Bool b_Result = editPreviewImageDisp( &s_PreviewControl[1], &ss_EditXSize, &ss_EditYSize );
		if( b_Result == True ) {
			// 画像表示ヘッダー作成処理.
			createHeaderData( psc_PreviewDisplayDataBuf, s_PreviewControl[1].e_getImageTone, ss_EditXSize, ss_EditYSize );	// 2013/11/05 酒井(日立JTE) プレビュー用バッファ領域動的化対応.
			// プレビュー.
			s_PreviewControl[1].pc_PartsPointer->changeRawGraphic( ( const uchar* )psc_PreviewDisplayDataBuf );					// 2013/11/05 酒井(日立JTE) プレビュー用バッファ領域動的化対応.
			s_PreviewControl[1].pc_PartsPointer->showEnableAdd( True );
		} else {
			s_PreviewControl[1].pc_PartsPointer->showEnableAdd( False );
		}
	}
	return True;
}
//概要    :プレビュー分割表示位置取得
//［引数］
//［戻値］	PCGE_PreviewImageSplitPos 分割時の表示位置
PCGE_PreviewImageSplitPos PCGC_ThumbnailPreviewControl::getDocPreviewSplitPos()
{
	return s_PreviewControl[1].e_PreviewImageSplitPos;
}
//概要    :プレビュー分割情報取得
//［引数］
//［戻値］	PCGE_PreviewImageDataSize 分割情報
PCGE_PreviewImageDataSize PCGC_ThumbnailPreviewControl::getDocPreviewSplit()
{
	return s_PreviewControl[1].e_PreviewImageDataSize;
}
//概要    :プレビュー分割方向情報取得
//［引数］
//［戻値］	Bool 分割方向情報 True:横	False:縦
Bool PCGC_ThumbnailPreviewControl::getDocPreviewSplitdirection()
{
	return s_PreviewControl[1].b_Splitdirection;
}
// comment 2017/02/03 MSE岡田 [IT5_3.4][1013467] プレビュー分割方向情報設定関数を追加.
//概要    :プレビュー分割方向情報設定.
//［引数］　Bool 分割方向情報 True:横	False:縦.
void PCGC_ThumbnailPreviewControl::setDocPreviewSplitdirection( Bool bl_Splitdirection )
{
	s_PreviewControl[1].b_Splitdirection = bl_Splitdirection;
}
//概要    :サムネイル画像取得をキャンセル
//［引数］	uchar					uc_option			: サムネイル表示オプション
//			int32_t					sl_BoxID			: BOX番号
//			int32_t					sl_DocID			: ドキュメント番号
//			int32_t					sl_DocPageNum		: ページ番号
//			PActivatable*			pc_PartsPointer		: 取得画像表示パーツポインタ
void PCGC_ThumbnailPreviewControl::cancelThumbnailImgeData(
    uchar uc_option,
    int32_t sl_BoxID,
    int32_t sl_DocID,
    int32_t sl_DocPageNum,
    PActivatableAdd* pc_PartsPointer,
    TYPE_ImageDir e_ImageDir,
    Bool bl_Req )
{
	if( uc_option >= PCGD_ThumbnailImageMaxNum ) {
		PnlComPutDebugLog( True, UC_PNL_LOGPATTERN_1, "PCGC_ThumbnailPreviewControl::cancelThumbnailImgeData", UC_PNL_ERROR_PARAMETER );
		return;
	}
	if( ( s_ThumbnailControl[uc_option].sl_BoxID != sl_BoxID
	      || s_ThumbnailControl[uc_option].sl_DocID != sl_DocID
	      || s_ThumbnailControl[uc_option].sl_DocPageNum != sl_DocPageNum
	      || s_ThumbnailControl[uc_option].pc_PartsPointer != pc_PartsPointer
	      || s_ThumbnailControl[uc_option].e_ImageDir != e_ImageDir )
	    && s_ThumbnailControl[uc_option].e_ImageDataStatus == PCGE_ImageDataRequext ) {
		// サムネイル画像要求のキャンセル.
		APIC_ThumbnailConverter* pc_ThumbnailConverter = APIC_ThumbnailConverter::newInstance();
		PanelLog( PNLD_LogKind_Box, "req_cancel: P1[%u]", s_ThumbnailControl[uc_option].ul_reqSerialNo, 0, 0, 0, 0, 0 );
		pc_ThumbnailConverter->req_cancel( s_ThumbnailControl[uc_option].ul_reqSerialNo );
		// 画像データ取得ステータスを初期化.
		s_ThumbnailControl[uc_option].e_ImageDataStatus = PCGE_ImageDataNonComplete;
	}
	if( True == bl_Req ) {
		if( PCGE_ImageDataRequext == s_ThumbnailControl[uc_option].e_ImageDataStatus ) {
			APIC_ThumbnailConverter* pc_ThumbnailConverter = APIC_ThumbnailConverter::newInstance();
			PanelLog( PNLD_LogKind_Box, "req_cancel: P1[%u]", s_ThumbnailControl[uc_option].ul_reqSerialNo, 0, 0, 0, 0, 0 );
			pc_ThumbnailConverter->req_cancel( s_ThumbnailControl[uc_option].ul_reqSerialNo );
			s_ThumbnailControl[uc_option].e_ImageDataStatus = PCGE_ImageDataNonComplete;
		}
		if( PCGE_ImageDataDrawingEnd == s_ThumbnailControl[uc_option].e_ImageDataStatus ) {
			s_ThumbnailControl[uc_option].e_ImageDataStatus = PCGE_ImageDataNonComplete;
		}
	}
}
//概要    :プレビュー画像取得をキャンセル
//［引数］	int32_t						sl_BoxID				: BOX番号
//			int32_t						sl_DocID				: ドキュメント番号
//			int32_t						sl_DocPageNum			: ページ番号
//			PActivatable*				pc_PartsPointer			: 取得画像表示パーツポインタ
//			PCGE_PreviewImageDataSize	e_PreviewImageDataSize	: 画像サイズ.
//			TYPE_ImageDir				e_ImageDir				: 画像回転角度
void PCGC_ThumbnailPreviewControl::cancelPreviewImgeData(
    int32_t sl_BoxID,
    int32_t sl_DocID,
    int32_t sl_DocPageNum,
    PActivatable* pc_PartsPointer,
    PCGE_PreviewImageDataSize e_PreviewImageDataSize,
    TYPE_ImageDir e_ImageDir )
{
	uchar uc_option = ( e_PreviewImageDataSize == PCGE_PreviewImageDataSizeLeftErea ) ? 0: 1;
	if( ( s_PreviewControl[uc_option].sl_BoxID != sl_BoxID
	      || s_PreviewControl[uc_option].sl_DocID != sl_DocID
	      || s_PreviewControl[uc_option].sl_DocPageNum != sl_DocPageNum
	      || s_PreviewControl[uc_option].e_PreviewImageDataSize != e_PreviewImageDataSize
	      || s_PreviewControl[uc_option].e_ImageDir != e_ImageDir
	      || s_PreviewControl[uc_option].pc_PartsPointer != pc_PartsPointer )
	    && s_PreviewControl[uc_option].e_ImageDataStatus == PCGE_ImageDataRequext ) {
		// プレビュー画像要求のキャンセル.
		APIC_PreviewConverter* pc_PreviewConverter = APIC_PreviewConverter::newInstance();
		PanelLog( PNLD_LogKind_Box, "req_cancel: P1[%u]", s_PreviewControl[uc_option].ul_reqSerialNo, 0, 0, 0, 0, 0 );
		pc_PreviewConverter->req_cancel( s_PreviewControl[uc_option].ul_reqSerialNo );
		// 画像データ取得ステータスを初期化.
		s_PreviewControl[uc_option].e_ImageDataStatus = PCGE_ImageDataNonComplete;
	}
}

//概要    :プレビュー画像(スタンプ)取得をキャンセル
//［引数］	PActivatable*				pc_PartsPointer			: 取得画像表示パーツポインタ.
//			PCGE_GetPreviewKind			e_GetKind				: プレビュー画像取得種類.
//			uint32_t					sl_StampKind			: スタンプID.
//			uchar						uc_option				: サムネイル表示オプション.
//			PCGE_PreviewImageDataSize	e_PreviewImageDataSize	: 画像サイズ.
//			TYPE_ImageDir				e_ImageDir				: 画像回転角度.
//
void PCGC_ThumbnailPreviewControl::cancelStampPreviewImgeData(
    PActivatable* pc_PartsPointer,
    PCGE_GetPreviewKind e_GetKind,
    uint32_t sl_StampKind,
    uchar uc_option,
    PCGE_PreviewImageDataSize e_PreviewImageDataSize,
    TYPE_ImageDir e_ImageDir )
{
	if( ( sizeof( s_PreviewControl )/sizeof( s_PreviewControl[0] ) <= uc_option )
	    &&( PCGE_GetPreviewKindStamp == e_GetKind
	        || PCGE_GetPreviewKindWatermark == e_GetKind
	        || PCGE_GetPreviewKindOverlayDetail == e_GetKind
	        || PCGE_GetPreviewKindJobLog == e_GetKind ) ) {
		return ;
	}
	APIC_PreviewConverter* pc_PreviewConverter = APIC_PreviewConverter::newInstance();
	switch( e_GetKind ) {
		case PCGE_GetPreviewKindStamp:			// スタンプ.
			if( ( s_PreviewControl[uc_option].e_StampKind != ( TYPE_StampKind )sl_StampKind
			      || s_PreviewControl[uc_option].e_GetKind != e_GetKind
			      || s_PreviewControl[uc_option].pc_PartsPointer != pc_PartsPointer )
			    && s_PreviewControl[uc_option].e_ImageDataStatus == PCGE_ImageDataRequext ) {
				// プレビュー画像要求のキャンセル.
				PanelLog( PNLD_LogKind_Box, "req_cancel: P1[%u]", s_PreviewControl[uc_option].ul_reqSerialNo, 0, 0, 0, 0, 0 );
				pc_PreviewConverter->req_cancel( s_PreviewControl[uc_option].ul_reqSerialNo );
			}
			break;
		case PCGE_GetPreviewKindWatermark:		// ウォーターマーク.
			if( ( s_PreviewControl[uc_option].ss_WatermarkID != ( short )sl_StampKind
			      || s_PreviewControl[uc_option].e_GetKind != e_GetKind
			      || s_PreviewControl[uc_option].pc_PartsPointer != pc_PartsPointer )
			    && s_PreviewControl[uc_option].e_ImageDataStatus == PCGE_ImageDataRequext ) {
				// プレビュー画像要求のキャンセル.
				PanelLog( PNLD_LogKind_Box, "req_cancel: P1[%u]", s_PreviewControl[uc_option].ul_reqSerialNo, 0, 0, 0, 0, 0 );
				pc_PreviewConverter->req_cancel( s_PreviewControl[uc_option].ul_reqSerialNo );
			}
			break;
		case PCGE_GetPreviewKindOverlay1:		// オーバーレイ1.
		case PCGE_GetPreviewKindOverlay2:		// オーバーレイ2.
		case PCGE_GetPreviewKindOverlay3:		// オーバーレイ3.
		case PCGE_GetPreviewKindOverlay4:		// オーバーレイ4.
		case PCGE_GetPreviewKindOverlay5:		// オーバーレイ5.
		case PCGE_GetPreviewKindOverlay6:		// オーバーレイ6.
			if( ( s_ThumbnailControl[uc_option].uc_OverlayID != ( uchar )sl_StampKind
			      || s_ThumbnailControl[uc_option].e_GetKind != e_GetKind
			      || s_ThumbnailControl[uc_option].pc_PartsPointerOverlay != pc_PartsPointer )
			    && s_ThumbnailControl[uc_option].e_ImageDataStatus == PCGE_ImageDataRequext ) {
				// プレビュー画像要求のキャンセル.
				PanelLog( PNLD_LogKind_Box, "req_cancel: P1[%u]", s_ThumbnailControl[uc_option].ul_reqSerialNo, 0, 0, 0, 0, 0 );
				pc_PreviewConverter->req_cancel( s_ThumbnailControl[uc_option].ul_reqSerialNo );
			}
			break;
		case PCGE_GetPreviewKindOverlayDetail:	// オーバーレイ詳細.
			if( ( s_PreviewControl[uc_option].uc_OverlayID != ( uchar )sl_StampKind
			      || s_PreviewControl[uc_option].e_GetKind != e_GetKind
			      || s_PreviewControl[uc_option].e_PreviewImageDataSize != e_PreviewImageDataSize
			      || s_PreviewControl[uc_option].e_ImageDir != e_ImageDir
			      || s_PreviewControl[uc_option].pc_PartsPointer != pc_PartsPointer )
			    && s_PreviewControl[uc_option].e_ImageDataStatus == PCGE_ImageDataRequext ) {
				// プレビュー画像要求のキャンセル.
				PanelLog( PNLD_LogKind_Box, "req_cancel: P1[%u]", s_PreviewControl[uc_option].ul_reqSerialNo, 0, 0, 0, 0, 0 );
				pc_PreviewConverter->req_cancel( s_PreviewControl[uc_option].ul_reqSerialNo );
			}
			break;
		case PCGE_GetPreviewKindJobLog:			// ジョブ履歴.
			if( ( s_PreviewControl[uc_option].sl_JobID != ( int32_t )sl_StampKind
			      || s_PreviewControl[uc_option].e_GetKind != e_GetKind
			      || s_PreviewControl[uc_option].pc_PartsPointer != pc_PartsPointer )
			    && s_PreviewControl[uc_option].e_ImageDataStatus == PCGE_ImageDataRequext ) {
				// プレビュー画像要求のキャンセル.
				PanelLog( PNLD_LogKind_Box, "req_cancel: P1[%u]", s_PreviewControl[uc_option].ul_reqSerialNo, 0, 0, 0, 0, 0 );
				pc_PreviewConverter->req_cancel( s_PreviewControl[uc_option].ul_reqSerialNo );
			}
			break;
		default:
			break;
	}
}

//概要    :プレビュー画像データ(スタンプ共通)取得応答共通.
//［引数］	uint32_t					ul_AcceptNum			: 1画像要求毎に割り振られるシリアルナンバー.
//			TYPE_PreviewResult			e_Result				: プレビュー画像生成結果.
//			PCGS_CommonActualStampPara	s_CommonActualStampPara	: プレビュー画像パラメータ(結果).
void PCGC_ThumbnailPreviewControl::commonAnsStamp(
    uint32_t ul_AcceptNum,
    TYPE_PreviewResult e_Result,
    PCGS_CommonActualStampPara s_CommonActualStampPara )
{
	if( TYPE_PreviewResult_OK != e_Result ) {
		// プリント停止警告発生時.
		if( TYPE_PreviewResult_PrintError == e_Result ) {
			s_PreviewControl[ 1 ].e_ImageDataStatus = PCGE_ImageDataPrintStop;
			s_PreviewControl[ 1 ].e_getImageTone = s_CommonActualStampPara.e_ImageTone;
			s_PreviewControl[ 1 ].ss_getImageXSize = s_CommonActualStampPara.ss_ImageDotSizeWidth;
			s_PreviewControl[ 1 ].ss_getImageYSize = s_CommonActualStampPara.ss_ImageDotSizeHight;
			s_PreviewControl[ 1 ].b_ReqPreviewImage = True;
			// コールバックイベントを発生させる.
			pc_PanelMain->PreviewCallBackIndi( PCGE_ImageDisplayTypeStamp );
			return;
		}
		// キャンセル応答時以外.
		if( TYPE_PreviewResult_Cancel != e_Result ) {
			// リクエスト失敗時はエラーを設定し、再取得しないようにする.
			s_PreviewControl[ 1 ].e_ImageDataStatus = PCGE_ImageDataReqError;
		}
		return;
	}
	if( NULL == s_CommonActualStampPara.psc_ImageDataPointer ) {
		// 画像ポインタがNULLの場合は画像無し.
		s_PreviewControl[ 1 ].e_ImageDataStatus = PCGE_ImageDataReqError;
		return;
	}

	ushort us_ImageSize = PCGD_RightEreaPreviewDotImageSize;
// comment 2018/09/27 SCD2-4G吉田 [EagleH][制御構成変更_No.53] サムネイルサイズ対応.
	APIC_PanelSetting* pc_ThumbnailSize = APIC_PanelSetting::newInstance();
	if( NULL == pc_ThumbnailSize ) {
		return;
	}
	short ss_ThumbnailDotImageSize = pc_ThumbnailSize->getThumbnailLength();
//comment 2019/02/26 HCLT-Naveena [IT6_EagleH] Warning Removal
//	uint32_t ul_ThumbnailImageSize = ( ss_ThumbnailDotImageSize * ss_ThumbnailDotImageSize * 3 + 6 );
	if( PCGE_GetPreviewKindJobLog == s_PreviewControl[ 1 ].e_GetKind )	// ジョブ履歴.
// comment 2018/09/27 SCD2-4G吉田 [EagleH][制御構成変更_No.53] サムネイルサイズ対応.
//	{ us_ImageSize = PCGD_HistoryPreviewDotImageSize; }
	{ us_ImageSize = ss_ThumbnailDotImageSize; }
	if( ( us_ImageSize < s_CommonActualStampPara.ss_ImageDotSizeWidth )
	    || ( us_ImageSize < s_CommonActualStampPara.ss_ImageDotSizeHight )
	    || ( ( PCGD_RightEreaPreviewImageSize - 6 ) < s_CommonActualStampPara.ul_TotalDataSize ) ) {
		s_PreviewControl[ 1 ].e_ImageDataStatus = PCGE_ImageDataNonComplete;
		return;
	}
	// 画像取得データ保持.
	s_PreviewControl[ 1 ].e_ImageDataStatus = PCGE_ImageDataComplete;
	s_PreviewControl[ 1 ].e_getImageTone = s_CommonActualStampPara.e_ImageTone;
	s_PreviewControl[ 1 ].ss_getImageXSize = s_CommonActualStampPara.ss_ImageDotSizeWidth;
	s_PreviewControl[ 1 ].ss_getImageYSize = s_CommonActualStampPara.ss_ImageDotSizeHight;
	// コールバックイベントを発生させる.
	pc_PanelMain->PreviewCallBackIndi( PCGE_ImageDisplayTypeStamp );
}
//概要    :プレビュー画像データ(オーバーレイ)取得応答.
//［引数］	uint32_t					ul_AcceptNum			: 1画像要求毎に割り振られるシリアルナンバー.
//			TYPE_ThumbnailResult		e_Result				: プレビュー画像生成結果.
//			TYPS_ActualThumbnailPara	s_ActualOverlayPara		: プレビュー画像パラメータ(結果).
void PCGC_ThumbnailPreviewControl::ans_OverlayData(
    uint32_t ul_AcceptNum,
    TYPE_ThumbnailResult e_Result,
    TYPS_ActualThumbnailPara s_ActualOverlayPara )
{
	uchar uc_option = 0;

	PanelLog( PNLD_LogKind_Box, "ans_OverlayData: P1[%u] P2[%d] P3[%p]",ul_AcceptNum, e_Result, &s_ActualOverlayPara, 0, 0, 0 );
	for( uchar i = 0; PCGD_ThumbnailImageMaxNum > i; ++i ) {
		// 応答シリアルNoが管理情報と一致判定.
		if( ul_AcceptNum == s_ThumbnailControl[ i ].ul_reqSerialNo ) {
			uc_option = getNumPreviewControl( s_ThumbnailControl[ i ].e_GetKind );
			break;
		}
	}

	if( TYPE_PreviewResult_OK != e_Result ) {
		// プリント停止警告発生時.
		if( TYPE_PreviewResult_PrintError == e_Result ) {
			s_ThumbnailControl[ uc_option ].e_ImageDataStatus = PCGE_ImageDataPrintStop;
			s_ThumbnailControl[ uc_option ].e_getImageTone = s_ActualOverlayPara.e_ImageTone;
			s_ThumbnailControl[ uc_option ].ss_getImageXSize = s_ActualOverlayPara.ss_ImageDotSizeWidth;
			s_ThumbnailControl[ uc_option ].ss_getImageYSize = s_ActualOverlayPara.ss_ImageDotSizeHight;
			// コールバックイベントを発生させる.
			pc_PanelMain->PreviewCallBackIndi( ( int32_t )getNumPreviewControl( s_ThumbnailControl[ uc_option ].e_GetKind ) );
			return;
		}
		// キャンセル応答時以外.
		if( TYPE_PreviewResult_Cancel != e_Result ) {
			// リクエスト失敗時はエラーを設定し、再取得しないようにする.
			s_ThumbnailControl[ uc_option ].e_ImageDataStatus = PCGE_ImageDataReqError;

// comment 2017.03.24 SCD2-Sky稲井 [IT5_4.0][問題点No.1012244].
			if(TYPE_ThumbnailResult_Nothing == e_Result){
				//ステータスを「ドキュメント無し」にする.
				s_ThumbnailControl[ uc_option ].e_ImageDataStatus = PCGE_ImageDataNothing;
				if(PNLE_ImageAcquisitionErrorState_None == onlyPanel.getImageAcquisitionErrorState()){
					//画面で警告を出すようにする為、警告発生準備OKにする.
					onlyPanel.setImageAcquisitionErrorState( PNLE_ImageAcquisitionErrorState_ThumbnailOccurrBefore );
				}
			}
		}
		return;
	}

	if( NULL == s_ActualOverlayPara.psc_ImageDataPointer ) {
		// 画像ポインタがNULLの場合は画像無し.
		s_ThumbnailControl[ uc_option ].e_ImageDataStatus = PCGE_ImageDataReqError;
		return;
	}

	if( ( PCGD_RightEreaPreviewDotImageSize < s_ActualOverlayPara.ss_ImageDotSizeWidth )
	    || ( PCGD_RightEreaPreviewDotImageSize < s_ActualOverlayPara.ss_ImageDotSizeHight )
	    || ( ( PCGD_RightEreaPreviewImageSize - 6 ) < s_ActualOverlayPara.ul_TotalDataSize ) ) {
		s_ThumbnailControl[ uc_option ].e_ImageDataStatus = PCGE_ImageDataNonComplete;
		return;
	}

	// 画像取得データ保持.
	s_ThumbnailControl[ uc_option ].e_ImageDataStatus = PCGE_ImageDataComplete;
	s_ThumbnailControl[ uc_option ].e_getImageTone = s_ActualOverlayPara.e_ImageTone;
	s_ThumbnailControl[ uc_option ].ss_getImageXSize = s_ActualOverlayPara.ss_ImageDotSizeWidth;
	s_ThumbnailControl[ uc_option ].ss_getImageYSize = s_ActualOverlayPara.ss_ImageDotSizeHight;
	// コールバックイベントを発生させる.
	pc_PanelMain->PreviewCallBackIndi( ( int32_t )getNumPreviewControl( s_ThumbnailControl[ uc_option ].e_GetKind ) );
}
//概要    :プレビュー画像データ(ジョブ履歴)取得応答.
//［引数］	uint32_t					ul_AcceptNum			: 1画像要求毎に割り振られるシリアルナンバー.
//			TYPE_ThumbnailResult		e_Result				: プレビュー画像生成結果.
//			TYPS_ActualThumbnailPara	s_ActualThumbnailPara	: プレビュー画像パラメータ(結果).
void PCGC_ThumbnailPreviewControl::ans_JobLogData(
    uint32_t ul_AcceptNum,
    TYPE_ThumbnailResult e_Result,
    TYPS_ActualThumbnailPara s_ActualThumbnailPara )
{
	PanelLog( PNLD_LogKind_Box, "ans_JobLogData: P1[%d] P2[%d] P3[%p]", ul_AcceptNum, e_Result, &s_ActualThumbnailPara, 0, 0, 0 );

	PCGS_CommonActualStampPara s_BufCommonActualStampPara;
	s_BufCommonActualStampPara.e_ImageTone				 = s_ActualThumbnailPara.e_ImageTone;
	s_BufCommonActualStampPara.ss_ImageDotSizeWidth		 = s_ActualThumbnailPara.ss_ImageDotSizeWidth;
	s_BufCommonActualStampPara.ss_ImageTransDotSizeWidth = s_ActualThumbnailPara.ss_ImageTransDotSizeWidth;
	s_BufCommonActualStampPara.ss_ImageDotSizeHight		 = s_ActualThumbnailPara.ss_ImageDotSizeHight;
	s_BufCommonActualStampPara.psc_ImageDataPointer		 = s_ActualThumbnailPara.psc_ImageDataPointer;
	s_BufCommonActualStampPara.pImageFile				 = s_ActualThumbnailPara.pImageFile;
	s_BufCommonActualStampPara.ul_ImageDataPointerOffset = static_cast<uint32_t>( s_ActualThumbnailPara.ul_ImageDataPointerOffset );	// to 'uint32_t'  from 'uintptr_t'.
	s_BufCommonActualStampPara.ul_TotalDataSize			 = s_ActualThumbnailPara.ul_TotalDataSize;

	commonAnsStamp( ul_AcceptNum, ( TYPE_PreviewResult )e_Result, s_BufCommonActualStampPara );
}


//概要    :画像表示管理情報を初期化
//［引数］	PCGE_ImageDisplayType		e_ImageDisplayType		: 画像表示タイプ
void PCGC_ThumbnailPreviewControl::clearThumbnailPreviewControl( PCGE_ImageDisplayType e_ImageDisplayType )
{
	switch( e_ImageDisplayType ) {
		// 全て.
		case PCGE_ImageDisplayTypeAll:
			memset( s_ThumbnailControl, 0, sizeof( PCGS_ThumbnailControl ) * PCGD_ThumbnailImageMaxNum );
			memset( s_PreviewControl, 0, sizeof( PCGS_PreviewControl ) * PCGD_PreviewImageMaxNum );
			break;
		// サムネイル表示.
		case PCGE_ImageDisplayTypeThumbnail: memset( s_ThumbnailControl, 0, sizeof( PCGS_ThumbnailControl ) * PCGD_ThumbnailImageMaxNum ); break;
		// 左エリア表示.
		case PCGE_ImageDisplayTypeLeftErea: memset( s_PreviewControl, 0, sizeof( PCGS_PreviewControl ) ); break;
		case PCGE_ImageDisplayTypeDocPreview: memset( &s_PreviewControl[1], 0, sizeof( PCGS_PreviewControl ) ); break;
		case PCGE_ImageDisplayTypewRightSmall: memset( &s_PreviewControl[2], 0, sizeof( PCGS_PreviewControl ) ); break;
		// 右プレビュー(小)表示.
		case PCGE_ImageDisplayTypeStamp:
			memset( s_ThumbnailControl, 0, sizeof( PCGS_ThumbnailControl ) * PCGD_ThumbnailImageMaxNum );
			memset( s_PreviewControl, 0, sizeof( PCGS_PreviewControl ) * PCGD_PreviewImageMaxNum );
			break;
		default: PnlComPutDebugLog( True, UC_PNL_LOGPATTERN_1, "PCGC_ThumbnailPreviewControl::clearThumbnailPreviewControl", UC_PNL_ERROR_PARAMETER ); break;
	}
	s_ThumbnailControl[0].psc_ImageData = psc_ThumbnailImageDataBuf1;
	s_ThumbnailControl[1].psc_ImageData = psc_ThumbnailImageDataBuf2;
	s_ThumbnailControl[2].psc_ImageData = psc_ThumbnailImageDataBuf3;
	s_ThumbnailControl[3].psc_ImageData = psc_ThumbnailImageDataBuf4;
	s_ThumbnailControl[4].psc_ImageData = psc_ThumbnailImageDataBuf5;
	s_ThumbnailControl[5].psc_ImageData = psc_ThumbnailImageDataBuf6;
	s_ThumbnailControl[6].psc_ImageData = psc_ThumbnailImageDataBuf7;
	s_ThumbnailControl[7].psc_ImageData = psc_ThumbnailImageDataBuf8;
	s_PreviewControl[0].psc_ImageData = psc_LeftEreaPreviewImageDataBuf;
	s_PreviewControl[1].psc_ImageData = psc_PreviewImageDataBuf;
	s_PreviewControl[2].psc_ImageData = psc_RightSmallPreviewImageDataBuf;
	s_PreviewControl[0].psc_DisplayImageData = NULL;
	s_PreviewControl[1].psc_DisplayImageData = psc_PreviewDisplayDataBuf;
	s_PreviewControl[2].psc_DisplayImageData = NULL;
	s_PreviewControl[0].psc_BGImageData = psc_LeftPreviewBGDataBuf;
	s_PreviewControl[1].psc_BGImageData = psc_RightPreviewBGDataBuf;
	s_PreviewControl[2].psc_BGImageData = psc_RightPreviewSmallBGDataBuf;
	s_PreviewControl[0].b_ReqPreviewImage = False;
	s_PreviewControl[1].b_ReqPreviewImage = False;
	s_PreviewControl[2].b_ReqPreviewImage = False;
}
//概要    :サムネイル画像データ取得要求チェック
//［引数］	uchar					uc_option			: サムネイル表示オプション
//			int32_t					sl_BoxID			: BOX番号
//			int32_t					sl_DocID			: ドキュメント番号
//			int32_t					sl_DocPageNum		: ページ番号
//			PActivatable*			pc_PartsPointer		: 取得画像表示パーツポインタ
Bool PCGC_ThumbnailPreviewControl::checkReqThumbnailControl(
    uchar uc_option,
    int32_t sl_BoxID,
    int32_t sl_DocID,
    int32_t sl_DocPageNum,
    PActivatableAdd* pc_PartsPointer,
    TYPE_ImageDir e_ImageDir )
{
	if( uc_option >= PCGD_ThumbnailImageMaxNum ) {
		PnlComPutDebugLog( True, UC_PNL_LOGPATTERN_1, "PCGC_ThumbnailPreviewControl::checkReqThumbnailControl", UC_PNL_ERROR_PARAMETER );
		return False;
	}
	if( s_ThumbnailControl[uc_option].sl_BoxID == sl_BoxID
	    && s_ThumbnailControl[uc_option].sl_DocID == sl_DocID
	    && s_ThumbnailControl[uc_option].sl_DocPageNum == sl_DocPageNum
	    && s_ThumbnailControl[uc_option].pc_PartsPointer == pc_PartsPointer
	    && s_ThumbnailControl[uc_option].e_ImageDataStatus != PCGE_ImageDataNonComplete
	    && s_ThumbnailControl[uc_option].e_ImageDir == e_ImageDir ) {
		// 既に画像データ取得済み、もしくは要求中.
// comment 2017.03.24 SCD2-Sky稲井 [IT5_4.0][問題点No.1012244].
//		return False;
		//メモリリーフの取得失敗(PCGE_ImageDataNothing)であれば、再要求を投げる.
		if(PCGE_ImageDataNothing == s_ThumbnailControl[uc_option].e_ImageDataStatus){
			return True;
		}else{
			return False;
		}
	} else {
		// 画像データ取得要求必要.
		return True;
	}
}
//概要    :プレビュー画像データ取得要求チェック
//［引数］	int32_t						sl_BoxID				: BOX番号
//			int32_t						sl_DocID				: ドキュメント番号
//			int32_t						sl_DocPageNum			: ページ番号
//			PActivatable*				pc_PartsPointer			: 取得画像表示パーツポインタ
//			PCGE_PreviewImageDataSize	e_PreviewImageDataSize	: 画像サイズ.
//			PCGE_ImageDirection			e_ImageDirection		: 画像回転角度
//			Bool						bl_Check				: 画像要求するか否かのチェック（True：チェックする、False：チェックしない）.
Bool PCGC_ThumbnailPreviewControl::checkReqPreviewControl(
    int32_t sl_BoxID,
    int32_t sl_DocID,
    int32_t sl_DocPageNum,
    PActivatable* pc_PartsPointer,
    PCGE_PreviewImageDataSize e_PreviewImageDataSize,
    TYPE_ImageDir e_ImageDir,
    Bool bl_Check )
{
	uchar uc_option = ( e_PreviewImageDataSize == PCGE_PreviewImageDataSizeLeftErea ) ? 0: 1;
	if( s_PreviewControl[uc_option].sl_BoxID == sl_BoxID
	    && s_PreviewControl[uc_option].sl_DocID == sl_DocID
	    && s_PreviewControl[uc_option].sl_DocPageNum == sl_DocPageNum
	    && s_PreviewControl[uc_option].e_PreviewImageDataSize == e_PreviewImageDataSize
	    && s_PreviewControl[uc_option].e_ImageDir == e_ImageDir
	    && s_PreviewControl[uc_option].pc_PartsPointer == pc_PartsPointer
	    && s_PreviewControl[uc_option].e_ImageDataStatus != PCGE_ImageDataNonComplete
	    && True == bl_Check ) {
// comment 2017.03.24 SCD2-Sky稲井 [IT5_4.0][問題点No.1012244].
		// 既に画像データ取得済み、もしくは要求中.
//		return False;
		//メモリリーフの取得失敗(PCGE_ImageDataNothing)であれば、再要求を投げる.
		if(PCGE_ImageDataNothing == s_PreviewControl[uc_option].e_ImageDataStatus){
			return True;
		}else{
			return False;
		}
	} else {
		// プレビュー1分割表示要求時.
		if( 1 == uc_option && PCGE_PreviewImageDataSizePreview1Split == e_PreviewImageDataSize ) {
			s_PreviewControl[uc_option].b_Splitdirection = False;
		}
		// 画像データ取得要求必要.
		return True;
	}
}

//概要    :プレビュー画像データ(スタンプ)取得要求チェック
//［引数］	PActivatable*				pc_PartsPointer			: 取得画像表示パーツポインタ.
//			PCGE_GetPreviewKind			e_GetKind				: プレビュー画像取得種類.
//			uint32_t					sl_StampKind			: スタンプID.
//			uchar						uc_option				: サムネイル表示オプション.
//			PCGE_PreviewImageDataSize	e_PreviewImageDataSize	: 画像サイズ.
//			TYPE_ImageDir				e_ImageDir				: 画像回転角度.
//			Bool						bl_isGestureZoom		: check gesture zoom.
//
Bool PCGC_ThumbnailPreviewControl::checkReqStampPreviewControl(
    PActivatable* pc_PartsPointer,
    PCGE_GetPreviewKind e_GetKind,
    uint32_t sl_StampKind,
    uchar uc_option,
    PCGE_PreviewImageDataSize e_PreviewImageDataSize,
    TYPE_ImageDir e_ImageDir,
	Bool bl_isGestureZoom ) //comment 2023/02/28 FPT-DuongDV11【IT6_2.3】【OP_BTS-39930】 登録したオーバーレイのプレビュー詳細画面で、ジェスチャーで拡大実施、プレビュー詳細画面は上下に移動できなくなる.
{
	if( ( sizeof( s_PreviewControl )/sizeof( s_PreviewControl[0] ) <= uc_option )
	    &&( PCGE_GetPreviewKindStamp == e_GetKind
	        || PCGE_GetPreviewKindWatermark == e_GetKind
	        || PCGE_GetPreviewKindOverlayDetail == e_GetKind
	        || PCGE_GetPreviewKindJobLog == e_GetKind ) ) {
		return False;
	}
	switch( e_GetKind ) {
		case PCGE_GetPreviewKindStamp:			// スタンプ.
			if( ( ( TYPE_StampKind )sl_StampKind == s_PreviewControl[uc_option].e_StampKind )
			    && ( s_PreviewControl[uc_option].e_GetKind == e_GetKind )
			    && ( s_PreviewControl[uc_option].pc_PartsPointer == pc_PartsPointer )
			    && ( s_PreviewControl[uc_option].e_ImageDataStatus != PCGE_ImageDataNonComplete ) ) {
				// 既に画像データ取得済み、もしくは要求中.
				return False;
			}
			break;
		case PCGE_GetPreviewKindWatermark:		// ウォーターマーク.
			if( ( ( short )sl_StampKind == s_PreviewControl[uc_option].ss_WatermarkID )
			    && ( s_PreviewControl[uc_option].e_GetKind == e_GetKind )
			    && ( s_PreviewControl[uc_option].pc_PartsPointer == pc_PartsPointer )
			    && ( s_PreviewControl[uc_option].e_ImageDataStatus != PCGE_ImageDataNonComplete ) ) {
				// 既に画像データ取得済み、もしくは要求中.
				return False;
			}
			break;
		case PCGE_GetPreviewKindOverlay1:		// オーバーレイ1.
		case PCGE_GetPreviewKindOverlay2:		// オーバーレイ2.
		case PCGE_GetPreviewKindOverlay3:		// オーバーレイ3.
		case PCGE_GetPreviewKindOverlay4:		// オーバーレイ4.
		case PCGE_GetPreviewKindOverlay5:		// オーバーレイ5.
		case PCGE_GetPreviewKindOverlay6:		// オーバーレイ6.
			if( ( ( uchar )sl_StampKind == s_ThumbnailControl[uc_option].uc_OverlayID )
			    && ( s_ThumbnailControl[uc_option].e_GetKind == e_GetKind )
			    && ( s_ThumbnailControl[uc_option].pc_PartsPointerOverlay == pc_PartsPointer )
			    && ( s_ThumbnailControl[uc_option].e_ImageDataStatus != PCGE_ImageDataNonComplete ) ) {
// comment 2017.03.24 SCD2-Sky稲井 [IT5_4.0][問題点No.1012244].
				// 既に画像データ取得済み、もしくは要求中.
//				return False;
				//メモリリーフの取得失敗(PCGE_ImageDataNothing)であれば、再要求を投げる.
				if(PCGE_ImageDataNothing == s_ThumbnailControl[uc_option].e_ImageDataStatus){
					return True;
				}else{
					return False;
				}
			}
			break;
		case PCGE_GetPreviewKindOverlayDetail:	// オーバーレイ詳細.
//comment 2023/01/30 FPT-DuongDV11【IT6_2.3】【OP_BTS-39930】 登録したオーバーレイのプレビュー詳細画面で、ジェスチャーで拡大実施、プレビュー詳細画面は上下に移動できなくなる.
			if( ( ( uchar )sl_StampKind == s_PreviewControl[uc_option].uc_OverlayID )
			    && ( s_PreviewControl[uc_option].e_GetKind == e_GetKind )
			    && ( e_PreviewImageDataSize == s_PreviewControl[uc_option].e_PreviewImageDataSize )
				&& ( False == bl_isGestureZoom )
			    && ( e_ImageDir == s_PreviewControl[uc_option].e_ImageDir )
			    && ( s_PreviewControl[uc_option].pc_PartsPointer == pc_PartsPointer )
			    && ( s_PreviewControl[uc_option].e_ImageDataStatus != PCGE_ImageDataNonComplete ) ) {
// comment 2017.03.24 SCD2-Sky稲井 [IT5_4.0][問題点No.1012244].
				// 既に画像データ取得済み、もしくは要求中.
//				return False;
				//メモリリーフの取得失敗(PCGE_ImageDataNothing)であれば、再要求を投げる.
				if(PCGE_ImageDataNothing == s_ThumbnailControl[uc_option].e_ImageDataStatus){
					return True;
				}else{
					return False;
				}
			}
			// プレビュー1分割表示要求時.
			break;
		case PCGE_GetPreviewKindJobLog:			// ジョブ履歴.
			if( ( ( int32_t )sl_StampKind == s_PreviewControl[uc_option].sl_JobID )
			    && ( s_PreviewControl[uc_option].e_GetKind == e_GetKind )
			    && ( s_PreviewControl[uc_option].pc_PartsPointer == pc_PartsPointer )
			    && ( s_PreviewControl[uc_option].e_ImageDataStatus != PCGE_ImageDataNonComplete ) ) {
				// 既に画像データ取得済み、もしくは要求中.
				return False;
			}
			break;
		default:	break;
	}
	// 画像データ取得要求必要.
	return True;
}

//概要    :プレビュー画像サイズ取得
//［引数］	PCGE_PreviewImageDataSize	e_PreviewImageDataSize	: 画像サイズ.
//			Bool						b_Splitdirection		: 分割方向		True:横 False:縦.
//			Bool						b_SizeXOn				: XY座標		True:X座標 False:Y座標.
short PCGC_ThumbnailPreviewControl::getPreviewXYSize(
    PCGE_PreviewImageDataSize e_PreviewImageDataSize,
    Bool b_Splitdirection,
    Bool b_SizeXOn )
{
	short ss_Size = 0;
	switch( e_PreviewImageDataSize ) {
		// 左エリア.
		case PCGE_PreviewImageDataSizeLeftErea: ss_Size = PCGD_LeftEreaPreviewDotImageSize; break;
		case PCGE_PreviewImageDataSizePreview1Split: ss_Size = PCGD_PreviewDotImageSize; break;
		case PCGE_PreviewImageDataSizePreview2Split:
//comment 2018/10/17 SCD2-Sky肥後 [Sparrow][AR1049141]プレビュー画像問題.
//			if( ( False == b_Splitdirection && False == b_SizeXOn )
//			    || ( True == b_Splitdirection && True == b_SizeXOn ) ) {
//				ss_Size = PCGD_PreviewDotImageSize * 2;
//			} else {
//				ss_Size = PCGD_PreviewDotImageSize;
//			}
			ss_Size = PCGD_PreviewDotImageSize * 1.414;
			break;
		case PCGE_PreviewImageDataSizePreview4Split: ss_Size = PCGD_PreviewDotImageSize * 2; break;
		case PCGE_PreviewImageDataSizePreview8Split:
//comment 2018/10/17 SCD2-Sky肥後 [Sparrow][AR1049141]プレビュー画像問題.
//			if( ( False == b_Splitdirection && False == b_SizeXOn )
//			    || ( True == b_Splitdirection && True == b_SizeXOn ) ) {
//				ss_Size = PCGD_PreviewDotImageSize * 4;
//			} else {
//				ss_Size = PCGD_PreviewDotImageSize * 2;
//			}
			ss_Size = PCGD_PreviewDotImageSize * 2.828;
			break;
		case PCGE_PreviewImageDataSizePreviewRightSmall: ss_Size = PCGD_RightSmallPreviewDotImageSize; break;
		default: PnlComPutDebugLog( True, UC_PNL_LOGPATTERN_1, "PCGC_ThumbnailPreviewControl::getPreviewXYSize", UC_PNL_ERROR_PARAMETER ); break;
	}
	return ss_Size;
}
//概要    :画像表示ヘッダー設定
//［引数］	char*					psc_ImageData		: データ設定ポインタ
//			TYPE_ImageTone			e_ImageTone			: 画像種別
//			short					ss_ImageDotSizeX	: 画像サイズX
//			short					ss_ImageDotSizeY	: 画像サイズY
void PCGC_ThumbnailPreviewControl::createHeaderData(
    char* psc_ImageData,
    TYPE_ImageTone e_ImageTone,
    short ss_ImageDotSizeX,
    short ss_ImageDotSizeY )
{
	char sc_HeaderBuf[5];
	memset( sc_HeaderBuf, 0 , sizeof(sc_HeaderBuf) );
	// Xサイズ格納.
	sc_HeaderBuf[0] = ( char )( ss_ImageDotSizeX >> 8 );
	sc_HeaderBuf[1] = (char)( ss_ImageDotSizeX & 0xff );
	// Yサイズ格納.
	sc_HeaderBuf[2] = ( char )( ss_ImageDotSizeY >> 8 );
	sc_HeaderBuf[3] = (char)( ss_ImageDotSizeY & 0xff );
	switch( e_ImageTone ) {
		case TYPE_ImageTone1bit:	sc_HeaderBuf[4] = UC_GPARTS_COLORNUMBER_MONO;		break;	// 1ピクセル、1bit.
		case TYPE_ImageTone8bit:	sc_HeaderBuf[4] = UC_GPARTS_COLORNUMBER_256COLOR;	break;	// 1ピクセル、8bit.
		case TYPE_ImageTone24bit:	sc_HeaderBuf[4] = UC_GPARTS_COLORNUMBER_FULLCOLOR;	break;	// 1ピクセル、24bit(点順次).
		default:	PnlComPutDebugLog( True, UC_PNL_LOGPATTERN_1, "PCGC_ThumbnailPreviewControl::createHeaderData", UC_PNL_ERROR_PARAMETER );	break;
	}
	memcpy( psc_ImageData, sc_HeaderBuf, sizeof( sc_HeaderBuf ) );
}
//概要    :	画像データサイズ取得
//［引数］	TYPE_ImageTone			e_ImageTone			: 画像データ種別
//			short					ss_XSize			: Xサイズ
//			short					ss_YSize			: Yサイズ
//［戻値］	uint32_t 画像データサイズ
uint32_t PCGC_ThumbnailPreviewControl::getPreviewImageDataSize(
    TYPE_ImageTone e_ImageTone,
    short ss_XSize,
    short ss_YSize )
{
	// パラメータ負数のときは正数に変換.
	ss_XSize = (short)( ( ss_XSize < 0 ) ? -ss_XSize : ss_XSize );
	ss_YSize = (short)( ( ss_YSize < 0 ) ? -ss_YSize : ss_YSize );
	uint32_t ui32_ImageDataSize = ss_XSize * ss_YSize;
	short ss_EditXSize = 0;
	char sc_Surplus = 0;
	switch( e_ImageTone ) {
		case TYPE_ImageTone1bit:
			sc_Surplus = ( char )( ss_XSize % 8 );
			ss_EditXSize = ss_XSize / 8;
			ss_EditXSize = (short)( ss_EditXSize + ( ( sc_Surplus == 0 ) ? 0: 1 ) );
			ui32_ImageDataSize = ss_EditXSize * ss_YSize;
			break;
		case TYPE_ImageTone8bit:  break;	// そのまま.
		case TYPE_ImageTone24bit: ui32_ImageDataSize = ui32_ImageDataSize * 3; break;
		default: PnlComPutDebugLog( True, UC_PNL_LOGPATTERN_1, "PCGC_ThumbnailPreviewControl::getPreviewImageDataSize", UC_PNL_ERROR_PARAMETER ); break;
	}
	return ui32_ImageDataSize;
}
//概要    :	プレビュー再取得要求設定.
void PCGC_ThumbnailPreviewControl::setDocPreviewReacquisition()
{
	for( register short i = 0; i < PCGD_PreviewImageMaxNum; i++ ) {
		if( PCGE_ImageDataRequext == s_PreviewControl[i].e_ImageDataStatus ) {
			APIC_PreviewConverter* pc_PreviewConverter = APIC_PreviewConverter::newInstance();
			PanelLog( PNLD_LogKind_Box, "req_cancel: P1[%u]", s_PreviewControl[i].ul_reqSerialNo, 0, 0, 0, 0, 0 );
			pc_PreviewConverter->req_cancel( s_PreviewControl[i].ul_reqSerialNo );
		}
		s_PreviewControl[i].e_ImageDataStatus = PCGE_ImageDataNonComplete;;
	}
}
//概要    :	サムネイル再取得要求設定.
void PCGC_ThumbnailPreviewControl::setDocThumbnailReacquisition()
{
	for( register short i = 0; i < PCGD_ThumbnailImageMaxNum; i++ ) {
		// サムネイル画像取得要求中である場合.
		if( PCGE_ImageDataRequext == s_ThumbnailControl[i].e_ImageDataStatus ) {
			APIC_ThumbnailConverter* pc_ThumbnailConverter = APIC_ThumbnailConverter::newInstance();
			PanelLog( PNLD_LogKind_Box, "req_cancel: P1[%u]", s_ThumbnailControl[i].ul_reqSerialNo, 0, 0, 0, 0, 0 );
			pc_ThumbnailConverter->req_cancel( s_ThumbnailControl[i].ul_reqSerialNo );
		}
		// サムネイル領域に対して、イメージコンプリート状態を解除し再要求するようにする.
		s_ThumbnailControl[i].e_ImageDataStatus = PCGE_ImageDataNonComplete;
	}
}
//概要    :	プレビュー表示割り込みキャンセル.
void PCGC_ThumbnailPreviewControl::interruptCancelPreviewImgeData()
{
	if( NULL != s_PreviewControl[0].pc_PartsPointer ) {
		if( PCGE_ImageDataRequext == s_PreviewControl[0].e_ImageDataStatus ) {
			// プレビュー画像要求のキャンセル.
			APIC_PreviewConverter* pc_PreviewConverter = APIC_PreviewConverter::newInstance();
			PanelLog( PNLD_LogKind_Box, "req_cancel: P1[%u]", s_PreviewControl[0].ul_reqSerialNo, 0, 0, 0, 0, 0 );
			pc_PreviewConverter->req_cancel( s_PreviewControl[0].ul_reqSerialNo );
			s_PreviewControl[0].e_ImageDataStatus = PCGE_ImageDataNonComplete;
		} else {
			// リクエストが完了していた、もしくは、そのほかの状態の場合はそのまま.
			s_PreviewControl[0].e_ImageDataStatus = PCGE_ImageDataNonComplete;
		}
		// 画面パーツは非表示にしておく.
		s_PreviewControl[0].pc_PartsPointer->showEnableAdd( False );
	}
}
//概要    :	プレビュー表示非表示設定.
void PCGC_ThumbnailPreviewControl::PreviewDispImgeData()
{
	if( NULL != s_PreviewControl[0].pc_PartsPointer ) {
		if( PCGE_ImageDataDrawingEnd != s_PreviewControl[0].e_ImageDataStatus )
		{
			// 画面パーツは非表示にしておく.
			s_PreviewControl[0].pc_PartsPointer->showEnableAdd( False );
		} else {
			// 画面パーツは非表示にしておく.
			s_PreviewControl[0].pc_PartsPointer->showEnableAdd( True );
		}
	}
}
