void PnlComSetMagStatausIconCLCD( TYPC_Common* pc_Common, PActivatableAdd* pKey_MagStatus, PSinglePartsGraphic* pGra_MagStatusIcon )
{
	// オート倍率フラグ、倍率の種類、倍率値.
	Bool b_AmsOn = pc_Common->c_Mag.getAmsOn();
	TYPE_MagType e_MagType = pc_Common->c_Mag.getMagType();
	TYPC_Point<float> c_MagTemplate = pc_Common->c_Mag.getMag().xyReverse();
	if( b_AmsOn == True || pc_Common->c_Mag.getMinimal() ) {
		// ＡＭＳの時.
		pKey_MagStatus->showEnableAdd( pGra_MagStatusIcon, False );
	} else {
		// ＡＭＳ以外の時.
		if( ( e_MagType == TYPE_MagTypeFull )
		    || ( ( e_MagType == TYPE_MagTypeXyZoom )&&( c_MagTemplate.x == 1.000f )&&( c_MagTemplate.y == 1.000f ) )
		    || ( ( e_MagType != TYPE_MagTypeXyZoom )&&( c_MagTemplate.x == 1.000f ) ) ) {
			// 等倍.
			pKey_MagStatus->changeGraphic( pGra_MagStatusIcon, uc_ZoomIconTable[0] );
		} else if( ( ( e_MagType == TYPE_MagTypeXyZoom )&&( c_MagTemplate.x  > 1.000f )&&( c_MagTemplate.y  > 1.000f ) )
		           || ( ( e_MagType != TYPE_MagTypeXyZoom )&&( c_MagTemplate.x  > 1.000f ) ) ) {
			// 拡大.
			pKey_MagStatus->changeGraphic( pGra_MagStatusIcon, uc_ZoomIconTable[1] );
		} else if( ( ( e_MagType == TYPE_MagTypeXyZoom )&&( c_MagTemplate.x  < 1.000f )&&( c_MagTemplate.y  < 1.000f ) )
		           || ( ( e_MagType != TYPE_MagTypeXyZoom )&&( c_MagTemplate.x  < 1.000f ) ) ) {
			// 縮小.
			pKey_MagStatus->changeGraphic( pGra_MagStatusIcon, uc_ZoomIconTable[2] );
		} else if( ( ( e_MagType == TYPE_MagTypeXyZoom )&&( c_MagTemplate.x == 1.000f )&&( c_MagTemplate.y  > 1.000f ) ) ) {
			// 倍率_縦拡大_横等倍.
			pKey_MagStatus->changeGraphic( pGra_MagStatusIcon, uc_ZoomIconTable[3] );
		} else if( ( ( e_MagType == TYPE_MagTypeXyZoom )&&( c_MagTemplate.x  < 1.000f )&&( c_MagTemplate.y  > 1.000f ) ) ) {
			// 倍率_縦拡大_横縮小.
			pKey_MagStatus->changeGraphic( pGra_MagStatusIcon, uc_ZoomIconTable[4] );
		} else if( ( ( e_MagType == TYPE_MagTypeXyZoom )&&( c_MagTemplate.x  > 1.000f )&&( c_MagTemplate.y == 1.000f ) ) ) {
			// 倍率_縦等倍_横拡大.
			pKey_MagStatus->changeGraphic( pGra_MagStatusIcon, uc_ZoomIconTable[5] );
		} else if( ( ( e_MagType == TYPE_MagTypeXyZoom )&&( c_MagTemplate.x  < 1.000f )&&( c_MagTemplate.y == 1.000f ) ) ) {
			// 倍率_縦等倍_横縮小.
			pKey_MagStatus->changeGraphic( pGra_MagStatusIcon, uc_ZoomIconTable[6] );
		} else if( ( ( e_MagType == TYPE_MagTypeXyZoom )&&( c_MagTemplate.x  > 1.000f )&&( c_MagTemplate.y  < 1.000f ) ) ) {
			// 倍率_縦縮小_横拡大.
			pKey_MagStatus->changeGraphic( pGra_MagStatusIcon, uc_ZoomIconTable[7] );
		} else if( ( ( e_MagType == TYPE_MagTypeXyZoom )&&( c_MagTemplate.x == 1.000f )&&( c_MagTemplate.y  < 1.000f ) ) ) {
			// 倍率_縦縮小_横等倍.
			pKey_MagStatus->changeGraphic( pGra_MagStatusIcon, uc_ZoomIconTable[8] );
		} else { LOGF_debug_PutEventLog( LOGF_DEBUG_EVENT_KIND_ALL, 0, LOGD_DEBUG_LEVEL_UNKNOWN, "Assert Failed!" ); }	// どれにも該当しない.
		pKey_MagStatus->showEnableAdd( pGra_MagStatusIcon, True );
	}
}
