// comment 2015/10/09 OPS1 Sky溝部 [操作性改善] テンキー改善対応.
///////////////////////////////////////////////////////////////////////////////
//概要    : 倍率値１０キー入力 (小数部の数値処理).
float procMagInput10keyFloat( uchar uc_Option, char* psc_Value, Bool* pb_isError )
{
	Bool _bl_OverMaxValue = False;					// 「最大値を超えた」フラグ  True:超えた.

	// 小数第一位以下の数値を計算する.
	// 表示方法の変更により、小数を整数として計算⇒桁数分0.1をかける制御に変更した.
	int32_t i32_TempNum = 0;
	short ss_Index = 0;
	short ss_cnt = 0;
	float f_TempNum = 0.0f;

	// 倍率系の数値は小数第1位まで.
	for( ss_Index = 0; ss_Index <= 1; ss_Index++ ) {
		if( 0x00 == psc_Value[ss_Index] ) {
			sprintf( &psc_Value[ss_Index], "%d", uc_Option );
			ss_Index++;
			break;
		}
	}

	// 桁数オーバー時は最大値を超えたフラグを設定する.
	if( 0x00 != psc_Value[1] ) {
		_bl_OverMaxValue = True;
	} else {
		// 桁数オーバーしていない場合、数値に変換する.
		i32_TempNum = atoi(psc_Value);
		f_TempNum = static_cast<float>(i32_TempNum);
		for( ss_cnt = 0; ss_cnt < ss_Index; ss_cnt++ ) {
			f_TempNum *= 0.10f;
		}
	}

	// 最大値を超えた場合、引数で指定された方法に従って処理する.
	if( True == _bl_OverMaxValue ) {
		if( NULL != pb_isError ) {
			*pb_isError = True;
		}
	}

	return f_TempNum;
}

///////////////////////////////////////////////////////////////////////////////
//概要    : 倍率値１０キー入力 (整数部の数値処理).
int32_t procMagInput10keyLong( uchar uc_Option, int32_t sl_NowValue, int32_t sl_MaxValue, Bool* pb_isError )
{
	int32_t i32_returnValue = sl_NowValue;				// とりあえず戻り値は現在値とする.
	Bool _bl_OverMaxValue = False;					// 「最大値を超えた」フラグ  True:超えた.

	if( NULL != pb_isError ) {
		*pb_isError = False;						// 初期値として範囲内のデータ.
	}

	if( ((sl_NowValue * 10) + (int32_t)uc_Option) <= sl_MaxValue ) {
		// 最大値以下なら値をセット.
		i32_returnValue = sl_NowValue * 10 + (int32_t)uc_Option;
	} else {
		// 最大値を超えた！.
		_bl_OverMaxValue = True;
	}

	// 最大値を超えた場合、引数で指定された方法に従って処理する.
	if( True == _bl_OverMaxValue ) {
		if( NULL != pb_isError ) {
			*pb_isError = True;
		}
		i32_returnValue = sl_MaxValue;
	}

	return i32_returnValue;
}
///////////////////////////////////////////////////////////////////////////////
//概要    : 倍率値１０キー入力（ライトエントリー）.
float procMagInput10keyRightEntry( float sf_NowMagValue, uchar option, short* pss_MagInpDigit, const Bool b_MultiPage, Bool bl_DirectOn, Bool* pb_isError )
{
	if( 9 < option ) {
		return sf_NowMagValue;
	}
	// 途中の計算のブレを少なくするため、倍率値を１００００倍して、四捨五入して１０で割、計算して、最後に１００で割る.
	int32_t  i32_ResultMagValue;
	float sf_ResultMagValue;
	int32_t  i32_NowMagValue = ( int32_t )( ( ( sf_NowMagValue    *10000 ) + 5 ) / 10 );		// 現在値。１００００倍して整数として計算させ、１/１００の位を四捨五入後にクリアして、１０で割って切り捨てる.
	int32_t  i32_MaxMag      = ( int32_t )( ( ( DEF_MaxMagOfManual*10000 ) + 5 ) / 10 );		// 最大値。１００００倍して整数として計算させ、１/１００の位を四捨五入後にクリアして、１０で割って切り捨てる.
	if( True == bl_DirectOn ) {
		// ダイレクト入力ON時は、小数点第一位の値を入れる.
		i32_ResultMagValue = ( int32_t )( option );
	} else {
		// ダイレクト入力OFF時は、現在値を１０倍してoptionを足す（１桁目が１/１０％になるから）.
		i32_ResultMagValue = ( i32_NowMagValue * 10 ) + option;
		if( i32_MaxMag < i32_ResultMagValue ) {
			// 最大値を超えた場合は、現在値を戻り値とする.
			i32_ResultMagValue = i32_NowMagValue;
			// エラーの設定.
			if( NULL != pb_isError ) {
				*pb_isError = True;
			}
		}
	}
	// １０００で割って元に戻す.
	sf_ResultMagValue = ( float )( ( float )i32_ResultMagValue / ( float )1000.0f );
	// ライトエントリーとして表示される為、常に４桁入力済みとする.
	*pss_MagInpDigit = PCGD_MaxMagInput;
	return sf_ResultMagValue;
}
///////////////////////////////////////////////////////////////////////////////
//概要    :倍率画面の「＋／－」キー押下時の処理を行う関数.
float PnlComCalcMag( TYPC_Point<float> c_MagTemplate, Bool b_checkUpDown, short ss_DigitNum )			// 「＋／－」キー押下時の処理. ステップ判断用にss_DigitNumを追加 UV-00978 OOXMLダイレクトプリント機能対応 酒井健.
{
	float sf_ResultMagValue;		// 計算結果用変数.

	int32_t i32_MagDecimalCalc = 0;
	switch( ss_DigitNum ) {
		case PNLE_DIGITNUM_01:
			i32_MagDecimalCalc = ( int32_t )( PCGD_MagDecimalCalc * 1000 );		// 倍率値変化 0.1ステップ.
			break;
		case PNLE_DIGITNUM_1:
			i32_MagDecimalCalc = ( int32_t )( PCGD_MagDecimalCalc * 10000 );	// 倍率値変化   1ステップ.
			break;
		default:
			LOGF_debug_PutEventLog( LOGF_DEBUG_EVENT_KIND_ALL, 0, LOGD_DEBUG_LEVEL_UNKNOWN, "Assert Failed!" );
			break;
	}
	// 現在値の計算.
	// １００００倍して整数として計算させ、１/１００の位を四捨五入後にクリアして、１０で割って切り捨てる.
	int32_t i32_NowMagValue = ( int32_t )( ( ( c_MagTemplate.x *10000 ) + 5 ) / 10 );
	// 倍率値を加算させる場合(プラスキー押下時).
	if( b_checkUpDown == True ) {
		// 現在の値からの加算.
		i32_NowMagValue += i32_MagDecimalCalc;
		// 倍率値が４００％より大きい場合は、入力無効音を鳴らす.
		if( i32_NowMagValue > ( PCGD_CopyMaxMag * 1000 ) ) {
			PBasicMessageProc::setBuzzerType( PCGE_BuzzerType_InputNg );
			// 上限値に丸め込む.
			i32_NowMagValue = ( int32_t )( PCGD_CopyMaxMag * 1000 );
		}
	}
	// 倍率値を減算させる場合(マイナスキー押下時).
	else {
		// 現在の値からの減算.
		i32_NowMagValue -= i32_MagDecimalCalc;
		// 倍率値が２５．０％未満の場合は、入力無効音を鳴らす.
		if( i32_NowMagValue < ( PCGD_CopyMinMag * 1000 ) ) {
			PBasicMessageProc::setBuzzerType( PCGE_BuzzerType_InputNg );
			// 下限値に丸め込む.
			i32_NowMagValue = ( int32_t )( PCGD_CopyMinMag * 1000 );
		}
	}
	// １０００で割って値を元に戻す.
	sf_ResultMagValue = ( float )( ( float )i32_NowMagValue / ( float )1000.0f );
	return sf_ResultMagValue;
}

//================================================================================================.
//	[機能]	isShowDisableAddressManualInputDirectUSB()		直接入力：外部保存画面へ遷移処理.
//------------------------------------------------------------------------------------------------.
//	[引数]	無し.
//	[戻値]	Bool.
//================================================================================================.
Bool isShowDisableAddressManualInputDirectUSB()
{
	// 初期化.
	Bool b_Flag = False;
	APIC_UsbMemDeviceInfo* 	pc_USBMemoryInfo = APIC_UsbMemDeviceInfo::newInstance();
	APIC_SystemInfo* 		pc_SystemInfo 	= APIC_SystemInfo::newInstance();
	APIC_UsbMemSetting* 	pc_UsbMemSetting = APIC_UsbMemSetting::newInstance();

	//Comment 2017/09/04 [HCL-Swathi] [IT5 4.2][RQ-686] [WP721]Multiple Network support.
	TYPE_NetworkSpecific e_NetworkSpecific  = PNLC_NetworkLan::getInstance()->getLine();
	// Boxアプリの場合は常に表示しない.
	if( True == onlyPanel.b_nowBoxMode ) {
		return False;
	}
	if( NULL != pc_USBMemoryInfo && NULL != pc_SystemInfo && NULL != pc_UsbMemSetting ) {

		// USBメモリーが検出, USBホスト基板装着, 管理者設定/環境設定/ボックス設定/外部メモリー機能設定の「文書保存」が「ON」, ネットワーク初期化ではない, Emperor初期化ではない, USBメモリー複数検知時.
		if( ( TYPD_UsbMemStatusConnect == pc_USBMemoryInfo->getStatus() )				// USBメモリーが接続中.
		    && ( True == pc_SystemInfo->isUSBHostExist() )									// USBホスト基板装着.
//Comment 2017/09/04 [HCL-Swathi] [IT5 4.2][RQ-686] [WP721]Multiple Network support.
//		    && ( True == pc_UsbMemSetting->getEnableScanToUsb() )							// 文書保存が「ON」.
			&& ( True == pc_UsbMemSetting->getEnableScanToUsb( e_NetworkSpecific ) )							// 文書保存が「ON」.
		    && ( False == APIC_NetworkDevice::newInstance()->isNetworkInitialing() )		// ネットワーク初期化ではない.
		    && ( True == isEmperorInitTaskDone() )											// Emperor初期化ではない.
		    && ( False == pc_USBMemoryInfo->isWarning( TYPE_UsbMemWarningTwoInsert ) ) )		// USBメモリー複数検知時.
		{
			// ユーザー認証時.
			if( PnlComGetUserAccountOn() == True ) {
				//ユーザー認証時は、機能制限設定で、外部メモリが使用制限がされていないか確認.
				APIC_User* p_LoginUser = PnlComGetUser();
				if( NULL != p_LoginUser ) {
					// 機能制限設定で外部メモリが使用可能になっているか.
					if( TYPE_FuncLimit_Disable != PnlComCheckOperationAccountStatus( PNLE_ACCOUNT_STATUS_TYPE_ScanToUsb ) ) {
						b_Flag = True;
					}
				}
			} else {
				b_Flag = True;
			}
		}
	}

	// パターンカスタマイズ判定処理.
	if( False == PnlComGetFunctionShowFaxScan( TYPE_PNLMENU_FAXSCAN_DirectInput_ExternalMemory ) ) {		// MinervaSky Sky東島 UV-00743 ユーザー部門別パターン設定.
		b_Flag = False;
	}

	return b_Flag;
}
