//概要    : ユーザー認証設定_手動宛先入力設定.
void PnlComSetAddressManualInput_User( TYPS_FunctionLimitation* pLimit_set, TYPE_FunctionLimit_AddressDirect e_EnableAddressDirect )
{
	if( True == PLBC_FuncVersionCheck::isOK_Type2() ) { // Donau機能拡張2、Amur機能拡張1以降.
		pLimit_set->e_EnableAddressDirect = e_EnableAddressDirect;
	} else {
	}
}
//概要    : ユーザー認証設定_手動宛先入力設定取得.
TYPE_FunctionLimit_AddressDirect PnlComGetAddressManualInput_User( TYPS_FunctionLimitation* pLimit_set )
{
	if( True == PLBC_FuncVersionCheck::isOK_Type2() ) { // Donau機能拡張2、Amur機能拡張1以降.
		return( pLimit_set->e_EnableAddressDirect );
	} else {
		return( ( Bool )True );
	}
}
//概要    : セキュリティ詳細_手動宛先入力設定.
void PnlComSetAddressManualInput_Admin( TYPE_AddressManualInputMethod e_DisableAddressManualInput )
{
	if( True == PLBC_FuncVersionCheck::isOK_Type2() ) { // Donau機能拡張2、Amur機能拡張1以降.
		PnlComGetSystemSetting()->setAddressManualInputMethod( e_DisableAddressManualInput );
	} else {
		PnlComGetSystemSetting()->setDisableAddressManualInput( ( Bool )e_DisableAddressManualInput );
	}
}
//概要    : セキュリティ詳細_手動宛先入力設定取得.
TYPE_AddressManualInputMethod PnlComGetAddressManualInput_Admin()
{
	if( True == PLBC_FuncVersionCheck::isOK_Type2() ) { // Donau機能拡張2、Amur機能拡張1以降.
		return( PnlComGetSystemSetting()->getAddressManualInputMethod() );
	} else {
		return( ( Bool )PnlComGetSystemSetting()->getDisableAddressManualInput() );
	}
}
///////////////////////////////////////////////////////////////////////////////
//概要    : 手動宛先入力禁止判断.
//			従来、APIC_SystemSetting::getDisableAddressManualInput()で判断していたものを、本関数に変更.
//          [True/False：「禁止」/「禁止」以外].
// comment 2022/8/15 FPT.YenNTH8 [IT6_2.3][OP_BTS-38789] change function prototype.
Bool isDisableAddressManualInput( Bool bl_FunctionLimitation, Bool bl_AddressBookCheck )
{
	Bool _b_isResult = ( TYPE_AddressManualInputDisable == PnlComGetAddressManualInput_Admin() ? True : False );		// 手動宛先入力禁止機能設定.
//	// 手動宛先入力禁止機能設定が禁止以外で、ユーザー認証がＯＮの場合のみ、ユーザー毎の手動宛先入力機能制限をチェックする.
	if( True == bl_FunctionLimitation ) {
		// 手動宛先入力禁止機能設定が禁止以外で、ユーザー認証がＯＮの場合のみ、ユーザー毎の手動宛先入力機能制限をチェックする.
		if( False == _b_isResult && TYPE_UserAuthenticationOff != PnlComGetUserAuthentication()->getUserAuthentication(PNLC_NetworkLan::getInstance()->getLine()) ) {
			if( PnlComGetUser() != NULL ) {
				TYPS_FunctionLimitation st_UserFuncLimit = PnlComGetUser()->getFunctionLimitation();
				_b_isResult = ( ( TYPE_FunctionLimit_AddressDirect_Disable == PnlComGetAddressManualInput_User( &st_UserFuncLimit ) ) ? True : False );
			}
		}
	}
// comment 2017/10/06 【HCL-RamKishor】【IT5_4.2】【RQ686】【WP779】 Supporting API Restrict Access to job setting function for NW2.
	TYPE_NetworkSpecific e_NetworkSpecific = PNLC_NetworkLan::getInstance()->getLine();
	APIC_Job* pc_Job = PnlComGetJobScanFax();
	if( NULL != pc_Job ) {
		TYPC_ComSend* pc_ComSend = &( pc_Job->getJobSpec()->pc_Send->c_ComSend );
		if( NULL != pc_ComSend ) {
// comment 2017/10/06 【HCL-RamKishor】【IT5_4.2】【RQ686】【WP779】 Supporting API Restrict Access to Job Settings function for NW2.
			if( ( True == APIC_SoftDipSw::newInstance()->getSoftDipSwBitForPanelSpecNo( SCANFAXSENDADDCANCEL, 1 ) )  		// SW73(bit1)がONの場合.
//			    && ( False == PnlComGetOperationSetting()->getEnableChangeAddress() )		// 登録宛先変更が禁止.
				&& ( ( False == PnlComGetOperationSetting()->getEnableChangeAddress() ) || ( TYPE_NetworkSpecific_NW2 == e_NetworkSpecific ) )
			    && ( False == isEnableSetAddress( pc_ComSend, TYPE_SendModeFax ) ) ) {		// ファクス宛先使用不可.
				_b_isResult = True;
			}
		}
	}
// comment 2022/8/15 FPT.YenNTH8 [IT6_2.3][OP_BTS-38789].
	if( False == bl_AddressBookCheck )
	{
	if( ( False == PnlComGetFunctionShowFaxScan( TYPE_PNLMENU_FAXSCAN_DirectInput ) )		// MinervaSky Sky東島 UV-00743 ユーザー部門別パターン設定.
	    || (
	        ( False == isShowDisableAddressManualInputDirectUSB() )	// 外部メモリ.
	        && ( False == isShowDisableAddressManualInputDirectFax() )			// G3Fax.
	        && ( False == isShowDisableAddressManualInputDirectEmail() )		// E-mail.
	        && ( False == isShowDisableAddressManualInputDirectBox() )			// Box.
	        && ( False == isShowDisableAddressManualInputDirectIFax() )			// InternetFax.
	        && ( False == isShowDisableAddressManualInputDirectIPAddrFax() )	// IPAddressFax.
	        && ( False == isShowDisableAddressManualInputDirectSmb() )			// SMB.
	        && ( False == isShowDisableAddressManualInputDirectFTP() )			// FTP.
	        && ( False == isShowDisableAddressManualInputDirectWebDAV() )		// WebDAV.
	        && ( False == isShowDisableAddressManualInputDirectWebService() )	// Webサービス.
	    ) ) {	// パターンカスタマイズによる表示判定.
		_b_isResult = True;
		}
	}
	return _b_isResult;
}
///////////////////////////////////////////////////////////////////////////////
//概要    : 手動宛先入力禁止判断.
//			isDisableAddressManualInput()をプログラム宛先用にカスタマイズ.
Bool isDisableAddressManualInputProgram()
{
	Bool _b_isResult = PnlComGetSystemSetting()->getDisableAddressManualInput();		// 手動宛先入力禁止機能設定.
	// 手動宛先入力禁止機能設定が許可で、ユーザー認証がＯＮの場合のみ、ユーザー毎の手動宛先入力機能制限をチェックする.
	if( False == _b_isResult && TYPE_UserAuthenticationOff != PnlComGetUserAuthentication()->getUserAuthentication(PNLC_NetworkLan::getInstance()->getLine()) ) {
		if( PnlComGetUser() != NULL ) {
			_b_isResult = ( ( PnlComGetUser()->getFunctionLimitation().e_EnableAddressDirect != TYPE_FunctionLimit_AddressDirect_Disable ) ? False : True );
		}
	}
	if( ( False == PnlComGetFunctionShowFaxScan( TYPE_PNLMENU_FAXSCAN_DirectInput ) )		// MinervaSky Sky東島 UV-00743 ユーザー部門別パターン設定.
	    || (
	        ( False == isShowDisableAddressManualInputDirectFax() )			// G3Fax.
	        && ( False == isShowDisableAddressManualInputDirectEmail() )		// E-mail.
	        && ( False == isShowDisableAddressManualInputDirectBox() )			// Box.
	        && ( False == isShowDisableAddressManualInputDirectIFax() )			// InternetFax.
	        && ( False == isShowDisableAddressManualInputDirectIPAddrFax() )	// IPAddressFax.
	        && ( False == isShowDisableAddressManualInputDirectSmb() )			// SMB.
	        && ( False == isShowDisableAddressManualInputDirectFTP() )			// FTP.
	        && ( False == isShowDisableAddressManualInputDirectWebDAV() )		// WebDAV.
	    ) ) {	// パターンカスタマイズによる表示判定.
		_b_isResult = True;
	}
	return _b_isResult;
}
//概要    : 手動宛先入力がファクスのみ許可か判断
//          [True/False：「ファクスのみ許可」/「ファクスのみ許可」以外].
// comment 2022/8/15 FPT.YenNTH8 [IT6_2.3][OP_BTS-38789].
Bool isAddressManualInputOnlyFax( Bool bl_AddressBookCheck )
{
	Bool _b_isResult = False;	// 判定結果：「ファクスのみ許可」以外.

	TYPE_AddressManualInputMethod _e_AddressManualInputMethod = PnlComGetAddressManualInput_Admin();
	TYPE_FunctionLimit_AddressDirect _e_FunctionLimit_AddressDirect = TYPE_FunctionLimit_AddressDirect_Enable;
	if( PnlComGetUser() != NULL ) {
		TYPS_FunctionLimitation st_UserFuncLimit = PnlComGetUser()->getFunctionLimitation();
		_e_FunctionLimit_AddressDirect = PnlComGetAddressManualInput_User( &st_UserFuncLimit );
	}
// comment 2022/8/15 FPT.YenNTH8 [IT6_2.3][OP_BTS-38789].
	if( False == isDisableAddressManualInput(True, bl_AddressBookCheck) ) {	// 手動宛先入力禁止.
		if( TYPE_AddressManualInputEnableOnlyG3Fax == _e_AddressManualInputMethod || TYPE_FunctionLimit_AddressDirect_EnableOnlyG3Fax == _e_FunctionLimit_AddressDirect ) {
			_b_isResult = True;	// 判定結果：「ファクスのみ許可」.
		}
	}

	return( _b_isResult );
}
//概要    : LDAP使用可否判断
//        :表: FaxAPPではLDAPを使用不可に.
Bool isEnableLDAP( Bool bl_FunctionLimitation )
{
// Comment 2018/01/26 [HCLT_RamSurat] [IT5 4.2][AR1037868] Non-supported "LDAP search" and "LDAP compound search" in NW 2 are hidden
	if( TYPE_NetworkSpecific_NW2 == PNLC_NetworkLan::getInstance()->getLine() ) {
		return False;
	}
	Bool	ldap_setPara = False;									// サーバ設定確認
	Bool	b_enable = False;
	if( True == ExtSet.getFaxAppOn() && ScanOapExtSet.isActiveGeneralApplication() == False ) {			// FaxApp使用時はLDAP使用不可.
		return False;
	}
	for( uchar i = 0; i < 5; i++ ) {
		// LDAPサーバ登録判定
		if( isLdapServerHostEntryCheck( (uchar)( i+1 ) ) == True ) {
			ldap_setPara = True;												// サーバー登録有
		}
	}
	APIC_Job* pc_job = PnlComGetJobScanFax();
	if( NULL != pc_job ) {
		if( ( PnlComGetLdapSetting()->getOn() == True )								// LDAP機能使用可
		    && ( ldap_setPara == True )													// サーバー登録有
		    && ( APIC_NetworkDevice::newInstance()->isNetworkInitialing() == False )	// MIOがイニシャル中でない場合
// 注意：本件の対応では拡大画面は対象外としている。そのためI-Fax有効時もLDAP有効条件に含めるが、拡大時は対象外.
// 拡大表示のLDAP検索にてI-Faxも有効化したため拡大表示の条件を削除.
		    && ( ( True == isEnableSetAddress( &( pc_job->getJobSpec()->pc_Send->c_ComSend ), TYPE_SendModeEmail, False, False, False, True, -1, NULL, True, False, bl_FunctionLimitation ) )	// E-Mail使用許可.
		         || ( True == isEnableSetAddress( &( pc_job->getJobSpec()->pc_Send->c_ComSend ), TYPE_SendModeFax,   False, False, False, True, -1, NULL, True, False, bl_FunctionLimitation ) )	// G3Fax使用許可.
		         || ( ( True == isEnableSetAddress( &( pc_job->getJobSpec()->pc_Send->c_ComSend ), TYPE_SendModeIfax,  False, False, False, True, -1, NULL, True, False, bl_FunctionLimitation ) )	// I-Fax使用許可.
		              && ( False == ScanOapExtSet.isActiveGeneralApplication() ) ) ) ) {	// OAP起動時でない,
			b_enable = True;
		}
	}
	if( True == b_enable ) {
		// PKI認証かつ特殊ユーザーログイン時.
		if( ( True == PLBC_FuncPKICheck::isPKI() )
		    &&	( NULL != PnlComGetUser() )
		    && ( TYPE_UserTypeUser != PnlComGetUser()->getUserType() ) ) {
			b_enable = False;
		}
	}

	return b_enable;
}
Bool isEnableLDAP( uchar uc_Index )
{
// Comment 2018/01/26 [HCLT_RamSurat] [IT5 4.2][AR1037868] Non-supported "LDAP search" and "LDAP compound search" in NW 2 are hidden
	if( TYPE_NetworkSpecific_NW2 == PNLC_NetworkLan::getInstance()->getLine() ) {
		return False;
	}
	Bool	ldap_setPara = False;									// サーバ設定確認
	Bool	b_enable = False;
	if( True == ExtSet.getFaxAppOn() && ScanOapExtSet.isActiveGeneralApplication() == False ) {			// FaxApp使用時はLDAP使用不可.
		return False;
	}
	// サーバーインデックスが有効範囲でない場合(1～5以外).
	if( ( 0 == uc_Index ) || ( 5 < uc_Index ) ) {
		return False;
	}
	// LDAPサーバ登録判定
	if( isLdapServerHostEntryCheck( uc_Index ) == True ) {
		ldap_setPara = True;												// サーバー登録有
	}
	if( ( PnlComGetLdapSetting()->getOn() == True )								// LDAP機能使用可
	    && ( ldap_setPara == True )													// サーバー登録有
	    && ( APIC_NetworkDevice::newInstance()->isNetworkInitialing() == False )	// MIOがイニシャル中でない場合
	    && ( NULL != PnlComGetJobScanFax() )
// 注意：本件の対応では拡大画面は対象外としている。そのためI-Fax有効時もLDAP有効条件に含めるが、拡大時は対象外.
// 拡大表示のLDAP検索にてI-Faxも有効化したため拡大表示の条件を削除.
	    && ( ( True == isEnableSetAddress( &( PnlComGetJobScanFax()->getJobSpec()->pc_Send->c_ComSend ), TYPE_SendModeEmail, False, False, False, True, -1, NULL, True ) )	// E-Mail使用許可.
	         || ( True == onlyPanel.isEnableSetFaxSend( PnlComGetJobScanFax(), PNELD_MSK_ISFAXMODE_FAX1 ) )	// G3Fax使用許可.
	         || ( ( True == isEnableSetAddress( &( PnlComGetJobScanFax()->getJobSpec()->pc_Send->c_ComSend ), TYPE_SendModeIfax, False, False, False, True, -1, NULL, True ) ) // I-Fax使用許可.
	              && ( False == ScanOapExtSet.isActiveGeneralApplication() ) ) ) ) {	// OAP起動時でない,
		b_enable = True;
	}
	if( True == b_enable ) {
		// PKI認証かつ特殊ユーザーログイン時.
		if( ( True == PLBC_FuncPKICheck::isPKI() )
		    &&	( NULL != PnlComGetUser() )
		    && ( TYPE_UserTypeUser != PnlComGetUser()->getUserType() ) ) {
			b_enable = False;
		}
	}
	return b_enable;
}

void changeTabKeyPosition()
{
	uchar	cnt;
	uchar	chk;
	const Bool b_Regist = True;		// 登録宛先は常に表示される
	Bool b_Direct;
// comment 2015/03/30 MSE永野 [Helios][CQ510921] Warning除去対応.
//	Bool b_ReDial;
	Bool b_ReDial = False;
	static Bool b_LDAP;
	Bool b_FaxApp;
	Bool b_TabRewrite = False;		// タブキー再描画フラグ
	// タブキー表示状態
	PCGS_BaseTabKeyStatus s_tabStatus[PNLD_ScanFaxBasicFunctionTabMax] = {
		{PNLE_ScanFaxBasicTabAddress, True},
		{PNLE_ScanFaxBasicTabDirect, True},
		{PNLE_ScanFaxBasicTabRedial, True},
		{PNLE_ScanFaxBasicTabLdap, True}
	};
	// 非選択タブキー配置
	const PCGS_ScanFaxChangePosition	s_TubKeyPos[PNLD_ScanFaxBasicFunctionTabMax] =
	{
		{168, 62},	{296, 62},	{424, 62},	{552, 62}
	};
	// 選択タブキー配置
	const PCGS_ScanFaxChangePosition	s_SelectTubKeyPos[PNLD_ScanFaxBasicFunctionTabMax] =
	{
		{168, 64},	{296, 64},	{424, 64},	{552, 64}
	};
	// 拡大 非選択タブキー配置
	const PCGS_ScanFaxChangePosition	s_EnlTubKeyPos[PNLD_EnlScanFaxBasicFunctionTabMax] =
	{
		{8, 64},	{192, 64},	{376, 64}
	};
	// 拡大 選択タブキー配置
	const PCGS_ScanFaxChangePosition	s_EnlSelectTubKeyPos[PNLD_EnlScanFaxBasicFunctionTabMax] =
	{
		{8, 74},	{192, 74},	{376, 74}
	};
	if( False == ScanOapExtSet.isRegistGeneralApplication() &&
	    True == ExtSet.getFaxAppOn() ) {
		// RightFax(FaxAPP)モードの場合
		APIC_AppInfoSetting* pc_AppButton = APIC_AppInfoSetting::newInstance( ExtSet.getSettingAppIndexNow() );	// インスタンス取得.
		Key_FromLogUnSelect.showEnable( False );			// 履歴から選択タブの非表示.
		Key_LDAPSearchUnSelect.showEnable( False );			// LDAP検索タブの非表示.
		Key_FaxScansendSettingMenuEnd.showEnable( True );	// 終了キーの表示.
		// 基本設定タブの表示 or 非表示を判定する.
		if( NULL != pc_AppButton
		    &&  False == pc_AppButton->getAppDisplay().b_EnableExtensionSetting ) {
			Key_FaxStdTabSettingUnSelect.showEnable( False );
			b_FaxApp = False;
		} else {
			Key_FaxStdTabSettingUnSelect.showEnable( True );
			b_FaxApp = True;
		}
		// 直接入力タブの表示 or 非表示を判定する.
		if( True == isDisableAddressManualInput() ) {	// 禁止時.
			Key_DirectUnSelect.showEnable( False );
			b_Direct = False;
		} else {
			Key_DirectUnSelect.showEnable( True );
			b_Direct = True;
		}
		// 履歴タブの非表示.
		b_ReDial = False;
		// LDAPタブの非表示.
		b_LDAP = False;
		s_tabStatus[0].e_BasicTab = PNLE_ScanFaxBasicTabFaxApp;
		s_tabStatus[1].e_BasicTab = PNLE_ScanFaxBasicTabAddress;
		s_tabStatus[2].e_BasicTab = PNLE_ScanFaxBasicTabDirect;
		s_tabStatus[3].e_BasicTab = PNLE_ScanFaxBasicTabLdap;
		s_tabStatus[0].b_DispStatus = b_FaxApp;
		s_tabStatus[1].b_DispStatus = b_Regist;
		s_tabStatus[2].b_DispStatus = b_Direct;
		s_tabStatus[3].b_DispStatus = b_LDAP;
	} else {
		Key_FaxStdTabSettingUnSelect.showEnable( False );	// 基本設定タブの非表示.
		Key_FaxScansendSettingMenuEnd.showEnable( False );	// 終了キーの非表示.
		if( onlyPanel.bl_isEnlargeDisplayMode == True ) {	//拡大のとき
			// G3宛先不可判定
			if( False == onlyPanel.isEnableSetFaxSend( PnlComGetJobScanFax(), PNELD_MSK_ISFAXMODE_FAX1 )
			    || True == isDisableAddressManualInput() ) {								// 「手動入力禁止」設定.
				// 「ダイアル入力」キーを表示しない
				( ( PButton* )pt_Key_EnlScanFaxDialInput )->showEnable( False );
			} else {
				// 「ダイアル入力」キーを表示する
				( ( PButton* )pt_Key_EnlScanFaxDialInput )->showEnable( True );
			}
		}
		// 直接入力タブの表示 or 非表示を判定する
		if( isDisableAddressManualInput() == True ) {	// 禁止時.
			if( onlyPanel.bl_isEnlargeDisplayMode == False ) {
				Key_DirectUnSelect.showEnable( False );
			} else {
				( ( PButton* )pt_Key_EnlScanFaxDirectFaxOffHookUnSelect )->showEnable( False );
			}
			b_Direct = False;
		} else {
			if( onlyPanel.bl_isEnlargeDisplayMode == False ) {
				Key_DirectUnSelect.showEnable( True );
				b_Direct = True;
			} else {
				//拡大のとき無し
				b_Direct = False;
			}
		}
		if( True == APIC_SoftDipSw::newInstance()->getSoftDipSwBitForPanelSpecNo( DEFSOFTWARESW42, 6 ) ) {	// DipSWNo.42 bit6.
			Key_EnlScanFax_FromLogUnSelect.showEnable( False );
		}
		else {
			if( ( onlyPanel.isFaxFunctionUseCheck( PDPE_FaxFunctionCheckReDial ) == False ) ) { // 禁止時
				if( onlyPanel.bl_isEnlargeDisplayMode == False ) {
					// Scan(TYPE-S)アプリ起動中は、Fax基盤装着/非装着に関わらず、[履歴から選択]タブは常に表示.
					if( !ScanOapExtSet.isActiveGeneralApplication() ) {
						Key_FromLogUnSelect.showEnable( False );
					}
				} else {
					( ( PButton* )pt_Key_EnlFromLogUnSelect )->showEnable( False );
				}
				// Scan(TYPE-S)アプリ起動中は、Fax基盤装着/非装着に関わらず、[履歴から選択]タブは常に表示.
				if( ScanOapExtSet.isActiveGeneralApplication() ) {
					b_ReDial = True;
				} else {
					b_ReDial = False;
				}
			} else {
				if( onlyPanel.bl_isEnlargeDisplayMode == False ) {
					Key_FromLogUnSelect.showEnable( True );
				} else {
					( ( PButton* )pt_Key_EnlFromLogUnSelect )->showEnable( True );
				}
				b_ReDial = True;
			}
		}
		// LDAPタブの表示 or 非表示を判定する
		if( isEnableLDAP() == True ) {
			// 「LDAP検索」キーを表示する
			if( onlyPanel.bl_isEnlargeDisplayMode == False ) {
				if( ScanOapExtSet.isActiveGeneralApplication() ) {	// Externalアプリ起動中の場合.
					if( ScanOapExtSet.isEnableLdapSetting() == True ) {	// LDAP使用する場合.
						Key_LDAPSearchUnSelect.showEnable( True );
					} else {												// LDAP使用しない場合.
						Key_LDAPSearchUnSelect.showEnable( False );
					}
				} else {														// Externalアプリが起動していない場合.
					Key_LDAPSearchUnSelect.showEnable( True );
				}
			} else {
				( ( PButton* )pt_Key_EnlLDAPSearchUnSelect )->showEnable( True );
			}
			if( b_LDAP == False ) { b_TabRewrite = True; } // LDAPタブの表示/非表示状態変化で再描画フラグを立てる
			b_LDAP = True;
		} else {
			// 「LDAP検索」キーを表示しない
			if( onlyPanel.bl_isEnlargeDisplayMode == False ) {
				Key_LDAPSearchUnSelect.showEnable( False );
			} else {
				( ( PButton* )pt_Key_EnlLDAPSearchUnSelect )->showEnable( False );
// LDAPを表示しない場合は3番目にポジション移動.
				( ( PButton* )pt_Key_EnlScanFaxDirectFaxOffHookSelect )->changePosition( s_EnlSelectTubKeyPos[2].us_x, s_EnlSelectTubKeyPos[2].us_y, 0, 0 );
				( ( PButton* )pt_Key_EnlScanFaxDirectFaxOffHookUnSelect )->changePosition( s_EnlTubKeyPos[2].us_x, s_EnlTubKeyPos[2].us_y, 0, 0 );
			}
			b_LDAP = False;
		}
		// 不揮発の値を参照し、表示する初期画面を判定
		switch( PnlComGetScanFaxMainDisp() ) {
			case TYPE_FaxMainDispProg:		// LDAP検索
				s_tabStatus[0].e_BasicTab = PNLE_ScanFaxBasicTabLdap;
				s_tabStatus[1].e_BasicTab = PNLE_ScanFaxBasicTabAddress;
				s_tabStatus[2].e_BasicTab = PNLE_ScanFaxBasicTabDirect;
				s_tabStatus[3].e_BasicTab = PNLE_ScanFaxBasicTabRedial;
				s_tabStatus[0].b_DispStatus = b_LDAP;
				s_tabStatus[1].b_DispStatus = b_Regist;
				s_tabStatus[2].b_DispStatus = b_Direct;
				s_tabStatus[3].b_DispStatus = b_ReDial;
				break;
			case TYPE_FaxMainDispGroup:		// 履歴
				s_tabStatus[0].e_BasicTab = PNLE_ScanFaxBasicTabRedial;
				s_tabStatus[1].e_BasicTab = PNLE_ScanFaxBasicTabAddress;
				s_tabStatus[2].e_BasicTab = PNLE_ScanFaxBasicTabDirect;
				s_tabStatus[3].e_BasicTab = PNLE_ScanFaxBasicTabLdap;
				s_tabStatus[0].b_DispStatus = b_ReDial;
				s_tabStatus[1].b_DispStatus = b_Regist;
				s_tabStatus[2].b_DispStatus = b_Direct;
				s_tabStatus[3].b_DispStatus = b_LDAP;
				break;
			case TYPE_FaxMainDispTenKey:	// 直接入力
				s_tabStatus[0].e_BasicTab = PNLE_ScanFaxBasicTabDirect;
				s_tabStatus[1].e_BasicTab = PNLE_ScanFaxBasicTabAddress;
				s_tabStatus[2].e_BasicTab = PNLE_ScanFaxBasicTabRedial;
				s_tabStatus[3].e_BasicTab = PNLE_ScanFaxBasicTabLdap;
				s_tabStatus[0].b_DispStatus = b_Direct;
				s_tabStatus[1].b_DispStatus = b_Regist;
				s_tabStatus[2].b_DispStatus = b_ReDial;
				s_tabStatus[3].b_DispStatus = b_LDAP;
				break;
			case TYPE_FaxMainDispAbb:		// 登録宛先
			default:
				s_tabStatus[0].e_BasicTab = PNLE_ScanFaxBasicTabAddress;
				s_tabStatus[1].e_BasicTab = PNLE_ScanFaxBasicTabDirect;
				s_tabStatus[2].e_BasicTab = PNLE_ScanFaxBasicTabRedial;
				s_tabStatus[3].e_BasicTab = PNLE_ScanFaxBasicTabLdap;
				s_tabStatus[0].b_DispStatus = b_Regist;
				s_tabStatus[1].b_DispStatus = b_Direct;
				s_tabStatus[2].b_DispStatus = b_ReDial;
				s_tabStatus[3].b_DispStatus = b_LDAP;
				break;
		}
	}
	for( cnt = 0, chk = 0; cnt < PNLD_ScanFaxBasicFunctionTabMax; cnt++ ) {
		// キー表示判定
		if( s_tabStatus[cnt].b_DispStatus == True ) {
			switch( s_tabStatus[cnt].e_BasicTab ) {
				case PNLE_ScanFaxBasicTabAddress:			// 登録宛先から
					if( onlyPanel.bl_isEnlargeDisplayMode == False ) {
						if( onlyPanel.b_nowBoxMode == True ) {
							Key_FromRegAddressSelect_Box.changePosition( s_SelectTubKeyPos[chk].us_x, s_SelectTubKeyPos[chk].us_y, 0, 0 );
						} else {
							Key_FromRegAddressSelect.changePosition( s_SelectTubKeyPos[chk].us_x, s_SelectTubKeyPos[chk].us_y, 0, 0 );
						}
						Key_FromRegAddressUnSelect.changePosition( s_TubKeyPos[chk].us_x, s_TubKeyPos[chk].us_y, 0, 0 );
					} else {
						( ( PButton* )pt_Key_EnlFromRegAddressSelect )->changePosition( s_EnlSelectTubKeyPos[chk].us_x, s_EnlSelectTubKeyPos[chk].us_y, 0, 0 );
						( ( PButton* )pt_Key_EnlFromRegAddressUnSelect )->changePosition( s_EnlTubKeyPos[chk].us_x, s_EnlTubKeyPos[chk].us_y, 0, 0 );
					}
					++chk;
					break;
				case PNLE_ScanFaxBasicTabDirect:			// 直接入力
					if( onlyPanel.bl_isEnlargeDisplayMode == False ) {
						if( True == onlyPanel.b_nowBoxMode ) {
							Key_DirectSelect_Box.changePosition( s_SelectTubKeyPos[chk].us_x, s_SelectTubKeyPos[chk].us_y, 0, 0 );
						} else {
							Key_DirectSelect.changePosition( s_SelectTubKeyPos[chk].us_x, s_SelectTubKeyPos[chk].us_y, 0, 0 );
						}
						Key_DirectUnSelect.changePosition( s_TubKeyPos[chk].us_x, s_TubKeyPos[chk].us_y, 0, 0 );
						++chk;
					}
					break;
				case PNLE_ScanFaxBasicTabRedial:			// 履歴から
					if( onlyPanel.bl_isEnlargeDisplayMode == False ) {
						if( True == onlyPanel.b_nowBoxMode ) {
							Key_FromLogSelect_Box.changePosition( s_SelectTubKeyPos[chk].us_x, s_SelectTubKeyPos[chk].us_y, 0, 0 );
						} else {
							Key_FromLogSelect.changePosition( s_SelectTubKeyPos[chk].us_x, s_SelectTubKeyPos[chk].us_y, 0, 0 );
						}
						Key_FromLogUnSelect.changePosition( s_TubKeyPos[chk].us_x, s_TubKeyPos[chk].us_y, 0, 0 );
					} else {
						( ( PButton* )pt_Key_EnlFromLogSelect )->changePosition( s_EnlSelectTubKeyPos[chk].us_x, s_EnlSelectTubKeyPos[chk].us_y, 0, 0 );
						( ( PButton* )pt_Key_EnlFromLogUnSelect )->changePosition( s_EnlTubKeyPos[chk].us_x, s_EnlTubKeyPos[chk].us_y, 0, 0 );
					}
					++chk;
					break;
				case PNLE_ScanFaxBasicTabLdap:			// LDAP
					if( onlyPanel.bl_isEnlargeDisplayMode == False ) {
						if( True == onlyPanel.b_nowBoxMode ) {
							Key_LDAPSearchSelect_Box.changePosition( s_SelectTubKeyPos[chk].us_x, s_SelectTubKeyPos[chk].us_y, 0, 0 );
						} else {
							Key_LDAPSearchSelect.changePosition( s_SelectTubKeyPos[chk].us_x, s_SelectTubKeyPos[chk].us_y, 0, 0 );
						}
						Key_LDAPSearchUnSelect.changePosition( s_TubKeyPos[chk].us_x, s_TubKeyPos[chk].us_y, 0, 0 );
					} else {
						( ( PButton* )pt_Key_EnlLDAPSearchSelect )->changePosition( s_EnlSelectTubKeyPos[chk].us_x, s_EnlSelectTubKeyPos[chk].us_y, 0, 0 );
						( ( PButton* )pt_Key_EnlLDAPSearchUnSelect )->changePosition( s_EnlTubKeyPos[chk].us_x, s_EnlTubKeyPos[chk].us_y, 0, 0 );
// 拡大時はLDAPと同じ位置に直接を持ってくる.
						( ( PButton* )pt_Key_EnlScanFaxDirectFaxOffHookSelect )->changePosition( s_EnlSelectTubKeyPos[chk].us_x, s_EnlSelectTubKeyPos[chk].us_y, 0, 0 );
						( ( PButton* )pt_Key_EnlScanFaxDirectFaxOffHookUnSelect )->changePosition( s_EnlTubKeyPos[chk].us_x, s_EnlTubKeyPos[chk].us_y, 0, 0 );
					}
					++chk;
					break;
				case PNLE_ScanFaxBasicTabFaxApp:			// 基本設定
					Key_FaxStdTabSettingSelect.changePosition( s_SelectTubKeyPos[chk].us_x, s_SelectTubKeyPos[chk].us_y, 0, 0 );
					Key_FaxStdTabSettingUnSelect.changePosition( s_TubKeyPos[chk].us_x, s_TubKeyPos[chk].us_y, 0, 0 );
					++chk;
					break;
				default: break;
			}
		}
	}
	// タブ表示パーツ再描画処理
	if( b_TabRewrite == True ) { // タブ再描画フラグが立っていたら
		for( cnt = 0, chk = 0; cnt < PNLD_ScanFaxBasicFunctionTabMax; cnt++ ) {
			if( s_tabStatus[cnt].b_DispStatus == True ) { // キー表示あり
				switch( s_tabStatus[cnt].e_BasicTab ) {
					case PNLE_ScanFaxBasicTabAddress:			// 登録宛先から
						if( onlyPanel.bl_isEnlargeDisplayMode == False ) {
							if( onlyPanel.b_nowBoxMode == True ) {
								Key_FromRegAddressSelect_Box.showEnable( False );
								Key_FromRegAddressSelect_Box.showEnable( True );
							} else {
								Key_FromRegAddressSelect.showEnable( False );
								Key_FromRegAddressSelect.showEnable( True );
							}
							Key_FromRegAddressUnSelect.showEnable( False );
							Key_FromRegAddressUnSelect.showEnable( True );
						} else {
							( ( PButton* )pt_Key_EnlFromRegAddressSelect )->showEnable( False );
							( ( PButton* )pt_Key_EnlFromRegAddressUnSelect )->showEnable( False );
							( ( PButton* )pt_Key_EnlFromRegAddressSelect )->showEnable( True );
							( ( PButton* )pt_Key_EnlFromRegAddressUnSelect )->showEnable( True );
						}
						++chk;
						break;
					case PNLE_ScanFaxBasicTabDirect:			// 直接入力
						if( onlyPanel.bl_isEnlargeDisplayMode == False ) {
							if( True == onlyPanel.b_nowBoxMode ) {
								Key_DirectSelect_Box.showEnable( False );
								Key_DirectSelect_Box.showEnable( True );
							} else {
								Key_DirectSelect.showEnable( False );
								Key_DirectSelect.showEnable( True );
							}
							Key_DirectUnSelect.showEnable( False );

							Key_DirectUnSelect.showEnable( True );
							++chk;
						}
						break;
					case PNLE_ScanFaxBasicTabRedial:			// 履歴から
						if( onlyPanel.bl_isEnlargeDisplayMode == False ) {
							if( True == onlyPanel.b_nowBoxMode ) {
								Key_FromLogSelect_Box.showEnable( False );
								Key_FromLogSelect_Box.showEnable( True );
							} else {
								Key_FromLogSelect.showEnable( False );
								Key_FromLogSelect.showEnable( True );
							}
							Key_FromLogUnSelect.showEnable( False );
							Key_FromLogUnSelect.showEnable( True );
						} else {
							( ( PButton* )pt_Key_EnlFromLogSelect )->showEnable( False );
							( ( PButton* )pt_Key_EnlFromLogUnSelect )->showEnable( False );
							( ( PButton* )pt_Key_EnlFromLogSelect )->showEnable( True );
							( ( PButton* )pt_Key_EnlFromLogUnSelect )->showEnable( True );
						}
						++chk;
						break;
					case PNLE_ScanFaxBasicTabLdap:			// LDAP
						if( onlyPanel.bl_isEnlargeDisplayMode == False ) {
							if( True == onlyPanel.b_nowBoxMode ) {
								Key_LDAPSearchSelect_Box.showEnable( False );
								Key_LDAPSearchSelect_Box.showEnable( True );
							} else {
								Key_LDAPSearchSelect.showEnable( False );
								Key_LDAPSearchSelect.showEnable( True );
							}
							Key_LDAPSearchUnSelect.showEnable( False );
							Key_LDAPSearchUnSelect.showEnable( True );
						} else {
							( ( PButton* )pt_Key_EnlLDAPSearchSelect )->showEnable( False );
							( ( PButton* )pt_Key_EnlLDAPSearchUnSelect )->showEnable( False );
							( ( PButton* )pt_Key_EnlLDAPSearchSelect )->showEnable( True );
							( ( PButton* )pt_Key_EnlLDAPSearchUnSelect )->showEnable( True );
							// 拡大時はLDAPと同じ位置に直接を持ってくる.
							( ( PButton* )pt_Key_EnlScanFaxDirectFaxOffHookSelect )->showEnable( False );
							( ( PButton* )pt_Key_EnlScanFaxDirectFaxOffHookUnSelect )->showEnable( False );
							( ( PButton* )pt_Key_EnlScanFaxDirectFaxOffHookSelect )->showEnable( True );
							( ( PButton* )pt_Key_EnlScanFaxDirectFaxOffHookUnSelect )->showEnable( True );
						}
						++chk;
						break;
					case PNLE_ScanFaxBasicTabFaxApp:			// 基本設定
						Key_FaxStdTabSettingSelect.showEnable( False );
						Key_FaxStdTabSettingUnSelect.showEnable( False );
						Key_FaxStdTabSettingSelect.showEnable( True );
						Key_FaxStdTabSettingUnSelect.showEnable( True );
						++chk;
						break;
					default: break;
				}
			}
		}
	}
	if( NULL != PnlComGetJobScanFax()
	    &&  True == PnlComGetJobScanFax()->getJobSpec()->pc_Send->c_MailSend.getSmimeEnableCrypt() ) {
		Key_ScanFaxDirectEmailIcon.activate( False );		// E-Mailアイコンキー
	}
}


