//概要　　：MySpoolがアプリ登録されているか.
Bool isMySpoolRegistration()
{
	for( uchar i = 1; i <= TYPD_MyServerMaxApplication; i++ ) {
		if( NULL == APIC_MyServerSetting::newInstance( i ) ) {
			return False;
		}
		TYPS_MyServerRegistration st_MyServerRegistration = APIC_MyServerSetting::newInstance( i )->getApplication();
		if( ( TYPE_RegistrationTypeOn == st_MyServerRegistration.e_Registration )		// アプリ登録済.
		    && ( TYPE_MyServerTypeMySpool == st_MyServerRegistration.e_MyServerType )	) {	// アプリ種別がMySpool.
			return True;
		}
	}
	return False;
}
