//			(認証&プリント、bizmic PS Liteの機能を利用できる様にするモードも兼用).
Bool isAdminMachineDirectLogin()
{
	if( TYPE_KeyModeAdminMachineKM == APIC_KeyDevice::getKeyMode() ) {
		APIC_MachineSetting* pc_MachineSetting = PnlComGetMachineSetting();
		if( NULL == pc_MachineSetting ) {
			return False;
		}
		if( TYPE_AuthDeviceType2Mode2AuthEnable == pc_MachineSetting->getEnableAuthDeviceType2Mode2Auth() ) {
			return True;
		}
	}
	return False;
}

//================================================================================================
//概要    :選択言語が中韓台かどうか判定関数.
//================================================================================================
Bool isLanguageChinaKoriaTaiwan( void )
{
	TYPE_Language ec_Language = PnlComGetLanguage();
	if( ( ec_Language == TYPE_LanguageChinese1 ) ||				// 台湾語.
	    ( ec_Language == TYPE_LanguageChinese2 ) ||				// 中国語.
	    ( ec_Language == TYPE_LanguageHangul ) ) {				// 韓国語.
		return True;
	} else {
		return False;
	}
}
//概要	:回線別発信元名設定有効判定.
TYPE_IndividualSenderLine isEachLineSenderNameSet()
{
	APIC_FaxJobSetting* pc_FaxJobSetting = PnlComGetFaxJobSetting();
	TYPE_IndividualSenderLine e_SenderLine = TYPE_IndividualSenderLineOff;
	if( ( NULL == pc_FaxJobSetting ) || ( NULL == ppc_SystemInfo ) ) {	LOGF_debug_PutEventLog( LOGF_DEBUG_EVENT_KIND_ALL, 0, LOGD_DEBUG_LEVEL_UNKNOWN, "Assert Failed!" );	return e_SenderLine;}
	Bool bl_ExistMultiLine = False;		// 複数回線接続されているか?.
	APIC_SystemInfo* pc_SystemInfo = PnlComGetSystemInfo();
	if( True == PnlComGetSystemInfo()->getFax1Exist()
	    && True == PnlComGetSystemInfo()->getFax2Exist() ) {
		bl_ExistMultiLine = True;
	}
	if( True == PLBC_FuncVersionCheck::isOK_MiZe_Type2() ) {	// Mi/Ze機能拡張2以降の場合.
		static const TYPE_FaxLineUse e_CommLineTbl[]= {TYPE_CommLine1,TYPE_CommLine2,TYPE_CommLine3,TYPE_CommLine4};
		uchar uc_LineCnt = 0;		// 総回線数.
		for( uchar i = 0; i < ( sizeof( e_CommLineTbl )/ sizeof( TYPE_CommLine ) ); i++ ) {
			if( True == pc_SystemInfo->getFaxExistAll( e_CommLineTbl[i] ) ) {	// 指定回線が存在していた場合.
				uc_LineCnt++;
			}
		}
		if( 2 <= uc_LineCnt ) {	// 2回線以上装着していたら.
			bl_ExistMultiLine = True;
		}
	}
	if( True == bl_ExistMultiLine ) {
		e_SenderLine = pc_FaxJobSetting->getIndividualSenderLineOn();
	}
	return e_SenderLine;
}
