//概要    :検索完了通知コールバック.
void PNLC_AddressSearch::notifyAddressSearchResult(
    short* s_SearchArea, 			// 番号取得領域.
    ushort us_TotalCount ) 			// 取得合計件数.
{
	b_checkNotity = True;
	// 全体合計数を設定.
	us_Total = us_TotalCount;
	// オプション情報で必要な情報のみに絞り込み.
	if( PNLD_SearchFilterDefault != s_AddressSearchConditionOption.c_regSearchFilter ) {
		// 各種フィルタ処理.
		switch( s_AddressSearchConditionOption.c_regSearchFilter ) {
			case PNLD_SearchFilterReg_RefPerGroup:		us_Total = referGroupAddressFilter(); break;	// 参照グループ内宛先フィルタ.
			case PNLD_SearchFilterReg_ColorProvAddr:	us_Total = colorProvUserAddressFilter();		// カラー禁止ユーザー参照可能宛先フィルタ.
		}
	}
	ss_nowPage = 1;
	ss_maxPage = (short)( us_Total / ss_addressListSize );
	if( 0 != ( us_Total % ss_addressListSize ) ) { ++ss_maxPage; } // 余分が0以外なら１ページ加える.
	// コールバックメッセージ送信.
	CallBackIndi( TYPE_PNL_CallBack_serchComplate );
}
//概要    :参照グループ内宛先検索フィルタ.
short PNLC_AddressSearch::referGroupAddressFilter()
{
	// 該当件数.
	register short ss_HitCount = 0;
	register short i = 0;
	// 短縮、グループ、プログラムでそれぞれ該当する宛先のみにフィルタリングする.
	switch( s_AddressSearchCondition.e_SearchDivision ) {
		case TYPE_AddressSearchDivisionShort:
			for( i = 0; i < us_Total; i++ ) {
				APIC_ShorteningAddress* pc_Shortening = NULL;
				if( -1 != ss_ResultArea[i] ) {
					pc_Shortening = APIC_ShorteningAddress::newInstance( ss_ResultArea[i] );
// comment 2019/11/21 【HCLT_Monisha】Kloc work Changes ID: [NPD.FUNC.MUST] Added NULL check condition.
					if ( NULL != pc_Shortening ) {
						if( True == pc_Shortening->getReferLicenceGroup()
					    	&& s_AddressSearchConditionOption.ss_regGroupNumber == pc_Shortening->getReferLicenceGroupID() ) {
							// 該当する宛先だった.
							ss_ResultArea[ss_HitCount] = ss_ResultArea[i];
							++ss_HitCount;
						}
					}
				}
			}
			break;
		case TYPE_AddressSearchDivisionGroup:
			for( i = 0; i < us_Total; i++ ) {
				APIC_GroupAddress* pc_GroupAddress = NULL;
				if( -1 != ss_ResultArea[i] ) {
					pc_GroupAddress = APIC_GroupAddress::newInstance( ss_ResultArea[i] );
// comment 2016/05/04 【HCLT-Ashok.D】【CQ529019】Null check activity.
					if ( NULL != pc_GroupAddress ) {
						if( True == pc_GroupAddress->getReferLicenceGroup()
						    && s_AddressSearchConditionOption.ss_regGroupNumber == pc_GroupAddress->getReferLicenceGroupID() ) {
							// 該当する宛先だった.
							ss_ResultArea[ss_HitCount] = ss_ResultArea[i];
							++ss_HitCount;
						}
					}
				}
			}
			break;
		case TYPE_AddressSearchDivisionKey:
			for( i = 0; i < us_Total; i++ ) {
				APIC_ProgramKey* pc_ProgramKey = NULL;
				if( -1 != ss_ResultArea[i] ) {
// comment 2019/11/21 【HCLT_Monisha】Kloc work Changes ID: [NPD.FUNC.MUST] Added NULL check condition.
					if ( NULL != pc_ProgramKey ) {
						pc_ProgramKey = APIC_ProgramKey::newInstance( ss_ResultArea[i] );
						if( True == pc_ProgramKey->getReferLicenceGroup()
						    && s_AddressSearchConditionOption.ss_regGroupNumber == pc_ProgramKey->getReferLicenceGroupID() ) {
							// 該当する宛先だった.
							ss_ResultArea[ss_HitCount] = ss_ResultArea[i];
							++ss_HitCount;
						}
					}
				}
			}
			break;
		case TYPE_AddressSearchDivisionTemp:
		default:  break;	// 一時配信は使用されないので、処理しない.
	}
	// 残りは-1で初期化する
	for( i = ss_HitCount; i < us_Total; i++ ) {
		ss_ResultArea[i] = -1;
	}
	return ss_HitCount;
}
//概要    :指定短縮アドレスがカラー送信禁止ユーザーで使用可能かどうか判定する.
//戻り値  :使用可能/ True , 使用不可能/ False.
Bool CheckColorProvUserUseAddressShort( APIC_ShorteningAddress* cp_addrIn )
{
	// 初期値使用可能.
	Bool b_Ret = True;
	if( NULL != cp_addrIn ) {
		TYPE_SendMode e_SendMode = cp_addrIn->getSendMode();
		// チェック対象はIP
		if( TYPE_SendModeIPAddressFax == e_SendMode ) {
			if( True == cp_addrIn->getColorMachine() ) {
				// 1件でもカラー機宛先が存在していれば使用できない.
				b_Ret = False;
			}
		} else if( TYPE_SendModeEmail     == e_SendMode
		           // 【課題】USBメモリの判定はいるのか？.
		           || TYPE_SendModeFtp    == e_SendMode
		           || TYPE_SendModeSmb    == e_SendMode
		           || TYPE_SendModeWebDav == e_SendMode ) {
			// 使用不可能な宛先.
			b_Ret = False;
		}
	} else {
		b_Ret = False;
	}
	return b_Ret;
}
//概要    :指定アドレスがカラー送信禁止ユーザーで使用可能かどうか判定する.
//戻り値  :使用可能/ True , 使用不可能/ False.
Bool CheckColorProvUserUseAddress( APIC_GroupAddress* cp_addrIn )
{
	if( NULL != cp_addrIn ) {
		const ushort us_MaxShorteningAddress = APIC_ShorteningAddress::getMaxShorteningAddress();
		APIC_ShorteningAddress* pc_ShorteningAddress = NULL;
		// １個づつグループに登録されている短縮Noを検索する.
		for( ushort i = 1; i <= us_MaxShorteningAddress; i++ ) {
			// グループに短縮登録あり
			if( True == cp_addrIn->getShorteningAddress( i ) ) {
				pc_ShorteningAddress = APIC_ShorteningAddress::newInstance( i );
				if( False == CheckColorProvUserUseAddressShort( pc_ShorteningAddress ) ) {
					// 使用不可能宛先が登録されていた.
					return False;
				}
			}
		}
		// 上記以外は使用可能.
		return True;
	}
	return False;
}
Bool CheckColorProvUserUseAddress( APIC_ShorteningAddress* cp_addrIn )
{
	if( NULL != cp_addrIn ) {
		// 短縮宛先のチェック
		return CheckColorProvUserUseAddressShort( cp_addrIn );
	}
	return False;
}
//概要    :カラー宛先が含まれているアドレスをフィルタリングする（モノクロ宛先のみで構成されるグループが有効になる）.
//戻り値  :フィルタ後の合計件数.
short PNLC_AddressSearch::colorProvUserAddressFilter()
{
	// 該当件数.
	register short ss_HitCount = 0;
	register short i = 0;
	// 短縮、グループ、プログラムでそれぞれ該当する宛先のみにフィルタリングする.
	switch( s_AddressSearchCondition.e_SearchDivision ) {
		case TYPE_AddressSearchDivisionShort:
			// ファクス検索の場合にカラー機の領域が-1にて含まれる為、ここでフィルタしておく.
			for( i = 0; i < us_Total; i++ ) {
				APIC_ShorteningAddress* pc_ShorteningAddress = NULL;
				if( -1 != ss_ResultArea[i] ) {
					pc_ShorteningAddress = APIC_ShorteningAddress::newInstance( ss_ResultArea[i] );
					// 登録宛先内にカラー禁止ユーザーが使用可能な宛先が存在するかどうかチェックする
					if( NULL != pc_ShorteningAddress && True == CheckColorProvUserUseAddress( pc_ShorteningAddress ) ) {
						// カラー禁止ユーザーが使用可能な宛先であった.
						ss_ResultArea[ss_HitCount] = ss_ResultArea[i];
						++ss_HitCount;
					}
				}
			}
			break;
		case TYPE_AddressSearchDivisionGroup:
			for( i = 0; i < us_Total; i++ ) {
				APIC_GroupAddress* pc_GroupAddress = NULL;
				if( -1 != ss_ResultArea[i] ) {
					pc_GroupAddress = APIC_GroupAddress::newInstance( ss_ResultArea[i] );
					// 登録宛先内にカラー禁止ユーザーが使用可能な宛先が存在するかどうかチェックする
					if( NULL != pc_GroupAddress && True == CheckColorProvUserUseAddress( pc_GroupAddress ) ) {
						// カラー禁止ユーザーが使用可能な宛先であった.
						ss_ResultArea[ss_HitCount] = ss_ResultArea[i];
						++ss_HitCount;
					}
				}
			}
			break;
		case TYPE_AddressSearchDivisionKey:
	case TYPE_AddressSearchDivisionTemp: default: break;
	}
	// 残りは-1で初期化する
	for( i = ss_HitCount; i < us_Total; i++ ) {
		ss_ResultArea[i] = -1;
	}
	return ss_HitCount;
}
//概要    :検索結果ID取得.
void PNLC_AddressSearch::getSearchResultID( LIBC_List<short>& lst )
{
	short* pss_index;
	lst.Lock();
	// リストを空にする
	while( 0 < lst.getCount() ) { lst.del( lst.findFirst() ); }
	c_SearchList.Lock();
	pss_index = c_SearchList.findFirst();
	if( ( pss_index != NULL ) && ( *pss_index > 0 ) ) {
		lst.add( pss_index );
	}
	for( short i=1; i < c_SearchList.getCount(); i++ ) {
		pss_index = c_SearchList.findNext();
		if( ( pss_index != NULL ) && ( *pss_index > 0 ) ) {
			lst.add( pss_index );
		}
	}
	c_SearchList.UnLock();
	lst.UnLock();
}
//概要    :DBイニシャル状態取得.
Bool getDBInitializeStatus()
{
	Bool bl_DBReady = False;
	// DBのイニシャル状態判定
	if( True == NVDF_isInitializeDatabase() ) {
		APIC_HddInfo* pc_HddInfo = APIC_HddInfo::newInstance();
		if( NULL == pc_HddInfo ) {
			LOGF_debug_PutEventLog( LOGF_DEBUG_EVENT_KIND_ALL, 0, LOGD_DEBUG_LEVEL_UNKNOWN, "Assert Failed!" );
			return bl_DBReady;				// 静的解析 2012/09/03 第一OPS 酒井(健).
		}
		if( True == pc_HddInfo->getHddExist() ) {
			// HDD有りの場合、Docの初期化状態を判定
			if( True == APIC_BoxRegistry::GetAccessStatus() ) {
				bl_DBReady = True;
			}
		} else {
			bl_DBReady = True;
		}
	}
	return bl_DBReady;
}
// ===============================================================================================
//	概要    カラーを表す文字列の取得.
//	戻り値  ：TEXT_ID.
// ===============================================================================================
TEXT_ID PnlComGetColorStr( const TYPE_MonoColor e_MonoColor, Bool b_2Line )
{
	// カラー判定.
	TEXT_ID puc_ColorStr = s_MonoColorRed;
	// コピー基本画面、設定内容画面の場合（カラー種類表示が2行になるもの）.
	if( b_2Line == True ) {
		for( uchar i = 0; uc_SizeMonoColorModeTbl > i; ++i ) {
			if( e_MonoColor == s_MonoColorMode2LineTbl[ i ].e_MonoColorCode ) {
				// カラー文字列を戻り値とする.
				puc_ColorStr = s_MonoColorMode2LineTbl[ i ].puc_parts;
				break;
			}
		}
	}
	// 詳細確認画面の場合（カラー種類表示が1行になるもの）.
	else {
		for( uchar i = 0; uc_SizeMonoColorModeTbl > i; ++i ) {
			if( e_MonoColor == s_MonoColorModeTbl[ i ].e_MonoColorCode ) {
				// カラー文字列を戻り値とする.
				puc_ColorStr = s_MonoColorModeTbl[ i ].puc_parts;
				break;
			}
		}
	}
	return puc_ColorStr;
}
