// ===============================================================================================
//	概要    ：リストプリントの可能サイズ種類チェック.
//	戻り値  ：True：可能、False：不可.
// ===============================================================================================
Bool isListPrintEnableSizeKind( TYPC_PaperSize c_PaperSize, TYPC_PaperType c_PaperType, Bool b_isDuplexOn, Bool b_Service )
{
	Bool b_Enable = False;
	Bool b_SizeCheck = False;
	Bool b_KindCheck = False;
	// サービスモード時.
	if( b_Service == True ) {
		TYPE_SystemType e_SystemType = PnlComGetMachineSetting()->getSystemType();		// 現在の仕向け.
		// サイズチェック.
		if( ( e_SystemType == TYPE_SystemType_US && c_PaperSize.e_SizeCode == TYPE_SizeCodeLetterSef	)				// ＭＣ仕向		: ＬｅｔｔｅｒＴ.
		    || ( e_SystemType != TYPE_SystemType_US && c_PaperSize.e_SizeCode == TYPE_SizeCodeA4Sef ) ) {			// ＭＣ仕向以外	: Ａ４Ｔ.
			b_SizeCheck = True;
		}
		// 種類チェック.
		Bool b_Custom = ( TYPE_CustomPaperType_UnSelect == c_PaperType.getCustomPaperType() ) ? False : True;
		Bool b_Normal = ( TYPE_PaperTypeNormal == c_PaperType.getPaperType() && False == b_Custom ) ? True : False;
		Bool b_Single = ( TYPE_PaperTypeNotDuplex1 == c_PaperType.getPaperType() && False == b_Custom ) ? True : False;
		if( ( True == b_Normal )			// 普通紙.
		    || ( ( b_isDuplexOn == False )
		         && ( c_PaperType.getFeed2ndSidedPaper() == False )
		         && ( True == b_Single ) ) )		// 片面で両面不可紙.
		{
			b_KindCheck = True;
		}
	} else {
		// サービス以外.
		// サイズチェック.
		if( c_PaperSize.b_WideOn == False										// ワイド紙でない.
		    && ( c_PaperSize.e_SizeCode == TYPE_SizeCodeA3Sef									// Ａ３Ｔ.
		         || c_PaperSize.e_SizeCode == TYPE_SizeCodeB4Sef									// Ｂ４Ｔ.
		         || c_PaperSize.e_SizeCode == TYPE_SizeCodeA4Sef									// Ａ４Ｔ.
		         || c_PaperSize.e_SizeCode == TYPE_SizeCodeA4Lef									// Ａ４Ｙ.
		         || c_PaperSize.e_SizeCode == TYPE_SizeCodeLedgerSef								// １１　×　１７Ｔ.
		         || c_PaperSize.e_SizeCode == TYPE_SizeCodeLegalSef								// ８・１/２　×　１４Ｔ.
		         || c_PaperSize.e_SizeCode == TYPE_SizeCodeLetterSef								// ＬｅｔｔｅｒＴ.
		         || c_PaperSize.e_SizeCode == TYPE_SizeCodeLetterLef								// ＬｅｔｔｅｒＹ.
		         || c_PaperSize.e_SizeCode == TYPE_SizeCode8KSef									// ８ＫＴ.
		         || c_PaperSize.e_SizeCode == TYPE_SizeCode16KSef								// １６ＫＴ.
		         || c_PaperSize.e_SizeCode == TYPE_SizeCode16KLef ) ) {							// １６ＫＹ.
			b_SizeCheck = True;
		}
		// 種類チェック.
		Bool b_Custom = ( TYPE_CustomPaperType_UnSelect == c_PaperType.getCustomPaperType() ) ? False : True;
		Bool b_Normal = ( TYPE_PaperTypeNormal == c_PaperType.getPaperType() && False == b_Custom ) ? True : False;
		Bool b_Single = ( TYPE_PaperTypeNotDuplex1 == c_PaperType.getPaperType() && False == b_Custom ) ? True : False;
		if( ( b_isDuplexOn == False && c_PaperType.getFeed2ndSidedPaper() == False && ( True == b_Normal || True == b_Single ) )		// 片面選択時は普通紙と両面不可紙.
		    || ( b_isDuplexOn == True  && c_PaperType.getFeed2ndSidedPaper() == False &&   True == b_Normal ) ) {	// 両面選択時は普通紙のみ.
			b_KindCheck = True;
		}
	}
	// サイズ種類可能であればTrueを返す.
	if( b_SizeCheck == True && b_KindCheck == True ) {
		b_Enable = True;
	}
	return b_Enable;
}
// ===============================================================================================
//	概要      ：オーバーレイ登録日表示関数.
// ===============================================================================================
void PnlComSetOverLayRegistDay( PActivatable* p_Btx_OverLayRegistDay,
                                uchar uc_Index )
{
	// 仕向け設定取得.
	TYPE_SystemType e_SystemType = PnlComGetMachineSetting()->getSystemType();
	// 登録日表示用変数.
	char sc_RegistrationDay[JBLD_DAYDISP_MAX + 2];
	memset( sc_RegistrationDay, 0, sizeof( sc_RegistrationDay ) );
	// オーバーレイ情報取得.
	TYPC_Overlay c_Overlay;
	if( False != PLBC_FuncVersionCheck::isOK_Type3() ) {				// Donau拡張機能3、Amur機能拡張2以降.
		PnlComGetOperationSetting()->getOverlay( uc_Index, &c_Overlay, True );
	} else {
		PnlComGetOperationSetting()->getOverlay( uc_Index, &c_Overlay );
	}
	// 画像登録日の取得.
	APIC_Doc* pc_Doc = cp_OneDoc;
	APIC_DocInfo pc_DocInfo;

	pc_Doc->setDocId( c_Overlay.sl_DocID );
// Commment 2017/09/22 HCL_Venkataramesh [IT5_4.2][RQ-686][WP689] setBoxId support for Network2 user.
//	pc_Doc->setBoxId( DOCD_OverLayBox );
	PNLC_NetworkLan::getInstance()->setBoxIdPNL( pc_Doc, DOCD_OverLayBox );
	int32_t i32_ret = APID_DocapiMethodOk;
	i32_ret = pc_Doc->getDocInfo( APID_DocapiNull, NULL, &pc_DocInfo, LIBE_CharSetDefault );
	if( APID_DocapiMethodOk != i32_ret ) {
		LOGF_debug_PutEventLog( LOGF_DEBUG_EVENT_KIND_ALL, 0, LOGD_DEBUG_LEVEL_UNKNOWN, "PnlComSetOverLayRegistDay getDocInfo NG" );
	} else {
		TYPC_Time c_Time = pc_DocInfo.t_DocTime;
		if( ( c_Time.ss_Year >= 1990 ) && ( c_Time.ss_Year <= 2089 )
		    && ( c_Time.sc_Month >= 1 ) && ( c_Time.sc_Month <= 12 )
		    && ( c_Time.sc_Day >= 1 ) && ( c_Time.sc_Day <= 31 ) ) {
			// 仕向けにより表示文字列を変更する.
			switch( e_SystemType ) {
				case TYPE_SystemType_US: snprintf( sc_RegistrationDay, sizeof( sc_RegistrationDay ), "%02d/%02d/%04d", c_Time.sc_Month, c_Time.sc_Day, c_Time.ss_Year );	break;	// ＵＳ仕向け.
				case TYPE_SystemType_JP: snprintf( sc_RegistrationDay, sizeof( sc_RegistrationDay ),"%04d/%02d/%02d", c_Time.ss_Year, c_Time.sc_Month, c_Time.sc_Day );	break;	// ＪＰ仕向け.
				case TYPE_SystemType_EU: snprintf( sc_RegistrationDay, sizeof( sc_RegistrationDay ),"%02d/%02d/%04d", c_Time.sc_Day, c_Time.sc_Month, c_Time.ss_Year );	break;	// ＥＵ仕向け.
				default:	break;
			}
		}
	}
	p_Btx_OverLayRegistDay->changeTextString( ( uchar* )sc_RegistrationDay );
}
// ===============================================================================================
//	概要      ：原稿サイズが確定しているか.
//	戻り値    ：Bool：True :原稿サイズが確定している.
//	          ：	：False:原稿サイズが確定していない.
// ===============================================================================================
Bool PnlComOriginalSizeFixed()
{
	Bool b_Result = False;
	if( ( comPanelJob->isPlatenOriginalSizeFixed() == True && ppc_Original->getPlatenOriginalSize().e_SizeCode != TYPE_SizeCodeUnknown )		// 原稿台原稿サイズ有効になった場合.
	    || ( comPanelJob->isADFOriginalSizeFixed() == True && ppc_Original->getAdfOriginalSize().e_SizeCode != TYPE_SizeCodeUnknown ) ) {			// ADF原稿サイズ有効になった場合.
		b_Result = True;
	}
	return b_Result;
}
// ===============================================================================================
//	概要      ：自動で原稿サイズ確定した時、確定した原稿開き方向を取得する.
//	戻り値    ：原稿開き方向.
// ===============================================================================================
TYPE_BindDirection PnlComBindDirectionOriginal( TYPC_Common* const pc_Common,
        TYPC_Scan* const pc_Scan )
{
	TYPC_PaperSize ct_DocSize;			// 原稿サイズ
	if( comPanelJob->getJobSpec()->pc_Scan->c_OriginalSize.getAutoSize() == False
	    && comPanelJob->getJobSpec()->pc_Scan->c_OriginalSize.getPaperSize().e_SizeCode != TYPE_SizeCodeUnknown ) {	// 原稿サイズマニュアル時は、パネル原稿サイズ採用.
		ct_DocSize = comPanelJob->getJobSpec()->pc_Scan->c_OriginalSize.getPaperSize();			// 原稿サイズマニュアル時は、パネル原稿サイズ採用
	} else if( comPanelJob->isADFOriginalSizeFixed() == True && ppc_Original->getAdfOriginalSize().e_SizeCode != TYPE_SizeCodeUnknown ) {
		// ADF原稿検出.
		ct_DocSize = ppc_Original->getAdfOriginalSize();									// 原稿サイズオート時は、ＩＲ検出原稿サイズ採用
	} else {
		ct_DocSize = ppc_Original->getPlatenOriginalSize();									// 原稿サイズオート時は、ＩＲ検出原稿サイズ採用
	}
	if( NULL == comPanelJob->getAutoSelect() ) {
		LOGF_debug_PutEventLog( LOGF_DEBUG_EVENT_KIND_ALL, 0, LOGD_DEBUG_LEVEL_UNKNOWN, "Assert Failed!" );
		return TYPE_BindDirectionAuto;
	}
	return ( comPanelJob->getAutoSelect()->decideBindDirection( pc_Scan->c_BindDirection.getBindDirection(), ct_DocSize, pc_Common->c_Orientation ) );
}
// ===============================================================================================
//	概要      ：自動で原稿サイズ確定した時、確定したコピー開き方向を取得する.
//	戻り値    ：コピー開き方向.
// ===============================================================================================
TYPE_BindDirection PnlComBindDirectionCopy()
{
	if( NULL == comPanelJob->getAutoSelect() ) {
		LOGF_debug_PutEventLog( LOGF_DEBUG_EVENT_KIND_ALL, 0, LOGD_DEBUG_LEVEL_UNKNOWN, "Assert Failed!" );
		return TYPE_BindDirectionAuto;
	}
	return ( comPanelJob->getAutoSelect()->getBindDir() );
}
//================================================================================================
//クラス  ：TYPC_BroadcastAddress : 同報宛先管理クラス
//概要    ：短縮宛先の設定・解除
//================================================================================================
void TYPC_BroadcastAddress::setShorteningAddressDigitalID( uint32_t ul_setRecodeId, const Bool b_On, const short ss_DigitalID )
{
	// 同報宛先件数を取得.
	const ushort us_AddressCount = s_MmbBroadcastList.getNodeSize();
	ushort i = 1;
	for( i = 1; us_AddressCount >= i; ++i ) {
		// 選択されている宛先を順次取得.
		TYPS_AddressInfo s_AddressInfo;
		memset( &s_AddressInfo, 0x00, sizeof( s_AddressInfo ) );
		s_MmbBroadcastList.getNode( s_AddressInfo, i );
		// 指定した宛先と同一のものがある場合(バッファに保存したレコードIDで判断).
		if( ( ul_setRecodeId == s_AddressInfo.ul_LeftRecodeId ) && ( False == s_AddressInfo.b_Direct ) ) {
			break;
		}
	}
	// 解除指定で指定した宛先が選択されている場合.
	if( ( False == b_On ) && ( us_AddressCount >= i ) ) {
		TYPS_AddressInfo s_AddressInfo;
		memset( &s_AddressInfo, 0x00, sizeof( s_AddressInfo ) );
		s_MmbBroadcastList.getNode( s_AddressInfo, i );
		APIC_SmimeCertInfo* pc_SmimeCertInfo = APIC_SmimeCertInfo::newInstance();
		pc_SmimeCertInfo->DeleteSmimeCertInfo( s_AddressInfo.ss_DigitalID );
		// 宛先登録情報を操作ログとして残す(宛先解除).
		PNLC_OperationLog::newInstance()->setLogAddressInfo( &s_AddressInfo, OPLE_SubInfoAdrRelease );
		// 最終選択同報宛先の削除.
		delLastSelectAddress( &s_AddressInfo );
		PNLC_BroadcastPadControlLib::newInstance()->deleteBroadcastList( (ushort)( i - 1 ) );
		// 指定した宛先を同報宛先リストから削除.
		s_MmbBroadcastList.deleteNode( i );
		bl_MmbAddressCount = False;	// カウンター更新フラグ.
		if( us_MmbSelectAddress == i ) {
			// 同報宛先非選択とする.
			us_MmbSelectAddress = TYPD_NotSelectBroadcastAddress;
		}
		if(	( TYPD_BroadcastAddressEffectiveStart != us_MmbEffectivePosition )
		    && ( us_MmbEffectivePosition > s_MmbBroadcastList.getNodeSize() ) ) {
			us_MmbEffectivePosition = (ushort)( us_MmbEffectivePosition - us_MmbEffectiveRange );
		}
	} else if( ( True == b_On ) && ( us_AddressCount < i ) ) {
		// 選択指定で指定した宛先が選択されていない場合.
		// 指定した宛先を同報宛先リストに追加.
		TYPS_AddressInfo s_AddressInfo;								// 同報宛先リスト.
		memset( &s_AddressInfo, 0x00, sizeof( s_AddressInfo ) );
		s_AddressInfo.b_Direct = False;								// 短縮宛先.
		s_AddressInfo.ul_LeftRecodeId = ul_setRecodeId;				// レコードID.
		// デジタルIDセット.
		s_AddressInfo.ss_DigitalID = ss_DigitalID;
		s_AddressInfo.b_Select = False;
// comment 2015/09/14 OPS1-Sky後藤 [MinervaSBK][CQ518343] UD評価指摘対応.
		s_AddressInfo.bl_Regist = False;
		if( PNLD_PKICARDRECORDNO != ul_setRecodeId ) {		// PKIカード証明書IDのレコード以外の場合.
			APIC_ShorteningAddress* pc_ShorteningAddress = APIC_ShorteningAddress::newInstance( (short)ul_setRecodeId );
			if( NULL != pc_ShorteningAddress ) {
				s_AddressInfo.e_SendMode = pc_ShorteningAddress->getSendMode();
			}
		}
		bl_MmbAddressCount = False;	// カウンター更新フラグ.
		s_MmbBroadcastList.addNode( s_AddressInfo );				// s_MmbBroadcastListへ保存.
		PNLC_BroadcastPadControlLib::newInstance()->addBroadcastList( s_AddressInfo );
		// 最終選択同報宛先の設定.
		setLastSelectAddress( &s_AddressInfo );
		// 宛先登録情報を操作ログとして残す(宛先選択).
		PNLC_OperationLog::newInstance()->setLogAddressInfo( &s_AddressInfo, OPLE_SubInfoAdrSelect );
	}
}
// ===============================================================================================
//	概要      ：デジタルID選択情報 .
//	戻り値    ：取得結果（ True:成功 False:失敗 ）.
// ===============================================================================================
Bool TYPC_DigitalIDAddress::getAddress( TYPS_DigitalIDAddressInfo* ps_addrInfo, uint32_t ul_AddressNo )
{
	// 宛先件数を取得.
	const ushort us_AddressCount = s_MmbDigitalIDList.getNodeSize();
	for( ushort i = 1; us_AddressCount >= i; ++i ) {
		// 選択されている宛先を順次取得.
		TYPS_DigitalIDAddressInfo s_AddressInfo;
		memset( &s_AddressInfo, 0x00, sizeof( s_AddressInfo ) );
		s_MmbDigitalIDList.getNode( s_AddressInfo, i );
		// 指定した宛先と同一のものがある場合.
		if( ul_AddressNo == s_AddressInfo.ul_AddressNo ) {
			memcpy( ps_addrInfo, &s_AddressInfo, sizeof( TYPS_DigitalIDAddressInfo ) );
			return True;
		}
	}
	ps_addrInfo = NULL;			// 一致する宛先がなかった為、クリア.
	return False;
}
// ===============================================================================================
//	概要      ：デジタルID選択情報 .
//	戻り値    ：登録結果（ True:成功 False:失敗 ）.
// ===============================================================================================
Bool TYPC_DigitalIDAddress::setAddress( char* sc_AddressName, char* sc_MailToAddress, uint32_t ul_AddressNo )
{
	TYPS_DigitalIDAddressInfo s_DigitalIDAddressInfo;
	memset( &s_DigitalIDAddressInfo, 0x00, sizeof( s_DigitalIDAddressInfo ) );
	memcpy( s_DigitalIDAddressInfo.sc_Name, sc_AddressName, TYPD_MaxStrAddressName );
	memcpy( s_DigitalIDAddressInfo.sc_Address, sc_MailToAddress, TYPD_MaxMailAddress );
	s_DigitalIDAddressInfo.e_SendMode = TYPE_SendModeEmail;
	s_DigitalIDAddressInfo.ul_AddressNo = ul_AddressNo;
	return setAddress( &s_DigitalIDAddressInfo );
}
// ===============================================================================================
//	概要      ：デジタルID選択情報 .
//	戻り値    ：登録結果（ True:成功 False:失敗 ）.
// ===============================================================================================
Bool TYPC_DigitalIDAddress::setAddress( TYPS_DigitalIDAddressInfo* ps_addrInfo )
{
	if( ps_addrInfo == NULL ) {	// 引数のデジタルIDアドレス情報が空の場合.
		return False;
	}
	// 宛先件数を取得.
	const ushort us_AddressCount = s_MmbDigitalIDList.getNodeSize();
	for( ushort i = 1; us_AddressCount >= i; ++i ) {
		// 選択されている宛先を順次取得.
		TYPS_DigitalIDAddressInfo s_AddressInfo;
		memset( &s_AddressInfo,0x00,sizeof( s_AddressInfo ) );
		s_MmbDigitalIDList.getNode( s_AddressInfo, i );
		// 指定した宛先と同一のものがある場合.
		if( ps_addrInfo->ul_AddressNo == s_AddressInfo.ul_AddressNo ) {
			return False;
		}
	}
	s_MmbDigitalIDList.addNode( *ps_addrInfo );
	return True;
}
// ===============================================================================================
//	概要      ：デジタルID選択情報 .
//	戻り値    ：削除結果（ True:成功 False:失敗 ）.
// ===============================================================================================
Bool TYPC_DigitalIDAddress::removeAddress( TYPS_DigitalIDAddressInfo* ps_addrInfo )
{
	if( ps_addrInfo == NULL ) {	// 引数のデジタルIDアドレス情報が空の場合.
		return False;
	}
	return removeAddress( ps_addrInfo->ul_AddressNo );
}
// ===============================================================================================
//	概要      ：デジタルID選択情報 .
//	戻り値    ：削除結果（ True:成功 False:失敗 ）.
// ===============================================================================================
Bool TYPC_DigitalIDAddress::removeAddress( uint32_t ul_AddressNo )
{
	// 宛先件数を取得.
	const ushort us_AddressCount = s_MmbDigitalIDList.getNodeSize();
	for( ushort i = 1; us_AddressCount >= i; ++i ) {
		// 選択されている宛先を順次取得.
		TYPS_DigitalIDAddressInfo s_AddressInfo;
		memset( &s_AddressInfo, 0x00, sizeof( s_AddressInfo ) );
		s_MmbDigitalIDList.getNode( s_AddressInfo, i );
		// 指定した宛先と同一のものがある場合.
		if( ul_AddressNo == s_AddressInfo.ul_AddressNo ) {
			s_MmbDigitalIDList.deleteNode( i );
			return True;
		}
	}
	return False;
}
// ===============================================================================================
