//概要    :ASCIIコードの文字列であるかのチェック
Bool isASCIIString( const char* psc_String, const uint32_t ul_Size )
{
	for( uint32_t i = 0; ul_Size > i; ++i ) {
		if( EndOfString == psc_String[i] ) {
			break;
		}
		if( 0x7F < ( uchar )psc_String[i] ) {
			return False;
		}
	}
	return True;
}
//================================================================================================
// 概要		:現在の時間をあらわすint32_t値を取得.
// 戻り値	:int32_t(西暦2000年以降の現在までの秒数).
//================================================================================================
uint32_t PnlGetSecondsPassedSinceMillennium( void )
{
	// 西暦2000年からの経過秒を取得↓.
	TYPC_Time _ct_NowTime = PnlComGetSystemSetting()->getSystemTime();				// 現在時刻の取得.
	uint32_t ui32_NowTime = 0;
	for( short _ss_Year = 2000; _ss_Year < _ct_NowTime.ss_Year; _ss_Year ++ ) {
		if( _ss_Year % 4 == 0 && ( _ss_Year % 100 != 0 || _ss_Year % 400 == 0 ) ) {
			ui32_NowTime += 366 * 24 * 60 * 60;		// 年＞秒(閏年).
		} else {
			ui32_NowTime += 365 * 24 * 60 * 60;		// 年＞秒(平年).
		}
	}
	for( char _sc_Month = 1; _sc_Month < _ct_NowTime.sc_Month; _sc_Month++ ) {
		switch( _sc_Month ) {
			case 2:
				if( _ct_NowTime.ss_Year % 4 == 0 && ( _ct_NowTime.ss_Year % 100 != 0 || _ct_NowTime.ss_Year % 400 == 0 ) ) {
					ui32_NowTime += 29 * 24 * 60 * 60;		// 月＞秒(閏年).
				} else {
					ui32_NowTime += 28 * 24 * 60 * 60;		// 月＞秒(平年).
				}
				break;
			case 4:
			case 6:
			case 9:
			case 11: ui32_NowTime += 30 * 24 * 60 * 60; break;	// 月＞秒.
			default: ui32_NowTime += 31 * 24 * 60 * 60; break;	// 月＞秒.
		}
	}
	ui32_NowTime += _ct_NowTime.sc_Day * 24 * 60 * 60;	// 日＞秒.
	ui32_NowTime += _ct_NowTime.sc_Hour * 60 * 60;		// 時＞秒.
	ui32_NowTime += _ct_NowTime.sc_Minute * 60;			// 分＞秒.
	ui32_NowTime += _ct_NowTime.sc_Second;				// 秒.
	// 西暦2000年からの経過秒を取得↑.
	return ui32_NowTime;
}
//================================================================================================
// 概要		:ScanFax 同時印刷キーの表示・非表示判定.
// 戻り値	:uchar  =0:表示 =1:非表示 =2:グレイアウト表示(=0:使用可 !=0:使用不可).
//================================================================================================
uchar	isShowSendWithPrint( APIC_Job* pc_Job,  Bool bl_FunctionLimitation )  // 引数でAPIC_Jobを渡す No.332093 2010/8/25 柳川.

{

	if( NULL == pc_Job ) {
		pc_Job = PnlComGetJobScanFax();
	}

	uchar	uc_RetInfo = PCGD_SendWithPrintShow;
	// ライフ系警告発生時同時プリントキー非表示
	// とりあえず、これだけ (追加の警告が発生する可能性あり).
	// sp_GamenWarningTableより、bl_enableNextJobSet(次ジョブ予約可能か？ True:可能) が
	// Trueのものを（コピー予約可能なものを除いて）チェックする.

	if( onlyPanel.isWarningOn( pc_Job,  PERROR_UsedTonerBottleFull ) == True 		// 廃トナーフル
	    ||	onlyPanel.isWarningOn( pc_Job,  PERROR_CTonerEmptyStop ) == True 			// シアン色トナーエンプティストップ
	    ||	onlyPanel.isWarningOn( pc_Job,  PERROR_MTonerEmptyStop ) == True 			// マゼンタ色トナーエンプティストップ
	    ||	onlyPanel.isWarningOn( pc_Job,  PERROR_YTonerEmptyStop ) == True 			// イエロー色トナーエンプティストップ
	    ||	onlyPanel.isWarningOn( pc_Job,  PERROR_KTonerEmptyStop ) == True 			// ブラック色トナーエンプティストップ
	    ||	onlyPanel.isWarningOn( pc_Job,  PERROR_PrinterJam ) == True 					// プリンタジャム検出
	    ||	onlyPanel.isWarningOn( pc_Job,  PERROR_ADFJam ) == True 						// ＡＤＦジャム検出
	    ||	onlyPanel.isWarningOn( pc_Job,  PERROR_RemovePaperOnFinisherTray ) == True ) {	// 処理トレイ用紙取り忘れ

		return PCGD_SendWithPrintHide;	// 非表示.
	}
	// 同時プリント非表示(装置装着判定)
#ifdef IT2
	APIC_KeyDevice*	pc_KeyDevice = APIC_KeyDevice::newInstance();
	TYPE_KeyMode e_KeyMode = pc_KeyDevice->getKeyMode();				//	キーモード.
#else
	TYPE_KeyMode e_KeyMode = APIC_KeyDevice::getKeyMode();				//	キーモード.
#endif
	switch( e_KeyMode ) {
		case TYPE_KeyModeKeyCounter:		// キーカウンタ
		case TYPE_KeyModeAdminMachine:		// 管理装置（従来タイプ）
		case TYPE_KeyModeVendor:			// ベンダー（従来タイプ）
		case TYPE_KeyModeAdminMachineKM:	// 管理装置（統合タイプ）
		case TYPE_KeyModeVendorKM:			// ベンダー（統合タイプ）
		case TYPE_KeyModePageAcses:			// ページアクセス
			return PCGD_SendWithPrintHide;	// 非表示.
			break;
		default: break;
	}
	// 強制コピーガード/強制パスワードコピー/コピープロテクト付加時は同時印刷不可.
	if( ( True == PnlComGetOperationSetting()->getForcedPrintInPrinting( TYPE_ForcedPrintKind_CopyGuard )	)		// 強制コピーガード印字の時.
	    ||( True == PnlComGetOperationSetting()->getForcedPrintInPrinting( TYPE_ForcedPrintKind_Jimon )	)		// コピープロテクト印字の時
	    ||( True == PnlComGetOperationSetting()->getForcedPrintInPrinting( TYPE_ForcedPrintKind_PasswordCopy )	) ) {	// 強制パスワードコピーの時.
		return PCGD_SendWithPrintHide;		// 非表示.
	}
	// コピーキットカウンタの状態取得.

	APIC_Job*	pJob = pc_Job;

	Bool bl_copyKitColor = False;
	Bool bl_copyKitBlack = False;
	Bool bl_copyKitTotal = False;
	if( pJob != NULL ) {
#ifndef DEF_MonoCus
		bl_copyKitColor = pJob->isLimitOverCopyKit( ERROR_CopyKitColorLimit_S, True );		// コピーキットカラー上限値オーバー(設定時)
#endif //DEF_MonoCus.

		bl_copyKitBlack = pJob->isLimitOverCopyKit( ERROR_CopyKitBlackLimit_S, True );		// コピーキットブラック上限値オーバー(設定時)
		bl_copyKitTotal = pJob->isLimitOverCopyKit( ERROR_CopyKitTotalLimit_S, True );		// コピーキットカラー・ブラック上限値オーバー(設定時)
	}
	Bool			b_blackprint	= True;
	Bool			b_colorprint	= True;
	TYPE_FuncLimit	funcLimit;

	funcLimit = PnlComCheckOperationAccountStatus( PNLE_ACCOUNT_STATUS_TYPE_PrintOfSendDocument );

	if( False == bl_FunctionLimitation ) {
		if( TYPE_FuncLimit_Enable != funcLimit ) {
			funcLimit = TYPE_FuncLimit_Enable;
		}
	}

	if( TYPE_FuncLimit_Disable == funcLimit ) {
		b_blackprint = False;
		b_colorprint = False;
	} else if( TYPE_FuncLimit_OnlyBlack == funcLimit ) {
		b_blackprint = True;
		b_colorprint = False;
	} else {
		b_blackprint = True;
		b_colorprint = True;
	}
	// ボックスモード判定
	if( onlyPanel.b_nowBoxMode == False ) {
		if( ( False == b_blackprint ) && ( False == b_colorprint ) ) {
			return PCGD_SendWithPrintHide;	// 非表示.
		}
		if( ( bl_copyKitColor == True && bl_copyKitBlack == True ) || bl_copyKitTotal == True ) {
			return PCGD_SendWithPrintHide;	// 非表示.
		}
// Comment 2020/05/14【HCLT-Madhavi】【HeliosMLK】【OP_BTS-23535】Retaining the Save and Print settings.
//		APIC_Job* pc_ScanFaxJob = PnlComGetJobScanFax();
//		if( NULL == pc_ScanFaxJob ) {
		if( NULL == pc_Job ) {
			return PCGD_SendWithPrintHide; //エラー処理の為非表示
		}
//		TYPE_PNL_COLOR	e_Color = PnlComGetPnlColor( pc_ScanFaxJob->getJobSpec()->pc_Common, pc_ScanFaxJob->getJobSpec()->pc_Scan ) ;
		TYPE_PNL_COLOR	e_Color = PnlComGetPnlColor( pc_Job->getJobSpec()->pc_Common, pc_Job->getJobSpec()->pc_Scan ) ;
		switch( e_Color ) {
			case TYPE_PNL_COLOR_AUTO :											// 自動
				// 自動の場合は、カラー印刷orブラック印刷のどちらかが禁止であればグレイアウトにする.
				if( b_colorprint == False || b_blackprint == False || bl_copyKitColor == True || bl_copyKitBlack == True ) {
					uc_RetInfo = PCGD_SendWithPrintGrayOut;
				}
				break ;
			case TYPE_PNL_COLOR_FULLCOLOR :										// フルカラー
				if( b_colorprint == False || bl_copyKitColor == True ) {	// カラー印刷禁止
					uc_RetInfo = PCGD_SendWithPrintGrayOut;
				}
				break ;
			case TYPE_PNL_COLOR_GRAY :											// グレースケール
			case TYPE_PNL_COLOR_BIN :											// 白黒２値
				if( b_blackprint == False || bl_copyKitBlack == True ) {	// ブラック印刷禁止
					uc_RetInfo = PCGD_SendWithPrintGrayOut;
				}
				break ;
			default : LOGF_debug_PutEventLog( LOGF_DEBUG_EVENT_KIND_ALL, 0, LOGD_DEBUG_LEVEL_UNKNOWN, "Assert Failed!" ) ; break ;
		}


	} else {
		// ボックス固有の判定処理をここに記述してください.
		if( gp_DocPrintFaceCom.getBoxSendGamenProp() & BOXE_BoxSendGamenProp_HideCurPrint					// 設定状態により、同時印刷キー非表示.
		    ||( TYPE_FuncLimit_Disable == funcLimit ) ) {							// 又は送信文書印字「許可しない」ユーザ.

			// 非表示.
			return PCGD_SendWithPrintHide;
		} else if( gp_DocPrintFaceCom.getBoxSendGamenProp() & BOXE_BoxSendGamenProp_GrayOutCurPrint ) {
			// グレイアウト.
			return PCGD_SendWithPrintGrayOut;
		}
	}
	return uc_RetInfo;
}
// ===============================================================================================
//	概要    ：PIトレイのエンプティチェック.
//	戻り値  ：True：エンプティ、False：エンプティでない.
// ===============================================================================================
Bool PnlComIsPIEmpty( APIC_Job* pc_Job )
{
	Bool bl_Empty = False;
	TYPC_Print* pc_Print = pc_Job->getJobSpec()->pc_Print;
	APIC_PrinterSystem* pc_PrinterSystem = PnlComGetPrinterSystem();
	APIC_SystemStatus* pc_SystemStatus = APIC_SystemStatus::newInstance();
	APIC_FeedTray* pc_FeedTray = PnlComGetFeedTray();
	if( pc_PrinterSystem->isCoverSheetFeeder() == True																	// カバーシートフィーダー装着.
	    && pc_SystemStatus->getTemporaryRescueUserStatus( TYPE_TemporaryRescueUnitPI ) != TYPE_TemporaryRescueStatusSet ) {	// カバーシートフィーダー暫定救済中でない.
		// PIトレイのエンプティ判定.
		// カバーシートのオモテ・ウラ表紙の取得.
		TYPC_IntersheetMode c_CoversheetFront = pc_Print->c_Intersheet.getFrontMode();
		TYPC_IntersheetMode c_CoversheetBack  = pc_Print->c_Intersheet.getBackMode();
		// インターシートの取得.
		TYPC_IntersheetMode c_IntersheetMode = pc_Print->c_Intersheet.getMiddleMode();
		if( isOn( CNK_CoverModeFront, pc_Job ) == True ) {
			// 表カバーシートがONの場合.
			if( ( c_CoversheetFront.getFeedTray() == TYPE_FeedTrayPI1 && pc_FeedTray->getPaperStatus( TYPE_FeedTrayPI1 ) == TYPE_PaperStatusEmpty )
			    || ( c_CoversheetFront.getFeedTray() == TYPE_FeedTrayPI2 && pc_FeedTray->getPaperStatus( TYPE_FeedTrayPI2 ) == TYPE_PaperStatusEmpty ) ) {
				// PIトレイがエンプティの場合.
				bl_Empty = True;
			}
		}
		if( isOn( CNK_CoverModeBack, pc_Job ) == True ) {
			// 裏カバーシートがONの場合.
			if( ( c_CoversheetBack.getFeedTray() == TYPE_FeedTrayPI1 && pc_FeedTray->getPaperStatus( TYPE_FeedTrayPI1 ) == TYPE_PaperStatusEmpty )
			    || ( c_CoversheetBack.getFeedTray() == TYPE_FeedTrayPI2 && pc_FeedTray->getPaperStatus( TYPE_FeedTrayPI2 ) == TYPE_PaperStatusEmpty ) ) {
				// PIトレイがエンプティの場合.
				bl_Empty = True;
			}
		}
		if( isOn( CNK_MiddleMode, pc_Job ) == True ) {
			// インターシートがONの場合.
			if( ( c_IntersheetMode.getFeedTray() == TYPE_FeedTrayPI1 && pc_FeedTray->getPaperStatus( TYPE_FeedTrayPI1 ) == TYPE_PaperStatusEmpty )
			    || ( c_IntersheetMode.getFeedTray() == TYPE_FeedTrayPI2 && pc_FeedTray->getPaperStatus( TYPE_FeedTrayPI2 ) == TYPE_PaperStatusEmpty ) ) {
				// PIトレイがエンプティの場合.
				bl_Empty = True;
			}
		}
	}
	return bl_Empty;
}
