//概要    :Webサービス用管理装置判定.
Bool isKeyModeSendKindUseChackWSD()
{
	Bool			b_ret = True;						// 戻り値
	TYPE_KeyMode	e_KeyMode = TYPE_KeyModeNone;		// ベンダー状態保存変数
#ifdef IT2
	APIC_KeyDevice*	pc_KeyDevice = APIC_KeyDevice::newInstance();
	if( NULL == pc_KeyDevice ) {
		LOGF_debug_PutEventLog( LOGF_DEBUG_EVENT_KIND_ALL, 0, LOGD_DEBUG_LEVEL_UNKNOWN, "Assert Failed!" );
		return b_ret;
	}
	APIC_SystemInfo*	pc_SystemInfo = APIC_SystemInfo::newInstance();
	if( NULL == pc_SystemInfo ) {
		LOGF_debug_PutEventLog( LOGF_DEBUG_EVENT_KIND_ALL, 0, LOGD_DEBUG_LEVEL_UNKNOWN, "Assert Failed!" );
		return b_ret;
	}
	e_KeyMode = pc_KeyDevice->getKeyMode();
#else
	e_KeyMode = APIC_KeyDevice::getKeyMode();
#endif	// IT2.
	if( ( e_KeyMode != TYPE_KeyModeKeyCounter && e_KeyMode != TYPE_KeyModeNone ) ) {
		b_ret = False;
	}
	return b_ret;
}
//概要    :Webサービスキー選択可否判定.
Bool isEnableSelectAddressWSD( TYPC_ComSend* pc_ComSend, const Bool b_ProgramCheck )
{
	// 戻り値.
	Bool b_Result = False;
	// 引数チェック.
	if( NULL == pc_ComSend ) {
		LOGF_debug_PutEventLog( LOGF_DEBUG_EVENT_KIND_ALL, 0, LOGD_DEBUG_LEVEL_UNKNOWN, "Assert Failed!" );
		return False;
	}
	// TYPC_ComSendのコピー.
	TYPC_ComSend c_ComSend;
	memcpy( &c_ComSend, pc_ComSend, sizeof( TYPC_ComSend ) );
	// 一時配信またはプログラムキー選択時のチェックである場合.
	if( True == b_ProgramCheck ) {
		// 解除される一時配信またはプログラムキーにリンクしている宛先を解除する.
		cancelSelectProgramAddress( &c_ComSend );
	}
	/////////////////////////////////////////////////////////////////////////////////////
	// 短縮宛先に選択されているものがあるかどうかを確認.
	/////////////////////////////////////////////////////////////////////////////////////
	// 現在の短縮宛先選択件数を取得.
	short ss_SelecShorteningAddressCount = c_ComSend.getSelecShorteningAddressCount();
	if( ss_SelecShorteningAddressCount > 0 ) {	// 1件以上選択されている場合はWSD無効.
		return b_Result;
	}
	/////////////////////////////////////////////////////////////////////////////////////
	// 直接入力された同報があるかどうかを確認.
	/////////////////////////////////////////////////////////////////////////////////////
	// メール同報確認.
	for( short i = 0; TYPD_MaxDirectMailAddress > i; ++i ) {
		// 設定件数をカウント.
		TYPC_DirectMailAddress* pc_DirectMailAddress = c_ComSend.c_DirectAddressBook.pageMailAddress( short( i + 1 ) );
		if( True == pc_DirectMailAddress->getOn() ) {
			return b_Result;
		}
	}
	// FTP同報確認.
	for( short j = 0; TYPD_MaxDirectFtpAddress > j; ++j ) {
		// 設定件数をカウント.
		TYPC_DirectFtpAddress* pc_DirectFtpAddress = c_ComSend.c_DirectAddressBook.pageFtpAddress( short( j + 1 ) );
		if( True == pc_DirectFtpAddress->getOn() ) {
			return b_Result;
		}
	}
	// SMB同報確認.
	for( short k = 0; TYPD_MaxDirectSmbAddress > k; ++k ) {
		// 設定件数をカウント.
		TYPC_DirectSmbAddress* pc_DirectSmbAddress = c_ComSend.c_DirectAddressBook.pageSmbAddress( short( k + 1 ) );
		if( True == pc_DirectSmbAddress->getOn() ) {
			return b_Result;
		}
	}
	// BOX同報確認.
	for( short m = 0; TYPD_MaxDirectBoxAddress > m; ++m ) {
		// 設定件数をカウント.
		TYPC_DirectBoxAddress* pc_DirectBoxAddress = c_ComSend.c_DirectAddressBook.pageBoxAddress( short( m + 1 ) );
		if( True == pc_DirectBoxAddress->getOn() ) {
			return b_Result;
		}
	}
	// FAX同報確認.
	for( short n = 0; TYPD_MaxDirectFaxAddress > n; ++n ) {
		// 設定件数をカウント.
		TYPC_DirectFaxAddress* pc_DirectFaxAddress = c_ComSend.c_DirectAddressBook.pageFaxAddress( short( n + 1 ) );
		if( True == pc_DirectFaxAddress->getOn() ) {
			return b_Result;
		}
	}
	// WebDAV同報確認.
	for( short o = 0; TYPD_MaxDirectWebDavAddress > o; ++o ) {
		// 設定件数をカウント.
		TYPC_DirectWebDavAddress* pc_DirectWebDavAddress = c_ComSend.c_DirectAddressBook.pageWebDavAddress( short( o + 1 ) );
		if( True == pc_DirectWebDavAddress->getOn() ) {
			return b_Result;
		}
	}
	b_Result = True;	// 選択件数0件.
	return b_Result;
}
//概要    :Webサービスキー表示可否判定.
Bool isEnableSetAddressWSD( TYPC_ComSend* pc_ComSend, const Bool b_DataSet, const Bool b_SetOn, const Bool b_ProgramCheck, Bool b_FunctionLimitation )
{
	Bool b_Result = False;
	Bool _b_SslSetting;		// SSL設定 使用する/しない ここではメソッド引数として使用するのみ.
	Bool _b_PrtOnOff;		// Print機能設定 使用する/しない ここではメソッド引数として使用するのみ.
	Bool _b_ScnOnOff;		// Scan機能設定 使用する/しない.
	// Webサービスを使用しない際に同報件数オーバーの警告メッセージが表示される問題への対応 12波多野.
	Bool _b_isSelectedAnyOtherAddress = True;	// 他のアドレスが選択されているかどうか False:選択されている.
	if( True == ExtSet.isActiveGeneralApplication() ) {	// 各モードで汎用アプリが登録されている場合は宛先選択不可.
		return b_Result;
	}
	PnlComGetWSDSetting()->getEnableWSD( &_b_SslSetting , &_b_PrtOnOff , &_b_ScnOnOff );	// SSL設定／Print機能設定／Scan機能設定  使用する：True.

	TYPE_FuncLimit e_FuncLimit = TYPE_FuncLimit_Enable;
	if( True == b_FunctionLimitation ) {
		e_FuncLimit = PnlComCheckOperationAccountStatus( PNLE_ACCOUNT_STATUS_TYPE_Scan );
	}
	if( True == _b_ScnOnOff
	    && True == isKeyModeSendKindUseChackWSD()	// ベンダー/管理装置/ページアクセス使用時のBox保存可否状態取得. > キーカウンター以外は全てFalse
	    && ( TYPE_FuncLimit_Disable != e_FuncLimit ) ) {		// スキャン可能ユーザー.
		// 表示のみの判定の場合または選択を解除の場合.
		if( ( False == b_DataSet ) || ( False == b_SetOn ) ) {
			b_Result = True;
		} else {
			// WSD宛先選択可否判定.
			// Webサービスを使用しない際に同報件数オーバーの警告メッセージが表示される問題への対応 12波多野.
			_b_isSelectedAnyOtherAddress = isEnableSelectAddressWSD( pc_ComSend, b_ProgramCheck );
			b_Result = _b_isSelectedAnyOtherAddress;
		}
	}
	// Webサービスを使用しない際に同報件数オーバーの警告メッセージが表示される問題への対応 12波多野.
	if( False == _b_isSelectedAnyOtherAddress ) {
		// 同報件数オーバー.
		onlyPanel.setPanelWarning( PNL_ERROR_BroadcastOver );
	}
	return b_Result;
}
//概要    :WebDAV表示用アドレス生成.
void getAddressDispStringWebDAV( TYPS_WebDavAddress* const pc_Data, char* sc_Address, uint32_t ul_MaxDispSize )
{
	char sc_tmpWebDavAddr[ TYPD_MaxStrWebDavHostAddress + TYPD_MaxStrWebDavDir + 2 + 1 + 1 ];	// "//ホスト名/ファイルパス"
	memset( sc_tmpWebDavAddr, '\0', sizeof( sc_tmpWebDavAddr ) );
	strcpy( sc_tmpWebDavAddr, "//" );
	strcat( sc_tmpWebDavAddr, pc_Data->sc_HostAddress );
	if( 0 < strlen( pc_Data->sc_Dir ) ) {
		if( '/' != *pc_Data->sc_Dir ) {
			strncat( sc_tmpWebDavAddr, ( char* )"/", sizeof( sc_tmpWebDavAddr ) - strlen( sc_tmpWebDavAddr ) -1 );
		}
		strcat( sc_tmpWebDavAddr, pc_Data->sc_Dir );
	}
	memset( sc_Address, '\0', ul_MaxDispSize );
	if( False != PLBC_FuncVersionCheck::isOK_Type3() ) {	// Donau拡張機能3、Amur機能拡張2以降.
// Comment 2015/03/09 HCLT_Rengaraaj [HeliosL] Klockwork Changes ID:14866 [ABV.GENERAL].
//		strncpy(sc_Address, sc_tmpWebDavAddr, ul_MaxDispSize) ;				// コピー.
		strncpy(sc_Address, sc_tmpWebDavAddr, ul_MaxDispSize - 1) ;				// コピー.
	} else {
		//          	 行　桁（文字数）　　　 格納元アドレス　　格納先アドレス　取出し開始位置　　文字コード.
		setupInputString( 1, (short)( ul_MaxDispSize - 1 ), sc_tmpWebDavAddr, sc_Address, 0, getCharSetForPanel() );
	}
}
