//================================================================================================
//クラス  ：TYPC_BroadcastAddress : 同報宛先管理クラス
//概要    ：短縮宛先の設定・解除
//================================================================================================
void TYPC_BroadcastAddress::setShorteningAddressIGC( uint32_t ul_setRecodeId, const Bool b_On )
{
	// 同報宛先件数を取得.
	const ushort us_AddressCount = s_MmbBroadcastList.getNodeSize();
	ushort i = 1;
	for( i = 1; us_AddressCount >= i; ++i ) {
		// 選択されている宛先を順次取得.
		TYPS_AddressInfo s_AddressInfo;
		memset( &s_AddressInfo, 0x00, sizeof( s_AddressInfo ) );
		s_MmbBroadcastList.getNode( s_AddressInfo, i );
		// 指定した宛先と同一のものがある場合(バッファに保存したレコードIDで判断).
		if( ( ul_setRecodeId == s_AddressInfo.ul_LeftRecodeId ) && ( False == s_AddressInfo.b_Direct ) ) {
			break;
		}
	}
	// 解除指定で指定した宛先が選択されている場合.
	if( ( False == b_On ) && ( us_AddressCount >= i ) ) {
		// 最終選択同報宛先の削除.
		TYPS_AddressInfo s_AddressInfo;
		memset( &s_AddressInfo, 0x00, sizeof( s_AddressInfo ) );
		s_MmbBroadcastList.getNode( s_AddressInfo, i );
		// 宛先登録情報を操作ログとして残す(宛先解除).
		PNLC_OperationLog::newInstance()->setLogAddressInfo( &s_AddressInfo, OPLE_SubInfoAdrRelease );
		delLastSelectAddress( &s_AddressInfo );
		PNLC_BroadcastPadControlLib::newInstance()->deleteBroadcastList( (ushort)( i - 1 ) );
		// 指定した宛先を同報宛先リストから削除.
		s_MmbBroadcastList.deleteNode( i );
		bl_MmbAddressCount = False;	// カウンター更新フラグ.
		if( us_MmbSelectAddress == i ) {
			// 同報宛先非選択とする.
			us_MmbSelectAddress = TYPD_NotSelectBroadcastAddress;
		}
		if(	( TYPD_BroadcastAddressEffectiveStart != us_MmbEffectivePosition )
		    && ( us_MmbEffectivePosition > s_MmbBroadcastList.getNodeSize() ) ) {
			us_MmbEffectivePosition = (ushort)( us_MmbEffectivePosition - us_MmbEffectiveRange );
		}
		if( True == APIC_SoftDipSw::newInstance()->getSoftDipSwBitForPanelSpecNo( DEFSOFTWARESW214, 0 ) ) {	// LDAP検索実施時、認証ユーザーのE-mailアドレスをFROMアドレスに設定する機能の有効設定.
			if( 0 == s_MmbBroadcastList.getNodeSize() ) {		// 宛先選択総数が0.
				PnlComSetFromAddressAtNotSelectAddress( PnlComGetJobScanFax() );
			}
		}
	} else if( ( True == b_On ) && ( us_AddressCount < i ) ) {
		// 選択指定で指定した宛先が選択されていない場合.
		// 指定した宛先を同報宛先リストに追加.
		TYPS_AddressInfo s_AddressInfo;								// 同報宛先リスト.
		memset( &s_AddressInfo, 0x00, sizeof( s_AddressInfo ) );
		s_AddressInfo.b_Direct = False;								// 短縮宛先.
		s_AddressInfo.ul_LeftRecodeId = ul_setRecodeId;				// レコードID.
		s_AddressInfo.b_Select = False;
// comment 2015/09/14 OPS1-Sky後藤 [MinervaSBK][CQ518343] UD評価指摘対応.
		s_AddressInfo.bl_Regist = False;
		APIC_ShorteningAddress* pc_ShorteningAddress = APIC_ShorteningAddress::newInstance( (short)ul_setRecodeId );
		if( NULL != pc_ShorteningAddress ) {
			s_AddressInfo.e_SendMode = pc_ShorteningAddress->getSendMode();
		}
		bl_MmbAddressCount = False;	// カウンター更新フラグ.
		s_MmbBroadcastList.addNode( s_AddressInfo );				// s_MmbBroadcastListへ保存.
		PNLC_BroadcastPadControlLib::newInstance()->addBroadcastList( s_AddressInfo );
		// 最終選択同報宛先の設定.
		setLastSelectAddress( &s_AddressInfo );
		// 宛先登録情報を操作ログとして残す(宛先選択).
		PNLC_OperationLog::newInstance()->setLogAddressInfo( &s_AddressInfo, OPLE_SubInfoAdrSelect );
	}
}
//================================================================================================
//クラス  ：TYPC_BroadcastAddress : 同報宛先管理クラス
//概要    ：指定したRecodeIDがリストに存在するかどうか
//================================================================================================
Bool TYPC_BroadcastAddress::searchRecodeID( uint32_t ul_RecodeId )
{
	// 同報宛先件数を取得.
	const ushort us_AddressCount = s_MmbBroadcastList.getNodeSize();
	ushort i = 1;
	for( i = 1; us_AddressCount >= i; ++i ) {
		// 選択されている宛先を順次取得.
		TYPS_AddressInfo s_AddressInfo;
		memset( &s_AddressInfo, 0x00, sizeof( s_AddressInfo ) );
		s_MmbBroadcastList.getNode( s_AddressInfo, i );
		// 指定したレコードIDと同一のものがある場合.
		if( ul_RecodeId == s_AddressInfo.ul_LeftRecodeId ) {
			return True;
		}
	}
	return False;
}
//================================================================================================
//クラス  ：TYPC_BroadcastAddress : 同報宛先管理クラス
//概要    ：指定したRecodeIDがリストに存在するかどうか
//================================================================================================
Bool TYPC_BroadcastAddress::getAddressInfo( TYPS_AddressInfo& s_AddressInfo, uint32_t ul_RecodeId )
{
	// 同報宛先件数を取得.
	const ushort us_AddressCount = s_MmbBroadcastList.getNodeSize();
	ushort i = 1;
	for( i = 1; us_AddressCount >= i; ++i ) {
		// 選択されている宛先を順次取得.
		TYPS_AddressInfo s_AddressInfo;
		memset( &s_AddressInfo, 0, sizeof( s_AddressInfo ) );
		s_MmbBroadcastList.getNode( s_AddressInfo, i );
		// 指定したレコードIDと同一のものがある場合.
		if( ul_RecodeId == s_AddressInfo.ul_LeftRecodeId ) {
			return True;
		}
	}
	return False;
}

//================================================================================================
//クラス  ：TYPC_BroadcastAddress : 同報宛先管理クラス.
//概要    ：同報宛先の選択.
//================================================================================================
void TYPC_BroadcastAddress::selectUniqueAddress( const ushort us_UniqueIndex )
{
	if( 0 == us_UniqueIndex || 0 == us_MmbEffectiveRange ) {
		// 引数が不正な場合.
		PnlComPutDebugLog( True, UC_PNL_LOGPATTERN_1, "TYPC_BroadcastAddress::selectUniqueAddress", UC_PNL_ERROR_PARAMETER );
		return;
	}
//	// 指定されたアドレスを算出.

	ushort _us_NowPage = ( ushort )( us_UniqueIndex / us_MmbEffectiveRange );
	if( 0 != ( us_UniqueIndex % us_MmbEffectiveRange ) ) {
		_us_NowPage++;
	}

	if( 0 == _us_NowPage ) {
		PnlComPutDebugLog( True, UC_PNL_LOGPATTERN_1, "TYPC_BroadcastAddress::selectUniqueAddress", UC_PNL_ERROR_PARAMETER );
		return;
	}

	us_MmbEffectivePosition = (ushort)(( _us_NowPage - 1 ) * us_MmbEffectiveRange + TYPD_BroadcastAddressEffectiveStart);
	us_MmbSelectAddress = us_UniqueIndex;
	if( us_UniqueIndex > s_MmbBroadcastList.getNodeSize() ) {
		PnlComPutDebugLog( True, UC_PNL_LOGPATTERN_1, "TYPC_BroadcastAddress::selectUniqueAddress", UC_PNL_ERROR_IMPOSSIBLE );
		return;
	}
	TYPS_AddressInfo _st_AddressInfo;
	s_MmbBroadcastList.getNode( _st_AddressInfo, us_UniqueIndex );
	_st_AddressInfo.b_Select = True;
	s_MmbBroadcastList.updateNode( _st_AddressInfo, us_UniqueIndex );
}
//================================================================================================
//クラス  ：TYPC_BroadcastAddress : 同報宛先管理クラス
//概要    ：指定したRecodeIDを同報宛先Indexへ変換する.
//================================================================================================
short TYPC_BroadcastAddress::recordIDToAddressIndex( uint32_t ul_RecodeId )
{
	short _ss_AddressIndex = -1;	// 同報宛先Index.
	const ushort _us_AddressCount = s_MmbBroadcastList.getNodeSize();	// 同報宛先件数を取得.
	ushort _us_Count = 1;
	for( _us_Count = 1; _us_Count <= _us_AddressCount; _us_Count++ ) {	// 選択されている宛先を順次取得.
		TYPS_AddressInfo _st_AddressInfo;
		memset( &_st_AddressInfo,0x00,sizeof( _st_AddressInfo ) );
		s_MmbBroadcastList.getNode( _st_AddressInfo, _us_Count );
		if( ul_RecodeId == _st_AddressInfo.ul_LeftRecodeId ) {	// 指定したレコードIDと同一のものがある場合.
			_ss_AddressIndex = _us_Count;
			break;
		}
	}
	return( _ss_AddressIndex );
}

//概要　　：ユーザー・部門情報の上限値カウンターパーツ非表示.
void PnlComGetLoginCounterInfo_HideParts(
    PActivatable* 			p_Btx_Title,			// タイトル(PActivatable).			NULL可.
    PSinglePartsText*		p_Txt_Title,			// タイトル(PSinglePartsText).		NULL可.
    PActivatable*    		p_Btx_Value,			// 値(PActivatable).				NULL可.
    PActivatableAdd* 		p_Btx_ValueAdd,			// 値(PActivatableAdd).				NULL可.
    PTextField*				p_Tfd_Value				// 値(PTextField).					NULL可.
)
{
	// タイトル表示.
	if( NULL != p_Btx_Title ) {	// 背景付き.
		p_Btx_Title->showEnable( False );
	} else if( NULL != p_Txt_Title ) {	// 背景なし.
		p_Txt_Title->showEnable( False );
	}
	// カウンター値.
	if( NULL != p_Btx_Value || NULL != p_Btx_ValueAdd ) {
		if( NULL != p_Btx_Value ) {	// PActivatable.
			p_Btx_Value->showEnable( False );
		} else if( NULL != p_Btx_ValueAdd ) {	// PActivatableAdd.
			p_Btx_ValueAdd->showEnable( False );
		}
	} else if( NULL != p_Tfd_Value ) {	// PTextField.
		p_Tfd_Value->showEnable( False );
	}
}
//概要　　：ユーザー・部門情報の上限値カウンターパーツ表示.
void PnlComGetLoginCounterInfo_ShowParts(
    Bool					b_Total,				// トータル表示かどうか.
    Bool					b_MessageGamenOn,		// メッセージかどうか.
    uint32_t				ul_Cnt,					// カウンター現在値.
    uint32_t				ul_Limit,				// カウンター最大値
    uint32_t				ul_LimitDisp,			// カウンター最大値(表示用).
    Bool					b_NumberOn,				// 「９９９９９」「ーーーーー」表示.
    PActivatable* 			p_Btx_Title,			// タイトル(PActivatable).			NULL可.
    PSinglePartsText*		p_Txt_Title,			// タイトル(PSinglePartsText).		NULL可.
    PActivatable*    		p_Btx_Value,			// 値(PActivatable).				NULL可.
    PActivatableAdd* 		p_Btx_ValueAdd,			// 値(PActivatableAdd).				NULL可.
    PTextField*				p_Tfd_Value				// 値(PTextField).					NULL可.
)
{
	char _sc_String[ 2+ DEF_LOGINCOUNTERINFO_COUNTER_LIMIT + 1 + DEF_LOGINCOUNTERINFO_COUNTER_LIMIT + 1 + 1 ]; 				// 残カウント値表示用19Byte( [: ]+[残カウント]+[(]+[上限値]+[)]+1 ).
	char _sc_StrTmp[ DEF_LOGINCOUNTERINFO_COUNTER_LIMIT + 1 ]; 																// 残カウント値作成用(「カウント」＋１).
	memset( _sc_String, '\0', sizeof( _sc_String ) );
	memset( _sc_StrTmp, '\0', sizeof( _sc_StrTmp ) );
	// タイトル表示.
	if( NULL != p_Btx_Title ) {	// 背景付き.
		p_Btx_Title->showEnable( True );
	} else if( NULL != p_Txt_Title ) {	// 背景なし.
		p_Txt_Title->showEnable( True );
	}
	// カラー残カウント値.
	if( False == b_NumberOn ) {
		strcpy( _sc_String, "-------" );
	} else {
		uint32_t ui32_Remain = ul_Limit - ul_Cnt;						// 残カウンター.
		if( TYPD_AdminUserAndDepart_DepartLimit < ui32_Remain ) {
			ui32_Remain = TYPD_AdminUserAndDepart_DepartLimit;
		}
		if( TYPD_AdminUserAndDepart_DepartLimit < ul_LimitDisp ) {	// 上限カウンター.
			ul_LimitDisp = TYPD_AdminUserAndDepart_DepartLimit;
		}

		// メッセージ画面.
		if( True == b_MessageGamenOn ) {
			if( False == b_Total ) { strcat( _sc_String, ": " ); }
			snprintf( _sc_StrTmp, sizeof( _sc_StrTmp ), "%d", ui32_Remain );		// 残カウント.
			strcat( _sc_String, _sc_StrTmp );
			strcat( _sc_String, "(" );
			snprintf( _sc_StrTmp, sizeof( _sc_StrTmp ), "%d", ul_LimitDisp );					// 上限値(表示用).
			strcat( _sc_String, _sc_StrTmp );
			strcat( _sc_String, ")" );
		} else {
			// ユーティリティなど(数字の間桁詰めない).
			snprintf( _sc_StrTmp, sizeof( _sc_StrTmp ), "%7d", ui32_Remain );		// 残カウント.
			strcat( _sc_String, _sc_StrTmp );
			strcat( _sc_String, "(" );
			snprintf( _sc_StrTmp, sizeof( _sc_StrTmp ), "%7d", ul_LimitDisp );					// 上限値(表示用).
			strcat( _sc_String, _sc_StrTmp );
			strcat( _sc_String, ")" );
		}
	}
	// パーツ表示.
	if( NULL != p_Btx_Value || NULL != p_Btx_ValueAdd ) {
		if( NULL != p_Btx_Value ) {	// PActivatable.
			p_Btx_Value->changeASCIIText( ( const uchar* )_sc_String, sizeof( _sc_String ) );
			p_Btx_Value->showEnable( True );
		} else if( NULL != p_Btx_ValueAdd ) {	// PActivatableAdd.
			p_Btx_ValueAdd->changeASCIIText( p_Tfd_Value, ( const uchar* )_sc_String, sizeof( _sc_String ) );
			p_Btx_ValueAdd->showEnable( True );
		}
	} else if( NULL != p_Tfd_Value ) {	// PTextField.
		p_Tfd_Value->changeASCIIText( ( const uchar* )_sc_String, sizeof( _sc_String ) );
		p_Tfd_Value->showEnable( True );
	}
}
//概要	  ：ユーザー・部門情報の上限値カウンター情報取得.
void PnlComGetLoginCounterInfo(
    APIC_Track*				pc_Track,					// 部門ポインタ.
    APIC_TrackCnt*			pc_TrackCnt,				// カウンターポインタ.
    Bool					b_ColonOn,					// カウンター値の前にコロンをつける.
    PSinglePartsText*		p_Txt_TotalTitle,			// トータルタイトル(PSinglePartsText).		NULL可.
    PTextField*				p_Tfd_TotalValue,			// トータル値(PTextField).					NULL可.
    PSinglePartsText*		p_Txt_ColorTitle,			// カラータイトル(PSinglePartsText).		NULL可.
    PTextField*				p_Tfd_ColorValue,			// カラー値(PTextField).					NULL可.
    PSinglePartsText*		p_Txt_BlackTitle,			// ブラックタイトル(PSinglePartsText).		NULL可.
    PTextField*				p_Tfd_BlackValue 			// ブラック値(PTextField).
)
{
	if( NULL == pc_Track || NULL == pc_TrackCnt ) {
		LOGF_debug_PutEventLog( LOGF_DEBUG_EVENT_KIND_ALL, 0, LOGD_DEBUG_LEVEL_UNKNOWN, "Assert Failed!" );	return;
	}
//【CQ510665】【RQ-218CostCenterの再設定】 HCL-Surya 2014/11/24 Add Start.
	char * psc_costcid = NULL;
	if(PNLC_ActionDataLib::newInstance() != NULL){
		psc_costcid = PNLC_ActionDataLib::newInstance()->getCostCenterID();
	}
//【CQ510665】【RQ-218CostCenterの再設定】 HCL-Surya 2014/11/24 Add End.
//【CQ510665】【RQ-218CostCenterの再設定】 HCL-Surya 2014/11/24 Mod Start.
	// トータルカウンター上限値.
//	if( True == pc_Track->getTotalLimitOn() ) {
	if( True == pc_Track->getTotalLimitOn(psc_costcid) ) {
//【CQ510665】【RQ-218CostCenterの再設定】 HCL-Surya 2014/11/24 Mod End.
		// パーツの非表示(カラー・ブラック).
		PnlComGetLoginCounterInfo_HideParts( NULL, p_Txt_ColorTitle, NULL, NULL, p_Tfd_ColorValue );
		PnlComGetLoginCounterInfo_HideParts( NULL, p_Txt_BlackTitle, NULL, NULL, p_Tfd_BlackValue );
		// パーツの表示(トータル).
		PnlComGetLoginCounterInfo_ShowParts(	True,									// トータル表示かどうか.
		                                        b_ColonOn,								// メッセージかどうか.
		                                        pc_TrackCnt->getDisplayUsedTotal(),		// カウンター使用済値.
		                                        pc_TrackCnt->getDisplayRemainTotal(),	// カウンター上限値.
		                                        pc_TrackCnt->getDisplayLimitTotal(),	// カウンター上限値（表示用）.
		                                        True,									// 「９９９９９」「ーーーーー」表示.
		                                        NULL,									// タイトル(PActivatable).			NULL可.
		                                        p_Txt_TotalTitle,						// タイトル(PSinglePartsText).		NULL可.
		                                        NULL,									// 値(PActivatable).				NULL可.
		                                        NULL,									// 値(PActivatableAdd).				NULL可.
		                                        p_Tfd_TotalValue						// 値(PTextField).					NULL可.
		                                   );
	} else {
		// その他.
		// パーツの非表示(トータル).
		PnlComGetLoginCounterInfo_HideParts( NULL, p_Txt_TotalTitle, NULL, NULL, p_Tfd_TotalValue );
//【CQ510665】【RQ-218CostCenterの再設定】 HCL-Surya 2014/11/24 Mod Start.
		// カラーカウンター上限値.
//		if( True == pc_Track->getTotalLimitFullColorOn() ) {
		if( True == pc_Track->getTotalLimitFullColorOn(psc_costcid) ) {
//【CQ510665】【RQ-218CostCenterの再設定】 HCL-Surya 2014/11/24 Mod End.
			// パーツの表示(カラー).
			PnlComGetLoginCounterInfo_ShowParts(	False,									// トータル表示かどうか.
			                                        b_ColonOn,								// メッセージかどうか.
			                                        pc_TrackCnt->getDisplayUsedFullColor(),		// カウンター使用済値.
			                                        pc_TrackCnt->getDisplayRemainFullColor(),	// カウンター上限値.
			                                        pc_TrackCnt->getDisplayLimitFullColor(),	// カウンター上限値（表示用）.
			                                        True,									// 「９９９９９」「ーーーーー」表示.
			                                        NULL,									// タイトル(PActivatable).			NULL可.
			                                        p_Txt_ColorTitle,						// タイトル(PSinglePartsText).		NULL可.
			                                        NULL,									// 値(PActivatable).				NULL可.
			                                        NULL,									// 値(PActivatableAdd).				NULL可.
			                                        p_Tfd_ColorValue						// 値(PTextField).					NULL可.
			                                   );
		} else {
			// パーツの非表示(カラー).
			PnlComGetLoginCounterInfo_HideParts( NULL, p_Txt_ColorTitle, NULL, NULL, p_Tfd_ColorValue );
		}
//【CQ510665】【RQ-218CostCenterの再設定】 HCL-Surya 2014/11/24 Mod Start.
		// ブラックカウンター上限値.
//		if( True == pc_Track->getTotalLimitBlackOn() ) {
		if( True == pc_Track->getTotalLimitBlackOn(psc_costcid) ) {
//【CQ510665】【RQ-218CostCenterの再設定】 HCL-Surya 2014/11/24 Mod End.
			// パーツの表示(ブラック).
			PnlComGetLoginCounterInfo_ShowParts(	False,									// トータル表示かどうか.
			                                        b_ColonOn,								// メッセージかどうか.
			                                        pc_TrackCnt->getDisplayUsedBlack(),		// カウンター使用済値.
			                                        pc_TrackCnt->getDisplayRemainBlack(),	// カウンター上限値.
			                                        pc_TrackCnt->getDisplayLimitBlack(),	// カウンター上限値（表示用）.
			                                        True,									// 「９９９９９」「ーーーーー」表示.
			                                        NULL,									// タイトル(PActivatable).			NULL可.
			                                        p_Txt_BlackTitle,						// タイトル(PSinglePartsText).		NULL可.
			                                        NULL,									// 値(PActivatable).				NULL可.
			                                        NULL,									// 値(PActivatableAdd).				NULL可.
			                                        p_Tfd_BlackValue						// 値(PTextField).
			                                   );
		} else {
			// パーツの非表示(ブラック).
			PnlComGetLoginCounterInfo_HideParts( NULL, p_Txt_BlackTitle, NULL, NULL, p_Tfd_BlackValue );
		}
	}
}
//概要　　：基本： ユーザー・部門上限値カウンター表示判断.
Bool isLoginCounterInfoOn()
{
	Bool b_Result = False;
//【CQ510665】【RQ-218CostCenterの再設定】 HCL-Surya 2014/11/24 Add Start.
	char * psc_costcid = NULL;
	if(PNLC_ActionDataLib::newInstance() != NULL){
		psc_costcid = PNLC_ActionDataLib::newInstance()->getCostCenterID();
	}
//【CQ510665】【RQ-218CostCenterの再設定】 HCL-Surya 2014/11/24 Add End.
	// ユーザー・部門上限値カウンター表示フラグ.
	if( True == onlyPanel.bl_isLoginCounterInfoOn ) {
		APIC_Track* pc_Track = NULL;
		// ユーザ認証中.
// PnlComGetUser()　NULLチェック対応.
		if( NULL != PnlComGetUser() && True == PnlComGetUserAccountOn() ) {
// Comment 2017/09/12【HCLT-Sindhu】【IT5 4.2】【RQ686】【WP1012】Public user support for Network 2.
//			if( TYPD_IndexUserPublic <= PnlComGetUser()->getUserNo() ) {
			if( (TYPD_IndexUserPublic <= PnlComGetUser()->getUserNo()) || (TYPD_IndexUserPublicNW2 <= PnlComGetUser()->getUserNo()) ) {
				pc_Track = APIC_Track::newInstance( PnlComGetUser()->getUserNo() );
			} else {
				pc_Track = APIC_Track::newInstance( PnlComGetUser()->getUserNo() + PnlComGetTrackManager()->getTrackCntNo() );
			}
			// 上限値が設定されている場合.
			if( NULL != pc_Track
//【CQ510665】【RQ-218CostCenterの再設定】 HCL-Surya 2014/11/24 Mod Start.
//			    && ( True == pc_Track->getTotalLimitOn()							// ユーザートータル上限値.
//			         || True == pc_Track->getTotalLimitFullColorOn()					// ユーザーカラー上限値.
//			         || True == pc_Track->getTotalLimitBlackOn() ) ) {				// ユーザーブラック上限値.
				&& ( True == pc_Track->getTotalLimitOn(psc_costcid)							// ユーザートータル上限値.
					 || True == pc_Track->getTotalLimitFullColorOn( psc_costcid )			// ユーザーカラー上限値.
					 || True == pc_Track->getTotalLimitBlackOn( psc_costcid ) ) ) {			// ユーザーブラック上限値.
//【CQ510665】【RQ-218CostCenterの再設定】 HCL-Surya 2014/11/24 Mod End.
				b_Result = True;
			}
		}
		// 部門管理中.
		if( True == PnlComGetTrackOn() ) {
			int32_t i32_TrackNo = PnlComGetTrack()->getTrackNo(); // 2013/11/01 【US-20U-PN3G】20万人対応.
			pc_Track = APIC_Track::newInstance( i32_TrackNo );
			// 上限値が設定されている場合.
			if( NULL != pc_Track
//【CQ510665】【RQ-218CostCenterの再設定】 HCL-Surya 2014/11/24 Mod Start.
//			    && ( True == pc_Track->getTotalLimitOn()							// 部門トータル上限値.
//			         || True == pc_Track->getTotalLimitFullColorOn()					// 部門カラー上限値.
//			         || True == pc_Track->getTotalLimitBlackOn() ) ) {				// 部門ブラック上限値.
				&& ( True == pc_Track->getTotalLimitOn( psc_costcid )							// 部門トータル上限値.
					 || True == pc_Track->getTotalLimitFullColorOn( psc_costcid )				// 部門カラー上限値.
					 || True == pc_Track->getTotalLimitBlackOn( psc_costcid ) ) ) {				// 部門ブラック上限値.
//【CQ510665】【RQ-218CostCenterの再設定】 HCL-Surya 2014/11/24 Mod End.
				b_Result = True;
			}
		}
	}
	return b_Result;
}
