//================================================================================================
// 概要    :ダブルダイアル::ダイアル比較処理
// 戻り値  :PNLE_REINPUT 初期状態(確認実行前) /確認OK/確認NGを返す
//================================================================================================
PNLE_REINPUT PNLC_DoubleDial::CmpInputDial()
{
	PNLE_REINPUT e_ReInput = PNLE_REINPUT_INIT;					// 戻り値
	char sc_WorkInput[ TYPD_MaxStrFaxDialNo + 1 ];				// 比較元文字列(確認もとのダイアル宛先)
	char sc_WorkReInput[ TYPD_MaxStrFaxDialNo + 1 ];			// 比較先文字列(入力したダイアル宛先)
	short ss_index = 0;											// 配列INDEX(for文)
	memset( sc_WorkInput, '\0', sizeof( sc_WorkInput ) );
	memset( sc_WorkReInput, '\0', sizeof( sc_WorkReInput ) );
	// 比較元/入力宛先なし時はNG
	if( ( sc_FaxInputStr[0] == '\0' ) || ( sc_FaxReInputStr[0] == '\0' ) ) {
		e_ReInput = PNLE_REINPUT_NG;
		e_ReInputResult = e_ReInput;
		return ( e_ReInput );
	}
	short ss_setIndex = 0;	// 保存先配列Index
	// 比較元配列(sc_FaxInputStr)から「-」を省く
	for( ss_index = 0, ss_setIndex = 0; ss_index < TYPD_MaxStrFaxDialNo; ss_index++ ) {
		if( sc_FaxInputStr[ ss_index ] != '\0' ) {
			if( sc_FaxInputStr[ ss_index ] != '-' ) {
				// 「-」以外であれば比較元文字列として格納する
				sc_WorkInput[ ss_setIndex ] = sc_FaxInputStr[ ss_index ];
				ss_setIndex++;
			}
		} else {
			// 比較元配列セット完了で抜ける
			break;
		}
	}
	// 比較先配列(sc_FaxReInputStr)から「-」を省く
	for( ss_index = 0, ss_setIndex = 0; ss_index < TYPD_MaxStrFaxDialNo; ss_index++ ) {
		if( sc_FaxReInputStr[ ss_index ] != '\0' ) {
			if( sc_FaxReInputStr[ ss_index ] != '-' ) {
				// 「-」以外であれば比較先文字列として格納する
				sc_WorkReInput[ ss_setIndex ] = sc_FaxReInputStr[ ss_index ];
				ss_setIndex++;
			}
		} else {
			// 比較先配列セット完了で抜ける
			break;
		}
	}
	// 入力済み宛先と、再入力宛先の比較
	if( strncmp( sc_WorkInput, sc_WorkReInput, TYPD_MaxStrFaxDialNo ) == 0 ) {
		// 比較OK
		e_ReInput = PNLE_REINPUT_OK;
	} else {
		// 比較NG
		e_ReInput = PNLE_REINPUT_NG;
	}
	// クラス内へ結果を保持
	e_ReInputResult = e_ReInput;
	return e_ReInput;
}
//================================================================================================
// 概要    : ダブルダイアル::再入力ダイアル初期設定処理
//           引数で再入力画面で使用する宛先表示パーツ、再入力画面モードを指定する
//================================================================================================
void PNLC_DoubleDial::initReDialInfo( PActivatable* setBtx, PNLE_REINPUTMODE e_setmode, Bool b_Clear )
{
	// 終了時処理フラグをFalseにする
	bl_EndFlg = False;
	// 吹き出し画面からの判定フラグを初期化
	bl_balloonFlg = False;
	// クリア指定があるとき
	if( b_Clear == True ) {
		// 比較結果を初期状態にする
		e_ReInputResult = PNLE_REINPUT_INIT;
		// 再入力宛先をクリアする
		memset( sc_FaxReInputStr, '\0', sizeof( sc_FaxReInputStr ) );
	}
	// 再入力画面モードを保存
	e_ReMode = e_setmode;
	if( setBtx != NULL ) {
		// 画面で使用するカーソルテキストパーツ設定
		Ctf_ReDialField38 = setBtx;
	} else {
		LOGF_debug_PutEventLog( LOGF_DEBUG_EVENT_KIND_ALL, 0, LOGD_DEBUG_LEVEL_UNKNOWN, "Assert Failed!" );
		return;
	}
	// スライドクラスの初期設定
	switch( e_ReMode ) {
		case PNLE_REINPUTMODE_FAX:
		case PNLE_REINPUTMODE_FAXENL:
		case PNLE_REINPUTMODE_POG:
			if( onlyPanel.bl_isEnlargeDisplayMode != True ) {
				// 通常
				c_SlideTextMgr.init_CLCD( sc_FaxReInputStr, PNLD_MaxFaxNumDispSize,
				                          TYPD_MaxStrFaxDialNo, Ctf_ReDialField38, EP_CharSet_USASCII );
			} else {
				// 拡大
				c_SlideTextMgr.init_CLCD( sc_FaxReInputStr, PNLD_MaxFaxNumDispSizeEnl,
				                          TYPD_MaxStrFaxDialNo, Ctf_ReDialField38, EP_CharSet_USASCII );
			}
			break;
		case PNLE_REINPUTMODE_BFAX:
		case PNLE_REINPUTMODE_JFAX:
			c_SlideTextMgr.init_CLCD( sc_FaxReInputStr, PNLD_MaxFaxNumDispSize,
			                          TYPD_MaxStrFaxDialNo, Ctf_ReDialField38, EP_CharSet_USASCII );
			break;
		case PNLE_REINPUTMODE_SETTING:
		case PNLE_REINPUTMODE_ADDRREG:
			c_SlideTextMgr.init_CLCD( sc_FaxReInputStr, TYPD_MaxStrFaxDialNo,
			                          TYPD_MaxStrFaxDialNo, Ctf_ReDialField38, EP_CharSet_USASCII );
			break;
		default: break;
	}
}
