//================================================================================================
// 概要    :ダブルダイアル::再入力画面メッセージ取得処理
// 戻り値  :ushort(メッセージシンボルID) 0時はシンボル無し
//================================================================================================
ushort PNLC_DoubleDial::getMessageDisp()
{
	ushort us_textID = 0;
	switch( e_ReMode ) {
		case PNLE_REINPUTMODE_FAX:
		case PNLE_REINPUTMODE_FAXENL:
		case PNLE_REINPUTMODE_BFAX:
		case PNLE_REINPUTMODE_POG:
		case PNLE_REINPUTMODE_JFAX:
			if( e_ReInputResult == PNLE_REINPUT_INIT ) {
				us_textID = s_MSGReDaialInputTx;
			} else if( e_ReInputResult == PNLE_REINPUT_NG ) {
				us_textID = s_MSGReDaialInputTxNG;
			} else {
				// 変更無し
				us_textID = 0;
			}
			break;
		case PNLE_REINPUTMODE_SETTING:
		case PNLE_REINPUTMODE_ADDRREG:
			if( e_ReInputResult == PNLE_REINPUT_INIT ) {
				us_textID = s_MSGReDaialInputReg;
			} else if( e_ReInputResult == PNLE_REINPUT_NG ) {
				us_textID = s_MSGReDaialInputRegNG;
			} else {
				// 変更無し
				us_textID = 0;
			}
			break;
		default: break;
	}
	return us_textID;
}
//================================================================================================
// 概要    :ダブルダイアル::ボタン押下処理
// 戻り値  :Bool   True 入力受付/False 受付不可
//          IDを定義して処理を行う、また、0～9は10キー共通処理に飛ばすために0～9OPTINに変更すること
//================================================================================================
Bool PNLC_DoubleDial::InputButtonOnCom( uchar option, uchar uc_offset )
{
	Bool  b_result =  False;	// 判定結果
	PARTS_POS uc_CurPos = 0;							// カーソル位置.
	if( Ctf_ReDialField38 == NULL ) {
		LOGF_debug_PutEventLog( LOGF_DEBUG_EVENT_KIND_ALL, 0, LOGD_DEBUG_LEVEL_UNKNOWN, "Assert Failed!" );
		return b_result;
	}
	// 各画面毎の使用パーツでのOPTION値設定
	const uchar BTNID_INDEX_DELETE	= uchar( 0 );		// 削除ボタンIndex
	const uchar BTNID_INDEX_LEFT	= uchar( 1 );		// 「←」ボタンIndex
	const uchar BTNID_INDEX_RIGHT	= uchar( 2 );		// 「→」ボタンIndex
	const uchar uc_ButtonOnID[7][3] = {
		// 削除ボタン 									// 「←」ボタン									// 「→」ボタン
		{	PNLD_FaxBtnNBasicDelete,						PNLD_FaxBtnNComArrowLeft,						PNLD_FaxBtnNComArrowRight						},		// 通常ScanFax宛先入力
		{	PNLD_FaxBtnNBasicDelete,						PNLD_FaxBtnNComArrowLeft,						PNLD_FaxBtnNComArrowRight						},		// BOX ScanFax宛先入力
		{	PNLD_FaxBtnNBasicDelete,						PNLD_FaxBtnNComArrowLeft,						PNLD_FaxBtnNComArrowRight						},		// 拡大 ScanFax宛先入力
		{	BTNID_KEY_SCANSERCHADDRESSLDAPFAXNUMBERDELETE,	BTNID_KEY_SCANSERCHADDRESSLDAPFAXNUMBERLEFT,	BTNID_KEY_SCANSERCHADDRESSLDAPFAXNUMBERRIGHT	},		// 管理者設定
		{	BTNID_KEY_SCANSERCHADDRESSLDAPFAXNUMBERDELETE,	BTNID_KEY_SCANSERCHADDRESSLDAPFAXNUMBERLEFT,	BTNID_KEY_SCANSERCHADDRESSLDAPFAXNUMBERRIGHT	},		// 宛先登録
		{	BTNID_KEY_SCANSERCHADDRESSLDAPFAXNUMBERDELETE,	BTNID_KEY_SCANSERCHADDRESSLDAPFAXNUMBERLEFT,	BTNID_KEY_SCANSERCHADDRESSLDAPFAXNUMBERRIGHT	},		// プログラム登録
		{	PNLD_FaxBtnNBasicDelete,						PNLD_FaxBtnNComArrowLeft,						PNLD_FaxBtnNComArrowRight						}		// 通常ScanFax宛先入力
	};
	// 各ボタン毎での処理実行
	if( option == uc_ButtonOnID[( uchar )e_ReMode][BTNID_INDEX_DELETE] ) {	// 削除
		if( sc_FaxReInputStr[0] != '\0' ) {
			// カーソル位置の取得(共通指定パーツから).
			Ctf_ReDialField38->getCursorPosition( uc_CurPos );
			if( ( sc_FaxReInputStr[0] == 'E' ) && ( sc_FaxReInputStr[1] == '-' )
			    && ( uc_CurPos == 2 ) && ( uc_CurPos >= ( PARTS_POS )( strlen( sc_FaxReInputStr ) ) ) ) {
				// 「E-」削除.
				sc_FaxReInputStr[0] = '\0';
				Ctf_ReDialField38->setCursorPosition( (short)( uc_CurPos - 2 ) );
				// 削除する文字が「T」の時、ＮＵＬＬ文字に入れ替え'T'以降を表示から削除.
			} else if( sc_FaxReInputStr[ uc_CurPos ] == 'T' ) {
				// カーソル位置はそのまま
				sc_FaxReInputStr[ uc_CurPos ] = '\0';
			} else {
				// 削除文字が「T」でない場合は通常削除動作.
				c_SlideTextMgr.deleteStr( sc_FaxReInputStr );
			}
			b_result = True;
		}
	} else if( option == uc_ButtonOnID[( uchar )e_ReMode][BTNID_INDEX_LEFT] ) {	// 矢印（←）キー
		Ctf_ReDialField38->getCursorPosition( uc_CurPos );		// カーソル位置取得.
		if( ( sc_FaxReInputStr[0] == 'E' ) && ( sc_FaxReInputStr[1] == '-' )
		    && ( uc_CurPos == 2 ) ) {
			// 「E-」入力時,2文字目以前にはカーソル移動できなくする.
			b_result = False;
		} else {
			c_SlideTextMgr.selectArrow_CLCD( True, sc_FaxReInputStr );
			b_result = True;
		}
	} else if( option == uc_ButtonOnID[( uchar )e_ReMode][BTNID_INDEX_RIGHT] ) {	// 矢印（→）キー
		c_SlideTextMgr.selectArrow_CLCD( False, sc_FaxReInputStr );
		b_result = True;
	} else if( option == BTNID_KEY_SCANSERCHADDRESSLDAPFAXNUMBERTONE ) {	// トーンキー
		b_result = InputSpecialKey( 'T' );
	} else if( option == BTNID_KEY_SCANSERCHADDRESSLDAPFAXNUMBERPAUSE ) {	// ポーズキー
		b_result = InputSpecialKey( 'P' );
	} else if( option == BTNID_KEY_SCANSERCHADDRESSLDAPFAXNUMBERHYPHEN ) {	// ハイフンキー
		b_result = InputSpecialKey( '-' );
	} else if( option == BTNID_KEY_FAXSPEEDDIALSETTINGEXTERNALLINE ) {	// 外線キー.
		if( strlen( sc_FaxReInputStr ) == 0 ) {
			// 何某かが入力されている場合は,「E-」の入力は無効.
			uchar  uc_InputText[3];
			memset( uc_InputText, '\0', sizeof( uc_InputText ) );
			uc_InputText[0] = 'E';
			uc_InputText[1] = '-';
			c_SlideTextMgr.insertStr( sc_FaxReInputStr, ( char* )uc_InputText );
			b_result = True;
		} else {
			b_result = False;
		}
	} else if( option == BTNID_KEY_SCANFAXLDAPSERCHFAXNUMSHARP ) {	// シャープキー
		b_result = Input10KeyCom( PNLD_FaxKeySharp );
	} else if( option == BTNID_KEY_SCANFAXLDAPSERCHFAXNUMASTERISK ) {	// アスタリスクキー
		b_result = Input10KeyCom( PNLD_FaxKeyAsterisk );
	} else {	// ０～９キー押下
		// 10キー押下処理にIDをあわせる
		b_result = Input10KeyCom( (uchar)( option - uc_offset ) );
	}
	return b_result;
}
//================================================================================================
// 概要    :ダブルダイアル::10キー押下処理
// 戻り値  :Bool   True 入力受付/False 受付不可
//================================================================================================
Bool PNLC_DoubleDial::Input10KeyCom( uchar option )
{
	Bool  b_result = False;		// 判定結果
	short ss_strLen = (short)strlen( sc_FaxReInputStr );
	uchar uc_text[2];
	TYPE_DialMethod		e_DialMethod = TYPE_DialMethod_PB;
	APIC_FaxGfpSetting* pc_FaxGfpSetting = PnlComGetFaxGfpSetting();
	memset( uc_text, '\0',sizeof( uc_text ) );
	// 音声再生用、トーン表示フラグを初期化.
	bl_showTone = False;

	// 入力桁数がMAX時は受付不可
	if( ss_strLen >= TYPD_MaxStrFaxDialNo ) {
		return b_result;
	}
	// 宛先文字列のトーン記号位置検索
	uchar uc_pos = ( uchar )strcspn( sc_FaxReInputStr, "T" );
	// 再入力実行画面毎で入力処理を行う
	if( ( e_ReMode == PNLE_REINPUTMODE_FAX )||( e_ReMode == PNLE_REINPUTMODE_FAXENL )
	    ||( e_ReMode == PNLE_REINPUTMODE_BFAX )||( e_ReMode == PNLE_REINPUTMODE_JFAX ) ) {
		APIC_Job* pc_job = PnlComGetJobScanFax();
		if( NULL == pc_job ) {
			LOGF_debug_PutEventLog( LOGF_DEBUG_EVENT_KIND_ALL, 0, LOGD_DEBUG_LEVEL_UNKNOWN, "Assert Failed!" );
			return False;
		}
		TYPC_FaxCommon* pc_FaxCommon = &( pc_job->getJobSpec()->pc_Fax->c_FaxCommon );
		// 指定回線の回線種別を取得。指定無しの場合は回線1に合わせる
		TYPE_CommLine e_CommLineTmp = pc_FaxCommon->getCommLine();
		// 回線指定がしていなしの時は回線1の回線種別を取得する.
		if( TYPE_CommLineNotUsed == e_CommLineTmp ) {
			e_CommLineTmp = TYPE_CommLine1;
		}
		//	// 回線1の回線種別を取得
		e_DialMethod = pc_FaxGfpSetting->getDialMethodAll( e_CommLineTmp );
	}
	// 押下キーで入力文字設定の処理わけ
	switch( option ) {
		case PNLD_FaxKeyAsterisk:	// 「*」キー押下時
			// 再入力実行画面毎で入力処理を行う
			if( ( e_ReMode == PNLE_REINPUTMODE_FAX )||( e_ReMode == PNLE_REINPUTMODE_FAXENL )
			    ||( e_ReMode == PNLE_REINPUTMODE_BFAX )||( e_ReMode == PNLE_REINPUTMODE_JFAX ) ) {
				// PB回線以外において「T」非表示で「＊」キー押下された場合
				if( ( e_DialMethod != TYPE_DialMethod_PB )
				    && ( uc_pos == ss_strLen ) ) {
					if( True == onlyPanel.isFaxServerEnable() ) {
						// Prefix/Suffixを使用する場合、* キー押下で * を入力する.
						uc_text[0] = '*';
						bl_showTone = False;	// CQ.317199 'T'の場合のみトーンと読み上げるようにする.
					} else {
						uc_text[0] = 'T';
						bl_showTone = True;		// CQ.317199 'T'の場合のみトーンと読み上げるようにする.
					}
				} else {
					uc_text[0] = '*';
				}
			} else {
				// 無条件で「*」を入力する
				uc_text[0] = '*';
			}
			break;
		case PNLD_FaxKeySharp:	// 「#」キー押下時
			// 再入力実行画面毎で入力処理を行う
			if( ( e_ReMode == PNLE_REINPUTMODE_FAX )||( e_ReMode == PNLE_REINPUTMODE_FAXENL )
			    ||( e_ReMode == PNLE_REINPUTMODE_BFAX )||( e_ReMode == PNLE_REINPUTMODE_JFAX ) ) {
				// PB回線以外において「T」非表示で「#」キー押下された場合
				if( ( e_DialMethod != TYPE_DialMethod_PB )
				    && ( uc_pos == ss_strLen ) ) {
					// 受付不可
				} else {
					uc_text[0] = '#';
				}
			} else {
				// 無条件で「#」を入力する
				uc_text[0] = '#';
			}
			break;
		default: uc_text[0] = (uchar)( 0x30 + option ); break;	// 「0」～「9」押下時
	}
	if( uc_text[0] == '\0' ) {
		// 受付不可
		b_result = False;
	} else {
		// uc_textに設定された文字列をカーソル位置に挿入する
		c_SlideTextMgr.insertStr( sc_FaxReInputStr, ( char* )uc_text );
		// 受付OK
		b_result = True;
	}
	return b_result;
}
//================================================================================================
// 概要    :ダブルダイアル::特殊キー押下処理（「T」「P」「-」）
// 戻り値  :Bool   True 入力受付/False 受付不可
//================================================================================================
Bool PNLC_DoubleDial::InputSpecialKey( uchar uc_text )
{
	Bool  b_result =  False;	// 判定結果
	uchar  uc_InputText[2];
	memset( uc_InputText, '\0', sizeof( uc_InputText ) );
	// MAXサイズまで入力されていない
	if( strlen( sc_FaxReInputStr ) < TYPD_MaxStrFaxDialNo ) {
		if( uc_text == 'T' ) {
			// 「T」が入力されているか
			if( NULL == strchr( sc_FaxReInputStr, 'T' ) ) {
				// 「T」未入力時は「T」をセットする
				uc_InputText[0] = uc_text;
			}
		} else {
			// 「P」「-」は常時受け付け
			uc_InputText[0] = uc_text;
		}
		// 入力文字列が有効ならば
		if( uc_InputText[0] != '\0' ) {
			// 文字列を挿入する
			c_SlideTextMgr.insertStr( sc_FaxReInputStr, ( char* )uc_InputText );
			b_result = True;
		}
	}
	return b_result;
}
//================================================================================================
// 概要    :ダブルダイアル::入力宛先クリア処理
// 戻り値  :Bool   True クリア受付/False クリア不可
//================================================================================================
Bool PNLC_DoubleDial::initDialDisp()
{
	Bool  b_result =  False;	// 判定結果
	if( Ctf_ReDialField38 == NULL ) {
		LOGF_debug_PutEventLog( LOGF_DEBUG_EVENT_KIND_ALL, 0, LOGD_DEBUG_LEVEL_UNKNOWN, "Assert Failed!" );
		return b_result;
	}
	// 再入力宛先が何か入力されているとき
	if( sc_FaxReInputStr[0] != '\0' ) {
		memset( sc_FaxReInputStr, '\0', sizeof( sc_FaxReInputStr ) );
		b_result = True;
		// スライドクラスの初期設定
		switch( e_ReMode ) {
			case PNLE_REINPUTMODE_FAX:
			case PNLE_REINPUTMODE_FAXENL:
			case PNLE_REINPUTMODE_POG:
				if( onlyPanel.bl_isEnlargeDisplayMode != True ) {
					// 通常
					c_SlideTextMgr.init_CLCD( sc_FaxReInputStr, PNLD_MaxFaxNumDispSize,
					                          TYPD_MaxStrFaxDialNo, Ctf_ReDialField38, EP_CharSet_USASCII );
				} else {
					// 拡大
					c_SlideTextMgr.init_CLCD( sc_FaxReInputStr, PNLD_MaxFaxNumDispSizeEnl,
					                          TYPD_MaxStrFaxDialNo, Ctf_ReDialField38, EP_CharSet_USASCII );
				}
				break;
			case PNLE_REINPUTMODE_BFAX:
			case PNLE_REINPUTMODE_JFAX:
				c_SlideTextMgr.init_CLCD( sc_FaxReInputStr, PNLD_MaxFaxNumDispSize,
				                          TYPD_MaxStrFaxDialNo, Ctf_ReDialField38, EP_CharSet_USASCII );
				break;
			case PNLE_REINPUTMODE_SETTING:
			case PNLE_REINPUTMODE_ADDRREG:
				c_SlideTextMgr.init_CLCD( sc_FaxReInputStr, TYPD_MaxStrFaxDialNo,
				                          TYPD_MaxStrFaxDialNo, Ctf_ReDialField38, EP_CharSet_USASCII );
				break;
			default: b_result = False; break;
		}
	}
	return b_result;
}
