// ==================================================================
// 概要		：左エリア用ボックス情報クラス : ボックス名称を取得する.
// ==================================================================
void TYPC_LeftAreaBoxInfo::getBoxName( char* sc_Name, short ss_size ) {
	if( NULL != sc_Name ) {
		if( 0 > sc_BoxType ) { getBoxInfoFromDoc(); }	// 詳細情報未取得の場合、詳細情報を取得する.
		char sc_BoxName[APID_BoxNameMax];
		memset( sc_BoxName, 0, APID_BoxNameMax );
		// c_BoxInfo.sc_BoxNameには、最大で(APID_BoxNameMax-1)byteが設定される.
		// よって、終端'\0'はsc_BoxNameに必ず付加される.
		strncpy( sc_BoxName, c_BoxInfo.sc_BoxName, sizeof( sc_BoxName )-1 );
		if( 0 == strlen( sc_BoxName ) ) {	// ボックス名が空の場合、新規ボックスとみなす.
			snprintf( sc_BoxName, sizeof(sc_BoxName), "%09d", sl_BoxNo );
		}
		setupInputString( 1, ss_size, sc_BoxName, sc_Name, 0, getCharSetForPanel() );
	}
}

