// 概要		：左エリア用ボックス情報クラス : ボックス種別を取得する.
// ==================================================================
char TYPC_LeftAreaBoxInfo::getBoxType() {
	if( 0 > sc_BoxType ) { getBoxInfoFromDoc(); }		// 詳細情報未取得の場合、詳細情報を取得する.
	return ( sc_BoxType );
}

// ==================================================================
// 概要		：左エリア用ボックス情報クラス : ボックスアイコンを取得する.
// ==================================================================
const uchar* TYPC_LeftAreaBoxInfo::getBoxTypeIcon() {
	if( 0 > sc_BoxType ) { getBoxInfoFromDoc(); }		// 詳細情報未取得の場合、詳細情報を取得する.
	const uchar* puc_RetIconGraphic = PG_LeftArea_Stored_PublicBox_X016_Y016;
	switch( sc_BoxType ) {
		case APIE_BoxmakerAuto: puc_RetIconGraphic = PG_LeftArea_Stored_PublicBox_X016_Y016; break;		// 共有ボックス.
		case APIE_BoxmakerUser: puc_RetIconGraphic = PG_LeftArea_Stored_PersonalBox_X016_Y016; break;	// 個人ボックス.
		case APIE_BoxmakerGroup: puc_RetIconGraphic = PG_LeftArea_Stored_GroupBox_X016_Y016; break;		// グループボックス.
		default: break;
	}
	return ( puc_RetIconGraphic );
}

// ==================================================================
// 概要		：左エリア用ボックス情報クラス : 詳細情報取得.
// ==================================================================
void TYPC_LeftAreaBoxInfo::getBoxInfoFromDoc() {
	PanelLog( PNLD_LogKind_Box, "setBoxId: P1[%d]", sl_BoxNo, 0, 0, 0, 0, 0 );
// Commment 2017/09/22 HCL_Venkataramesh [IT5_4.2][RQ-686][WP689] setBoxId support for Network2 user.
//	cp_DocList->setBoxId( sl_BoxNo );
	PNLC_NetworkLan::getInstance()->setBoxIdPNL( cp_DocList, sl_BoxNo );
	int32_t i32_isOk = 0;
	if( False != PLBC_FuncVersionCheck::isOK_Type3() ) {				// Donau拡張機能3、Amur機能拡張2以降.
		PanelLog( PNLD_LogKind_Admin, "getBoxInfo: P1[%p] P2[%p] P3[%d]", NULL, &c_BoxInfo, -1, 0, 0, 0 );
		i32_isOk = cp_DocList->getBoxInfo( NULL, &c_BoxInfo, LIBE_CharSetDefault );	// ボックス情報を取得する.
	} else {
		PanelLog( PNLD_LogKind_Admin, "getBoxInfo: P1[%p] P2[%p] P3[%d]", NULL, &c_BoxInfo, getCharSetForCAPI(), 0, 0, 0 );
		i32_isOk = cp_DocList->getBoxInfo( NULL, &c_BoxInfo, ( LIBE_CharSet )getCharSetForCAPI() );	// ボックス情報を取得する.
	}
	if( APID_DocapiMethodOk == i32_isOk ) {
		APIC_BoxOption c_BoxOption;
		APIC_User* pc_Admin = APIC_User::newInstance( TYPD_IndexUserAdmin );
		PanelLog( PNLD_LogKind_Box, "getBoxOption: P1[%p] P2[%s] P3[%p]", pc_Admin, "NULL", &c_BoxOption, 0, 0, 0 );
		cp_DocList->getBoxOption( pc_Admin, NULL, &c_BoxOption );									// 管理者権限にてボックス情報(オプション)を取得する.
		sc_BoxType = c_BoxOption.sl_BoxCreateInfo;												// ボックス種別を設定する.
	}
}

// ==================================================================
// 概要		：左エリア用ボックス情報リスト管理クラス : 唯一インスタンス.
// ==================================================================
TYPC_LeftAreaBoxInfoControl TYPC_LeftAreaBoxInfoControl::s_OnlyInstance( TYPD_MaxDirectBoxAddress );
// ==================================================================
// 概要		：左エリア用ボックス情報リスト管理クラス : 管理クラスインスタンス取得(Singleton風).
// ==================================================================
TYPC_LeftAreaBoxInfoControl* TYPC_LeftAreaBoxInfoControl::getInstance() {
	return ( &s_OnlyInstance );
}

// ==================================================================
// 概要		：左エリア用ボックス情報リスト管理クラス : リストクリア.
// ==================================================================
void TYPC_LeftAreaBoxInfoControl::resetAllBoxInfo() {
	s_LeftAreaBoxInfoList.resetAllNode();							// 左エリア用選択ボックスリストをクリアする.
	us_EffectivePosition = TYPD_BroadcastAddressEffectiveStart;		// 走査対象の先頭アドレスを初期化する.
	us_SelectedBox = TYPD_NotSelectBroadcastAddress;				// 非選択状態にする.
}

// ==================================================================
// 概要		：左エリア用ボックス情報リスト管理クラス : 要素取得(操作範囲内インデックス指定).
// ==================================================================
void TYPC_LeftAreaBoxInfoControl::getLeftAreaBoxInfo( TYPC_LeftAreaBoxInfo& s_Info, const ushort& us_Num ) {
	if( 0 == us_Num || us_Num > us_EffectiveRange ) {				// 引数の妥当性を確認する.
		PnlComPutDebugLog( True, UC_PNL_LOGPATTERN_1, "TYPC_LeftAreaBoxInfoControl::getLeftAreaBoxInfo", UC_PNL_ERROR_PARAMETER );
		return;
	}
	const ushort us_Index = (ushort)( us_EffectivePosition + ( us_Num - 1 ) );	// インデックスを取得する.
	if( us_Index > s_LeftAreaBoxInfoList.getNodeSize() ) {
		PnlComPutDebugLog( True, UC_PNL_LOGPATTERN_1, "TYPC_LeftAreaBoxInfoControl::getLeftAreaBoxInfo", UC_PNL_ERROR_PARAMETER );
		return;
	}
	s_LeftAreaBoxInfoList.getNode( s_Info, us_Index );				// 左エリア用選択ボックス情報を取得する.
}


// ==================================================================
// 概要		：左エリア用ボックス情報リスト管理クラス : 選択中の要素取得.
// ==================================================================
Bool TYPC_LeftAreaBoxInfoControl::getSelectedLeftAreaBoxInfo( TYPC_LeftAreaBoxInfo& s_Info ) {
	if( TYPD_NotSelectBroadcastAddress == us_SelectedBox ) { return ( False ); }
	if( us_SelectedBox > s_LeftAreaBoxInfoList.getNodeSize() ) {
		PnlComPutDebugLog( True, UC_PNL_LOGPATTERN_1, "TYPC_LeftAreaBoxInfoControl::getSelectedLeftAreaBoxInfo", UC_PNL_ERROR_IMPOSSIBLE );
		return ( False );
	}
	s_LeftAreaBoxInfoList.getNode( s_Info, us_SelectedBox );
	return ( True );
}

// ==================================================================
// 概要		：左エリア用ボックス情報リスト管理クラス : 要素数取得.
// ==================================================================
ushort TYPC_LeftAreaBoxInfoControl::getLeftAreaBoxInfoCount() {
	return ( s_LeftAreaBoxInfoList.getNodeSize() );
}

// ==================================================================
// 概要		：左エリア用ボックス情報リスト管理クラス : 操作対象の先頭インデックス取得.
// ==================================================================
ushort TYPC_LeftAreaBoxInfoControl::getEffectivePosition() const {
	return ( us_EffectivePosition );
}

// ==================================================================
// 概要		：左エリア用ボックス情報リスト管理クラス : 操作対象変更[ページ移動(前へ)].
// ==================================================================
Bool TYPC_LeftAreaBoxInfoControl::moveBeforeEffectivePosition() {
	Bool b_Ret = False;
	if( us_EffectiveRange < us_EffectivePosition ) {
		us_EffectivePosition = (ushort)( us_EffectivePosition - us_EffectiveRange );
		b_Ret = True;
	}
	return b_Ret;
}

// ==================================================================
// 概要		：左エリア用ボックス情報リスト管理クラス : 操作対象変更[ページ移動(次へ)].
// ==================================================================
Bool TYPC_LeftAreaBoxInfoControl::moveNextEffectivePosition() {
	Bool b_Ret = False;
	if( us_EffectiveRange < us_EffectivePosition ) {
		us_EffectivePosition = (ushort)( us_EffectivePosition - us_EffectiveRange );
		b_Ret = True;
	}
	return b_Ret;
}

// ==================================================================
// 概要		：左エリア用ボックス情報リスト管理クラス : 要素選択.
// ==================================================================
void TYPC_LeftAreaBoxInfoControl::selectLeftAreaBoxInfo( const ushort& us_Index ) {
	if( ( 0 == us_Index ) || ( us_EffectiveRange < us_Index ) ) {
		PnlComPutDebugLog( True, UC_PNL_LOGPATTERN_1, "TYPC_LeftAreaBoxInfoControl::selectLeftAreaBoxInfo", UC_PNL_ERROR_PARAMETER );
		return;
	}
	const ushort us_SelectAddress = (ushort)( us_EffectivePosition + ( us_Index - 1 ) );
	if( us_SelectAddress > s_LeftAreaBoxInfoList.getNodeSize() ) {
		PnlComPutDebugLog( True, UC_PNL_LOGPATTERN_1, "TYPC_LeftAreaBoxInfoControl::selectLeftAreaBoxInfo", UC_PNL_ERROR_IMPOSSIBLE );
		return;
	}
	us_SelectedBox = ( ( us_SelectAddress == us_SelectedBox ) ? TYPD_NotSelectBroadcastAddress : us_SelectAddress );
}

// ==================================================================
// 概要		：左エリア用ボックス情報リスト管理クラス : インデックス取得.
// ==================================================================
ushort TYPC_LeftAreaBoxInfoControl::getSelectedEffectiveIndex() {
	if( TYPD_NotSelectBroadcastAddress == us_SelectedBox ) { return ( us_SelectedBox ); }
	if( ( us_EffectivePosition <= us_SelectedBox ) && ( ( us_EffectivePosition + us_EffectiveRange ) > us_SelectedBox ) ) {
		return (ushort)( ( us_SelectedBox - us_EffectivePosition ) + 1 );
	}
	return ( TYPD_NotSelectBroadcastAddress );
}

// ==================================================================
// 概要		：左エリア用ボックス情報リスト管理クラス : 要素追加.
// ==================================================================
void TYPC_LeftAreaBoxInfoControl::setLeftAreaBoxInfo( const int32_t& sl_Num ) {
	const ushort us_BoxCount = s_LeftAreaBoxInfoList.getNodeSize();
	ushort us_Index = 1;
	for( us_Index = 1; us_BoxCount >= us_Index; ++us_Index ) {
		TYPC_LeftAreaBoxInfo s_LeftAreaBoxInfo;
		s_LeftAreaBoxInfoList.getNode( s_LeftAreaBoxInfo, us_Index );
		if( sl_Num == s_LeftAreaBoxInfo.getBoxNo() ) { break; }
	}
	if( us_BoxCount < us_Index ) {
		TYPC_LeftAreaBoxInfo s_LeftAreaBoxInfo;
		s_LeftAreaBoxInfo.setBoxNo( sl_Num );
		s_LeftAreaBoxInfoList.addNode( s_LeftAreaBoxInfo );
	}
}

// ==================================================================
// 概要		：左エリア用ボックス情報リスト管理クラス : 要素削除.
// ==================================================================
void TYPC_LeftAreaBoxInfoControl::deleteLeftAreaBoxInfo( const int32_t& sl_Num ) {
	const ushort us_BoxCount = s_LeftAreaBoxInfoList.getNodeSize();
	ushort us_Index = 1;
	for( us_Index = 1; us_BoxCount >= us_Index; ++us_Index ) {
		TYPC_LeftAreaBoxInfo s_LeftAreaBoxInfo;
		s_LeftAreaBoxInfoList.getNode( s_LeftAreaBoxInfo, us_Index );
		if( sl_Num == s_LeftAreaBoxInfo.getBoxNo() ) { break; }
	}
	if( us_Index <= us_BoxCount ) {
		s_LeftAreaBoxInfoList.deleteNode( us_Index );
		if( us_Index == us_SelectedBox ) { us_SelectedBox = TYPD_NotSelectBroadcastAddress; }
		if( TYPD_BroadcastAddressEffectiveStart != us_EffectivePosition
		    && s_LeftAreaBoxInfoList.getNodeSize() < us_EffectivePosition ) {
			us_EffectivePosition = (ushort)( us_EffectivePosition - us_EffectiveRange );
		}
	}
}

// ==================================================================
// 概要		：USBメモリ内のファイルをあらわすクラス : ファイル名を設定する.
// ==================================================================
void TYPC_USBFileInfo::setFileName( const char* pszFileName ) {
	if( NULL == pszFileName ) {
		PnlComPutDebugLog( True, UC_PNL_LOGPATTERN_1, "TYPC_USBFileInfo::setFileName", UC_PNL_ERROR_PARAMETER );
		return;
	}
	Bool b_FoundDot = False;
	short ss_ExtIndex = 0;
	for( short i = 0; TYPD_MAX_USB_FILE_NAME_LEN > i; ++i ) {
		sc_FileName[i] = pszFileName[i];
		if( True == b_FoundDot && TYPD_MAX_USB_FILE_EXT_LEN > ss_ExtIndex ) {
			sc_FileExt[ss_ExtIndex++] = ( char )tolower( pszFileName[i] );
		}
		if( '.' == pszFileName[i] ) {					// ドット以降を拡張子とみなす.
			ss_ExtIndex = 0;
			b_FoundDot = True;
		}
		if( '\0' == pszFileName[i] ) { break; }			// 終端までコピーする.
	}
}

// ==================================================================
// 概要		：USBメモリ内のファイルをあらわすクラス : ファイルパスを設定する.
// ==================================================================
void TYPC_USBFileInfo::setFilePath( const char* pszFilePath ) {
	if( NULL == pszFilePath ) {
		PnlComPutDebugLog( True, UC_PNL_LOGPATTERN_1, "TYPC_USBFileInfo::setFilePath", UC_PNL_ERROR_PARAMETER );
		return;
	}
	for( short i = 0; TYPD_MAX_USB_FILE_PATH_LEN > i; ++i ) {
		sc_FilePath[i] = pszFilePath[i];
		if( '\0' == pszFilePath[i] ) { break; }
	}
}

