{
	if( NULL == pszFileExt ) {
		PnlComPutDebugLog( True, UC_PNL_LOGPATTERN_1, "TYPC_USBFileInfo::setFileExt", UC_PNL_ERROR_PARAMETER );
		return;
	}
	for( short i = 0; TYPD_MAX_USB_FILE_EXT_LEN > i; ++i ) {
		sc_FileExt[i] = pszFileExt[i];
		if( '\0' == pszFileExt[i] ) {
			break;
		}
	}
}

