// ==================================================================
// 概要		：USBメモリ内のファイルをあらわすクラス : ファイル名を取得する.
// ==================================================================
void TYPC_USBFileInfo::getFileName( char* pszFileName, const short& ss_Size ) const {
	if( NULL == pszFileName ) {
		PnlComPutDebugLog( True, UC_PNL_LOGPATTERN_1, "TYPC_USBFileInfo::getFileName", UC_PNL_ERROR_PARAMETER );
		return;
	}
	short ss_MaxSize = TYPD_MAX_USB_FILE_NAME_LEN;
	if( TYPD_MAX_USB_FILE_NAME_LEN > ss_Size ) { ss_MaxSize = ss_Size; }
	short i = 0;
	for( i = 0; ss_MaxSize > i; ++i ) {
		pszFileName[i] = sc_FileName[i];
		if( '\0' == sc_FileName[i] ) { break; }
	}
	if( 0 < i && i == ss_Size ) { pszFileName[i - 1] = '\0'; }
}

