int32_t TYPC_USBFileInfo::getFileSize() const {
	return ( sl_FileSize );
}

// ==================================================================
// 概要		：USBメモリ内のファイルをあらわすクラス : 代入演算子をあらわす.
// ==================================================================
TYPC_USBFileInfo& TYPC_USBFileInfo::operator=( const TYPC_USBFileInfo& obj ) {
	if( sc_FileName != obj.sc_FileName ) {
		setFileName( obj.sc_FileName );
		setFilePath( obj.sc_FilePath );
		setFileSize( obj.sl_FileSize );
	}
	return ( *this );
}

