// ==================================================================
// 概要		：USBメモリ内のファイル情報を管理するクラス : 管理クラスインスタンス取得(Singleton風).
// ==================================================================
TYPC_USBFileControl* TYPC_USBFileControl::getInstance() {
	return ( &s_OnlyInstance );
}

// ==================================================================
// 概要		：USBメモリ内のファイル情報を管理するクラス : リストクリア.
// ==================================================================
void TYPC_USBFileControl::resetAllFiles() {
	s_USBFileInfoList.resetAllNode();		// USBメモリ内のファイルリストをクリアする.
	us_EffectivePosition = 1;				// 操作対象の先頭アドレスを初期化する.
}

// ==================================================================
// 概要		：USBメモリ内のファイル情報を管理するクラス : 要素取得(操作範囲内インデックス指定).
// ==================================================================
void TYPC_USBFileControl::getUSBFileInfo( TYPC_USBFileInfo& s_Info, const ushort& us_Num ) {
	if( 0 == us_Num || us_Num > us_EffectiveRange ) {				// 引数の妥当性を確認する.
		PnlComPutDebugLog( True, UC_PNL_LOGPATTERN_1, "TYPC_USBFileControl::getUSBFileInfo", UC_PNL_ERROR_PARAMETER );
		return;
	}
	const ushort us_Index = (ushort)( us_EffectivePosition + ( us_Num - 1 ) );	// インデックスを取得する.
	if( us_Index > s_USBFileInfoList.getNodeSize() ) {
		PnlComPutDebugLog( True, UC_PNL_LOGPATTERN_1, "TYPC_USBFileControl::getUSBFileInfo", UC_PNL_ERROR_PARAMETER );
		return;
	}
	s_USBFileInfoList.getNode( s_Info, us_Index );
}

// ==================================================================
// 概要		：USBメモリ内のファイル情報を管理するクラス : 要素数取得.
// ==================================================================
ushort TYPC_USBFileControl::getUSBFileInfoCount() {
	return ( s_USBFileInfoList.getNodeSize() );
}

// ==================================================================
// 概要		：USBメモリ内のファイル情報を管理するクラス : 要素追加.
// ==================================================================
void TYPC_USBFileControl::setUSBFileInfo( const TYPC_USBFileInfo& s_Info ) {
	char sc_FilePath1[TYPD_MAX_USB_FILE_PATH_LEN];
	char sc_FilePath2[TYPD_MAX_USB_FILE_PATH_LEN];
	memset( sc_FilePath1, '\0', TYPD_MAX_USB_FILE_PATH_LEN );
	memset( sc_FilePath2, '\0', TYPD_MAX_USB_FILE_PATH_LEN );
	s_Info.getFilePath( sc_FilePath1, TYPD_MAX_USB_FILE_PATH_LEN );
	const ushort us_FileCount = s_USBFileInfoList.getNodeSize();
	ushort us_Index = 1;
	for( us_Index = 1; us_FileCount >= us_Index; ++us_Index ) {
		TYPC_USBFileInfo s_USBFileInfo;
		s_USBFileInfoList.getNode( s_USBFileInfo, us_Index );
		s_USBFileInfo.getFilePath( sc_FilePath2, TYPD_MAX_USB_FILE_PATH_LEN );
		if( 0 == strncmp( sc_FilePath1, sc_FilePath2, TYPD_MAX_USB_FILE_PATH_LEN ) ) { break; }
	}
	if( us_FileCount < us_Index ) {
		s_USBFileInfoList.addNode( s_Info );
	}
}

// ==================================================================
// 概要		：USBメモリ内のファイル情報を管理するクラス : 要素削除.
// ==================================================================
void TYPC_USBFileControl::deleteUSBFileInfo( const char* pszFilePath ) {
	char sc_FilePath[TYPD_MAX_USB_FILE_PATH_LEN];
	memset( sc_FilePath, '\0', TYPD_MAX_USB_FILE_PATH_LEN );
	const ushort us_FileCount = s_USBFileInfoList.getNodeSize();
	ushort us_Index = 1;
	for( us_Index = 1; us_FileCount >= us_Index; ++us_Index ) {
		TYPC_USBFileInfo s_USBFileInfo;
		s_USBFileInfoList.getNode( s_USBFileInfo, us_Index );
		s_USBFileInfo.getFilePath( sc_FilePath, TYPD_MAX_USB_FILE_PATH_LEN );
		if( 0 == strncmp( sc_FilePath, pszFilePath, TYPD_MAX_USB_FILE_PATH_LEN ) ) { break; }
	}
	if( us_FileCount >= us_Index ) {
		s_USBFileInfoList.deleteNode( us_Index );
		if( 1 != us_EffectivePosition
		    && s_USBFileInfoList.getNodeSize() < us_EffectivePosition ) {
			us_EffectivePosition = (ushort)( us_EffectivePosition - us_EffectiveRange );
		}
	}
}

// ===============================================================================================
//	概要    ：表示可能なサーバー名称か.
//	戻り値  ：Bool : True：表示する False：表示しない.
// ===============================================================================================
Bool isShowUserAccountDomainName( APIS_AuthenticationServerInfo srv_info_buf )
{
	if( True == PLBC_FuncPKICheck::isPKI() ) {
		if( TYPE_AuthenticationServerTypeActiveDirectory != srv_info_buf.e_ServerType ) {
			return False;
		}
	}

	Bool bl_result = True;
	Bool b_NDSAuthTcp = False;	// NDSoverTCP/IP.
	Bool b_NDSAuthIpx = False;	// NDSoverIPX.
	if( True == PnlComGetNetWareSetting()->getEnableAuthentication() ) {
// comment 2017/11/23 【HCL-Suganya】【IT5_4.2】【RQ686】 Multiple Network Support.
//		if( True == PnlComGetTcpIpSetting()->getEnableTCPIP() ) {		// NetWare ユーザ認証設定が「True」& TCP/IP設定が「True」の場合.
		if( True == PnlComGetTcpIpSetting()->getEnableTCPIP( PNLC_NetworkLan::getInstance()->getLine() ) ) {		// NetWare ユーザ認証設定が「True」& TCP/IP設定が「True」の場合.
			b_NDSAuthTcp = True;	// NDSoverTCP/IPをデフォルトに出来る.
		}
		if( True == PnlComGetNetWareSetting()->getEnableIPX() ) {		// NetWare ユーザ認証設定が「True」& IPX設定が「True」の場合.
			b_NDSAuthIpx = True;	// NDSoverIPXをデフォルトに出来る.
		}
	}
//Comment 2017/09/04 [HCL-Suribabu][IT5_4.2][RQ-686][WP914]The new API is used and to detect the current network type, new API arguments are passed.
//	Bool b_NTLMAuth = PnlComGetSmbPrintSetting()->getEnableNTLM();			// ユーザー認証(NTLM).
	Bool b_NTLMAuth = PnlComGetSmbPrintSetting()->getEnableNTLM( PNLC_NetworkLan::getInstance()->getLine() );			// ユーザー認証(NTLM).
	if( ( ( TYPE_AuthenticationServerTypeSMB == srv_info_buf.e_ServerType || TYPE_AuthenticationServerTypeNTLMv2 == srv_info_buf.e_ServerType ) && False == b_NTLMAuth )
	    ||( TYPE_AuthenticationServerTypeNDS == srv_info_buf.e_ServerType && False == b_NDSAuthIpx )
	    ||( TYPE_AuthenticationServerTypeNDSOverTCPIP == srv_info_buf.e_ServerType && False == b_NDSAuthTcp ) ) {
		bl_result = False;
	} else {
		bl_result = True;
	}
	return bl_result;
}
// ===============================================================================================
//	概要    ：送信結果レポートが出力される宛先かを判定する.
//	戻り値  ：Bool : True：出力される False：出力されない.
// ===============================================================================================
Bool isReportOutputAddress( TYPC_JobSpec* pc_JobSpec )
{
	if( NULL == pc_JobSpec ) { return True; }	// ジョブスペックがNULLであった場合は、従来通り、何でも出力されることとする.
	ushort us_Cnt = 0;
	TYPE_SendMode e_SendMode;										// 宛先種別.
	ushort us_SelShorternNum = ( ushort )pc_JobSpec->pc_Send->c_ComSend.getSelecShorteningAddressCount();		// 短縮宛先件数.
	for( us_Cnt = 1; us_Cnt <= us_SelShorternNum; us_Cnt++ ) {
		//短縮宛先取得.
		TYPC_ShorteningAddress* AddressBook = pc_JobSpec->pc_Send->c_ComSend.getShorteningAddressData( us_Cnt );
		if( NULL == AddressBook ) { return True; }
		// 宛先種別の取得.
		e_SendMode = AddressBook->getSendMode();
		switch( e_SendMode ) {
			case TYPE_SendModeFax:			// Ｇ３ＦＡＸ送信.
			case TYPE_SendModeIfax:			// Ｉ－ＦＡＸ送信.
			case TYPE_SendModeIPAddressFax:	// IPアドレスファクス送.
			case TYPE_SendModeIPFax:		// IP-Fax(T.38)送信.		// comment 2019/02/27 SCD2-Sky中野 [EagleH][RQ-272] Fax機能をもつ全製品のT38Faxプロトコルの対応.
				// 短縮宛先で一つでもファクス宛先が選ばれていたらレポート出力あり.
				return True;
			default:
				break;
		}
	}
	for( us_Cnt = 1; us_Cnt <= TYPD_MaxDirectMailAddress; us_Cnt++ ) {
		if( True == pc_JobSpec->pc_Send->c_ComSend.c_DirectAddressBook.pageMailAddress( us_Cnt )->getOn() ) {
			if( TYPE_SendModeIPAddressFax == pc_JobSpec->pc_Send->c_ComSend.c_DirectAddressBook.pageMailAddress( us_Cnt )->getSendMode()
// comment 2019/02/27 SCD2-Sky中野 [EagleH][RQ-272] Fax機能をもつ全製品のT38Faxプロトコルの対応 判定条件にIP-FAX(T.38)の条件を追加.
			    || ( TYPE_SendModeIfax == pc_JobSpec->pc_Send->c_ComSend.c_DirectAddressBook.pageMailAddress( us_Cnt )->getSendMode() )
			    || ( TYPE_SendModeIPFax == pc_JobSpec->pc_Send->c_ComSend.c_DirectAddressBook.pageMailAddress( us_Cnt )->getSendMode() ) ) {
				// 直接入力にファクス宛先が一つでも選ばれていたらレポート出力あり.
				return True;
			}
		}
	}
	for( us_Cnt = 1; us_Cnt <= TYPD_MaxDirectFaxAddress; us_Cnt++ ) {
		if( True == pc_JobSpec->pc_Send->c_ComSend.c_DirectAddressBook.pageFaxAddress( us_Cnt )->getOn() ) {
			// 直接入力にファクス宛先が一つでも選ばれていたらレポート出力あり.
			return True;
		}
	}
	return False;
}
// ==================================================================
// 概要		：宛先文字列がE-mail形式かを判定する.
// ==================================================================
Bool PnlComIsEmailAddress( const char* str )
{
	int ix=0;
	while( str[ix] != NULL ) {
		if( str[ix] == '@' ) { return True; }
		ix++;
	}

	return False;
}

// ==================================================================
// 概要		：E-mail宛先チェック.
// ==================================================================
Bool isEmailAddressCheck( const char* sc_String )
{
//	// アカウント文字数の最大PCGD_IP_EMAILADDRESS_ACCOUNT_MAX。ドメイン文字数の最大PCGD_IP_EMAILADDRESS_DOMAIN_MAX.
	ushort us_AccountLen = (ushort)strcspn( sc_String, "@" );
	short  ss_DomainLen  = (short)( strlen( sc_String ) - us_AccountLen - strlen( "@" ) );

	// アカウント文字数の最大PCGD_IP_EMAILADDRESS_ACCOUNT_MAX。ドメイン文字数の最大PCGD_IP_EMAILADDRESS_DOMAIN_MAX.
	if( ( PCGD_IP_EMAILADDRESS_ACCOUNT_MAX >= us_AccountLen ) &&
	    ( PCGD_IP_EMAILADDRESS_DOMAIN_MAX  >= ss_DomainLen ) ) {
		return True;
	}

	return False;
}


