	bl_BrowserStartUpFlag = False;					// ブラウザ起動フラグ.
	uc_EventID = PNLE_BrowserEndEvtID_Invalid;		// 無効なイベントID..
	uc_BrwStartMode = PNLE_BrwStartMode_Normal;		// 通常起動モード.
	memset( &s_BrwRebootSettingInfo, 0x00, sizeof( s_BrwRebootSettingInfo ) );
