// ===============================================================================================
//	［クラス］PNLC_BrowUserInfoManager：ブラウザユーザー情報管理クラス.
//	概要     : ブラウザユーザー情報の読込み要求.
//	作成者   : 13松尾.
// ----------+------------+--------+--------------------------------------------------------------
// ----------+------------+--------+--------------------------------------------------------------
// ===============================================================================================
void PNLC_BrowUserInfoManager::reqReadBrowUserInfo()
{
	// 状態チェック.
	if( PNLE_BrowState_Idle != uc_State ) {
		SYSF_logMsg( "◆状態：状態チェックエラー：PNLE_BrowState_Idle以外\n", 0,0,0,0,0,0 );
		// アサート.
		LOGF_debug_PutEventLog( LOGF_DEBUG_EVENT_KIND_ALL, 0, LOGD_DEBUG_LEVEL_UNKNOWN, "Assert Failed!" );
		return;
	}
	else {
		if( NULL != pt_APIC_Browsr_req_ReadBrowserUserInfo ) {
			// ブラウザユーザー情報読込み要求.
			if( False == ( ( Bool( * )( void ( * pCallbackFunc )( uchar ) ) )pt_APIC_Browsr_req_ReadBrowserUserInfo )( PNLC_BrowUserInfoManager::ans_BrowUserInfoAccessCallBack ) ) {
				// アサート.
				LOGF_debug_PutEventLog( LOGF_DEBUG_EVENT_KIND_ALL, 0, LOGD_DEBUG_LEVEL_UNKNOWN, "Assert Failed!" );
				return;
			}



			// ブラウザユーザー情報読込み要求中状態設定.
			setState( PNLE_BrowState_ReqReadBrowUserInfo );
		}
		else {
			SYSF_logMsg( "ロード失敗：pt_APIC_Browsr_req_ReadBrowserUserInfo = NULL\n", 0,0,0,0,0,0 );
		}
	}
}

// ===============================================================================================
//	［クラス］PNLC_BrowUserInfoManager：ブラウザユーザー情報管理クラス.
//	概要     : ブラウザユーザー情報の書込み要求.
//	作成者   : 13松尾.
// ----------+------------+--------+--------------------------------------------------------------
// ----------+------------+--------+--------------------------------------------------------------
// ===============================================================================================
void PNLC_BrowUserInfoManager::reqWriteBrowUserInfo()
{

	// 状態チェック.
	if( PNLE_BrowState_Idle != uc_State ) {
		// アサート.
		LOGF_debug_PutEventLog( LOGF_DEBUG_EVENT_KIND_ALL, 0, LOGD_DEBUG_LEVEL_UNKNOWN, "Assert Failed!" );
		return;
	}
	else {
		if( NULL != pt_APIC_Browsr_req_WriteBrowserUserInfo ) {
			// ブラウザユーザー情報書込み要求.
			if( False == ( ( Bool( * )( void ( * pCallbackFunc )( uchar ) ) )pt_APIC_Browsr_req_WriteBrowserUserInfo )( PNLC_BrowUserInfoManager::ans_BrowUserInfoAccessCallBack ) ) {
				// アサート.
				LOGF_debug_PutEventLog( LOGF_DEBUG_EVENT_KIND_ALL, 0, LOGD_DEBUG_LEVEL_UNKNOWN, "Assert Failed!" );
				return;
			}

			// ブラウザユーザー情報書込み要求中状態設定.
			setState( PNLE_BrowState_ReqWriteBrowUserInfo );
		}
	}

}

// ===============================================================================================
//	［クラス］PNLC_BrowUserInfoManager：ブラウザユーザー情報管理クラス.
//	概要     : 要求応答通知コールバック関数.
//	作成者   : 13松尾.
// ----------+------------+--------+--------------------------------------------------------------
// ----------+------------+--------+--------------------------------------------------------------
// ===============================================================================================
void PNLC_BrowUserInfoManager::ans_BrowUserInfoAccessCallBack( uchar uc_Option )
{

	// インスタンス取得.
	PNLC_BrowUserInfoManager* pc_BrowUserInfoMgr = PNLC_BrowUserInfoManager::getInstance();
	TYPE_PNL_CallBack ss_SendMsg = TYPE_PNL_CallBack_BrowserUserInfoReadSuccess;	// ブラウザユーザー情報読込み成功.

	switch( uc_Option ) {
		case BRWD_READ_USERINFO_COMPLETE:			// ブラウザユーザー情報の取得成功.
			// ブラウザユーザー情報読込み要求成功.
			if( PNLE_BrwStartMode_Normal != pc_BrowUserInfoMgr->getBrowserStartMode() ) {
				ss_SendMsg = TYPE_PNL_CallBack_OAPBrowUserInfoReadSuccess;	// 連携起動ブラウザユーザー情報読込み成功.
			}
			// 状態をアイドルに設定.
			pc_BrowUserInfoMgr->setState( PNLE_BrowState_Idle );
			// 読込み済みブラウザユーザー情報ありに設定.
			pc_BrowUserInfoMgr->setReadBrowUserInfo( True );
			break;

		case BRWD_READ_USERINFO_ERROR:				// ブラウザユーザー情報の取得失敗.
			if( PNLE_BrwStartMode_Normal == pc_BrowUserInfoMgr->getBrowserStartMode() ) {
				ss_SendMsg = TYPE_PNL_CallBack_BrowserUserInfoReadError;	// ブラウザユーザー情報読込み要求失敗.
			}
			else {
				ss_SendMsg = TYPE_PNL_CallBack_OAPBrowUserInfoReadError;	// 連携起動ブラウザユーザー情報読込み失敗.
			}
			// 状態をアイドルに設定.
			pc_BrowUserInfoMgr->setState( PNLE_BrowState_Idle );
			// 読込み済みブラウザユーザー情報なしに設定.
			pc_BrowUserInfoMgr->setReadBrowUserInfo( False );
			break;

		case BRWD_WRITE_USERINFO_COMPLETE:			// ブラウザユーザー情報書き込み成功.
			// ブラウザユーザー情報書込み要求成功.
			ss_SendMsg = TYPE_PNL_CallBack_BrowserUserInfoWriteSuccess;
			break;

		case BRWD_WRITE_USERINFO_ERROR:				// ブラウザユーザー情報書き込み失敗.
			// ブラウザユーザー情報書込み要求失敗.
			ss_SendMsg = TYPE_PNL_CallBack_BrowserUserInfoWriteError;
			break;

		default:
			// アサート.
			LOGF_debug_PutEventLog( LOGF_DEBUG_EVENT_KIND_ALL, 0, LOGD_DEBUG_LEVEL_UNKNOWN, "Assert Failed!" );
			break;
	}

	// ブラウザユーザー情報アクセス中解除.
	onlyPanel.resetPanelWarning( PNL_OTHER_NowAccessBrowserUserInfo );

	// 通常起動モードで初期化.
	pc_BrowUserInfoMgr->setBrowserStartMode( PNLE_BrwStartMode_Normal );

	// アクセスモード初期化
	pc_BrowUserInfoMgr->setAccessMode( PNLE_BrowUserInfoAccessNon );

	// ブラウザユーザー情報要求応答コールバック通知.
	CallBackIndi( ss_SendMsg );

}

