// 概要		: ユーザ設定キー受付けチェック(言語選択キーのショートカット用に共通関数へ).
Bool checkEnableUtilityMode()
{
	Bool _bl_result = True;
	if( False == PnlComIsMyPanel() ) {
		if( NULL == ( PUtilitySystemLanguageSet* )pt_gp_UtilitySystemLanguageSet ) {
			_bl_result = False;
		}
	} else {
		if( NULL == ( PUtilitySystemLanguageSetMyPanel* )pt_gp_UtilitySystemLanguageSetMyPanel ) {
			_bl_result = False;
		}
	}
	// 処理中、受信中、送信中（プリントジョブやリードジョブでない状態）のチェック.
	if( True == _bl_result ) {
		if( EC_IntMode_Off != onlyPanel.ec_IntMode					// 割り込み、又は、割り込み遷移中の時.
		    || True == PnlComGetSystemStatus()->isJobExist()			// ジョブの有無チェック.
		    || True == PnlComGetInterpreter()->isExistInterpreterJob()
		    || True == ppc_PrinterStatus->isPIActive()					// PIマニュアル動作中.
		    || True == PBasicMessageProc::b_isFaxLine1OffHook			// 外部電話オフフック中.
		    || True == PBasicMessageProc::b_isOffHookBtnOn				// 手動オフフック中.
		    || True == PnlComGetSystemSetting()->getLongPicturePrint()	// 長尺紙ﾌﾟﾘﾝﾄﾓｰﾄﾞ中.
		    || TYPE_ProgJobInStatusIdle != PnlComGetSystemStatus()->getProgJobInStatus()		// プログラムジョブ設定中.
		    || TYPE_ProgJobOutStatusIdle != PnlComGetSystemStatus()->getProgJobOutStatus() ) {
			_bl_result = False;
		}
	}
	// 警告関係のチェック.
	if( True == _bl_result ) {
		if( True == onlyPanel.isWarningOn( comPanelJob, PFATAL_ServiceCall )			// Fatal.
		    || True == onlyPanel.isWarningOn( comPanelJob, PFATAL_ServiceCallSMART )
		    || True == onlyPanel.isWarningOn( comPanelJob, PFATAL_ServiceCallHEART )
		    || TYPE_HddLockStatus_Locked == PnlComGetHddInfo()->getLockStatus()			// HDDロックパスワード不一致.
		    || True == PnlComGetSystemStatus()->isEncryptionKeyNG() ) {					// HDD暗号化不一致.
			_bl_result = False;
		}
	}
	if( True == _bl_result ) {
		// ERROR2.
		for( ushort i = 0; i < DEF_checkError21Tbl; i++ ) {
			if( NULL != comPrintJob && NULL != pt_checkError21Tbl && True == onlyPanel.isWarningOn( comPrintJob, ( ( TYPE_WarningName* )pt_checkError21Tbl )[i] ) ) {
				_bl_result = False;
				break;
			}
			if( NULL != pt_checkError21Tbl && True == onlyPanel.isWarningOn( comPanelJob, ( ( TYPE_WarningName* )pt_checkError21Tbl )[i] ) ) {
				// パネルジョブが警告発生中の時
				_bl_result = False;
				break;
			}
		}
	}
	return _bl_result;
}

// 概要    : 現在の濃度レベルを返す.
// 戻り値  : short  濃度レベル(0～8).
short nowSelectDensityAdjustLevel()
{
	short ss_SelectLevel = -1;

	APIC_Job* pc_job = PnlComGetJobCopy();
	if( NULL == pc_job ) {
		LOGF_debug_PutEventLog( LOGF_DEBUG_EVENT_KIND_ALL, 0, LOGD_DEBUG_LEVEL_UNKNOWN, "Assert Failed!" );
		return ss_SelectLevel;
	}
	TYPC_Common* pc_Common = pc_job->getJobSpec()->pc_Common;
	// 濃度を取得.
	const TYPE_ImageAdjust e_ImageAdjust = pc_Common->c_ImageAdjust.getDensity().getImageAdjust();
	// 濃度レベルの取得と表示.
	switch( e_ImageAdjust ) {
		case TYPE_ImageAdjustM09:
		case TYPE_ImageAdjustM08:
		case TYPE_ImageAdjustM07:	ss_SelectLevel = 0;	break;
		case TYPE_ImageAdjustM06:
		case TYPE_ImageAdjustM05:	ss_SelectLevel = 1;	break;
		case TYPE_ImageAdjustM04:
		case TYPE_ImageAdjustM03:	ss_SelectLevel = 2;	break;
		case TYPE_ImageAdjustM02:
		case TYPE_ImageAdjustM01:	ss_SelectLevel = 3;	break;
		case TYPE_ImageAdjustStd:	ss_SelectLevel = 4;	break;
		case TYPE_ImageAdjustP01:
		case TYPE_ImageAdjustP02:	ss_SelectLevel = 5;	break;
		case TYPE_ImageAdjustP03:
		case TYPE_ImageAdjustP04:	ss_SelectLevel = 6;	break;
		case TYPE_ImageAdjustP05:
		case TYPE_ImageAdjustP06:	ss_SelectLevel = 7;	break;
		case TYPE_ImageAdjustP07:
		case TYPE_ImageAdjustP08:
		case TYPE_ImageAdjustP09:	ss_SelectLevel = 8;	break;
		default: LOGF_debug_PutEventLog( LOGF_DEBUG_EVENT_KIND_ALL, 0, LOGD_DEBUG_LEVEL_UNKNOWN, "Assert Failed!" ); break;
	}
	return ss_SelectLevel;	// 濃度のレベルゲージポイント.
}
// 概要    : 印刷設定の可否をファイル拡張子で判断する関数.
// 戻り値  : True:印刷設定不可 / False:印刷設定可能.
// 問題点317447対応により処理を共通化.
Bool PNLC_ExtentionCheck::checkExtentionType( short( *p_GetMaxCount )(),char* ( *p_GetFileName )( short ) )
{
	Bool		bResult = False;								// 戻り値をあらわす.
	char		scExtension[6];									// 拡張子領域をあらわす.
	char*		scFileNameExtent[] = {".jpg", ".jpeg", ".xps"};	// 拡張子をあらわす.
	const short	ssFileNameExtentLength = sizeof( scFileNameExtent ) / sizeof( scFileNameExtent[0] );
	short		ssTextLenMax = 0;								// ファイル名の長さをあらわす.
	char		scFileName[PNLD_MaxStrUsbMemDeviceName];		// ファイル名をあらわす.
	memset( scExtension, '\0', sizeof( scExtension ) );				// 拡張子領域を初期化する.

	for( short ss_Index = 0; ( *p_GetMaxCount )() > ss_Index; ++ss_Index ) {
		char* psc_FileName = ( *p_GetFileName )( ss_Index );
		if( NULL == psc_FileName ) { LOGF_debug_PutEventLog( LOGF_DEBUG_EVENT_KIND_ALL, 0, LOGD_DEBUG_LEVEL_UNKNOWN, "Assert Failed!" ); return( bResult );} //【静的解析, CID:11814, 2011.03.03 ,細見】.
		ssTextLenMax = (short)( strlen( psc_FileName ) );
		memset( scFileName, '\0', sizeof( scFileName ) );

		short i = ssTextLenMax;
		for( i = ssTextLenMax; 0 < i; --i ) {

			if( '.' == psc_FileName[i] ) {
				setupInputString( 1, i, psc_FileName, scFileName, 0, getCharSetForPanel() );
				for( uint j = 0; sizeof( scExtension ) > j; ++j ) {
					scExtension[j] = psc_FileName[i];
					if( i != ssTextLenMax ) { ++i; }	// ファイル名の終端に達していない.
					else { break; }					// ファイル名の終端に達した.
				}
				break;
			}
		}
		for( i = 0; strlen( scExtension ) > ( uint )i; ++i ) { scExtension[i] = ( char )tolower( scExtension[i] ); }
		for( i = 0; ssFileNameExtentLength > i; ++i ) {
			if( 0 == strcmp( scExtension, scFileNameExtent[i] ) ) {
				bResult = True;
				break;
			} else {
				bResult = False;
			}
		}
		// 選択されているファイルが複数である かつ jpg/xps形式でない.
		if( False == bResult && 1 < ( *p_GetMaxCount )() ) { break; }
	}
	return ( bResult );
}

// 概要   : FAX警告詳細情報取得.
// 備考   : 戻り値：PDPS_FaxWarningDetail (FAX警告詳細情報)、引数：char sc_CommLine(主回線or副回線).
PDPS_FaxWarningDetail getFaxWarningDetail( char sc_CommLine ) {
	APIC_FaxDevice* pc_FaxDevice = APIC_FaxDevice::newInstance();
	PDPS_FaxWarningDetail s_FaxWarningDetail;	// FAX警告詳細情報.
	uchar uc_LineStatus = pc_FaxDevice->getLineStatus( sc_CommLine );
	if( ( uc_LineStatus != FAXE_LineStateError ) && ( uc_LineStatus != FAXE_LineStateHardwareErr ) && ( uc_LineStatus != FAXE_LineStateNoDevice ) ) {
		s_FaxWarningDetail.e_CommLine = sc_CommLine;
		pc_FaxDevice->getWarning( s_FaxWarningDetail.e_CommLine,		// ［IN］回線番号
		                          &s_FaxWarningDetail.ul_JobId,		//  [OUT] ジョブID
		                          s_FaxWarningDetail.sc_ErrorCode,	//  [OUT] エラーコード
		                          &s_FaxWarningDetail.e_Warning,		//  [OUT] Warning種別
		                          &s_FaxWarningDetail.e_RedialOver	//  [OUT] リダイアルの回数オーバーであるか
		                        );
	}
	return s_FaxWarningDetail;
}
// 概要   : G3FAXリダイアルアイコン表示判定.
// 備考   : 戻り値：Bool True(アイコン表示).
Bool isG3FaxRedialIconDisp() {
	Bool bl_Disp = False;			// 警告発生状態.
	PDPS_FaxWarningDetail s_FaxWarningDetailLine1 = getFaxWarningDetail( TYPE_CommLine1 );	// 各回線ごとのFAX警告詳細情報を取得.
	PDPS_FaxWarningDetail s_FaxWarningDetailLine2 = getFaxWarningDetail( TYPE_CommLine2 );	// 各回線ごとのFAX警告詳細情報を取得.
	if( ( FAXE_WarningDial == s_FaxWarningDetailLine1.e_Warning || FAXE_WarningXmt == s_FaxWarningDetailLine1.e_Warning )
	    && ( FAXE_WarningDial == s_FaxWarningDetailLine2.e_Warning || FAXE_WarningXmt == s_FaxWarningDetailLine2.e_Warning ) ) {	// 回線1、回線2共にチェック対象の警告が発生している場合.
		if( FAXE_RedialOverNon == s_FaxWarningDetailLine1.e_RedialOver
		    ||  FAXE_RedialOverNon == s_FaxWarningDetailLine2.e_RedialOver ) {	// 回線1or回線2に、リダイアル残り回数がある場合、アイコン表示 No.317878 2009/8/3 柳川.
			bl_Disp = True;
		}
	} else if( FAXE_WarningDial == s_FaxWarningDetailLine1.e_Warning || FAXE_WarningXmt == s_FaxWarningDetailLine1.e_Warning ) {		// 回線1 のみにチェック対象の警告が発生している場合.
		if( FAXE_RedialOverNon == s_FaxWarningDetailLine1.e_RedialOver ) {	// リダイアル残り回数がない場合、アイコン表示.
			bl_Disp = True;
		}
	} else if( FAXE_WarningDial == s_FaxWarningDetailLine2.e_Warning || FAXE_WarningXmt == s_FaxWarningDetailLine2.e_Warning ) {		// 回線2 のみにチェック対象の警告が発生している場合.
		if( FAXE_RedialOverNon == s_FaxWarningDetailLine2.e_RedialOver ) {	// リダイアル残り回数がない場合、アイコン表示.
			bl_Disp = True;
		}
	}
	return bl_Disp;
}


// 概要   : ADFが使用可能かを判定する.
// 戻り値 : Bool（True : 使用可能、False : 使用不可）.
Bool PnlComIsEnableUseAdf()
{
	Bool b_Result = True;
	if( ( TYPE_TemporaryRescueStatusReset != PnlComGetSystemStatus()->getTemporaryRescueUserStatus( TYPE_TemporaryRescueUnitADF ) )	// ADF暫定救済中.
	    || ( TYPE_ADFTypeNon == PnlComGetScannerSystem()->getADFType() ) ) {																// ADF非装着時.
		b_Result = False;
	}
	return b_Result;
}
// 概要   : ADFアイコンの表示状態を切替える.
// 戻り値 : 無し.
void PnlComSetupOriginalDirectionAdfIcon( PActivatableAdd* pc_Background, PSinglePartsGraphic* pc_AdfIcon )
{
	if( ( NULL == pc_Background ) || ( NULL == pc_AdfIcon ) ) {
		LOGF_debug_PutEventLog( LOGF_DEBUG_EVENT_KIND_ALL, 0, LOGD_DEBUG_LEVEL_UNKNOWN, "Assert Failed!" );
		return;
	}
	Bool b_ShowAdfIcon = PnlComIsEnableUseAdf();				// ADFが使用可能かを取得.
	pc_Background->showEnableAdd( pc_AdfIcon, b_ShowAdfIcon );	// ADFアイコンの表示状態を切替える.
}

// 概要   : 原稿セット方向の全てのADFアイコンに対して表示状態を切替える.
// 戻り値 : 無し.
void PnlComSetupOriginalDirectionAllAdfIcon( PSinglePartsGraphic** ppc_AllAdfIcon , uchar uc_Size )
{
	if( NULL == ppc_AllAdfIcon ) {
		LOGF_debug_PutEventLog( LOGF_DEBUG_EVENT_KIND_ALL, 0, LOGD_DEBUG_LEVEL_UNKNOWN, "Assert Failed!" );
		return;
	}
	Bool b_ShowAdfIcon = PnlComIsEnableUseAdf();		// ADFが使用可能かを取得.
	for( uchar i = 0; uc_Size > i; ++i ) {
		if( NULL == ppc_AllAdfIcon[i] ) {
			LOGF_debug_PutEventLog( LOGF_DEBUG_EVENT_KIND_ALL, 0, LOGD_DEBUG_LEVEL_UNKNOWN, "Assert Failed!" );
			return;
		}
		ppc_AllAdfIcon[i]->showEnable( b_ShowAdfIcon );	// ADFアイコンの表示状態を切替える.
	}
}

// 概要   : 「Language Selection」キーの表示/非表示設定情報取得.
// 戻り値 : Bool（True : 表示設定、False : 非表示設定）.
Bool isLanguageSelectionKeyDispSetting()
{
	// Donau機能拡張2以降、Amur機能拡張1以降の場合.
	if( True == PLBC_FuncVersionCheck::isOK_Type2() ) {
	} else { return True; }

	Bool b_Setting = True;
	APIC_SoftDipSw* pc_SoftDipSw = APIC_SoftDipSw::newInstance();	// DipSw（API）・インスタンス取得.

	if( True == pc_SoftDipSw->getSoftDipSwBit( 30, 3 ) ) {	// ソフトスイッチ49bit5がON(0x20)の時.
		b_Setting = False;
	}

	return b_Setting;
}

//概要　　：Email送信Fromアドレスにデフォルト設定すべきアドレスの判定.
//戻り値  ：TYPE_ScanFromSelect	Fromアドレス選択状態.
//引数	  ：APIC_Job* pc_Job	ジョブポインタ.
//		  ：char* sc_From		Fromアドレス格納先ポインタ.
TYPE_ScanFromSelect PnlComGetFromAdressSelection( APIC_Job* pc_Job, char* sc_From ) {

	TYPE_ScanFromSelect e_FaxScanFromSelect = TYPE_ScanFromSelectNon;							// Fromアドレス選択状態初期化.
// comment 2017/10/06 【HCL-RamKishor】【IT5_4.2】【RQ686】【WP779】 Supporting API Restrict Access to job setting function for NW2.
//	TYPE_FromChange		e_FromChange		= PnlComGetScanJobSetting()->getFromChange();		// Fromアドレス変更設定取得.
	TYPE_NetworkSpecific e_NetworkSpecific = PNLC_NetworkLan::getInstance()->getLine();
// comment 2022/05/11 FPT.DungDV14 [IT6_2.3] [RQ-815] Apply new API for IT6_2.3 or later models.
	PNLE_FromAddressChange e_FromChange     = PnlGetFromAddressChange( e_NetworkSpecific );
	if( NULL != sc_From ) {
		if( PNLE_FromChange_Specify == e_FromChange  ) {
				PnlComGetMailSendSetting()->getSmtpCertificationMailFromadrs( sc_From , e_NetworkSpecific );
				e_FaxScanFromSelect = c_JobControl.e_FaxScanFromSelect;
		} else if( ( True == PnlComGetUserAccountOn() )											// ユーザー認証中.
		    // PnlComGetUser()　NULLチェック対応.
		    && ( NULL != PnlComGetUser() )
		    &&	( 0 < strlen( PnlComGetUser()->getMailNotification().sc_UserMailAdrs ) )			// 認証ユーザーのアドレスが存在.
		    &&	( True == PLBC_FuncPKICheck::isPKI() ) ) {										// PKI認証.
// comment 2022/05/11 FPT.DungDV14 [IT6_2.3] [RQ-815] Apply new API for IT6_2.3 or later models.
			if( PNLE_FromChange_Able == e_FromChange ) {					// Fromアドレス変更設定 許可.
				if( True == isOn( CNK_DigitalSignature, pc_Job ) ||			// デジタル署名 ON.
				    ( True == isOn( CNK_EncryptionMail, pc_Job ) ) ) {		// メール暗号化 ON.
					// ユーザーアドレスを設定する。.
					strcpy( sc_From, PnlComGetUser()->getMailNotification().sc_UserMailAdrs );
					e_FaxScanFromSelect = TYPE_ScanFromSelectUser;
					// Fromアドレスがない場合は、ユーザアドレス(Default)を設定する。.
				} else if( 0 == strlen( sc_From ) ) {
					strcpy( sc_From, PnlComGetUser()->getMailNotification().sc_UserMailAdrs );
					e_FaxScanFromSelect = TYPE_ScanFromSelectUser;
					// デジタル署名 & メール暗号化 OFF.
				} else {
					e_FaxScanFromSelect = c_JobControl.e_FaxScanFromSelect;
				}
// comment 2022/05/11 FPT.DungDV14 [IT6_2.3] [RQ-815] Apply new API for IT6_2.3 or later models.
			} else if( PNLE_FromChange_Disable_AdminAdress == e_FromChange ) {   // 管理者アドレス優先.
				if( True == isOn( CNK_DigitalSignature, pc_Job ) ||
				    ( True == isOn( CNK_EncryptionMail, pc_Job ) ) ) {
					// ユーザーアドレスを設定する.
					strcpy( sc_From, PnlComGetUser()->getMailNotification().sc_UserMailAdrs );
					e_FaxScanFromSelect = TYPE_ScanFromSelectUser;
				} else {
					// 管理者アドレスを設定する.
					PnlComGetSystemSetting()->getAdminMailAddress( sc_From );
					e_FaxScanFromSelect = TYPE_ScanFromSelectAdmin;
				}
			} else { // ユーザーアドレス優先.
				// ユーザーアドレスを設定する。.
				strcpy( sc_From, PnlComGetUser()->getMailNotification().sc_UserMailAdrs );
				e_FaxScanFromSelect = TYPE_ScanFromSelectUser;
			}
		} else if( ( NULL != pc_Job )
		           &&	( NULL != PnlComGetUser() )
		           &&	( True == PnlComGetUserAccountOn() )												// ユーザー認証ON.
		           &&	( 0 < strlen( PnlComGetUser()->getMailNotification().sc_UserMailAdrs ) ) ) {			// ユーザーアドレス有り.
// comment 2022/05/11 FPT.DungDV14 [IT6_2.3] [RQ-815] Apply new API for IT6_2.3 or later models.
			if( PNLE_FromChange_Able == e_FromChange ) {
				if( True == isOn( CNK_DigitalSignature, pc_Job ) ||
				    ( True == isOn( CNK_EncryptionMail, pc_Job ) ) ) {
					// 管理者アドレスを設定する。.
					PnlComGetSystemSetting()->getAdminMailAddress( sc_From );
					e_FaxScanFromSelect = TYPE_ScanFromSelectAdmin;
				} else if( 0 == strlen( sc_From ) ) {
					strcpy( sc_From, PnlComGetUser()->getMailNotification().sc_UserMailAdrs );
					e_FaxScanFromSelect = TYPE_ScanFromSelectUser;
				} else {
					e_FaxScanFromSelect = c_JobControl.e_FaxScanFromSelect;
				}
// comment 2022/05/11 FPT.DungDV14 [IT6_2.3] [RQ-815] Apply new API for IT6_2.3 or later models.
			} else if( PNLE_FromChange_Disable_AdminAdress == e_FromChange ) {
				// 管理者アドレスを設定する。.
				PnlComGetSystemSetting()->getAdminMailAddress( sc_From );
				e_FaxScanFromSelect = TYPE_ScanFromSelectAdmin;
			} else {
				if( True == isOn( CNK_DigitalSignature, pc_Job ) ||
				    ( True == isOn( CNK_EncryptionMail, pc_Job ) ) ) {
					// 管理者アドレスを設定する。.
					PnlComGetSystemSetting()->getAdminMailAddress( sc_From );
					e_FaxScanFromSelect = TYPE_ScanFromSelectUser;
				} else {
					// ユーザーEmailアドレスを設定する。.
					strcpy( sc_From, PnlComGetUser()->getMailNotification().sc_UserMailAdrs );
					e_FaxScanFromSelect = TYPE_ScanFromSelectUser;
				}
			}
		}
		else if( ( NULL != pc_Job )
		         &&	( False == isOn( CNK_DigitalSignature, pc_Job ) )									// デジタル署名.
		         &&	( False == isOn( CNK_EncryptionMail, pc_Job ) )										// メール暗号化.
		         &&	( 0 != strlen( sc_From ) )															// Fromアドレスが入力されていれば.
// comment 2022/05/11 FPT.DungDV14 [IT6_2.3] [RQ-815] Apply new API for IT6_2.3 or later models.
		         && ( PNLE_FromChange_Able == e_FromChange ) ) {										// Amur/Donau機能拡張1：『許可』.
			// Fromアドレスは変更しない.
			e_FaxScanFromSelect = TYPE_ScanFromSelectAdmin;
		}
		else {
			// 未登録もしくは送信元変更禁止なので、管理者アドレスを取得する。.
			PnlComGetSystemSetting()->getAdminMailAddress( sc_From );
			e_FaxScanFromSelect = TYPE_ScanFromSelectAdmin;
		}
	}
	return e_FaxScanFromSelect;
}

// ==================================================================
// 概要		：表示可能な言語を判定し、CommonAPIへsetする.
// ==================================================================
void PnlComSetEnableLanguage()
{
	ST_LangValTbl* pst_table[9];				// 選択キー.

	int32_t i32_LangNum = getLangCount();
	ushort i;
	uchar j;
	TYPE_Language ec_SelectLang;
	if( i32_LangNum <= 0 ) {
		// 言語データを搭載していないときは、日英を選択可能とする(切換え可能かどうかは別にして).
#if defined(SIMULATOR)
		pst_table[0] = &st_LangValTbl[1];		// 英語.
		pst_table[1] = &st_LangValTbl[2];		// ドイツ語.
		pst_table[2] = &st_LangValTbl[3];		// フランス語.
		pst_table[3] = &st_LangValTbl[4];		// イタリア語.
		pst_table[4] = &st_LangValTbl[9];		// スペイン語.
		pst_table[5] = &st_LangValTbl[0];		// 日本語.
		i32_LangNum = 6;
#else	// defined(SIMULATOR)
		pst_table[0] = &st_LangValTbl[1];		// 英語.
		pst_table[1] = &st_LangValTbl[0];		// 日本語.
		i32_LangNum = 2;
#endif	// defined(SIMULATOR)
	} else if( False == isStandardMSGBinary() ) {
		// 言語データを搭載しているが、標準MSGバイナリではない場合(日英FIGS中韓台のバイナリではない場合).
		// MSGバイナリに搭載している言語、すべてを表示する.
		// ただし、画面表示上、MAXは DEF_LanguageSelectMax 分とする.
		i32_LangNum = DEF_LanguageSelectMax;
		for( i = 0; i < i32_LangNum; i++ ) {	// 搭載言語数分、pst_table[]にデータをセットする.
			pst_table[i] = NULL;
			ec_SelectLang = getLanguageType( i );
			for( j = 0; j < sizeof( st_LangValTbl ) / sizeof( st_LangValTbl[0] ); j++ ) {
				if( st_LangValTbl[j].e_Language == TYPE_LanguageSize ) {
					// データが見つからなかった.
					i32_LangNum = i;		// 搭載言語数ここまでにする.
					break;
				}
				if( st_LangValTbl[j].e_Language == ec_SelectLang ) {	// 一致するテーブルのポインタをセットする.
					pst_table[i] = &st_LangValTbl[j];
					break;
				}
			}
		}
	} else {
		// 言語データを搭載しているとき.
		if( i32_LangNum > PNL_MAX_LANGUAGES ) {
			i32_LangNum = PNL_MAX_LANGUAGES;				// 言語数は最大PNL_MAX_LANGUAGES(cf.ppcglanguage.h).
		}

		enum {
			SimukeJapan = 0,
			SimukeUS,
			SimukeEurope,
			SimukeBrazil,
			SimukeBAU,
			SimukeChina,
			SimukeTaiwan,
			SimukeBAUHungle
			,SimukeAllLang				//拡張メモリ有り・全言語利用可
		};
		struct SELECTLANG {
			uchar			uc_langCnt;		// 選択可能な言語数.
			TYPE_Language	e_lang[9];		// 選択可能な言語.
		};
		static const SELECTLANG selectLang[] = {
			{	6, { TYPE_LanguageJapanese,	TYPE_LanguageAmerican,	TYPE_LanguageFrench,
					TYPE_LanguageItalian,	TYPE_LanguageGerman,	TYPE_LanguageSpanish
				}
			},	// 日本仕向
			{	6, { TYPE_LanguageAmerican,	TYPE_LanguageFrench,	TYPE_LanguageSpanish,
					TYPE_LanguageJapanese,	TYPE_LanguageItalian,	TYPE_LanguageGerman
				}
			},	// US仕向.
			{ 6,	{ TYPE_LanguageAmerican, TYPE_LanguageFrench,  TYPE_LanguageItalian, TYPE_LanguageGerman,  TYPE_LanguageSpanish, TYPE_LanguageJapanese } },	// 欧州仕向.
			{ 4,	{ TYPE_LanguageAmerican, TYPE_LanguageFrench,  TYPE_LanguageSpanish, TYPE_LanguageJapanese } },	// サウジB/ブラジル仕向.
			{ 4,	{ TYPE_LanguageAmerican, TYPE_LanguageFrench,  TYPE_LanguageSpanish, TYPE_LanguageChinese1 } },	// BAU仕向(Traditional Chinese).
			{ 2,	{ TYPE_LanguageChinese2, TYPE_LanguageAmerican } },	// 中国仕向
			{ 2,	{ TYPE_LanguageChinese1, TYPE_LanguageAmerican } },	// 台湾仕向
			{ 4,	{ TYPE_LanguageAmerican, TYPE_LanguageFrench,  TYPE_LanguageSpanish, TYPE_LanguageHangul } },	// BAU仕向(ハングル).
			{	9, { TYPE_LanguageAmerican,	TYPE_LanguageFrench,	TYPE_LanguageItalian,
					TYPE_LanguageGerman,		TYPE_LanguageSpanish,	TYPE_LanguageJapanese,
					TYPE_LanguageChinese2,	TYPE_LanguageChinese1,	TYPE_LanguageHangul
				}
			},		// 全言語.
		};
		APIC_MachineSetting* pc_APIC_MachineSetting = APIC_MachineSetting::newInstance();
		uchar uc_selectLangIndex = 0;
		switch( pc_APIC_MachineSetting->getSystemType() ) {
			case TYPE_SystemType_JP: uc_selectLangIndex = SimukeJapan; break;	// 日本仕向.
			case TYPE_SystemType_US: uc_selectLangIndex = SimukeUS;	   break;	// US仕向.
			case TYPE_SystemType_EU:
				switch( pc_APIC_MachineSetting->getSubSystemType() ) {
					case TYPE_SubSystemType1: uc_selectLangIndex = SimukeEurope; break;	// 欧州仕向.
					case TYPE_SubSystemType2: uc_selectLangIndex = SimukeBrazil; break;	// サウジＢ/ブラジル仕向.
					case TYPE_SubSystemType3: uc_selectLangIndex = SimukeBAU;	 break;	// BAU仕向(Traditional Chinese).
					case TYPE_SubSystemType4: uc_selectLangIndex = SimukeChina;	 break;	// 中国仕向.
					case TYPE_SubSystemType5: uc_selectLangIndex = SimukeTaiwan; break;	// 台湾仕向.
					case TYPE_SubSystemType6: uc_selectLangIndex = SimukeBAUHungle; break;	// BAU仕向(ハングル).
				}
				break;
		}
		if( ( True == PnlComGetEnabler()->isExtendedMemory() ) 	//増設メモリ有り.
		    ||( True == PLBC_FuncVersionCheck::isOK_Type3() ) ) { // Gaia先取り以降.標準9言語ROM.
			uc_selectLangIndex = SimukeAllLang;					//９言語すべて
		}

		uchar	ucIndex = 0;
		for( i=0; i<selectLang[uc_selectLangIndex].uc_langCnt; i++ ) {
			ec_SelectLang = selectLang[uc_selectLangIndex].e_lang[i];
			Bool bIsLangFlg = False;
			for( j=0; j<( uchar )i32_LangNum; j++ ) {
				if( getLanguageType( j ) == ec_SelectLang ) {
					bIsLangFlg = True;
					break;
				}
			}
			if( bIsLangFlg == False ) { continue; }	// 言語バイナリ内に選択可能な言語が無ければ次.

			pst_table[ucIndex] = NULL;
			for( j = 0; j < sizeof( st_LangValTbl ) / sizeof( st_LangValTbl[0] ); j++ ) {
				if( st_LangValTbl[j].e_Language == TYPE_LanguageSize ) {
					SYSF_logMsg( "Panel::メッセージバイナリ中に言語%d見つからない\n", ( int )ec_SelectLang, 0, 0, 0, 0, 0 );
					// データが見つからなかった.
					break;
				}
				if( st_LangValTbl[j].e_Language == ec_SelectLang ) {	// 一致するテーブルのポインタをセットする.
					SYSF_logMsg( "Panel::メッセージバイナリ中に言語%d発見\n", ( int )ec_SelectLang, 0, 0, 0, 0, 0 );
					pst_table[ucIndex] = &st_LangValTbl[j];
					ucIndex++;
					break;
				}
			}
		}
		i32_LangNum = ucIndex;
	}
// comment 2018/12/14 Sky東島 [EagleHigh][RQ-258] タイ語とベトナム語の対応.
//	uint32_t ui32_EnableLanguage = 0;
	uint64_t ui64_EnableLanguage = 0;
	for( int sc_count = 0; sc_count < i32_LangNum; sc_count++ ) {
// comment 2018/12/14 Sky東島 [EagleHigh][RQ-258] タイ語とベトナム語の対応.
//		ui32_EnableLanguage |= pst_table[sc_count]->e_LanguageBIT;
		ui64_EnableLanguage |= pst_table[sc_count]->e_LanguageBIT;
	}
// comment 2018/12/14 Sky東島 [EagleHigh][RQ-258] タイ語とベトナム語の対応.
//	APIC_MachineSetting::newInstance()->setEnableLanguage( ui32_EnableLanguage );
	APIC_MachineSetting::newInstance()->setEnableLanguage( ui64_EnableLanguage );

#ifndef SIMULATOR
	// 仕向け情報をQt側へ通知.
	PnlComMtuiIf_MarketAreaNotify::instance()->setEnableChinese( PnlComIsChineseDestination() );
#endif	// SIMULATOR.

}
