/**
@name	PnlComBackupJobSpecDataNWScan.
@brief	ネットワークスキャン時のジョブスペックデータバックアップ処理.
*/
// ===============================================================================================
void PnlComBackupJobSpecDataNWScan() {
// comment 2017/08/03 【HCL-Pavani】【IT6_Eagle】【AR1026431】【KLOC ID: 166192】NPD.FUNC.MUST.
//	if( NULL != PnlComGetJobScanFax() ) {
	if(( NULL != PnlComGetJobScanFax() ) 
		&& ( NULL != PnlComGetJobScanFax()->getJobSpec() )){
		memcpy( &c_BackupNWScanCommon, PnlComGetJobScanFax()->getJobSpec()->pc_Common, sizeof( TYPC_Common ) );
		memcpy( &c_BackupNWScanScan,   PnlComGetJobScanFax()->getJobSpec()->pc_Scan,   sizeof( TYPC_Scan ) );
		memcpy( &c_BackupNWScanSend,   PnlComGetJobScanFax()->getJobSpec()->pc_Send,   sizeof( TYPC_Send ) );
		memcpy( &c_BackupNWScanFax,    PnlComGetJobScanFax()->getJobSpec()->pc_Fax,    sizeof( TYPC_Fax ) );
		memcpy( &c_BackupNWScanPrint,  PnlComGetJobScanFax()->getJobSpec()->pc_Print,  sizeof( TYPC_Print ) );
	}

	bl_BackupSendWithPrint = PnlComGetFaxCommonBackup( PNLE_FaxBackupKind_SendWithPrint );
}

// ===============================================================================================
/**
@name	PnlComRecoverJobSpecDataNWScan.
@brief	ネットワークスキャン終了時の退避ジョブスペックデータ復帰処理.
*/
// ===============================================================================================
void PnlComRecoverJobSpecDataNWScan() {
	short s_MemId = 0;
	// PSP選択中の場合.
	if( PCGD_NetworkScan_PSP == onlyPanel.getNetworkScanType() ) {
		// 最新のMemoryIdを取得する.
		s_MemId = PnlComGetJobScanFax( PCGE_JobPutOther )->getJobSpec()->pc_Send->c_ComSend.getMyAddressMemoryId();
	}
	memcpy( PnlComGetJobScanFax( PCGE_JobPutOther )->getJobSpec()->pc_Common, &c_BackupNWScanCommon, sizeof( TYPC_Common ) );
	memcpy( PnlComGetJobScanFax( PCGE_JobPutOther )->getJobSpec()->pc_Scan,   &c_BackupNWScanScan,   sizeof( TYPC_Scan ) );
	memcpy( PnlComGetJobScanFax( PCGE_JobPutOther )->getJobSpec()->pc_Send,   &c_BackupNWScanSend,   sizeof( TYPC_Send ) );
	memcpy( PnlComGetJobScanFax( PCGE_JobPutOther )->getJobSpec()->pc_Fax,    &c_BackupNWScanFax,    sizeof( TYPC_Fax ) );
	memcpy( PnlComGetJobScanFax( PCGE_JobPutOther )->getJobSpec()->pc_Print,  &c_BackupNWScanPrint,  sizeof( TYPC_Print ) );
	if( PCGD_NetworkScan_PSP == onlyPanel.getNetworkScanType() ) {
		// ジョブ終了後 c_ComSendのMemoryIdがずれないようにするため、最新のMemoryIdを継承する.
		PnlComGetJobScanFax( PCGE_JobPutOther )->getJobSpec()->pc_Send->c_ComSend.setMyAddressMemoryId( s_MemId );
	}
	if( NULL != PnlComGetJobSpecScanFaxBack() ) {
		PnlComGetJobSpecScanFaxBack()->b_MmbSendWithPrint = bl_BackupSendWithPrint;
	}
}

