// ===============================================================================================
/**
@name	keyBoardInputCharUnicodeToNativecode.
@brief	キーボード入力したUnicodeの文字をキーボード入力言語各国キャラへ変換(キーボード専用).
*/
// ===============================================================================================
static const struct ST_CharCodeSetISO8859WinCPTbl {
	LIBE_CharSet	e_ISO8859;
	LIBE_CharSet	e_WinCP;
} st_CharCodeSetISO8859WinCPTbl[] = {
	{	LIBE_CharSetISO8859_1,	LIBE_CharSetWindowsCP_1252	},
	{	LIBE_CharSetISO8859_2,	LIBE_CharSetWindowsCP_1250	},
	{	LIBE_CharSetISO8859_4,	LIBE_CharSetWindowsCP_1257	},
	{	LIBE_CharSetISO8859_5,	LIBE_CharSetWindowsCP_1251	},
	{	LIBE_CharSetISO8859_7,	LIBE_CharSetWindowsCP_1253	},
	{	LIBE_CharSetISO8859_9,	LIBE_CharSetWindowsCP_1254	},
};
static uchar sc_CharCodeSetISO8859WinCPTblMAXSIZE = ( uchar )( sizeof( st_CharCodeSetISO8859WinCPTbl ) / sizeof( st_CharCodeSetISO8859WinCPTbl[0] ) );

LIBE_CharSet PnlComkeyBoardInputCharUnicodeToNativecode( char* psc_InputCode )	{

	TYPE_Language eLang = PnlComGetLanguageForKeyboard();
	// キーボード言語設定が日中韓台の場合のキーボード入力時の文字はすでに各国キャラなので変換処理を行わない.
	switch( eLang ) {
		case TYPE_LanguageJapanese:	return LIBE_CharSetSJIS;	// 日本語.
		case TYPE_LanguageChinese1:	return LIBE_CharSetBIG5;	// 台湾語.
		case TYPE_LanguageChinese2:	return LIBE_CharSetGB18030;	// 中国語.
		case TYPE_LanguageHangul:	return LIBE_CharSetKSX1001;	// ハングル語.
		default: break;
	}
	// UCS2⇒各国キャラに変換.
	char sc_Dstcode[3] = {0,0,0};
	ushort us_Unicode = 0;
	Bool b_Hit = False;
	uchar i = 0;
	LIBE_CharSet e_LIBCharSet;
	if( False != PLBC_FuncVersionCheck::isOK_Type3() && PnlComIsMyPanel() == False && PCGE_OapMyPanel != PnlComGetMyPanelType() ) {
		e_LIBCharSet = getCharSetForKeyboadPLib( True );
	} else {											// キーボード画面以外の場合.
		e_LIBCharSet = getCharSetForKeyboadPLib( False );
	}
	uchar uc_Temp[TYPD_CharCode];
	memset( uc_Temp, 0, sizeof( uc_Temp ) );
	memcpy( uc_Temp, psc_InputCode , TYPD_CharCode );
	us_Unicode = ( ushort )uc_Temp[0];
	us_Unicode = (ushort)( us_Unicode << 8 );
	us_Unicode = (ushort)( us_Unicode + ( ushort )uc_Temp[1] );
	b_Hit = LIBF_CharcodeSearchFromUnicode( e_LIBCharSet, us_Unicode, sc_Dstcode, 3 );
	// ISO8859で変換できない場合はWindowsCPで検索.
	if( False == b_Hit )	{
		for( i = 0; sc_CharCodeSetISO8859WinCPTblMAXSIZE > i; i++ )	{
			if( e_LIBCharSet == st_CharCodeSetISO8859WinCPTbl[i].e_ISO8859 )	{
				e_LIBCharSet = st_CharCodeSetISO8859WinCPTbl[i].e_WinCP;
				b_Hit = LIBF_CharcodeSearchFromUnicode( e_LIBCharSet, us_Unicode, sc_Dstcode, 3 );
				break;
			}
		}
	}
	psc_InputCode[0] = sc_Dstcode[0];
	psc_InputCode[1] = sc_Dstcode[1];
	psc_InputCode[2] = sc_Dstcode[2];
	return ( True == b_Hit ? e_LIBCharSet : LIBE_CharSetISO8859_1 );
}

//================================================================================================
//クラス  ：TYPC_BroadcastAddress : 同報宛先管理クラス.
//概要    ：操作対象範囲の設定.
//================================================================================================
void TYPC_BroadcastAddress::setEffectiveRange( ushort us_EffectiveRange )
{
	us_MmbEffectiveRange = us_EffectiveRange;
	resetBroadcastAddress();
}
//================================================================================================
//クラス  ：TYPC_BroadcastAddress : 同報宛先管理クラス.
//概要    ：総ページ数の取得.
//================================================================================================
ushort TYPC_BroadcastAddress::getTotalPageCount()
{
	ushort us_TotalNodeCount = s_MmbBroadcastList.getNodeSize();
	ushort us_TotalPageCount = ( ushort )( us_TotalNodeCount / us_MmbEffectiveRange );
	if( ( 0 != ( us_TotalNodeCount % us_MmbEffectiveRange ) ) || ( 0 == us_TotalNodeCount ) ) {
		++us_TotalPageCount;
	}
	return us_TotalPageCount;
}
//================================================================================================
//クラス  ：TYPC_BroadcastAddress : 同報宛先管理クラス.
//概要    ：現在ページの取得.
//================================================================================================
ushort TYPC_BroadcastAddress::getNowPage()
{
	ushort us_NowPage = ( us_MmbEffectivePosition / us_MmbEffectiveRange );
	if( ( 0 != ( us_MmbEffectivePosition % us_MmbEffectiveRange ) ) || ( 0 == us_MmbEffectivePosition ) ) {
		++us_NowPage;
	}
	return us_NowPage;
}
//================================================================================================
//クラス  ：TYPC_BroadcastAddress : 同報宛先管理クラス.
//概要    ：前ページへ移動.
//================================================================================================
void TYPC_BroadcastAddress::setPageUp()
{
	if( 1 == us_MmbEffectivePosition ) {
		ushort us_TotalPage = getTotalPageCount();	// 総ページ数を取得.
		if( 1 < us_TotalPage ) {
			// 捜査対象となる宛先の開始インデックスを最終ページへ移動.
			us_MmbEffectivePosition = ( ushort )( ( us_MmbEffectiveRange * ( us_TotalPage - 1 ) ) + TYPD_BroadcastAddressEffectiveStart );
		}
	} else {
		if( us_MmbEffectivePosition > us_MmbEffectiveRange ) {
			// 捜査対象となる宛先の開始インデックスを前ページへ移動.
			us_MmbEffectivePosition = ( ushort )( us_MmbEffectivePosition - us_MmbEffectiveRange );
		}
	}
}
//================================================================================================
//クラス  ：TYPC_BroadcastAddress : 同報宛先管理クラス.
//概要    ：次ページへ移動.
//================================================================================================
void TYPC_BroadcastAddress::setPageDown()
{
	ushort us_TotalPage = getTotalPageCount();	// 総ページ数を取得.
	ushort us_NowPage = getNowPage();			// 現在ページを取得.
	if( us_TotalPage == us_NowPage ) {
		// 捜査対象となる宛先の開始インデックスを先頭ページへ移動.
		us_MmbEffectivePosition = TYPD_BroadcastAddressEffectiveStart;
	} else {
		ushort us_TotalNode = s_MmbBroadcastList.getNodeSize();
		if( us_TotalNode >= ( ushort )( us_MmbEffectivePosition + us_MmbEffectiveRange ) ) {
			// 捜査対象となる宛先の開始インデックスを次ページへ移動.
			us_MmbEffectivePosition = ( ushort )( us_MmbEffectivePosition + us_MmbEffectiveRange );
		}
	}
}
//================================================================================================
//クラス  ：TYPC_BroadcastAddress : 同報宛先管理クラス.
//概要    ：Indexを元にページ移動.
//================================================================================================
void TYPC_BroadcastAddress::setPageInfo( const ushort us_EffectiveIndex )
{
	ushort us_tmpPage = ( ushort )(( us_EffectiveIndex / us_MmbEffectiveRange ) * us_MmbEffectiveRange + TYPD_BroadcastAddressEffectiveStart);
	ushort us_TotalNode = s_MmbBroadcastList.getNodeSize();

	if( us_TotalNode >= us_tmpPage ) {
		// 捜査対象となる宛先の開始インデックスを次ページへ移動.
		us_MmbEffectivePosition = us_tmpPage;
	}
}
//================================================================================================
//クラス  ：TYPC_BroadcastAddress : 同報宛先管理クラス.
//概要    ：同報宛先の選択（複数選択可能）.
//================================================================================================
void TYPC_BroadcastAddress::selectAddress( const ushort us_EffectiveIndex )
{
	if( ( 0 == us_EffectiveIndex ) || ( us_MmbEffectiveRange < us_EffectiveIndex ) ) {
		// 引数が不正な場合.
		PnlComPutDebugLog( True, UC_PNL_LOGPATTERN_1, "TYPC_BroadcastAddress::selectBroadcastAddress", UC_PNL_ERROR_PARAMETER );
		return;
	}
	// 指定されたアドレスを算出.
	const ushort us_SelectAddress = ( ushort )( us_MmbEffectivePosition + ( us_EffectiveIndex - 1 ) );
	if( us_SelectAddress > s_MmbBroadcastList.getNodeSize() ) {
		PnlComPutDebugLog( True, UC_PNL_LOGPATTERN_1, "TYPC_BroadcastAddress::selectBroadcastAddress", UC_PNL_ERROR_IMPOSSIBLE );
		return;
	}
	TYPS_AddressInfo s_AddressInfo;
	memset( &s_AddressInfo, 0x00, sizeof( s_AddressInfo ) );
	s_MmbBroadcastList.getNode( s_AddressInfo, us_SelectAddress );
	s_AddressInfo.b_Select = ( Bool )( ( False == s_AddressInfo.b_Select ) ? True : False );
	s_MmbBroadcastList.updateNode( s_AddressInfo, us_SelectAddress );
	bl_MmbAddressCount = False;	// カウンター更新フラグ.
}
//================================================================================================
//クラス  ：TYPC_BroadcastAddress : 同報宛先管理クラス.
//概要    ：同報宛先選択件数の取得.
//================================================================================================
ushort TYPC_BroadcastAddress::getSelectAddressCount()
{
	ushort us_SelectAddress = 0;
	const ushort us_AddressCount = s_MmbBroadcastList.getNodeSize();
	for( ushort i = 1; us_AddressCount >= i; ++i ) {
		TYPS_AddressInfo s_AddressInfo;
		memset( &s_AddressInfo, 0x00, sizeof( s_AddressInfo ) );
		s_MmbBroadcastList.getNode( s_AddressInfo, i );
		if( True == s_AddressInfo.b_Select ) {
			++us_SelectAddress;
		}
	}
	return us_SelectAddress;
}
