{
	if( ps_AddressInfo != NULL ) {
		memcpy( &s_MmbLastSelectAddress, ps_AddressInfo, sizeof( s_MmbLastSelectAddress ) );
	}
}
//================================================================================================
//クラス  ：TYPC_BroadcastAddress : 同報宛先管理クラス.
//概要    最終選択同報宛先の取得.
//================================================================================================
void TYPC_BroadcastAddress::getLastSelectAddress( TYPS_AddressInfo* ps_AddressInfo )
{
	if( ps_AddressInfo != NULL ) {
		memcpy( ps_AddressInfo, &s_MmbLastSelectAddress, sizeof( s_MmbLastSelectAddress ) );
	}
}
//================================================================================================
//クラス  ：TYPC_BroadcastAddress : 同報宛先管理クラス.
//概要    最終選択同報宛先の削除.
//================================================================================================
void TYPC_BroadcastAddress::delLastSelectAddress( TYPS_AddressInfo* ps_AddressInfo )
{
	if( ps_AddressInfo != NULL ) {
		// 直接
		if( ps_AddressInfo->b_Direct ) {
			if( ps_AddressInfo->ss_AddressNo == s_MmbLastSelectAddress.ss_AddressNo &&
			    ps_AddressInfo->e_SendMode == s_MmbLastSelectAddress.e_SendMode ) {
				memset( &s_MmbLastSelectAddress, 0x00, sizeof( s_MmbLastSelectAddress ) );
			}
		} else {
			if( ps_AddressInfo->ul_LeftRecodeId == s_MmbLastSelectAddress.ul_LeftRecodeId ) {
				memset( &s_MmbLastSelectAddress, 0x00, sizeof( s_MmbLastSelectAddress ) );
			}
		}
	}
}
