void TYPC_BroadcastAddress::resetLastSelectAddress()
{
	memset( &s_MmbLastSelectAddress, 0x00, sizeof( s_MmbLastSelectAddress ) );
}

static TYPC_BroadcastAddress c_BroadcastAddressScanFaxBackup( TYPD_LeftSettingScanFaxListNum );
static TYPC_BroadcastAddress c_BroadcastAddressBoxBackup( TYPD_LeftSettingScanFaxListNum );
//================================================================================================
//グローバル関数
//概要    ：同報宛先情報のバックアップ.
//================================================================================================
void PnlComBackupBroadcastAddress( APIC_Job* pc_Job )
{
	TYPC_BroadcastAddress* pc_BroadcastAddressOriginal = PnlComGetBroadcastAddressForSend( pc_Job );
	if( NULL == pc_BroadcastAddressOriginal ) { LOGF_debug_PutEventLog( LOGF_DEBUG_EVENT_KIND_ALL, 0, LOGD_DEBUG_LEVEL_UNKNOWN, "Assert Failed!" ); return; }
	// スキャンファクスかボックスかを判定（同報宛先クラス取得処理と同じでジョブから判定する）.
	Bool b_ScanFaxMode = False;
	if( NULL != pc_Job ) 	{
//		if ( cp_scanfaxJob == cp_Job ) {
		if( cp_scanfaxJob == pc_Job || cp_faxJob == pc_Job ) {
			b_ScanFaxMode = True;
		} else if( cp_jbscanfaxJob != pc_Job ) {
			LOGF_debug_PutEventLog( LOGF_DEBUG_EVENT_KIND_ALL, 0, LOGD_DEBUG_LEVEL_UNKNOWN, "Assert Failed!" );
			return;
		}
	} else {
		b_ScanFaxMode = ( Bool )( ( PCGE_JobPutOther == sc_JobPutNo ) ? True : False );
	}
	// 同報宛先クラスのバックアップ.
	if( True == b_ScanFaxMode ) {
		memcpy( &c_BroadcastAddressScanFaxBackup, pc_BroadcastAddressOriginal, sizeof( TYPC_BroadcastAddress ) );
	} else {
		memcpy( &c_BroadcastAddressBoxBackup, pc_BroadcastAddressOriginal, sizeof( TYPC_BroadcastAddress ) );
	}
}
//================================================================================================
//グローバル関数
//概要    ：同報宛先情報のリカバリー.
//================================================================================================
void PnlComRecoveryBroadcastAddress( APIC_Job* pc_Job )
{
	TYPC_BroadcastAddress* pc_BroadcastAddressOriginal = PnlComGetBroadcastAddressForSend( pc_Job );
	if( NULL == pc_BroadcastAddressOriginal ) { LOGF_debug_PutEventLog( LOGF_DEBUG_EVENT_KIND_ALL, 0, LOGD_DEBUG_LEVEL_UNKNOWN, "Assert Failed!" ); return; }
	// スキャンファクスかボックスかを判定（同報宛先クラス取得処理と同じでジョブから判定する）.
	Bool b_ScanFaxMode = False;
	if( NULL != pc_Job ) 	{
//		if ( cp_scanfaxJob == pc_Job ) {
		if( cp_scanfaxJob == pc_Job || cp_faxJob == pc_Job ) {
			b_ScanFaxMode = True;
		} else if( cp_jbscanfaxJob != pc_Job ) {
			LOGF_debug_PutEventLog( LOGF_DEBUG_EVENT_KIND_ALL, 0, LOGD_DEBUG_LEVEL_UNKNOWN, "Assert Failed!" );
			return;
		}
	} else {
		b_ScanFaxMode = ( Bool )( ( PCGE_JobPutOther == sc_JobPutNo ) ? True : False );
	}
	// 同報宛先クラスのバックアップ.
	if( True == b_ScanFaxMode ) {
		memcpy( pc_BroadcastAddressOriginal, &c_BroadcastAddressScanFaxBackup, sizeof( TYPC_BroadcastAddress ) );
	} else {
		memcpy( pc_BroadcastAddressOriginal, &c_BroadcastAddressBoxBackup, sizeof( TYPC_BroadcastAddress ) );
	}
	PNLC_BroadcastPadControlLib::newInstance()->setQtListData();
}


//================================================================================================
//グローバル関数
//概要    ：サーチャブルPDFの文書名自動抽出確認画面を表示するか？
//================================================================================================
Bool PnlComIsEnableSearchablePDFAutoExtrFileNameConfirm( APIC_Job* pc_Job )
{
	if( NULL == pc_Job ) {
		LOGF_debug_PutEventLog( LOGF_DEBUG_EVENT_KIND_ALL, 0, LOGD_DEBUG_LEVEL_UNKNOWN, "Assert Failed!" );
		return False;
	}

	Bool bl_Result = False;
	TYPC_SearchablePdf c_SearchablePdf = pc_Job->getJobSpec()->pc_Send->getSearchablePdf();
	APIC_ScanJobSetting* pc_ScanJobSetting = PnlComGetScanJobSetting();

	if( NULL == pc_ScanJobSetting ) {
		LOGF_debug_PutEventLog( LOGF_DEBUG_EVENT_KIND_ALL, 0, LOGD_DEBUG_LEVEL_UNKNOWN, "Assert Failed!" );
		return False;
	}

	// サーチャブルPDFが有効で文書名確認画面設定が『確認する』の場合.
	if( True == pc_ScanJobSetting->getSearchablePDFCreateFileName() && True == pc_ScanJobSetting->getSearchablePDFAutoExtrFileNameConfirm() ) {
		// ファイルタイプが「PDF」もしくは「コンパクトPDF」の場合.
		if( TYPE_FileFormatPdf == pc_Job->getJobSpec()->pc_Send->c_ComSend.getFileFormat() ||
		    TYPE_FileFormatCompactPdf == pc_Job->getJobSpec()->pc_Send->c_ComSend.getFileFormat() ) {
			// ファイル名の自動抽出がONの場合.
			if( True == c_SearchablePdf.getOffOn() && True == c_SearchablePdf.getAutoExtractionValueSetting() ) {
				bl_Result = True;
			}
		}
	}
	return bl_Result;
}
// 中間認証サーバーのダウン状態の判定. True:ダウン False：正常.
Bool isDetectServerDown()
{
	Bool bl_result = False;		// 判定結果.
	// DipSW66 0x20がONかつ中間認証サーバーダウン状態(サーバーの1番目).
	if( True == APIC_SoftDipSw::newInstance()->getSoftDipSwBit( 32, 7 ) 										// DipSW ON
	    && ( TYPE_UserAuthenticationIntermeddiateServer == PnlComGetUserAuthentication()->getUserAuthentication(PNLC_NetworkLan::getInstance()->getLine())	// 中間認証.
	         || TYPE_UserAuthenticationDeviceAndMidAuth == PnlComGetUserAuthentication()->getUserAuthentication(PNLC_NetworkLan::getInstance()->getLine()) )	// 本体＋拡張サーバー認証.
	    &&  False == APIC_AuthenticationSeverSetting::newInstance()->getServerStatus( 1 , PNLC_NetworkLan::getInstance()->getLine()) ) {							// サーバーダウン.
		bl_result = True;
	}
	return bl_result;
}

