/**
* @brief LDAP宛先自動検索のキャンセル時のコールバック関数.
*/
//------------------------------------------------------------------------------.
static void CallBackLDAPAddressAutoSearchCancel( TYPE_LdapCancelError e_LdapCancelError, int32_t sl_NicFumResult )
{
}
//------------------------------------------------------------------------------.
/**
* @brief LDAP宛先自動検索の検索完了時のコールバック関数 CallBackSearchLdapComplete()流用.
*/
//------------------------------------------------------------------------------.
static Bool	b_LdapDisconnect = False;			// LDAP切断要求が必要かどうか.
static void CallBackLDAPAddressAutoSearchComplete( TYPE_LdapSearchError e_LdapSearchError, int32_t sl_NicFumResult )
{
	if( True == b_LdapDisconnect ) {
		// LDAP切断要求がある場合は、検索処理が終了した時点で実行する.
		APIC_LdapSearch* pc_LdapSearch = APIC_LdapSearch::newInstance();
		pc_LdapSearch->req_disconnect( );
		b_LdapDisconnect = False;
	} else {
		// エラー種別の保持
		e_LdapSearchErrorStatus = e_LdapSearchError;
		if( TYPE_LdapSearchErrorOk != e_LdapSearchError ) { onlyPanel.setNetworkTroubleCode( sl_NicFumResult ); }
		switch( e_LdapSearchError ) {
			case TYPE_LdapSearchErrorOk:						// 接続成功
			case TYPE_LdapSearchErrorNoMemory:					// メモリ確保エラー
			case TYPE_LdapSearchErrorTimeout:					// 接続タイムアウト
			case TYPE_LdapSearchErrorDNSResolutionError:		// サーバー名解決エラー（ＤＮＳエラー）
			case TYPE_LdapSearchErrorNotSupported:				// ＬＤＡＰバージョン相違
			case TYPE_LdapSearchErrorSearchError:				// 接続エラー
			case TYPE_LdapSearchErrorStrongAuthNotSupported:	// サーバーがＳＡＳＬをサポートしていない
			case TYPE_LdapSearchErrorAuthUnknown:				// サーバーのＳＡＳＬをサポートしていない
			case TYPE_LdapSearchErrorInvalidCredentials:		// ログインエラー
			case TYPE_LdapSearchErrorOther:						// その他(特定できない)エラー
			case TYPE_LdapSearchErrorUserCanceled:				// ユーザーによってキャンセルされました。
			case TYPE_LdapSearchErrorNosuchObject:				// オブジェクトが見つかりません
			case TYPE_LdapSearchErrorSizeLimitExceeded:			// 検索結果が最大値を超えました
			case TYPE_LdapSearchErrorReferral:					// サーバーがReferral機能を設定しています
			case TYPE_LdapSearchErrorOperationsError:			// 操作エラー
				CallBackIndi( TYPE_PNL_CallBack_serchComplate );	break;	// コールバックイベント発生要求
			default: LOGF_debug_PutEventLog( LOGF_DEBUG_EVENT_KIND_ALL, 0, LOGD_DEBUG_LEVEL_UNKNOWN, "Assert Failed!" ); break;
		}
	}
}
