/**
* @brief LDAP宛先自動検索共通クラス : インスタンス取得.
*/
//------------------------------------------------------------------------------.
PNLC_LDAPAddressAutoSearch* PNLC_LDAPAddressAutoSearch::newInstance()
{
	// インスタンス取得.
	static PNLC_LDAPAddressAutoSearch c_LDAPAddressAutoSearch;
	return  &c_LDAPAddressAutoSearch;
}

//------------------------------------------------------------------------------.
/**
* @brief LDAP宛先自動検索共通クラス : 宛先自動検索開始時の処理(startGamen()でコールする処理).
*/
//------------------------------------------------------------------------------.
void PNLC_LDAPAddressAutoSearch::startProcess( char* sc_InputString )
{
	// LDAP検索文字列は宛先検索と共用しているので自動検索時には退避する.
	TYPS_LdapSearchCondition* ps_LdapSearchCondition;
	memset( sc_SearchStringBackup, 0, sizeof( sc_SearchStringBackup ) / sizeof( sc_SearchStringBackup[0] ) );
	ps_LdapSearchCondition = PNLC_LdapSearchManager::newInstance()->getLdapSearchCondition();
	strncpy( sc_SearchStringBackup, ps_LdapSearchCondition->sc_SearchNameUTF8, sizeof( sc_SearchStringBackup ) -1 );
	ul_SearchStringBackupLen = strlen( sc_SearchStringBackup );
	//検索条件の初期化.
	initLdapSearchCondition();

	b_LdapDisconnect = False;
	b_LDAPAddressAutoSearchFlg = True;								// LDAP自動検索開始フラグ.

	// 検索文字列設定.
	memset( sc_SearchString, 0, sizeof( sc_SearchString ) );
	memset( sc_SearchResultString, 0, sizeof( sc_SearchResultString ) );
	strncpy( sc_SearchString, sc_InputString, TYPE_LDAPAddressAutoSearchStringMax );

	e_ConnectStatus = TYPE_LDAPAddressAutoSearchConnectNon;			// 未接続に設定.
	e_SearchStatus = TYPE_LDAPAddressAutoSearchNon;						// 未検索に設定.

	startLdapConnect();													// 認証処理.
}

//------------------------------------------------------------------------------.
/**
* @brief LDAP宛先自動検索共通クラス : 宛先自動検索終了時の処理(endGamen()でコールする処理).
*/
//------------------------------------------------------------------------------.
void PNLC_LDAPAddressAutoSearch::endProcess()
{
	if( TYPE_LDAPAddressAutoSearchNon == e_SearchStatus ) {
		if( TYPE_LDAPAddressAutoSearchConnectExecu == e_ConnectStatus ) {
			// 接続・認証中の場合、キャンセル実行.
			cancelLdapSearch();
		}
		// 検索していなければ、切断要求を行う.
		APIC_LdapSearch* pc_LdapSearch = APIC_LdapSearch::newInstance();
		pc_LdapSearch->req_disconnect( CallBackLDAPDisConnect );	// LDAPサーバー切断.
	} else {
		// 検索中の場合は、検索完了のコールバック処理で切断要求を行う.
		b_LdapDisconnect = True;
		if( TYPE_LDAPAddressAutoSearchExecu == e_SearchStatus ) {
			// キャンセルが実行されていない場合は、キャンセル実行.
			cancelLdapSearch();
		}
	}
	b_LDAPAddressAutoSearchFlg = False;								// LDAP自動検索開始フラグ.

	e_ConnectStatus = TYPE_LDAPAddressAutoSearchConnectNon;			// 未接続に設定.
	e_SearchStatus = TYPE_LDAPAddressAutoSearchNon;						// 未検索に設定.
	uc_ServerIndex = 0;
	// 退避していたLDAP検索文字列を復帰させる.
	changeBackupSerchString( sc_SearchStringBackup, ul_SearchStringBackupLen );
}

//------------------------------------------------------------------------------.
/**
* @brief LDAP宛先自動検索共通クラス : 宛先自動検索セットアップ時の処理(setupGamen()でコールする処理).
*/
//------------------------------------------------------------------------------.
void PNLC_LDAPAddressAutoSearch::setupProcess( char* sc_InputString, ushort us_Position )
{
	// 未接続や接続エラーが発生した場合は、検索処理は行わない。
	if( TYPE_LDAPAddressAutoSearchConnectNon == e_ConnectStatus || TYPE_LDAPAddressAutoSearchConnectError == e_ConnectStatus ) {
		return;
	}

	// 入力文字列が0の時は検索しない.
	if( sc_InputString[0] == NULL ) {
		//検索中の時は、キャンセル処理を行う.
		if( TYPE_LDAPAddressAutoSearchExecu == e_SearchStatus ) {
			cancelLdapSearch();
			e_SearchStatus = TYPE_LDAPAddressAutoSearchCancel;
		}

		// 検索予約中の時は、キャンセル中に変更する.
		if( TYPE_LDAPAddressAutoSearchReserve == e_SearchStatus ) {
			e_SearchStatus = TYPE_LDAPAddressAutoSearchCancel;
		}
		memset( sc_SearchString, 0, sizeof( sc_SearchString ) );
		memset( sc_SearchResultString, 0, sizeof( sc_SearchResultString ) );
		return;
	}

	// 検索が必要かチェック.
	Bool b_Search = checkLdapSearch( sc_InputString, us_Position );

	// 検索が必要がない場合は、ここで終了.
	if( False == b_Search ) {
		return;
	}

	// 検索文字を設定.
	setLdapSearchCondition();

	// 接続中の場合は、検索予約中にして終了.
	if( TYPE_LDAPAddressAutoSearchConnectExecu == e_ConnectStatus ) {
		e_SearchStatus = TYPE_LDAPAddressAutoSearchReserve;
		return;
	}

	// 現在検索キャンセル中・検索予約中の時は、検索予約中にして終了.
	if( ( TYPE_LDAPAddressAutoSearchCancel == e_SearchStatus ) || ( TYPE_LDAPAddressAutoSearchReserve == e_SearchStatus ) ) {
		e_SearchStatus = TYPE_LDAPAddressAutoSearchReserve;
		return;
	}

	// 現在検索中の時は、キャンセル処理のみ行い、キャンセル終了が完了した時点で検索する.
	if( TYPE_LDAPAddressAutoSearchExecu == e_SearchStatus ) {
		cancelLdapSearch();
		e_SearchStatus = TYPE_LDAPAddressAutoSearchReserve;
		return;
	}

	// 検索開始.
	startLdapSearch();
}

//----------------------------------------------------------------------	--------.
/**
* @brief LDAP宛先自動検索共通クラス : 宛先自動検索コールバック時の処理(procCallBack()でコールする処理).
*/
//------------------------------------------------------------------------------.
TYPE_TYPE_LDAPAddressAutoSearchError PNLC_LDAPAddressAutoSearch::CallBackProcess( TYPE_PNL_CallBack option )
{
	TYPE_TYPE_LDAPAddressAutoSearchError e_Error = TYPE_LDAPAddressAutoSearchErrorNon;
	switch( option ) {
		case TYPE_PNL_CallBack_LDAPConnectReqOK:							// 接続OK.
			e_ConnectStatus = TYPE_LDAPAddressAutoSearchConnectComplite;	// 接続完了にする.
			if( TYPE_LDAPAddressAutoSearchReserve == e_SearchStatus ) {		// 検索予約されている時には、検索要求.
				startLdapSearch();
			}
			break;
		case TYPE_PNL_CallBack_LDAPConnectReqNG:							// 接続NG.
			if( True == b_LdapUserAuthenticationInput ) {
				// ログイン名／パスワードの設定値を使用している時は、エラー.
				e_ConnectStatus = TYPE_LDAPAddressAutoSearchConnectError;
				e_SearchStatus = TYPE_LDAPAddressAutoSearchNon;
				switch( e_LdapConnectError ) {
					case	TYPE_LdapConnectErrorNoMemory:					// メモリ確保エラー.
					case	TYPE_LdapConnectErrorTimeout:					// 接続タイムアウト.
					case	TYPE_LdapConnectErrorDNSResolutionError:		// サーバー名解決エラー（ＤＮＳエラー）.
					case	TYPE_LdapConnectErrorNotSupported:				// ＬＤＡＰバージョン相違.
					case	TYPE_LdapConnectErrorConnectError:				// 接続エラー.
					case	TYPE_LdapConnectErrorStrongAuthNotSupported:	// サーバーがＳＡＳＬをサポートしていない.
					case	TYPE_LdapConnectErrorAuthUnknown:				// サーバーのＳＡＳＬをサポートしていない.
					case	TYPE_LdapConnectErrorOther:						// その他(特定できない)エラー.
					case	TYPE_LdapConnectErrorBusy:						// ビジー状態.
// comment 2016/11/11 Sky東島 [特ROM][AU DoD].
//						e_Error = TYPE_LDAPAddressAutoSearchErrorConnect;
						if( ( TYPE_LdapConnectErrorOk != e_LdapConnectError )
						 && ( MIO_LDAP_PKINIT_TICKET_EXPIRED == onlyPanel.getNetworkTroubleCode()
						   || MIO_LDAP_PKINIT_CARD_ERROR == onlyPanel.getNetworkTroubleCode() ) ){
							PCGC_PkiCardManager_PKI::getInstance()->setPincodeInputKind( DEF_INPUTPINCODE_LDAPEMail );
							e_Error = TYPE_LDAPAddressAutoSearchErrorPKITICKET;
						} else {
							e_Error = TYPE_LDAPAddressAutoSearchErrorConnect;
						}
						break;
					default:
						e_Error = TYPE_LDAPAddressAutoSearchError;
						break;
				}
				memset( sc_SearchResultString, 0, sizeof( sc_SearchResultString ) );
// comment 2016/11/22 Sky東島 [特ROM][AU DoD].
			} else if( True == isContactlessPKICard()
					   && False == onlyPanel.getMfpLoginOnPKIMode() ){
					// DODモードかつカードログイン時
				if( ( TYPE_LdapConnectErrorOk != e_LdapConnectError )
				 && ( MIO_LDAP_PKINIT_TICKET_EXPIRED == onlyPanel.getNetworkTroubleCode()
				   || MIO_LDAP_PKINIT_CARD_ERROR == onlyPanel.getNetworkTroubleCode() ) ){
					PCGC_PkiCardManager_PKI::getInstance()->setPincodeInputKind( DEF_INPUTPINCODE_LDAPEMail );
					// ログイン名／パスワードの設定値を使用している時は、エラー.
					e_ConnectStatus = TYPE_LDAPAddressAutoSearchConnectError;
					e_SearchStatus = TYPE_LDAPAddressAutoSearchNon;
					e_Error = TYPE_LDAPAddressAutoSearchErrorPKITICKET;
				} else {
					e_Error = TYPE_LDAPAddressAutoSearchErrorConnect;
					e_ConnectStatus = TYPE_LDAPAddressAutoSearchConnectError;
					e_SearchStatus = TYPE_LDAPAddressAutoSearchNon;
				}
			} else {
				// ユーザー認証の情報を使用している時は、ログイン名／パスワードの設定値を使用して再接続.
				restartLdapConnect();
			}
			break;
		case TYPE_PNL_CallBack_serchComplate:								// 検索終了.
			if( TYPE_LdapSearchErrorSearchError == e_LdapSearchErrorStatus || TYPE_LdapSearchErrorTimeout == e_LdapSearchErrorStatus ) {		// 接続エラー.
				// 接続成功 or ユーザーによってキャンセルされました or 検索結果が最大値を超えました 以外はエラー.
				e_ConnectStatus = TYPE_LDAPAddressAutoSearchConnectError;
				e_SearchStatus = TYPE_LDAPAddressAutoSearchNon;
				e_Error = TYPE_LDAPAddressAutoSearchErrorConnect;
				memset( sc_SearchResultString, 0, sizeof( sc_SearchResultString ) );
			} else {
				// 検索成功 or 検索結果が最大値を超えましたの時.
				if( TYPE_LdapSearchErrorOk == e_LdapSearchErrorStatus || TYPE_LdapSearchErrorSizeLimitExceeded == e_LdapSearchErrorStatus ) {
					// 検索結果取得.
					getLdapSearchResult();
				}
				else if( TYPE_LdapSearchErrorUserCanceled != e_LdapSearchErrorStatus ) {		// ユーザーキャンセル以外のエラーの時.
					// エラー表示はしないが、検索結果は空にしておく.
					memset( sc_SearchResultString, 0, sizeof( sc_SearchResultString ) );
				}
				// 検索予約されている時には、検索要求.
				if( TYPE_LDAPAddressAutoSearchReserve == e_SearchStatus ) {
					startLdapSearch();
				} else {
					e_SearchStatus = TYPE_LDAPAddressAutoSearchNon;
				}
			}
			break;
		default:		break;
	}
	return e_Error;
}

//------------------------------------------------------------------------------.
/**
* @brief LDAP宛先自動検索共通クラス : 検索文字列・検索結果文字列のクリア.
*/
//------------------------------------------------------------------------------.
void PNLC_LDAPAddressAutoSearch::clearSearchString()
{
	memset( sc_SearchString, 0, sizeof( sc_SearchString ) );
	memset( sc_SearchResultString, 0, sizeof( sc_SearchResultString ) );
}

//------------------------------------------------------------------------------.
/**
* @brief LDAP宛先自動検索共通クラス : 宛先自動検索が使用可能かどうか確認する.
*/
//------------------------------------------------------------------------------.
Bool PNLC_LDAPAddressAutoSearch::CheckLDAPAddressAutoSearchEnable( uchar uc_Index )
{
	if( 0 == uc_Index ) {
		uc_Index = ( uchar )PnlComGetLdapSetting()->getDefaultLdapServer();
	}

	APIC_LdapSetting* pc_LdapSetting = PnlComGetLdapSetting( uc_Index );
	if( NULL == pc_LdapSetting ) {
		return False;
	}

	// 管理者設定のLDAPの使用設定で「使用する」が選択されている、かつ、
	// デフォルトの予測入力設定で「使用する」が選択している、かつ、
	// デフォルトのLDAPが有効なサーバーである場合
	if( ( True == PnlComGetLdapSetting()->getOn() ) &&
	    ( True == pc_LdapSetting->getValiableAutoLdapSearchSetting() ) &&
	    ( True == isEnableLDAP( uc_Index ) ) ) {
		return True;
	} else {
		return False;
	}
}

//------------------------------------------------------------------------------.
/**
* @brief LDAP宛先自動検索共通クラス : 検索条件の初期設定.
*/
//------------------------------------------------------------------------------.
void PNLC_LDAPAddressAutoSearch::initLdapSearchCondition()
{
	TYPS_LdapSearchCondition* ps_LdapSearchCondition = PNLC_LdapSearchManager::newInstance()->getLdapSearchCondition();

	memset( ps_LdapSearchCondition, 0, sizeof( TYPS_LdapSearchCondition ) );

	//検索属性は、「名称」「メールアドレス」「名」「姓」の種別に設定する.
	TYPD_LdapSearchType us_SearchType;
	if( True == onlyPanel.isSearchDigitalID() ) {
		// 証明書付き宛先を選択中の時.
		us_SearchType = TYPD_LdapSearchTypeName | TYPD_LdapSearchTypeMailAddress | TYPD_LdapSearchTypeFirstName | TYPD_LdapSearchTypeLastName | TYPD_LdapSearchTypeSmime;
	} else {
		// 証明書付き宛先を選択中でない時.
		us_SearchType = TYPD_LdapSearchTypeName | TYPD_LdapSearchTypeMailAddress | TYPD_LdapSearchTypeFirstName | TYPD_LdapSearchTypeLastName;
	}
	ps_LdapSearchCondition->us_SearchType = us_SearchType;

	// 検索条件の設定（「名称」「メールアドレス」「名」「姓」に対して「前方一致」を設定）.
	ps_LdapSearchCondition->e_SearchNameCondition = TYPE_LdapSearchConditionFirst;
	ps_LdapSearchCondition->e_SearchMailAddressCondition = TYPE_LdapSearchConditionFirst;
	ps_LdapSearchCondition->e_SearchFirstNameCondition = TYPE_LdapSearchConditionFirst;
	ps_LdapSearchCondition->e_SearchLastNameCondition = TYPE_LdapSearchConditionFirst;

	ps_LdapSearchCondition->e_LdapSearchOption = TYPE_LdapSearchOptionOr;	// 複合検索条件の設定.
}

//------------------------------------------------------------------------------.
/**
* @brief LDAP宛先自動検索共通クラス : 検索条件を設定する.
*/
//------------------------------------------------------------------------------.
void PNLC_LDAPAddressAutoSearch::setLdapSearchCondition()
{
	TYPS_LdapSearchCondition* ps_LdapSearchCondition = PNLC_LdapSearchManager::newInstance()->getLdapSearchCondition();

	// 検索文字列の設定「名称」「メールアドレス」「名」「姓」.
	memset( ps_LdapSearchCondition->sc_SearchNameUTF8,      '\0', sizeof( ps_LdapSearchCondition->sc_SearchNameUTF8 ) );
	strncpy( ps_LdapSearchCondition->sc_SearchNameUTF8,      sc_SearchString, us_SearchLen );
	memset( ps_LdapSearchCondition->sc_SearchMailAddress, '\0', sizeof( ps_LdapSearchCondition->sc_SearchMailAddress ) );
	strncpy( ps_LdapSearchCondition->sc_SearchMailAddress, sc_SearchString, us_SearchLen );
	memset( ps_LdapSearchCondition->sc_SearchFirstNameUTF8, '\0', sizeof( ps_LdapSearchCondition->sc_SearchFirstNameUTF8 ) );
	strncpy( ps_LdapSearchCondition->sc_SearchFirstNameUTF8, sc_SearchString, us_SearchLen );
	memset( ps_LdapSearchCondition->sc_SearchLastNameUTF8,  '\0', sizeof( ps_LdapSearchCondition->sc_SearchLastNameUTF8 ) );
	strncpy( ps_LdapSearchCondition->sc_SearchLastNameUTF8,  sc_SearchString, us_SearchLen );

	PNLC_LdapSearchManager::newInstance()->setupStringToUTF8API( ps_LdapSearchCondition );		// UTF8へ変換.
}

//------------------------------------------------------------------------------.
/**
* @brief LDAP宛先自動検索共通クラス : 検索条件を画面開始時の状態に戻す為のAPI.
*/
//------------------------------------------------------------------------------.
void PNLC_LDAPAddressAutoSearch::changeBackupSerchString( char* p_scSerchString, size_t ul_SerchStringLen )
{
	ul_SerchStringLen++;					// strncpyで文字列終端をコピーするため文字列長に＋１する.
	TYPS_LdapSearchCondition* ps_LdapSearchCondition = PNLC_LdapSearchManager::newInstance()->getLdapSearchCondition();
	strncpy( sc_SearchString, p_scSerchString , sizeof( sc_SearchString ) -1 );
	memset( ps_LdapSearchCondition->sc_SearchNameUTF8,      '\0', sizeof( ps_LdapSearchCondition->sc_SearchNameUTF8 ) );
	strncpy( ps_LdapSearchCondition->sc_SearchNameUTF8,      sc_SearchString, ul_SerchStringLen );
	memset( ps_LdapSearchCondition->sc_SearchMailAddress, '\0', sizeof( ps_LdapSearchCondition->sc_SearchMailAddress ) );
	strncpy( ps_LdapSearchCondition->sc_SearchMailAddress, sc_SearchString, ul_SerchStringLen );
	memset( ps_LdapSearchCondition->sc_SearchFirstNameUTF8, '\0', sizeof( ps_LdapSearchCondition->sc_SearchFirstNameUTF8 ) );
	strncpy( ps_LdapSearchCondition->sc_SearchFirstNameUTF8, sc_SearchString, ul_SerchStringLen );
	memset( ps_LdapSearchCondition->sc_SearchLastNameUTF8,  '\0', sizeof( ps_LdapSearchCondition->sc_SearchLastNameUTF8 ) );
	strncpy( ps_LdapSearchCondition->sc_SearchLastNameUTF8,  sc_SearchString, ul_SerchStringLen );
}


//------------------------------------------------------------------------------.
/**
* @brief LDAP宛先自動検索共通クラス : 検索要求.
*/
//------------------------------------------------------------------------------.
void PNLC_LDAPAddressAutoSearch::startLdapSearch()
{
	if( NULL == PnlComGetJobScanFax() ) { LOGF_debug_PutEventLog( LOGF_DEBUG_EVENT_KIND_ALL, 0, LOGD_DEBUG_LEVEL_UNKNOWN, "Assert Failed!" ); return; }

	s_LdapSearchCondition = *PNLC_LdapSearchManager::newInstance()->getLdapSearchCondition();

	// Email宛先が使用できるか確認.
	TYPC_ComSend* pc_ComSend = &( PnlComGetJobScanFax()->getJobSpec()->pc_Send->c_ComSend );
	if( True == isEnableSetAddress( pc_ComSend, TYPE_SendModeEmail, False, False, False, True, -1, NULL, True ) ) {
		// E-mail宛先使用可能時はScanモード検索を追加する(Email未登録宛先は表示しない)
		s_LdapSearchCondition.us_SearchType |= TYPD_LdapSearchTypeScan;
	}

	if( True == onlyPanel.isSearchDigitalID() || True == onlyPanel.isEquivalentAddressOn()
	    || True == PnlComGetJobScanFax()->getJobSpec()->pc_Send->c_MailSend.getSmimeEnableCrypt() ) {
		// メール暗号化がONの場合または証明書付宛先検索の場合、フラグを立てる.
		s_LdapSearchCondition.us_SearchType |= TYPD_LdapSearchTypeSmime;
	}

	e_SearchStatus = TYPE_LDAPAddressAutoSearchExecu; 						// 検索中に設定.

	// 検索開始.
	APIC_LdapSearch* pc_LdapSearch = APIC_LdapSearch::newInstance();
	TYPC_LdapSetting c_LdapSetting = PNLC_LdapSearchManager::newInstance()->getLdapSettingInfo();
// comment 2016/09/27 Sky大濵  [特ROM][AU DoD] 認証状況通知.
//	pc_LdapSearch->req_searchstart( &c_LdapSetting, &s_LdapSearchCondition, CallBackLDAPAddressAutoSearchComplete, uc_ServerIndex );
	if( ( False == PLBC_FuncPKICheck::isPKI() ) || ( True == onlyPanel.getMfpLoginOnPKIMode() ) ) {		// PKIモード無効 または ID/パスワード認証.
// comment 2017/11/23 【HCL-Suganya】【IT5_4.2】【RQ686】 Multiple Network Support.
//		pc_LdapSearch->req_searchstart( &c_LdapSetting, &s_LdapSearchCondition, CallBackLDAPAddressAutoSearchComplete, uc_ServerIndex, TYPE_PKILoginModePassword );
		pc_LdapSearch->req_searchstart( &c_LdapSetting, &s_LdapSearchCondition, CallBackLDAPAddressAutoSearchComplete, uc_ServerIndex, TYPE_PKILoginModePassword , PNLC_NetworkLan::getInstance()->getLine() );
	} else {																							// カード認証.
// comment 2017/11/23 【HCL-Suganya】【IT5_4.2】【RQ686】 Multiple Network Support.
//		pc_LdapSearch->req_searchstart( &c_LdapSetting, &s_LdapSearchCondition, CallBackLDAPAddressAutoSearchComplete, uc_ServerIndex );
		pc_LdapSearch->req_searchstart( &c_LdapSetting, &s_LdapSearchCondition, CallBackLDAPAddressAutoSearchComplete, uc_ServerIndex , TYPE_PKILoginModeCard , PNLC_NetworkLan::getInstance()->getLine() );
	}
}

//------------------------------------------------------------------------------.
/**
* @brief LDAP宛先自動検索共通クラス : 検索が必要か確認.
*/
//------------------------------------------------------------------------------.
Bool PNLC_LDAPAddressAutoSearch::checkLdapSearch( char* sc_InputString, ushort us_Position )
{
	ushort us_InputStringLen = (ushort)strlen( sc_InputString );
	ushort us_SearchStringLen = (ushort)strlen( sc_SearchString );

	// 入力文字数が検索最大文字数より大きい場合は、検索最大文字数に丸める.
	if( TYPE_LDAPAddressAutoSearchStringMax < us_InputStringLen ) {
		us_InputStringLen = TYPE_LDAPAddressAutoSearchStringMax;
	}
	if( TYPE_LDAPAddressAutoSearchStringMax < us_Position ) {
		us_Position = TYPE_LDAPAddressAutoSearchStringMax;
	}

	Bool b_Search = True;

	// 文字数が同じ時.
	if( us_InputStringLen == us_SearchStringLen ) {
		// 文字が一致する時.
		if( 0 == strncmp( sc_InputString, sc_SearchString, us_InputStringLen ) ) {
			b_Search = False;
		}
	}

	// 検索が必要な時.
	if( True == b_Search ) {
		strncpy( sc_SearchString, sc_InputString, TYPE_LDAPAddressAutoSearchStringMax );

		if( 0 == us_Position ) {
			us_SearchLen = ( ushort )strlen( sc_SearchString );
		} else {
			us_SearchLen = us_Position;
		}

		// アルファベット、数字、ハイフン(-)、記号以外が文字にあるときは、その文字の手前まで検索対象とする.
		for( ushort i = 0; i < us_SearchLen; i++ ) {

			// アルファベット、数字、ハイフン(-)、記号の時.
			// 予測入力画面からこれらの文字以外は入力できないはずだが、念の為プロテクト.
			if( ( 0x21 <= sc_SearchString[i] ) && ( 0x7E >= sc_SearchString[i] ) ) {
				// 何もしない.
			} else {
				us_SearchLen = i;
				break;
			}
		}
		if( 0 == us_SearchLen ) {
			b_Search = False;
		}
	}
	return b_Search;
}

//------------------------------------------------------------------------------.
/**
* @brief LDAP宛先自動検索共通クラス : 検索キャンセル要求.
*/
//------------------------------------------------------------------------------.
void PNLC_LDAPAddressAutoSearch::cancelLdapSearch()
{
	// キャンセル処理実行.
	APIC_LdapSearch* pc_LdapSearch = APIC_LdapSearch::newInstance();
	pc_LdapSearch->req_cancel( CallBackLDAPAddressAutoSearchCancel );
}

//------------------------------------------------------------------------------.
/**
* @brief LDAP宛先自動検索共通クラス : 検索結果取得.
*/
//------------------------------------------------------------------------------.
void PNLC_LDAPAddressAutoSearch::getLdapSearchResult()
{
	APIC_LdapSearch* pc_LdapSearch = APIC_LdapSearch::newInstance();
	// 状態の取得.
	TYPE_LdapSearchStatus e_LdapSearchStatus = pc_LdapSearch->getSearchStatus();

	// 「登録宛先から」画面からの遷移時、常用宛先検索のコールバック（TYPE_PNL_CallBack_serchComplate）を本画面で受ける可能性があるため、初期状態を処理無しとして抜ける.
	if( TYPE_LdapSearchStatusInit == e_LdapSearchStatus ) {
		return;
	}
	// 状態が検索の時.
	if( TYPE_LdapSearchStatusSearch == e_LdapSearchStatus ) {
		memset( sc_SearchResultString, 0, sizeof( sc_SearchResultString ) );
		// 索結果があるとき.
		if( 0 < pc_LdapSearch->getTotalSearchCount() ) {
			Bool b_Smime = False;
			if( ( True == onlyPanel.isSearchDigitalID() )
			    || ( True == onlyPanel.isEquivalentAddressOn() )
			    || ( NULL != PnlComGetJobScanFax() &&( True == PnlComGetJobScanFax()->getJobSpec()->pc_Send->c_MailSend.getSmimeEnableCrypt() ) ) ) {
				b_Smime = True;
			}

			TYPS_LdapSearchResult* ps_index;
			if( True == b_Smime ) {
				pc_LdapSearch->getResultListSmime( 1, TYPE_LdapSearchGetListTypeFirst, &c_ResultListSmime );

				TYPS_LdapSearchResultSmime* ps_LdapSearchResultCpySmime;
				c_ResultListSmime.Lock();
				ps_LdapSearchResultCpySmime = c_ResultListSmime.findFirst();
// comment 2018/01/22 【HCL-Rajesh】 [IT5_4.2] Klockwork Changes ID: 396040 [CONC.NO_UNLOCK].
//				if( NULL == ps_LdapSearchResultCpySmime ) { LOGF_debug_PutEventLog( LOGF_DEBUG_EVENT_KIND_ALL, 0, LOGD_DEBUG_LEVEL_UNKNOWN, "Assert Failed!" ); return; }
				if( NULL == ps_LdapSearchResultCpySmime ) { 
					LOGF_debug_PutEventLog( LOGF_DEBUG_EVENT_KIND_ALL, 0, LOGD_DEBUG_LEVEL_UNKNOWN, "Assert Failed!" );
					c_ResultListSmime.UnLock();
					return; 
				}
				// リストを空にする.
				c_ResultList.Lock();
				while( NULL != ( ps_index = c_ResultList.findFirst() ) ) {
					c_ResultList.del( ps_index );
				}
				// リストに追加.
				c_ResultList.add( &( ps_LdapSearchResultCpySmime->s_LdapSearchResult ) );
				c_ResultList.UnLock();
				ss_SearchResultx509size = ps_LdapSearchResultCpySmime->ss_x509size;
				if( 0 != ss_SearchResultx509size ) {
					memcpy( sc_SearchResultx509, ps_LdapSearchResultCpySmime->sc_x509, TYPD_SmimeCert );
				}
				// リスト移動.
				ps_LdapSearchResultCpySmime = c_ResultListSmime.findNext();
				c_ResultListSmime.UnLock();
			} else {
				pc_LdapSearch->getResultList( 1, TYPE_LdapSearchGetListTypeFirst, &c_ResultList );
			}
			// 検索結果の内、メールアドレスを取得する.
			ps_index = c_ResultList.findFirst();
			if( NULL != ps_index ) {
				struct ps_LdapSearchResult s_LdapSearchResultString = PNLC_LdapSearchManager::newInstance()->setupResultFromUTF8API( ps_index );
				strncpy( sc_SearchResultString, s_LdapSearchResultString.sc_MailAddressResultString, sizeof(sc_SearchResultString)-1 );
				sc_SearchResultString[sizeof(sc_SearchResultString)-1] = '\0';
				strncpy( sc_SearchResultName, s_LdapSearchResultString.sc_NameResultString, sizeof(sc_SearchResultName)-1 );
				sc_SearchResultName[sizeof(sc_SearchResultName)-1] = '\0';
			}
		}
	}
}

//------------------------------------------------------------------------------.
/**
* @brief LDAP宛先自動検索共通クラス : 認証処理.
*/
//------------------------------------------------------------------------------.
void PNLC_LDAPAddressAutoSearch::startLdapConnect()
{
	TYPC_LdapSetting c_LdapSetting;
	memset( &c_LdapSetting, 0, sizeof( c_LdapSetting ) );

	APIC_User* pc_LoginUser = PnlComGetUser();
	if( NULL ==pc_LoginUser ) {
		return;				// 静的解析 2012/09/03 第一OPS 酒井(健).
	}
	// LDAPサーバ設定パラメータ作成.
	c_LdapSetting.uc_LdapSettingFlag = ( TYPD_LdapSettingFlagServerAddress | TYPD_LdapSettingFlagLoginName | TYPD_LdapSettingFlagPassword );

	// サーバーのインデックス設定.
	if( 0 == uc_ServerIndex ) {
		// デフォルトサーバーのインデックス設定（現在の仕様では、必ずデフォルトサーバーを使用します）.
		uc_ServerIndex = ( uchar )PnlComGetLdapSetting()->getDefaultLdapServer() ;
	}

	APIC_LdapSetting* pc_LdapSetting = PnlComGetLdapSetting( uc_ServerIndex );
	if( NULL == pc_LdapSetting ) { LOGF_debug_PutEventLog( LOGF_DEBUG_EVENT_KIND_ALL, 0, LOGD_DEBUG_LEVEL_UNKNOWN, "Assert Failed!" ); return; }
	// ホスト名設定.
	pc_LdapSetting->getServerAddressUTF8( c_LdapSetting.sc_ServerAddressUTF8, LIBE_CharSetUTF8 );

	// ユーザー名・パスワード設定.
	b_LdapUserAuthenticationInput = True;
	TYPE_LdapUserAuthentication e_LdapUserAuthentication = pc_LdapSetting->getLdapUserAuthentication();
	switch( e_LdapUserAuthentication ) {
		// 設定値を使用.
		case TYPE_LdapUserAuthenticationInput:
		// Dynamic認証.
		case TYPE_LdapUserAuthenticationDynamicAuthentication:
			pc_LdapSetting->getLoginNameUTF8( c_LdapSetting.sc_LoginNameUTF8, LIBE_CharSetUTF8 );
			pc_LdapSetting->getPasswordUTF8( c_LdapSetting.sc_PasswordUTF8, LIBE_CharSetUTF8 );
			break;
		// ユーザー認証を使用.
		case TYPE_LdapUserAuthenticationUserAuthentication:
		{
			Bool b_UserAccountOn = PnlComGetUserAccountOn();
			Bool b_TrackOn = PnlComGetTrackOn();

			if( True == b_UserAccountOn ) {						// ユーザー認証ありの時.
				APIC_AuthenticationSeverSetting* apicAuth = APIC_AuthenticationSeverSetting::newInstance();

				if( apicAuth->getAuthCardSearch(PNLC_NetworkLan::getInstance()->getLine()) ) {																		// 認証カード検索がON.
					pc_LdapSetting->getLoginNameUTF8( c_LdapSetting.sc_LoginNameUTF8, LIBE_CharSetUTF8 );
					if( True == PLBC_FuncPKICheck::isPKI() ) {
// comment 2016/11/22 Sky東島 [特ROM][AU DoD].
						if( True == onlyPanel.getMfpLoginOnPKIMode() ){
							PnlComGetUser()->getUserPassword( c_LdapSetting.sc_PasswordUTF8 , True );
						} else {
							// PKI時はPKIのPINコードをパスワードとして使用する.
							APIC_AuthDevicePkiCommon* apicAuthDevPkiCom = APIC_AuthDevicePkiCommon::newInstance();
							if( NULL != apicAuthDevPkiCom ) {
								apicAuthDevPkiCom->getCachePinCode( ( uchar* )c_LdapSetting.sc_PasswordUTF8, False );
							}
						}
					} else {
						pc_LdapSetting->getPasswordUTF8( c_LdapSetting.sc_PasswordUTF8, LIBE_CharSetUTF8 );
					}
				} else {
					pc_LoginUser->getUserNameUTF8( c_LdapSetting.sc_LoginNameUTF8, LIBE_CharSetUTF8 );		// 静的解析 2012/09/03 第一OPS 酒井(健).
					Bool bServerPass = False;
					if( ( TYPE_UserAuthenticationServer              == PnlComGetLoginUserAuthenticationType() )
					    || ( TYPE_UserAuthenticationIntermeddiateServer == PnlComGetLoginUserAuthenticationType() ) ) {
						bServerPass = True;
					}
					if( True == PLBC_FuncPKICheck::isPKI() ) {
// comment 2016/11/22 Sky東島 [特ROM][AU DoD].
						if( True == onlyPanel.getMfpLoginOnPKIMode() ){
							PnlComGetUser()->getUserPassword( c_LdapSetting.sc_PasswordUTF8 , True );
						} else {
							// PKI時はPKIのPINコードをパスワードとして使用する.
							APIC_AuthDevicePkiCommon* apicAuthDevPkiCom = APIC_AuthDevicePkiCommon::newInstance();
							if( NULL != apicAuthDevPkiCom ) {
								apicAuthDevPkiCom->getCachePinCode( ( uchar* )c_LdapSetting.sc_PasswordUTF8, False );
							}
						}
					} else {
						PnlComGetUser()->getUserPassword( c_LdapSetting.sc_PasswordUTF8 , bServerPass );
					}
					b_LdapUserAuthenticationInput = False;
				}
			} else if( True == b_TrackOn ) {						// 部門認証ありの時.
				// 部門名認証ありの時.
				if( TYPE_TrackModeOnlyPassword != PnlComGetTrackManager()->getTrackMode(PNLC_NetworkLan::getInstance()->getLine()) ) {
					// 部門名称をユーザー名に設定.
					PnlComGetTrack()->getTrackName( c_LdapSetting.sc_LoginNameUTF8 );
				}
				// 部門パスワードをパスワードに設定.
				PnlComGetTrack()->getTrackPassword( c_LdapSetting.sc_PasswordUTF8 );
				b_LdapUserAuthenticationInput = False;
			} else {											// 上記以外の時.
				pc_LdapSetting->getLoginNameUTF8( c_LdapSetting.sc_LoginNameUTF8, LIBE_CharSetUTF8 );
				if( True == PLBC_FuncPKICheck::isPKI() ) {
					// PKI時はPKIのPINコードをパスワードとして使用する.
					APIC_AuthDevicePkiCommon* apicAuthDevPkiCom = APIC_AuthDevicePkiCommon::newInstance();
					if( NULL != apicAuthDevPkiCom ) {
						apicAuthDevPkiCom->getCachePinCode( ( uchar* )c_LdapSetting.sc_PasswordUTF8, False );
					}
				} else {
					pc_LdapSetting->getPasswordUTF8( c_LdapSetting.sc_PasswordUTF8, LIBE_CharSetUTF8 );
				}
			}
		}
		break;
		default:	break;
	}

	APIC_LdapSearch* pc_LdapSearch = APIC_LdapSearch::newInstance();
	pc_LdapSearch->setAutoConnect( False );															// 自動接続を無効にする.
	e_ConnectStatus = TYPE_LDAPAddressAutoSearchConnectExecu;										// 接続・認証中に設定.
// comment 2016/09/27 Sky大濵  [特ROM][AU DoD] 認証状況通知.
//	pc_LdapSearch->req_connect( &c_LdapSetting, CallBackLDAPConnect, uc_ServerIndex );				// 認証.
	if( ( False == PLBC_FuncPKICheck::isPKI() ) || ( True == onlyPanel.getMfpLoginOnPKIMode() ) ) {	// PKIモード無効 または ID/パスワード認証.
// comment 2017/11/23 【HCL-Suganya】【IT5_4.2】【RQ686】 Multiple Network Support.
//		pc_LdapSearch->req_connect( &c_LdapSetting, CallBackLDAPConnect, uc_ServerIndex, TYPE_PKILoginModePassword );
		pc_LdapSearch->req_connect( &c_LdapSetting, CallBackLDAPConnect, uc_ServerIndex, TYPE_PKILoginModePassword , PNLC_NetworkLan::getInstance()->getLine() );
	} else {																						// カード認証.
// comment 2017/11/23 【HCL-Suganya】【IT5_4.2】【RQ686】 Multiple Network Support.
//		pc_LdapSearch->req_connect( &c_LdapSetting, CallBackLDAPConnect, uc_ServerIndex );
		pc_LdapSearch->req_connect( &c_LdapSetting, CallBackLDAPConnect, uc_ServerIndex , TYPE_PKILoginModeCard, PNLC_NetworkLan::getInstance()->getLine() );
	}
	PNLC_LdapSearchManager::newInstance()->initLdapSettingInfo();									// LDAP認証情報を初期化.
	PNLC_LdapSearchManager::newInstance()->setLdapSettingInfo( &c_LdapSetting );						// LDAP認証情報を保存(LDAP検索時に使用する).

	PNLC_ScanFaxDataLib::newInstance()->setSelectHostNum( uc_ServerIndex );							// 接続する LDAP サーバを設定.
}

//------------------------------------------------------------------------------.
/**
* @brief LDAP宛先自動検索共通クラス : 再認証処理.
*/
//------------------------------------------------------------------------------.
void PNLC_LDAPAddressAutoSearch::restartLdapConnect()
{
	APIC_LdapSetting* pc_LdapSetting = PnlComGetLdapSetting( uc_ServerIndex );
	if( NULL == pc_LdapSetting ) { LOGF_debug_PutEventLog( LOGF_DEBUG_EVENT_KIND_ALL, 0, LOGD_DEBUG_LEVEL_UNKNOWN, "Assert Failed!" ); return; }
	TYPC_LdapSetting c_LdapSetting;
	b_LdapUserAuthenticationInput = True;

	pc_LdapSetting->getServerAddressUTF8( c_LdapSetting.sc_ServerAddressUTF8, LIBE_CharSetUTF8 );	// ホスト名設定.
	pc_LdapSetting->getLoginNameUTF8( c_LdapSetting.sc_LoginNameUTF8, LIBE_CharSetUTF8 );				// ユーザー名設定.
	pc_LdapSetting->getPasswordUTF8( c_LdapSetting.sc_PasswordUTF8, LIBE_CharSetUTF8 );				// パスワード設定.

	APIC_LdapSearch* pc_LdapSearch = APIC_LdapSearch::newInstance();
	pc_LdapSearch->setAutoConnect( False );															// 自動接続を無効にする.
	e_ConnectStatus = TYPE_LDAPAddressAutoSearchConnectExecu;										// 接続・認証中に設定
// comment 2016/09/27 Sky大濵  [特ROM][AU DoD] 認証状況通知.
//	pc_LdapSearch->req_connect( &c_LdapSetting, CallBackLDAPConnect, uc_ServerIndex );				// 認証.
	if( ( False == PLBC_FuncPKICheck::isPKI() ) || ( True == onlyPanel.getMfpLoginOnPKIMode() ) ) {	// PKIモード無効 または ID/パスワード認証.
// comment 2017/11/23 【HCL-Suganya】【IT5_4.2】【RQ686】 Multiple Network Support.
//		pc_LdapSearch->req_connect( &c_LdapSetting, CallBackLDAPConnect, uc_ServerIndex, TYPE_PKILoginModePassword );
		pc_LdapSearch->req_connect( &c_LdapSetting, CallBackLDAPConnect, uc_ServerIndex, TYPE_PKILoginModePassword , PNLC_NetworkLan::getInstance()->getLine() );
	} else {																						// カード認証.
// comment 2017/11/23 【HCL-Suganya】【IT5_4.2】【RQ686】 Multiple Network Support.
//		pc_LdapSearch->req_connect( &c_LdapSetting, CallBackLDAPConnect, uc_ServerIndex );
		pc_LdapSearch->req_connect( &c_LdapSetting, CallBackLDAPConnect, uc_ServerIndex , TYPE_PKILoginModeCard, PNLC_NetworkLan::getInstance()->getLine() );
	}
	PNLC_LdapSearchManager::newInstance()->initLdapSettingInfo();									// LDAP認証情報を初期化.
	PNLC_LdapSearchManager::newInstance()->setLdapSettingInfo( &c_LdapSetting );						// 	LDAP認証情報を保存(LDAP検索時に使用する).
}
//------------------------------------------------------------------------------.
/**
* @brief サーバー稼動状態取得(ユーザー認証画面専用).
*/
//------------------------------------------------------------------------------.
Bool PnlComServerStatus( Bool b_UserAuthTypeApp )
{
	TYPE_UserAuthentication e_UserAuthentication = PnlComGetUserAuthentication()->getUserAuthentication(PNLC_NetworkLan::getInstance()->getLine());
	// 認証方式が外部サーバー認証 又は 本体＋外部サーバー認証以外の時は、稼働中でリターンする
	if( ( TYPE_UserAuthenticationServer != e_UserAuthentication ) && ( TYPE_UserAuthenticationDeviceAndServer != e_UserAuthentication ) ) {
		return True;
	}
	APIC_AuthenticationSeverSetting* apicAuth = APIC_AuthenticationSeverSetting::newInstance();
	if( NULL == apicAuth ) {LOGF_debug_PutEventLog( LOGF_DEBUG_EVENT_KIND_ALL, 0, LOGD_DEBUG_LEVEL_UNKNOWN, "Assert Failed!" ); return True;}

	APID_AuthenticationServerIndex uc_StartIndex;
	APID_AuthenticationServerIndex uc_EndIndex;
	APID_AuthenticationServerIndex i;

	if( True == b_UserAuthTypeApp ) {							// 認証装置による認証画面
		if( True == apicAuth->getAuthCardSearch(PNLC_NetworkLan::getInstance()->getLine()) ) {			// 認証カード検索機能がONの時.
			uc_StartIndex = APID_AuthenticationSeverTypeIccLDAP;
			uc_EndIndex   = APID_AuthenticationSeverTypeIccLDAP;
		} else {												// 認証カード検索機能がOFFの時.
			return True;
		}
	} else {													// 上記以外のよる認証画面
		uc_StartIndex = 1;
		uc_EndIndex   = APID_MaxNumberOfAuthenticationSever;
	}

	Bool b_ServerStatus;
	for( i = uc_StartIndex; i <= uc_EndIndex; i++ ) {
		b_ServerStatus = apicAuth->getServerStatus( i , PNLC_NetworkLan::getInstance()->getLine());			// サーバー稼動状態取得.
		if( False == b_ServerStatus ) {							// サーバーダウン中の時.
			return False;
		}
	}
	return True;
}

//------------------------------------------------------------------------------.
/**
* @brief サーバー稼動状態取得(すべての外部サーバーをチェック).
*/
//------------------------------------------------------------------------------.
Bool PnlComServerStatusAll()
{
	TYPE_UserAuthentication e_UserAuthentication = PnlComGetUserAuthentication()->getUserAuthentication(PNLC_NetworkLan::getInstance()->getLine());
	// 認証方式が外部サーバー認証 又は 本体＋外部サーバー認証以外の時は、稼働中でリターンする
	if( ( TYPE_UserAuthenticationServer != e_UserAuthentication ) && ( TYPE_UserAuthenticationDeviceAndServer != e_UserAuthentication ) ) {
		return True;
	}
	APIC_AuthenticationSeverSetting* apicAuth = APIC_AuthenticationSeverSetting::newInstance();
	if( NULL == apicAuth ) {LOGF_debug_PutEventLog( LOGF_DEBUG_EVENT_KIND_ALL, 0, LOGD_DEBUG_LEVEL_UNKNOWN, "Assert Failed!" ); return True;}

	Bool b_ServerStatus;
	APID_AuthenticationServerIndex i;
	// 外部サーバーのサーバー稼動状態.
	for( i = 1; i <= APID_MaxNumberOfAuthenticationSever; i++ ) {
		b_ServerStatus = apicAuth->getServerStatus( i , PNLC_NetworkLan::getInstance()->getLine());			// サーバー稼動状態取得.
		if( False == b_ServerStatus ) {							// サーバーダウン中の時.
			return False;
		}
	}

	APID_AuthServerGroupIndex uc_Index = APID_AuthServerGroupIndexNone;
	Bool b_chkIccChange = PnlComGetAuthDeviceCommon()->checkIccChangeAuthServer();

// comment 2017/10/31 【HCL-TANU】【IT5_4.2】【RQ686】【IT Defect AR1030817].
//	Bool b_Midauth = PnlComGetUserAuthentication()->getMidauthControl();
	Bool b_Midauth = PnlComGetUserAuthentication()->getMidauthControl(PNLC_NetworkLan::getInstance()->getLine());
	// 認証カード検索用のサーバーのサーバー稼動状態.
	if( ( False == b_chkIccChange ) || ( True == b_Midauth ) ) {
		// LDAP-ICカード認証用のサーバーのサーバー稼動状態を取得.
		b_ServerStatus = apicAuth->getServerStatus( APID_AuthenticationSeverTypeIccLDAP , PNLC_NetworkLan::getInstance()->getLine());	// サーバー稼動状態取得.
		if( False == b_ServerStatus ) {														// サーバーダウン中の時.
			return False;
		}
	} else {
		// 全てのLDAP-ICカード認証用のサーバーのサーバー稼動状態を取得.
		for( uc_Index = APID_AuthenticationServerIndexIccLdapMin; uc_Index <= APID_AuthenticationServerIndexIccLdapMax; uc_Index++ ) {
			b_ServerStatus = apicAuth->getServerStatus( static_cast<APID_AuthenticationServerIndex>( uc_Index ), PNLC_NetworkLan::getInstance()->getLine() );	// サーバー稼動状態取得.
			if( False == b_ServerStatus ) {																			// サーバーダウン中の時.
				return False;
			}
		}
	}
	return True;
}
typedef uchar TYPE_AuthModuleStatus;
#define  TYPE_AuthModuleStatusInitialize		0x01		//!< 認証FUMが初期化完了したかどうか.
#define  TYPE_AuthModuleStatusReserve			0x02		//!< 認証FUMが初期化完了するまでに認証サービスを実行したかどうか.
#define  TYPE_AuthModuleStatusStart				0x04		//!< 認証FUMの認証サービスを実行したかどうか.
#define  TYPE_AuthModuleStatusStop				0x08		//!< 認証FUMの認証サービスが中断している.
static TYPE_AuthModuleStatus e_AuthModuleStatus = 0x00;
// comment Sky東島 [RQ-686] 複合機の複数ネットワーク対応.
//------------------------------------------------------------------------------.
//
// @brief ポーリングを行うネットワークの取得.
//
//------------------------------------------------------------------------------.
TYPE_NetworkSpecific isPollingRequestNetwork()
{
	if( True == PNLC_NetworkLan::getInstance()->getVlanSetting() ){
// comment 2019/05/28 [HCL-Naveena][EagleBK] NetworkType Default selection activity.
//		TYPE_NetworkSpecific e_NowNW = PNLC_NetworkLan::getInstance()->getLine();		// 現在のネットワーク.
		TYPE_NetworkSpecific e_NowNW = PNLC_NetworkLan::getInstance()->getLineForPanel();
		if( ( TYPE_NetworkSpecific_NONE != e_NowNW )
		 && ( TYPE_UserAuthenticationOff != ppc_UserAuthentication->getUserAuthentication(e_NowNW) ) ){
			return e_NowNW;
		}

// comment [2018/03/12] [HCLT-Satheesh][AR1041136] Polling Restart Request stopped for Auto Login Logout when VLAN setting is enabled.
		if( TYPE_NetworkSpecific_NONE == e_NowNW ) {
			TYPE_AUTH_DEVICE_TYPE e_DeviceType = PnlComGetAuthDeviceSetting()->getAuthDeviceType();
			if( TYPE_AuthDeviceType_None != e_DeviceType ){
				if( ( TYPE_UserAuthenticationOff != ppc_UserAuthentication->getUserAuthentication( TYPE_NetworkSpecific_NW1 )
					&& TYPE_UserAuthenticationOff != ppc_UserAuthentication->getUserAuthentication( TYPE_NetworkSpecific_NW2 ) ) ) {
					return TYPE_NetworkSpecific_NONE;
				}
			}
		}

		// 他の認証が有効なネットワークを検索する.
		TYPE_NetworkSpecific i;
		for( i = TYPE_NetworkSpecific_NW1; i < TYPE_NetworkSpecific_MAX; i++ ){
			if(TYPE_UserAuthenticationOff != ppc_UserAuthentication->getUserAuthentication(i)){
				break;
			}
		}
		if( TYPE_NetworkSpecific_MAX == i ){
			return TYPE_NetworkSpecific_NONE;
		} else {
			return i;
		}
	} else {
		return TYPE_NetworkSpecific_NW1;
	}
}

// comment 2021/02/01 [IT6-54(機種マージ)] Sky下野 セルフレジスト時のICカードチェック機能対応.
//------------------------------------------------------------------------------.
//
// @brief 認証ポーリング実行状態取得.
//
//------------------------------------------------------------------------------.
Bool PnlComGetAuthPollingStatusStart() {

	if( TYPE_AuthModuleStatusStart == ( e_AuthModuleStatus & TYPE_AuthModuleStatusStart ) ) {
		return True;
	} else {
		return False;
	}

}
//------------------------------------------------------------------------------.
//
// @brief 認証ポーリング実行状態設定.
//
//------------------------------------------------------------------------------.
void PnlComSetAuthPollingStatusStart() {

	e_AuthModuleStatus |= TYPE_AuthModuleStatusStart;				// 認証FUMの認証サービスを実行.
	
	PM_TaskID priTask;
	PMGC_PanelManager::getPriority( &priTask );
	ExpPanelLog( PNLD_ExpLogKind_AuthDevicePoling, "[LocalUI][AuthPolling][PriTask:%d] PnlComSetAuthPollingStatusStart e_AuthModuleStatus[%d]", priTask, e_AuthModuleStatus, 0, 0, 0, 0 );

}

//------------------------------------------------------------------------------.
//
// @brief 認証ポーリング中断状態取得.
//
//------------------------------------------------------------------------------.
Bool PnlComGetAuthPollingStatusStop() {

	if( TYPE_AuthModuleStatusStop == ( e_AuthModuleStatus & TYPE_AuthModuleStatusStop ) ) {
		return True;
	} else {
		return False;
	}

}
//------------------------------------------------------------------------------.
//
// @brief 認証ポーリング中断状態設定.
//
//------------------------------------------------------------------------------.
void PnlComSetAuthPollingStatusStop() {

	e_AuthModuleStatus |= TYPE_AuthModuleStatusStop;				//  認証FUMの認証サービスを中断.
	// ポーリングの中断ではなく、再開で初期化するべき.
	
// comment 2020/07/01 Sky菅野 ログ強化改善.
	PM_TaskID priTask;
	PMGC_PanelManager::getPriority( &priTask );
	ExpPanelLog( PNLD_ExpLogKind_AuthDevicePoling, "[LocalUI][AuthPolling][PriTask:%d] PnlComSetAuthPollingStatusStop e_AuthModuleStatus[%d]", priTask, e_AuthModuleStatus, 0, 0, 0, 0 );

}
//------------------------------------------------------------------------------.
//
// @brief 認証ポーリング再開要求.
//
//------------------------------------------------------------------------------.
void PnlComReqAuthPollingRestart() {

// comment 2020/07/01 Sky菅野 ログ強化改善.
	PM_TaskID priTask;
	PMGC_PanelManager::getPriority( &priTask );
	ExpPanelLog( PNLD_ExpLogKind_AuthDevicePoling, "[LocalUI][AuthPolling][PriTask:%d] PnlComReqAuthPollingRestart e_AuthModuleStatus[%d]", priTask, e_AuthModuleStatus, 0, 0, 0, 0 );
	
	if( False == PnlComGetAuthPollingStatusStop() ) {					// 認証ポーリングが中断していない場合.
		ExpPanelLog( PNLD_ExpLogKind_AuthDevicePoling, "[LocalUI][AuthPolling][PriTask:%d] PnlComReqAuthPollingRestart return e_AuthModuleStatus[%d]", priTask, e_AuthModuleStatus, 0, 0, 0, 0 );	// comment 2020/07/01 Sky菅野 ログ強化改善.
		return;
	}
// comment Sky東島 [RQ-686] 複合機の複数ネットワーク対応.
	TYPE_NetworkSpecific e_isPollingRequestNetwork = isPollingRequestNetwork();
	if( TYPE_NetworkSpecific_NONE == e_isPollingRequestNetwork ){
		ExpPanelLog( PNLD_ExpLogKind_AuthDevicePoling, "[LocalUI][AuthPolling][PriTask:%d] PnlComReqAuthPollingRestart return e_AuthModuleStatus[%d]", priTask, e_AuthModuleStatus, 0, 0, 0, 0 );	// comment 2020/07/01 Sky菅野 ログ強化改善.
		return;
	}
	
	//comment 2021/04/20 2DWS2G-Sky松田 クラウドSSO認証開発v1_Step2 OP_BTS-32831.
	if(True==APIC_UserAuthentication::newInstance()->getICCardAuthenticationForIdP()){
		if(NULL==PnlComGetUser()){
			ExpPanelLog( PNLD_ExpLogKind_AuthDevicePoling, "[LocalUI][AuthPolling][PriTask:%d] PnlComReqAuthPollingRestart return e_AuthModuleStatus[%d]", priTask, e_AuthModuleStatus, 0, 0, 0, 0 );
			return;
		}
	}
	
	e_AuthModuleStatus &= (TYPE_AuthModuleStatus)( ~TYPE_AuthModuleStatusStop );				// 認証FUMの認証サービスを中断解除.
	// ポーリングの中断ではなく、再開で初期化するべき.
	onlyPanel.e_AuthDeviceTouch = TYPE_AuthDeviceTouch_None;		// 認証装置の状態を初期化.

	ExpPanelLog( PNLD_ExpLogKind_AuthDevicePoling, "[LocalUI][AuthPolling][PriTask:%d] PnlComReqAuthPollingRestart -RequestRestart- e_AuthModuleStatus[%d], e_isPollingRequestNetwork[%d]", priTask, e_AuthModuleStatus, e_isPollingRequestNetwork, 0, 0, 0 );	// comment 2020/07/01 Sky菅野 ログ強化改善.
	PnlComGetAuthDeviceCommon()->reqAuthPollingTerminate();			// ポーリング終了リクエスト.
// comment Sky東島 [RQ-686] 複合機の複数ネットワーク対応.
	PnlComGetAuthDeviceCommon()->requestSelectNetwork(e_isPollingRequestNetwork);
	PnlComGetAuthDeviceCommon()->reqAuthPollingStart();				// ポーリング開始リクエスト.
	// ポーリング再開要求時に認証データをクリアしておく..
	// 拡張サーバー認証時に使用する情報をクリア.
	PCGC_AuthOapCommonStaticLib::cAuthDeviceConnect->clear();
	// 本体認証、外部サーバー認証時に使用する情報をクリア.
	char sc_AuthUserName[ PCGD_UserNameUTF8_193 ];	// 認証装置スキャン成功時に通知されるユーザー名.
	char sc_AuthPassword[ PCGD_UserPasswordUTF8 ];	// 認証装置スキャン成功時に通知されるパスワード.
	memset( sc_AuthUserName, '\0', sizeof( sc_AuthUserName ) );
	memset( sc_AuthPassword, '\0', sizeof( sc_AuthPassword ) );
	PNLC_ActionDataLib* pc_ActionDataLib=PNLC_ActionDataLib::newInstance();
	pc_ActionDataLib->setAuthDeviceNotifyResult( False );
	pc_ActionDataLib->setAuthDeviceNotifyUserName( sc_AuthUserName );
	pc_ActionDataLib->setAuthDeviceNotifyPassword( sc_AuthPassword );
	pc_ActionDataLib->setAuthDeviceNotifyDetailResult( APID_AUTH_SUCCESS );
	pc_ActionDataLib->setAuthDeviceNotifyResultType( APID_AUTH_FAILED );

	gp_UserAccountUser_act.setAuthDeviceNotifyResult( False );
	gp_UserAccountUser_act.setAuthDeviceNotifyResultType( APID_AUTH_FAILED );
	gp_UserAccountUser_act.setAuthDeviceNotifyUserName( sc_AuthUserName );
	gp_UserAccountUser_act.setAuthDeviceNotifyPassword( sc_AuthPassword );
	gp_UserAccountUser_act.setAuthDeviceNotifyDetailResult( APID_AUTH_SUCCESS );
	gp_UserAccountUserPopup_act.setAuthDeviceNotifyResult( False );
	gp_UserAccountUserPopup_act.setAuthDeviceNotifyResultType( APID_AUTH_FAILED );
	gp_UserAccountUserPopup_act.setAuthDeviceNotifyUserName( sc_AuthUserName );
	gp_UserAccountUserPopup_act.setAuthDeviceNotifyPassword( sc_AuthPassword );

	gp_UserAccountUser_act_SeqCustom.setAuthDeviceNotifyResult( False );
	gp_UserAccountUser_act_SeqCustom.setAuthDeviceNotifyResultType( APID_AUTH_FAILED );
	gp_UserAccountUser_act_SeqCustom.setAuthDeviceNotifyUserName( sc_AuthUserName );
	gp_UserAccountUser_act_SeqCustom.setAuthDeviceNotifyPassword( sc_AuthPassword );
	gp_UserAccountUser_act_SeqCustom.setAuthDeviceNotifyDetailResult( APID_AUTH_SUCCESS );
	gp_UserAccountUserPopup_act_SeqCustom.setAuthDeviceNotifyResult( False );
	gp_UserAccountUserPopup_act_SeqCustom.setAuthDeviceNotifyResultType( APID_AUTH_FAILED );
	gp_UserAccountUserPopup_act_SeqCustom.setAuthDeviceNotifyUserName( sc_AuthUserName );
	gp_UserAccountUserPopup_act_SeqCustom.setAuthDeviceNotifyPassword( sc_AuthPassword );
}

// comment 2016/01/06 OPS1-Sky浜野 [MinervaSBK][CQ523134].
//------------------------------------------------------------------------------.
//
// @brief 認証情報初期化処理.
//
//------------------------------------------------------------------------------.		
void PnlComClearAuthDeviceData()
{
// comment 2020/07/01 Sky菅野 ログ強化改善.
	PM_TaskID priTask;
	PMGC_PanelManager::getPriority( &priTask );
	ExpPanelLog( PNLD_ExpLogKind_AuthDevicePoling, "[LocalUI][AuthPolling][PriTask:%d] PnlComClearAuthDeviceData e_AuthModuleStatus[%d]", priTask, e_AuthModuleStatus, 0, 0, 0, 0 );
	// ポーリング停止中でない場合.
	// ポーリングを強制的に再起動する.
	// ※カード検知の認証通知後、ウィークリータイマーで中止を行った場合.
	//   ログイン処理が実施されない為、カード検知状態が継続されるため、以降のカード検知がされない.
	//   そのため、ポーリング停止⇒開始を行うことで、カード検知状態をクリアする.
	if( False == PnlComGetAuthPollingStatusStop() ){
		ExpPanelLog( PNLD_ExpLogKind_AuthDevicePoling, "[LocalUI][AuthPolling][PriTask:%d] PnlComClearAuthDeviceData Restart e_AuthModuleStatus[%d]", priTask, e_AuthModuleStatus, 0, 0, 0, 0 );	// comment 2020/07/01 Sky菅野 ログ強化改善.
		PnlComSetAuthPollingStatusStop();		// ポーリング中断状態を設定.
		PnlComReqAuthPollingRestart();			// ポーリング再開させる。
	} 
}

//関数-----------------------------------------------------------------------------------------------------------------.
//概要　　：isExtAuthDeviceLoginsupportEnable()
//作成者　：.
//レビュー：.
//変更履歴：.

Bool isExtAuthDeviceLoginsupportEnable() {
// comment 2021/06/09 DWS2-Sky肥後 [IT6_2.2][OP_BTS-34009].	
// 従来のIWS認証ではアプリ側でポーリング制御を行っていた為、ここでFalseが返り.
// LocalUIのポーリング制御が正常に動いてなくても問題なかったが、IdP認証が有効の場合はLocalUIでポーリング制御を行う.
// 必要がある為、条件を追加する.
	if( True == APIC_UserAuthentication::newInstance()->getAuthIdPMode() && True == cp_IwsSetting->getIwsAuthScreenStartup() ) {
		if ( True == APIC_UserAuthentication::newInstance()->getICCardAuthenticationForIdP() ) {
			return True;
		}
	}
	if( True == ScanOapExtSet.isActiveGeneralApplication() ) {
		APIC_ExtSetting* apl = ScanOapExtSet.getCurrentAplInfo();
		if( NULL != apl ) {
			TYPE_ExtType e_Type = ScanOapExtSet.getExtAppType();
			TYPC_ExtAplDetail* p_extapldetail = apl->getAplDetail();
			if( NULL != p_extapldetail ) {
				switch( e_Type ) {
					case TYPE_ExtTypeScanD:
						if( NULL != p_extapldetail->getScanD() ) {
							if( TYPE_ExtLoginFromAuthDevicepossible == p_extapldetail->getScanD()->s_AuthenticationDeviceLoginInfo.e_LoginFromAuthDevice ) {
								return True;
							}
						}
						break;
					case TYPE_ExtTypePullPrint:
						if( NULL != p_extapldetail->getPullPrint() ) {
							if( TYPE_ExtLoginFromAuthDevicepossible == p_extapldetail->getPullPrint()->s_AuthenticationDeviceLoginInfo.e_LoginFromAuthDevice ) {
								return True;
							}
						}
						break;
					case TYPE_ExtTypeBrowserScan:		// スキャン連携ブラウザアプリケーション.
						if( NULL != p_extapldetail->getBrowserScan() ) {
							if( TYPE_ExtLoginFromAuthDevicepossible == p_extapldetail->getBrowserScan()->s_AuthenticationDeviceLoginInfo.e_LoginFromAuthDevice ) {
								return True;
							}
						}
						break;
					case TYPE_ExtTypeBrowserPull:		// PullPrintブラウザ連携アプリケーション.
						if( NULL != p_extapldetail->getBrowserPull() ) {
							if( TYPE_ExtLoginFromAuthDevicepossible == p_extapldetail->getBrowserPull()->s_AuthenticationDeviceLoginInfo.e_LoginFromAuthDevice ) {
								return True;
							}
						}
						break;
					case TYPE_ExtTypeBrowserGeneral:	// ブラウザ統合アプリケーション.
						if( NULL != p_extapldetail->getBrowserGeneral() ) {
							if( TYPE_ExtLoginFromAuthDevicepossible == p_extapldetail->getBrowserGeneral()->s_AuthenticationDeviceLoginInfo.e_LoginFromAuthDevice ) {
								return True;
							}
						}
						break;
					default:
						return False;
						break;
				}
				return False;
			}
		}
	}
// comment 2014/12/10 【HCL-Anusha】【CQ-506924】  Klockwork Changes ID:30333 [FUNCRET.GEN].
	return False;
}
//------------------------------------------------------------------------------.
/**
* @brief 認証ポーリング開始リクエスト.
*/
//------------------------------------------------------------------------------.
void PnlComReqAuthPollingStart()
{
// comment 2020/07/01 Sky菅野 ログ強化改善.
	PM_TaskID priTask;
	PMGC_PanelManager::getPriority( &priTask );
	ExpPanelLog( PNLD_ExpLogKind_AuthDevicePoling, "[LocalUI][AuthPolling][PriTask:%d] PnlComReqAuthPollingStart e_AuthModuleStatus[%d]", priTask, e_AuthModuleStatus, 0, 0, 0, 0 );
	
	if( PnlComGetAuthPollingStatus() ) {										//ポーリング中の場合.
		ExpPanelLog( PNLD_ExpLogKind_AuthDevicePoling, "[LocalUI][AuthPolling][PriTask:%d] PnlComReqAuthPollingStart return e_AuthModuleStatus[%d]", priTask, e_AuthModuleStatus, 0, 0, 0, 0 );	// comment 2020/07/01 Sky菅野 ログ強化改善.
		return;
	}
	if( TYPE_UserAuthenticationOff == PnlComGetUserAuthentication()->getUserAuthentication(PNLC_NetworkLan::getInstance()->getLine()) && False == isExtAuthDeviceLoginsupportEnable() ) {
		ExpPanelLog( PNLD_ExpLogKind_AuthDevicePoling, "[LocalUI][AuthPolling][PriTask:%d] PnlComReqAuthPollingStart return e_AuthModuleStatus[%d]", priTask, e_AuthModuleStatus, 0, 0, 0, 0 );	// comment 2020/07/01 Sky菅野 ログ強化改善.
		return;
	}
	// 認証情報表示エリア表示判定関数を使用するように変更.
	//if( True == PLBC_FuncVersionCheck::isOK_MiZe_Type3() 	// 機能拡張3以降.
//	if( True == PnlCom_IsEnableAutoLogoutLogin() ){
// comment 2021/05/10 2DWS2G-Sky東野 クラウドSSO認証開発v1_Step2 OP_BTS-33263 .
//	if( True == PnlCom_IsEnableAutoLogoutLogin() && False == isExtAuthDeviceLoginsupportEnable() ) {
	if( True == PnlCom_IsEnableAutoLogoutLogin() && False == isExtAuthDeviceLoginsupportEnable() && False == APIC_UserAuthentication::newInstance()->getICCardAuthenticationForIdP()) {
		PNLC_SPSAuthDataLib* pc_SPSAuthDataLib = PNLC_SPSAuthDataLib::newInstance();
		if (!pc_SPSAuthDataLib || (False == pc_SPSAuthDataLib->isSPSMode())) {
			ExpPanelLog( PNLD_ExpLogKind_AuthDevicePoling, "[LocalUI][AuthPolling][PriTask:%d] PnlComReqAuthPollingStart return e_AuthModuleStatus[%d]", priTask, e_AuthModuleStatus, 0, 0, 0, 0 );	// comment 2020/07/01 Sky菅野 ログ強化改善.
			return;
		}
	}

	if( PNLE_AuthModuleStatusRegitering_On == e_AuthModuleStatusRegitering ) {
		// 認証登録中は排他関係にある認証ポーリングを開始させない.
		ExpPanelLog( PNLD_ExpLogKind_AuthDevicePoling, "[LocalUI][AuthPolling][PriTask:%d] PnlComReqAuthPollingStart return e_AuthModuleStatus[%d]", priTask, e_AuthModuleStatus, 0, 0, 0, 0 );	// comment 2020/07/01 Sky菅野 ログ強化改善.
		return;
	}
// comment Sky東島 [RQ-686] 複合機の複数ネットワーク対応.
// comment 2019/05/28 [HCL-Naveena][EagleBK] NetworkType Default selection activity.
//	if( TYPE_NetworkSpecific_NONE == PNLC_NetworkLan::getInstance()->getLine() ){
	if( TYPE_NetworkSpecific_NONE == PNLC_NetworkLan::getInstance()->getLineForPanel() ){
		ExpPanelLog( PNLD_ExpLogKind_AuthDevicePoling, "[LocalUI][AuthPolling][PriTask:%d] PnlComReqAuthPollingStart return e_AuthModuleStatus[%d]", priTask, e_AuthModuleStatus, 0, 0, 0, 0 );	// comment 2020/07/01 Sky菅野 ログ強化改善.
		return;
	}
	TYPE_NetworkSpecific e_isPollingRequestNetwork = isPollingRequestNetwork();
	if( TYPE_NetworkSpecific_NONE == e_isPollingRequestNetwork ){
		ExpPanelLog( PNLD_ExpLogKind_AuthDevicePoling, "[LocalUI][AuthPolling][PriTask:%d] PnlComReqAuthPollingStart return e_AuthModuleStatus[%d]", priTask, e_AuthModuleStatus, 0, 0, 0, 0 );	// comment 2020/07/01 Sky菅野 ログ強化改善.
		return;
	}
// comment 2021/06/09 DWS2-Sky肥後 [IT6_2.2][OP_BTS-34009].
// 認証画面上でスリープに入ると、ユーザーはNULLのままになる為ポーリングが開始されない.
// その為、立ち上げ中画面、スクリーンセーバー画面の時はICカード設定がIDP認証のみの場合でもポーリングを開始させる.
// comment 2022/10/14 Sky東島 [IT6_2.3][OP_BTS-39280].
//	if(&gp_ActionInitialSetup != PBasicMessageProc::getNowGamen()){
	if( &gp_ActionInitialSetup != PBasicMessageProc::getNowGamen()
	 && &gp_AppChangeScreenSaver != PBasicMessageProc::getNowGamen() ){
		//comment 2021/04/20 2DWS2G-Sky松田 クラウドSSO認証開発v1_Step2 OP_BTS-32831.
		if(True==APIC_UserAuthentication::newInstance()->getICCardAuthenticationForIdP()){
			if(NULL==PnlComGetUser()){
				ExpPanelLog( PNLD_ExpLogKind_AuthDevicePoling, "[LocalUI][AuthPolling][PriTask:%d] PnlComReqAuthPollingStart return e_AuthModuleStatus[%d]", priTask, e_AuthModuleStatus, 0, 0, 0, 0 );
				return;
			}
		}
	}
	
	if( 0 == ( e_AuthModuleStatus & TYPE_AuthModuleStatusInitialize ) ) {			// 認証FUMが初期化中のとき.
		e_AuthModuleStatus |= TYPE_AuthModuleStatusReserve;						// 認証サービス実行を予約する.
		ExpPanelLog( PNLD_ExpLogKind_AuthDevicePoling, "[LocalUI][AuthPolling][PriTask:%d] PnlComReqAuthPollingStart return e_AuthModuleStatus[%d]", priTask, e_AuthModuleStatus, 0, 0, 0, 0 );	// comment 2020/07/01 Sky菅野 ログ強化改善.
		return;
	}

	if( 0 == ( e_AuthModuleStatus & TYPE_AuthModuleStatusStart ) ) {				// 認証サービス実行していないとき.
// comment Sky東島 [RQ-686] 複合機の複数ネットワーク対応.
		PnlComGetAuthDeviceCommon()->requestSelectNetwork(e_isPollingRequestNetwork);
		PnlComGetAuthDeviceCommon()->reqAuthPollingStart();						//ポーリング開始リクエスト.
		e_AuthModuleStatus |= TYPE_AuthModuleStatusStart;
		ExpPanelLog( PNLD_ExpLogKind_AuthDevicePoling, "[LocalUI][AuthPolling][PriTask:%d] PnlComReqAuthPollingStart reqAuthPollingStart e_AuthModuleStatus[%d], e_isPollingRequestNetwork[%d]", priTask, e_AuthModuleStatus, e_isPollingRequestNetwork, 0, 0, 0 );	// comment 2020/07/01 Sky菅野 ログ強化改善.

		onlyPanel.e_AuthDeviceTouch = TYPE_AuthDeviceTouch_None;				// 伊丹Sky(坂梨)  2011/07/29 CQ347753.
	}
}

//------------------------------------------------------------------------------.
/**
* @brief 認証ポーリング終了リクエスト.
*/
//------------------------------------------------------------------------------.
void PnlComReqAuthPollingTerminate()
{
// comment 2020/07/01 Sky菅野 ログ強化改善.
	PM_TaskID priTask;
	PMGC_PanelManager::getPriority( &priTask );
	ExpPanelLog( PNLD_ExpLogKind_AuthDevicePoling, "[LocalUI][AuthPolling][PriTask:%d] PnlComReqAuthPollingTerminate e_AuthModuleStatus[%d]", priTask, e_AuthModuleStatus, 0, 0, 0, 0 );
	
	if( onlyPanel.b_MidAuthProcessing ) {
		ExpPanelLog( PNLD_ExpLogKind_AuthDevicePoling, "[LocalUI][AuthPolling][PriTask:%d] PnlComReqAuthPollingTerminate return e_AuthModuleStatus[%d]", priTask, e_AuthModuleStatus, 0, 0, 0, 0 );	// comment 2020/07/01 Sky菅野 ログ強化改善.
		return;
	}
// comment 2021/06/09 DWS2-Sky肥後 [IT6_2.2][OP_BTS-34009].
// reqAuthPollingTerminateの中でカード情報を削除している.
// その為、下記条件時は自動ログインするためreturnさせる. 
	Bool bl_IdPICCardSetting  = APIC_UserAuthentication::newInstance()->getICCardAuthenticationForIdP();
	Bool bl_DefaultIdPSetting = ppc_UserAuthentication->getIdPAuthPrioritySetting();
// comment 2021/12/23 Sky蒲原 [MinervaSSBK][OP_BTS-36272]IDP認証でログアウト->ログイン中にTerminateしない.
//	if(&gp_ActionInitialSetup == PBasicMessageProc::getNowGamen()){
	if ( PCGE_LogoutLoginSts_ICCardLogout == PJobListControl::getLoginLogoutSts() // 自動ログアウト時のログアウト処理中.
	  || &gp_ActionInitialSetup == PBasicMessageProc::getNowGamen() ){
		// ICカード設定がIdP認証のみ 且つ IdP認証画面に遷移する場合.
		if( (True == bl_IdPICCardSetting) && (True == bl_DefaultIdPSetting) ){
			ExpPanelLog( PNLD_ExpLogKind_AuthDevicePoling, "[LocalUI][AuthPolling][PriTask:%d] PnlComReqAuthPollingTerminate return e_AuthModuleStatus[%d]", priTask, e_AuthModuleStatus, 0, 0, 0, 0 );
			return;
		}
		// ICカード設定がIdP認証以外のみ 且つ IdP認証画面以外に遷移する場合.
		if( (False == bl_IdPICCardSetting) && (False == bl_DefaultIdPSetting) ){
			ExpPanelLog( PNLD_ExpLogKind_AuthDevicePoling, "[LocalUI][AuthPolling][PriTask:%d] PnlComReqAuthPollingTerminate return e_AuthModuleStatus[%d]", priTask, e_AuthModuleStatus, 0, 0, 0, 0 );
			return;
		}
	}

	if( TYPE_AuthModuleStatusStart == ( e_AuthModuleStatus & TYPE_AuthModuleStatusStart ) ) {	// 認証サービス実行しているとき.

		PNLC_SPSAuthDataLib* pc_SPSAuthDataLib = PNLC_SPSAuthDataLib::newInstance();
		if (pc_SPSAuthDataLib &&  (False != pc_SPSAuthDataLib->isSPSMode())) {
			if (False != pc_SPSAuthDataLib->canSpsTerminate()) {
				// SPS検知状態クリア.
				pc_SPSAuthDataLib->setSPSStatus(PNLE_SPS_STATUS_Idle);
			} else {
				e_AuthModuleStatus &= ~TYPE_AuthModuleStatusReserve;
				return;
			}
		}

		PnlComGetAuthDeviceCommon()->reqAuthPollingTerminate();								//ポーリング終了リクエスト.
		e_AuthModuleStatus &= (TYPE_AuthModuleStatus)( ~TYPE_AuthModuleStatusStart );
		ExpPanelLog( PNLD_ExpLogKind_AuthDevicePoling, "[LocalUI][AuthPolling][PriTask:%d] PnlComReqAuthPollingTerminate reqAuthPollingTerminate e_AuthModuleStatus[%d]", priTask, e_AuthModuleStatus, 0, 0, 0, 0 );	// comment 2020/07/01 Sky菅野 ログ強化改善.
	}
	e_AuthModuleStatus &= (TYPE_AuthModuleStatus)( ~TYPE_AuthModuleStatusReserve );
	ExpPanelLog( PNLD_ExpLogKind_AuthDevicePoling, "[LocalUI][AuthPolling][PriTask:%d] PnlComReqAuthPollingTerminate end e_AuthModuleStatus[%d]", priTask, e_AuthModuleStatus, 0, 0, 0, 0 );	// comment 2020/07/01 Sky菅野 ログ強化改善.
}

//------------------------------------------------------------------------------.
/**
* @brief 認証ポーリングリスタートリクエスト.
*/
//------------------------------------------------------------------------------.
void PnlComReqAuthModuleRestart()
{
	// comment 2020/07/01 Sky菅野 ログ強化改善.
	PM_TaskID priTask;
	PMGC_PanelManager::getPriority( &priTask );
	ExpPanelLog( PNLD_ExpLogKind_AuthDevicePoling, "[LocalUI][AuthPolling][PriTask:%d] PnlComReqAuthModuleRestart e_AuthModuleStatus[%d]", priTask, e_AuthModuleStatus, 0, 0, 0, 0 );
	
	// パワーセーブ中はコールしない.
	TYPE_PowerSaveStatus e_PowerSaveStatus = ppc_Power->getPowerSaveStatus();
	if( True == PnlComIsPowerSaveMode( e_PowerSaveStatus ) ) {
		ExpPanelLog( PNLD_ExpLogKind_AuthDevicePoling, "[LocalUI][AuthPolling][PriTask:%d] PnlComReqAuthModuleRestart return e_AuthModuleStatus[%d]", priTask, e_AuthModuleStatus, 0, 0, 0, 0 );	// comment 2020/07/01 Sky菅野 ログ強化改善.
		return;
	}


	if( TYPE_AuthModuleStatusStart == ( e_AuthModuleStatus & TYPE_AuthModuleStatusStart ) ) {		// 認証サービス実行しているとき.
		PnlComGetAuthDeviceCommon()->reqAuthModuleRestart();									// ポーリングリスタートリクエスト.
		onlyPanel.e_AuthDeviceTouch = TYPE_AuthDeviceTouch_None;								// 認証装置の状態を初期化とする.
		ExpPanelLog( PNLD_ExpLogKind_AuthDevicePoling, "[LocalUI][AuthPolling][PriTask:%d] PnlComReqAuthModuleRestart reqAuthModuleRestart e_AuthModuleStatus[%d]", priTask, e_AuthModuleStatus, 0, 0, 0, 0 );	// comment 2020/07/01 Sky菅野 ログ強化改善.
	}
}

//------------------------------------------------------------------------------.
/**
* @brief 認証ポーリング開始リクエスト(予約実行).
*/
//------------------------------------------------------------------------------.
void PnlComReqAuthPollingInitializeStart()
{
	// comment 2020/07/01 Sky菅野 ログ強化改善.
	PM_TaskID priTask;
	PMGC_PanelManager::getPriority( &priTask );
	ExpPanelLog( PNLD_ExpLogKind_AuthDevicePoling, "[LocalUI][AuthPolling][PriTask:%d] PnlComReqAuthPollingInitializeStart e_AuthModuleStatus[%d]", priTask, e_AuthModuleStatus, 0, 0, 0, 0 );
	
	e_AuthModuleStatus |= TYPE_AuthModuleStatusInitialize;										// 認証FUM初期化終了.
	if( TYPE_AuthModuleStatusReserve == ( e_AuthModuleStatus & TYPE_AuthModuleStatusReserve ) ) {	// 認証サービス実行が予約されているとき.
		e_AuthModuleStatus &= (TYPE_AuthModuleStatus)( ~TYPE_AuthModuleStatusReserve );
		PnlComReqAuthPollingStart();															// 認証サービス実行.
		ExpPanelLog( PNLD_ExpLogKind_AuthDevicePoling, "[LocalUI][AuthPolling][PriTask:%d] PnlComReqAuthPollingInitializeStart PnlComReqAuthPollingStart e_AuthModuleStatus[%d]", priTask, e_AuthModuleStatus, 0, 0, 0, 0 );	// comment 2020/07/01 Sky菅野 ログ強化改善.
	}
}
//------------------------------------------------------------------------------.
/**
* @brief 認証ポーリングステータス取得(True：ポーリング中、False：ポーリングしていない).
*/
//------------------------------------------------------------------------------.
Bool PnlComGetAuthPollingStatus()
{
	Bool bl_Ret = False;

	if( TYPE_AuthModuleStatusStart == ( e_AuthModuleStatus & TYPE_AuthModuleStatusStart ) ) {	// 認証サービス実行しているとき.
		bl_Ret = True;	// 実行中.
	}

	return bl_Ret;
}

//------------------------------------------------------------------------------.
//	comment 2016/10/07 HCL-Omkar [IT5_4.0][制御構成変更_No.45][WP-683] New function definition for chacking Authentication device loading completion.
/**
* @brief Authentication device loading status acquisition ( True: Loading completed, False: loading not completed ).
*/
//------------------------------------------------------------------------------.
Bool PnlComGetAuthLoadingStatus()
{
	Bool bl_Ret = False;
	if ( TYPE_AuthModuleStatusInitialize == ( e_AuthModuleStatus & TYPE_AuthModuleStatusInitialize ) ) {  //	To check if auth device loading is completed.
		bl_Ret = True;					//	Loading completed.
	}
	return bl_Ret;
}

