//------------------------------------------------------------------------------.
/**
* @brief 複数指登録が可能かどうか.
*/
//------------------------------------------------------------------------------.
Bool PnlComCheckMultipleFingerEnable()
{
	Bool b_OK_Tpye3 = PLBC_FuncVersionCheck::isOK_Type3();
	TYPE_AUTH_DEVICE_TYPE e_DeviceType = PnlComGetAuthDeviceSetting()->getAuthDeviceType();

	// 認証デバイスが生体　かつ　生体機器かAU-102　かつ　Amur、Donau機能拡張3以降の時、複数指登録可能.
	if( TYPE_AUTH_DEVICE_BIO2 == e_DeviceType && True == b_OK_Tpye3 ) {
		return True;
	} else {
		return False;
	}
}
//------------------------------------------------------------------------------.
/**
* @brief ログインする認証デバイス種別を取得.
*/
//------------------------------------------------------------------------------.
TYPE_LoginDeviceType PnlComGetLoginDeviceType( Bool b_AuthDeviceType )
{
	TYPE_LoginDeviceType e_LoginDeviceType = TYPE_LoginDeviceType_None;

	if( True == b_AuthDeviceType ) {																				// 認証装置で認証しようとしている時.
		TYPE_AUTH_DEVICE_TYPE e_DeviceType = PnlComGetAuthDeviceSetting()->getAuthDeviceType();
		if( ( TYPE_AUTH_DEVICE_BIO == e_DeviceType ) || ( TYPE_AUTH_DEVICE_BIO2 == e_DeviceType ) ) {				// 認証装置が生体の時.
			e_LoginDeviceType = TYPE_LoginDeviceType_BIO;
		} else if( ( TYPE_AUTH_DEVICE_ICC == e_DeviceType ) || ( TYPE_AUTH_DEVICE_LOADABLE_ICC == e_DeviceType ) ) {	// 認証装置がカードの時.
			e_LoginDeviceType = TYPE_LoginDeviceType_ICC;
// comment 2018/11/08 Sky嵯峨山 [特ROM][SPS].
		} else if ( TYPE_AUTH_DEVICE_TYPE_SPS == e_DeviceType ) {
			e_LoginDeviceType = TYPE_LoginDeviceType_None;
		}
	}
	return e_LoginDeviceType;
}
