//==========================================================================================//
// 概要   : ジョブスペックのコピー.
// 戻り値 : TYPC_JobSpec* コピー先のJobSpec(NULLの場合はJobSpecが取得未).
// 備考   : **/**/** 夏目(FT).
//==========================================================================================//
TYPC_JobSpec* PnlComCopyJobSpec( TYPC_JobSpec* pc_OriginJobSpec, TYPC_JobSpec* pc_CopyJobSpec )
{
	TYPC_JobSpec* pc_ResultJobSpec = NULL;
	if( NULL == pc_OriginJobSpec || NULL == pc_CopyJobSpec ) {
		pc_ResultJobSpec = NULL;
	} else {
		pc_ResultJobSpec = pc_CopyJobSpec;
		memcpy( pc_CopyJobSpec->pc_Common,	 		pc_OriginJobSpec->pc_Common,	 	sizeof( TYPC_Common ) );
		memcpy( pc_CopyJobSpec->pc_Scan,			pc_OriginJobSpec->pc_Scan,			sizeof( TYPC_Scan ) );
		memcpy( pc_CopyJobSpec->pc_Print,	 		pc_OriginJobSpec->pc_Print,	 		sizeof( TYPC_Print ) );
		memcpy( pc_CopyJobSpec->pc_Send,			pc_OriginJobSpec->pc_Send,			sizeof( TYPC_Send ) );
		memcpy( pc_CopyJobSpec->pc_Fax, 			pc_OriginJobSpec->pc_Fax, 			sizeof( TYPC_Fax ) );
		memcpy( pc_CopyJobSpec->pc_Interpreter, 	pc_OriginJobSpec->pc_Interpreter,	sizeof( TYPC_Interpreter ) );
		memcpy( pc_CopyJobSpec->pc_IPP, 			pc_OriginJobSpec->pc_IPP, 			sizeof( TYPC_IPP ) );
	}
	return pc_ResultJobSpec;
}

//概要		：セキュリティ文書ボックスが表示可能かどうか判定.
Bool isSecurePrintBoxEnable() {
	const TYPE_KeyMode e_KeyMode = PnlComGetMachineSetting()->getKeyMode();														// キーモード.
	const TYPE_AppAtAdminMachineVendor e_AppAtAdminMachineVendor = PnlComGetSystemSetting()->getPrintAtAdminMachineVendor();	// ベンダー接続時のプリント許可/不許可.
	if( ( ( ( TYPE_KeyModeAdminMachineKM == e_KeyMode ) || ( TYPE_KeyModeAdminMachine == e_KeyMode ) )									// 管理装置装着の場合.
	      && ( TYPE_AppAtAdminMachineVendorDisable == e_AppAtAdminMachineVendor ) )													// ベンダー接続時のプリント禁止の場合.
	    || ( TYPE_KeyModePageAcses == e_KeyMode )																					// ページアクセス装着の場合.
	    || ( True == isScanToAuthrizedFolder() ) ) {	// AuthrizedFolder設定が有効の場合.
		return False;	// 表示禁止.
	}
	APIC_HddInfo* pc_HddInfo = APIC_HddInfo::newInstance();
	if( NULL == pc_HddInfo ) {
		LOGF_debug_PutEventLog( LOGF_DEBUG_EVENT_KIND_ALL, 0, LOGD_DEBUG_LEVEL_UNKNOWN, "Assert Failed!" );
		return False;			// 静的解析 2012/09/03 第一OPS 酒井(健).
	}
	if( False == pc_HddInfo->getHddExist() ) {	// HDD装着状態の判定.
		return False;		// 使用不可能.
	}
	return True;	// 表示可能.
}
//概要		：セキュリティ文書ボックスが使用可能かどうか判定.
Bool isSecurePrintBoxReady()
{
	APIC_HddInfo* pc_HddInfo = APIC_HddInfo::newInstance();
	if( NULL == pc_HddInfo ) {
		LOGF_debug_PutEventLog( LOGF_DEBUG_EVENT_KIND_ALL, 0, LOGD_DEBUG_LEVEL_UNKNOWN, "Assert Failed!" );
		return False;				// 静的解析 2012/09/03 第一OPS 酒井(健).
	}
	if( False == APIC_BoxRegistry::GetAccessStatus() ) {	// リストまで初期化未完了.
		return False;		// 使用不可能.
	}
	if( TYPE_HddStatusFormated != pc_HddInfo->getHddStatus() ) {// ﾌｫｰﾏｯﾄ済でない場合
		return False;	// 使用不可能.
	}
	if( EC_IntMode_Off == onlyPanel.ec_IntMode 													// 割り込み中でないとき.
	    && TYPE_FuncLimit_Disable != PnlComCheckOperationAccountStatus( PNLE_ACCOUNT_STATUS_TYPE_BoxOperation ) ) {
		if( TYPE_IGC_STATUS_NOT_Ready == APIC_SystemStatus::newInstance()->getIgcStatus() ) {	// IGC起動中.
			return False;	// 使用不可能.
		}
		if( True == onlyPanel.isMyAddressLoading() ) {	// Myアドレス取得中.
			return False;	// 使用不可能.
		}
		return True;		// 使用可能.
	} else {
		return False;		// 使用不可能.
	}
}

// 表示用ボックスリストに該当ユーザーのボックスがあるかどうか判定.
Bool isExistDispBoxList( APIC_User* pc_user, APIC_Track* pc_track ) {
	if( NULL == pc_user ) {
		LOGF_debug_PutEventLog( LOGF_DEBUG_EVENT_KIND_ALL, 0, LOGD_DEBUG_LEVEL_UNKNOWN, "Assert Failed!" );
		return False;
	}
	setBoxListType( BOXE_BOXListType_Personal );			// 表示ボックスタイプを個人ボックスに変更.
	createBoxDispTable( pc_user, pc_track );				// 表示用テーブルを作成.
	if( 0 == s_BoxDispTable.ss_BoxNumberOfPutin ) {		// 表示用ボックスリストが0の場合.
		return False;
	}
	return True;
}

//概要　　：外部サーバー+ICカード認証モード判定.
//戻り値  ：True-外部サーバー+ICカード認証モード False-外部サーバー+ICカード認証モードではない.
//引数	  ：なし.
Bool PnlComIsExternalServerExtraMode()
{
	if( ( TYPE_UserAuthenticationServer   == PnlComGetUserAuthentication()->getUserAuthentication(PNLC_NetworkLan::getInstance()->getLine()) )		// 外部サーバー認証.
	    && ( ( TYPE_AUTH_DEVICE_ICC 		  == PnlComGetAuthDeviceSetting()->getAuthDeviceType() ) 			// 認証装置2(カード1).
	         || ( TYPE_AUTH_DEVICE_LOADABLE_ICC == PnlComGetAuthDeviceSetting()->getAuthDeviceType() ) ) ) {		// 認証装置2(カード2).
		return True;
	} else {
		return False;
	}
}
//概要		：認証&プリントボックスが表示可能かどうか判定.
Bool isTouchAndGoBoxEnable() {
	const TYPE_KeyMode e_KeyMode = PnlComGetMachineSetting()->getKeyMode();	// キーモード.
	if( ( TYPE_UserAuthenticationOff == PnlComGetUserAuthentication()->getUserAuthentication(PNLC_NetworkLan::getInstance()->getLine()) )										// ユーザー認証OFFの場合.
	    || ( TYPE_KeyModeVendor == e_KeyMode ) || ( TYPE_KeyModeVendorKM == e_KeyMode ) || ( TYPE_KeyModeAdminMachineKM == e_KeyMode )		// ベンダー・管理装置装着の場合.
// comment 2017/04/13 SCD2-Sky工藤 [特ROM][FQ-OPSD-1700092-OFP066][AR1019805] 特定のバックアップファイルをPSDAでMFPに一括コピーすると、認証＆プリントボックスへのショートカットが機能しなくなる
//	    || ( True == isScanToAuthrizedFolder() ) ) {	// AuthrizedFolder設定が有効の場合.
	) {
		return False;	// 表示不可.
	}
	return True;		// 表示可能.
}
//概要		：認証&プリントボックスが使用可能かどうか判定.
Bool isTouchAndGoBoxReady()
{
	APIC_HddInfo* pc_HddInfo = APIC_HddInfo::newInstance();
	if( NULL == pc_HddInfo ) {
		LOGF_debug_PutEventLog( LOGF_DEBUG_EVENT_KIND_ALL, 0, LOGD_DEBUG_LEVEL_UNKNOWN, "Assert Failed!" );
		return False;		// 静的解析 2012/09/03 第一OPS 酒井(健).
	}
	if( False == pc_HddInfo->getHddExist() ) {	// HDD装着状態の判定.
		return False;		// 使用不可能.
	}
	if( False == APIC_BoxRegistry::GetAccessStatus() ) {	// リストまで初期化未完了.
		return False;		// 使用不可能.
	}
	// Myスプール動作中に認証&プリントボックスへ入ってしまうと、動作がキャンセルされてしまうため.
	// Myスプール動作中は、認証&プリントキーは使用不可.
	if( True == isMySpoolRegistration() && 0 <= pdpc_WebDAVServerControl.getSessionID() ) {
		return False;
	}
	if( EC_IntMode_Off == onlyPanel.ec_IntMode 													// 割り込み中でないとき.
	    && TYPE_FuncLimit_Disable != PnlComCheckOperationAccountStatus( PNLE_ACCOUNT_STATUS_TYPE_BoxOperation ) ) {
		if( TYPE_IGC_STATUS_NOT_Ready == APIC_SystemStatus::newInstance()->getIgcStatus() ) {	// IGC起動中.
			return False;	// 使用不可能.
		}
		if( True == onlyPanel.isMyAddressLoading() ) {	// Myアドレス取得中.
			return False;	// 使用不可能.
		}
		return True;		// 使用可能.
	} else {
		return False;		// 使用不可能.
	}
}
Bool isBroadcastOver( TYPC_ComSend* pc_ComSend ) {					// 同報件数チェック.True:オーバー.
	if( NULL == pc_ComSend ) {
		LOGF_debug_PutEventLog( LOGF_DEBUG_EVENT_KIND_ALL, 0, LOGD_DEBUG_LEVEL_UNKNOWN, "Assert Failed!" );
		return False;
	}
	if( True == onlyPanel.checkBroadcastOver( 0, pc_ComSend ) ) {		// 複数宛先禁止時に既に複数宛先がジョブに設定されていた場合.
		return True;
	}
	return False;
}
// 概要   : パンチが暫定救済中かを判定する.
// 戻り値 : Bool（True : 暫定救済中、False : 暫定救済ではない）.
// 備考   : No329852対応:パンチキット無し且つZU切り離し時もパンチキット切り離し時と同様にパンチ機能OFFとする.
Bool PnlComIsRescueStatusSetPunch()
{
	Bool _bl_Result = False;
// comment 2016/11/16 [HCL_Baskaran] [IT5_3.3][AR-1007620] As punch” Key is not related to “Punch Unit", ZU unit check is removed.
//	if( TYPE_TemporaryRescueStatusReset != ppc_SystemStatus->getTemporaryRescueUserStatus( TYPE_TemporaryRescueUnitPK )	// PK暫定救済.
//	    || ( TYPE_PunchKitType_None == PnlComGetMachineSetting()->getPunchKitType() && TYPE_TemporaryRescueStatusReset != ppc_SystemStatus->getTemporaryRescueUserStatus( TYPE_TemporaryRescueUnitPZ ) ) ) {	// PK非装着且つPZ暫定救済.
	if( TYPE_TemporaryRescueStatusReset != ppc_SystemStatus->getTemporaryRescueUserStatus( TYPE_TemporaryRescueUnitPK )	// PK暫定救済.
	    || ( TYPE_PunchKitType_None == PnlComGetMachineSetting()->getPunchKitType() ) ) {	// PK非装着且つPZ暫定救済.
		_bl_Result = True;
	}
	return _bl_Result;
}

// 文字列の文頭または文末がアンダースコア(_)か?.
Bool isUnderScoreHead_or_Tail( char* pc_string, uchar uc_size ) {
	if( 0 == uc_size || NULL == pc_string ) {		// 文字数が0の場合は評価しない.
		return False;
	}
	if( '_' == *pc_string
	    || '_' == * ( pc_string + uc_size - 1 ) ) {
		return True;
	} else {
		return False;
	}
}


