//================================================================================================
TYPC_BroadcastAddressCounter::TYPC_BroadcastAddressCounter()
{
	memset( m_us_AddressCount, 0x00, sizeof( m_us_AddressCount ) );
}

//================================================================================================
//クラス  ：TYPC_BroadcastAddressCounter ：同報宛先カウンター管理クラス.
//概要    ：カウンターのクリア.
//================================================================================================
void TYPC_BroadcastAddressCounter::clearAddressCount()
{
	memset( m_us_AddressCount, 0x00, sizeof( m_us_AddressCount ) );
}

//================================================================================================
//クラス  ：TYPC_BroadcastAddressCounter ：同報宛先カウンター管理クラス.
//概要    ：カウンターのカウントアップ.
//================================================================================================
void TYPC_BroadcastAddressCounter::countUpAddressCount( TYPE_SendMode e_SendMode )
{
	ushort us_SendMode = (ushort)( ( ushort )e_SendMode - 1 );

	// 範囲チェック.
	if( 0 <= us_SendMode  && PNLD_SendModeMax > us_SendMode ) {
		m_us_AddressCount[ us_SendMode ]++;		// カウントアップ.
	}
}

//================================================================================================
//クラス  ：TYPC_BroadcastAddressCounter ：同報宛先カウンター管理クラス.
//概要    ：カウンター取得.
//================================================================================================
ushort TYPC_BroadcastAddressCounter::getAddressCount( TYPE_SendMode e_SendMode )
{
	ushort us_SendMode 	= (ushort)( ( ushort )e_SendMode - 1 );
	ushort us_Count 	= 0;

	// 範囲チェック.
	if( 0 <= us_SendMode  && PNLD_SendModeMax > us_SendMode ) {
		us_Count = m_us_AddressCount[ us_SendMode ];
	}
	return us_Count;
}

