PNLC_TokenCodeSetting::PNLC_TokenCodeSetting()
{
	bl_SelectTokenCode = False;		// トークンコードキーの選択状態.
	ss_SelectTokenCodeNum = 0;		// 選択されているトークンコードの番号.
	clearTokenCode(); 				// トークンコードとトークンコード(ハイフン付)クリア.
	memset( sc_ErrorCode, '\0', sizeof( sc_ErrorCode ) );	// エラーコードクリア.
}
//================================================================================================.
//	概要		：インスタンス取得.
//================================================================================================.
PNLC_TokenCodeSetting* PNLC_TokenCodeSetting::getInstance()
{
	static PNLC_TokenCodeSetting cp_TokenCodeSetting;	// トークンコード管理クラス.
	return &cp_TokenCodeSetting;
}
//================================================================================================.
//	概要		：選択されているトークンコードの番号を設定.
//================================================================================================.
void PNLC_TokenCodeSetting::setSelectTokenCodeNum( uchar ss_setNum )
{
	if( 0 <= ss_setNum && PNLD_TokenCodeMaxNum > ss_setNum ) {
		ss_SelectTokenCodeNum = ss_setNum;
	}
}
//================================================================================================.
//	概要		：選択されているトークンコードの番号を取得.
//================================================================================================.
uchar PNLC_TokenCodeSetting::getSelectTokenCodeNum()
{
	return ss_SelectTokenCodeNum;
}
//================================================================================================.
//	概要		：設定されている番号のインデックスにトークンコードを設定.
//================================================================================================.
void PNLC_TokenCodeSetting::setTokenCode( char* sc_set )
{
	// NULLチェック.
	if( NULL != sc_set ) {
		if( '\0' != sc_set[0] ) {
			strncpy( s_LcaTokenCode.sc_TokenCode[ss_SelectTokenCodeNum], sc_set, PNLD_TokenCodeLenMax );
			// トークンコードにハイフンを追加する.
			for( uchar i = 0, j = 0; PNLD_TokenCodeLenMax > i; i++, j++ ) {
				if( ( 0 != j ) && ( 0 == ( i % PNLD_TokenCodeBlockLenMax ) ) ) {
					// コードブロックの間にハイフンを追加.
					sc_TokenCodeAddHyphen[ss_SelectTokenCodeNum][j++] = '-';
				}
				sc_TokenCodeAddHyphen[ss_SelectTokenCodeNum][j] = s_LcaTokenCode.sc_TokenCode[ss_SelectTokenCodeNum][i];
			}
		} else {
			memset( s_LcaTokenCode.sc_TokenCode[ss_SelectTokenCodeNum], '\0', sizeof( s_LcaTokenCode.sc_TokenCode[ss_SelectTokenCodeNum] ) );
			memset( sc_TokenCodeAddHyphen[ss_SelectTokenCodeNum], '\0', sizeof( sc_TokenCodeAddHyphen[ss_SelectTokenCodeNum] ) );
		}
	}
}
//================================================================================================.
//	概要		：設定されている番号のインデックスのトークンコードを取得.
//================================================================================================.
char* PNLC_TokenCodeSetting::getTokenCode()
{
	return s_LcaTokenCode.sc_TokenCode[ss_SelectTokenCodeNum];
}
//================================================================================================.
//	概要		：指定した番号のトークンコード(ハイフン付)を取得.
//================================================================================================.
char* PNLC_TokenCodeSetting::getTokenCodeAddHyphen( uchar ss_getNum )
{
	if( 0 <= ss_getNum && PNLD_TokenCodeMaxNum > ss_getNum ) {
		return sc_TokenCodeAddHyphen[ss_getNum];
	} else {
		return NULL;
	}
}
