void PNLC_TokenCodeSetting::clearTokenCode()
{
	for( uchar i = 0; i < PNLD_TokenCodeMaxNum; i++ ) {
		memset( s_LcaTokenCode.sc_TokenCode[i], '\0', sizeof( s_LcaTokenCode.sc_TokenCode[i] ) );
		memset( sc_TokenCodeAddHyphen[i], '\0', sizeof( sc_TokenCodeAddHyphen[i] ) );
	}
}
