//	概要		：トークンコードが入力されているかチェック.
//================================================================================================.
Bool PNLC_TokenCodeSetting::checkInputTokenCode()
{
	for( uchar i = 0; i < PNLD_TokenCodeMaxNum; i++ ) {
		if( '\0' != s_LcaTokenCode.sc_TokenCode[i][0] ) {
			return( True );
		}
	}
	return( False );
}
