void PnlComGetAddressDispStringSmb( char* sc_string, uint32_t ul_MaxNum, char sc_LoginName ) {

	if( NULL == sc_string ) {
		LOGF_debug_PutEventLog( LOGF_DEBUG_EVENT_KIND_ALL, 0, LOGD_DEBUG_LEVEL_UNKNOWN, "Assert Failed!" );
		return;
	}

	const uchar PNLD_ScansStringSize = uchar( 6 );	// "\\scans"の文字数.

	// 追加するフォルダー名(ユーザー名\scans).
	char sc_AddFolderName[PCGD_MaxUserName*3 + PNLD_ScansStringSize + PCGD_EndCode];
	ACSE_FilePathChangeSTSMB	e_Mode	= ACSE_FilePathChangeSTSMB_Convent;
	char	sc_ConfigAnyString[PNLD_ShortAddrFilePathAnyStr_MaxSize_SMB]	= { 0 };

	APIC_AuthCust*	pc_AuthCust	= APIC_AuthCust::newInstance();
	if( 0 != pc_AuthCust ) {
		pc_AuthCust->getShortAddressFilePathChangeScanToSMB( &e_Mode, &( sc_ConfigAnyString[0] ) );
	}

	switch( e_Mode ) {
	case ACSE_FilePathChangeSTSMB_NoCustom:		// 短縮宛先ファイルパス変更 ScanToSMB機能無効.
		break;
	case ACSE_FilePathChangeSTSMB_UserName:		// 短縮宛先ファイルパス変更 ScanToSMB(ユーザ名置換).
	case ACSE_FilePathChangeSTSMB_RepString:	// 短縮宛先ファイルパス変更 ScanToSMB(置換文字列).
		PnlComGetAddressDispStringSmbConfig( sc_string, ul_MaxNum, &( sc_ConfigAnyString[0] ), e_Mode );
		break;
	case ACSE_FilePathChangeSTSMB_Convent:	// コンフィグファイルの設定未使用(従来動作).
	default:
		if( True == isScanToAuthrizedFolder()
		    && True == APIC_SoftDipSw::newInstance()->getSoftDipSwBitForPanelSpecNo( 17, 7 )
		    && '\0' != sc_string[0]
		    && '\0' == sc_LoginName
		    && NULL != PnlComGetUser() ) {
			// ユーザー名取得.
			PnlComGetUser()->getUserNameUTF8( sc_AddFolderName, TYPE_CharSetUTF8 );

			//ファイルパスに\を結合させる領域がある場合.
			if( ( int32_t )( ul_MaxNum - strlen( sc_string ) ) > 1 ) {
				strncat( sc_string, ( char* )"\\", 1 );
			} else {
				return;
			}
			strncat( sc_AddFolderName, ( char* )"\\scans", PNLD_ScansStringSize );
			// 結合元の文字数＋結合先の文字数＋終端コードが結合元のサイズ以下の場合.
			if( ( strlen( sc_string ) + strlen( sc_AddFolderName ) + 1 ) <= ul_MaxNum ) {
				// ユーザー名を全てファイルパスへ結合.
				strncat( sc_string, sc_AddFolderName, strlen( sc_AddFolderName ) );
			} else {
				// ユーザー名を表示可能なところまでファイルパスへ結合.
				strncat( sc_string, sc_AddFolderName, ( ul_MaxNum - strlen( sc_string ) - 1 ) );
			}
		}
		break;
	}
}

// comment 2015/08/03 HCL_Premkumar 【ZeusS_ZX0】 【RQ-261】 Adding new function for checking dynamic conditions of ScanToURL.
// comment 2021/01/18 Sky中野 [IT6_2.2] 制御No.34_目的別UI対応(ScanToURL/ScanToHome).
Bool isScanToURL( Bool bl_inHome )
{
	APIC_UserAuthentication* pc_UserAuth = PnlComGetUserAuthentication();
	if ( NULL != pc_UserAuth ) {
		if ( False == pc_UserAuth->getEnableURLAddress( ) ) {
			return False;
		}
	}
	if ( True == APIC_SoftDipSw::newInstance()->getSoftDipSwBitForPanelSpecNo( DEFSOFTWARESW216, 5 ) ) {
		return False;
	}
	APIC_Job *pc_job = PnlComGetJobScanFax();
	if( NULL == pc_job ){
		LOGF_debug_PutEventLog( LOGF_DEBUG_EVENT_KIND_ALL, 0, LOGD_DEBUG_LEVEL_UNKNOWN, "Assert Failed!" );
		return( False );
	}
	TYPC_ComSend *pc_ComSend = &( pc_job->getJobSpec()->pc_Send->c_ComSend );
	
	// E-mail送信が有効か.
// comment 2021/01/18 Sky中野 [IT6_2.2] 制御No.34_目的別UI対応(ScanToURL/ScanToHome).
//	if( False == isEnableSetAddress(pc_ComSend, TYPE_SendModeEmail, False, False, False, True, -1, NULL, True)){
//		return( False );
//	}
	Bool bl_EnableEmail = False;
	if( True == bl_inHome ) {
		SetFuncShowHomeMenu(True);
		bl_EnableEmail = isEnableSetAddress( pc_ComSend, TYPE_SendModeEmail, False, False, False, True, -1, NULL, True, False, False );
		SetFuncShowHomeMenu(False);
	} else {
		bl_EnableEmail = isEnableSetAddress( pc_ComSend, TYPE_SendModeEmail, False, False, False, True, -1, NULL, True );
	}
	if( False == bl_EnableEmail ) {
		return( False );
	}
	
	// ユーザ認証中か.
	if( False == PnlComGetUserAccountOn() ){
		return( False );
	}
	// ユーザーが取得できたか.
	if (NULL == PnlComGetUser()) {
		return( False );
	}
	// ユーザーE-mailが取得できたか.
	if( 0 < strlen(PnlComGetUser()->getMailNotification().sc_UserMailAdrs ) ) {
	}else{
		return( False );
	}
	if ( True == PLBC_FuncPKICheck::isPKI() ) {		// PKIカード認証.
		if(   ( True  == pc_job->getJobSpec()->pc_Send->c_MailSend.getSmimeEnableCrypt() )	// メール暗号化ON.
		   && ( False == APIC_User::isLoginUserCertificateEnable() ) ) {									// デジタル署名を内部に保持していない.
			return( False );
		}
	}
	// RightFaxモードであるかどうか.
// comment 2021/01/18 Sky中野 [IT6_2.2] 制御No.34_目的別UI対応(ScanToURL/ScanToHome).
//	if ( True == ExtSet.isRightFaxMode() ) {
	if ( ( True == ExtSet.isRightFaxMode() ) && ( False == bl_inHome ) ) {
		return( False );
	}
	return( True );	
}

// comment 2015/08/03 HCL_Premkumar 【ZeusS_ZX0】 【RQ-261】 Adding new function for setting data to ScanToURL.
Bool PnlComSetScanToURL(TYPC_ShorteningAddress* pc_ScanToURL)
{
	TYPS_MailAddress	s_MailAddress;
	// ユーザーE-mailが取得できたか.
	if( (NULL != PnlComGetUser())
		&& (NULL != pc_ScanToURL)
		&& (0 < strlen(PnlComGetUser()->getMailNotification().sc_UserMailAdrs ) ) ) {
		strncpy( s_MailAddress.sc_MailToAddress, PnlComGetUser()->getMailNotification().sc_UserMailAdrs ,TYPD_MaxMailAddress);
		// メール宛先 設定.
		pc_ScanToURL->setMailAddress(s_MailAddress);
	}else{
		return( False );
	}
	// 短縮宛先の名称 設定.
// Comment 2023/05/17 Sky村田 OP_BTS-42758 軽微問題リストNo.27.
	char sc_AddressName[ TYPD_MaxStrAddressNameUTF8 + 1 ];
	memset( sc_AddressName, '\0', sizeof( sc_AddressName ) );
	PnlComConvertTextIDToString( s_pITMURL_W088H196A, sc_AddressName, sizeof( sc_AddressName ) );
//	pc_ScanToURL->setAddressNameUTF8((char*)getTextPartsPointer(s_pITMURL_W088H196A), getCharSetForCAPI());
	pc_ScanToURL->setAddressNameUTF8( sc_AddressName, TYPE_CharSetUTF8 );
	// 表示用 番号 設定.
	pc_ScanToURL->setDisplayNo( PCGD_ScanToURLIndex );
	// 送信モード(宛先種別) 設定.
	pc_ScanToURL->setSendMode(TYPE_SendModeEmail);
	return( True );	
}
// セキュリティー文書ボックスに遷移可能な条件判断(DA-142用).
Bool isDirectSecurityBox()
{
	TYPE_FuncLimit e_FuncLimit = TYPE_FuncLimit_Disable;
	Bool bl_enable = True;
	if( EP_BoxKeyToSecurityBox_BoxTop == onlyPanel.getBoxKeyToSecurityBox() ) {
		return False;
	} else {
		e_FuncLimit = PnlComCheckOperationAccountStatus( PNLE_ACCOUNT_STATUS_TYPE_Print ) ;	// プリント可能ユーザか.
		if( TYPE_FuncLimit_Disable == e_FuncLimit ) {
			bl_enable = False;
		}
		switch( APIC_KeyDevice::getKeyMode() ) {
			case TYPE_KeyModeAdminMachineKM :				// 統合管理装置装着または.
			case TYPE_KeyModeVendorKM :						// 統合ベンダー装着ならば.
				if( TYPE_AppAtAdminMachineVendorDisable == PnlComGetSystemSetting()->getPrintAtAdminMachineVendor() ) {	// アプリケーションの使用設定がプリント禁止.
					bl_enable = False ;				 		// セキュリティ文書へ飛ばさない.
				}
				break ;
			default : break ;
		}
// Comment 2017/09/04 [HCL-TANU] [IT5 4.2][RQ-755] [WP716]Multiple Network support.
		//  if( TYPE_SecurePrintCertification2 == PnlComGetSystemSetting()->getSecurePrintCertification() ) {	//セキュリティー文書アクセス方式が2の時.
            TYPE_NetworkSpecific e_NetworkSpecific = PNLC_NetworkLan::getInstance()->getLine();
			if( TYPE_SecurePrintCertification2 == PnlComGetSystemSetting()->getSecurePrintCertification( e_NetworkSpecific ) ) {	//セキュリティー文書アクセス方式が2の時.
			bl_enable = False;
		}
		if( False == bl_enable																	// セキュリティ印刷ボックスに遷移可能.
		    && EP_BoxKeyToSecurityBox_SecurityBox == onlyPanel.getBoxKeyToSecurityBox() ) {	// ボックスキーでの画面遷移の場合.
			onlyPanel.setBoxKeyToSecurityBox( EP_BoxKeyToSecurityBox_BoxTop );		// フラグを落とす.
		}
		return bl_enable;
	}
}
//備考   回線パラメータ設定1共通 : リダイアル回数,リダイアル間隔使用可否判定関数.
Bool chkRedialEnable()
{
	TYPE_KeyMode e_KeyMode = PnlComGetMachineSetting()->getKeyMode();			// 管理機能モード
	APIC_SoftDipSw* pc_SoftDipSw = APIC_SoftDipSw::newInstance();
	Bool bl_RedialEnable = True;		// リダイアル設定使用可否フラグ.
	switch( e_KeyMode ) {
		//キーモード：従来ベンダー時は使用不可.
		case TYPE_KeyModeVendor:
			bl_RedialEnable = False;
			break;
		case TYPE_KeyModeVendorKM:		// 統合ベンダー装着時.
			if( ( False == pc_SoftDipSw->getSoftDipSwBitForPanelSpecNo( Vendor2MessageSWNUM, 4 ) )				// DipSW30 bit4がOffのとき.
			    || ( TYPE_AppAtAdminMachineVendorEnableWithoutCardOrCoin != PnlComGetSystemSetting()->getSendAtAdminMachineVendor() ) ) {	// データ送信「課金管理しない」以外.
				bl_RedialEnable = False;
			}
		default: break;
	}
	return bl_RedialEnable;

}

// APS、もしくは選択したトレイが手差し、ユニバーサルトレイ以外は選択トレイキーをグレイアウト.
// 引数		: 	TYPE_FeedTray e_FeedTray		トレイ情報.
//			  	APIC_Job* pc_Job 				ジョブスペック.
// 戻り値	:	Bool (True:選択トレイキーをアクティブ False:選択トレイキーをグレイアウト).
Bool PnlComGetFeedTrayType( TYPE_FeedTray e_FeedTray, APIC_Job* pc_Job ) {
	if( NULL == pc_Job ) {
		return False;
	}
	if( True == pc_Job->getJobSpec()->pc_Print->c_PaperTray.getApsOn() ) { // APS選択時.
		return False;
	}
	TYPE_TrayType e_TrayType = PnlComGetFeedTray()->getTrayType( e_FeedTray );		// トレイタイプ取得.
// Comment 2019/09/11 [EagleZPlus_BKZPlus ] [OP_BTS-7296] [HCLT-Santhiya]  Enable the Change Tray Setting Key.
	//	if( TYPE_TrayTypeUniversal == e_TrayType || TYPE_TrayTypeMultiMan == e_TrayType  ) {	// 手差しかユニバーサルトレイの時.
	if( TYPE_TrayTypeUniversal == e_TrayType 
		|| TYPE_TrayTypeMultiMan == e_TrayType  
		|| TYPE_TrayTypeMPC  == e_TrayType) {	// 手差しかユニバーサルトレイの時.
		return True;
	}
	return False;
}
// 現在選択中のトレイが指定なしかを判定する.
// 戻り値 指定あり:True,指定なし:False.
// リストカウンタ>用紙サイズ/種類カウンタの用紙種類の指定あり/なしを判断する.
// 引数		: TYPE_FeedTray e_FeedTray		トレイ情報.
// 戻り値 指定あり:True,指定なし:False.
Bool PnlComIsSpecificationListCounterPaperType( TYPE_FeedTray e_FeedTray ) {

	uchar uc_Index = 0;
	TYPC_PaperType c_PaperType;
//Comment 2018/12/21 【HCLT-Chinna】【IT6_DenebMLK】【AR 1069006】Correcting the index for Tray5.
#ifdef DEF_DenebMLKCus
	TYPE_FeedTray	e_FeedTrayTable[]= { TYPE_FeedTray1,TYPE_FeedTray2,TYPE_FeedTray3,TYPE_FeedTray4,TYPE_FeedTrayManual,TYPE_FeedTrayUnselect,TYPE_FeedTray5 };
#else
	TYPE_FeedTray	e_FeedTrayTable[]= { TYPE_FeedTray1,TYPE_FeedTray2,TYPE_FeedTray3,TYPE_FeedTray4,TYPE_FeedTrayManual,TYPE_FeedTray5 };
#endif
	for( uc_Index = 0; uc_Index < sizeof( e_FeedTrayTable )/sizeof( TYPE_FeedTray ) ; uc_Index++ ) {
		if (e_FeedTrayTable[uc_Index] == TYPE_FeedTrayUnselect) {
			continue;
		}
		if( e_FeedTray == e_FeedTrayTable[uc_Index]) {
			c_PaperType.setPaperType( PnlComGetSystemSetting()->getPaperSizeCnt_PaperType( ( TYPE_PaperSizeCnt )uc_Index ) );	// ????????????.
			break;
		}
	}

	if( TYPE_PaperTypeDontcare == c_PaperType.getPaperType() ) {	// ?????????.
		return False;
	}

	return True;
}
// 概要：パブリックまたは未認証状態でジョブ操作禁止か？.
// 引数：無し
// 戻り値： True(禁止)、False(許可).
// 備考：【DA-387】に関連して新規作成..
Bool PnlComIsDisableJobOpeWithPublic()
{
	// DipSWNo.71 bit7が有効.
	if( True == APIC_SoftDipSw::newInstance()->getSoftDipSwBitForPanelSpecNo( SALESCOUNTERSWNUM,7 ) ) {
		// ユーザー未認証状態.
		if( NULL == PnlComGetUser() ) {
			return True;
		}
		// 「部門管理ON」かつ「部門未認証」
// comment 2021/04/30 Sky東島 [IT6_2.2][OP_BTS-32561].
//		if( TYPE_TrackModeOff != PnlComGetTrackManager()->getTrackMode(PNLC_NetworkLan::getInstance()->getLine())
//		    && NULL == PnlComGetTrack() ) {
		if( True == PnlComGetNeedToTrackLogin() ){
			return True;
		}
		// Publicユーザ認証中..
		if( True == PnlComGetUserAccountPublic() ) {
			return True;
		}
	}
	return False;
}
//=======================================================================================================================.
// 概要		：指定機能が使用可能かどうか.
//［引数]	：機能種別(PNLE_EnableFunctionType).
//［戻値]	：True：使用可 False：使用不可.
// 備考：プログラム機能禁止設定が「禁止」であっても、キーカウンター挿入時に関しては「使用可」と判定する.
// 備考：原稿サイズ自動設定禁止が「する」であっても、キーカウンター挿入時に関しては「使用可」と判定する.
//=======================================================================================================================.
Bool PnlComIsEnableFunction( PNLE_EnableFunctionType e_FunctionType )
{
	Bool bl_result = False;	// 使用不可.

	if( ( TYPE_KeyModeKeyCounter == APIC_KeyDevice::getKeyMode() )
	    && ( True == APIC_KeyDevice::isKeyCounterCopyEnable() ) ) {		// キーカウンター挿入状態を確認する.
		// 「ベンダー2+キーカウンター」、「キーカウンターのみ」設定時のキーカウンター挿入状態時は使用可.
		// キーカウンター未挿入状態時はプログラム機能禁止設定に従う.
		bl_result = True;	// 使用可.
	} else if( True == PnlComGetSystemStatus()->getServiceModeOn() ) {		// サービスモード中.
		bl_result = True;	// 使用可.
	} else {
		switch( e_FunctionType )
		{
			case PNLE_EnableFunctionType_Program:	// プログラム機能に関する判定.
//comment 2017/08/24 [HCL-Rajesh] [IT5 4.2] [RQ-686][WP 122] Multiple Network Support.
//				if( TYPE_OperationProhibit_Permit == PnlComGetOperationSetting()->getEnableProgram() ) {	// プログラム機能禁止設定が「許可」の場合.		
				if( TYPE_OperationProhibit_Permit == PnlComGetOperationSetting()->getEnableProgram( PNLC_NetworkLan::getInstance()->getLine() ) ) {	// プログラム機能禁止設定が「許可」の場合.
					bl_result = True;	// 使用可.
				}
				break;
			case PNLE_EnableFunctionType_OriginalSizeAuto:	// 原稿サイズ自動設定機能に関する判定.
//comment 2017/08/24 [HCL-Rajesh] [IT5 4.2] [RQ-686][WP 122] Multiple Network Support.
//				if( TYPE_OperationProhibit_Permit == PnlComGetOperationSetting()->getEnableOriginalSizeAutoDetect() ) {	// 原稿サイズ自動設定禁止が「しない」の場合.
				if( TYPE_OperationProhibit_Permit == PnlComGetOperationSetting()->getEnableOriginalSizeAutoDetect(PNLC_NetworkLan::getInstance()->getLine() ) ) {	// 原稿サイズ自動設定禁止が「しない」の場合.
					bl_result = True;	// 使用可.
				}
//comment 2018/01/03 [HCL-Gadiyasai] [IT5 4.2] [AR1033019] to set paper size to auto by default when no network is selected.
// comment 2019/05/28 [HCL-Naveena][EagleBK] NetworkType Default selection activity.
//				if ( TYPE_NetworkSpecific_NONE == PNLC_NetworkLan::getInstance()->getLine() ) {
				if ( TYPE_NetworkSpecific_NONE == PNLC_NetworkLan::getInstance()->getLineForPanel() ) {
					bl_result = True;
				}
				break;
			default :	// 例外.
				LOGF_debug_PutEventLog( LOGF_DEBUG_EVENT_KIND_ALL, 0, LOGD_DEBUG_LEVEL_UNKNOWN, "Assert Failed!" );
				break;
		}
	}
	return bl_result;
}

