void PNLC_RemoteFWUpdateClientLogForwardSetting::clear()
{
	m_blLogForward = TYPD_DEFAULT_ClientLogForwardSetting;
	m_eLogForwardProtocol = TYPE_DEFAULT_ClientLogForwardProtocol;
	memset( m_scSMBHostName, '\0', TYPD_MAX_ClientLogForwardForSMBHost );
	memset( m_scSMBFilePath, '\0', TYPD_MAX_ClientLogForwardForSMBFolder );
	memset( m_scSMBUserName, '\0', TYPD_MAX_ClientLogForwardForSMBUserName );
	memset( m_scSMBUserPassword, '\0', TYPD_MAX_ClientLogForwardForSMBPassword );
	memset( m_scWebDAVURL, '\0', TYPD_MAX_ClientLogForwardForWebDAVURL );
	memset( m_scWebDAVUserName, '\0', TYPD_MAX_ClientLogForwardForWebDAVUserName );
	memset( m_scWebDAVUserPassword, '\0', TYPD_MAX_ClientLogForwardForWebDAVPassword );
	m_blProxy = TYPD_DEFAULT_ClientLogForwardForWebDAVProxyOffOn;
}

//==================================================================================================
// 概要     : NV-RAMからメンバ変数へ設定値をロード.
// 引数     : なし.
// 戻り値   : なし.
// 備考     : なし.
//==================================================================================================
void PNLC_RemoteFWUpdateClientLogForwardSetting::load()
{
	clear();
	m_blLogForward = APIC_FWUpdateSetting::newInstance()->getClientLogForwardSetting();
	m_eLogForwardProtocol = APIC_FWUpdateSetting::newInstance()->getClientLogForwardProtocol();
	APIC_FWUpdateSetting::newInstance()->getClientLogForwardForSMBHost( m_scSMBHostName );
	APIC_FWUpdateSetting::newInstance()->getClientLogForwardForSMBFolder( m_scSMBFilePath );
	APIC_FWUpdateSetting::newInstance()->getClientLogForwardForSMBUserName( m_scSMBUserName );
	APIC_FWUpdateSetting::newInstance()->getClientLogForwardForSMBPassword( m_scSMBUserPassword );
	APIC_FWUpdateSetting::newInstance()->getClientLogForwardForWebDAVURL( m_scWebDAVURL );
	APIC_FWUpdateSetting::newInstance()->getClientLogForwardForWebDAVUserName( m_scWebDAVUserName );
	APIC_FWUpdateSetting::newInstance()->getClientLogForwardForWebDAVPassword( m_scWebDAVUserPassword );
	m_blProxy = APIC_FWUpdateSetting::newInstance()->getClientLogForwardForWebDAVProxyOffOn();
}

//==================================================================================================
// 概要     : メンバ変数からNV-RAMへ設定値を書き込み.
// 引数     : bl_ErrorCheck : True(設定値のチェックを行う)、False(設定値のチェックを行わない).
// 戻り値   : True  : 設定OK.
//            False : エラー(入力不足項目有).
// 備考     : なし.
//==================================================================================================
Bool PNLC_RemoteFWUpdateClientLogForwardSetting::commit( Bool bl_ErrorCheck )
{
	// 必須入力項目のチェック.
	if( True == bl_ErrorCheck && False == checkSettings() ) {
		// 入力項目チェックを行う指定がされてかつ、入力項目チェックNG.
		return False;
	}
	APIC_FWUpdateSetting::newInstance()->setClientLogForwardSetting( m_blLogForward );
	APIC_FWUpdateSetting::newInstance()->setClientLogForwardProtocol( m_eLogForwardProtocol );
	APIC_FWUpdateSetting::newInstance()->setClientLogForwardForSMBHost( m_scSMBHostName );
	APIC_FWUpdateSetting::newInstance()->setClientLogForwardForSMBFolder( m_scSMBFilePath );
	APIC_FWUpdateSetting::newInstance()->setClientLogForwardForSMBUserName( m_scSMBUserName );
	APIC_FWUpdateSetting::newInstance()->setClientLogForwardForSMBPassword( m_scSMBUserPassword );
	APIC_FWUpdateSetting::newInstance()->setClientLogForwardForWebDAVURL( m_scWebDAVURL );
	APIC_FWUpdateSetting::newInstance()->setClientLogForwardForWebDAVUserName( m_scWebDAVUserName );
	APIC_FWUpdateSetting::newInstance()->setClientLogForwardForWebDAVPassword( m_scWebDAVUserPassword );
	APIC_FWUpdateSetting::newInstance()->setClientLogForwardForWebDAVProxyOffOn( m_blProxy );

	return True;
}

//==================================================================================================
// 概要     : 必須入力項目をチェックします.
// 引数     : なし.
// 戻り値   : True  : 設定値OK.
//            False : エラー(入力不足項目有).
// 備考     : なし.
//==================================================================================================
Bool PNLC_RemoteFWUpdateClientLogForwardSetting::checkSettings( )
{
	Bool result = True;

	if( ( True == m_blLogForward )
	    && ( TYPE_ClientLogForwardProtocolForSMB == m_eLogForwardProtocol )
	    && ( '\0' == m_scSMBHostName[0] || '\0' == m_scSMBFilePath[0] ) ) {
		// 更新ログ送信「する」かつ、転送プロトコルが「SMB」かつ、SMBホスト名またはファイルパスが空の場合.
		result = False;
	} else if( ( True == m_blLogForward )
	           && ( TYPE_ClientLogForwardProtocolForWebDAV == m_eLogForwardProtocol )
	           && ( '\0' == m_scWebDAVURL[0] ) )  {
		// 更新ログ送信「する」かつ、転送プロトコルが「WebDAV」かつ、WebDAVURLが空の場合.
		result = False;
	}
	return result;
}

