/**
* @brief ROM異常暫定救済 通常/拡大切替用の定数.
* @date
*	2012/6/1 OPS1 yusaku [ZeusMLK][制御構成変更 管理No.1150] ROM容量不足対応 新規作成.
*/
const uchar PNLD_RomFatalUnitTxtType_Def	= 	0;		///< 暫定救済警告(通常)文字タイプ.
const uchar PNLD_RomFatalUnitTxtType_Enl	= 	1;		///< 暫定救済警告(拡大)文字タイプ.
/**
* @brief ROM異常暫定救済 使用不可機能のシンボル変換テーブル(通常、拡大).
* @date
*	2012/6/1 OPS1 yusaku [ZeusMLK][制御構成変更 管理No.1150] ROM容量不足対応 新規作成.
*/
struct PNLS_TemporaryRescueUnitTxtId {					///< 暫定救済 機能リスト構造体定義
	TYPE_TemporaryRescueUnit e_RescueUnit;			///< 暫定救済ユニット.
	TEXT_ID puc_FuncName[2];						///< 機能名文字列シンボル.
};
const PNLS_TemporaryRescueUnitTxtId st_UnitList[TYPE_FWReadingUnitMax] = {									///< ROM異常トラブル シンボル変換リスト.
///<	ユニット							通常シンボル					拡大シンボル
	{	TYPE_FWReadingUnitOCR,			{	s_pITMOCR_W308H016A, 			s_pITMEnlOcr 			},	},	///< 一時切り離し対象：OCR.
	{	TYPE_FWReadingUnitWebBrowser,	{	s_pITMWebBrowser_W308H016A, 	s_pITMEnlWebbrowser  	},	},	///< 一時切り離し対象：Webブラウザー.
};
//-----------------------------------------------------------------------------------------------.
/**
* @brief ROM異常暫定救済 :表示用機能リスト初期化処理.
*	機能リストのユニット、シンボルを格納する.
*	[初期値] e_RescueUnit:TYPE_TemporaryRescueUnitNone, puc_FuncName:NULL.
* @param st_FuncList:機能リストポインタ.
* @param e_Size:機能リストのサイズ 原則TYPE_FWReadingUnitMaxと同値になるはず.
* @return 無し
* @date
*	2012/6/1 OPS1 yusaku [ZeusMLK][制御構成変更 管理No.1150] ROM容量不足対応 新規作成.
*/
//-----------------------------------------------------------------------------------------------.
void PNLC_RomFatalUnitListSetting::initFuncList( PNLS_InterimRescueFatalList* st_FuncList, TYPE_FWReadingUnit e_Size ) {
	if( NULL == st_FuncList ) {																				///< リストのNULLチェック.
		SYSF_logMsg( "%s:(%d) === Assert Failed!\n", __FILE__, __LINE__, 3, 4, 5, 6 );						///< アサート.
		return;
	}
	PNLS_InterimRescueFatalList* pst_FuncList = st_FuncList;												///< 機能リスト(引数)のデータアドレス.
	for( uchar uc_ListIndex = 0; uc_ListIndex < TYPE_FWReadingUnitMax; uc_ListIndex++, pst_FuncList++ ) {		///< 機能リスト(引数)の走査.
// Comment 2019/03/18 HCLT_Krishnakumar [IT6-EagleH][OP_BTS-3666] Added log for Detail code.
		if( NULL == pst_FuncList ){
			LOGF_debug_PutEventLog( LOGF_DEBUG_EVENT_KIND_ALL, 0, LOGD_DEBUG_LEVEL_INFO, "Assert Failed!" );
		 	return;
		}
		pst_FuncList->e_RescueUnit = TYPE_FWReadingUnitMax;													///< 機能リスト(引数)にユニットMAX値(終端)登録.
		pst_FuncList->puc_FuncName = s_Space1;																///< 機能リスト(引数)にシンボル無し登録.
	}
}
//-----------------------------------------------------------------------------------------------.
/**
* @brief ROM異常暫定救済 :暫定救済ユニット 表示用機能リスト取得API.
* @param (InOut)機能リスト 表示用.
* @param e_Size:機能リストのサイズ 原則TYPE_FWReadingUnitMaxと同値になるはず.
* @return 無し
* @date
*	2012/6/1 OPS1 yusaku [ZeusMLK][制御構成変更 管理No.1150] ROM容量不足対応 新規作成.
*/
//-----------------------------------------------------------------------------------------------.
void PNLC_RomFatalUnitListSetting::getFuncList( PNLS_InterimRescueFatalList* st_FuncList, TYPE_FWReadingUnit e_Size ) {
	APIC_SystemStatus* pc_SystemStatus = APIC_SystemStatus::newInstance();													///< SystemStatusの実体アドレス取得.
	if( NULL == st_FuncList || NULL == pc_SystemStatus ) {																	///< リストのNULLチェック.
		SYSF_logMsg( "%s:(%d) ===Assert Failed!\n", __FILE__, __LINE__, 3, 4, 5, 6 );										///< アサート.
		return;
	}
	uchar uc_TxtType = onlyPanel.bl_isEnlargeDisplayMode ? PNLD_RomFatalUnitTxtType_Enl : PNLD_RomFatalUnitTxtType_Def;		///< 通常/拡大シンボル選択.
	uchar uc_UnitIndex = 0;																									///< 暫定救済可能ユニット情報(CommonData)Index.
	TYPE_TemporaryRescueEnableMode e_TmpRescueModeList[TYPE_FWReadingUnitMax];												///< 各ユニットの暫定救済 可能/不可 記憶用テーブル(CommonData)宣言.
	for( uc_UnitIndex = 0; uc_UnitIndex < TYPE_FWReadingUnitMax; uc_UnitIndex++ ) {											///< 各ユニットの暫定救済 可能/不可 記憶用テーブル(CommonData)初期化.
		e_TmpRescueModeList[uc_UnitIndex] = TYPE_TemporaryRescueDisable;													///< 暫定救済不可で無効(CommonData).
	}
	pc_SystemStatus->getTemporaryRescueFunctionList( e_TmpRescueModeList );													///< 各ユニットの暫定救済可能/不可(CommonData)を取得.
	uchar uc_ListIndex = 0;																									///< 機能リスト(引数)Index.
	PNLS_InterimRescueFatalList* pst_FuncList = st_FuncList;																///< 機能リスト(引数)のデータアドレス.
	for( uc_UnitIndex = 0; uc_UnitIndex < TYPE_FWReadingUnitMax; uc_UnitIndex++ ) {											///< 暫定救済ユニット情報(CommonData)走査.
		if( e_Size <= uc_ListIndex ) {																						///< 機能リスト(引数)のサイズを超えていた時.
			SYSF_logMsg( "%s:(%d) === Common-Panel 配列要素数不一致!\n", __FILE__, __LINE__, 3, 4, 5, 6 );					///< アサート.
			break;																											///< 機能リスト(引数)への登録処理終了.
		}
		if( TYPE_TemporaryRescueEnable == e_TmpRescueModeList[uc_UnitIndex] ) {												///< 暫定救済可能ユニットがあった場合(CommonData).
			pst_FuncList->e_RescueUnit = uc_UnitIndex;																		///< 機能リスト(引数)に暫定救済ユニット(固定配列)登録.
			pst_FuncList->puc_FuncName = st_UnitList[uc_UnitIndex].puc_FuncName[uc_TxtType];								///< 機能リスト(引数)にシンボル(固定配列)を登録.
			uc_ListIndex++;																									///< 機能リスト(引数)Indexを一つ進める.
			pst_FuncList++;																									///< 機能リスト(引数)のデータアドレスを一つ進める.
		}
	}
}
void PnlComIGCWaitDisplayClose( )
{
	// 表示フラグが落ちた場合.
	// - 非同期型APIからのコールバックが戻ってきた場合等が該当.

	PBasicMessageProc* c_NextGamen = NULL;
	c_NextGamen = pc_ManageIGCWaitDisplay.getnextIGCGamen();		// 遷移先取得.

	short ss_IGCDisplayID = pc_ManageIGCWaitDisplay.getIGCDisplayID();	// IGC画面ID取得.

	switch( ss_IGCDisplayID )
	{
		case PCGD_IGCDisplayStandard:
		default:
			PBasicMessageProc::setNextGamen( c_NextGamen );
			break;
	}
}

// ===============================================================================================
//	概要      ：コンストラクタ.
//	戻り値    ：.
// ===============================================================================================
PNLC_DigitalIDAddressEx::PNLC_DigitalIDAddressEx()	// コンストラクタ.
{
	// デジタルID宛先リスト用配列の初期化.
	memset( &s_MmbDigitalIDExAddress[ 0 ], 0, ( sizeof( s_MmbDigitalIDExAddress ) / sizeof( PNLS_DigitalIDAddressInfoEx ) ) );
	// デジタルID宛先リストの初期化.
	s_MmbDigitalIDExList.init( &s_MmbDigitalIDExAddress[ 0 ], ( ushort )( sizeof( s_MmbDigitalIDExAddress ) / sizeof( PNLS_DigitalIDAddressInfoEx ) ) );
}
// ===============================================================================================
//	概要      ：デジタルID選択情報 .
//	戻り値    ：取得結果（ True:成功 False:失敗 ）.
// ===============================================================================================
Bool PNLC_DigitalIDAddressEx::getAddress( PNLS_DigitalIDAddressInfoEx* ps_addrInfo, ushort us_Index )
{
	if( ( 0 == us_Index ) || ( s_MmbDigitalIDExList.getNodeSize() < us_Index ) ) {
		// 引数が不正な場合.
		PnlComPutDebugLog( True, UC_PNL_LOGPATTERN_1, "PNLC_DigitalIDAddressEx::getAddress", UC_PNL_ERROR_PARAMETER );
		return False;
	}
	// 指定した宛先情報を取得する.
	s_MmbDigitalIDExList.getNode( *ps_addrInfo, us_Index );

	return True;
}
// ===============================================================================================
//	概要      ：デジタルID選択情報 .
//	戻り値    ：登録結果（ True:成功 False:失敗 ）.
// ===============================================================================================
Bool PNLC_DigitalIDAddressEx::setAddress( PNLS_DigitalIDAddressInfoEx* ps_addrInfo )
{
	if( ps_addrInfo == NULL ) {	// 引数のデジタルIDアドレス情報が空の場合.
		return False;
	}
	// 宛先件数を取得.
	const ushort us_AddressCount = s_MmbDigitalIDExList.getNodeSize();
	for( ushort i = 1; us_AddressCount >= i; ++i ) {
		// 選択されている宛先を順次取得.
		PNLS_DigitalIDAddressInfoEx s_AddressInfo;
		memset( &s_AddressInfo, 0, sizeof( s_AddressInfo ) );
		s_MmbDigitalIDExList.getNode( s_AddressInfo, i );
		// 指定した宛先と同一のものがある場合.
		if( ps_addrInfo->ul_AddressNo == s_AddressInfo.ul_AddressNo ) {
			s_MmbDigitalIDExList.updateNode( *ps_addrInfo, i );
			return True;
		}
	}
	s_MmbDigitalIDExList.addNode( *ps_addrInfo );
	return True;
}
// ===============================================================================================
//	概要      ：デジタルID選択情報 .
//	戻り値    ：削除結果（ True:成功 False:失敗 ）.
// ===============================================================================================
Bool PNLC_DigitalIDAddressEx::removeAddress( PNLS_DigitalIDAddressInfoEx* ps_addrInfo )
{
	if( ps_addrInfo == NULL ) {	// 引数のデジタルIDアドレス情報が空の場合.
		return False;
	}
	return removeAddress( ps_addrInfo->ul_AddressNo );
}
// ===============================================================================================
//	概要      ：デジタルID選択情報 .
//	戻り値    ：削除結果（ True:成功 False:失敗 ）.
// ===============================================================================================
Bool PNLC_DigitalIDAddressEx::removeAddress( uint32_t ul_AddressNo )
{
	// 宛先件数を取得.
	const ushort us_AddressCount = s_MmbDigitalIDExList.getNodeSize();
	for( ushort i = 1; us_AddressCount >= i; ++i ) {
		// 選択されている宛先を順次取得.
		PNLS_DigitalIDAddressInfoEx s_AddressInfo;
		memset( &s_AddressInfo, 0, sizeof( s_AddressInfo ) );
		s_MmbDigitalIDExList.getNode( s_AddressInfo, i );
		// 指定した宛先と同一のものがある場合.
		if( ul_AddressNo == s_AddressInfo.ul_AddressNo ) {
			s_MmbDigitalIDExList.deleteNode( i );
			return True;
		}
	}
	return False;
}
// ===============================================================================================
//	概要      ：デジタルID選択情報 .
//	戻り値    ：宛先件数.
// ===============================================================================================
ushort PNLC_DigitalIDAddressEx::getAddressCount()
{
	return s_MmbDigitalIDExList.getNodeSize();
}
// ===============================================================================================
//	概要      ：デジタルID選択情報 .
//	戻り値    ：なし.
// ===============================================================================================
void PNLC_DigitalIDAddressEx::clearAddress()
{
	// デジタルID宛先リスト用配列の初期化.
	memset( &s_MmbDigitalIDExAddress[ 0 ], 0, ( sizeof( s_MmbDigitalIDExAddress ) / sizeof( PNLS_DigitalIDAddressInfoEx ) ) );
	s_MmbDigitalIDExList.resetAllNode();
	return;
}

#define PNLD_NativeBufSize (5)

void copyUTF8ToCharSet( char* sc_output , char* sc_input , short ss_width , char sc_lang )
{
	short ss_count = 0;				// 変換後の文字列幅.
	uchar uc_tmp[ 3 + 1 ];			// UTF-8コード一時格納領域.
	short ss_len = 0;				// コピーするUTF-8のバイト数.
	char sc_native[ PNLD_NativeBufSize ];		// ネイティブコード格納用.
	ushort us_unicode;				// Unicode格納用.
	unsigned short us_oneCharSize;
	short ss_nativeSize;
	LIBE_CharSet e_CharSet = LIBE_CharSetASCII;			// 変換優先キャラセット.
	Bool b_ret;
	short ss_i;

	switch( sc_lang ) {
		case -1:					// パネル言語の場合.
			e_CharSet = getCharSetForKeyboadPLib( False );
			break;
		case -2:					// キーボード言語の場合.
			if( False != PLBC_FuncVersionCheck::isOK_Type3() && PnlComIsMyPanel() == False && PCGE_OapMyPanel != PnlComGetMyPanelType() ) {
				// パネル言語設定と同等の処理をする.
				e_CharSet = getCharSetForKeyboadPLib( False );
			} else {
				// キーボード言語設定を取得する.
				e_CharSet = getCharSetForKeyboadPLib( True );
			}
			break;
		case LIBE_CharSetASCII:
		case LIBE_CharSetJISX0201:
		case LIBE_CharSetJISX0208:
		case LIBE_CharSetSJIS:
		case LIBE_CharSetISO8859_1:
		case LIBE_CharSetISO8859_2:
		case LIBE_CharSetISO2022_JP:
		case LIBE_CharSetUTF8:
		case LIBE_CharSetGB18030:
		case LIBE_CharSetKSX1001:
		case LIBE_CharSetBIG5:
		case LIBE_CharSetISO8859_5:
		case LIBE_CharSetISO8859_7:
		case LIBE_CharSetISO8859_9:
		case LIBE_CharSetHalfSJIS:
		case LIBE_CharSetISO8859_4:
		case LIBE_CharSetWindowsCP_1250:
		case LIBE_CharSetWindowsCP_1251:
		case LIBE_CharSetWindowsCP_1252:
		case LIBE_CharSetWindowsCP_1253:
		case LIBE_CharSetWindowsCP_1254:
		case LIBE_CharSetWindowsCP_1257:
			// 引数に応じて変換言語を決定する.
			e_CharSet = ( LIBE_CharSet )sc_lang;
			break;
		default:			// その他のパネル言語の場合.
			// 指定キャラセットはなしとする.
			e_CharSet = LIBE_CharSetASCII;
			break;
	}
	do {
		// バッファ領域の初期化.
		memset( uc_tmp, '\0', sizeof( uc_tmp ) );
		memset( sc_native, '\0', sizeof( sc_native ) );
		// 対象文字が何バイトコードか判定.
		us_oneCharSize = LIBF_getUTF8ByteCount( sc_input );
		// 対象文字を変換用バッファに格納する.
		memcpy( uc_tmp , sc_input , us_oneCharSize );
		// Unicodeに変換する.
		_TransferUTF8ToUnicode( uc_tmp , &us_unicode );
		// 指定言語を優先して変換する.
		for( ss_i = 0 ; ss_i < LIBE_CharSetMax + 1 ; ss_i++ ) {			// LIBE_CharSetの定数の数+1で全てのテーブルを調査する.
			if( ss_i == 0 ) {							// 最初に優先言語への変換が可能か調査する.
				b_ret = LIBF_CharcodeSearchFromUnicode( e_CharSet, us_unicode, sc_native, PNLD_NativeBufSize );
			} else {
				b_ret = LIBF_CharcodeSearchFromUnicode( ( LIBE_CharSet )( ss_i - 1 ) , us_unicode, sc_native, PNLD_NativeBufSize );
			}
			if( b_ret == True ) {
				break;
			} else {
				// 見つからなかった場合はブラックスクエアになるため、2バイトと判断する.

			}
		}
		if( b_ret == True ) {							// テーブルで文字コードが見つかった場合.
			// 変換後の文字列の幅を取得する.
			ss_nativeSize = ( short )strlen( sc_native );
			if( ss_nativeSize + ss_count <= ss_width ) {			// 変換後の文字列幅が限界を超えない場合.
				// 変換後の文字列幅を加算する.
				ss_count = (short)( ss_count + ss_nativeSize );
				// UTF-8のバイト数を加算する.
				ss_len = (short)( ss_len + us_oneCharSize );
				// 文字列参照ポインタを進める.
				sc_input += us_oneCharSize;
				// 変換文字を格納.
				strcat( sc_output, sc_native );
			} else {											// 変換後の文字列幅が限界を超える場合.
				break;
			}
		} else {										// テーブルで文字コードが見つからなかった場合.
			// 見つからなかった場合はブラックスクエアになるため、2バイトと判断する.
			if( 2 + ss_count <= ss_width ) {			// 変換後の文字列幅が限界を超えない場合.
				// 変換後の文字列幅を加算する.
				ss_count = (short)( ss_count + 2 );
				// UTF-8のバイト数を加算する.
				ss_len = (short)( ss_len + us_oneCharSize );
				// 文字列参照ポインタを進める.
				sc_input += us_oneCharSize;
				// 変換文字を格納.
				strcat( sc_output, sc_native );
			} else {											// 変換後の文字列幅が限界を超える場合.
				break;
			}
		}
	} while( *sc_input != '\0' );				// 入力文字がない場合は終了.

}

// ===============================================================================================
//	概要      ：シングルサインオン時のSMBログイン名を取得.
//	戻り値    ：なし.
// ===============================================================================================
void getSMBLoginNameForSSO( char* psc_LoginName )
{
	if( NULL == psc_LoginName ) {LOGF_debug_PutEventLog( LOGF_DEBUG_EVENT_KIND_ALL, 0, LOGD_DEBUG_LEVEL_UNKNOWN, "Assert Failed!" ); return ;}

	APIC_User* pC_User = PnlComGetUser();
	if( NULL != pC_User ) {
		char    sc_DomainName[PNLD_NetworkSetSSODomainNameSize + 1];
		memset( sc_DomainName , 0x00 , sizeof( sc_DomainName ) );
		// ユーザー名取得.
		// getInputUserNameはICカードログインではカードIDをユーザー名と覚えてしまうので
		// getUserNameUTF8を使用する.
		pC_User->getUserNameUTF8( psc_LoginName );
		// ログイン中ユーザのドメイン名取得.
		Bool bl_Ret = pC_User->getDomainNameForLoginUser( pC_User->getUserNo(), sc_DomainName );
		if( False == bl_Ret ) {	// 認証サーバー設定がActive Directory以外.
			memset( sc_DomainName , 0x00 , sizeof( sc_DomainName ) );

			APIC_UserAuthenticationSetting* pC_AuthSetting = PnlComGetUserAuthenticationSetting();
			if( NULL != pC_AuthSetting ) {
				TYPE_UserAuthentication e_UserAuthentication = PnlComGetUserAuthentication()->getUserAuthentication(PNLC_NetworkLan::getInstance()->getLine());
				if( ( TYPE_UserAuthenticationServer == e_UserAuthentication ) || ( TYPE_UserAuthenticationDeviceAndServer == e_UserAuthentication ) ) {
					// 認証方式が外部認証サーバー 又は 本体＋外部サーバー認証の時.
					APIC_AuthenticationSeverSetting* apicAuth = APIC_AuthenticationSeverSetting::newInstance();
					if( NULL == apicAuth ) {LOGF_debug_PutEventLog( LOGF_DEBUG_EVENT_KIND_ALL, 0, LOGD_DEBUG_LEVEL_UNKNOWN, "Assert Failed!" ); return ;}
					char sc_ServerName[ APID_MaxLengthOfServerName + 1 ];
					memset( sc_ServerName , 0x00 , sizeof( sc_ServerName ) );
					pC_User->getServerName( sc_ServerName );									// 認証外部サーバー名取得.
					char sc_SrvIndex = 0;
					// 認証外部サーバーインデックス取得.
					if( False == apicAuth->checkServerGroup() ) {
						// サーバー名よりサーバーIndexを取得.
						sc_SrvIndex = apicAuth->getServerIndexFromName( sc_ServerName );
					} else {
						// サーバー名よりサーバーグループIndexを取得.
						sc_SrvIndex = static_cast<APID_AuthenticationServerIndex>( apicAuth->getServerGroupIndexFromName( sc_ServerName , PNLC_NetworkLan::getInstance()->getLine() ) );
					}

					APIS_AuthenticationServerInfo  st_AuthenticationServerInfo;
					// 外部認証サーバの設定情報の初期化.
					st_AuthenticationServerInfo.e_ServerType = TYPE_AuthenticationServerTypeNone;		// サーバ種別.
					memset( st_AuthenticationServerInfo.sc_ServerName, '\0', sizeof( st_AuthenticationServerInfo.sc_ServerName ) );		// パネル用サーバ名称.
					memset( st_AuthenticationServerInfo.u_Params.s_ActiveDirectory.sc_DefaultDomain, '\0', ( APID_MaxLengthOfDomainNameOfActiveDirectory+1 ) );		// ActiveDirectory認証サーバのパラメータ(デフォルトドメイン名).
					st_AuthenticationServerInfo.u_Params.s_ActiveDirectory.us_Timeout = APID_ActiveDirectoryParams_DefaultTimeout;			// タイムアウト時間[単位：秒](60秒).
					memset( st_AuthenticationServerInfo.u_Params.s_NTLM.sc_DefaultDomain, '\0', ( APID_MaxLengthOfDomainNameOfNTLM+1 ) );		// NTLM認証サーバのパラメータ(デフォルトドメイン名).
					memset( st_AuthenticationServerInfo.u_Params.s_NDS.sc_DefaultNDSTreeName, '\0', ( APID_MaxLengthOfTreeNameOfNDS+1 ) );		// NDS認証サーバのパラメータ(デフォルトNDSツリー名).
					memset( st_AuthenticationServerInfo.u_Params.s_NDS.sc_DefaultNDSContextName, '\0', ( APID_MaxLengthOfContextNameOfNDS+1 ) );		// NDS認証サーバのパラメータ(デフォルトNDSコンテキスト名).
					memset( st_AuthenticationServerInfo.u_Params.s_LDAP.sc_IPAddress, '\0', ( APID_MaxLengthOfIPAddressOfLDAP+1 ) );		// Ldap認証サーバのパラメータ(IPアドレス).
					st_AuthenticationServerInfo.u_Params.s_LDAP.us_PortNo = APID_LDAPDefaultPort_ConnectionPlane;		// Ldap認証サーバのパラメータ(使用ポート番号(非SSL時)).
					st_AuthenticationServerInfo.u_Params.s_LDAP.us_PortNoSSL = APID_LDAPDefaultPort_ConnectionSSL;		// Ldap認証サーバのパラメータ(使用ポート番号(SSL時)).
					st_AuthenticationServerInfo.u_Params.s_LDAP.us_Timeout = APID_ActiveDirectoryParams_DefaultTimeout;		// Ldap認証サーバのパラメータ(タイムアウト時間[単位：秒](60秒)).
					memset( st_AuthenticationServerInfo.u_Params.s_LDAP.sc_Base, '\0', ( APID_MaxLengthOfBaseOfLDAP+1 ) );		// Ldap認証サーバのパラメータ(検索ベース).
					st_AuthenticationServerInfo.u_Params.s_LDAP.e_AuthenticationType = TYPE_LdapAuthenticationSimple;		// Ldap認証サーバのパラメータ(認証方式).
					st_AuthenticationServerInfo.u_Params.s_LDAP.b_SslOn = APID_LDAPParams_DefaultSslOn;						// Ldap認証サーバのパラメータ(検索属性による認証).
					memset( st_AuthenticationServerInfo.u_Params.s_LDAP.sc_LoginName, '\0', ( TYPD_MaxStrSearchAttrLoginName+1 ) );	// Ldap認証サーバのパラメータ([ログイン名]として使用する文字列).
					memset( st_AuthenticationServerInfo.u_Params.s_LDAP.sc_PassWord, '\0', ( TYPD_MaxStrSearchAttrPassWord+1 ) );	// Ldap認証サーバのパラメータ([パスワード]として使用する文字列).
					st_AuthenticationServerInfo.s_IccLDAP.ss_TimeOutSec = APID_LDAPParams_DefaultTimeout;						// 認証カード検索サーバのパラメータ(タイムアウト時間).
					memset( st_AuthenticationServerInfo.s_IccLDAP.sc_ServerAddress, '\0', ( APID_MaxServerAddress+1 ) );			// 認証カード検索サーバのパラメータ(LDAPサーバアドレス).
					memset( st_AuthenticationServerInfo.s_IccLDAP.sc_SearchChar, '\0', ( APID_MaxSearchChar+1 ) );			// 認証カード検索サーバのパラメータ(検索ベース).
					memset( st_AuthenticationServerInfo.s_IccLDAP.sc_SearchCommand, '\0', ( APID_MaxSearchCommand+1 ) );			// 認証カード検索サーバのパラメータ(検索属性).
					memset( st_AuthenticationServerInfo.s_IccLDAP.sc_UserCommand, '\0', ( APID_MaxUserCommand+1 ) );			// 認証カード検索サーバのパラメータ(ユーザ名とする属性).
					st_AuthenticationServerInfo.s_IccLDAP.b_UserOn = True;													// 認証カード検索サーバのパラメータ(ユーザ名の取得方法).
					st_AuthenticationServerInfo.s_IccLDAP.b_SslOn = False;													// 認証カード検索サーバのパラメータ(SSL使用設定).
					st_AuthenticationServerInfo.s_IccLDAP.us_PortNumber = APID_LDAPDefaultPort_ConnectionPlane;				// 認証カード検索サーバのパラメータ(ポート番号).
					st_AuthenticationServerInfo.s_IccLDAP.us_SslPortNumber = APID_LDAPDefaultPort_ConnectionSSL;			// 認証カード検索サーバのパラメータ(SSLポート番号).
					st_AuthenticationServerInfo.s_IccLDAP.us_Srvcert = TYPD_Cert_Validity;									// 認証カード検索サーバのパラメータ(証明書検証強度設定).
					st_AuthenticationServerInfo.s_IccLDAP.e_AuthenticationType = TYPE_LdapAuthenticationSimple;				// 認証カード検索サーバのパラメータ(認証方式).
					memset( st_AuthenticationServerInfo.s_IccLDAP.sc_LoginNameFromUTF8, '\0', ( APID_MaxLoginName+1 ) );		// 認証カード検索サーバのパラメータ(ログイン名).
					memset( st_AuthenticationServerInfo.s_IccLDAP.sc_PasswordFromUTF8, '\0', ( APID_MaxPassword+1 ) );			// 認証カード検索サーバのパラメータ(パスワード).
					memset( st_AuthenticationServerInfo.s_IccLDAP.sc_DomainNameUTF8, '\0', ( APID_MaxDomainName+1 ) );			// 認証カード検索サーバのパラメータ(ドメイン名).
					memset( st_AuthenticationServerInfo.s_IccLDAP.sc_DomainNameUTF8, '\0', ( APID_MaxDomainName+1 ) );			// 認証カード検索サーバのパラメータ(ドメイン名).
					st_AuthenticationServerInfo.s_IccLDAP.b_RefferalOn = True;												// 認証カード検索サーバのパラメータ(refferal設定).
					APIS_AuthServerGroupInfo st_AuthServerGroupInfo = {};	// サーバーグループ情報.
					// 認証中のサーバー情報取得.
					if( False == apicAuth->checkServerGroup() ) {
						// サーバーIndexよりサーバー情報を取得.
						apicAuth->getServerInfo( sc_SrvIndex, &st_AuthenticationServerInfo, PNLC_NetworkLan::getInstance()->getLine() );
					} else {
						// サーバーグループIndexよりサーバーグループ情報を取得.
						apicAuth->getAuthServerGroupInfo( static_cast<APID_AuthServerGroupIndex>( sc_SrvIndex ), &st_AuthServerGroupInfo , PNLC_NetworkLan::getInstance()->getLine() );
						// サーバーグループ情報のサーバー登録１のサーバー情報を取得.
						apicAuth->getServerInfo( st_AuthServerGroupInfo.sc_ServerIndex[0], &st_AuthenticationServerInfo, PNLC_NetworkLan::getInstance()->getLine() );
					}

					switch( st_AuthenticationServerInfo.e_ServerType ) {	// 認証サーバー設定.
						case TYPE_AuthenticationServerTypeSMB:		// NTLM v1.
						case TYPE_AuthenticationServerTypeNTLMv2:	// NTLM v2.
// comment 2017/11/23 【HCL-Suganya】【IT5_4.2】【RQ686】 Multiple Network Support.
//							pC_AuthSetting->getSmbDefaultDomainName( sc_DomainName );
							pC_AuthSetting->getSmbDefaultDomainName( sc_DomainName , PNLC_NetworkLan::getInstance()->getLine() );
							break;
						default:
							// ドメイン名付加しない.
							break;
					}
				}
			}
		}
		// comment 2015/08/27 OPS1-川手 [特ROM対応][CQ517645] SMB、Kerveros認証の強化対応(PKIの場合以外、ドメインを付与しない).
		if( True == PLBC_FuncPKICheck::isPKI() ){ 		// PKI認証の場合のみ.
			if( sc_DomainName[0] != '\0' ){
				// ユーザー名の文字数の取得処理.
				int32_t i32_loginNamelen = 0;
				i32_loginNamelen = PLBC_UTF8Library::getCharCount( (char *)psc_LoginName );
				// ドメイン名の文字数の取得処理.
				int32_t i32_DomainNamelen = 0;
				i32_DomainNamelen = PLBC_UTF8Library::getCharCount( (char *)sc_DomainName );
				// ユーザーIDの領域に収まる場合、文字列を合成し格納.
				// ドメイン名はユーザー領域へ”ユーザー名”＋”＠”＋”ドメイン名”として表示される.
				if( PCGD_SMB_InputStrName_MAX >= ( i32_loginNamelen + 1 + i32_DomainNamelen ) ){
					strncat( psc_LoginName, "@", 1 );
					strncat( psc_LoginName, sc_DomainName, sizeof(sc_DomainName) );
					// 文字数オーバー警告フラグ設定.
					//onlyPanel.bl_deleteDomainName = False;	// 別件提起で対応.
				}else{
					// 文字数オーバー警告フラグ設定.
					//onlyPanel.bl_deleteDomainName = True;		// 別件提起で対応.
				}
			}
		}
	}
}

// ===============================================================================================
//	概要      ：シングルサインオン時のSMBパスワードを取得.
//	戻り値    ：なし.
// ===============================================================================================
void getSMBPasswordForSSO( char* psc_Password )
{
	if( NULL == psc_Password ) {LOGF_debug_PutEventLog( LOGF_DEBUG_EVENT_KIND_ALL, 0, LOGD_DEBUG_LEVEL_UNKNOWN, "Assert Failed!" ); return ;}

	APIC_User* pC_User = PnlComGetUser();
	if( NULL != pC_User ) {
		if( True == PLBC_FuncVersionCheck::isOK_MiZe_Type2() ) {		// Mi/Ze機能拡張2以降.
			TYPE_UserAuthentication e_UserAuthentication = PnlComGetUserAuthentication()->getUserAuthentication(PNLC_NetworkLan::getInstance()->getLine());
			if( ( TYPE_UserAuthenticationServer           		== e_UserAuthentication 	// 外部サーバー認証.
			      || TYPE_UserAuthenticationIntermeddiateServer == e_UserAuthentication 	// 中間認証サーバ認証.
			      || TYPE_UserAuthenticationDeviceAndServer 	== e_UserAuthentication 	// 本体装置+外部サーバでの認証.
			      || TYPE_UserAuthenticationDeviceAndMidAuth	== e_UserAuthentication )	// 本体装置+拡張サーバでの認証.
			    && True  == PnlComGetUserAccountOn()										// ユーザー認証ログイン済.
			    && True  == onlyPanel.b_AuthenticationCardSearch )  { 						// 認証カード検索でユーザー認証した.
				if( False == onlyPanel.b_AuthenticationCardSearchPasswordInput ) {		// パスワード未入力時.
					// パスワード未入力時は取得しない.
				} else {
					// 認証中のユーザーのパスワード取得.
					pC_User->getUserPassword( psc_Password,
					                          ( TYPE_UserAuthenticationServer == e_UserAuthentication ? True : False ) );
				}
			} else {
				// ログイン時のパスワード取得.
				pC_User->getInputUserPassword( psc_Password );
			}
		} else {
			// ログインパスワード取得.
			pC_User->getInputUserPassword( psc_Password );
		}
	}
}

// ===============================================================================================.
//	概要	：拡張サーバー稼動状態状態 管理クラス : 拡張サーバー稼動状態取得API.
//	戻り値	：True : 稼働中.
//			：False	: ダウン中.
//	備考	：.
// ===============================================================================================.
Bool PNLC_MidAuthServerStatus::getServerStatus()
{
	Bool bl_ret = True;

	APIC_UserAuthentication* apicUserAuth = PnlComGetUserAuthentication();
	APIC_MidAuthServerSetting* apicMidAuthServer= APIC_MidAuthServerSetting::newInstance();

	if( NULL == apicUserAuth || NULL == apicMidAuthServer ) { return bl_ret; }
	if( True == PLBC_FuncVersionCheck::isOK_MiZe_Type2() ) {
		// 認証情報の一時保存設定が有効の場合.
		if( True == apicUserAuth->getAuthCacheMode(PNLC_NetworkLan::getInstance()->getLine()) ) {
			// ユーザー認証方式が「拡張サーバー」または「本体+拡張サーバー認証」の場合.
			if( TYPE_UserAuthenticationIntermeddiateServer == apicUserAuth->getUserAuthentication(PNLC_NetworkLan::getInstance()->getLine())
			    || TYPE_UserAuthenticationDeviceAndMidAuth == apicUserAuth->getUserAuthentication(PNLC_NetworkLan::getInstance()->getLine()) ) {
				// 拡張サーバーダウン中の場合.
				if( False == apicMidAuthServer->getServerStatus() ) {
					bl_ret = False;
				}
			}
		}
	}
	return bl_ret;
}

// ===============================================================================================.
//	概要	：拡張サーバー稼動状態状態 管理クラス : 拡張サーバー稼動状態取得API.
//	引数    ：True  : 稼働中.
//			：False : ダウン中.
//	戻り値	：True  : 稼働中.
//			：False : ダウン中.
//	備考	：.
// ===============================================================================================.
Bool PNLC_MidAuthServerStatus::setServerStatus( Bool bMidAuthServerStatus )
{
	Bool bl_ret = True;

	APIC_UserAuthentication* apicUserAuth = PnlComGetUserAuthentication();
	APIC_MidAuthServerSetting* apicMidAuthServer= APIC_MidAuthServerSetting::newInstance();

	if( NULL == apicUserAuth || NULL == apicMidAuthServer ) { return bl_ret; }
	if( True == PLBC_FuncVersionCheck::isOK_MiZe_Type2() ) {
		// 認証情報の一時保存設定が有効の場合.
		if( True == apicUserAuth->getAuthCacheMode(PNLC_NetworkLan::getInstance()->getLine()) ) {
			// ユーザー認証方式が「拡張サーバー」または「本体+拡張サーバー認証」の場合.
			if( TYPE_UserAuthenticationIntermeddiateServer == apicUserAuth->getUserAuthentication(PNLC_NetworkLan::getInstance()->getLine())
			    || TYPE_UserAuthenticationDeviceAndMidAuth == apicUserAuth->getUserAuthentication(PNLC_NetworkLan::getInstance()->getLine()) ) {
				// 拡張サーバー稼動状態を設定.
				apicMidAuthServer->setServerStatus( bMidAuthServerStatus );
				bl_ret = bMidAuthServerStatus;
			}
		}
	}
	return bl_ret;
}

// ===============================================================================================.
//	概要	：拡張サーバー上限値使用、取得済み判定.
//	備考	：戻り値	True	: 取得済み、使用しない.
//			：			 False	: 未取得.
// ===============================================================================================.
Bool PNLC_MidAuthServerStatus::isGetServerDownLimit( PNLE_ServerDownLimitType e_LimitType )
{
	Bool bl_ret = False;

	uint32_t ui32_LimitCnt = 0;
	TYPS_ServerDownLimitSetting st_ServerLimitSetting = {0};
	APIC_User* pc_user = PnlComGetUser();
	APIC_UserAuthentication* pc_userAuth = PnlComGetUserAuthentication();

	if( NULL != pc_user && NULL != pc_userAuth ) {
		// サーバーダウン上限値：管理しない.
		if( False == pc_userAuth->getServerDownLimitEnable() ) { return bl_ret; }

		// サーバーダウン時上限値取得.
		pc_userAuth->getServerDownLimitSetting( &st_ServerLimitSetting );

		switch( e_LimitType ) {
			case PNLE_ServerDownLimitType_Total:	ui32_LimitCnt = st_ServerLimitSetting.ul_TotalLimitTotal;		break;
			case PNLE_ServerDownLimitType_Color:	ui32_LimitCnt = st_ServerLimitSetting.ul_TotalLimitFullColor;	break;
			case PNLE_ServerDownLimitType_Black:	ui32_LimitCnt = st_ServerLimitSetting.ul_TotalLimitMonoColor;	break;
			case PNLE_ServerDownLimitType_Credit:	ui32_LimitCnt = st_ServerLimitSetting.ul_TotalLimitCredit;	break;
			default: break;
		}

		// サーバーダウン上限値取得済み.
		// サーバーダウン上限値：使用しない.
		// 上記いずれかの場合は、Trueを返却.
		if( True == pc_user->isGetServerDownLimit()
		    ||	0 == ui32_LimitCnt ) {
			bl_ret = True;
		}
	}

	return bl_ret;
}

// ===============================================================================================.
//	概要	：		// 拡張サーバー上限値使用、取得済みでのメッセージ種別取得
//	備考	：戻り値	PNLE_LimitOverMsgType_Normal	: 通常時.
//			：		    PNLE_LimitOverMsgType_NonSupply	: 拡張サーバーダウン中未補充.
//			：		    PNLE_LimitOverMsgType_Supply	: 拡張サーバーダウン中お補充済み.
// ===============================================================================================.
PNLE_LimitOverMsgType PNLC_MidAuthServerStatus::GetLimitOverMsgType( PNLE_ServerDownLimitType e_LimitType )
{
	PNLE_LimitOverMsgType eMsgType = PNLE_LimitOverMsgType_Normal;
	// 拡張サーバーダウン中.
	if( False == getServerStatus() ) {
		eMsgType = PNLE_LimitOverMsgType_NonSupply;
		// 上限管理しない、もしくは取得済みの場合.
		if( True == isGetServerDownLimit( e_LimitType ) ) {
			// 補充済みメッセージを設定.
			eMsgType = PNLE_LimitOverMsgType_Supply;
		}
	}

	return eMsgType;
}

// ===============================================================================================
//	概要      ：SMTP認証パスワード画面に遷移する必要があるかどうか.
//	戻り値    ：True	:画面遷移あり.
//				False	:画面遷移なし.
// ===============================================================================================
Bool isNeedSMTPCertifyPasswordInput( void )
{
	Bool bl_result = False;

//Comment 2017/12/01【HCLT-Sudheer】【IT5 4.2】【RQ686】 API Correction.
//	TYPE_SmtpCertification e_SmtpCertification = PnlComGetMailSendSetting()->getSmtpCertification();
	TYPE_SmtpCertification e_SmtpCertification = PnlComGetMailSendSetting()->getSmtpCertification( PNLC_NetworkLan::getInstance()->getLine() );
	APIC_Job* pc_ScanFaxJob = PnlComGetJobScanFax();
	if( NULL == pc_ScanFaxJob ) { return bl_result; }

	// 「SMTP認証を使用する」且つ「宛先にE-mailが存在する」の場合.
	if( ( TYPE_SmtpCertificationBoth == e_SmtpCertification || TYPE_SmtpCertificationSMTP == e_SmtpCertification )	// SMTP認証を使用する.
	    &&( True == isEmailAddressSelect( pc_ScanFaxJob->getJobSpec() ) ) ) {									// 宛先にE-mailが存在するかどうかチェック.
		// SMTP認証方式がユーザー認証を使用するの場合.
// comment 2017/11/15 【HCL-Sindhu】【IT5_4.2】【RQ686】【WP1360】 Multiple Network Support Additional WP.
//		if( TYPE_SmtpCertificationTypeUser == PnlComGetMailSendSetting()->getSmtpCertificationType() ) {
		if( TYPE_SmtpCertificationTypeUser == PnlComGetMailSendSetting()->getSmtpCertificationType( PNLC_NetworkLan::getInstance()->getLine() ) ) {
			TYPE_UserAuthentication e_UserAuthentication = PnlComGetLoginUserAuthenticationType();
			// 外部サーバー認証か中間認証サーバ認証で、カードログインした場合.
			if( ( TYPE_UserAuthenticationServer              		== e_UserAuthentication 	// 外部サーバー認証.
			      || TYPE_UserAuthenticationIntermeddiateServer	== e_UserAuthentication )	// 中間認証サーバ認証.
			    && True == onlyPanel.b_AuthenticationCardSearch ) {								// カードログインした場合.
				// シングルサインオンのパスワードが保持されていない場合.
				if( False == onlyPanel.b_AuthenticationCardSearchPasswordInput ) {
					bl_result = True;
				}
				// 中間認証でSMTP認証を行っていない場合.
				// ZeusBK以降で、中間認証のログイン時に手動入力した場合は初回時もSMTP認証のパスワード画面を出さない.
				// そのため、機能拡張2以前の判定を追加.
			} else if( ( False == PLBC_FuncVersionCheck::isOK_MiZe_Type2() )
			           && ( TYPE_UserAuthenticationIntermeddiateServer	== e_UserAuthentication )
			           && ( False == onlyPanel.b_SmtpUserLogout ) ) {
				bl_result = True;
			}
		}
	}

	return bl_result;
}
