//------------------------------------------------------------------------------
// PCGC_ThumbnailPreviewControl				private.
//------------------------------------------------------------------------------
//------------------------------------------------------------------------------
// PCGC_ThumbnailPreviewControl				protected.
//------------------------------------------------------------------------------
//
//概要    :	PCGC_ThumbnailPreviewControl	: サムネイル画像データ取得応答.
//［引数］	uint32_t					ul_AcceptNum			: 1画像要求毎に割り振られるシリアルナンバー
//			TYPE_ThumbnailResult		e_Result				: 要求画像取得結果
//			TYPS_ActualThumbnailPara	s_ActualThumbnailPara	: サムネイル画像結果パラメータ
//［戻値］	無し.
//作成者  :竹菴.
//レビュー:未実施.
//変更履歴:
//	2016.05.13	N.Sakai		CQ528328対応.
//		キャンセル応答時は未取得を設定し、次の契機で再取得する.
//
void PCGC_ThumbnailPreviewControl::ans_ThumbnailData(
    uint32_t ul_AcceptNum,
    TYPE_ThumbnailResult e_Result,
    TYPS_ActualThumbnailPara s_ActualThumbnailPara )
{
	// サムネイル画像取得応答の対象となるインデックスを取得する.
	uchar uc_Option = getReqThumbnailImageIndex( ul_AcceptNum );
	if( PCGD_ThumbnailImageMaxNum <= uc_Option )
	{
		return;
	}

	PCGS_ThumbnailControl* ps_ThumbnailControl = getThumbnailControlData( uc_Option );
	if( NULL == ps_ThumbnailControl )
	{
		PnlComPutDebugLog( True, UC_PNL_LOGPATTERN_1, "PCGC_ThumbnailPreviewControl::ans_ThumbnailData", UC_PNL_ERROR_PARAMETER );
		return;
	}

// 2016/07/08 CQ532138 画像アクセスログ対応 Sky大嶋.
	addOpeLogThumbnailImage(ps_ThumbnailControl->sl_DocID, ps_ThumbnailControl->sl_BoxID, e_Result);

	if( TYPE_PreviewResult_OK != e_Result )
	{
		// リクエスト失敗時はエラーを設定し、再取得しないようにする.
		// キャンセル応答時は未取得を設定し、次の契機で再取得する.
		if ( TYPE_PreviewResult_Cancel != e_Result ) {
			ps_ThumbnailControl->e_ImageDataStatus = PCGE_ImageDataReqError;
		}

// comment 2017.03.24 SCD2-Sky稲井 [IT5_4.0][問題点No.1012244].
		if(TYPE_ThumbnailResult_Nothing == e_Result){
			//ステータスを「ドキュメント無し」にする.
			ps_ThumbnailControl->e_ImageDataStatus = PCGE_ImageDataNothing;
			if(PNLE_ImageAcquisitionErrorState_None == onlyPanel.getImageAcquisitionErrorState()){
				//画面で警告を出すようにする為、警告発生準備OKにする.
				onlyPanel.setImageAcquisitionErrorState( PNLE_ImageAcquisitionErrorState_ThumbnailOccurrBefore );
			}
		}

		return;
	}

	if( NULL == s_ActualThumbnailPara.psc_ImageDataPointer )
	{
		// 画像ポインタがNULLの場合は画像無し.
		ps_ThumbnailControl->e_ImageDataStatus = PCGE_ImageDataReqError;
		return;
	}

// comment 2018/09/27 SCD2-4G吉田 [EagleH][制御構成変更_No.53] サムネイルサイズ対応.
	APIC_PanelSetting* pc_ThumbnailSize = APIC_PanelSetting::newInstance();
	if( NULL == pc_ThumbnailSize ) {
		return;
	}
	short ss_ThumbnailDotImageSize = pc_ThumbnailSize->getThumbnailLength();
	uint32_t ul_ThumbnailImageSize = ( ss_ThumbnailDotImageSize * ss_ThumbnailDotImageSize * 3 + 6 );

//	if( ( PCGD_ThumbnailDotImageSize < s_ActualThumbnailPara.ss_ImageDotSizeWidth )
//	    || ( PCGD_ThumbnailDotImageSize < s_ActualThumbnailPara.ss_ImageDotSizeHight )
//	    || ( ( PCGD_ThumbnailImageSize - 6 ) < s_ActualThumbnailPara.ul_TotalDataSize ) )
	if( ( ss_ThumbnailDotImageSize < s_ActualThumbnailPara.ss_ImageDotSizeWidth )
	    || ( ss_ThumbnailDotImageSize < s_ActualThumbnailPara.ss_ImageDotSizeHight )
	    || ( ( ul_ThumbnailImageSize - 6 ) < s_ActualThumbnailPara.ul_TotalDataSize ) )
	{
		ps_ThumbnailControl->e_ImageDataStatus = PCGE_ImageDataNonComplete;
		return;
	}

	// 画像取得データ保持.
	ps_ThumbnailControl->e_ImageDataStatus = PCGE_ImageDataComplete;
	ps_ThumbnailControl->e_getImageTone = s_ActualThumbnailPara.e_ImageTone;
	ps_ThumbnailControl->ss_getImageXSize = s_ActualThumbnailPara.ss_ImageDotSizeWidth;
	ps_ThumbnailControl->ss_getImageYSize = s_ActualThumbnailPara.ss_ImageDotSizeHight;

	// コールバックイベントを発生させる.
	pc_PanelMain->ThumbnailCallBackIndi( ( int32_t )uc_Option );

	PnlComMakeWVEvent( PNLD_WVEVENT_THUMBNAIL_GETEND, &uc_Option, sizeof( uc_Option ) );
}

//
//概要    :	PCGC_ThumbnailPreviewControl	: メディアダイレクトサムネイル画像データ取得応答.
//［引数］	uint32_t					ul_AcceptNum					: 1画像要求毎に割り振られるシリアルナンバー
//			TYPE_ThumbnailResult		e_Result						: 要求画像取得結果
//			TYPS_ActualMediaThumbnailPara	s_ActualMediaThumbnailPara	: サムネイル画像結果パラメータ
//［戻値］	無し.
//作成者  :末永.
//レビュー:未実施.
//変更履歴:
//
void PCGC_ThumbnailPreviewControl::ans_MediaDirectData(
    uint32_t ul_AcceptNum,
    TYPE_ThumbnailResult e_Result,
    TYPS_ActualMediaThumbnailPara s_ActualMediaThumbnailPara )
{
	// サムネイル画像取得応答の対象となるインデックスを取得する.
	uchar uc_Option = getReqThumbnailImageIndex( ul_AcceptNum );
	if( PCGD_ThumbnailImageMaxNum <= uc_Option )
	{
		return;
	}

	PCGS_ThumbnailControl* ps_ThumbnailControl = getThumbnailControlData( uc_Option );
	if( NULL == ps_ThumbnailControl )
	{
		PnlComPutDebugLog( True, UC_PNL_LOGPATTERN_1, "PCGC_ThumbnailPreviewControl::ans_ThumbnailData", UC_PNL_ERROR_PARAMETER );
		return;
	}

// 2016/07/08 CQ532138 画像アクセスログ対応 Sky大嶋.
	addOpeLogThumbnailImage(ps_ThumbnailControl->sl_DocID, ps_ThumbnailControl->sl_BoxID, e_Result);

	if( TYPE_PreviewResult_OK != e_Result )
	{
		// リクエスト失敗時はエラーを設定し、再取得しないようにする.
		ps_ThumbnailControl->e_ImageDataStatus = PCGE_ImageDataReqError;
		// 取得種類をメディア画像なしに設定.
		ps_ThumbnailControl->e_GetKind = PCGE_GetPreviewKindNoMedia;
		// 状態を完了に設定する.
		ps_ThumbnailControl->e_ImageDataStatus = PCGE_ImageDataComplete;
		// 画像なしアイコン表示のためにコールバックイベントを発生させる.
		pc_PanelMain->ThumbnailCallBackIndi( ( int32_t )uc_Option );
		return;
	}

	if( NULL == s_ActualMediaThumbnailPara.psc_ImageDataPointer )
	{
		// 画像ポインタがNULLの場合は画像無し.
		ps_ThumbnailControl->e_ImageDataStatus = PCGE_ImageDataReqError;
		return;
	}

// comment 2018/09/27 SCD2-4G吉田 [EagleH][制御構成変更_No.53] サムネイルサイズ対応.
	APIC_PanelSetting* pc_ThumbnailSize = APIC_PanelSetting::newInstance();
	if( NULL == pc_ThumbnailSize ) {
		return;
	}
	short ss_ThumbnailDotImageSize = pc_ThumbnailSize->getThumbnailLength();
	uint32_t ul_ThumbnailImageSize = ( ss_ThumbnailDotImageSize * ss_ThumbnailDotImageSize * 3 + 6 );

//	if( ( PCGD_ThumbnailDotImageSize < s_ActualMediaThumbnailPara.ss_ImageDotSizeWidth )
//	    || ( PCGD_ThumbnailDotImageSize < s_ActualMediaThumbnailPara.ss_ImageDotSizeHight )
//	    || ( ( PCGD_ThumbnailImageSize - 6 ) < s_ActualMediaThumbnailPara.ul_TotalDataSize ) )
	if( ( ss_ThumbnailDotImageSize < s_ActualMediaThumbnailPara.ss_ImageDotSizeWidth )
	    || ( ss_ThumbnailDotImageSize < s_ActualMediaThumbnailPara.ss_ImageDotSizeHight )
	    || ( ( ul_ThumbnailImageSize - 6 ) < s_ActualMediaThumbnailPara.ul_TotalDataSize ) )
	{
		ps_ThumbnailControl->e_ImageDataStatus = PCGE_ImageDataNonComplete;
		return;
	}

	// 画像取得データ保持.
	ps_ThumbnailControl->e_ImageDataStatus = PCGE_ImageDataComplete;
	ps_ThumbnailControl->e_getImageTone = s_ActualMediaThumbnailPara.e_ImageTone;
	ps_ThumbnailControl->ss_getImageXSize = s_ActualMediaThumbnailPara.ss_ImageDotSizeWidth;
	ps_ThumbnailControl->ss_getImageYSize = s_ActualMediaThumbnailPara.ss_ImageDotSizeHight;

	// コールバックイベントを発生させる.
	pc_PanelMain->ThumbnailCallBackIndi( ( int32_t )uc_Option );
	PnlComMakeWVEvent( PNLD_WVEVENT_THUMBNAIL_GETEND, &uc_Option, sizeof( uc_Option ) );
}

//
//概要    :	PCGC_ThumbnailPreviewControl : サムネイル管理情報を取得する.
//［引数］	uchar	uc_Option  : サムネイル表示オプション.
//［戻値］	PCGS_ThumbnailControl	サムネイル管理情報.
//作成者  :竹菴.
//レビュー:未実施.
//変更履歴:
//
PCGS_ThumbnailControl* PCGC_ThumbnailPreviewControl::getThumbnailControlData(
    uchar uc_Option )
{
	if( PCGD_ThumbnailImageMaxNum <= uc_Option )
	{
		PnlComPutDebugLog( True, UC_PNL_LOGPATTERN_1, "PCGC_ThumbnailPreviewControl::getThumbnailControlData", UC_PNL_ERROR_PARAMETER );
		return NULL;
	}

	return &s_ThumbnailControl[uc_Option];
}
//
//概要    :	PCGC_ThumbnailPreviewControl	: サムネイル画像取得応答の対象となるインデックスを取得する.
//［引数］	uint32_t	ul_AcceptNum		: 1画像要求毎に割り振られるシリアルナンバー.
//［戻値］	short	サムネイル画像取得応答の対象となるインデックス.
//作成者  :竹菴.
//レビュー:未実施.
//変更履歴:
//
uchar PCGC_ThumbnailPreviewControl::getReqThumbnailImageIndex(
    uint32_t ul_AcceptNum )
{
	uchar i = 0;
	for( i = 0; PCGD_ThumbnailImageMaxNum > i; ++i )

	{
		// 応答シリアルNoが管理情報と一致判定.
		if( ul_AcceptNum == s_ThumbnailControl[i].ul_reqSerialNo )
		{
			break;
		}
	}
	return i;
}
//
//概要    :	PCGC_ThumbnailPreviewControl	: プレビュー画像データ取得応答.
//［引数］	uint32_t				ul_AcceptNum		: 1画像要求毎に割り振られるシリアルナンバー .
//			TYPE_PreviewResult		e_Result			: 要求画像取得結果 .
//			TYPS_ActualPreviewPara	s_ActualPreviewPara	: プレビュー画像結果パラメータ .
//［戻値］	無し.
//作成者  :竹菴.
//レビュー:未実施.
//変更履歴:
//
void PCGC_ThumbnailPreviewControl::ans_PreviewData(
    uint32_t ul_AcceptNum,
    TYPE_PreviewResult e_Result,
    TYPS_ActualPreviewPara s_ActualPreviewPara )
{
	PanelLog( PNLD_LogKind_Box, "ans_PreviewData: P1[%d] P2[%d] P3[%p]", ul_AcceptNum, e_Result, &s_ActualPreviewPara, 0, 0, 0 );
	// プレビュー画像取得応答の対象となるプレビュー管理情報を取得する.
	PCGE_ImageDisplayType e_ImageDisplayType = getReqPreviewImageDisplayType( ul_AcceptNum );
	PCGS_PreviewControl* ps_PreviewControl = getPreviewControlData( e_ImageDisplayType );
	if( NULL == ps_PreviewControl )
	{
		// キャンセルしてもコールバックが返ることがあるので落とさない事.
		return;
	}

// 2016/07/08 CQ532138 画像アクセスログ対応 Sky大嶋.
	addOpeLogThumbnailImage(ps_PreviewControl->sl_DocID, ps_PreviewControl->sl_BoxID, e_Result);

	// アニメーション表示時は、アニメーションストップ処理を行う.
	if( ( NULL != PnlComGetPreviewSettingIcon( e_ImageDisplayType )->getVerifyPartWaitGraphic() )&&
	    ( ul_AcceptNum == ps_PreviewControl->ul_reqSerialNo ) &&
	    ( ( PCGE_ImageDisplayTypeDocPreview == e_ImageDisplayType ) || ( PCGE_ImageDisplayTypewRightSmall == e_ImageDisplayType ) ) ) {
		if( m_pc_Cmp_VerifyPreviewControl != 0 ) {
			m_pc_Cmp_VerifyPreviewControl->animationEvent( false );
		} else {
			pc_PanelMain->stopAnime();
		}
	}

	if( TYPE_PreviewResult_OK != e_Result )
	{
		// プリント停止警告発生時.
		if( TYPE_PreviewResult_PrintError == e_Result )
		{
			ps_PreviewControl->e_ImageDataStatus = PCGE_ImageDataPrintStop;
			ps_PreviewControl->b_Splitdirection = False;
			ps_PreviewControl->e_getImageTone = s_ActualPreviewPara.e_ImageTone;
			ps_PreviewControl->ss_getImageXSize = s_ActualPreviewPara.ss_ImageDotSizeWidth;
			ps_PreviewControl->ss_getImageYSize = s_ActualPreviewPara.ss_ImageDotSizeHight;
			ps_PreviewControl->ss_getBGXSize = s_ActualPreviewPara.ss_BGImageDotSizeWidth;
			ps_PreviewControl->ss_getBGYSize = s_ActualPreviewPara.ss_BGImageDotSizeHight;
			ps_PreviewControl->ss_getImageShiftSizeX = s_ActualPreviewPara.ss_MarginDotSizeWidth;
			ps_PreviewControl->ss_getImageShiftSizeY = s_ActualPreviewPara.ss_MarginDotSizeHight;
			ps_PreviewControl->ss_getOverlayShiftSizeX = s_ActualPreviewPara.ss_BGImageStartPointX;
			ps_PreviewControl->ss_getOverlayShiftSizeY = s_ActualPreviewPara.ss_BGImageStartPointY;
			ps_PreviewControl->b_ReqPreviewImage = True;
			// コールバックイベントを発生させる.
			pc_PanelMain->PreviewCallBackIndi( ( int32_t )e_ImageDisplayType );
			return;
		}
		// メモリオーバー発生時.
		if( TYPE_PreviewResult_MemoryOver == e_Result )
		{
			ps_PreviewControl->e_ImageDataStatus = PCGE_ImageDataMemoryError;
			ps_PreviewControl->b_Splitdirection = False;
			ps_PreviewControl->e_getImageTone = s_ActualPreviewPara.e_ImageTone;
			ps_PreviewControl->ss_getImageXSize = s_ActualPreviewPara.ss_ImageDotSizeWidth;
			ps_PreviewControl->ss_getImageYSize = s_ActualPreviewPara.ss_ImageDotSizeHight;
			ps_PreviewControl->ss_getBGXSize = s_ActualPreviewPara.ss_BGImageDotSizeWidth;
			ps_PreviewControl->ss_getBGYSize = s_ActualPreviewPara.ss_BGImageDotSizeHight;
			ps_PreviewControl->ss_getImageShiftSizeX = s_ActualPreviewPara.ss_MarginDotSizeWidth;
			ps_PreviewControl->ss_getImageShiftSizeY = s_ActualPreviewPara.ss_MarginDotSizeHight;
			ps_PreviewControl->ss_getOverlayShiftSizeX = s_ActualPreviewPara.ss_BGImageStartPointX;
			ps_PreviewControl->ss_getOverlayShiftSizeY = s_ActualPreviewPara.ss_BGImageStartPointY;
			ps_PreviewControl->b_ReqPreviewImage = True;
			// コールバックイベントを発生させる.
			pc_PanelMain->PreviewCallBackIndi( ( int32_t )e_ImageDisplayType );
			return;
		}
		// キャンセル応答時以外.
		if( TYPE_PreviewResult_Cancel != e_Result )
		{
			// リクエスト失敗時はエラーを設定し、再取得しないようにする.
			ps_PreviewControl->e_ImageDataStatus = PCGE_ImageDataReqError;

// comment 2017.03.24 SCD2-Sky稲井 [IT5_4.0][問題点No.1012244].
			if(TYPE_ThumbnailResult_OutOfSupport == e_Result){
				//ステータスを「ドキュメント無し」にする.
				ps_PreviewControl->e_ImageDataStatus = PCGE_ImageDataNothing;
				if(PNLE_ImageAcquisitionErrorState_None == onlyPanel.getImageAcquisitionErrorState()){
					//画面で警告を出すようにする為、警告発生準備OKにする.
					onlyPanel.setImageAcquisitionErrorState( PNLE_ImageAcquisitionErrorState_PreviewOccurrBefore );
				}
			}
		}
		return;
	}

	if( NULL == s_ActualPreviewPara.psc_ImageDataPointer )
	{
		// 画像ポインタがNULLの場合は画像無し.
		ps_PreviewControl->e_ImageDataStatus = PCGE_ImageDataReqError;
		return;
	}

	const Bool b_Splitdirection = ( ( s_ActualPreviewPara.ss_ImageDotSizeWidth > s_ActualPreviewPara.ss_ImageDotSizeHight ) ? True : False );
// comment 2015/12/10 【HCLT-Meenakshi】【ZeusSZX0】【CQ521750】Stop unnecessary scaling for preview image for 10.1inch.
// comment 2015/12/10 【HCLT-Meenakshi】 【ZeusSZX0】 【CQ521759】 Removing LCD Panel resolution check and added 10.1 inch compilation switch.
// comment 2015/10/27 [HCLT-Krishnakanth] [制御構成変更_No.74] [WP1724] Thumbanail Image Resolution has been modified for 10.1 inch.
//	const short ss_MaxRangeX = getPreviewXYSize( ps_PreviewControl->e_PreviewImageDataSize, b_Splitdirection, True );
//	const short ss_MaxRangeY = getPreviewXYSize( ps_PreviewControl->e_PreviewImageDataSize, b_Splitdirection, False );
	
//	short ss_MaxRangeX;
//	short ss_MaxRangeY; 
	
//	if ( PNLD_PANELSIZE_10_1INCH == PLBC_PanelDeviceCheck::getInstance()->getPanelSize() ) {
//#ifdef DEF_RES_WSVGA
//	const short ss_MaxRangeX = c_ThumbnailPreviewControl.scalePreviewThumbnailWidth(getPreviewXYSize( ps_PreviewControl->e_PreviewImageDataSize, b_Splitdirection, True ));
//	const short ss_MaxRangeY = GFWC_System::getInstance()->convertScalingPartsY (getPreviewXYSize( ps_PreviewControl->e_PreviewImageDataSize, b_Splitdirection, False ));
//	} else {
//#else
	const short ss_MaxRangeX = getPreviewXYSize( ps_PreviewControl->e_PreviewImageDataSize, b_Splitdirection, True );
	const short ss_MaxRangeY = getPreviewXYSize( ps_PreviewControl->e_PreviewImageDataSize, b_Splitdirection, False );
//	}
//#endif
	uint32_t ui32_MaxDataSize = 0;
	switch( e_ImageDisplayType )
	{
		case PCGE_ImageDisplayTypeLeftErea:			// 左エリア表示.
			ui32_MaxDataSize = PCGD_LeftEreaPreviewImageSize;
			break;
		case PCGE_ImageDisplayTypeDocPreview:		// プレビュー表示.
			ui32_MaxDataSize = PCGD_PreviewImageSize;
			break;
		case PCGE_ImageDisplayTypewRightSmall:		// 右プレビュー(小)表示.:
			ui32_MaxDataSize = PCGD_RightSmallPreviewImageSize;
			break;
		default:
			return;
	}

	PCGC_VerifyThumbnailPreviewControl* pc_VerifyControl = PnlComGetVerifyPreviewControl();
	if( NULL == pc_VerifyControl ) {
		LOGF_debug_PutEventLog( LOGF_DEBUG_EVENT_KIND_ALL, 0, LOGD_DEBUG_LEVEL_UNKNOWN, "Assert Failed!" );
		return;
	}
	if( PNLE_MTUIMODE_NONE == pc_VerifyControl->getMultiTouchMode() ) {
		if( ( ss_MaxRangeX < s_ActualPreviewPara.ss_ImageDotSizeWidth )
		    || ( ss_MaxRangeY < s_ActualPreviewPara.ss_ImageDotSizeHight )
		    || ( ( ui32_MaxDataSize - 6 ) < s_ActualPreviewPara.ul_TotalDataSize ) )
		{
			ps_PreviewControl->e_ImageDataStatus = PCGE_ImageDataNonComplete;
			return;
		}
	}

	ps_PreviewControl->e_ImageDataStatus = PCGE_ImageDataComplete;
	ps_PreviewControl->b_Splitdirection = b_Splitdirection;
	ps_PreviewControl->e_getImageTone = s_ActualPreviewPara.e_ImageTone;
	ps_PreviewControl->ss_getImageXSize = s_ActualPreviewPara.ss_ImageDotSizeWidth;
	ps_PreviewControl->ss_getImageYSize = s_ActualPreviewPara.ss_ImageDotSizeHight;
	ps_PreviewControl->ss_getBGXSize = s_ActualPreviewPara.ss_BGImageDotSizeWidth;
	ps_PreviewControl->ss_getBGYSize = s_ActualPreviewPara.ss_BGImageDotSizeHight;
	ps_PreviewControl->ss_getImageShiftSizeX = s_ActualPreviewPara.ss_MarginDotSizeWidth;
	ps_PreviewControl->ss_getImageShiftSizeY = s_ActualPreviewPara.ss_MarginDotSizeHight;
	ps_PreviewControl->ss_getOverlayShiftSizeX = s_ActualPreviewPara.ss_BGImageStartPointX;
	ps_PreviewControl->ss_getOverlayShiftSizeY = s_ActualPreviewPara.ss_BGImageStartPointY;
	ps_PreviewControl->b_ReqPreviewImage = True;
	ps_PreviewControl->e_GetImageDir = s_ActualPreviewPara.e_ImageDir;

	// コールバックイベントを発生させる.
	pc_PanelMain->PreviewCallBackIndi( ( int32_t )e_ImageDisplayType );
	PnlComMakeWVEvent( PNLD_WVEVENT_PREVIEW_GETEND, &e_ImageDisplayType, sizeof( e_ImageDisplayType ) );
}

//
//概要    :	PCGC_ThumbnailPreviewControl : プレビュー管理情報を取得する.
//［引数］	PCGE_ImageDisplayType	e_ImageDisplayType  :  画像表示タイプ.
//［戻値］	PCGS_PreviewControl*	プレビュー管理情報.
//作成者  :竹菴.
//レビュー:未実施.
//変更履歴:
//
PCGS_PreviewControl* PCGC_ThumbnailPreviewControl::getPreviewControlData(
    PCGE_ImageDisplayType e_ImageDisplayType )
{
	uchar uc_Option = 0;
	switch( e_ImageDisplayType )
	{
		// 左エリア表示.
		case PCGE_ImageDisplayTypeLeftErea:
			uc_Option = 0;
			break;
		// プレビュー表示.
		case PCGE_ImageDisplayTypeDocPreview:
		// スタンプ表示.
		case PCGE_ImageDisplayTypeStamp:
		// サムネイル表示.
		case PCGE_ImageDisplayTypeThumbnail:
			uc_Option = 1;
			break;
		// 右プレビュー(小)表示.
		case PCGE_ImageDisplayTypewRightSmall:
			uc_Option = 2;
			break;
		default:
			// キャンセルしてもコールバックが返ることがあるので落とさない事.
			return NULL;
	}

	return &s_PreviewControl[uc_Option];
}
//概要    :	PCGC_ThumbnailPreviewControl	: プレビュー管理情報の先頭アドレスを取得する.
//［引数］	なし.
//［戻値］	char* : プレビュー管理情報の先頭アドレス.
//作成者  :第1OSW開発 長岡.
char* PCGC_ThumbnailPreviewControl::getPreviewControlDataHead()
{
	return s_PreviewControl[1].psc_ImageData;
}

//
//概要    :	PCGC_ThumbnailPreviewControl : プレビュー画像取得応答の対象となる画像表示タイプを取得する.
//［引数］	uint32_t	ul_AcceptNum	: 1画像要求毎に割り振られるシリアルナンバー.
//［戻値］	PCGE_ImageDisplayType	画像表示タイプ.
//作成者  :竹菴.
//レビュー:未実施.
//変更履歴:
//
PCGE_ImageDisplayType PCGC_ThumbnailPreviewControl::getReqPreviewImageDisplayType(
    uint32_t ul_AcceptNum )
{
	PCGE_ImageDisplayType e_ImageDisplayType = PCGE_ImageDisplayTypeAll;
	for( uchar i = 0; PCGD_PreviewImageMaxNum > i; ++i )
	{
		// 応答シリアルNoが管理情報と一致判定.
		if( ul_AcceptNum == s_PreviewControl[i].ul_reqSerialNo )
		{
			e_ImageDisplayType = getPreviewImageDisplayType( s_PreviewControl[i].e_PreviewImageDataSize );
			break;
		}
	}
	return e_ImageDisplayType;
}

//
//概要    :	PCGC_ThumbnailPreviewControl : 画像表示タイプを取得する.
//［引数］	PCGE_PreviewImageDataSize	e_PreviewImageDataSize	: プレビュー画像データサイズ.
//［戻値］	PCGE_ImageDisplayType	画像表示タイプ.
//作成者  :竹菴.
//レビュー:未実施.
//変更履歴:
//
PCGE_ImageDisplayType PCGC_ThumbnailPreviewControl::getPreviewImageDisplayType( PCGE_PreviewImageDataSize e_PreviewImageDataSize )
{
	PCGE_ImageDisplayType e_ImageDisplayType = PCGE_ImageDisplayTypeAll;
	switch( e_PreviewImageDataSize )
	{
		case PCGE_PreviewImageDataSizeLeftErea:				// 左エリア表示.
			e_ImageDisplayType = PCGE_ImageDisplayTypeLeftErea;
			break;
		case PCGE_PreviewImageDataSizePreview1Split:		// プレビュー1分割表示.
		case PCGE_PreviewImageDataSizePreview2Split:		// プレビュー2分割表示.
		case PCGE_PreviewImageDataSizePreview4Split:		// プレビュー4分割表示.
		case PCGE_PreviewImageDataSizePreview8Split:		// プレビュー8分割表示.
			e_ImageDisplayType = PCGE_ImageDisplayTypeDocPreview;
			break;
		case PCGE_PreviewImageDataSizePreviewStamp:			// 右スタンププレビュー表示.
			e_ImageDisplayType = PCGE_ImageDisplayTypeStamp;
			break;
		case PCGE_PreviewImageDataSizePreviewRightSmall:	// 右プレビュー(小)表示.
			e_ImageDisplayType = PCGE_ImageDisplayTypewRightSmall;
			break;
		default:
			PnlComPutDebugLog( True, UC_PNL_LOGPATTERN_1, "PCGC_ThumbnailPreviewControl::getPreviewImageDisplayType", UC_PNL_ERROR_PARAMETER );
			break;
	}
	return e_ImageDisplayType;
}
//
//概要    :	PCGC_ThumbnailPreviewControl : プレビュー画像編集処理.
//［引数］	PCGS_PreviewControl	s_PreviewControl  : 画像データ編集対象の管理情報.
//			short*				pss_EditXSize	  : 画像編集での表示Xサイズ.
//			short*				pss_EditYSize	  : 画像編集での表示Yサイズ.
//［戻値］	Bool	True:表示画像有り False:表示画像なし.
//作成者  :竹菴.
//レビュー:未実施.
//
Bool PCGC_ThumbnailPreviewControl::editPreviewImageDisp(
    PCGS_PreviewControl* ps_PreviewControl,
    short* pss_EditXSize,
    short* pss_EditYSize )
{
	if( ( NULL == ps_PreviewControl ) || ( NULL == pss_EditXSize ) || ( NULL == pss_EditYSize ) )
	{
		PnlComPutDebugLog( True, UC_PNL_LOGPATTERN_1, "PCGC_ThumbnailPreviewControl::editPreviewImageDisp", UC_PNL_ERROR_PARAMETER );
		return False;
	}

	// プレビュー表示画像格納領域初期化.
	memset( psc_PreviewDisplayDataBuf, 0, PCGD_PreviewDisplaySize );	// 2013/11/05 酒井(日立JTE) プレビュー用バッファ領域動的化対応.

	// プレビュー画像最大サイズX,Y.
	const short ss_XMaxBaseImageSize = getPreviewXYSize( ps_PreviewControl->e_PreviewImageDataSize, ps_PreviewControl->b_Splitdirection, True );
	const short ss_YMaxBaseImageSize = getPreviewXYSize( ps_PreviewControl->e_PreviewImageDataSize, ps_PreviewControl->b_Splitdirection, False );

	// 取得画像のサイズが想定範囲内に収まらない場合.
	if( ( 0 >= ps_PreviewControl->ss_getImageXSize )
	    || ( 0 >= ps_PreviewControl->ss_getImageYSize )
	    || ( ss_XMaxBaseImageSize < ps_PreviewControl->ss_getImageXSize )
	    || ( ss_YMaxBaseImageSize < ps_PreviewControl->ss_getImageYSize ) )
	{
		return False;
	}

	// スクロール範囲X,Y.
	const short ss_XRange = (short)( ss_XMaxBaseImageSize - PCGD_PreviewDotImageSize );
	const short ss_YRange = (short)( ss_YMaxBaseImageSize - PCGD_PreviewDotImageSize );

	// 画像切り取り開始位置X,Y.
	short ss_XStartPos = 0;
	short ss_YStartPos = 0;

	// X方向の範囲が0より大きい場合.
	if( 0 < ss_XRange )
	{
		ss_XStartPos = ( short )( ( ss_XRange * ps_PreviewControl->uc_PreviewScrollLevelX ) / ( PCGD_PreviewScrollDivision-1 ) );
	}
	// Y方向の範囲が0より大きい場合.
	if( 0 < ss_YRange )
	{
		ss_YStartPos = ( short )( ( ss_YRange * ps_PreviewControl->uc_PreviewScrollLevelY ) / ( PCGD_PreviewScrollDivision-1 ) );
	}

	// 表示サイズX,Y.
	short ss_XSize = 0;
	short ss_YSize = 0;

	// 表示サイズXを算出.
	short ss_XSizeWork = (short)( ps_PreviewControl->ss_getImageXSize - ss_XStartPos );
	if( 0 < ss_XSizeWork )
	{
		ss_XSize = ( ( PCGD_PreviewDotImageSize < ss_XSizeWork ) ? PCGD_PreviewDotImageSize : ss_XSizeWork );
	}

	// 表示サイズY算出.
	short ss_YSizeWork = (short)( ps_PreviewControl->ss_getImageYSize - ss_YStartPos );
	if( 0 < ss_YSizeWork )
	{
		ss_YSize = ( ( PCGD_PreviewDotImageSize < ss_YSizeWork ) ? PCGD_PreviewDotImageSize : ss_YSizeWork );
	}

	// 表示サイズが0以下または280x280に収まらない場合.
	if( ( 0 >= ss_XSize ) || ( PCGD_PreviewDotImageSize < ss_XSize )
	    || ( 0 >= ss_YSize ) || ( PCGD_PreviewDotImageSize < ss_YSize ) )
	{
		*pss_EditXSize = 0;
		*pss_EditYSize = 0;
		return False;
	}

	// 表示画像1ラインサイズを取得.
	const uint32_t ui32_1LineDispSize = getPreviewImageDataSize( ps_PreviewControl->e_getImageTone, ss_XSize, 1 );

	// 全体画像1ラインサイズを取得.
	const uint32_t ui32_1LineImageSize = getPreviewImageDataSize( ps_PreviewControl->e_getImageTone, ps_PreviewControl->ss_getImageXSize, 1 );

	// 全体画像からの画像切り出し位置Xオフセット値を取得.
	const uint32_t ui32_XDirOffset = getPreviewImageDataSize( ps_PreviewControl->e_getImageTone, ss_XStartPos, 1 );

	// 全体画像からの画像切り出し位置Yオフセット値を取得.
	const uint32_t ui32_YDirOffset = ( uint32_t )( ui32_1LineImageSize * ss_YStartPos );

	// 全体画像から表示画像切り出し処理.
	for( short i = 0; i < ss_YSize; ++i )
	{
		memcpy( &psc_PreviewDisplayDataBuf[5 + ( i * ui32_1LineDispSize )], &ps_PreviewControl->psc_ImageData[5 + ui32_XDirOffset + ui32_YDirOffset + ( i * ui32_1LineImageSize )], ui32_1LineDispSize );	// 2013/11/05 酒井(日立JTE) プレビュー用バッファ領域動的化対応.
	}

	// 表示画像XYサイズを設定.
	*pss_EditXSize = ss_XSize;
	*pss_EditYSize = ss_YSize;
	return True;
}

Bool PCGC_ThumbnailPreviewControl::isIdling( const uchar& uc_idx ) {
	Bool bl_idling = False;
	PCGS_ThumbnailControl* pc_thimbnailControl = getThumbnailControlData( uc_idx );
	if( NULL != pc_thimbnailControl ) {
		if(	PCGE_ImageDataRequext != pc_thimbnailControl->e_ImageDataStatus		// 要求中でない.
		    &&	PCGE_ImageDataComplete != pc_thimbnailControl->e_ImageDataStatus	// 取得済み(描画待ち)でない.
		  ) {
			bl_idling = True;
		}
	}
	return ( bl_idling );
}

//------------------------------------------------------------------------------
// PCGC_ThumbnailPreviewControl				public.
//------------------------------------------------------------------------------
//
//概要    :	PCGC_ThumbnailPreviewControl : サムネイル画像を表示する.
//［引数］	uchar	uc_Option	: サムネイル表示オプション.
//［戻値］	無し.
//作成者  :竹菴.
//レビュー:未実施.
//変更履歴:
//
void PCGC_ThumbnailPreviewControl::showThumbnailImage( uchar uc_Option )
{
	PnlComMakeWVEvent( PNLD_WVEVENT_THUMBNAIL_DRAWSTART, &uc_Option, sizeof( uc_Option ) );

	// サムネイル管理情報を取得する.
	PCGS_ThumbnailControl* ps_ThumbnailControl = getThumbnailControlData( uc_Option );
	if( NULL == ps_ThumbnailControl )
	{
		PnlComPutDebugLog( True, UC_PNL_LOGPATTERN_1, "PCGC_ThumbnailPreviewControl::showThumbnailImage", UC_PNL_ERROR_PARAMETER );
		return;
	}

	// 画像取得ステータスチェック.
	if( PCGE_ImageDataComplete != ps_ThumbnailControl->e_ImageDataStatus )
	{
		return;
	}

	// 画像表示ヘッダーを設定する.
	if( PCGE_GetPreviewKindNoMedia != ps_ThumbnailControl->e_GetKind ) {
		createHeaderData( ps_ThumbnailControl->psc_ImageData, ps_ThumbnailControl->e_getImageTone, ps_ThumbnailControl->ss_getImageXSize, ps_ThumbnailControl->ss_getImageYSize );
	}

	APIC_SoftDipSw* pc_SoftDipSw = APIC_SoftDipSw::newInstance();
	if( NULL == pc_SoftDipSw ) {
		LOGF_debug_PutEventLog( LOGF_DEBUG_EVENT_KIND_ALL, 0, LOGD_DEBUG_LEVEL_UNKNOWN, "Assert Failed!" ); return;
	} else {
		if( True == pc_SoftDipSw->getSoftDipSwBitForPanelSpecNo( DEFSOFTWARESW208, 0 ) ) {	// DipSW No.208=0x01.
			//  ヘッダー情報「画像サイズX,Yサイズ、画像種別」がある為、5byte分ずらして、データをコピー.
			if( TYPE_ImageTone24bit == ps_ThumbnailControl->e_getImageTone ) {
				memset( &ps_ThumbnailControl->psc_ImageData[5], 0xff, ps_ThumbnailControl->ss_getImageXSize*ps_ThumbnailControl->ss_getImageYSize*3 );
			} else {
				memset( &ps_ThumbnailControl->psc_ImageData[5], 0xff, ps_ThumbnailControl->ss_getImageXSize*ps_ThumbnailControl->ss_getImageYSize );
			}
		}
	}

	switch( ps_ThumbnailControl->e_GetKind ) {
		case PCGE_GetPreviewKindOverlay1:	// オーバーレイ1.
		case PCGE_GetPreviewKindOverlay2:	// オーバーレイ2.
		case PCGE_GetPreviewKindOverlay3:	// オーバーレイ3.
		case PCGE_GetPreviewKindOverlay4:	// オーバーレイ4.
		case PCGE_GetPreviewKindOverlay5:	// オーバーレイ5.
		case PCGE_GetPreviewKindOverlay6:	// オーバーレイ6.
			// サムネイル画像を表示する.
			ps_ThumbnailControl->pc_PartsPointerOverlay->changeRawGraphic( ( const uchar* )ps_ThumbnailControl->psc_ImageData );
			ps_ThumbnailControl->pc_PartsPointerOverlay->showEnableAdd( True );
			break;
		case PCGE_GetPreviewKindNoMedia:	// メディアNG画像.
			if( 0 != ps_ThumbnailControl->pc_NotThumbnail ) {
				ps_ThumbnailControl->pc_PartsPointer->showEnable( False );
				ps_ThumbnailControl->pc_NotThumbnail->changeGraphic( PG_USBIcon_X104Y104 );
				ps_ThumbnailControl->pc_NotThumbnail->showEnable( True );
			}
			break;
		default:
			// サムネイル画像を表示する.
			ps_ThumbnailControl->pc_PartsPointer->changeRawGraphic( ( const uchar* )ps_ThumbnailControl->psc_ImageData );
			ps_ThumbnailControl->pc_PartsPointer->showEnableAdd( ps_ThumbnailControl->pc_PartsRawGraphic, True );

// comment 2023/07/04 Sky Nakamura [IT6_2.3][TAS000000013824]暗号化PDF設定時、プレビューを表示しない対応.
			if (True == pc_SoftDipSw->getSoftDipSwBitForPanelSpecNo(DEFSOFTWARESW125, 2)) {
				TYPE_PdfEncryption e_enc = TYPE_PdfEncryptionNon;
				if (True == PNLC_DocInfoMng::newInstance()->getDocInfo_PdfEncryption(ps_ThumbnailControl->sl_BoxID, ps_ThumbnailControl->sl_DocID, &e_enc)) {
					if (TYPE_PdfEncryptionNon != e_enc && DOCE_DocDispTypeInfo_Print == PNLC_BoxDataLib::newInstance()->getDocListType()) {
						replaceThumbnailToEncPdfIconRawData(ps_ThumbnailControl);
					}
					PnlComMtuiIf_BoxDocumentModel::instance()->setThumbnail( ps_ThumbnailControl->sl_DocID, ( uchar* )ps_ThumbnailControl->psc_ImageData );
					if( PNLE_MTUIMODE_V0 <= PLBC_MultiTouchFunction::getMultiTouchMode() ) { //[MTUIv1-CHANGED] MR対応.
						PnlComMtuiIf_BoxDocumentPageModel::instance()->setThumbnail( ps_ThumbnailControl->sl_DocPageNum, ( uchar* )ps_ThumbnailControl->psc_ImageData );
					}
					ps_ThumbnailControl->bl_IsWaitForDocInfo = False;
				}
				else {
					ps_ThumbnailControl->bl_IsWaitForDocInfo = True;
				}
			}
			else {
				PnlComMtuiIf_BoxDocumentModel::instance()->setThumbnail( ps_ThumbnailControl->sl_DocID, ( uchar* )ps_ThumbnailControl->psc_ImageData );
				if( PNLE_MTUIMODE_V0 <= PLBC_MultiTouchFunction::getMultiTouchMode() ) { //[MTUIv1-CHANGED] MR対応.
					PnlComMtuiIf_BoxDocumentPageModel::instance()->setThumbnail( ps_ThumbnailControl->sl_DocPageNum, ( uchar* )ps_ThumbnailControl->psc_ImageData );
				}
				ps_ThumbnailControl->bl_IsWaitForDocInfo = False; // 念のため.
			}
			break;
	}

// comment 2023/07/04 Sky Nakamura [IT6_2.3][TAS000000013824]暗号化PDF設定時、プレビューを表示しない対応.
	if (True != ps_ThumbnailControl->bl_IsWaitForDocInfo) {
		// サムネイル画像データ取得ステータスを描画要求完了に設定する.
		ps_ThumbnailControl->e_ImageDataStatus = PCGE_ImageDataDrawingEnd;
	}

	PnlComMakeWVEvent( PNLD_WVEVENT_THUMBNAIL_DRAWEND, &uc_Option, sizeof( uc_Option ) );
}

//
//概要    :	PCGC_ThumbnailPreviewControl : サムネイル画像を表示する.
//［引数］	sl_BoxNo: ボックスNo.
//          sl_DocNo: 文書No.
//［戻値］	無し.
//作成者  :Sky Kawanishi.
//変更履歴:
// 2023/07/04 Sky Nakamura [IT6_2.3][TAS000000013824]暗号化PDF時プレビューを表示しない対応で新規作成.
void PCGC_ThumbnailPreviewControl::showThumbnailImage(int32_t sl_BoxNo, int32_t sl_DocNo)
{
//comment 2023/07/31 FPT.ThanhLH11 [IT6_2.3][ALL MACHINE][KLOCWORK]PRECISION.LOSS.CALL.
	// for (int si_cnt = 0; si_cnt < PCGD_ThumbnailImageMaxNum; si_cnt++) {
	for (uchar si_cnt = 0; si_cnt < PCGD_ThumbnailImageMaxNum; si_cnt++) {
		PCGS_ThumbnailControl* ps_ThumbnailControl = getThumbnailControlData(si_cnt);
		if (NULL == ps_ThumbnailControl) {
			PnlComPutDebugLog( True, UC_PNL_LOGPATTERN_1, "PCGC_ThumbnailPreviewControl::showThumbnailImage", UC_PNL_ERROR_PARAMETER );
			return;
		}
		if (True == ps_ThumbnailControl->bl_IsWaitForDocInfo && ps_ThumbnailControl->sl_BoxID == sl_BoxNo && ps_ThumbnailControl->sl_DocID == sl_DocNo) {
			showThumbnailImage(si_cnt);
		}
	}
}

//
//概要    :	PCGC_ThumbnailPreviewControl : サムネイル画像データ差し替え.
//［引数］	無し.
//［戻値］	無し.
//作成者  :Sky Kawanishi.
//変更履歴:
// 2023/07/04 Sky Nakamura [IT6_2.3][TAS000000013824]暗号化PDF時プレビューを表示しない対応で新規作成.
void PCGC_ThumbnailPreviewControl::replaceThumbnailToEncPdfIconRawData(PCGS_ThumbnailControl* ps_ThumbnailControl)
{
	char sc_HeaderBuf[5];
	memset(sc_HeaderBuf, 0, sizeof(sc_HeaderBuf));
	sc_HeaderBuf[0] = (char)(ss_EncPdfIconRowDataSizeX >> 8);
	sc_HeaderBuf[1] = (char)(ss_EncPdfIconRowDataSizeX & 0xff);
	sc_HeaderBuf[2] = (char)(ss_EncPdfIconRowDataSizeY >> 8);
	sc_HeaderBuf[3] = (char)(ss_EncPdfIconRowDataSizeY & 0xff);
	sc_HeaderBuf[4] = UC_GPARTS_COLORNUMBER_65536COLOR;
	memcpy(ps_ThumbnailControl->psc_ImageData, sc_HeaderBuf, sizeof(sc_HeaderBuf));

	memcpy(ps_ThumbnailControl->psc_ImageData + 5, tbl_EncPdfIconRawData, sizeof(tbl_EncPdfIconRawData));
}

//
//概要    :	PCGC_ThumbnailPreviewControl : プレビュー画像を表示する.
//［引数］	無し.
//［戻値］	無し.
//作成者  :竹菴.
//レビュー:未実施.
//変更履歴:
void PCGC_ThumbnailPreviewControl::showPreviewImage(
    PCGE_ImageDisplayType e_ImageDisplayType,
    uchar uc_option
)
{
	PnlComMakeWVEvent( PNLD_WVEVENT_PREVIEW_DRAWSTART, &e_ImageDisplayType, sizeof( e_ImageDisplayType ) );

	PCGS_PreviewControl* ps_PreviewControl;
	// プレビュー管理情報を取得する.
	ps_PreviewControl = getPreviewControlData( e_ImageDisplayType );

	if( NULL == ps_PreviewControl )
	{
		PnlComPutDebugLog( True, UC_PNL_LOGPATTERN_1, "PCGC_ThumbnailPreviewControl::showPreviewImage", UC_PNL_ERROR_PARAMETER );
		return;
	}

	// 画像取得ステータスチェック.
	if( PCGE_ImageDataComplete != ps_PreviewControl->e_ImageDataStatus )
	{
		return;
	}

	Bool b_ShowEnable = False;
	Bool b_isQtPreviewIsVisible = False;
	TYPE_ImageTone e_ImageTone = ps_PreviewControl->e_getImageTone;
	short ss_DstXSize = ps_PreviewControl->ss_getImageXSize;
	short ss_DstYSize = ps_PreviewControl->ss_getImageYSize;

	APIC_SoftDipSw* pc_SoftDipSw = APIC_SoftDipSw::newInstance();
	if( NULL == pc_SoftDipSw ) {
		LOGF_debug_PutEventLog( LOGF_DEBUG_EVENT_KIND_ALL, 0, LOGD_DEBUG_LEVEL_UNKNOWN, "Assert Failed!" ); return;
	} else {
		if( True == pc_SoftDipSw->getSoftDipSwBitForPanelSpecNo( DEFSOFTWARESW208, 0 ) ) {	// DipSW No.208=0x01.
			//  ヘッダー情報「画像サイズX,Yサイズ、画像種別」がある為、5byte分ずらして、データをコピー.
			if( TYPE_ImageTone24bit == e_ImageTone ) {
				memset( &ps_PreviewControl->psc_ImageData[5], 0xff, ss_DstXSize*ss_DstYSize*3 );
			} else {
				memset( &ps_PreviewControl->psc_ImageData[5], 0xff, ss_DstXSize*ss_DstYSize );
			}
		}
	}

	char* psc_DstBuff = ps_PreviewControl->psc_ImageData;

	switch( e_ImageDisplayType )
	{
		// 左エリア表示.
		case PCGE_ImageDisplayTypeLeftErea:
			b_ShowEnable = True;
			break;
		// プレビュー表示.
		case PCGE_ImageDisplayTypeDocPreview:
			if( PNLE_MTUIMODE_V0 <= getMultiTouchMode() ) {
				b_ShowEnable = True;
			} else {
				psc_DstBuff = ps_PreviewControl->psc_DisplayImageData;
				b_ShowEnable = editPreviewImageDisp( ps_PreviewControl, &ss_DstXSize, &ss_DstYSize );
			}
			break;
		// 右プレビュー(小)表示.
		case PCGE_ImageDisplayTypewRightSmall:
		// スタンプ表示.
		case PCGE_ImageDisplayTypeStamp:
			b_ShowEnable = True;
			break;
		default:
			PnlComPutDebugLog( True, UC_PNL_LOGPATTERN_1, "PCGC_ThumbnailPreviewControl::showPreviewImage", UC_PNL_ERROR_PARAMETER );
			return;
	}

	if( True == b_ShowEnable )
	{
		// 画像表示ヘッダーを設定する.
		createHeaderData( psc_DstBuff, e_ImageTone, ss_DstXSize, ss_DstYSize );
		if( ( PNLE_MTUIMODE_V2 > PLBC_MultiTouchFunction::getMultiTouchMode() )	// MTUIv2以上 且つ プレビュー画面がMTUIv2に対応済みの場合は.
		    || ( False == m_bl_PreviewMtuiExt ) ) {								// 旧QtWidget or 旧UIのプレビュー処理を行わない.
			// プレビュー画像の切り替えを行う.
			if( True == PnlComQtPreviewIsVisible() ) {
				int32_t i32_PreviewPageNo = ps_PreviewControl->sl_DocPageNum;
				if( True == m_bl_Overlay ) {
					// プレビューオーバーレイの場合 1ページ目はオーバーレイ画像のため1マイナスを行う.
					i32_PreviewPageNo = i32_PreviewPageNo -1;
				}
				i32_PreviewPageNo = PnlComGetVerifyPreviewControl()->getPreviewPageNo( i32_PreviewPageNo, False );
				if( 0 != ps_PreviewControl->sl_DispDocPageNum ) {
					i32_PreviewPageNo = ps_PreviewControl->sl_DispDocPageNum;
				}
				PnlComQtPreviewSetImage( ( uchar* )psc_DstBuff, ps_PreviewControl->sl_DocID, i32_PreviewPageNo, e_ImageDisplayType, PM_TASKID_PANEL );
			}
			else {
				ps_PreviewControl->pc_PartsPointer->changeRawGraphic( ( const uchar* )psc_DstBuff );
			}
		} else {
			if( NULL != m_pc_PreviewObserver ) {
				int32_t i32_Page = ps_PreviewControl->sl_DocPageNum;
				if( True == m_bl_Overlay ) { --i32_Page; }
				i32_Page = PnlComGetVerifyPreviewControl()->getPreviewPageNo( i32_Page );
				m_pc_PreviewObserver->updateImage(
				    ps_PreviewControl->sl_BoxID
				    , ps_PreviewControl->sl_DocID
				    , i32_Page
				    , ( uchar* )( psc_DstBuff )
				    , PCGE_ImageDataComplete );
			}
		}
		// プレビュー画像の切り替えを行う.
		if( False == m_bl_isActivatablePartsDummy )
		{
			b_isQtPreviewIsVisible = PnlComQtPreviewIsVisible();
		} else {
			PNLC_DummyActivatable* p_dummyParts = ( PNLC_DummyActivatable* )ps_PreviewControl->pc_PartsPointer;

			b_isQtPreviewIsVisible = p_dummyParts->isVisiblePreviewParentWidget();
		}
		if( True == b_isQtPreviewIsVisible ) {
			int32_t i32_PreviewPageNo = ps_PreviewControl->sl_DocPageNum;
			if( True == m_bl_Overlay ) {
				// プレビューオーバーレイの場合 1ページ目はオーバーレイ画像のため1マイナスを行う.
				i32_PreviewPageNo = i32_PreviewPageNo -1;
			}
			i32_PreviewPageNo = PnlComGetVerifyPreviewControl()->getPreviewPageNo( i32_PreviewPageNo, False );
			if( 0 != ps_PreviewControl->sl_DispDocPageNum ) {
				i32_PreviewPageNo = ps_PreviewControl->sl_DispDocPageNum;
			}
			if( False == m_bl_isActivatablePartsDummy ) {
				PnlComQtPreviewSetImage( ( uchar* )psc_DstBuff, ps_PreviewControl->sl_DocID, i32_PreviewPageNo, e_ImageDisplayType, PM_TASKID_PANEL );
			} else {
				PNLC_DummyActivatable* p_dummyParts = ( PNLC_DummyActivatable* )ps_PreviewControl->pc_PartsPointer;
				p_dummyParts->setPreviewImageNoticed( ( uchar* )psc_DstBuff, ps_PreviewControl->sl_DocID, i32_PreviewPageNo, e_ImageDisplayType );
			}
		}
		else {
			ps_PreviewControl->pc_PartsPointer->changeRawGraphic( ( const uchar* )psc_DstBuff );
		}
	}

	if( False == m_bl_isActivatablePartsDummy )
	{
		b_isQtPreviewIsVisible = PnlComQtPreviewIsVisible();
	} else {
		PNLC_DummyActivatable* p_dummyParts = ( PNLC_DummyActivatable* )ps_PreviewControl->pc_PartsPointer;
		b_isQtPreviewIsVisible = p_dummyParts->isVisiblePreviewParentWidget();
	}
	if( ( PNLE_MTUIMODE_V2 > PLBC_MultiTouchFunction::getMultiTouchMode() )	// MTUIv2以上 且つ プレビュー画面がMTUIv2に対応済みの場合は.
	    || ( False == m_bl_PreviewMtuiExt ) ) {                               	// 旧QtWidget or 旧UIのプレビュー処理を行わない.
		if( False == PnlComQtPreviewIsVisible() ) {
			// プレビュー画像を表示する.
			ps_PreviewControl->pc_PartsPointer->showEnableAdd( b_ShowEnable );
		}
	}
	if( False == b_isQtPreviewIsVisible ) {
		// プレビュー画像を表示する.
		ps_PreviewControl->pc_PartsPointer->showEnableAdd( b_ShowEnable );
	}

	// プレビュー画像データ取得ステータスを描画要求完了に設定する.
	ps_PreviewControl->e_ImageDataStatus = PCGE_ImageDataDrawingEnd;

	PnlComMakeWVEvent( PNLD_WVEVENT_PREVIEW_DRAWEND, &e_ImageDisplayType, sizeof( e_ImageDisplayType ) );
}
//
//概要    : PCGC_ThumbnailPreviewControl : プレビュー画像のスクロール位置を取得する.
//［引数］	uchar*	puc_PreviewScrollLevelX : スクロールレベル(X方向).
//			uchar*	puc_PreviewScrollLevelY : スクロールレベル(Y方向).
//［戻値］	無し.
//作成者  :竹菴.
//レビュー:未実施.
//変更履歴:
//
void PCGC_ThumbnailPreviewControl::getPreviewScrollLevel( uchar* puc_PreviewScrollLevelX, uchar* puc_PreviewScrollLevelY )
{
	if( ( NULL == puc_PreviewScrollLevelX ) || ( NULL == puc_PreviewScrollLevelY ) )
	{
		PnlComPutDebugLog( True, UC_PNL_LOGPATTERN_1, "PCGC_ThumbnailPreviewControl::getPreviewScrollLevel", UC_PNL_ERROR_PARAMETER );
		return;
	}

	*puc_PreviewScrollLevelX = uc_MmbPreviewScrollLevelX;
	*puc_PreviewScrollLevelY = uc_MmbPreviewScrollLevelY;
}
//
//概要    : PCGC_ThumbnailPreviewControl : プレビュー画像のスクロール位置を変更する.
//［引数］	uchar	uc_PreviewScrollLevelX : スクロールレベル(X方向).
//			uchar	uc_PreviewScrollLevelY : スクロールレベル(Y方向).
//［戻値］	無し.
//作成者  :竹菴.
//レビュー:未実施.
//変更履歴:
//
void PCGC_ThumbnailPreviewControl::changePreviewScrollLevel( uchar uc_PreviewScrollLevelX, uchar uc_PreviewScrollLevelY )
{
	if( ( PCGD_PreviewScrollDivision <= uc_PreviewScrollLevelX )
	    || ( PCGD_PreviewScrollDivision <= uc_PreviewScrollLevelY ) )
	{
		PnlComPutDebugLog( True, UC_PNL_LOGPATTERN_1, "PCGC_ThumbnailPreviewControl::changeDocPreviewScrollLevel", UC_PNL_ERROR_PARAMETER );
		return;
	}

	uc_MmbPreviewScrollLevelX = uc_PreviewScrollLevelX;
	uc_MmbPreviewScrollLevelY = uc_PreviewScrollLevelY;
}
//
//概要    : PCGC_ThumbnailPreviewControl : プレビュー画像分割表示のスクロール位置を取得する（Y方向）.
//［引数］	無し.
//［戻値］	uchar	:スクロールレベル（Y方向）.
//作成者  :竹菴.
//レビュー:未実施.
//変更履歴:
//
uchar PCGC_ThumbnailPreviewControl::getScrollLevelUpDown()
{
	// スクロールレベル（Y方向）を返す.
	return uc_MmbPreviewScrollLevelY;
}
//
//概要    : PCGC_ThumbnailPreviewControl : プレビュー画像分割表示のスクロール位置を取得する（X方向）.
//［引数］	無し.
//［戻値］	uchar	:スクロールレベル（X方向）.
//作成者  :竹菴.
//レビュー:未実施.
//変更履歴:
//
uchar PCGC_ThumbnailPreviewControl::getScrollLevelLeftRight()
{
	// スクロールレベル（X方向）を返す.
	return uc_MmbPreviewScrollLevelX;
}
//
//概要    : PCGC_ThumbnailPreviewControl : プレビュー画像分割表示のダイレクトタッチエリアを設定する（Y方向）.
//［引数］	uchar	uc_DirectTouchArea :ダイレクトタッチエリア（Y方向）.
//［戻値］	無し.
//作成者  :竹菴.
//レビュー:未実施.
//変更履歴:
//
void PCGC_ThumbnailPreviewControl::setScrollDirectTouchAreaUpDown( uchar uc_DirectTouchArea )
{
	// プレビュー画像分割表示のスクロールが有効か判定する.
	if( False == isEnablePreviewScroll() )
	{
		return;
	}

	// プレビュー画像取得応答の対象となるプレビュー管理情報を取得する.
	PCGS_PreviewControl* ps_PreviewControl = getPreviewControlData( e_MmbImageDisplayType );
	if( ps_PreviewControl == NULL )
	{
		return;
	}

	if( uc_DirectTouchArea < ps_PreviewControl->uc_PreviewScrollLevelY )
	{
		// プレビュー画像分割表示を上にスクロールする.
		scrollPreviewUp();
	}
	else if( uc_DirectTouchArea > ps_PreviewControl->uc_PreviewScrollLevelY )
	{
		// プレビュー画像分割表示を下にスクロールする.
		scrollPreviewDown();
	}
}
//
//概要    : PCGC_ThumbnailPreviewControl : プレビュー画像分割表示のダイレクトタッチエリアを設定する（X方向）.
//［引数］	uchar	uc_DirectTouchArea :ダイレクトタッチエリア（X方向）.
//［戻値］	無し.
//作成者  :竹菴.
//レビュー:未実施.
//変更履歴:
//
void PCGC_ThumbnailPreviewControl::setScrollDirectTouchAreaLeftRight( uchar uc_DirectTouchArea )
{
	// プレビュー画像分割表示のスクロールが有効か判定する.
	if( False == isEnablePreviewScroll() )
	{
		return;
	}

	// プレビュー画像取得応答の対象となるプレビュー管理情報を取得する.
	PCGS_PreviewControl* ps_PreviewControl = getPreviewControlData( e_MmbImageDisplayType );
	if( ps_PreviewControl == NULL )
	{
		return;
	}

	if( uc_DirectTouchArea < ps_PreviewControl->uc_PreviewScrollLevelX )
	{
		// プレビュー画像分割表示を左にスクロールする.
		scrollPreviewLeft();
	}
	else if( uc_DirectTouchArea > ps_PreviewControl->uc_PreviewScrollLevelX )
	{
		// プレビュー画像分割表示を右にスクロールする.
		scrollPreviewRight();
	}
}
//
//概要    : PCGC_ThumbnailPreviewControl : プレビュー画像分割表示を上にスクロールする.
//［引数］	無し.
//［戻値］	Bool	:要求結果.
//作成者  :竹菴.
//レビュー:未実施.
//変更履歴:
//
void PCGC_ThumbnailPreviewControl::scrollPreviewUp()
{
	// プレビュー画像分割表示を上にスクロール可能か判定する.
	if( False == isPreviewScrollUp() )
	{
		return;
	}

	// プレビュー画像取得応答の対象となるプレビュー管理情報を取得する.
	PCGS_PreviewControl* ps_PreviewControl = getPreviewControlData( e_MmbImageDisplayType );
	if( ps_PreviewControl == NULL )
	{
		return;
	}

	// プレビュー画像のスクロール位置を変更する.
	changePreviewScrollLevel( ps_PreviewControl->uc_PreviewScrollLevelX,
	                          ( uchar )( ps_PreviewControl->uc_PreviewScrollLevelY - 1 ) );
}
