//
//概要    : PCGC_ThumbnailPreviewControl : プレビュー画像分割表示のスクロールが有効か判定する.
//［引数］	無し.
//［戻値］	Bool	True:スクロール可	False:スクロール不可.
//作成者  :竹菴.
//レビュー:未実施.
//変更履歴:
//
Bool PCGC_ThumbnailPreviewControl::isEnablePreviewScroll()
{
	// プレビュー画像取得応答の対象となるプレビュー管理情報を取得する.
	PCGS_PreviewControl* ps_PreviewControl = getPreviewControlData( e_MmbImageDisplayType );
	if( ps_PreviewControl == NULL )
	{
		return False;
	}

	if( ps_PreviewControl->e_ImageDataStatus != PCGE_ImageDataDrawingEnd )
	{
		return False;
	}

	return True;
}
//
//概要    : PCGC_ThumbnailPreviewControl : プレビュー画像分割表示を上にスクロール可能か判定する.
//［引数］	無し.
//［戻値］	Bool	True:スクロール可	False:スクロール不可.
//作成者  :竹菴.
//レビュー:未実施.
//変更履歴:
//
Bool PCGC_ThumbnailPreviewControl::isPreviewScrollUp()
{
	// プレビュー画像分割表示のスクロールが有効か判定する.
	if( False == isEnablePreviewScroll() )
	{
		return False;
	}

	// プレビュー画像取得応答の対象となるプレビュー管理情報を取得する.
	PCGS_PreviewControl* ps_PreviewControl = getPreviewControlData( e_MmbImageDisplayType );
	if( ps_PreviewControl == NULL )
	{
		return False;
	}

	// スクロール可能かどうかをチェック.
	if( ( ( uchar )0 == getScrollLevelUpDown() )
	    || ( PCGE_PreviewImageDataSizePreview1Split == ps_PreviewControl->e_PreviewImageDataSize )														// 全体表示時.
	    || ( ( PCGE_PreviewImageDataSizePreview2Split == ps_PreviewControl->e_PreviewImageDataSize ) && ( ps_PreviewControl->b_Splitdirection == True ) )	// 2分割で横長時.
	    || ( PCGE_PreviewImageDataSizePreviewRightSmall == ps_PreviewControl->e_PreviewImageDataSize ) )												// プレビュー画像サイズ右小時.
	{
		return False;
	}
	return True;
}
//
//概要    : PCGC_ThumbnailPreviewControl : プレビュー画像分割表示を下にスクロール可能か判定する.
//［引数］	無し.
