//概要    :	PCGC_ThumbnailPreviewControl	: 画像取得ステータスをSet.
//［引数］	PCGE_ImageDisplayType	e_ImageDisplayType: 画像取得ステータス.
//［戻値］	無し.
//作成者  :第一OSW 酒井健.
//レビュー:
//変更履歴:
//
void PCGC_ThumbnailPreviewControl::setImageDataStatus( PCGE_ImageDataStatus e_ImageDataStatus, uchar uc_option )
{
	if( PCGD_ThumbnailImageMaxNum <= uc_option ) {		// 範囲外チェック.
		return;
	}
	s_ThumbnailControl[uc_option].e_ImageDataStatus = e_ImageDataStatus;
}

// [MTUI]ボックスプレビューマルチページ対応.
//概要    :	PCGC_ThumbnailPreviewControl : 画像データ取得中.
Bool PCGC_ThumbnailPreviewControl::isImageDataRequesting()
{
	Bool bl_Reading = False;
	PCGS_PreviewControl* ps_PreviewControl[PCGD_PreviewImageMaxNum];
	ps_PreviewControl[0] = getPreviewControlData( PCGE_ImageDisplayTypeLeftErea );
	ps_PreviewControl[1] = getPreviewControlData( PCGE_ImageDisplayTypeDocPreview );
	ps_PreviewControl[2] = getPreviewControlData( PCGE_ImageDisplayTypewRightSmall );
	for( uchar uc_Cnt = 0; PCGD_PreviewImageMaxNum > uc_Cnt; ++uc_Cnt ) {	// プレビュー管理情報の全ての要素を確認.
		if( PCGE_ImageDataRequext == ps_PreviewControl[uc_Cnt]->e_ImageDataStatus ) {	// プレビュー画像要求中の場合.
			bl_Reading = True;
			break;
		}
	}
	return( bl_Reading );
}
#ifdef SIMULATOR		// シミュレータで有効.
//
//概要    : PCGC_ThumbnailPreviewControl : シミュレータデバッグ用画像作成関数.
//［引数］	TYPE_ImageTone e_ImageTone	: 画像種別.
//			uchar* puc_DebugImage		: 画像格納領域.
//			short ss_DstXSize			: X方向サイズ.
//			short ss_DstYSize			: Y方向サイズ.
//［戻値］	無し.
//作成者  :竹菴.
//レビュー:未実施.
//変更履歴:
//
void PCGC_ThumbnailPreviewControl::DebugThumbnailPreviewMakeImage( TYPE_ImageTone e_ImageTone, uchar* puc_DebugImage, ushort us_DstXSize, ushort us_DstYSize )
{
	if( NULL == puc_DebugImage )
	{
		PnlComPutDebugLog( True, UC_PNL_LOGPATTERN_1, "PCGC_OriginalThumbnailPreviewControl::DebugThumbnailPreviewMakeImage", UC_PNL_ERROR_PARAMETER );
		return;
	}

	uchar uc_1ColorSize = 0;
	switch( e_ImageTone )
	{
		case TYPE_ImageTone8bit:	uc_1ColorSize = 1;	break;	// 1ピクセル、8bit.
		case TYPE_ImageTone24bit:	uc_1ColorSize = 3;	break;	// 1ピクセル、24bit(点順次).
		case TYPE_ImageTone1bit:								// 1ピクセル、1bit.
		default:					return;
	}

	if( us_DstXSize == 74 )
	{
		if( 3 == uc_1ColorSize )
		{
			// 24bit(点順次) かつ 一覧表示
			memcpy( puc_DebugImage, X74Y104_256, sizeof( uchar )*( us_DstXSize*us_DstYSize*3 ) );
		}
		else if( 1 == uc_1ColorSize )
		{
			// 8bit かつ 一覧表示
			memcpy( puc_DebugImage, X74Y104_16, sizeof( uchar )*( us_DstXSize*us_DstYSize ) );
		}
	}
	else if( us_DstXSize == 141 )
	{
		if( 3 == uc_1ColorSize )
		{
			// 24bit(点順次) かつ 仕上り表示
			memcpy( puc_DebugImage, X141Y200_256, sizeof( uchar )*( us_DstXSize*us_DstYSize*3 ) );
		}
		else if( 1 == uc_1ColorSize )
		{
			// 8bit かつ 仕上り表示
			memcpy( puc_DebugImage, X141Y200_16, sizeof( uchar )*( us_DstXSize*us_DstYSize ) );
		}
	}
	else if( us_DstXSize == 198 )
	{
		if( 3 == uc_1ColorSize )
		{
			// 24bit(点順次) かつ 全体表示
			memcpy( puc_DebugImage, X198Y280_256, sizeof( uchar )*( us_DstXSize*us_DstYSize*3 ) );
		}
		else if( 1 == uc_1ColorSize )
		{
			// 8bit かつ 全体表示
			memcpy( puc_DebugImage, X198Y280_16, sizeof( uchar )*( us_DstXSize*us_DstYSize ) );
		}
	}
	else if( us_DstXSize == 280 )
	{
		if( 3 == uc_1ColorSize )
		{
			// 24bit(点順次) かつ ２倍表示
			memcpy( puc_DebugImage, X280Y396_256, sizeof( uchar )*( us_DstXSize*us_DstYSize*3 ) );
		}
		else if( 1 == uc_1ColorSize )
		{
			// 8bit(点順次) かつ ２倍表示
			memcpy( puc_DebugImage, X280Y396_16, sizeof( uchar )*( us_DstXSize*us_DstYSize ) );
		}
	}
	else if( us_DstXSize == 396 )
	{
		if( 3 == uc_1ColorSize )
		{
			// 24bit(点順次) かつ ４倍表示
			// 点順次データサイズが大きいとコンパイル不可の為、２分割データとしている
			memcpy( puc_DebugImage, X396Y560_1_256, sizeof( uchar )*( us_DstXSize*us_DstYSize*3/2 ) );
			memcpy( &puc_DebugImage[us_DstXSize*us_DstYSize*3/2], X396Y560_2_256, sizeof( uchar )*( us_DstXSize*us_DstYSize*3/2 ) );
		}
		else if( 1 == uc_1ColorSize )
		{
			// 8bit(点順次) かつ ４倍表示
			memcpy( puc_DebugImage, X396Y560_16, sizeof( uchar )*( us_DstXSize*us_DstYSize ) );
		}
	}
	else if( us_DstXSize == 560 )
	{
		if( 3 == uc_1ColorSize )
		{
			// 24bit(点順次) かつ ８倍表示
			// 点順次データサイズが大きいとコンパイル不可の為、４分割データとしている
			memcpy( puc_DebugImage, X560Y792_1_256, sizeof( uchar )*( us_DstXSize*us_DstYSize*3/2 ) );
			memcpy( &puc_DebugImage[us_DstXSize*us_DstYSize*3/4], X560Y792_2_256, sizeof( uchar )*( us_DstXSize*us_DstYSize*3/2 ) );
			memcpy( &puc_DebugImage[( us_DstXSize*us_DstYSize*3/4 )*2], X560Y792_3_256, sizeof( uchar )*( us_DstXSize*us_DstYSize*3/2 ) );
			memcpy( &puc_DebugImage[( us_DstXSize*us_DstYSize*3/4 )*3], X560Y792_4_256, sizeof( uchar )*( us_DstXSize*us_DstYSize*3/2 ) );
		}
		else if( 1 == uc_1ColorSize )
		{
			// 8bit(点順次) かつ ８倍表示
			memcpy( puc_DebugImage, X560Y792_16, sizeof( uchar )*( us_DstXSize*us_DstYSize ) );
		}
	}
	else
	{
		for( ushort i = 0; us_DstYSize > i; ++i )
		{
			for( ushort j = 0; us_DstXSize > j; ++j )
			{
				uchar uc_Color = 0;
				if( 0 == ( ( ( j + i ) / 255 ) % 2 ) )	{ uc_Color = ( ( j + i ) % 255 );			}
				else						{ uc_Color = ( 255 - ( ( j + i ) % 255 ) ); }

				if( 1 == uc_1ColorSize )
				{
					puc_DebugImage[( us_DstXSize * uc_1ColorSize * i ) + j] = uc_Color;
				}
				else
				{
					puc_DebugImage[( us_DstXSize * uc_1ColorSize * i ) + ( j * 3 )] = uc_Color;
					puc_DebugImage[( us_DstXSize * uc_1ColorSize * i ) + ( j * 3 ) + 1] = uc_Color;
					puc_DebugImage[( us_DstXSize * uc_1ColorSize * i ) + ( j * 3 ) + 2] = uc_Color;
				}
			}
		}
	}
}
#endif // #ifdef SIMULATOR.

//概要    :	PCGC_ThumbnailPreviewControl	: プレビュー画像データ取得応答.
//［引数］	uint32_t				ul_AcceptNum		: 1画像要求毎に割り振られるシリアルナンバー .
//			TYPE_PreviewResult		e_Result			: 要求画像取得結果 .
//			TYPS_ActualPreviewPara	s_ActualPreviewPara	: プレビュー画像結果パラメータ .
//［戻値］	無し.
//変更履歴:
//
void PCGC_ThumbnailPreviewControl::ans_OCRData(
    uint32_t ul_AcceptNum,
    TYPE_PreviewResult e_Result,
    TYPS_ActualPreviewPara st_ActualPreviewPara )
{
	// プレビュー管理情報を取得する.
	PCGS_PreviewControl* ps_PreviewControl = getPreviewControlData( PCGE_ImageDisplayTypeDocPreview );
	if( NULL == ps_PreviewControl )
	{
		PnlComPutDebugLog( True, UC_PNL_LOGPATTERN_1, "PCGC_OCRDocNameConfirm_act::showPreviewImage", UC_PNL_ERROR_PARAMETER );
		return;
	}

	if( ul_AcceptNum != ps_PreviewControl->ul_reqSerialNo )
	{
		return;
	}

	if( TYPE_PreviewResult_OK != e_Result )
	{
		// プリント停止警告発生時.
		if( TYPE_PreviewResult_PrintError == e_Result )
		{
			ps_PreviewControl->e_ImageDataStatus = PCGE_ImageDataPrintStop;
			ps_PreviewControl->b_Splitdirection = False;
			ps_PreviewControl->e_getImageTone = st_ActualPreviewPara.e_ImageTone;
			ps_PreviewControl->ss_getImageXSize = st_ActualPreviewPara.ss_ImageDotSizeWidth;
			ps_PreviewControl->ss_getImageYSize = st_ActualPreviewPara.ss_ImageDotSizeHight;
			ps_PreviewControl->ss_getBGXSize = st_ActualPreviewPara.ss_BGImageDotSizeWidth;
			ps_PreviewControl->ss_getBGYSize = st_ActualPreviewPara.ss_BGImageDotSizeHight;
			ps_PreviewControl->ss_getImageShiftSizeX = st_ActualPreviewPara.ss_MarginDotSizeWidth;
			ps_PreviewControl->ss_getImageShiftSizeY = st_ActualPreviewPara.ss_MarginDotSizeHight;
			ps_PreviewControl->ss_getOverlayShiftSizeX = st_ActualPreviewPara.ss_BGImageStartPointX;
			ps_PreviewControl->ss_getOverlayShiftSizeY = st_ActualPreviewPara.ss_BGImageStartPointY;
			ps_PreviewControl->b_ReqPreviewImage = True;

			// コールバックイベントを発生させる.
			pc_PanelMain->PreviewCallBackIndi( ( int32_t )PCGE_ImageDisplayTypeDocPreview );
			return;
		}
		// メモリオーバー発生時.
		if( TYPE_PreviewResult_MemoryOver == e_Result )
		{
			ps_PreviewControl->e_ImageDataStatus = PCGE_ImageDataMemoryError;
			ps_PreviewControl->b_Splitdirection = False;
			ps_PreviewControl->e_getImageTone = st_ActualPreviewPara.e_ImageTone;
			ps_PreviewControl->ss_getImageXSize = st_ActualPreviewPara.ss_ImageDotSizeWidth;
			ps_PreviewControl->ss_getImageYSize = st_ActualPreviewPara.ss_ImageDotSizeHight;
			ps_PreviewControl->ss_getBGXSize = st_ActualPreviewPara.ss_BGImageDotSizeWidth;
			ps_PreviewControl->ss_getBGYSize = st_ActualPreviewPara.ss_BGImageDotSizeHight;
			ps_PreviewControl->ss_getImageShiftSizeX = st_ActualPreviewPara.ss_MarginDotSizeWidth;
			ps_PreviewControl->ss_getImageShiftSizeY = st_ActualPreviewPara.ss_MarginDotSizeHight;
			ps_PreviewControl->ss_getOverlayShiftSizeX = st_ActualPreviewPara.ss_BGImageStartPointX;
			ps_PreviewControl->ss_getOverlayShiftSizeY = st_ActualPreviewPara.ss_BGImageStartPointY;
			ps_PreviewControl->b_ReqPreviewImage = True;

			// コールバックイベントを発生させる.
			pc_PanelMain->PreviewCallBackIndi( ( int32_t )PCGE_ImageDisplayTypeDocPreview );
			return;
		}
		// キャンセル応答時以外.
		if( TYPE_PreviewResult_Cancel != e_Result )
		{
			// リクエスト失敗時はエラーを設定し、再取得しないようにする.
			ps_PreviewControl->e_ImageDataStatus = PCGE_ImageDataReqError;
		}
		return;
	}

	if( NULL == st_ActualPreviewPara.psc_ImageDataPointer )
	{
		// 画像ポインタがNULLの場合は画像無し.
		ps_PreviewControl->e_ImageDataStatus = PCGE_ImageDataReqError;
		return;
	}

	const Bool b_Splitdirection = ( ( st_ActualPreviewPara.ss_ImageDotSizeWidth > st_ActualPreviewPara.ss_ImageDotSizeHight ) ? True : False );

	if( ( PCGD_PreviewDotImageSize < st_ActualPreviewPara.ss_ImageDotSizeWidth )
	    || ( PCGD_PreviewDotImageSize < st_ActualPreviewPara.ss_ImageDotSizeHight )
	    || ( ( PCGD_PreviewImageSize - 6 ) < st_ActualPreviewPara.ul_TotalDataSize ) )
	{
		ps_PreviewControl->e_ImageDataStatus = PCGE_ImageDataNonComplete;
		return;
	}

	ps_PreviewControl->e_ImageDataStatus = PCGE_ImageDataComplete;
	ps_PreviewControl->b_Splitdirection = b_Splitdirection;
	ps_PreviewControl->e_getImageTone = st_ActualPreviewPara.e_ImageTone;
	ps_PreviewControl->ss_getImageXSize = st_ActualPreviewPara.ss_ImageDotSizeWidth;
	ps_PreviewControl->ss_getImageYSize = st_ActualPreviewPara.ss_ImageDotSizeHight;
	ps_PreviewControl->ss_getBGXSize = st_ActualPreviewPara.ss_BGImageDotSizeWidth;
	ps_PreviewControl->ss_getBGYSize = st_ActualPreviewPara.ss_BGImageDotSizeHight;
	ps_PreviewControl->ss_getImageShiftSizeX = st_ActualPreviewPara.ss_MarginDotSizeWidth;
	ps_PreviewControl->ss_getImageShiftSizeY = st_ActualPreviewPara.ss_MarginDotSizeHight;
	ps_PreviewControl->ss_getOverlayShiftSizeX = st_ActualPreviewPara.ss_BGImageStartPointX;
	ps_PreviewControl->ss_getOverlayShiftSizeY = st_ActualPreviewPara.ss_BGImageStartPointY;
	ps_PreviewControl->b_ReqPreviewImage = True;
	ps_PreviewControl->e_GetImageDir = st_ActualPreviewPara.e_ImageDir;

	// コールバックイベントを発生させる.
	pc_PanelMain->PreviewCallBackIndi( ( int32_t )PCGE_ImageDisplayTypeDocPreview );
}

//概要    :画像表示ヘッダー設定.
//［引数］	char*					psc_ImageData		: データ設定ポインタ.
//			TYPE_ImageTone			e_ImageTone			: 画像種別.
//			short					ss_ImageDotSizeX	: 画像サイズX.
//			short					ss_ImageDotSizeY	: 画像サイズY.
void PCGC_ThumbnailPreviewControl::createHeaderDataOCR(
    char* psc_ImageData,
    TYPE_ImageTone e_ImageTone,
    short ss_ImageDotSizeX,
    short ss_ImageDotSizeY )
{
	char sc_HeaderBuf[5];
	memset( sc_HeaderBuf, 0 , sizeof(sc_HeaderBuf) );
	// Xサイズ格納.
	sc_HeaderBuf[0] = ( char )( ss_ImageDotSizeX >> 8 );
	sc_HeaderBuf[1] = (char)( ss_ImageDotSizeX & 0xff );
	// Yサイズ格納.
	sc_HeaderBuf[2] = ( char )( ss_ImageDotSizeY >> 8 );
	sc_HeaderBuf[3] = (char)( ss_ImageDotSizeY & 0xff );
	switch( e_ImageTone ) {
		case TYPE_ImageTone1bit:	sc_HeaderBuf[4] = UC_GPARTS_COLORNUMBER_MONO;		break;	// 1ピクセル、1bit.
		case TYPE_ImageTone8bit:	sc_HeaderBuf[4] = UC_GPARTS_COLORNUMBER_256COLOR;	break;	// 1ピクセル、8bit.
		case TYPE_ImageTone24bit:	sc_HeaderBuf[4] = UC_GPARTS_COLORNUMBER_FULLCOLOR;	break;	// 1ピクセル、24bit(点順次).
		default:	PnlComPutDebugLog( True, UC_PNL_LOGPATTERN_1, "PCGC_OCRDocNameConfirm_act::createHeaderDataOCR", UC_PNL_ERROR_PARAMETER );	break;
	}
	memcpy( psc_ImageData, sc_HeaderBuf, sizeof( sc_HeaderBuf ) );
}

