PNLC_FaxRxDataGuardLib* PNLC_FaxRxDataGuardLib::newInstance()
{
	static PNLC_FaxRxDataGuardLib gcPNLC_FaxRxDataGuardLib;
	return &gcPNLC_FaxRxDataGuardLib;
}

//==================================================================================================
// 概要     : ファクス受信データ削除用パスワードが必要かの判別関数.
// 引数     : 削除対象ジョブ.
// 戻り値   : True:ファクス受信データ削除用パスワードが必要.
//          : False:ファクス受信データ削除用パスワードが不要.
// 備考     : なし.
//==================================================================================================
Bool PNLC_FaxRxDataGuardLib::isReqFaxRXDataPass( TYPC_JobSpec* cp_Spec )
{
	if( NULL == cp_Spec ) {	//JobSpecがNULLの場合パスワード必要と判定.
		return True;
	}

	TYPE_JobType e_JobType = cp_Spec->pc_Common->c_JobType.getJobType();

	//ファクス受信/印刷ジョブの判定
	if( TYPE_JobTypeFaxReceive == e_JobType  					//ＦＡＸ受信プリント.
	    || TYPE_JobTypeIfaxReceive == e_JobType 				//ＩＦａｘ受信.
	    || TYPE_JobTypeFaxReceiveTimer == e_JobType 			//ＦＡＸ（タイマーポーリング受信）.
	    || TYPE_JobTypeFaxReceivePolling == e_JobType 			//ＦＡＸ（ポーリング受信）.
	    || DOCD_CompulsionRcvBox == cp_Spec->pc_Common->c_JobType.getBoxNo() ) 		//強制メモリBOXからの印刷.
	{
		if( TYPE_FaxRxDataGuardPassword == PnlComGetFaxPanelSetting()->getFaxRxDataGuard( NULL ) )	//ファクス受信データ削除保護設定種別が「する / パスワード」.
		{
			if( NULL == PnlComGetUser() ) {
				return True;
			} else if( TYPE_UserTypeAdmin != PnlComGetUser()->getUserType() ) {						//ログインユーザーが管理者以外.
				return True;
			}
		}
	}

	return False;
}

//==================================================================================================
// 概要     : ファクスジョブ削除保護設定による削除権限がないかの判別関数.
// 引数     : 削除対象ジョブ.
// 戻り値   : True:削除権限ない.
//          : False:削除権限ある.
// 備考     : なし.
//==================================================================================================
Bool PNLC_FaxRxDataGuardLib::isFaxRxDataDeleteImpossible( TYPC_JobSpec* cp_Spec )
{
	if( NULL == cp_Spec ) {	//JobSpecがNULLの場合削除権限無しと判定.
		return True;
	}

	TYPE_JobType e_JobType = cp_Spec->pc_Common->c_JobType.getJobType();

	if( TYPE_JobTypeFaxReceive == e_JobType					//ＦＡＸ受信プリント.
	    || TYPE_JobTypeIfaxReceive == e_JobType				//ＩＦａｘ受信.
	    || TYPE_JobTypeFaxReceiveTimer == e_JobType			//ＦＡＸ（タイマーポーリング受信）.
	    || TYPE_JobTypeFaxReceivePolling == e_JobType		//ＦＡＸ（ポーリング受信）.
	    || DOCD_CompulsionRcvBox == cp_Spec->pc_Common->c_JobType.getBoxNo() )			//強制メモリBOXからの印刷.
	{
		if( TYPE_FaxRxDataGuardBoxAdmin == PnlComGetFaxPanelSetting()->getFaxRxDataGuard( NULL ) ) {	//ファクス受信データ削除保護設定種別が「する / BOX管理者で削除」.
			if( NULL == PnlComGetUser() ) {
				return True;
			} else if( TYPE_UserTypeUser == PnlComGetUser()->getUserType() || TYPE_UserTypePublicUser == PnlComGetUser()->getUserType() ) {	//ログインユーザーが一般ユーザーまたはパブリックユーザー.
				return True;
			}
		}
	}

	return False;
}
// リモートパネル文字入力管理クラス コンストラクタ.
PNLC_RMPStrInputMng::PNLC_RMPStrInputMng() {
	// クラス変数の初期化.
	bl_isNowKbd = False;
	bl_is2BytesChar = False;
	bl_is3BytesChar = False;

	psc_StrBuf = NULL;
	us_MaxStrSize = 0;
	us_MaxStrByte = 0;

	e_LengthCheck = TYPE_InsertCharLenByte;
	pc_SlideTextMgr = NULL;
	pc_KeybordComponent = NULL;
	pc_ConvertKeybord = NULL;

	pc_ConvertKeybordEnl = NULL;
	pc_SelectTextMgr = NULL;
	sc_MaxRange = 0;
	bl_InputRefuse = False;
}
PCGC_SlideTextMgr _c_SlideTextMgr;			// スライド文字列管理クラス.
// リモートパネル文字入力管理クラス 受付可能文字列判定関数.
Bool PNLC_RMPStrInputMng::isUsableStr( char* psc_Str, ushort us_Size ) {
	if( NULL == psc_Str ) {
		LOGF_debug_PutEventLog( LOGF_DEBUG_EVENT_KIND_ALL, 0, LOGD_DEBUG_LEVEL_UNKNOWN, "Assert Failed!" );
		return False;
	}
	if( us_Size > us_MaxStrSize ) {		// 文字数の確認.
		if( TYPE_InsertCharLenUTF8 == e_LengthCheck					// UTF8変換後のbyte数.
		    || TYPE_InsertCharLenByte == e_LengthCheck				// パネル言語でのbyte数.
		    || TYPE_InsertCharLenByteAndUTF8 == e_LengthCheck ) {	// パネル言語でのbyte数とUTF8変換後のbyte数.
			return False;
		}
	}
	if( us_Size > us_MaxStrByte ) {		// バイト数の確認.
		if( TYPE_InsertCharLenStrUTF8AndByteUTF8 == e_LengthCheck		// 文字数とbyte数でチェック.
		    || ( TYPE_InsertCharLen_Full2_Half1 == e_LengthCheck 		// 半角は1文字、全角は2文字として入力制限する.
		         && 0 < us_MaxStrByte ) ) {								// 文字数とバイト数でチェックする場合もある.
			return False;
		}
	}
	ushort us_StrNum = 0;		//実際の文字数.
	while( '\0' != *psc_Str ) {
		uchar uc_charByte = 0;		// 一文字あたりのバイト数.
		uc_charByte = LIBF_getUTF8ByteCount( ( const char* )psc_Str );		// バイト数取得.

		if( 0 == uc_charByte ) {
			return False;
		} else if( 1 == uc_charByte ) {		// 1バイト文字の場合.
			if( 0x1f >= *psc_Str ) {		// 制御コードの場合.
				return False;
			} else if( ( NULL != pc_ConvertKeybord && True == pc_ConvertKeybord->isDisableKeyCharCode( psc_Str ) )
			           || ( NULL != pc_ConvertKeybordEnl && True == pc_ConvertKeybordEnl->isDisableKeyCharCode( psc_Str ) ) ) {	// 入力禁止文字.
				return False;
			}
		} else if( 2 == uc_charByte ) {		// 2バイト文字の場合.
			if( False == bl_is2BytesChar ) {			// 2バイト文字使用不可.
				return False;
			}
		} else if( 3 == uc_charByte ) {		// 3バイト文字の場合.
			// ユーロ記号の場合は、2バイト文字使用不可の場合、Falseを返す.
			if( ( 0xE2 == ( uchar )( *psc_Str ) ) && ( 0x82 == ( uchar )( *( psc_Str+1 ) ) ) && ( 0xAC == ( uchar )( *( psc_Str+2 ) ) ) ) {
				if( False == bl_is2BytesChar ) {	// 2バイト文字使用不可.
					return False;
				}
			} else if( False == bl_is3BytesChar ) {		// 3バイト文字使用不可.
				return False;
			}
		}	// 以下、4バイト文字以上の対応が必要ならば追加すること.

		// 一文字あたりのバイト数分のサイズを持っているか?.
		char sc_Str[7];
		memset( sc_Str, '\0', sizeof( sc_Str ) );
		memcpy( sc_Str, psc_Str, uc_charByte );		// psc_StrよりUTF-8 1文字分取り出す.
		if( uc_charByte != strlen( sc_Str ) ) {
			return False;
		}
		if( TYPE_InsertCharLen_Full2_Half1 == e_LengthCheck ) {	// 半角は1文字、全角は2文字として入力制限する.
			if( NULL != pc_SlideTextMgr ) {
				us_StrNum = (ushort)( us_StrNum + pc_SlideTextMgr->cntCharLenFull2_Half1( sc_Str ) );
			} else if( NULL != pc_SelectTextMgr ) {
				us_StrNum = (ushort)( us_StrNum + pc_SelectTextMgr->cntCharLenFull2_Half1( sc_Str ) );
			}
		} else {
			us_StrNum++;
		}
		if( us_StrNum > us_MaxStrSize ) {
			return False;
		}
		psc_Str += uc_charByte;		// 次のUTF-8先頭文字へ移動.
	}
	return True;
}
// リモートパネル文字入力管理クラス キーボード画面フラグ取得.
Bool PNLC_RMPStrInputMng::getNowKbd() {
	return bl_isNowKbd;
}
// リモートパネル文字入力管理クラス クラスインスタンス取得.
PNLC_RMPStrInputMng* PNLC_RMPStrInputMng::newInstance() {
	static PNLC_RMPStrInputMng c_RMPStrInputMng;
	return &c_RMPStrInputMng;
}
// リモートパネル文字入力管理クラス 文字列更新処理.
void PNLC_RMPStrInputMng::StrToKbd() {
	if( False == checkKeyBoadFromParts() ) {	// キーボード画面ではない.
		return;
	}
	char sc_InputStrFromRMP[PNLD_RMPStrInputMaxByte+1];	// リモートパネルからの文字列.
	char sc_InputStr[PNLD_RMPStrInputMaxByte+1];		// 入力文字列(512+1バイト).
	memset( sc_InputStrFromRMP, '\0', sizeof( sc_InputStrFromRMP ) );
	memset( sc_InputStr, '\0', sizeof( sc_InputStr ) );
	RMP_WebDAVClient::newInstance()->getTxt( sc_InputStrFromRMP );
	if( NULL != sc_InputStrFromRMP ) {
		memcpy( sc_InputStr, sc_InputStrFromRMP ,PNLD_RMPStrInputMaxByte );
		if( True == isUsableStr( sc_InputStr, ( ushort )strlen( sc_InputStr ) ) ) {
			// 未変換文字列を消去する.キーボードコンポーネントの場合もここで処理を行う.
			if( NULL != pc_ConvertKeybord
			    && '\0' != pc_ConvertKeybord->c_PreString[0] ) {				// キーボードクラス.
				pc_ConvertKeybord->clearPreString();
			} else if( NULL != pc_ConvertKeybordEnl
			           && '\0' != pc_ConvertKeybordEnl->c_PreString[0] ) {		// キーボードクラス.
				pc_ConvertKeybordEnl->c_PreString[0] = '\0';
			}
			if( NULL != pc_KeybordComponent ) {		// キーボードコンポーネント.
				pc_KeybordComponent->updateTextBuf( sc_InputStr );
			} else if( NULL != pc_SlideTextMgr && NULL != psc_StrBuf ) {	//スライド文字列(PCGC_SlideTextMgr).
				pc_SlideTextMgr->updateTextBuf( psc_StrBuf, sc_InputStr, sc_MaxRange );
			} else if( NULL != pc_SelectTextMgr && NULL != psc_StrBuf ) {	//スライド文字列(PCGC_SelectTextMgr).
				pc_SelectTextMgr->updateTextBuf( psc_StrBuf, sc_InputStr, sc_MaxRange );
			} else {
				// 何もしない.
			}
		} else {
			// 何もしない.
		}
	}	// 文字列取得失敗または文字列が存在しない場合は、何もしない.
}
// リモートパネル文字入力管理クラス キーボード情報取得関数.
// キーボード画面の情報取得およびキーボード画面かどうかを返す.
// チェック処理が含まれるので必要の無い場合はgetNowKbd()を使うこと.
void PNLC_RMPStrInputMng::collectKeyBoadInfo() {
	// パーツ判定処理.
	if( False == checkKeyBoadFromParts() ) {		// キーボード表示中でない.
		return;
	}
	// キーボードクラスによる使用可能言語チェックは共通なので先に評価する.
	bl_is2BytesChar = False;				// 2Byte文字？(5カ国可能か？).
	bl_is3BytesChar = False;				// 3Byte文字？(9カ国可能か？).
	if( NULL != pc_ConvertKeybord && NULL == pc_KeybordComponent ) {		// キーボードクラス.
		if( True == pc_ConvertKeybord->b_Keybord5Country ) {
			bl_is2BytesChar = True;
			bl_is3BytesChar = False;
		} else if( True == pc_ConvertKeybord->b_Keybord9Country ) {
			bl_is2BytesChar = True;
			bl_is3BytesChar = True;
		} else {
			// 上記以外でも9ヶ国語パーツが表示中の場合は9ヶ国語言語入力可能.
			if( True == Grp_Keybordcom9Country.isNowShown() ) {
				bl_is2BytesChar = True;
				bl_is3BytesChar = True;
			}
		}
	} else if( NULL != pc_ConvertKeybordEnl && NULL == pc_KeybordComponent ) {	// キーボードクラス(拡大).
		if( True == pc_ConvertKeybordEnl->getKeybord5CountryEnl() ) {
			bl_is2BytesChar = True;
			bl_is3BytesChar = False;
		} else if( True == pc_ConvertKeybordEnl->getKeybord9CountryEnl() ) {
			bl_is2BytesChar = True;
			bl_is3BytesChar = True;
		} else {
			// 上記以外でも9ヶ国語パーツが表示中の場合は9ヶ国語言語入力可能.
			if( True == Grp_Keybordcom9Country.isNowShown() ) {
				bl_is2BytesChar = True;
				bl_is3BytesChar = True;
			}
		}
	}
	if( NULL != pc_KeybordComponent ) {		// キーボードコンポーネントが有効.
		PNLE_KeyboadTypeCom ec_KeybordBasicType = PNLD_KBTC_Nomal;		// キーボードコンポーネント種別.

		if( True == pc_KeybordComponent->isSelectInputLine2() ) {		// 2行目選択時.
			PNLS_InputNumKeyboard* ps_InputNumKeyboard = pc_KeybordComponent->getInputNumKeyboard();
			if( NULL == ps_InputNumKeyboard ) {
				LOGF_debug_PutEventLog( LOGF_DEBUG_EVENT_KIND_ALL, 0, LOGD_DEBUG_LEVEL_UNKNOWN, "Assert Failed!" );
				return;
			}
			us_MaxStrSize = ( ushort )ps_InputNumKeyboard->ul_maxLen;			// 文字サイズ.
			ec_KeybordBasicType = ps_InputNumKeyboard->ec_KeybordBasicType;		// キーボードコンポーネント種別.
		} else {
			us_MaxStrSize = ( ushort )pc_KeybordComponent->getmaxLen();
			ec_KeybordBasicType = pc_KeybordComponent->getKeybordBasicType();
		}
		us_MaxStrByte = pc_KeybordComponent->getSubMaxInputSizeUTF8();						// 制限バイト数(文字数と同時チェック用）.

		// キーボードコンポーネントでは使用可能言語をキーボードクラスで行っていないので別途状態を取得する.
		if( PNLD_KBTC_5Country == ec_KeybordBasicType ) {
			bl_is2BytesChar = True;
			bl_is3BytesChar = False;
		} else if( PNLD_KBTC_9Country == ec_KeybordBasicType ) {
			bl_is2BytesChar = True;
			bl_is3BytesChar = True;
		} else {// ☆追加.
			// 上記以外でも9ヶ国語パーツが表示中の場合は9ヶ国語言語入力可能.
			if( True == Grp_Keybordcom9Country_COM.isNowShown() ) {
				bl_is2BytesChar = True;
				bl_is3BytesChar = True;
			}
		}

		e_LengthCheck = pc_KeybordComponent->getInsertCharLenCheck();						// 文字列長判定方法.

		// PNLC_RMPStrInputMng::StrToKbd()で使用するためpc_SlideTextMgr,pc_ConvertKeybordを代入しておく.
		pc_SlideTextMgr = &_c_SlideTextMgr;		//スライド文字列管理クラスオブジェクト(ローカル).
		pc_ConvertKeybord = &Kbd_ComKeybordConv;
	} else if( NULL != pc_SlideTextMgr ) {
		us_MaxStrSize = pc_SlideTextMgr->getMaxInputSize();
		us_MaxStrByte = pc_SlideTextMgr->getMmbSubMaxInputSizeUTF8();
		e_LengthCheck = pc_SlideTextMgr->getInsertCharLenCheck();
	} else if( NULL != pc_SelectTextMgr ) {
		us_MaxStrSize = pc_SelectTextMgr->getMaxInputSize();
		us_MaxStrByte = pc_SelectTextMgr->getMmbSubMaxInputSizeUTF8();
		e_LengthCheck = pc_SelectTextMgr->getInsertCharLenCheck();
	}
}
// リモートパネル文字入力管理クラス　スライド文字列関連情報取得処理(PCGC_SlideTextMgr用).
// 引数 char* psc_Buffer:入力文字列バッファ char _sc_MaxRange:1行あたりの文字数 PCGC_SlideTextMgr* pc_STMgr:スライド文字列管理クラスオブジェクト.
void PNLC_RMPStrInputMng::setKeyBoadDataFromSlideTextMgr( char* psc_Buffer, char _sc_MaxRange, PCGC_SlideTextMgr* pc_STMgr ) {
	if( NULL == psc_Buffer || NULL == pc_STMgr ) {
		LOGF_debug_PutEventLog( LOGF_DEBUG_EVENT_KIND_ALL, 0, LOGD_DEBUG_LEVEL_UNKNOWN, "Assert Failed!" );
		return;
	}
	psc_StrBuf = psc_Buffer;
	sc_MaxRange = _sc_MaxRange;

	pc_SlideTextMgr = pc_STMgr;
	pc_SelectTextMgr = NULL;
	pc_KeybordComponent = NULL;
}
