// リモートパネル文字入力管理クラス　キーボード画面判別処理.
// 戻り値:True キーボード画面、False キーボード画面以外.
//				ZeusCD以降は、LCDの状態変更をRMPへ通知しない.
Bool PNLC_RMPStrInputMng::checkKeyBoadFromParts()
{
	static Bool bl_isNowKbdBk = False;	// キーボード表示中かどうかの前回値.
	bl_isNowKbd = False;

	RMP_WebDAVClient* pc_Client = RMP_WebDAVClient::newInstance();
	if( NULL == pc_Client || NULL == pc_PanelManager ) {
		PnlComPutDebugLog( False, UC_PNL_LOGPATTERN_1, "PNLC_RMPStrInputMng::checkKeyBoadFromParts", UC_PNL_ERROR_IMPOSSIBLE );
		bl_isNowKbd = False;
		return ( False );
	}

	if( True == bl_InputRefuse ) {
		// 受付拒否中はFalseを返す.
		bl_isNowKbd = False;
		return False;
	}

	PM_TaskID	e_TaskId = PM_TASKID_PANEL;
	if( 0 == pc_PanelManager->getPriority( &e_TaskId ) ) {
		bl_isNowKbd = False;
		return ( False );
	}

	if( PM_TASKID_BRWPNL == e_TaskId ) {
		BRWC_BasicMessageProc* pc_BrwGamen = NULL;
		if( True == BRWC_PopupListControl::newInstance()->isPopupOpen() ) {
			pc_BrwGamen = BRWC_PopupListControl::newInstance()->getNowPopup();
		} else {
			pc_BrwGamen = BRWC_BasicMessageProc::getNowGamen();
		}
		if( NULL != pc_BrwGamen ) {
			PDisplayParts** pc_PartsTable = pc_BrwGamen->getPartsTable();
			short ss_PartsNumber = pc_BrwGamen->getPartsNumber();
			for( short ss_PartsIndex = 0; ss_PartsNumber > ss_PartsIndex; ++ss_PartsIndex ) {
				PKeybordComponent* pc_TargetComponent = dynamic_cast<PKeybordComponent*>( pc_PartsTable[ss_PartsIndex] );
				if( NULL != pc_TargetComponent ) {
					pc_KeybordComponent = pc_TargetComponent;
					bl_isNowKbd = True;
					break;
				}
			}
		}
	} else {
		PNLC_PopupListControl* pc_PopupListControl = PNLC_PopupListControl::newInstance();
		if( NULL == pc_PopupListControl ) {
			LOGF_debug_PutEventLog( LOGF_DEBUG_EVENT_KIND_ALL, 0, LOGD_DEBUG_LEVEL_UNKNOWN, "Assert Failed!" );
			bl_isNowKbd = False;
			return False;
		}
		PLayerControl* pc_NowPopup = pc_PopupListControl->getNowPopup();
		PBaseGamenCom* pc_BaseGamen = dynamic_cast< PBaseGamenCom* >( PBasicMessageProc::nowGamen );
		if( NULL != pc_NowPopup ) {	// ポップアップ画面表示中.
			PDisplayParts** pc_partsTable = pc_NowPopup->getPartsTable();
			short ss_partsNumber          = pc_NowPopup->getPartsNumber();
			for( short i=0; i < ss_partsNumber; i++ ) {
				PKeybordComponent* pc_KbdComp = dynamic_cast<PKeybordComponent*>( pc_partsTable[i] );
				if( NULL != pc_KbdComp ) {		// PKeybordComponentクラスの場合.
					pc_KeybordComponent = pc_KbdComp;
					bl_isNowKbd = True;
					break;
				}
			}
		} else if( NULL != pc_BaseGamen ) {	// 新UIベース画面.
			PDisplayParts** pc_partsTable = pc_BaseGamen->getPartsTable();
			short ss_partsNumber          = pc_BaseGamen->getPartsNumber();
			for( short i=0; i < ss_partsNumber; i++ ) {
				PKeybordComponent* pc_KbdComp = dynamic_cast<PKeybordComponent*>( pc_partsTable[i] );
				if( NULL != pc_KbdComp ) {		// PKeybordComponentクラスの場合.
					pc_KeybordComponent = pc_KbdComp;
					bl_isNowKbd = True;
					break;
				}
			}
		} else {
			PBasicMessageProc* pc_Gamen = PBasicMessageProc::nowGamen;
			if( NULL != pc_Gamen ) {
				PDisplayParts** partsTable2 = pc_Gamen->getPartsTable();
				short ss_partsNumber = pc_Gamen->getPartsNumber();
				// 画面パーツテーブルのパーツ（キーボードパーツを含むもの）を探し、表示されているかを判断する.
				for( short ss_i = 0; ss_i < ss_partsNumber; ss_i++ ) {
					if( True == partsTable2[ss_i]->checkParts( &Grp_Keybord )
					    || True == partsTable2[ss_i]->checkParts( &Grp_EnlKeybord ) ) {
						if( True == partsTable2[ss_i]->isNowShown() ) {
							bl_isNowKbd = True;
							break;
						}
					}
				}
			}
		}
	}

	// パーツ判定処理.
	if( bl_isNowKbdBk != bl_isNowKbd ) {	// 状態が変化した.
		if( True == bl_isNowKbd ) {
			if( True == PLBC_FuncVersionCheck::isOK_MiZe_Type5() ) {
				// QtLibへテキスト入力できることを通知する.
				PNLC_RMPQtConnector::newInstance()->textInputEnabled( True );
			} else {
				pc_Client->InfoStatusChanged( RMP_TXT_CHANGED );	// LCD状態変化あり(テキスト入力可).
			}
		} else {
			if( True == PLBC_FuncVersionCheck::isOK_MiZe_Type5() ) {
				// QtLibへテキスト入力できないことを通知する.
				PNLC_RMPQtConnector::newInstance()->textInputEnabled( False );
			} else {
				pc_Client->InfoStatusChanged( RMP_LCD_CHANGED );	// LCD状態変化あり(テキスト入力不可).
			}
		}
		bl_isNowKbdBk = bl_isNowKbd;
	}

	return bl_isNowKbd;
}
