// -----------------------------------------------------------------------------------------------
// クラス	：PNLC_RMPStrInputMng.
// 関数名	：setStringToSeparateBuffer.
// 引数		：char   *psc_Buff		バッファ.
//			：ushort us_MaxLen		(ハイフンを無視した)最大文字列長.
//			：uchar  uc_BlockNum	ブロック数.
//			：uchar  uc_BlockLen	ブロック内文字数.
// 戻り値	：なし.
// 備考		：入力文字列長が大きい場合、文字種が不正の場合は入力しない.
// 作成者	：OPS1 棚.
// -----------------------------------------------------------------------------------------------
void PNLC_RMPStrInputMng::setStringToSeparateBuffer( char* psc_Buff, ushort us_MaxLen, uchar uc_BlockNum, uchar uc_BlockLen )
{
	if( NULL == psc_Buff ) {
		LOGF_debug_PutEventLog( LOGF_DEBUG_EVENT_KIND_ALL, 0, LOGD_DEBUG_LEVEL_UNKNOWN, "Assert Failed!" );
		return;
	}

	// 引数サイズチェック.
	if( us_MaxLen < uc_BlockNum * uc_BlockLen ) {
		LOGF_debug_PutEventLog( LOGF_DEBUG_EVENT_KIND_ALL, 0, LOGD_DEBUG_LEVEL_UNKNOWN, "Assert Failed!" );
		return;
	}

	char sc_InputStrFromRMP[PNLD_RMPStrInputMaxByte+1];	// リモートパネルからの文字列.
	memset( sc_InputStrFromRMP, '\0', sizeof( sc_InputStrFromRMP ) );

	RMP_WebDAVClient::newInstance()->getTxt( sc_InputStrFromRMP );

	ushort us_Len = (ushort)strlen( sc_InputStrFromRMP );

	if( us_MaxLen >= us_Len ) {
		if( True == isUsableLicenseCode( sc_InputStrFromRMP ) ) {
			// 文字列長、文字種チェックが正常なので、バッファを初期化してから入力文字列を格納する.
			for( ushort us_cnt = 0; us_cnt < uc_BlockNum; us_cnt++ ) {
				// ブロックには、uc_BlockLenで指示される文字数分の文字が入り、終端が存在することを前提とする.
				// ブロックの領域が実際に入る文字数＋終端のサイズより大きい場合は、別途対応すること.
				// ※ PServiceLicenseManagementCodeInputCom では、.
				// 		現状ライセンスコード	(ブロック数：6、ブロック内文字数：5文字).
				// 		無効化コード			(ブロック数：7、ブロック内文字数：5文字).
				// 		修復許可コード			(ブロック数：7、ブロック内文字数：5文字).
				// 		初期化コード			(ブロック数：7、ブロック内文字数：5文字).
				//    が子クラスとして存在する.
				//    バッファは char sc_Code[PNLD_TokenCodeBlockNumMax][PNLD_TokenCodeBlockLenMax + 1];.
				//    として確保される。.
				//    現状では、全てブロック内文字数は5文字であるが、同クラスを用いて、ブロック内文字数が.
				//    4文字という画面が作成される場合は別途対応が必要である.
				//    なお、引数サイズチェックで、入力文字数とブロック数、ブロック内文字数の関係が保証されるので.
				//    領域外に書き込まれることはない.
				memset( psc_Buff, '\0', uc_BlockLen+1 );
				strncpy( psc_Buff, sc_InputStrFromRMP+( us_cnt*uc_BlockLen ), uc_BlockLen );
				psc_Buff = psc_Buff + uc_BlockLen + 1;
			}
		}
	}
}
