// -----------------------------------------------------------------------------------------------
// クラス	：PNLC_RMPStrInputMng.
// 関数名	：isUsableLicenseCode.
// 引数		：char *psc_str.
// 戻り値	：True(英大文字（I、Oを除く）および数字（2～9）のみで構成されている)/ False(左記以外).
// 備考		：ライセンスコードなどで用いる.
// 作成者	：OPS1 棚.
// -----------------------------------------------------------------------------------------------
Bool PNLC_RMPStrInputMng::isUsableLicenseCode( char* psc_str )
{
	Bool bl_ret = True;		// 返却値.

	if( NULL == psc_str ) {
		LOGF_debug_PutEventLog( LOGF_DEBUG_EVENT_KIND_ALL, 0, LOGD_DEBUG_LEVEL_UNKNOWN, "Assert Failed!" );
		return False;
	}
	while( '\0' != *psc_str ) {	// 終端文字チェック.
		if( 0x32 <= *psc_str && 0x39 >= *psc_str ) {	// 2-9の場合.
			// 受付許可.
		} else if( 0x41 <= *psc_str && 0x5A >= *psc_str ) {	// A-Zの場合.
			if( 0x49 == *psc_str || 0x4F == *psc_str ) {		// IおよびOは受付拒否.
				bl_ret = False;
				break;
			}
		} else {	// それ以外は一律で受付拒否.
			bl_ret = False;
			break;
		}
		psc_str++;				// 次の文字へ移動.
	}
	return bl_ret;
}
