// -----------------------------------------------------------------------------------------------
// クラス	：PNLC_RMPStrInputMng.
// 関数名	：isUsableStrForNotSlideTextMgr.
// 引数		：char *psc_str.
//			：ushort us_MaxLen		最大文字数.
//			：ushort us_MaxSize		バッファサイズ.
// 戻り値	：True(サイズ適正かつ入力可能文字のみ)/ False(左記以外).
// 備考		：キーボードパーツを持っているが、PCGC_SlideTextMgrを用いていない画面でのチェック用.
//			：PNLC_RMPStrInputMng::isUsableStr()の処理を流用.
// 作成者	：OPS1 棚.
// -----------------------------------------------------------------------------------------------
Bool PNLC_RMPStrInputMng::isUsableStrForNotSlideTextMgr( char* psc_Str, ushort us_MaxLen, ushort us_MaxSize )
{
	if( NULL == psc_Str ) {
		LOGF_debug_PutEventLog( LOGF_DEBUG_EVENT_KIND_ALL, 0, LOGD_DEBUG_LEVEL_UNKNOWN, "Assert Failed!" );
		return False;
	}

	ushort us_StrNum = 0;		//実際の文字数.
	while( '\0' != *psc_Str ) {
		uchar uc_charByte = 0;		// 一文字あたりのバイト数.
		uc_charByte = LIBF_getUTF8ByteCount( ( const char* )psc_Str );		// バイト数取得.

		if( 0 == uc_charByte ) {
			return False;
		} else if( 1 == uc_charByte ) {		// 1バイト文字の場合.
			if( 0x1f >= *psc_Str ) {		// 制御コードの場合.
				return False;
			} else if( ( NULL != pc_ConvertKeybord && True == pc_ConvertKeybord->isDisableKeyCharCode( psc_Str ) )
			           || ( NULL != pc_ConvertKeybordEnl && True == pc_ConvertKeybordEnl->isDisableKeyCharCode( psc_Str ) ) ) {	// 入力禁止文字.
				return False;
			}
		} else if( 2 == uc_charByte ) {		// 2バイト文字の場合.
			if( False == bl_is2BytesChar ) {			// 2バイト文字使用不可.
				return False;
			}
		} else if( 3 == uc_charByte ) {		// 3バイト文字の場合.
			// ユーロ記号の場合は、2バイト文字使用不可の場合、Falseを返す.
			if( ( 0xE2 == *psc_Str ) && ( 0x82 == *( psc_Str+1 ) ) && ( 0xAC == *( psc_Str+2 ) ) ) {
				if( False == bl_is2BytesChar ) {	// 2バイト文字使用不可.
					return False;
				}
			} else if( False == bl_is3BytesChar ) {		// 3バイト文字使用不可.
				return False;
			}
		}	// 以下、4バイト文字以上の対応が必要ならば追加すること.
		// 一文字あたりのバイト数分のサイズを持っているか?.
		char sc_Str[7];
		memset( sc_Str, '\0', sizeof( sc_Str ) );
		memcpy( sc_Str, psc_Str, uc_charByte );		// psc_StrよりUTF-8 1文字分取り出す.
		if( uc_charByte != strlen( sc_Str ) ) {
			return False;
		}
		us_StrNum++;
		if( us_StrNum > us_MaxLen ) {
			return False;
		}

		psc_Str += uc_charByte;		// 次のUTF-8先頭文字へ移動.
	}
	return True;
}
