ushort PnlComGetMaxUniversalShorteningAddCnt()
{
	ushort us_MaxFaxSendShorteningAddress = PNLD_MaxFaxSendShorteningAddress;
	ACSE_CCScanToEmail	sc_CCScanToEmailFunc	= ACSE_CCScanToEmail_Convent;		// 送信先 CC  ScanToE-mail機能設定.
	ACSE_BCCScanToEmail	sc_BCCScanToEmailFunc	= ACSE_BCCScanToEmail_Convent;		// 送信先 BCC ScanToE-mail機能設定.

	// コンフィグ値読込み
	APIC_AuthCust *pc_AuthCust = APIC_AuthCust::newInstance();
	if (NULL != pc_AuthCust){
		pc_AuthCust->getCCScanToEmail(&sc_CCScanToEmailFunc);
		pc_AuthCust->getBCCScanToEmail(&sc_BCCScanToEmailFunc);
	}

	// どちらか片方だけが従来動作になる事は無いが、念のため両機能が従来動作の場合のみDipSWを考慮する.
	if(		(ACSE_CCScanToEmail_Convent == sc_CCScanToEmailFunc)
		&&	(ACSE_CCScanToEmail_Convent == sc_BCCScanToEmailFunc)	) {
		if( True == APIC_SoftDipSw::newInstance()->getSoftDipSwBitForPanelSpecNo( 201, 0 ) ) {
			us_MaxFaxSendShorteningAddress = (ushort)( us_MaxFaxSendShorteningAddress - 1 );
		}
	}
	return us_MaxFaxSendShorteningAddress;
}

//================================================================================================.
// 概要     : セルフレジストレーション機能のOn/Off判定.
//================================================================================================.
Bool PnlComIsCardSelfRegistrationOn()
{
	Bool b_Result = False;

	Bool b_SpRomMode = False;
	APIC_AuthCust *pc_AuthCust = NULL;
	ACSE_RegistType e_Param = ACSE_RegistType_Convent;

	pc_AuthCust = APIC_AuthCust::newInstance();
	if (NULL == pc_AuthCust) {
		return b_Result;
	}

	pc_AuthCust->getUserRegistType(&e_Param);
	switch( e_Param ) {
		case ACSE_RegistType_SelfReg:
			b_SpRomMode = True;
			break;
		case ACSE_RegistType_Convent:
			if ( True == APIC_SoftDipSw::newInstance()->getSoftDipSwBitForPanelSpecNo( DEFSOFTWARESW200, 2 ) ) {
				b_SpRomMode = True;
			}
			break;
		default:
			break;
	}
	// DipSWNo.200 bit2 がOnで、ユーザー認証方式が「本体装置+外部サーバでの認証」、尚且つ、認証装置装着時、機能Onと判定する.
	if( ( True == b_SpRomMode )
	    && ( TYPE_UserAuthenticationDeviceAndServer == PnlComGetUserAuthentication()->getUserAuthentication(PNLC_NetworkLan::getInstance()->getLine()) )
	    && ( TYPE_KeyModeNone == PnlComGetMachineSetting()->getKeyMode() )
	    && ( ( TYPE_AUTH_DEVICE_ICC == PnlComGetAuthDeviceSetting()->getAuthDeviceType() )
	         || ( TYPE_AUTH_DEVICE_LOADABLE_ICC == PnlComGetAuthDeviceSetting()->getAuthDeviceType() ) ) ) {
		b_Result = True;
	}
	return b_Result;
}

