/*================================================================================================
// 概要		:カバレッジレートの値を取得(CommonAPI).
// 戻り値	:なし
// 備考		:
================================================================================================*/
void PLBC_BillingCounterManager::getCoverageRateData( PNLE_CovaregeCntSizeOnColors e_TonerCoverageCnt,PNLS_CoverageRateYMCK* ps_coverageRateYMCK,PNLS_CoverageRateCoefficient* ps_CoverageRateCoefficient )
{
	// 引数チェック.
	if( ( NULL == ps_coverageRateYMCK ) || ( NULL == ps_CoverageRateCoefficient ) ) {
		LOGF_debug_PutEventLog( LOGF_DEBUG_EVENT_KIND_ALL, 0, LOGD_DEBUG_LEVEL_UNKNOWN, "Assert Failed!" );
		return;
	}

	// 範囲チェック.
	if( PNLE_CovaregeCntSize <= e_TonerCoverageCnt ) {
		LOGF_debug_PutEventLog( LOGF_DEBUG_EVENT_KIND_ALL, 0, LOGD_DEBUG_LEVEL_UNKNOWN, "Assert Failed!" );
		return;
	}
	// APIC_TonerCoverageSettingインスタンス取得.
	APIC_TonerCoverageSetting* pc_TonerCoverageSetting = APIC_TonerCoverageSetting::newInstance();
	if( NULL == pc_TonerCoverageSetting ) {
		LOGF_debug_PutEventLog( LOGF_DEBUG_EVENT_KIND_ALL, 0, LOGD_DEBUG_LEVEL_UNKNOWN, "Assert Failed!" );
		return;
	}

	// YMC/YMCK合計印字率取得.
	ps_coverageRateYMCK->range1 = PNLD_BillingCounterManagerCoverageRateRange1InitVal;
	if( TYPD_ThresholdNotUse == pc_TonerCoverageSetting->getTotalCoverageRateThreshold_YMCK( g_s_CovaregeCntData[e_TonerCoverageCnt].range3 ) ) {
		ps_coverageRateYMCK->range4 = TYPD_ThresholdNotUse;
		ps_coverageRateYMCK->range3 = TYPD_ThresholdNotUse;
		ps_coverageRateYMCK->range2 = TYPD_ThresholdNotUse;
	}
	else if( TYPD_ThresholdNotUse == pc_TonerCoverageSetting->getTotalCoverageRateThreshold_YMCK( g_s_CovaregeCntData[e_TonerCoverageCnt].range2 ) ) {
		ps_coverageRateYMCK->range4 = TYPD_ThresholdNotUse;
		ps_coverageRateYMCK->range3 = TYPD_ThresholdNotUse;
		ps_coverageRateYMCK->range2 = pc_TonerCoverageSetting->getTotalCoverageRateThreshold_YMCK( g_s_CovaregeCntData[e_TonerCoverageCnt].range3 );
	}
	else if( TYPD_ThresholdNotUse == pc_TonerCoverageSetting->getTotalCoverageRateThreshold_YMCK( g_s_CovaregeCntData[e_TonerCoverageCnt].range1 ) ) {
		ps_coverageRateYMCK->range4 = TYPD_ThresholdNotUse;
		ps_coverageRateYMCK->range3 = pc_TonerCoverageSetting->getTotalCoverageRateThreshold_YMCK( g_s_CovaregeCntData[e_TonerCoverageCnt].range2 ) ;
		ps_coverageRateYMCK->range2 = pc_TonerCoverageSetting->getTotalCoverageRateThreshold_YMCK( g_s_CovaregeCntData[e_TonerCoverageCnt].range3 ) ;
	}
	else {
		ps_coverageRateYMCK->range4 = pc_TonerCoverageSetting->getTotalCoverageRateThreshold_YMCK( g_s_CovaregeCntData[e_TonerCoverageCnt].range1 ) ;
		ps_coverageRateYMCK->range3 = pc_TonerCoverageSetting->getTotalCoverageRateThreshold_YMCK( g_s_CovaregeCntData[e_TonerCoverageCnt].range2 ) ;
		ps_coverageRateYMCK->range2 = pc_TonerCoverageSetting->getTotalCoverageRateThreshold_YMCK( g_s_CovaregeCntData[e_TonerCoverageCnt].range3 ) ;
	}

	// 印字率係数取得.
	ps_CoverageRateCoefficient->range4 = pc_TonerCoverageSetting->getCoverageRateCoefficient( g_s_CovaregeCntData[e_TonerCoverageCnt].range1 ) ;
	ps_CoverageRateCoefficient->range3 = pc_TonerCoverageSetting->getCoverageRateCoefficient( g_s_CovaregeCntData[e_TonerCoverageCnt].range2 ) ;
	ps_CoverageRateCoefficient->range2 = pc_TonerCoverageSetting->getCoverageRateCoefficient( g_s_CovaregeCntData[e_TonerCoverageCnt].range3 ) ;
	ps_CoverageRateCoefficient->range1 = pc_TonerCoverageSetting->getCoverageRateCoefficient( g_s_CovaregeCntData[e_TonerCoverageCnt].range4 ) ;
}
/*================================================================================================
// 概要		:BillingCounter色別サイズ.
// 戻り値	:BillingCounter色別サイズの取得.
// 備考		:
================================================================================================*/
PNLE_CovaregeCntSizeOnColors PLBC_BillingCounterManager::getCovarageRateKind( PNLE_BillingCounterColorMode e_colorMode,PNLE_BillingCounterPaperSize e_paperSize )
{
	PNLE_CovaregeCntSizeOnColors ui_Result = PNLE_CovaregeCntSize;

	if( PNLE_BILLINGCOUNTCOLORMODE_Color == e_colorMode ) {
		switch( e_paperSize ) {
			case PNLE_BillingCounterPaperSize_Small:	ui_Result = PNLE_CovaregeCntColorSmall;		break;
			case PNLE_BillingCounterPaperSize_A4:		ui_Result = PNLE_CovaregeCntColorA4;		break;
			case PNLE_BillingCounterPaperSize_Large:	ui_Result = PNLE_CovaregeCntColorLarge;		break;
			case PNLE_BillingCounterPaperSize_Bunner:	ui_Result = PNLE_CovaregeCntColorBunner;	break;
			default: LOGF_debug_PutEventLog( LOGF_DEBUG_EVENT_KIND_ALL, 0, LOGD_DEBUG_LEVEL_UNKNOWN, "Assert Failed!" );	break;
		}
	}
	else if( PNLE_BILLINGCOUNTCOLORMODE_Black == e_colorMode ) {
		switch( e_paperSize ) {
			case PNLE_BillingCounterPaperSize_Small:	ui_Result = PNLE_CovaregeCntBlackSmall;		break;
			case PNLE_BillingCounterPaperSize_A4:		ui_Result = PNLE_CovaregeCntBlackA4;		break;
			case PNLE_BillingCounterPaperSize_Large:	ui_Result = PNLE_CovaregeCntBlackLarge;		break;
			case PNLE_BillingCounterPaperSize_Bunner:	ui_Result = PNLE_CovaregeCntBlackBunner;	break;
			default: LOGF_debug_PutEventLog( LOGF_DEBUG_EVENT_KIND_ALL, 0, LOGD_DEBUG_LEVEL_UNKNOWN, "Assert Failed!" );	break;
		}
	}
	return ui_Result;
}

/*================================================================================================
// 概要		:YMC/YMCK合計印字率を保存(CommonAPI).
// 戻り値	:なし
// 備考		:
================================================================================================*/
void PLBC_BillingCounterManager::setCoverageRateYMCK( PNLE_CovaregeCntSizeOnColors e_TonerCoverageCnt,PNLS_CoverageRateYMCK* ps_coverageRateYMCK )
{
	// 引数チェック.
	if( NULL == ps_coverageRateYMCK ) {
		LOGF_debug_PutEventLog( LOGF_DEBUG_EVENT_KIND_ALL, 0, LOGD_DEBUG_LEVEL_UNKNOWN, "Assert Failed!" );
		return;
	}

	// 範囲チェック.
	if( PNLE_CovaregeCntSize <= e_TonerCoverageCnt ) {
		LOGF_debug_PutEventLog( LOGF_DEBUG_EVENT_KIND_ALL, 0, LOGD_DEBUG_LEVEL_UNKNOWN, "Assert Failed!" );
		return;
	}
	// APIC_TonerCoverageSettingインスタンス取得.
	APIC_TonerCoverageSetting* pc_TonerCoverageSetting = APIC_TonerCoverageSetting::newInstance();
	if( NULL == pc_TonerCoverageSetting ) {
		LOGF_debug_PutEventLog( LOGF_DEBUG_EVENT_KIND_ALL, 0, LOGD_DEBUG_LEVEL_UNKNOWN, "Assert Failed!" );
		return;
	}

	// YMC/YMCK合計印字率設定.
	pc_TonerCoverageSetting->setTotalCoverageRateThreshold_YMCK( g_s_CovaregeCntData[e_TonerCoverageCnt].range1,ps_coverageRateYMCK->range4 );
	pc_TonerCoverageSetting->setTotalCoverageRateThreshold_YMCK( g_s_CovaregeCntData[e_TonerCoverageCnt].range2,ps_coverageRateYMCK->range3 );
	pc_TonerCoverageSetting->setTotalCoverageRateThreshold_YMCK( g_s_CovaregeCntData[e_TonerCoverageCnt].range3,ps_coverageRateYMCK->range2 );
}
/*================================================================================================
// 概要		:印字率係数を保存(CommonAPI).
// 戻り値	:なし
// 備考		:
================================================================================================*/
void PLBC_BillingCounterManager::setCoverageRateCoefficient( PNLE_CovaregeCntSizeOnColors e_TonerCoverageCnt,PNLS_CoverageRateCoefficient* ps_CoverageRateCoefficient )
{
	// 引数チェック.
	if( NULL == ps_CoverageRateCoefficient ) {
		LOGF_debug_PutEventLog( LOGF_DEBUG_EVENT_KIND_ALL, 0, LOGD_DEBUG_LEVEL_UNKNOWN, "Assert Failed!" );
		return;
	}

	// 範囲チェック.
	if( PNLE_CovaregeCntSize <= e_TonerCoverageCnt ) {
		LOGF_debug_PutEventLog( LOGF_DEBUG_EVENT_KIND_ALL, 0, LOGD_DEBUG_LEVEL_UNKNOWN, "Assert Failed!" );
		return;
	}
	// APIC_TonerCoverageSettingインスタンス取得.
	APIC_TonerCoverageSetting* pc_TonerCoverageSetting = APIC_TonerCoverageSetting::newInstance();
	if( NULL == pc_TonerCoverageSetting ) {
		LOGF_debug_PutEventLog( LOGF_DEBUG_EVENT_KIND_ALL, 0, LOGD_DEBUG_LEVEL_UNKNOWN, "Assert Failed!" );
		return;
	}
	// 印字率係数保存.
	pc_TonerCoverageSetting->setCoverageRateCoefficient( g_s_CovaregeCntData[e_TonerCoverageCnt].range1,ps_CoverageRateCoefficient->range4 );
	pc_TonerCoverageSetting->setCoverageRateCoefficient( g_s_CovaregeCntData[e_TonerCoverageCnt].range2,ps_CoverageRateCoefficient->range3 );
	pc_TonerCoverageSetting->setCoverageRateCoefficient( g_s_CovaregeCntData[e_TonerCoverageCnt].range3,ps_CoverageRateCoefficient->range2 );
	pc_TonerCoverageSetting->setCoverageRateCoefficient( g_s_CovaregeCntData[e_TonerCoverageCnt].range4,ps_CoverageRateCoefficient->range1 );
}

