/*================================================================================================
// 概要		:整数値を100で割った文字列を取得する.
// 戻り値	:変換成否.
// 備考		:
================================================================================================*/
Bool PLBC_BillingCounterManager::ulToStrDecpnt( uint32_t ul_num, char* psc_str, uchar uc_len )
{
	Bool bl_ret = False;

	//  引数チェック.
	if( NULL == psc_str ) {
		LOGF_debug_PutEventLog( LOGF_DEBUG_EVENT_KIND_ALL, 0, LOGD_DEBUG_LEVEL_UNKNOWN, "Assert Failed!" );
		return bl_ret;
	}

	memset( psc_str,'\0',uc_len );

	uint32_t	ui32_integer  = static_cast<uint32_t>( ul_num / 100 );
	uchar		uc_decimal  = static_cast<uchar>( ul_num % 100 );
	char		uc_buf[12]  = {0};  //  整数8桁 + '.' + 小数2桁 + '\0'.
	uchar		uc_buflen   =  0;   //  結合後桁数.

	//  整数値と小数値を'.'を挟んで結合.
	uc_buflen = static_cast<uchar>( snprintf( uc_buf, sizeof( uc_buf ), "%d.%02d", ( int )ui32_integer, ( int )uc_decimal ) );
	if( uc_buflen <= uc_len ) {
		memcpy( psc_str, uc_buf, uc_buflen );   //  出力領域長が足りていれば出力領域にコピー.
		bl_ret = True;
	}

	return bl_ret;
}

/*================================================================================================
// 概要		:整数値を100で割った文字列を取得する.
// 戻り値	:変換成否.
// 備考		:第一引数はdoubleだが、整数値を渡すこと.
================================================================================================*/
Bool PLBC_BillingCounterManager::dblToStrDecpnt( double sd_num, char* psc_str, uchar uc_len )
{
	//  引数チェック.
	if( NULL == psc_str ) {
		LOGF_debug_PutEventLog( LOGF_DEBUG_EVENT_KIND_ALL, 0, LOGD_DEBUG_LEVEL_UNKNOWN, "Assert Failed!" );
		return False;
	}
	memset( psc_str, '\0', uc_len );

	char  uc_buf1[21]   = {0};  //  doubleの整数部最大桁数は20 +'\0'.
	char  uc_buf2[21]   = {0};  //  小数点以下を除いた文字列.
	uchar uc_cLen       =  0;   //  整数値の桁数.
	uchar uc_indL       =  0;   //  数値文字列のインデックス.

	snprintf( uc_buf1, sizeof(uc_buf1), "%f", sd_num );
	for( ; uc_buf1[uc_cLen] != '.'; uc_cLen++ ) {
		uc_buf2[uc_cLen] = uc_buf1[uc_cLen];
	}

	if( uc_len <= uc_cLen ) { return False; }

	//  3桁に満たなければ先頭0埋めで3桁に.
	if( uc_cLen < 3 ) {
		snprintf( uc_buf2, sizeof(uc_buf2), "%03d", atoi( uc_buf2 ) );
		uc_cLen = 3;
	}

	//  文字列を生成(適当な個所に '.' を挿入).
	for( uchar uc_i = 0; ( uc_buf2[uc_indL] != '\0' ) && ( uc_i < uc_len ); uc_i++ ) {
		if( uc_i == ( uc_cLen - 2 ) ) {
			psc_str[uc_i] = '.';
		} else {
			psc_str[uc_i] = uc_buf2[uc_indL];
			uc_indL++;
		}
	}

	return True;
}

//================================================================================================.
// 概要		:宛先確認を表示するかを判定する.
// 戻り値	:True/False 表示/非表示.
//================================================================================================.
Bool PnlComIsSelectCheckAddressDisplay() {

	APIC_Job*	pc_Job = PnlComGetJobScanFax();
	if( NULL == pc_Job ) {  return False; }
	if( ( True == PnlComGetSystemSetting()->getEnableViewSelectedAddress() ) 		// 宛先選択表示機能の有効.
	    &&( 1 < pc_Job->getJobSpec()->pc_Send->c_ComSend.getSelectTotalAddressCount() ) 	// 宛先登録済み件数が2件目以降のときに表示.
	    &&( False == onlyPanel.isWarningOn( pc_Job , PNL_ERROR_BroadcastOver ) ) ) {
		return True;
	} else {
		return False;
	}
}
//================================================================================================.
// 概要		:自動ログアウト/ログインが可能かの判定関数.
// 戻り値	:True/False 可能/不可.
//================================================================================================.
Bool PnlCom_IsEnableAutoLogoutLogin() {
	ACSE_UserAuthAutoLoginLogout	e_Mode	= ACSE_UserAuthAutoLoginLogout_Convent;
	APIC_AuthCust*	pc_AuthCust	= APIC_AuthCust::newInstance();
	if( 0 != pc_AuthCust ) {
		pc_AuthCust->getUserAuthAutoLoginLogout( &e_Mode );
	}
	Bool	bl_SpRomMode	= False;
	switch( e_Mode ) {
	case ACSE_UserAuthAutoLoginLogout_NoCustom:		// 無効.
		break;
	case ACSE_UserAuthAutoLoginLogout_Custom:	// 有効.
		bl_SpRomMode	= True;
		break;
	case ACSE_UserAuthAutoLoginLogout_Convent:	// 従来動作.
	default:
		{
			APIC_SoftDipSw*	pc_SoftDipSw	= APIC_SoftDipSw::newInstance();
			if ( 0 == pc_SoftDipSw ) {
				return( False );
			}
			if ( False == pc_SoftDipSw->getSoftDipSwBitForPanelSpecNo( DEFSOFTWARESW203 , 2 ) ) {
				bl_SpRomMode	= True;
			}
		}
		break;
	}
	if( True == PLBC_FuncVersionCheck::isOK_MiZe_Type4() 	// 機能拡張4以降.
		&& ( True == bl_SpRomMode ) ) {		// DipSW203のbit2.
		return True;
	} else {
		return False;
	}
}
//================================================================================================.
// 概要		:中間認証に対してログインしているのか判定し、部門情報をジョブスペックの部門ID領域に設定する.
//
//================================================================================================.
void PnlComSetExtTrackNoIntermeddiateServer( TYPC_JobSpec* pc_JobSpec ) {

	// ユーザーログイン中でない場合はreturnする.
	if( NULL == PnlComGetUser() ) {
		return;
	}
	// ジョブスペックがNULLの場合はreturnする.
	if( NULL == pc_JobSpec ) {
		return;
	}
	// 認証方式を取得.
	TYPE_UserAuthentication e_UserAuthentication = PnlComGetUserAuthentication()->getUserAuthentication(PNLC_NetworkLan::getInstance()->getLine());
	Bool bl_IntermeddiateServerLogin = False;		// 中間認証に対してログインしているかのフラグ.
	// 中間認証に対してログインしているのかを判定する.
	if( TYPE_UserAuthenticationDeviceAndMidAuth == e_UserAuthentication ) {		// 本体認証+中間認証設定時.

		// 本体認証＋中間認証に設定していて中間認証に対してログインしている場合.
		if( TYPE_UserAuthenticationIntermeddiateServer == PnlComGetUser()->getLoginUserAuthenticationType() ) {
			bl_IntermeddiateServerLogin = True;
		}

	} else if( TYPE_UserAuthenticationIntermeddiateServer == e_UserAuthentication ) {		// 中間認証設定時.
		bl_IntermeddiateServerLogin = True;
	}
	// 中間認証に対してログインしていた場合は部門情報をジョブスペックの部門ID領域に設定する.
	if( True == bl_IntermeddiateServerLogin ) {
		pc_JobSpec->pc_Common->c_UserAcount.setExtTrackNo( PCGC_AuthOapCommonStaticLib::sExtTrack.sl_ID );
	}

}

// 概要		：短縮宛先登録で空きがあるかどうかを判定.
// 引数		：TYPE_SendMode e_sendMode：宛先種別.
// 戻り値	：True:空き有り、False:空き無し.
//	PAdminToAddressInputCom::getNewRegを流用.
Bool PnlComIsRegEmpty(
    TYPE_SendMode	e_sendMode )	// 宛先種別
{
	Bool bl_Empty = False;	// 空きなし.
	short ss_RegNoMin = 0;
	short ss_RegNoMax = 0;

	switch( e_sendMode ) {
		case TYPE_SendModeEmail:
		case TYPE_SendModeFtp:
		case TYPE_SendModeSmb:
		case TYPE_SendModeBox:
		case TYPE_SendModeWebDav:
			ss_RegNoMin = PNLD_ScanRegNoMin;
			ss_RegNoMax = PNLD_ScanRegNoMax;
			break;
		case TYPE_SendModeFax:
		case TYPE_SendModeIfax:
		case TYPE_SendModeIPAddressFax:
		case TYPE_SendModeIPFax:		// comment 2019/02/27 SCD2-Sky中野 [EagleH][RQ-272] Fax機能をもつ全製品のT38Faxプロトコルの対応.
			ss_RegNoMin = PNLD_FaxRegNoMin;
			ss_RegNoMax = PNLD_FaxRegNoMax;
			break;
		default:
			break;
	}
//Comment 2017/09/04 [HCL-Suganya] [IT5 4.2][RQ-686] [WP97]Multiple Network support.
	TYPE_NetworkSpecific e_NetworkSpecific = PNLC_NetworkLan::getInstance()->getLine();
	for( register short i = ss_RegNoMax; i >= ss_RegNoMin; i-- ) {
//Comment 2017/09/04 [HCL-Suganya] [IT5 4.2][RQ-686] [WP97]Multiple Network support.
//		APIC_ShorteningAddress* pc_ShorteningAddress = APIC_ShorteningAddress::newInstance( i );
		APIC_ShorteningAddress* pc_ShorteningAddress = APIC_ShorteningAddress::newInstance( i , e_NetworkSpecific );
// comment 2018/01/17【HCLT-Jagadeesh】【IT5_4.2】Kloc work Changes ID:396003 【NPD.FUNC.MUST】.
		if( ( NULL != pc_ShorteningAddress ) && ( False == pc_ShorteningAddress->getRegistration() ) ) {
			// 未登録状態ならば
			bl_Empty = True;	// 空きあり.
			break;
		}
	}
	return bl_Empty;
}
// 概要   : 宛先解除後のFromアドレス設定.
// 戻り値 : 無し.
void PnlComSetFromAddressAtNotSelectAddress( APIC_Job* pc_Job ) {
	if( NULL == pc_Job ) {
		LOGF_debug_PutEventLog( LOGF_DEBUG_EVENT_KIND_ALL, 0, LOGD_DEBUG_LEVEL_UNKNOWN, "Assert Failed!" );
		return;
	}
	// Fromアドレス設定.
	char sc_From[TYPD_MaxMailAddress + 1];
	memset( sc_From, 0, sizeof( sc_From ) );
	c_JobControl.e_FaxScanFromSelect = PnlComGetFromAdressSelection( pc_Job, sc_From );		// Fromアドレスの取得.
	pc_Job->getJobSpec()->pc_Send->c_MailSend.setMailFrom( sc_From );						// ジョブスペックへ反映.
}

