#define PNLD_BroadcastPadMaxLen ( 35 * 3 )		// 同報宛先パッドのリスト最大文字幅 35文字 * UTF8.

//================================================================================================.
//	概要    ：同報宛先パッド管理クラス モデルデータの設定.
// 戻り値	: なし.
//================================================================================================.
void PNLC_BroadcastPadControlLib::setModelData( const TYPS_AddressInfo& st_AddressInfo , Bool bl_update , ushort us_updateIndex )
{
//#if !defined(SIMULATOR)
	TYPE_SendMode e_SendMode = st_AddressInfo.e_SendMode;
	// アドレス名.
	char sc_address[ PNLD_BroadcastPadMaxLen + 1 ];
	memset( sc_address , '\0', sizeof( sc_address ) );

	if( ( True == onlyPanel.isSearchDigitalID() ) && ( False == st_AddressInfo.b_Direct ) ) {
		// デジタルID検索中で短縮宛先の場合.
		e_SendMode = TYPE_SendModeEmail;

		TYPC_DigitalIDAddress* pc_DigitalIDAddress = PnlComGetSelectedDigitalIDAddress();
		if( pc_DigitalIDAddress == NULL ) {
			return;
		}
		TYPS_DigitalIDAddressInfo s_DigitalIDAddressInfo;
		memset( &s_DigitalIDAddressInfo, 0x00, sizeof( s_DigitalIDAddressInfo ) );
		if( True == pc_DigitalIDAddress->getAddress( &s_DigitalIDAddressInfo, st_AddressInfo.ul_LeftRecodeId ) ) {
			strncpy( sc_address , s_DigitalIDAddressInfo.sc_Name , PNLD_BroadcastPadMaxLen );
		} else {
			return;
		}
	} else if( False == st_AddressInfo.b_Direct ) {
		// 短縮宛先の場合.
		APIC_Job* pc_Job = PnlComGetJobScanFax();
		if( NULL == pc_Job )	{
			LOGF_debug_PutEventLog( LOGF_DEBUG_EVENT_KIND_ALL, 0, LOGD_DEBUG_LEVEL_UNKNOWN, "Assert Failed!" );
			return;
		}
		// FAX共通配信 .
		TYPC_ComSend* pc_LeftComSend = &( pc_Job->getJobSpec()->pc_Send->c_ComSend );
		// 選択されている同報宛先のレコードIDを使用して、宛先情報を取得.
		TYPC_ShorteningAddress* pc_ShorteningAddress = NULL;
		pc_ShorteningAddress = pc_LeftComSend->searchShorteningAddressByDbRecordNo( st_AddressInfo.ul_LeftRecodeId );
		if( NULL == pc_ShorteningAddress ) {
			PnlComPutDebugLog( True, UC_PNL_LOGPATTERN_1, "getLeftAreaAddressGraphic", UC_PNL_ERROR_IMPOSSIBLE );
			return;
		}
		// 宛先種別の取得.
		e_SendMode = pc_ShorteningAddress->getSendMode();

		// 宛先.
		char sc_ShorteningAddress[ TYPD_MaxStrAddressNameUTF8 + 1 ];
		// 宛先名の取得.
		pc_ShorteningAddress->getAddressNameUTF8( sc_ShorteningAddress, TYPE_CharSetUTF8 );
		strncpy( sc_address , sc_ShorteningAddress , PNLD_BroadcastPadMaxLen );
	} else {
		APIC_Job* pc_Job = PnlComGetJobScanFax();
		if( NULL == pc_Job )	{
			LOGF_debug_PutEventLog( LOGF_DEBUG_EVENT_KIND_ALL, 0, LOGD_DEBUG_LEVEL_UNKNOWN, "Assert Failed!" );
			return;
		}
		// ダイレクト宛先の場合.
		TYPC_DirectAddressBook* pc_DirectAddressBook = &( pc_Job->getJobSpec()->pc_Send->c_ComSend.c_DirectAddressBook );
		char sc_DirectAddress[ TYPD_MaxMailAddress + 3 ];
		memset( sc_DirectAddress, '\0', sizeof( sc_DirectAddress ) );
		TYPS_FtpAddress		s_FtpAddress;				// FTP宛先
		TYPS_WebDavAddress	s_WebDavAddress;			// WebDav宛先.
		// 送信種別の判定.
		switch( st_AddressInfo.e_SendMode ) {
			// FTP宛先.
			case TYPE_SendModeFtp:
				if( True == pc_DirectAddressBook->pageFtpAddress( st_AddressInfo.ss_AddressNo )->getOn() ) {
					// 宛先名の取得.
					s_FtpAddress = pc_DirectAddressBook->pageFtpAddress( st_AddressInfo.ss_AddressNo )->getFtpAddress( TYPE_CharSetUTF8 );
					getAddressDispStringFtp( &s_FtpAddress, sc_DirectAddress, sizeof( sc_DirectAddress ) );
					// 宛先名として表示する文字列を整形する.
					strncpy( sc_address , sc_DirectAddress , PNLD_BroadcastPadMaxLen );
				} else {
					PnlComPutDebugLog( True, UC_PNL_LOGPATTERN_1, "getLeftAreaAddressName", UC_PNL_ERROR_IMPOSSIBLE );
					return;
				}
				break;
			// SMB宛先.
			case TYPE_SendModeSmb:
				if( True == pc_DirectAddressBook->pageSmbAddress( st_AddressInfo.ss_AddressNo )->getOn() ) {
					// 宛先名の取得.
					TYPS_SmbAddress s_SmbAddress;
					s_SmbAddress = pc_DirectAddressBook->pageSmbAddress( st_AddressInfo.ss_AddressNo )->getSmbAddress( TYPE_CharSetUTF8 );
// comment 2016/12/19 MSE岡田 [IT5_3.4][xxxxxxx] SMB宛先のホスト名とディレクトリパスを結合する処理を共通関数で行うように修正する.
//					PnlComJointAddress( s_SmbAddress.sc_HostAddress, s_SmbAddress.sc_Dir, sc_DirectAddress );
					PnlComJointAddressForSMB( s_SmbAddress.sc_HostAddress, s_SmbAddress.sc_Dir, sc_DirectAddress, sizeof( sc_DirectAddress ) );
					strncpy( sc_address , sc_DirectAddress , PNLD_BroadcastPadMaxLen );
				} else {
					PnlComPutDebugLog( True, UC_PNL_LOGPATTERN_1, "getLeftAreaAddressName", UC_PNL_ERROR_IMPOSSIBLE );
					return;
				}
				break;
			// BOX宛先.
			case TYPE_SendModeBox:
				if( True == pc_DirectAddressBook->pageBoxAddress( st_AddressInfo.ss_AddressNo )->getOn() ) {
					// 宛先名の取得.
					TYPS_BoxAddress s_BoxAddress = pc_DirectAddressBook->pageBoxAddress( st_AddressInfo.ss_AddressNo )->getBoxAddress();
					// ボックス番号の設定.
					PanelLog( PNLD_LogKind_ScanFax, "setBoxId: P1[%d]", s_BoxAddress.sl_BoxNo, 0, 0, 0, 0, 0 );
					
// comment 2015/10/26 OP1-Sky浜野 [MinervaSBK][MZV-48] ScanToURLとScanToE-Mailの機能拡張対応.
					if( ( True == isScanToURL() )
					&&	( DOCD_ScanToURLBox == s_BoxAddress.sl_BoxNo ) ) {
						e_SendMode = TYPE_SendModeEmail;

						TYPC_ShorteningAddress c_ScanToMe;
						PnlComSetScanToMe( &c_ScanToMe );
						TYPS_MailAddress s_MailAddress = c_ScanToMe.getMailAddress();
						
						strncpy( sc_address, s_MailAddress.sc_MailToAddress, PNLD_BroadcastPadMaxLen );
						
					} else { 
// Commment 2017/09/22 HCL_Venkataramesh [IT5_4.2][RQ-686][WP689] setBoxId support for Network2 user.
//						cp_DocList->setBoxId( s_BoxAddress.sl_BoxNo );
						PNLC_NetworkLan::getInstance()->setBoxIdPNL( cp_DocList, s_BoxAddress.sl_BoxNo );
						// ボックス情報の取得（この時点でCommonAPI用文字列をパネル用に変換）.
						APIC_BoxInfo c_BoxInfo;
						PanelLog( PNLD_LogKind_ScanFax, "getBoxInfo P1[%p] P2[%p] P3[%d]", NULL, &c_BoxInfo, -1, 0, 0, 0 );
						cp_DocList->getBoxInfo( NULL, &c_BoxInfo, LIBE_CharSetDefault );
						// ボックス名をコピー.
						strcpy( sc_DirectAddress, c_BoxInfo.sc_BoxName );
						// ボックス名が未登録の場合.
						if( 0 == strlen( sc_DirectAddress ) ) {
							// ボックス番号を取得.
							snprintf( sc_DirectAddress, sizeof(sc_DirectAddress), "%09d", s_BoxAddress.sl_BoxNo );
						}
						strncpy( sc_address , sc_DirectAddress , PNLD_BroadcastPadMaxLen );
					}
				} else {
					PnlComPutDebugLog( True, UC_PNL_LOGPATTERN_1, "getLeftAreaAddressName", UC_PNL_ERROR_IMPOSSIBLE );
					return;
				}
				break;
			// FAX宛先.
			case TYPE_SendModeFax:
				if( True == pc_DirectAddressBook->pageFaxAddress( st_AddressInfo.ss_AddressNo )->getOn() ) {
					TYPS_FaxAddress s_FaxAddress;
					PNLC_DoubleDial* pc_Pdd = PNLC_DoubleDial::getInstance();
					// 宛先名の取得.
					if( st_AddressInfo.ss_AddressNo  == pc_Pdd->getFaxDirectIndexNo() ) {
						memset( s_FaxAddress.sc_DialNo, '\0', sizeof( s_FaxAddress.sc_DialNo ) );	// 静的解析対応.
//Comment 2018/03/08 【HCLT-Vinod】【IT6_Eagle】【AR1037312】Modified to display only "********" in Broadcast destination list screen.
//						strncpy( s_FaxAddress.sc_DialNo, "***************", sizeof( s_FaxAddress.sc_DialNo )-1 );
						strncpy( s_FaxAddress.sc_DialNo, "********", sizeof( s_FaxAddress.sc_DialNo )-1 );
					} else {
						s_FaxAddress = pc_DirectAddressBook->pageFaxAddress( st_AddressInfo.ss_AddressNo )->getFaxAddress();
					}
					strncpy( sc_address , s_FaxAddress.sc_DialNo , PNLD_BroadcastPadMaxLen );
				} else {
					PnlComPutDebugLog( True, UC_PNL_LOGPATTERN_1, "getLeftAreaAddressName", UC_PNL_ERROR_IMPOSSIBLE );
					return;
				}
				break;
			// メール宛先.
			case TYPE_SendModeEmail:
			// I-FAX送信.
			case TYPE_SendModeIfax:
				if( True == PnlComGetDirectMailAddress( &pc_Job->getJobSpec()->pc_Send->c_ComSend, st_AddressInfo.ss_AddressNo )->getOn() ) {
					// 宛先名の取得.
					TYPS_MailAddress s_MailAddress = PnlComGetDirectMailAddress( &pc_Job->getJobSpec()->pc_Send->c_ComSend, st_AddressInfo.ss_AddressNo )->getMailAddress();
					// 宛先名として表示する文字列を整形する.
					strncpy( sc_address , s_MailAddress.sc_MailToAddress , PNLD_BroadcastPadMaxLen );
				} else {
					PnlComPutDebugLog( True, UC_PNL_LOGPATTERN_1, "getLeftAreaAddressName", UC_PNL_ERROR_IMPOSSIBLE );
					return;
				}
				break;
			// IPアドレスファクス宛先.
			case TYPE_SendModeIPAddressFax:
				if( True == pc_DirectAddressBook->pageMailAddress( st_AddressInfo.ss_AddressNo )->getOn() ) {
					// 宛先名の取得.
					TYPS_MailAddress s_MailAddress = pc_DirectAddressBook->pageMailAddress( st_AddressInfo.ss_AddressNo )->getMailAddress();
					if( True == PnlComIsEmailAddress( s_MailAddress.sc_MailToAddress ) ) {
						strcpy( sc_DirectAddress, s_MailAddress.sc_MailToAddress );
					} else {
						strcpy( sc_DirectAddress, "\\\\" );
						strcat( sc_DirectAddress, s_MailAddress.sc_MailToAddress );
					}
					strncpy( sc_address , sc_DirectAddress , PNLD_BroadcastPadMaxLen );
				} else {
					PnlComPutDebugLog( True, UC_PNL_LOGPATTERN_1, "getLeftAreaAddressName", UC_PNL_ERROR_IMPOSSIBLE );
					return;
				}
				break;
			// WebDAV宛先.
			case TYPE_SendModeWebDav:
				if( True == pc_DirectAddressBook->pageWebDavAddress( st_AddressInfo.ss_AddressNo )->getOn() ) {
					// 宛先名の取得.
					s_WebDavAddress = pc_DirectAddressBook->pageWebDavAddress( st_AddressInfo.ss_AddressNo )->getWebDavAddressUTF8( TYPE_CharSetUTF8 );
					getAddressDispStringWebDAV( &s_WebDavAddress, sc_DirectAddress, sizeof( sc_DirectAddress ) );
					strncpy( sc_address , sc_DirectAddress , PNLD_BroadcastPadMaxLen );
				} else {
					PnlComPutDebugLog( True, UC_PNL_LOGPATTERN_1, "getLeftAreaAddressName", UC_PNL_ERROR_IMPOSSIBLE );
					return;
				}
				break;
			default:	PnlComPutDebugLog( True, UC_PNL_LOGPATTERN_1, "getLeftAreaAddressName", UC_PNL_ERROR_IMPOSSIBLE );	return;
		}
	}

	if( True == bl_update ) {
		PnlComMtuiIf_BroadcastListModel::instance()->updateDataToSubmit( us_updateIndex , e_SendMode , sc_address );
	} else {
		PnlComMtuiIf_BroadcastListModel::instance()->addDataToSubmit( e_SendMode , sc_address );
	}
//#endif
}

//================================================================================================.
//	概要    ：同報宛先パッド管理クラス 同報宛先パッド終了処理.
// 戻り値	: なし.
//================================================================================================.
void PNLC_BroadcastPadControlLib::endBroadcastPad()
{
//#if !defined(SIMULATOR)
// comment 2015/04/17 OPS1-Sky守川 [特ROM][CQ392604] ベンダー接続時にスリープ中に入金すると標準トップメニューになにも表示されないことがある（ERBJKS1400776212）.
//	m_bl_isNowShownBroadCastPad = False;
	memset( &m_st_selectAddressInfo, 0x00, sizeof( m_st_selectAddressInfo ) );

// comment 2014/12/25 OPS1-Sky中江 [ZeusS][CQ507795] 同報宛先リストをアニメーションで閉じるよう修正.
//	PnlComMtuiIf_BroadcastPadView::instance()->hide();
//	PnlComMtuiIf_BroadcastListModel::instance()->free();
	// 同報宛先パッドが表示中の場合.
	if( True == m_bl_isNowShownBroadCastPad ){
		m_bl_isNowShownBroadCastPad = False;
//Comment 2017/12/26 【HCLT-Vinod】【IT5 4.2】【AR1035101】commented free and hide to perform animation when closing.
//		PnlComMtuiIf_BroadcastPadView::instance()->hide();
//		PnlComMtuiIf_BroadcastListModel::instance()->free();
	}
	Bool bl_AnimatorForCloseFlg = True;
	if( ( 0 == m_ss_destinationCountArea_x ) && ( 0 == m_ss_destinationCountArea_y ) ){
		// 宛先件数キーの座標情報が設定されていない場合はアニメーションを行わない.
		bl_AnimatorForCloseFlg = False;
	}
	if( TYPE_EnablePopupAnimationOFF == PnlComGetOperationSetting()->getEnablePopupAnimationClose() ) {
		// ポップアップクローズ時、アニメーションしない設定の場合.
		bl_AnimatorForCloseFlg = False;
	}
	if( True == bl_AnimatorForCloseFlg ){
		PnlComMtuiIf_BroadcastPadView::instance()->startToClose( bl_AnimatorForCloseFlg, m_ss_destinationCountArea_x, m_ss_destinationCountArea_y, m_ss_destinationCountArea_width, m_ss_destinationCountArea_height );
	}else{
	PnlComMtuiIf_BroadcastPadView::instance()->hide();
	PnlComMtuiIf_BroadcastListModel::instance()->free();
	}
	// 宛先件数キーの矩形情報クリア.
	clearDestinationCountAreaRect();
// comment 2014/09/19 OPS1-Sky東島 [ZeusS][UV-01439].
//#endif
}
//================================================================================================.
//	概要    ：同報宛先パッド管理クラス 2度宛先入力設定変更.
// 戻り値	: なし.
//================================================================================================.
void PNLC_BroadcastPadControlLib::setDoubleDial( short ss_index )
{
//#if !defined(SIMULATOR)
	if( True == m_bl_isNowShownBroadCastPad ) {
		TYPC_BroadcastAddress* pc_BroadcastAddress = PnlComGetBroadcastAdress();
		// モデルの更新.
		for( short ss_i = 0 ; pc_BroadcastAddress->getBroadcastAddressCount() > ss_i ; ss_i++ ) {
			TYPS_AddressInfo st_AddressInfo;
			memset( &st_AddressInfo, 0x00, sizeof( st_AddressInfo ) );
			pc_BroadcastAddress->getUniqueBroadcastAddressInfo( st_AddressInfo, (ushort)( ss_i + 1 ) );
			setModelData( st_AddressInfo , True , ss_i );
		}
		PnlComMtuiIf_BroadcastListModel::instance()->submitDatas();
		PnlComMtuiIf_BroadcastPadView::instance()->setReInputState( TYPD_NotSetting == ss_index ? False : True );
	}
//#endif
}
//================================================================================================.
//	概要    ：同報宛先パッド管理クラス ベース画面判定処理.
// 戻り値	: True：ベース宛先画面 False：それ以外.
//================================================================================================.
Bool PNLC_BroadcastPadControlLib::isNowBaseGamen()
{
	PNLC_PopupListControl* pc_PopupListControl = PNLC_PopupListControl::newInstance();
	if( NULL != pc_PopupListControl ) {
		PPopupAnimationCom* pc_NowPopup = dynamic_cast<PPopupAnimationCom*>( pc_PopupListControl->getNowPopup() ) ;
		if( NULL != pc_NowPopup ) {
			return False;
		}
		return True;
	} else {
		return False;
	}
}
//================================================================================================.
//	概要    ：同報宛先パッド管理クラス ファクス直接入力画面判定処理.
// 戻り値	: True：FAX直接入力画面 False：それ以外.
//================================================================================================.
Bool PNLC_BroadcastPadControlLib::isNowDirectInputFaxGamen()
{
	PNLC_PopupListControl* pc_PopupListControl = PNLC_PopupListControl::newInstance();
	if( NULL != pc_PopupListControl ) {
		PLayerControl* pc_NowPopup = pc_PopupListControl->getNowPopup();
		if( ( &gp_A032000100 == pc_NowPopup )
		    || ( &gp_DirectInputAddrContinuousPush_scanfax == pc_NowPopup )
		    || ( &gp_DocSendINputDirect_box == pc_NowPopup )
		    || ( &gp_DocSendINputDirectRe_box == pc_NowPopup )
		    || ( &gp_DirectInputFaxSendExt_scanfax == pc_NowPopup )
		    || ( &gp_OAPDirectInputAddrContinuousPush_scanfax == pc_NowPopup ) ) {
			return True;
		} else {
			return False;
		}
	} else {
		return False;
	}
}
