//const uchar uc_broadcastPadPopupGamenTblSize = ( uchar )( sizeof( st_broadcastPadBaseGamenTbl ) / sizeof( PLayerControl* ) );
const uchar uc_broadcastPadPopupGamenTblSize = ( uchar )( sizeof( c_BroadcastPadPopupGamenTbl ) / sizeof( PLayerControl* ) );

//================================================================================================.
//	概要    ：同報宛先パッド管理クラス 宛先件数キー押下処理.
// 戻り値	: なし.
//================================================================================================.
void PNLC_BroadcastPadControlLib::procDestinationCount( short ss_x , short ss_y , short ss_width , short ss_height )
{
// Comment [2015/09/29] [HCLT_Rajamanickam] [MinervaSBK] [CQ516282] Added condition to validate the screen for opening destination list.
	PNLC_PopupListControl* pc_PopupListControl = PNLC_PopupListControl::newInstance();
	if ( NULL == pc_PopupListControl ){
		LOGF_debug_PutEventLog( LOGF_DEBUG_EVENT_KIND_ALL, 0, LOGD_DEBUG_LEVEL_UNKNOWN, "Assert Failed!" );
		return;
	}
    Bool bl_flag = False;
    if( True == pc_PopupListControl->isPopupOpen() ) {
    	for( uchar uc_i = 0; uc_broadcastPadPopupGamenTblSize > uc_i ;uc_i++ ){
             if( pc_PopupListControl->getNowPopupNonPullDown() == ((PLayerControl*)c_BroadcastPadPopupGamenTbl[ uc_i ]) ){
                 bl_flag = True;
				 break;
             }
    	}
    } else {
    	PBasicMessageProc* p_getGamen = PBasicMessageProc::getNowGamen();
    	for( uchar uc_i = 0; uc_broadcastPadBaseGamenTblSize > uc_i ;uc_i++ ){
             if( p_getGamen == ((PBasicMessageProc*)st_broadcastPadBaseGamenTbl[ uc_i ].pc_gamen) ){
                 bl_flag = True;
				 break;
             }
    	}
    }
	if( False == bl_flag){ 
		return;				//Focus is not in listed screen.
    }
//#if !defined(SIMULATOR)
	if( False == m_bl_isNowShownBroadCastPad ) {				// 同報宛先パッド非表示の場合.
		m_bl_isFaxOnlyModeNowGamen = onlyPanel.getFaxAppMode();
		m_bl_isNowShownBroadCastPad = True;
		m_bl_selectAllFlg = False;
		// モデル確保.
		PnlComMtuiIf_BroadcastListModel::instance()->alloc();
// Comment 2019/03/21 [HCL_Ranjith][IT6_EagleH][OP_BTS-3538] Scrollbar display in broadcast list.
//		setQtListData();

		if( True == isNowBaseGamen() ) {
			ss_x = 596;
			ss_y = 5;
			ss_width = -1;
			ss_height = -1;
		} else if( True == isNowDirectInputFaxGamen() ) {
			ss_x = 594;
			ss_y = 5;
			ss_width = -1;
			ss_height = -1;
		} else {
			// 何もしない.
		}

		PnlComMtuiIf_BroadcastPadView::instance()->show( ss_x , ss_y , ss_width , ss_height );
// Comment 2019/03/21 [HCL_Ranjith][IT6_EagleH][OP_BTS-3538] Scrollbar display in broadcast list.
		setQtListData();
		PnlComMtuiIf_BroadcastPadView::instance()->setReInputState( TYPD_NotSetting == PNLC_DoubleDial::getInstance()->getFaxDirectIndexNo() ? False : True );
	} else {												// 同報宛先パッド表示中の場合.
// comment 2014/12/25 OPS1-Sky中江 [ZeusS][CQ507795] 同報宛先リストをアニメーションで閉じるよう修正.
		setDestinationCountAreaRect( ss_x, ss_y, ss_width, ss_height );
		endBroadcastPad();
	}
//#endif
}

//================================================================================================.
//	概要    ：同報宛先パッド管理クラス 同報宛先リストの設定.
// 戻り値	: なし.
//================================================================================================.
void PNLC_BroadcastPadControlLib::setQtListData()
{
//#if !defined(SIMULATOR)
	if( True == m_bl_isNowShownBroadCastPad ) {
		PnlComMtuiIf_BroadcastListModel::instance()->clear();
		PnlComMtuiIf_BroadcastPadView::instance()->selectAll( False );
		memset( &m_st_selectAddressInfo, 0x00, sizeof( m_st_selectAddressInfo ) );

		TYPC_BroadcastAddress* pc_BroadcastAddress = PnlComGetBroadcastAdress();
		// モデル設定.
		for( short ss_i = 0 ; pc_BroadcastAddress->getBroadcastAddressCount() > ss_i ; ss_i++ ) {
			// 表示対象となる宛先情報の取得.
			TYPS_AddressInfo st_AddressInfo;
			memset( &st_AddressInfo, 0x00, sizeof( st_AddressInfo ) );
			pc_BroadcastAddress->getUniqueBroadcastAddressInfo( st_AddressInfo, (ushort)( ss_i + 1 ) );

			setModelData( st_AddressInfo );
		}
		PnlComMtuiIf_BroadcastListModel::instance()->submitDatas();
	}
//#endif
}
//================================================================================================.
//	概要    ：同報宛先パッド管理クラス 入力中ファクスアドレスの更新.
// 戻り値	: なし.
//================================================================================================.
void PNLC_BroadcastPadControlLib::updataFaxAddress()
{
//#if !defined(SIMULATOR)
	if( True == m_bl_isNowShownBroadCastPad ) {
		TYPC_BroadcastAddress* pc_BroadcastAddress = PnlComGetBroadcastAdress();
		ushort us_broadcastAddressCount = pc_BroadcastAddress->getBroadcastAddressCount();
		// 表示対象となる宛先情報の取得.
		TYPS_AddressInfo st_AddressInfo;
		memset( &st_AddressInfo, 0x00, sizeof( st_AddressInfo ) );
		// 最終リスト情報を取得する.
		pc_BroadcastAddress->getUniqueBroadcastAddressInfo( st_AddressInfo, us_broadcastAddressCount );
		setModelData( st_AddressInfo , True , (ushort)( us_broadcastAddressCount - 1 ) );
		PnlComMtuiIf_BroadcastListModel::instance()->submitDatas();
	}
//#endif
}
