//================================================================================================.
//	概要    ：同報宛先パッド管理クラス 対象画面終了処理.
// 戻り値	: なし.
//================================================================================================.
void PNLC_BroadcastPadControlLib::endBroadcastListGamen()
{
//#if !defined(SIMULATOR)
	if( True == m_bl_isNowShownBroadCastPad ) {
		PBasicMessageProc* pc_nextGamen = PBasicMessageProc::getNextGamen();
		PBasicMessageProc* pc_nowGamen = PBasicMessageProc::getNowGamen();
		PNLC_PopupListControl* pc_PopupListControl = PNLC_PopupListControl::newInstance();
		if( NULL == pc_PopupListControl ) {
			LOGF_debug_PutEventLog( LOGF_DEBUG_EVENT_KIND_ALL, 0, LOGD_DEBUG_LEVEL_UNKNOWN, "Assert Failed!" );
			return;
		}
		PLayerControl* pc_nextPopup = pc_PopupListControl->getNextPopup();
		if( NULL != pc_nextGamen ) {
			// 次画面が存在するとき.
			PNLE_BroadcastGamenAppType e_nowGamenType = PNLE_BroadcastGamenAppType_Other;
			PNLE_BroadcastGamenAppType e_nextGamenType = PNLE_BroadcastGamenAppType_Other;
			for( uchar uc_i = 0; uc_broadcastPadBaseGamenTblSize > uc_i ; uc_i++ ) {
				if( pc_nowGamen == st_broadcastPadBaseGamenTbl[ uc_i ].pc_gamen ) {
					e_nowGamenType = st_broadcastPadBaseGamenTbl[ uc_i ].e_appType;
				}
				if( pc_nextGamen == st_broadcastPadBaseGamenTbl[ uc_i ].pc_gamen ) {
					e_nextGamenType = st_broadcastPadBaseGamenTbl[ uc_i ].e_appType;
				}
			}
			if( e_nowGamenType != e_nextGamenType
			    || onlyPanel.getFaxAppMode() != m_bl_isFaxOnlyModeNowGamen 		// comment 2014/09/19 OPS1-Sky東島 [ZeusS][UV-01439].
			    || PNLE_BroadcastGamenAppType_Other == e_nextGamenType ) {
				// 次画面が対象画面ではない またはアプリ種別が異なるときは同報宛先パッドを終了させる.l
				endBroadcastPad();
			} else {
				PnlComMtuiIf_BroadcastPadView::instance()->hide();
				return;
			}
		} else if( NULL != pc_nextPopup ) {
			// 次ポップアップ画面が存在するとき.
			for( uchar uc_i = 0; uc_broadcastPadPopupGamenTblSize > uc_i ; uc_i++ ) {
				if( pc_nextPopup == c_BroadcastPadPopupGamenTbl[ uc_i ] ) {
					// 次ポップアップが対象画面のとき.
					PnlComMtuiIf_BroadcastPadView::instance()->hide();
					return;
				}
			}
			endBroadcastPad();
		} else {
			// 次画面、次ポップ画面どちらも存在しないとき
			PLayerControl* pc_SrcPopup = pc_PopupListControl->getSrcPopup();
			if( NULL != pc_SrcPopup ) {
				for( uchar uc_i = 0; uc_broadcastPadPopupGamenTblSize > uc_i ; uc_i++ ) {
					if( pc_SrcPopup == c_BroadcastPadPopupGamenTbl[ uc_i ] ) {
						// 前ポップアップが対象画面のとき.
						PnlComMtuiIf_BroadcastPadView::instance()->hide();
						return;
					}
				}
				endBroadcastPad();
			} else {
				PnlComMtuiIf_BroadcastPadView::instance()->hide();
			}
		}
	}
//#endif
}

//================================================================================================.
//	概要    ：同報宛先パッド管理クラス 対象画面非アクティブ処理.
// 戻り値	: なし.
//================================================================================================.
void PNLC_BroadcastPadControlLib::inactivateBroadcastListGamen()
{
//#if !defined(SIMULATOR)
	if( True == m_bl_isNowShownBroadCastPad ) {
		PNLC_PopupListControl* pc_PopupListControl = PNLC_PopupListControl::newInstance();
		if( NULL == pc_PopupListControl ) {
			LOGF_debug_PutEventLog( LOGF_DEBUG_EVENT_KIND_ALL, 0, LOGD_DEBUG_LEVEL_UNKNOWN, "Assert Failed!" );
			return;
		}
		PLayerControl* pc_nextPopup = pc_PopupListControl->getNextPopup();

		if( NULL != dynamic_cast< PPopupPullDownCom* >( pc_nextPopup ) ) {
			// 次ポップアップがプルダウンの場合.
			PnlComMtuiIf_BroadcastPadView::instance()->hide();
			return;
		}

		if( NULL != pc_nextPopup ) {
			// 次ポップアップ画面が存在するとき.
			for( uchar uc_i = 0; uc_broadcastPadPopupGamenTblSize > uc_i ; uc_i++ ) {
				if( pc_nextPopup == c_BroadcastPadPopupGamenTbl[ uc_i ] ) {
					// 次ポップアップが対象画面のとき.
					PnlComMtuiIf_BroadcastPadView::instance()->hide();
					return;
				}
			}
			endBroadcastPad();
		}
	}
//#endif
}

