//================================================================================================.
//	概要    ：同報宛先パッド管理クラス 同報宛先リストの選択.
// 戻り値	: なし.
//================================================================================================.
void PNLC_BroadcastPadControlLib::procBroadCastList( short ss_option )
{
//#if !defined(SIMULATOR)
	TYPC_BroadcastAddress* pc_BroadcastAddress = PnlComGetBroadcastAdress();
	if( pc_BroadcastAddress->getBroadcastAddressIndex( m_st_selectAddressInfo ) == ss_option + 1 ) {
		// 選択中のリストを選択した場合は解除する.
		memset( &m_st_selectAddressInfo, 0x00, sizeof( m_st_selectAddressInfo ) );
		PnlComMtuiIf_BroadcastPadView::instance()->select( ss_option , False );
	} else {
		memset( &m_st_selectAddressInfo, 0x00, sizeof( m_st_selectAddressInfo ) );
		pc_BroadcastAddress->getUniqueBroadcastAddressInfo( m_st_selectAddressInfo  , (ushort)( ss_option + 1 ) );
		PnlComMtuiIf_BroadcastPadView::instance()->select( ss_option , True );
	}
//#endif
}

