//================================================================================================.
//	概要    ：同報宛先パッド管理クラス 削除キー押下動作.
// 戻り値	: なし.
//================================================================================================.
void PNLC_BroadcastPadControlLib::procDeleteKey()
{
//#if !defined(SIMULATOR)
	APIC_Job* pc_JobFax = PnlComGetJobScanFax();
	if( ( NULL == pc_JobFax ) ||
	    ( NULL == pc_JobFax->getJobSpec() ) ||
	    ( NULL == pc_JobFax->getJobSpec()->pc_Send ) )
	{
		LOGF_debug_PutEventLog( LOGF_DEBUG_EVENT_KIND_ALL, 0, LOGD_DEBUG_LEVEL_UNKNOWN, "[PCGC_ConfirmReadSet_scanfax::clearAddress]Assert Failed!" );
		return;
	}
	TYPC_BroadcastAddress* pc_BroadcastAddress = PnlComGetBroadcastAddressForSend();
	if( NULL == pc_BroadcastAddress ) { LOGF_debug_PutEventLog( LOGF_DEBUG_EVENT_KIND_ALL, 0, LOGD_DEBUG_LEVEL_UNKNOWN, "Assert Failed!" ); return; }
	ushort us_selectIndex = pc_BroadcastAddress->getBroadcastAddressIndex( m_st_selectAddressInfo );
	if( 0 == us_selectIndex ) {
		// 宛先を選択していない場合は拒否音を鳴らす.
		PBasicMessageProc::setBuzzerType( PCGE_BuzzerType_InputNg );
		return;
	}
	TYPC_ComSend* pc_ComSend = &( pc_JobFax->getJobSpec()->pc_Send->c_ComSend );

	TYPS_AddressInfo s_AddressInfo;
	memset( &s_AddressInfo, 0x00, sizeof( s_AddressInfo ) );
	pc_BroadcastAddress->getUniqueBroadcastAddressInfo( s_AddressInfo, us_selectIndex );	// 宛先情報を取得.

	if( False == s_AddressInfo.b_Direct ) {		// 短縮宛先のクリア.
		TYPC_ShorteningAddress* pc_ShorteningAddress = pc_ComSend->searchShorteningAddressByDbRecordNo( s_AddressInfo.ul_LeftRecodeId );
		if( NULL == pc_ShorteningAddress ) { LOGF_debug_PutEventLog( LOGF_DEBUG_EVENT_KIND_ALL, 0, LOGD_DEBUG_LEVEL_UNKNOWN, "Assert Failed!" ); return; }
		if( TYPE_SendModeBox == pc_ShorteningAddress->getSendMode() ) {
			pc_ComSend->decrementSelectBoxCount();
		}
		pc_ComSend->setShorteningAddress( pc_ShorteningAddress, False );
		pc_BroadcastAddress->setShorteningAddressIGC( s_AddressInfo.ul_LeftRecodeId, False );
	} else {										// 直接入力宛先のクリア.
		TYPC_DirectAddressBook* pc_DirectAddressBook = &( pc_JobFax->getJobSpec()->pc_Send->c_ComSend.c_DirectAddressBook );
		switch( s_AddressInfo.e_SendMode ) {
			case TYPE_SendModeFax:				// 宛先種別：Ｇ３ＦＡＸ送信.
				if( True == pc_DirectAddressBook->pageFaxAddress( s_AddressInfo.ss_AddressNo )->getOn() ) {
					ushort	us_DirectIndexNo = PNLC_ScanFaxDataLib::newInstance()->getDirectIndexNo();	// ダイレクト入力宛先格納番号.
					pc_DirectAddressBook->pageFaxAddress( s_AddressInfo.ss_AddressNo )->setOn( False );
					pc_DirectAddressBook->decrementSelectCount();
					pc_BroadcastAddress->setDirectAddress( s_AddressInfo.ss_AddressNo, s_AddressInfo.e_SendMode, False );
					if( us_DirectIndexNo == s_AddressInfo.ss_AddressNo ) {
						// 現在入力中の宛先と削除宛先が一致した場合はダイレクト入力宛先格納番号を更新する.
						PNLC_ScanFaxDataLib::newInstance()->setDirectIndexNo( PNLD_DirectIndexNon );
						for( short ss_j = 1; TYPD_MaxDirectFaxAddress >= ss_j; ++ss_j ) {
							if( pc_DirectAddressBook->pageFaxAddress( ss_j )->getOn() == False ) {
								PNLC_ScanFaxDataLib::newInstance()->setDirectIndexNo( ( ushort )ss_j );
								break;
							}
						}
					}
				}
				break;
			case TYPE_SendModeIfax:				// 宛先種別：Ｉ－ＦＡＸ送信.
			case TYPE_SendModeEmail:			// 宛先種別：Ｅ－Ｍａｉｌ送信.
			case TYPE_SendModeIPAddressFax:		// 宛先種別：ＩＰアドレスＦＡＸ送信.
				if( True == pc_DirectAddressBook->pageMailAddress( s_AddressInfo.ss_AddressNo )->getOn() ) {
					// ダイレクト宛先（メール宛先、I-FAX送信）の設定解除.
					pc_DirectAddressBook->pageMailAddress( s_AddressInfo.ss_AddressNo )->setOn( False );
					if( TYPE_SendModeIfax == s_AddressInfo.e_SendMode ) {
						pc_DirectAddressBook->pageMailAddress( s_AddressInfo.ss_AddressNo )->setIfaxSendInfo( c_JobControl.getDefaultIfaxPartnerReceptAbility() );
					}
					pc_DirectAddressBook->decrementSelectCount();
					pc_BroadcastAddress->setDirectAddress( s_AddressInfo.ss_AddressNo, s_AddressInfo.e_SendMode, False );
				}
				break;
			case TYPE_SendModeFtp:				// 宛先種別：ＦＴＰ送信.
				if( True == pc_DirectAddressBook->pageFtpAddress( s_AddressInfo.ss_AddressNo )->getOn() ) {
					pc_DirectAddressBook->pageFtpAddress( s_AddressInfo.ss_AddressNo )->setOn( False );
					pc_DirectAddressBook->decrementSelectCount();
					pc_BroadcastAddress->setDirectAddress( s_AddressInfo.ss_AddressNo, s_AddressInfo.e_SendMode, False );
				}
				break;
			case TYPE_SendModeSmb:				// 宛先種別：ＳＭＢ送信.
				if( True == pc_DirectAddressBook->pageSmbAddress( s_AddressInfo.ss_AddressNo )->getOn() ) {
					pc_DirectAddressBook->pageSmbAddress( s_AddressInfo.ss_AddressNo )->setOn( False );
					pc_DirectAddressBook->decrementSelectCount();
					pc_BroadcastAddress->setDirectAddress( s_AddressInfo.ss_AddressNo, s_AddressInfo.e_SendMode, False );
				}
				break;
			case TYPE_SendModeBox:				// 宛先種別：ＢＯＸ送信.
				if( True == pc_DirectAddressBook->pageBoxAddress( s_AddressInfo.ss_AddressNo )->getOn() ) {
					if( True == isOn( CNK_FilingNumber, pc_JobFax ) ) {
						APIS_FilingNoBoxStruct s_FilingNoBox;
						memset( &s_FilingNoBox, 0, sizeof( APIS_FilingNoBoxStruct ) );
						// 指定したボックス番号がファイリングナンバー設定の場合でかつ、他のボックスにファイリングナンバー設定がされていない場合のみ解除.
						if( APID_DocapiMethodOk == cp_BoxList->FilingBoxInfoAction( pc_DirectAddressBook->pageBoxAddress( s_AddressInfo.ss_AddressNo )->getBoxAddress().sl_BoxNo, 2 ,&s_FilingNoBox ) ) {
							cancel( CNK_FilingNumber, CNK_Size, pc_JobFax );
						}
					}
					pc_DirectAddressBook->pageBoxAddress( s_AddressInfo.ss_AddressNo )->setOn( False );
					TYPS_BoxAddress s_BoxAddress = pc_DirectAddressBook->pageBoxAddress( s_AddressInfo.ss_AddressNo )->getBoxAddress();
					s_BoxAddress.sl_BoxNo = DOCD_BoxIdDefault;
					memset( s_BoxAddress.sc_BoxNameUTF8, '\0', sizeof( s_BoxAddress.sc_BoxNameUTF8 ) );
					pc_DirectAddressBook->pageBoxAddress( s_AddressInfo.ss_AddressNo )->setBoxAddress( s_BoxAddress );
					pc_DirectAddressBook->decrementSelectCount();
					pc_ComSend->decrementSelectBoxCount();
					pc_BroadcastAddress->setDirectAddress( s_AddressInfo.ss_AddressNo, s_AddressInfo.e_SendMode, False );
				}
				break;
			case TYPE_SendModeWebDav:			// 宛先種別：ＷｅｂＤＡＶ送信.
				if( True == pc_DirectAddressBook->pageWebDavAddress( s_AddressInfo.ss_AddressNo )->getOn() ) {
					pc_DirectAddressBook->pageWebDavAddress( s_AddressInfo.ss_AddressNo )->setOn( False );
					pc_DirectAddressBook->decrementSelectCount();
					pc_BroadcastAddress->setDirectAddress( s_AddressInfo.ss_AddressNo, s_AddressInfo.e_SendMode, False );
				}
				break;
			case TYPE_SendModeNotSetting:		// 宛先種別：未設定状態.
			case TYPE_SendModeUsbMem:			// 宛先種別：ＵＳＢメモリ送信.
			default:	LOGF_debug_PutEventLog( LOGF_DEBUG_EVENT_KIND_ALL, 0, LOGD_DEBUG_LEVEL_UNKNOWN, "Assert Failed!" );	return;
		}
	}

	pc_PanelMain->DeleteBroadcastAddressIndi( ( int32_t )s_AddressInfo.e_SendMode ); // 同報宛先削除通知.
//#endif
// comment 2019/10/17 sky-tobita [EagleBK][OP_BTS-12044]ファクス送信不可制御修正.
	TYPS_FaxAddress s_FaxAddress;
	memset( s_FaxAddress.sc_DialNo, '\0', sizeof( s_FaxAddress.sc_DialNo ) );
	TYPC_DirectAddressBook* pc_DirectAddressBook = &( pc_JobFax->getJobSpec()->pc_Send->c_ComSend.c_DirectAddressBook );
	Bool bl_RegisterNumberProhibition = False;
	if( NULL != pc_DirectAddressBook ) {
		for( ushort us_count = 1 ; getSelectTotalAddressCount() > us_count ; us_count++ ) {
			pc_BroadcastAddress->getUniqueBroadcastAddressInfo( s_AddressInfo, us_count );
			s_FaxAddress = pc_DirectAddressBook->pageFaxAddress( s_AddressInfo.ss_AddressNo )->getFaxAddress();
			if( True == PnlComIsGetFaxPanelSetting( s_FaxAddress.sc_DialNo ) ) {
				bl_RegisterNumberProhibition = True;
				break;
			}
		}
	}
	if( False == bl_RegisterNumberProhibition ) {
		onlyPanel.m_bl_RegisterNumberProhibition = False;
	}
}

