// 2014/04/30 OPS1-Sky東島 [Minerva5th][UV-01425] ペアリング用QRコード生成機能対応.
PSinglePartsRawGraphic* PCGC_QRCodeControl::m_pc_PartsPointer = NULL;
Bool PCGC_QRCodeControl::m_bl_NowRequest = False;
char PCGC_QRCodeControl::m_sc_QRCodeBuf[ PCGD_QRCodeImageBufferSize ];
//================================================================================================.
//	概要    ：QRコード取得管理クラス コンストラクタ.
//================================================================================================.
PCGC_QRCodeControl::PCGC_QRCodeControl()
{
	memset( m_sc_QRCodeBuf, 0x00, PCGD_QRCodeImageBufferSize );
}

//================================================================================================.
//	概要    ：QRコード取得管理クラス インスタンス取得.
// 戻り値	: インスタンス.
//================================================================================================.
PCGC_QRCodeControl* PCGC_QRCodeControl::newInstance()
{
	static PCGC_QRCodeControl c_QRCodeControl;
	return &c_QRCodeControl;
}

//================================================================================================.
//	概要    ：QRコード取得管理クラス  QRコード画像データ取得応答.
//================================================================================================.
void PCGC_QRCodeControl::ans_getQRcodeData( TYPS_QRcodeImagePara st_QRCodeImagePara )
{
	m_bl_NowRequest = False;	// 待機中を設定.
	// 返却された値をチェック.
	if( ( TYPE_QRcodeResult_NG == st_QRCodeImagePara.e_Result )							// 結果が失敗の場合.
	    || ( st_QRCodeImagePara.psc_ImageDataPointer != &m_sc_QRCodeBuf[5] )				// 先頭アドレスが要求時と異なっている場合.
	    || ( st_QRCodeImagePara.ul_ImageDataPointerSize > PCGD_QRCodeImageSize ) ) {		// 出力画像サイズが要求時より大きい場合.
		LOGF_debug_PutEventLog( LOGF_DEBUG_EVENT_KIND_ALL, 0, LOGD_DEBUG_LEVEL_UNKNOWN, "Assert Failed!" );
		// コールバックメッセージ送信.
		CallBackIndi( TYPE_PNL_CallBack_GetQRCodeResult_NG );
		return;
	}
	// ヘッダ情報を設定.
	char sc_HeaderBuf[5];
	memset( sc_HeaderBuf, 0 , sizeof(sc_HeaderBuf) );
	// Xサイズ格納.
	sc_HeaderBuf[0] = ( char )( st_QRCodeImagePara.ss_ImageDotSizeWidth >> 8 );
	sc_HeaderBuf[1] = (char)( st_QRCodeImagePara.ss_ImageDotSizeWidth & 0xff );
	// Yサイズ格納.
	sc_HeaderBuf[2] = ( char )( st_QRCodeImagePara.ss_ImageDotSizeHeight >> 8 );
	sc_HeaderBuf[3] = (char)( st_QRCodeImagePara.ss_ImageDotSizeHeight & 0xff );
	// カラー情報.
	sc_HeaderBuf[4] = UC_GPARTS_COLORNUMBER_256COLOR;
	memcpy( m_sc_QRCodeBuf, sc_HeaderBuf, sizeof( sc_HeaderBuf ) );
	CallBackIndi( TYPE_PNL_CallBack_GetQRCodeResult_OK );

}

//================================================================================================.
//	概要    ：QRコード取得管理クラス  QRコード取得要求処理.
//	引数    ： char* sc_Message					: 文字列情報.
//		    ：PSinglePartsRawGraphic* pc_PartsPointer		: 取得画像設定用パーツポインタ.
//================================================================================================.
Bool PCGC_QRCodeControl::getQRCodeImage( char* sc_Message , PSinglePartsRawGraphic* pc_PartsPointer )
{
	if( NULL == sc_Message
	    || NULL == pc_PartsPointer ) {
		LOGF_debug_PutEventLog( LOGF_DEBUG_EVENT_KIND_ALL, 0, LOGD_DEBUG_LEVEL_UNKNOWN, "Assert Failed!" );
		return False;
	}
	// 取得中の場合は何もしない.
	if( True == m_bl_NowRequest ) {
		return False;
	}

	uint32_t ui32_MessageSize = ( uint32_t )strlen( sc_Message );
	// 文字列がない場合は失敗を返却.
	if( 0 == ui32_MessageSize ) {
		LOGF_debug_PutEventLog( LOGF_DEBUG_EVENT_KIND_ALL, 0, LOGD_DEBUG_LEVEL_UNKNOWN, "Assert Failed!" );
		return False;
	}

	APIC_PreviewConverter* pc_PreviewConverter = APIC_PreviewConverter::newInstance();
	if( NULL == pc_PreviewConverter ) {
		LOGF_debug_PutEventLog( LOGF_DEBUG_EVENT_KIND_ALL, 0, LOGD_DEBUG_LEVEL_UNKNOWN, "Assert Failed!" );
		return False;
	}
	memset( m_sc_QRCodeBuf, 0x00, PCGD_QRCodeImageBufferSize );
	m_pc_PartsPointer = pc_PartsPointer;

	TYPS_ReqQRcodePara st_QRCodePara;
	memset( &st_QRCodePara, 0x00, sizeof( st_QRCodePara ) );

	st_QRCodePara.psc_QRcodeData				= sc_Message;					// 文字列.
	st_QRCodePara.ul_QRcodeDataSize				= ui32_MessageSize;				// 文字列サイズ.
	st_QRCodePara.psc_ImageDataPointer			= &m_sc_QRCodeBuf[5];			// 画像エリア先頭アドレス.
	st_QRCodePara.ul_ImageDataPointerSize		= PCGD_QRCodeImageSize;			// 画像サイズ.

	pc_PreviewConverter->req_getQRcodeData( &st_QRCodePara , ans_getQRcodeData );		// QRコード画像生成の要求.

	m_bl_NowRequest = True;		// 取得中を設定.
	return True;
}

//================================================================================================.
//	概要    ：QRコード取得管理クラス  QRコード表示要求処理.
//================================================================================================.
void PCGC_QRCodeControl::showQRCodeImage()
{
	// 取得中の場合は何もしない.
	if( True == m_bl_NowRequest ) {
		return;
	}
	// パーツが設定されていない場合は何もしない.
	if( NULL == m_pc_PartsPointer ) {
		return;
	}
	// カラー情報が設定されていない場合は何もしない.
	if( 0x00 == m_sc_QRCodeBuf[4] ) {
		return;
	}
	// パーツに画像を設定する.
	m_pc_PartsPointer->changeRawGraphic( ( const uchar* )m_sc_QRCodeBuf );
}

uchar PnlComGetCardTypeAndroidCheck()
{
	uchar uc_ret = PNLD_CardType_NonAndorid;
	APIC_AuthDeviceCommon* pc_AuthDeviceCommon = PnlComGetAuthDeviceCommon();
	if( NULL == pc_AuthDeviceCommon ) { return uc_ret ;}
	// 設定されているカードタイプを取得.
	uint32_t ui32_CardTypes[UACD_AUTH_ICC_CARD_TYPE_PARAMS_MAX];
	memset( ui32_CardTypes, 0x00, sizeof( ui32_CardTypes ) );
	uchar uc_NumCardTypes = 0;
	// 設定されているカードタイプを取得.
	pc_AuthDeviceCommon->getAuthIccCardTypeGet( ui32_CardTypes,						// [O]カードタイプ種別を受けとる配列.
	        UACD_AUTH_ICC_CARD_TYPE_PARAMS_MAX,	// [I]配列サイズ.
	        &uc_NumCardTypes );					// [O]受け取ったカードタイプの数.
	Bool bl_TypeAndroid = False;
	for( uchar uc_loop = 0; uc_loop < uc_NumCardTypes; uc_loop++ ) {
		switch( ui32_CardTypes[uc_loop] ) {
			case TYPE_ConfigCardType_Android:
				bl_TypeAndroid = True;
				break;
			default:
				break;
		}
	}
	if( 1 == uc_NumCardTypes && True == bl_TypeAndroid ) {
		uc_ret = PNLD_CardType_Andorid;
	} else if( 2 == uc_NumCardTypes && True == bl_TypeAndroid ) {
		uc_ret = PNLD_CardType_Andorid_ICCard;
	} else {
		uc_ret = PNLD_CardType_NonAndorid;
	}
	return uc_ret;
}
