//================================================================================================.
//	概要    ：クラウド接続設定データ管理クラス : クラウド接続設定/XMPP設定情報 取得.
//================================================================================================.
void PNLC_CloudConnectSettingData::loadXmppSetting()
{
	// 初期化要否フラグ判定.
	if( False == isCloudConnectSubSettingInitialize() ) {	// 初期化不要の場合.
		return;
	}

	// APIC_SaaSGatewayInfoクラスのインスタンス取得.
	APIC_SaaSGatewayInfo* pc_SaaSGatewayInfo = APIC_SaaSGatewayInfo::newInstance();
	if( NULL == pc_SaaSGatewayInfo ) { LOGF_debug_PutEventLog( LOGF_DEBUG_EVENT_KIND_ALL, 0, LOGD_DEBUG_LEVEL_UNKNOWN, "Assert Failed!" ); return; }

	// 設定領域クリア.
	memset( m_sc_preXmppDomainName, '\0', sizeof( m_sc_preXmppDomainName ) );

	// 設定領域クリア(更新用).
	memset( m_sc_XmppDomainName, '\0', sizeof( m_sc_XmppDomainName ) );

	// 外部の取得APIから接続設定情報を取得.
	m_us_preXmppBoshPort = pc_SaaSGatewayInfo->getXMPP_BoshPort();			// BOSH通信ポート ポート番号.
	m_us_preXmppBoshSslPort = pc_SaaSGatewayInfo->getXMPP_BoshPortSSL();	// BOSH通信ポート SSLポート番号.
	pc_SaaSGatewayInfo->getXMPP_DomainName( m_sc_preXmppDomainName );		// サービス名.
	m_us_preXmppNonBoshPort = pc_SaaSGatewayInfo->getXMPP_Port();			// 非BOSH通信ポート ポート番号.
	m_us_preXmppNonBoshSslPort = pc_SaaSGatewayInfo->getXMPP_PortSSL();		// 非BOSH通信ポート SSLポート番号.
	m_us_preXmppSrvcertOfXmpp = pc_SaaSGatewayInfo->getSrvcertOfXMPP();		// 証明書検証強度(有効期限/鍵使用法/チェーン/失効確認).
	m_us_preXmppNotifiInterval = pc_SaaSGatewayInfo->getXMPP_Polling();		// サービス通知間隔.
	m_us_preXmppTimeout = pc_SaaSGatewayInfo->getXMPP_Timeout();			// タイムアウト時間.
	m_uc_preXmppRetryCount  = pc_SaaSGatewayInfo->getXMPP_RetryCount();		// リトライ回数.

	// 更新用領域にコピー.
	m_us_XmppBoshPort = m_us_preXmppBoshPort;													// BOSH通信ポート ポート番号.
	m_us_XmppBoshSslPort = m_us_preXmppBoshSslPort;												// BOSH通信ポート SSLポート番号.
// comment 2018/01/19 【HCL-Rajesh】 [IT5_4.2] Klockwork Changes ID: 396023 [SV.STRBO.BOUND_COPY.UNTERM].
//	strncpy( m_sc_XmppDomainName, m_sc_preXmppDomainName, sizeof( m_sc_XmppDomainName ) );		// サービス名.
	strncpy( m_sc_XmppDomainName, m_sc_preXmppDomainName, sizeof( m_sc_XmppDomainName ) - 1 );		// サービス名.
	m_us_XmppNonBoshPort = m_us_preXmppNonBoshPort;												// 非BOSH通信ポート ポート番号.
	m_us_XmppNonBoshSslPort = m_us_preXmppNonBoshSslPort;										// 非BOSH通信ポート SSLポート番号.
	m_us_XmppSrvcertOfXmpp = m_us_preXmppSrvcertOfXmpp;											// 証明書検証強度(有効期限/鍵使用法/チェーン/失効確認).
	m_us_XmppNotifiInterval = m_us_preXmppNotifiInterval;										// サービス通知間隔.
	m_us_XmppTimeout = m_us_preXmppTimeout;														// タイムアウト時間.
	m_uc_XmppRetryCount = m_uc_preXmppRetryCount;												// リトライ回数.

	// 初期化要否フラグにFalseを設定.
	setCloudConnectSubSettingInitialize( False );
}
