void PNLC_CloudConnectSettingData::loadHttpTunnelSetting()
{
	// 初期化要否フラグ判定.
	if( False == isCloudConnectSubSettingInitialize() ) {	// 初期化不要の場合.
		return;
	}

	// APIC_SaaSGatewayInfoクラスのインスタンス取得.
	APIC_SaaSGatewayInfo* pc_SaaSGatewayInfo = APIC_SaaSGatewayInfo::newInstance();
	if( NULL == pc_SaaSGatewayInfo ) { LOGF_debug_PutEventLog( LOGF_DEBUG_EVENT_KIND_ALL, 0, LOGD_DEBUG_LEVEL_UNKNOWN, "Assert Failed!" ); return; }

	// クラウド接続設定/HTTPトンネル設定情報を取得する.
	m_us_preHttpTunnelTimeout         = pc_SaaSGatewayInfo->getTunnelTimeout();
	m_us_preHttpTunnelDeviceTimeout   = pc_SaaSGatewayInfo->getDeviceTimeout();
	m_us_preHttpTunnelSrvcertOfTunnel = pc_SaaSGatewayInfo->getSrvcertOfTunnel();
	m_us_preHttpTunnelSrvcertOfServer = pc_SaaSGatewayInfo->getSrvcertOfServer();
	m_us_preHttpTunnelSrvcertOfClient = pc_SaaSGatewayInfo->getSrvcertOfClient();

	// 取得した設定値を設定更新用のメンバ変数にコピーする.
	m_us_HttpTunnelTimeout         = m_us_preHttpTunnelTimeout;
	m_us_HttpTunnelDeviceTimeout   = m_us_preHttpTunnelDeviceTimeout;
	m_us_HttpTunnelSrvcertOfTunnel = m_us_preHttpTunnelSrvcertOfTunnel;
	m_us_HttpTunnelSrvcertOfServer = m_us_preHttpTunnelSrvcertOfServer;
	m_us_HttpTunnelSrvcertOfClient = m_us_preHttpTunnelSrvcertOfClient;

	// 初期化要否フラグにFalseを設定.
	setCloudConnectSubSettingInitialize( False );
}
