//================================================================================================.
void PNLC_CloudConnectSettingData::loadProxySetting()
{
	// 初期化要否フラグ判定.
	if( False == isCloudConnectSubSettingInitialize() ) {	// 初期化不要の場合.
		return;
	}

	// APIC_SaaSGatewayInfoクラスのインスタンス取得.
	APIC_SaaSGatewayInfo* pc_SaaSGatewayInfo = APIC_SaaSGatewayInfo::newInstance();
	if( NULL == pc_SaaSGatewayInfo ) { LOGF_debug_PutEventLog( LOGF_DEBUG_EVENT_KIND_ALL, 0, LOGD_DEBUG_LEVEL_UNKNOWN, "Assert Failed!" ); return; }

	// 読込値のメンバ変数をクリアする.
	memset( m_sc_preProxyAddress, '\0', sizeof( m_sc_preProxyAddress ) );
	memset( m_sc_preProxyUser, '\0', sizeof( m_sc_preProxyUser ) );
	memset( m_sc_preProxyPassword, '\0', sizeof( m_sc_preProxyPassword ) );

	// クラウド接続設定/プロキシ設定情報を取得する.
	m_bl_preProxyEnable = pc_SaaSGatewayInfo->getPROXY_Enable();
	m_bl_preProxyExtractWebDavClientEnable = pc_SaaSGatewayInfo->getExtractWebDAVClientSetting();
	pc_SaaSGatewayInfo->getPROXY_Address( m_sc_preProxyAddress );
	m_us_preProxyPort = pc_SaaSGatewayInfo->getPROXY_Port();
	pc_SaaSGatewayInfo->getPROXY_User( m_sc_preProxyUser );
	pc_SaaSGatewayInfo->getPROXY_Password( m_sc_preProxyPassword );

	// 更新値のメンバ変数をクリアする.
	memset( m_sc_ProxyAddress, '\0', sizeof( m_sc_ProxyAddress ) );
	memset( m_sc_ProxyUser, '\0', sizeof( m_sc_ProxyUser ) );
	memset( m_sc_ProxyPassword, '\0', sizeof( m_sc_ProxyPassword ) );

	// 読込値を更新値のメンバ変数にコピーする.
	m_bl_ProxyEnable = m_bl_preProxyEnable;
	m_bl_ProxyExtractWebDavClientEnable = m_bl_preProxyExtractWebDavClientEnable;
// comment 2018/01/19 【HCL-Rajesh】 [IT5_4.2] Klockwork Changes ID: 396023 [SV.STRBO.BOUND_COPY.UNTERM].
//	strncpy( m_sc_ProxyAddress, m_sc_preProxyAddress, sizeof( m_sc_ProxyAddress ) );
	strncpy( m_sc_ProxyAddress, m_sc_preProxyAddress, sizeof( m_sc_ProxyAddress ) - 1 );
	m_us_ProxyPort = m_us_preProxyPort;
// comment 2018/01/19 【HCL-Rajesh】 [IT5_4.2] Klockwork Changes ID: 396023 [SV.STRBO.BOUND_COPY.UNTERM].
//	strncpy( m_sc_ProxyUser, m_sc_preProxyUser, sizeof( m_sc_ProxyUser ) );
	strncpy( m_sc_ProxyUser, m_sc_preProxyUser, sizeof( m_sc_ProxyUser ) - 1 );
// comment 2018/02/16 【HCL-Neeraj】 [IT5_4.2] Klockwork Changes ID: 396023 [SV.STRBO.BOUND_COPY.UNTERM].
//	strncpy( m_sc_ProxyPassword, m_sc_preProxyPassword, sizeof( m_sc_ProxyPassword ) );
	strncpy( m_sc_ProxyPassword, m_sc_preProxyPassword, sizeof( m_sc_ProxyPassword ) - 1 );

	// 初期化要否フラグにFalseを設定.
	setCloudConnectSubSettingInitialize( False );
}
