//================================================================================================.
//	概要    ：クラウド接続設定データ管理クラス : クラウド接続設定/XMPP設定情報 設定.
//================================================================================================.
void PNLC_CloudConnectSettingData::commitXmppSetting()
{
	// APIC_SaaSGatewayInfoクラスのインスタンス取得.
	APIC_SaaSGatewayInfo* pc_SaaSGatewayInfo = APIC_SaaSGatewayInfo::newInstance();
	if( NULL == pc_SaaSGatewayInfo ) { LOGF_debug_PutEventLog( LOGF_DEBUG_EVENT_KIND_ALL, 0, LOGD_DEBUG_LEVEL_UNKNOWN, "Assert Failed!" ); return; }

	// BOSH通信ポート ポート番号.
	if( m_us_preXmppBoshPort != m_us_XmppBoshPort ) {
		pc_SaaSGatewayInfo->setXMPP_BoshPort( m_us_XmppBoshPort );
		setSettingChanged( True );
	}

	// BOSH通信ポート SSLポート番号.
	if( m_us_preXmppBoshSslPort != m_us_XmppBoshSslPort ) {
		pc_SaaSGatewayInfo->setXMPP_BoshPortSSL( m_us_XmppBoshSslPort );
		setSettingChanged( True );
	}

	// サービス名.
	if( 0 != strncmp( m_sc_preXmppDomainName, m_sc_XmppDomainName, sizeof( m_sc_preXmppDomainName ) ) ) {
		pc_SaaSGatewayInfo->setXMPP_DomainName( m_sc_XmppDomainName );
		setSettingChanged( True );
	}

	// 非BOSH通信ポート ポート番号.
	if( m_us_preXmppNonBoshPort != m_us_XmppNonBoshPort ) {
		pc_SaaSGatewayInfo->setXMPP_Port( m_us_XmppNonBoshPort );
		setSettingChanged( True );
	}

	// 非BOSH通信ポート ポート番号.
	if( m_us_preXmppNonBoshSslPort != m_us_XmppNonBoshSslPort ) {
		pc_SaaSGatewayInfo->setXMPP_PortSSL( m_us_XmppNonBoshSslPort );
		setSettingChanged( True );
	}

	// 証明書検証強度(有効期限/鍵使用法/チェーン/失効確認).
	if( m_us_preXmppSrvcertOfXmpp != m_us_XmppSrvcertOfXmpp ) {
		TYPE_MioSettingResult e_MioSettingResult = pc_SaaSGatewayInfo->setSrvcertOfXMPP( m_us_XmppSrvcertOfXmpp );
		if( TYPE_MioSettingResultOk == e_MioSettingResult ) {	// 正常終了の場合のみ、変更ありとする.
			setSettingChanged( True );
		}
	}

	// サービス通知間隔.
	if( m_us_preXmppNotifiInterval != m_us_XmppNotifiInterval ) {
		pc_SaaSGatewayInfo->setXMPP_Polling( m_us_XmppNotifiInterval );
		setSettingChanged( True );
	}

	// タイムアウト時間.
	if( m_us_preXmppTimeout != m_us_XmppTimeout ) {
		pc_SaaSGatewayInfo->setXMPP_Timeout( m_us_XmppTimeout );
		setSettingChanged( True );
	}

	// リトライ回数.
	if( m_uc_preXmppRetryCount != m_uc_XmppRetryCount ) {
		pc_SaaSGatewayInfo->setXMPP_RetryCount( m_uc_XmppRetryCount );
		setSettingChanged( True );
	}
}
//================================================================================================.
//	概要    ：クラウド接続設定データ管理クラス : クラウド接続設定/HTTPトンネル設定情報 設定.
//================================================================================================.
void PNLC_CloudConnectSettingData::commitHttpTunnelSetting()
{
	// APIC_SaaSGatewayInfoクラスのインスタンス取得.
	APIC_SaaSGatewayInfo* pc_SaaSGatewayInfo = APIC_SaaSGatewayInfo::newInstance();
	if( NULL == pc_SaaSGatewayInfo ) { LOGF_debug_PutEventLog( LOGF_DEBUG_EVENT_KIND_ALL, 0, LOGD_DEBUG_LEVEL_UNKNOWN, "Assert Failed!" ); return; }

	// 読込時の設定値と更新後の設定値を比較し、異なる場合はクラウド接続設定/HTTPトンネル設定情報を設定する.
	// 設定後、データ変更状態を変更有にする.
	// HTTPトンネル通信タイムアウト時間.
	if( m_us_preHttpTunnelTimeout != m_us_HttpTunnelTimeout ) {
		pc_SaaSGatewayInfo->setTunnelTimeout( m_us_HttpTunnelTimeout );
		setSettingChanged( True );
	}

	// デバイスとの通信タイムアウト時間.
	if( m_us_preHttpTunnelDeviceTimeout != m_us_HttpTunnelDeviceTimeout ) {
		pc_SaaSGatewayInfo->setDeviceTimeout( m_us_HttpTunnelDeviceTimeout );
		setSettingChanged( True );
	}

	// トンネル証明書検証強度設定.
	if( m_us_preHttpTunnelSrvcertOfTunnel != m_us_HttpTunnelSrvcertOfTunnel ) {
		TYPE_MioSettingResult e_MioSettingResult = pc_SaaSGatewayInfo->setSrvcertOfTunnel( m_us_HttpTunnelSrvcertOfTunnel );
		if( TYPE_MioSettingResultOk == e_MioSettingResult ) {	// 正常終了の場合のみ、変更ありとする.
			setSettingChanged( True );
		}
	}

	// クラウド通信証明書検証強度設定.
	if( m_us_preHttpTunnelSrvcertOfServer != m_us_HttpTunnelSrvcertOfServer ) {
		TYPE_MioSettingResult e_MioSettingResult = pc_SaaSGatewayInfo->setSrvcertOfServer( m_us_HttpTunnelSrvcertOfServer );
		if( TYPE_MioSettingResultOk == e_MioSettingResult ) {	// 正常終了の場合のみ、変更ありとする.
			setSettingChanged( True );
		}
	}

	// MFP通信証明書検証強度設定.
	if( m_us_preHttpTunnelSrvcertOfClient != m_us_HttpTunnelSrvcertOfClient ) {
		TYPE_MioSettingResult e_MioSettingResult = pc_SaaSGatewayInfo->setSrvcertOfClient( m_us_HttpTunnelSrvcertOfClient );
		if( TYPE_MioSettingResultOk == e_MioSettingResult ) {	// 正常終了の場合のみ、変更ありとする.
			setSettingChanged( True );
		}
	}
}
