//================================================================================================.
//	概要    ：クラウド接続設定データ管理クラス : クラウド接続設定／XMPP設定／証明書検証強度(有効期限/鍵使用法/チェーン/失効確認) 設定.
//================================================================================================.
void PNLC_CloudConnectSettingData::setXmppSrvcertOfXmpp( ushort us_CertType, Bool bl_isCheck )
{
	//失効確認(CRL)の場合は、失効確認(OCSP)のビットも更新する.
	if( TYPD_Cert_Verify_CRL == ( us_CertType & TYPD_Cert_Verify_CRL ) ) {
		us_CertType |= TYPD_Cert_Verify_OCSP;
	//失効確認(OCSP)の場合は、失効確認(CRL)のビットも更新する.
	} else if ( TYPD_Cert_Verify_OCSP == ( us_CertType & TYPD_Cert_Verify_OCSP ) ) {
		us_CertType |= TYPD_Cert_Verify_CRL;
	}

	if( True == bl_isCheck ) {
		m_us_XmppSrvcertOfXmpp |= us_CertType;
	} else {
		m_us_XmppSrvcertOfXmpp &= (ushort)( ~us_CertType );
	}
}
//================================================================================================.
//	概要    ：クラウド接続設定データ管理クラス : クラウド接続設定／XMPP設定／証明書検証強度(有効期限/鍵使用法/チェーン/失効確認) 取得.
//	備考    ：引数で指定するビットは１つとする.
//================================================================================================.
Bool PNLC_CloudConnectSettingData::getXmppSrvcertOfXmpp( ushort us_CertType )
{
	if( 0 == ( m_us_XmppSrvcertOfXmpp & us_CertType ) ) {
		return False;
	} else {
		return True;
	}
}
//================================================================================================.
//	概要    ：クラウド接続設定データ管理クラス : クラウド接続設定／HTTPトンネル設定／トンネル証明書検証強度(有効期限/鍵使用法/チェーン/失効確認) 設定.
//================================================================================================.
void PNLC_CloudConnectSettingData::setHttpTunnelSrvcertOfTunnel( ushort us_CertType, Bool bl_isCheck )
{
	//失効確認(CRL)の場合は、失効確認(OCSP)のビットも更新する.
	if( TYPD_Cert_Verify_CRL == ( us_CertType & TYPD_Cert_Verify_CRL ) ) {
		us_CertType |= TYPD_Cert_Verify_OCSP;
	//失効確認(OCSP)の場合は、失効確認(CRL)のビットも更新する.
	} else if ( TYPD_Cert_Verify_OCSP == ( us_CertType & TYPD_Cert_Verify_OCSP ) ) {
		us_CertType |= TYPD_Cert_Verify_CRL;
	}

	if( True == bl_isCheck ) {
		m_us_HttpTunnelSrvcertOfTunnel |= us_CertType;
	} else {
		m_us_HttpTunnelSrvcertOfTunnel &= (ushort)( ~us_CertType );
	}
}
