/**
* @brief  : Paper Tray Jam Job restart request process.
* @note   : PNLC_ControlJamReleaseFlow : Job restart request.
* @param  : None.
* @return : None.
* @author : 2016/05/05 HCLT-Harish [ZuesSBK][制御構成変更_No.55].
*/
//================================================================================================.
void PNLC_ControlJamReleaseFlow::restartPaperFeedTrayJamJob()
{
	APIC_PrinterStatus* pc_PrinterStatus = APIC_PrinterStatus::newInstance();	//Get printer status.
	if( NULL == pc_PrinterStatus ) {
		LOGF_debug_PutEventLog( LOGF_DEBUG_EVENT_KIND_ALL, 0, LOGD_DEBUG_LEVEL_UNKNOWN, "Assert Failed!" );
		return;
	}

	if ( ( True == PnlComGetOperationSetting()->getPaperJamReleaseProcedureDisplay() ) 		// Paper JAM Release Display Setting Check.
			&& ( True == pc_PrinterStatus->getJAMReleaseFlag() ) ) {							// JAM Release Flag Check.

		pc_PrinterStatus->setJAMReleaseFlag(False);				// Setting PrintP JAM Release Flag  to False.

		APIC_ActiveJobList* pc_ActiveJobList = APIC_ActiveJobList::newInstance();		//Get Active Job List.
		if( NULL == pc_ActiveJobList ) {
			LOGF_debug_PutEventLog( LOGF_DEBUG_EVENT_KIND_ALL, 0, LOGD_DEBUG_LEVEL_UNKNOWN, "Assert Failed!" );
			return;
		}		
		pc_ActiveJobList->restart();			// Restart request to ActiveJob.
	}
}
