/**
		* @brief	To Decide the ADF Priority Jam in Occured Jam's.
		* @note		None.
		* @param	PNLD_ADFamJamTableIdentifier - ADF Jam Table Identifier,us_Index-To hold Index Value,PNLS_ADFJam_Position - ADF Table.
* @return : uint32_t. Will return 0 for failure case. First 2 bytes - ADF Jam Table Index. Last 2 bytes - Printer Jam Table Index.
* @author : 2016/01/01 HCLT-Vasu [ZuesSBK][RQ-438].
*/
//================================================================================================.
// comment 2016/04/21 HCLT-Juned [Rank C][ZeusSBK][CQ526966] To remove the invalid conversion from const PNLS_ADFJam_Position* to PNLS_ADFJam_Position* warning.
// void PNLC_ControlJamReleaseFlow::createImgList_ADF(PNLD_ADFamJamTableIdentifier us_TableID, ushort us_Index, PNLS_ADFJam_Position* pst_JamPosition)
void PNLC_ControlJamReleaseFlow::createImgList_ADF(PNLD_ADFamJamTableIdentifier us_TableID, ushort us_Index, const PNLS_ADFJam_Position* pst_JamPosition)
{
	if (NULL == pst_JamPosition) {
		LOGF_debug_PutEventLog( LOGF_DEBUG_EVENT_KIND_ALL, 0, LOGD_DEBUG_LEVEL_UNKNOWN, "Assert Failed!" );
		return;
	}
	//Return if the particular image is already in the imgList.
	for (int i = 0; i < imgIDListNum_ADF; i++) {
		if (pst_JamPosition->puc_JAMGuideParts == imgIDList_ADF[i].puc_Img) {
			return;
		}
	}
	if (imgIDListNum_ADF < IMG_TABLE_MAX) {
		imgIDList_ADF[imgIDListNum_ADF].us_tableID = us_TableID;
		imgIDList_ADF[i].us_Index = us_Index;
		imgIDList_ADF[i].us_JamPosition = pst_JamPosition->ADFJamPosition;
		imgIDList_ADF[imgIDListNum_ADF].puc_Img = pst_JamPosition->puc_JAMGuideParts;
		++imgIDListNum_ADF;
	} else {
		LOGF_debug_PutEventLog( LOGF_DEBUG_EVENT_KIND_ALL, 0, LOGD_DEBUG_LEVEL_UNKNOWN, "Assert Failed!" );
	}
}
//================================================================================================.
/**
		* @brief	To Decide the Printer Priority Jam in Occured Jam's.
		* @note		None.
		* @param	PNLD_PrinterJamTableIdentifier - Printer Jam Table Identifier,us_Index-To hold Index Value,PNLS_PrinterJam_Position - Printer Jam Table.
		* @return : uint32_t. Will return 0 for failure case. First 2 bytes - ADF Jam Table Index. Last 2 bytes - Printer Jam Table Index.
		* @author : 2016/01/01 HCLT-Vasu [ZuesSBK][RQ-438].
*/
//================================================================================================.
// comment 2016/04/06 HCLT-Juned [Rank B][ZeusSBK][CQ526966] To remove the invalid conversion from const PNLS_PrinterJam_Position* to PNLS_PrinterJam_Position* warning.
//void PNLC_ControlJamReleaseFlow::createImgList_Printer(PNLD_PrinterJamTableIdentifier us_TableID, ushort us_Index,  PNLS_PrinterJam_Position* pst_JamPosition)
// Comment [2017/05/12] [HCLT_Harish] [AR1018303] Added arrguments to access the table and update the value of JAM table, index in case of JAM code 1501.
//void PNLC_ControlJamReleaseFlow::createImgList_Printer(PNLD_PrinterJamTableIdentifier us_TableID, ushort us_Index, const PNLS_PrinterJam_Position* pst_JamPosition)
void PNLC_ControlJamReleaseFlow::createImgList_Printer(PNLD_PrinterJamTableIdentifier us_TableID, ushort us_Index, const PNLS_PrinterJam_Position* pst_JamPosition, 
														const PNLS_PrinterJamTable* pst_PrinterJamTable, PNLD_PrinterJamTableIdentifier& us_PrinterJamCodeTableID, 
														ushort& us_JamCodeTableIndex)
{
	APIC_PrinterWarning* pc_PrinterWarning = PnlComGetPrinterWarning();
	if (NULL == pst_JamPosition || NULL == pst_PrinterJamTable || NULL == pc_PrinterWarning) {
		LOGF_debug_PutEventLog( LOGF_DEBUG_EVENT_KIND_ALL, 0, LOGD_DEBUG_LEVEL_UNKNOWN, "Assert Failed!" );
		return;
	}
	if (pc_PrinterWarning->getPrinterJam().us_Code == pst_PrinterJamTable[us_TableID].pst_PrinterJam_Position[ us_Index ].us_JamCode) {
		us_PrinterJamCodeTableID = us_TableID;
		us_JamCodeTableIndex = us_Index;
	}
	//Return if the particular image is already in the imgList.
	for (int i = 0; i < imgIDListNum_Printer; i++) {
		if (pst_JamPosition->puc_JAMGuideParts == imgIDList_Printer[i].puc_Img) {
			return;
		}
	}
	if (imgIDListNum_Printer < IMG_TABLE_MAX) {
		imgIDList_Printer[imgIDListNum_Printer].us_tableID = us_TableID;
		imgIDList_Printer[imgIDListNum_Printer].us_Index = us_Index;
		imgIDList_Printer[imgIDListNum_Printer].us_JamPosition = pst_JamPosition->PrinterJamPosition;
		imgIDList_Printer[imgIDListNum_Printer].puc_Img = pst_JamPosition->puc_JAMGuideParts;
		++imgIDListNum_Printer;
	} else {
		LOGF_debug_PutEventLog( LOGF_DEBUG_EVENT_KIND_ALL, 0, LOGD_DEBUG_LEVEL_UNKNOWN, "Assert Failed!" );
	}
}
