/**
		* @brief	To Decide the Priority Jam to dispaly in Warning End Screen.
		* @note		None.
		* @param	PNLD_PrinterJamTableIdentifier - Printer Jam Table Identifier,us_Index-To hold Index Value,PNLS_PrinterJamTray_EndWarnInfo - End_warn Screen Image Display.
		* @return : uint32_t. Will return 0 for failure case. First 2 bytes - ADF Jam Table Index. Last 2 bytes - Printer Jam Table Index.
		* @author : 2016/01/01 HCLT-Vasu [ZuesSBK][KRQ-438].
*/
//================================================================================================.	
// comment 2016/04/06 HCLT-Juned [Rank B][ZeusSBK][CQ526966] To remove the invalid conversion from const PNLS_PrinterJamTray_EndWarnInfo* to PNLS_PrinterJamTray_EndWarnInfo* warning.
//void PNLC_ControlJamReleaseFlow::createImgList_PrinterEndWarn(PNLD_PrinterJamTableIdentifier us_TableID, ushort us_Index, PNLS_PrinterJamTray_EndWarnInfo* pst_JamPosition)
void PNLC_ControlJamReleaseFlow::createImgList_PrinterEndWarn(PNLD_PrinterJamTableIdentifier us_TableID, ushort us_Index, const PNLS_PrinterJamTray_EndWarnInfo* pst_JamPosition)
{
	if (NULL == pst_JamPosition) {
		LOGF_debug_PutEventLog( LOGF_DEBUG_EVENT_KIND_ALL, 0, LOGD_DEBUG_LEVEL_UNKNOWN, "Assert Failed!" );
		return;
	}
	//Return if the particular image is already in the imgList.
	for (int i = 0; i < imgIDListNum_Printer; i++) {
		if (pst_JamPosition->puc_WarnEndGuideParts == imgIDList_Printer[i].puc_Img) {
			return;
		}
	}
	if (imgIDListNum_Printer < IMG_TABLE_MAX) {
		imgIDList_Printer[imgIDListNum_Printer].us_tableID = us_TableID;
		imgIDList_Printer[imgIDListNum_Printer].us_Index = us_Index;
		imgIDList_Printer[imgIDListNum_Printer].us_JamPosition = -1;
		imgIDList_Printer[imgIDListNum_Printer].puc_Img = pst_JamPosition->puc_WarnEndGuideParts;
		++imgIDListNum_Printer;
	} else {
		LOGF_debug_PutEventLog( LOGF_DEBUG_EVENT_KIND_ALL, 0, LOGD_DEBUG_LEVEL_UNKNOWN, "Assert Failed!" );
	}
}
