// comment 2019/01/07 SCD2-Sky小畑 [EagleH] WebUIv3FUM対応.
// comment 2018/04/04 SCD2 Yoshinori.Yamabe[Eagle]制御構成変更_No.111 ホーム画面認証画面の新UI化対応.
//================================================================================================.
//概要    :LightUIモードを考慮した優先アプリ取得関数.
//================================================================================================.
//================================================================================================.
//TYPE_DefaultApplication PnlComGetDefaultApplication( void )
//{
//	TYPE_DefaultApplication e_DefaultApplication = TYPE_DefaultApplicationTopMenu;	// トップメニュー.
//
//	if( PNLE_UIModeLightUI != PNLC_WebUIControl::getInstance()->getUIMode() ) {		// UIのモードの取得
//		//  UIのモードがLightUIモードでは無い場合は優先機能を取得.
//		e_DefaultApplication = cp_OperationSetting->getDefaultApplication();
//	}
//	return e_DefaultApplication;
//}
PNLE_DefaultApplication PnlComGetDefaultApplication( void )
{
	PNLE_DefaultApplication e_DefaultApplication = PNLE_DefaultApplicationNone;

	if( PNLE_UIModeLightUI != PNLC_WebUIControl::getInstance()->getUIMode() ) {		// UIのモードの取得
		//  UIのモードがLightUIモードでは無い場合は優先機能を取得.
		e_DefaultApplication = cp_OperationSetting->getDefaultApplication();

		switch(e_DefaultApplication) {
			case TYPE_DefaultApplicationCopy:				// コピー.
				e_DefaultApplication = PNLE_DefaultApplicationCopy;
				break;
			case TYPE_DefaultApplicationScan:				// スキャン.
				e_DefaultApplication = PNLE_DefaultApplicationScan;
				break;
			case TYPE_DefaultApplicationFax:				// ＦＡＸ.
				e_DefaultApplication = PNLE_DefaultApplicationFax;
				break;
			case TYPE_DefaultApplicationBox:				// ＢＯＸ.
				e_DefaultApplication = PNLE_DefaultApplicationBox;
				break;
			case TYPE_DefaultApplicationImageDealer:		// イメージディーラー.
				e_DefaultApplication = PNLE_DefaultApplicationImageDealer;
				break;
			case TYPE_DefaultApplicationMyPanel:			// マイパネル.
				e_DefaultApplication = PNLE_DefaultApplicationMyPanel;
				break;
			case TYPE_DefaultApplicationBrowser:			// ブラウザ.
				e_DefaultApplication = PNLE_DefaultApplicationBrowser;
				break;
			case TYPE_DefaultApplicationApplicationMenu:	// アプリケーションメニュー.
				e_DefaultApplication = PNLE_DefaultApplicationApplicationMenu;
				break;
			case TYPE_DefaultApplicationTopMenu:			// 標準トップメニュー/ユーザー別トップメニュー(Huron).
				e_DefaultApplication = PNLE_DefaultApplicationTopMenu;
				break;
			default:
				break;
		}
	}
	else {
// comment 2022/05/16 Sky中野 [IT6_2.3] 制御No.43_システムオートリセット改善(システムオートリセット対応).
//		e_DefaultApplication = PNLC_WebUIControl::getInstance()->getDefaultApp();
		PNLE_DefaultApplicationSource e_Source = PnlComGetDefaultApplicationSource();
		switch( e_Source ) {
			case PNLE_DefaultApplicationSource_Personalize:		// パーソナライズアプリ.
				e_DefaultApplication = PNLC_WebUIControl::getInstance()->getDefaultApp();
				break;
			case PNLE_DefaultApplicationSource_Admin:			// 管理者設定.
				{
					// 優先機能を取得.
					TYPE_BasicDefaultApplication e_BasicDefaultApp = TYPE_BasicDefaultApplication_HomeMenu;
					if( NULL != cp_OperationSetting ) {
						e_BasicDefaultApp = cp_OperationSetting->getBasicDefaultApplication();
					}
					// PNLE_DefaultApplicationへ変換.
					switch( e_BasicDefaultApp ) {
						case TYPE_BasicDefaultApplication_HomeMenu:			// Home画面.
							e_DefaultApplication = PNLE_DefaultApplicationWebUIHome;
							break;
						case TYPE_BasicDefaultApplication_Copy:				// コピー.
							e_DefaultApplication = PNLE_DefaultApplicationWebUICopy;
							break;
						case TYPE_BasicDefaultApplication_SimpleCopy:		// シンプルコピー.
							e_DefaultApplication = PNLE_DefaultApplicationCopyCardType;
							break;
						case TYPE_BasicDefaultApplication_ScanMailSend:		// スキャン(メール送信).
							e_DefaultApplication = PNLE_DefaultApplicationScanToEmail;
							break;
						case TYPE_BasicDefaultApplication_ScanBoxSave:		// スキャン(ボックス保存).
							e_DefaultApplication = PNLE_DefaultApplicationScanToBox;
							break;
						case TYPE_BasicDefaultApplication_ScanPCSend:		// スキャン(PCへ送信).
							e_DefaultApplication = PNLE_DefaultApplicationScanToPC;
							break;
						case TYPE_BasicDefaultApplication_Fax:				// ファクス.
							e_DefaultApplication = PNLE_DefaultApplicationWebUIFax;
							break;
						case TYPE_BasicDefaultApplication_InternetFax:		// インターネットファクス.
							e_DefaultApplication = PNLE_DefaultApplicationIFax;
							break;
						case TYPE_BasicDefaultApplication_IPAddressFax:		// IPアドレスファクス.
							e_DefaultApplication = PNLE_DefaultApplicationIPAddressFax;
							break;
						case TYPE_BasicDefaultApplication_IPFax:			// IPファクス(SIP).
							e_DefaultApplication = PNLE_DefaultApplicationIpFaxT38;
							break;
						default:											// その他(ありえない).
							ExpPanelLog( PNLD_ExpLogKind_AlwaysLogOut, "[PnlComGetDefaultApplication] BasicDefaultApplication : %d", e_BasicDefaultApp ,0, 0 , 0, 0, 0 );
							e_DefaultApplication = PNLE_DefaultApplicationWebUIHome;
							break;
					}
				}
				break;
			default:											// 不明.
				e_DefaultApplication = PNLE_DefaultApplicationNone;
				break;
		}
	}
	return e_DefaultApplication;
}
// comment [特ROM対応][IT5-26] エラー発生時のジョブの削除方法を自動又は手動に設定可能とする対応.
//概要　　：ジョブ自動削除対象警告が発生しているかどうかを判定する.
//戻り値　：Bool  True：対象警告が発生している  False：対象警告が発生していない.
//作成者　：SKY_新大阪.
Bool PnlComIsJudgeAutoDeleteWarning( APIC_Job* pJob )
{
	// パラメータチェック( ここではAssertはしないでおく ).
	if( pJob == NULL ){
		return False;
	}

	// 以下のどれかが発生していればTrueを返す.
	if( True == onlyPanel.isWarningOn( pJob, PERROR_PaperEmpty )					// ペーパーエンプティ(プリント開始後).
//	 || True == onlyPanel.isWarningOn( pJob, PCAUTION_PaperEmpty )					// ペーパーエンプティ(読み込み時) → Scanで検出.		→Jobで対象外にされているため、削除.
	 || True == onlyPanel.isWarningOn( pJob, PERROR_PrintPaperError )				// プリント用紙不適合.
	 || True == onlyPanel.isWarningOn( pJob, PERROR_CrossSortPaperSizeError )		// 回転ソート用紙サイズ不適合(スタートキー押下時).
	 || True == onlyPanel.isWarningOn( pJob, PERROR_FuserRetractedTypeError )		// 定着手動離間中用紙不適合(ジョブ実行時).
	 || True == onlyPanel.isWarningOn( pJob, PERROR_OffsetPaperSizeError )			// オフセット用紙サイズ不適合(プリント開始後).
	 || True == onlyPanel.isWarningOn( pJob, PERROR_APSNoPaperSize )				// ＡＰＳサイズ不適合(ERROR1)(スタート時).				→対象として入れるが、現在は「ERROR_PrintPaperError」で検出されるため、発生しない.
	 || True == onlyPanel.isWarningOn( pJob, PERROR_ManualTrayMissSet )				// 手差しトレイセット不良(動作中).
	 || True == onlyPanel.isWarningOn( pJob, PATTENTION_CTonerEmptyStop )			// シアン色トナーエンプティストップ.
	 || True == onlyPanel.isWarningOn( pJob, PATTENTION_MTonerEmptyStop )			// マゼンタ色トナーエンプティストップ.
	 || True == onlyPanel.isWarningOn( pJob, PATTENTION_YTonerEmptyStop )			// イエロー色トナーエンプティストップ.
	 || True == onlyPanel.isWarningOn( pJob, PATTENTION_KTonerEmptyStop )			// ブラック色トナーエンプティストップ.
	 || True == onlyPanel.isWarningOn( pJob, PERROR_PrinterJam ) 					// プリンタジャム検出.
	 || True == onlyPanel.isWarningOn( pJob, PERROR_CTonerEmptyStop )				// シアン色トナーエンプティストップ.
	 || True == onlyPanel.isWarningOn( pJob, PERROR_MTonerEmptyStop )				// マゼンタ色トナーエンプティストップ.
	 || True == onlyPanel.isWarningOn( pJob, PERROR_YTonerEmptyStop )				// イエロー色トナーエンプティストップ.
	 || True == onlyPanel.isWarningOn( pJob, PERROR_KTonerEmptyStop )				// ブラック色トナーエンプティストップ.
	 || True == onlyPanel.isWarningOn( pJob, PERROR_PaperSizeChanged )				// 用紙サイズ不一致.
	 || True == onlyPanel.isWarningOn( pJob, PERROR_PaperKindChanged )				// 用紙種類不一致.
//Comment 2020/02/21 HCL_Monisha [IT6_2.0MR2] [制御構成変更_No.38] When Paper Warning Displayed,Job is stopped<Start>.
//	 || True == onlyPanel.isWarningOn( pJob, PERROR_LetterheadSmallSizeDisable ) ){	// レターヘッド紙小サイズ禁止警告.
	 || True == onlyPanel.isWarningOn( pJob, PERROR_LetterheadSmallSizeDisable ) 
	 || True == onlyPanel.isWarningOn( pJob, PERROR_LetterHeadPaperJobError_S )
	 || True == onlyPanel.isWarningOn( pJob, PERROR_LetterHeadPaperJobError )
	 || True == onlyPanel.isWarningOn( pJob, PERROR_ThinPaperJobError_S )
	 || True == onlyPanel.isWarningOn( pJob, PERROR_ThinPaperJobError ) ){	// レターヘッド紙小サイズ禁止警告.

	// 以下は、Panel上で全警告画面の表示処理がない
//	 || e_PrinterWarning == ERROR_PaperSizeChangedManual		// 手差しサイズエラー警告.		// Print上で、ERROR_PaperSizeChangedと or条件で検出.
//	 || e_PrinterWarning == ERROR_PaperSizeChangedForceStop		// 強制停止サイズエラー警告.	// Print上で、ERROR_PaperSizeChangedとして条件チェック.

		return True;
	} else {
		return False;
	}
}

//概要　　：ジョブ自動削除設定で、ログイン時削除設定がされているものがあるかどうかを判定する.
//戻り値　：Bool  True：ログイン時設定されているものがある  False：ログイン時設定されているものがない.
//作成者　：SKY_新大阪.
Bool PnlComIsJudgeAutoDelete_OnLoginSetting()
{
	// DipSwNo231 Bit 0がOffのときは、Falseをかえす.
	APIC_SoftDipSw* pc_SoftDipSw = APIC_SoftDipSw::newInstance();
	if( pc_SoftDipSw == NULL
	 || False == pc_SoftDipSw->getSoftDipSwBitForPanelSpecNo( DEFSOFTWARESW231, 0 ) ){
		return False;
	}

	// 自動削除モード設定の取得.
	TYPS_JobAutoDeleteWhenErrorOccurs s_DeleteMode;
	memset( &s_DeleteMode, 0x00, sizeof( TYPS_JobAutoDeleteWhenErrorOccurs ) );
	PnlComGetSystemSetting()->getJobAutoDeleteWhenErrorOccurs( &s_DeleteMode );

	// 削除モード設定がOff（使用しない）の場合はFalseを返す.
	if( s_DeleteMode.bl_IsOn == False ){
		return False;
	}

	// Mode4以外のとき.
	if( s_DeleteMode.e_JobAutoDeleteMode != TYPE_JobAutoDeleteMode_4 ){
		// Mode4以外はFalseを返す.
		return False;

// Mode4のとき.
	} else {
		// ログイン時設定確認.
		if( s_DeleteMode.e_PaperJam              == TYPE_JobAutoDeleteDetails_OnLogin
		 || s_DeleteMode.e_PaperEmpty            == TYPE_JobAutoDeleteDetails_OnLogin
		 || s_DeleteMode.e_ConsumableReplacement == TYPE_JobAutoDeleteDetails_OnLogin
		 || s_DeleteMode.e_PaperSizeMismatch     == TYPE_JobAutoDeleteDetails_OnLogin ){
			return True;
		}
	}

	return False;
}

//概要　　：ジョブ自動削除設定で、ペーパージャムがログイン時削除設定がされているかを判定する.
//戻り値　：Bool  True：ペーパージャムがログイン時設定されている  False：ログイン時設定されていない.
//作成者　：SKY_新大阪.
Bool PnlComIsJudgeAutoDelete_OnLoginSetting_PaperJam()
{
	// DipSwNo231 Bit 0がOffのときは、Falseをかえす.
	APIC_SoftDipSw* pc_SoftDipSw = APIC_SoftDipSw::newInstance();
	if( pc_SoftDipSw == NULL
	 || False == pc_SoftDipSw->getSoftDipSwBitForPanelSpecNo( DEFSOFTWARESW231, 0 ) ){
		return False;
	}

	// 自動削除モード設定の取得.
	TYPS_JobAutoDeleteWhenErrorOccurs s_DeleteMode;
	memset( &s_DeleteMode, 0x00, sizeof( TYPS_JobAutoDeleteWhenErrorOccurs ) );
	PnlComGetSystemSetting()->getJobAutoDeleteWhenErrorOccurs( &s_DeleteMode );

	// 削除モード設定がOff（使用しない）の場合はFalseを返す.
	if( s_DeleteMode.bl_IsOn == False ){
		return False;
	}

	// PaperJamの設定判定.
	if( s_DeleteMode.e_JobAutoDeleteMode == TYPE_JobAutoDeleteMode_4
	 && s_DeleteMode.e_PaperJam          == TYPE_JobAutoDeleteDetails_OnLogin ){
		return True;
	}

	return False;
}

