// Comment [2017/07/05] [HCLT_Prasanjeet] [AR1023442] Function to check whether the functionality is restricted for User.
Bool isModeRestrict() {
	Bool bl_ret=False;
	TYPE_JobType e_JobType = comPanelJob->getJobSpec()->pc_Common->c_JobType.getJobType();
	if( onlyPanel.b_nowBoxMode == True ) {													// Box Mode.
    	if(False ==s_AryApplicationUseStatusTable_CLCD[PCGE_ModeBoxOperation].b_Enable){
       		 bl_ret =True;
    	}
	} else if( onlyPanel.getBrowserMode() == True || onlyPanel.b_goBrowserMode == True ) {	// Browser Mode.
    	if(False ==s_AryApplicationUseStatusTable_CLCD[PCGE_ModeBrowser].b_Enable){
       		bl_ret =True;
    	}
	} else if( True == comPanelJob->getJobSpec()->pc_Send->c_Twain.getScanToAndroid() ) {	// Scan Mode.
    	if(False ==s_AryApplicationUseStatusTable_CLCD[PCGE_ModeScanFax].b_Enable){
       		bl_ret =True;
    	}
	} else if( ( TYPE_JobTypeCopy == e_JobType ) || ( TYPE_JobTypeIntCopy == e_JobType )) {	// Copy.
		if(False ==s_AryApplicationUseStatusTable_CLCD[PCGE_ModeCopy].b_Enable){
         	 bl_ret =True;
        }
	} else if( True == comPanelJob->getFaxAppFlag()) {										// Fax Mode.
		if(False ==s_AryApplicationUseStatusTable_CLCD[PCGE_ModeFaxOnly].b_Enable){
       		bl_ret =True;
    	}
	}else {																					// Scan / Fax.
		if(False ==s_AryApplicationUseStatusTable_CLCD[PCGE_ModeScanFax].b_Enable){
			bl_ret =True;
		}
    }
 	return bl_ret;
}
