// Comment KronosS <- 2016/08/19 SCD2 3G Sky瀬戸 機能バッジループ処理ON/OFF対応.
// Comment <- 2017/07/14 [IT5_4.2][管理No.31][RQ-655] 機能キーループ7インチ共通化 2SCD3G Sky瀬戸.
// [IT5_4.2][制御構成変更_No.34] トレイオープン時の警告表示改善 SCD2 3G Sky西場 2017/08/29 start.
#ifdef DEF_KRONOSS_Cus
//================================================================================================.
// 概要		：印刷実行中のジョブが存在するかの判定.
//================================================================================================.
Bool PnlComIsExistActivePrintJob()
{
	APIC_ActiveJobList* cp_ActiveJobList = APIC_ActiveJobList::newInstance();
	LIBC_List<APIC_Job> c_Joblist;
	APIC_Job* cp_Job = NULL;
	Bool exist = False;

	if( cp_ActiveJobList == NULL ) {
		return False;
	}
// Comment 2017/11/22【HCLT-Tanu】【IT5 4.2】【RQ686】API Correction.
//	short JobListNum = cp_ActiveJobList->getListPanel(TYPE_ActiveJobListPrint, 1, TYPD_MaxActiveJob, &c_Joblist);
	short JobListNum = cp_ActiveJobList->getListPanel(TYPE_ActiveJobListPrint, 1, TYPD_MaxActiveJob, &c_Joblist,PNLC_NetworkLan::getInstance()->getLine());
	cp_Job = c_Joblist.findFirst();
	while( cp_Job != NULL ) {
		TYPC_JobStatus* c_JobStatus = cp_Job->getJobStatus();
		if( c_JobStatus != NULL ) {
			if( c_JobStatus->getOutputStatus() == TYPE_OutputStatusPrintExec ) {
				exist = True;
				break;
			}
		}
		cp_Job = c_Joblist.findNext();
	}
	c_Joblist.delAll();

	return exist;
}
#endif	// #ifdef DEF_KRONOSS_Cus.
