// comment [特ROM対応][IT5-80] 拡張サーバ認証時にユーザのActiveDirectoryアカウントでHomeDirectoryにSMB送信を行う対応.
//概要    : ScanToHomeをADアカウントのホームディレクトリで送信する機能が有効かどうか？.
//戻り値  : Bool  True:有効 False：無効.
Bool PnlComIsSendScanToHomeInADHomeDir()
{
	// DipSwがOff.
	if( ( True != APIC_SoftDipSw::newInstance()->getSoftDipSwBitForPanelSpecNo( DEFSOFTWARESW236, 0 ) ) ){	// DipSwNo236 Bit0がOn.
		return False;
	}

	// ScanToHome有効設定が有効でなければ無効.
// Comment 2017/11/22【HCLT-Tanu】【IT5 4.2】【RQ686】API Correction.	
//	if( ( False == PnlComGetUserAuthentication()->getEnableHomeAddress() ) ){
	if( ( False == PnlComGetUserAuthentication()->getEnableHomeAddress(PNLC_NetworkLan::getInstance()->getLine()) ) ){
		return False;
	}

	// ユーザー認証設定がOff、又は本体認証のみのときは無効.
// Comment 2017/11/22【HCLT-Tanu】【IT5 4.2】【RQ686】API Correction.	
//	if( ( TYPE_UserAuthenticationDevice == PnlComGetUserAuthentication()->getUserAuthentication() ) 		// ユーザー認証タイプが本体認証.
//	 || ( TYPE_UserAuthenticationOff    == PnlComGetUserAuthentication()->getUserAuthentication() ) ){		// ユーザー認証タイプがOff.
	if( ( TYPE_UserAuthenticationDevice == PnlComGetUserAuthentication()->getUserAuthentication(PNLC_NetworkLan::getInstance()->getLine()) ) 		// ユーザー認証タイプが本体認証.
	 || ( TYPE_UserAuthenticationOff    == PnlComGetUserAuthentication()->getUserAuthentication(PNLC_NetworkLan::getInstance()->getLine()) ) ){		// ユーザー認証タイプがOff.
		return False;
	}

	// ユーザーログインしていない.
	if( ( NULL == PnlComGetUser() ) ){
		return False;
	}

	// 一般ユーザー以外がログインしているとき.
	if( ( TYPE_UserTypeUser != PnlComGetUser()->getUserType() ) ){
		return False;
	}

	// SMB送信が有効か.
	TYPC_ComSend* pc_ComSend = NULL;
	if( ( NULL != PnlComGetJobScanFax() )
	 && ( NULL != PnlComGetJobScanFax()->getJobSpec() )
	 && ( NULL != PnlComGetJobScanFax()->getJobSpec()->pc_Send ) ){
		pc_ComSend = &( PnlComGetJobScanFax()->getJobSpec()->pc_Send->c_ComSend );
	}else{
//Comment 2019/06/14 [HCLT_Monisha][EagleH][N Rank] Removed unwanted Detailed code.
//		LOGF_debug_PutEventLog(LOGF_DEBUG_EVENT_KIND_ALL, 0, 3, "Assert Failed!");
		LOGF_debug_PutEventLog(LOGF_DEBUG_EVENT_KIND_ALL, 0, LOGD_DEBUG_LEVEL_UNKNOWN, "Assert Failed!");
		return False;
	}
	if( ( NULL  != pc_ComSend )
	 && ( False == isEnableSetAddress( pc_ComSend, TYPE_SendModeSmb, False, False, False, True, -1, NULL, True ) ) ){
		return False;
	}

	// HomeDirectory情報が取得できるとき.
	uchar uc_HomeDir[ TYPD_HomeDirMaxString + 1 ] = {};
	PnlComGetUser()->getHomeDir( uc_HomeDir );
	if( ( 0x00 != uc_HomeDir[0] ) ){
		return False;
	}

	// LDAP設定から、ADドメインの設定を取ってくる → 未設定の場合は無効.
	APIC_LdapSetting* pc_LdapSetting = APIC_LdapSetting::newInstance( 4 );
	if( ( NULL != pc_LdapSetting ) ){
		char sc_UserDomain[TYPD_LDAPServerReferBase + 1] = {};
		pc_LdapSetting->getSearchCharUTF8( &sc_UserDomain[0] , TYPE_CharSetUTF8 );				// LDAPサーバー設定(4番目) -> 検索ベース取得.
		if( ( 0 == strlen( sc_UserDomain ) ) ){
			return False;
		}
	}else{
//Comment 2019/06/14 [HCLT_Monisha][EagleH][N Rank] Removed unwanted Detailed code.
//		LOGF_debug_PutEventLog(LOGF_DEBUG_EVENT_KIND_ALL, 0, 3, "Assert Failed!");
		LOGF_debug_PutEventLog(LOGF_DEBUG_EVENT_KIND_ALL, 0, LOGD_DEBUG_LEVEL_UNKNOWN, "Assert Failed!");
		return False;
	}

	// 上記条件をすり抜けたら、機能有効.
	return True;
}

