// comment 2018/01/09 [HCL_Ramasamy][IT5_4.2] [AR1033802] Abnormal warning Next, Prev and OK key not display while transition Issue Fix.
ushort PnlComGetAbnormalFeedTray()
{
	return us_AbnormalFeedTraystate;
}

void PnlComSetAbnormalFeedTray()
{
	APIC_PrinterStatus* pc_PrinterStatus = APIC_PrinterStatus::newInstance();		// Get Printer status.
	if( NULL == pc_PrinterStatus ) {
//Comment 2019/06/14 [HCLT_Monisha][EagleH][N Rank] Removed unwanted Detailed code.
//		LOGF_debug_PutEventLog(LOGF_DEBUG_EVENT_KIND_ALL, 0, 3, "Assert Failed!");
		LOGF_debug_PutEventLog(LOGF_DEBUG_EVENT_KIND_ALL, 0, LOGD_DEBUG_LEVEL_UNKNOWN, "Assert Failed!");
		return;
	}
	us_AbnormalFeedTraystate = pc_PrinterStatus->getAbnormalSetFeedTray();
}

