// comment 2022/05/13 FPT.DungDV14 [IT6_2.3] [RQ-815] Convert commonAPI to Panel define.
PNLE_FromAddressChange PnlGetFromAddressChange( TYPE_NetworkSpecific e_NetworkSpecific )
{
	PNLE_FromAddressChange 	e_ret = PNLE_FromChangeAll;
	TYPE_FromAddressChange 	e_FromAddressChange;
	TYPE_FromChange 		e_FromChange;

	// getFuncVer2の結果が、TYPE_FuncVer_Expansion4以降の場合
	if(True == PLBC_FuncVersionCheck::isOK_IT6_Type4() ) {
		e_FromAddressChange = PnlComGetMailSendSetting()->getFromAddressChange( e_NetworkSpecific );
		switch( e_FromAddressChange ) {
			case TYPE_FromAddressChange_AllowUserToChange:
				e_ret = PNLE_FromChange_Able;
				break;
			case TYPE_FromAddressChange_FixedAdminAddress:
				e_ret = PNLE_FromChange_Disable_AdminAdress;
				break;
			case TYPE_FromAddressChange_UserAddressPriority:
				e_ret = PNLE_FromChange_Disable_UserAdress;
				break;
			case TYPE_FromAddressChange_Specify:
				e_ret = PNLE_FromChange_Specify;
				break;
			default:
				break;
		}
	} else {
		e_FromChange = PnlComGetScanJobSetting()->getFromChange( e_NetworkSpecific );
		switch( e_FromChange ) {
			case TYPE_FromChange_Able:
				e_ret = PNLE_FromChange_Able;
				break;
			case TYPE_FromChange_Disable_AdminAdress:
				e_ret = PNLE_FromChange_Disable_AdminAdress;
				break;
			case TYPE_FromChange_Disable_UserAdress:
				e_ret = PNLE_FromChange_Disable_UserAdress;
				break;
			default:
				break;
		}
	}
	return e_ret;
}
